    "explanation": "**[핵심 개념]**\n순열(Permutation)은 서로 다른 n개의 원소 중에서 r개를 순서를 고려하여 선택하는 경우의 수이다. 특히 n개의 서로 다른 원소를 모두 일렬로 나열하는 경우의 수는 n!(n팩토리얼)으로 계산된다.\n\n$$P(n,n) = n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 2 \\times 1$$\n\n**[풀이]**\n\n**Step 1: 문제 상황 파악**\n- 서로 다른 5개의 공을 일렬로 나열하는 것이므로, 5개의 원소를 모두 사용하는 순열이다.\n\n**Step 2: 위치별로 선택 가능한 경우의 수 계산**\n- 첫 번째 자리: 5개의 공 중 아무거나 선택 → 5가지\n- 두 번째 자리: 남은 4개의 공 중 선택 → 4가지\n- 세 번째 자리: 남은 3개의 공 중 선택 → 3가지\n- 네 번째 자리: 남은 2개의 공 중 선택 → 2가지\n- 다섯 번째 자리: 남은 1개의 공 → 1가지\n\n**Step 3: 전체 경우의 수 계산**\n$$5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$$\n\n**[정답 확인]**\n서로 다른 5개의 공을 모두 사용하여 일렬로 나열하는 경우의 수는 $5! = 120$이므로 정답이다.\n\n**[오답 분석]**\n(객관식 선지가 없으므로 생략)\n\n**[핵심 포인트]**\n- **\"서로 다른\" + \"일렬로 나열\"** → 무조건 $n!$ (팩토리얼) 공식 적용\n- 순열의 기본 원리: 각 위치에서 선택 가능한 원소의 개수가 1씩 감소하므로 곱하기로 계산",
