    "explanation": "**[핵심 개념]**\n조건부 순열 문제이다. \"여학생 2명이 이웃하도록\"이라는 조건이 있으므로, 여학생 2명을 하나의 단위로 묶어서 생각한다. 이를 '묶음 전략' 또는 '블록 만들기'라고 부르며, 조건이 있는 순열 문제의 기본 해법이다.\n\n**[풀이]**\n\n**Step 1: 여학생 2명을 하나의 블록으로 묶기**\n\n여학생 2명(여1, 여2)이 반드시 이웃하려면, 이들을 하나의 단위로 취급한다.\n- 여학생 블록: (여1, 여2)\n- 남학생 3명: 남1, 남2, 남3\n\n이제 \"여학생 블록\" 1개 + \"남학생\" 3명 = 총 4개의 단위를 배열하는 것과 같다.\n\n**Step 2: 4개 단위의 배열 수**\n\n4개 단위를 일렬로 배열하는 경우의 수:\n$$4! = 4 \\times 3 \\times 2 \\times 1 = 24$$\n\n**Step 3: 여학생 블록 내부의 배열 수**\n\n여학생 블록 내에서 여학생 2명이 서로 다르므로, 블록 내부에서도 순서가 있다.\n여학생 2명의 배열 수:\n$$2! = 2 \\times 1 = 2$$\n\n**Step 4: 전체 경우의 수**\n\n곱의 법칙을 적용하면:\n$$4! \\times 2! = 24 \\times 2 = 48$$\n\n따라서 답은 **48**이다.\n\n**[정답 확인]**\n여학생 2명을 블록으로 묶어 4개 단위를 배열(24가지)하고, 블록 내부에서 여학생 2명을 배열(2가지)하면 $24 \\times 2 = 48$가지가 된다.\n\n**[오답 분석]**\n- **① 24**: 여학생 블록 내부의 배열을 고려하지 않음 ($4!$만 계산)\n- **② 36**: 일반적인 계산 오류로, 부분적인 경우만 센 것\n- **④ 60**: $5! \\times 2 = 240$을 실수하거나 잘못된 공식 적용\n- **⑤ 72**: 중복 계산이나 추가 조건을 잘못 반영한 결과\n\n**[핵심 포인트]**\n조건이 있는 순열은 **묶음 전략**을 사용한다. 조건을 만족하는 대상들을 하나의 블록으로 묶은 후, 블록 내부의 배열도 잊지 말고 고려해야 한다.",
