    "explanation": "**[핵심 개념]**\n조건부 순열 문제로, 특정 조건을 만족하는 배열의 개수를 구하는 문제이다. \n- 먼저 조건을 만족하는 단위를 하나의 묶음으로 취급하여 순열을 계산\n- 묶음 내부의 순열도 함께 고려해야 함\n\n**[풀이]**\n\n**Step 1: A와 B 사이에 정확히 2명이 서는 상황 파악**\n\nA와 B 사이에 정확히 2명이 선다는 것은 A_○_○_B 또는 B_○_○_A 형태를 의미한다.\n(○는 다른 사람)\n\n**Step 2: A, B와 그 사이의 2명을 하나의 블록으로 생각**\n\nA와 B 사이의 2명을 선택하고 배열하는 방법:\n- 남은 5명 중에서 2명을 선택: $\\binom{5}{2} = 10$\n- 선택한 2명을 A와 B 사이에 배열: $2! = 2$\n- A와 B의 순서 (A가 먼저 올지, B가 먼저 올지): $2$\n\n따라서 블록 내부 경우의 수: $10 \\times 2 \\times 2 = 40$\n\n**Step 3: 블록과 나머지 사람들을 배열**\n\n- A, B와 그 사이의 2명으로 이루어진 블록: 1개\n- 선택되지 않은 남은 사람: $5 - 2 = 3$명\n- 총 배열할 단위: $1 + 3 = 4$개\n\n이 4개 단위를 일렬로 배열: $4! = 24$\n\n**Step 4: 전체 경우의 수 계산**\n\n$$\\text{전체 경우의 수} = 40 \\times 24 = 960$$\n\n**[정답 확인]**\nA와 B 사이의 2명을 선택하고 배치하는 방법(40)과 블록을 포함한 4개 단위를 배열하는 방법(24)을 곱하면 960이 되므로 정답이다.\n\n**[오답 분석]**\n- ① 480: 블록 내부 계산에서 A, B의 순서를 빠뜨린 경우 ($20 \\times 24$)\n- ② 720: 블록 내부에서 2명 선택만 고려하고 배열을 빠뜨린 경우 ($30 \\times 24$)\n- ④ 1200: 계산 과정에서 실수하여 $50 \\times 24$ 등으로 계산한 경우\n- ⑤ 1440: 남은 사람을 3명이 아닌 4명으로 잘못 계산하여 $40 \\times 36$ 등으로 계산한 경우\n\n**[핵심 포인트]**\n- 조건을 만족하는 대상을 블록화할 때, 블록 내부의 모든 배열 경우의 수(선택, 순서, 순서쌍)를 빠짐없이 계산해야 한다.\n- A와 B의 순서(누가 먼저 올지)를 반드시 고려하는 것이 중요하다.",
