    "type": "순열",
    "problem": "1, 2, 3, 4, 5, 6, 7의 숫자를 모두 사용하여 일곱 자리 수를 만든다. 홀수는 홀수 번째 자리에만, 짝수는 짝수 번째 자리에만 오도록 배열하는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 144,
    "explanation": "**[핵심 개념]**\n이 문제는 순열 문제로서, 주어진 조건에 따라 숫자들을 분류한 후 각각 배치하는 경우의 수를 구하는 문제이다. \n- 홀수: 1, 3, 5, 7 (4개)\n- 짝수: 2, 4, 6 (3개)\n- 일곱 자리 수에서 홀수 자리: 1, 3, 5, 7번째 (4개)\n- 일곱 자리 수에서 짝수 자리: 2, 4, 6번째 (3개)\n\n조건: 홀수는 홀수 자리에만, 짝수는 짝수 자리에만 배치\n\n**[풀이]**\n\n**1단계: 자리 분석**\n일곱 자리 수 $\\square^1 \\square^2 \\square^3 \\square^4 \\square^5 \\square^6 \\square^7$에서\n- 홀수 자리(1, 3, 5, 7번째): 4개\n- 짝수 자리(2, 4, 6번째): 3개\n\n**2단계: 숫자 분류**\n- 홀수: 1, 3, 5, 7 (정확히 4개)\n- 짝수: 2, 4, 6 (정확히 3개)\n\n**3단계: 조건 확인**\n홀수 4개를 홀수 자리 4개에 배치하고, 짝수 3개를 짝수 자리 3개에 배치해야 한다. 이는 완벽하게 일치한다.\n\n**4단계: 경우의 수 계산**\n\n홀수 4개를 홀수 자리 4개에 배치하는 경우의 수:\n$$4! = 4 \\times 3 \\times 2 \\times 1 = 24$$\n\n짝수 3개를 짝수 자리 3개에 배치하는 경우의 수:\n$$3! = 3 \\times 2 \\times 1 = 6$$\n\n**5단계: 전체 경우의 수**\n곱의 법칙에 의해:\n$$4! \\times 3! = 24 \\times 6 = 144$$\n\n**[정답 확인]**\n홀수와 짝수의 개수가 각각 홀수 자리와 짝수 자리의 개수와 정확히 일치하므로, 각 그룹 내에서의 배열을 모두 곱하면 $24 \\times 6 = 144$이다.\n\n**[오답 분석]**\n객관식이 제시되지 않았으나, 흔한 오답들:\n- $7! = 5040$: 조건을 무시하고 전체 경우의 수를 구한 경우\n- $4! + 3! = 30$: 곱의 법칙 대신 덧셈을 사용한 경우\n- $7 \\times 6 \\times 5 \\times 4 = 840$: 순열 공식을 잘못 적용한 경우\n\n**[핵심 포인트]**\n- 조건에 따라 먼저 숫자와 자리를 분류한 후, 각 그룹 내에서의 배열을 독립적으로 계산\n- 홀수(4개)와 홀수 자리(4개), 짝수(3개)와 짝수 자리(3개)의 개수가 정확히 일치하는지 확인하는 것이 중요",
