    "_type": "permutation",
    "type": "순열",
    "problem": "10명이 원형 탁자에 앉는데, 특정 3명 A, B, C가 연속하여 앉되 A가 B의 왼쪽에, B가 C의 왼쪽에 오도록 앉는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 5040,
    "explanation": "**[핵심 개념]**\n\n원형 배열(circular permutation)에서는 회전을 같은 것으로 취급한다. 일반적으로 n명이 원형 탁자에 앉는 경우의 수는 $(n-1)!$이다. 이 문제에서는 특정 조건(A, B, C가 연속하고 순서가 정해짐)이 있으므로, 조건을 만족하는 그룹을 하나의 단위로 취급한 후 나머지 사람들과 함께 배열한다.\n\n**[풀이]**\n\n**Step 1: 특정 조건을 만족하는 그룹 만들기**\n\nA, B, C가 연속하여 앉되, A가 B의 왼쪽에, B가 C의 왼쪽에 오도록 앉아야 한다.\n이는 시계 반대 방향(또는 왼쪽 방향)으로 A → B → C 순서라는 의미이다.\n따라서 A, B, C의 순서는 고정되므로 이들을 하나의 블록으로 생각한다.\n\n**Step 2: 단위 결정**\n\n- A, B, C 블록: 1개\n- 나머지 인원: 10 - 3 = 7명\n\n총 1 + 7 = 8개의 단위를 원형 탁자에 배치하게 된다.\n\n**Step 3: 원형 배열 계산**\n\n8개의 단위를 원형 탁자에 배치하는 경우의 수는:\n$$8개\\ 단위의\\ 원형\\ 배열 = (8-1)! = 7!$$\n\n**Step 4: 블록 내 배치 확인**\n\nA, B, C는 이미 순서가 정해져 있다(A가 B의 왼쪽, B가 C의 왼쪽).\n따라서 블록 내에서 배열하는 방법은 1가지이다.\n\n**Step 5: 최종 계산**\n\n$$경우의\\ 수 = 7! × 1 = 5040$$\n\n$$7! = 7 × 6 × 5 × 4 × 3 × 2 × 1 = 5040$$\n\n**[정답 확인]**\n\nA, B, C를 순서가 정해진 하나의 블록으로 취급하여 나머지 7명과 함께 8개 단위를 원형 배치하면 $(8-1)! = 7! = 5040$이 된다.\n\n**[오답 분석]**\n\n- **8!을 계산한 경우**: A, B, C의 순서를 미리 정했으므로 8개 단위를 일렬로 배치하는 것처럼 계산하면 8! = 40,320이 되어 틀립니다.\n- **10!을 계산한 경우**: 원형 배열임을 무시하고 일렬 배치로 계산한 경우이다.\n- **9!을 계산한 경우**: (9-1)! = 8!로 계산하는 실수로, 단위의 개수를 잘못 센 경우이다.\n- **A, B, C 순서를 고려하여 3!을 곱한 경우**: 이미 순서가 고정되어 있으므로 3!을 곱하면 안 된다.\n\n**[핵심 포인트]**\n\n1. 원형 배열에서 조건이 있는 특정 인물들은 **순서가 정해진 하나의 블록**으로 취급하여 $(n-1)!$을 적용한다.\n2. \"A가 B의 왼쪽에, B가 C의 왼쪽에\"라는 조건은 A, B, C의 상대적 위치가 완전히 고정됨을 의미하므로, 블록 내 배열은 1가지이다.",
