    "_type": "combination",
    "type": "조합",
    "problem": "평면 위에 어느 세 점도 한 직선 위에 있지 않은 8개의 점이 있다. 이 점들 중 2개를 이어 만들 수 있는 선분의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 28,
    "explanation": "**[핵심 개념]**\n조합(Combination)의 기본 개념이다. 8개의 점 중에서 순서를 고려하지 않고 2개를 선택하는 경우의 수를 구하는 문제이다. 조합의 공식은 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이며, 여기서 $n$은 전체 개수, $r$은 선택하는 개수이다.\n\n**[풀이]**\n\n**단계 1: 문제 상황 파악**\n- 8개의 점이 평면 위에 있고, 어느 세 점도 한 직선 위에 있지 않는다.\n- \"어느 세 점도 한 직선 위에 있지 않다\"는 조건은 2개의 점을 이으면 항상 하나의 선분이 만들어짐을 보장한다.\n\n**단계 2: 2개의 점을 선택하기**\n8개의 점 중에서 2개를 선택하는 경우의 수를 구한다.\n- 1번째 점을 선택: 8가지\n- 2번째 점을 선택: 7가지\n- 곱하면: $8 \\times 7 = 56$\n\n**단계 3: 순서 제거**\n선분은 방향이 없으므로 (A-B와 B-A는 같은 선분), 순서를 고려하지 않아야 한다.\n따라서 2로 나누어야 한다:\n\n$$\\frac{8 \\times 7}{2} = \\frac{56}{2} = 28$$\n\n또는 조합 공식을 직접 적용하면:\n\n$$\\binom{8}{2} = \\frac{8!}{2!(8-2)!} = \\frac{8 \\times 7}{2 \\times 1} = 28$$\n\n**[정답 확인]**\n8개의 점 중 2개를 순서 없이 선택하면 28개의 서로 다른 선분이 만들어지며, 세 점이 일직선상에 있지 않다는 조건으로 모든 선분이 유효한다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 가능한 오답은:\n- **56**: 순서를 고려하여 2로 나누지 않은 경우\n- **36**: 계산 실수 ($8 \\times 9 \\div 2$ 등으로 잘못 계산)\n- **64**: 전체 점의 개수를 잘못 이용한 경우\n\n**[핵심 포인트]**\n조합 문제에서는 \"선분을 만든다\" = 두 점을 **선택**하는 것이므로 순서가 없다. 따라서 $\\binom{n}{2} = \\frac{n(n-1)}{2}$ 공식을 적용하면 된다.",
