    "explanation": "**[핵심 개념]**\n조합(Combination)은 순서를 고려하지 않고 주어진 집합에서 원소를 선택하는 경우의 수이다. n개 중에서 r개를 선택하는 조합의 수는 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$로 계산된다. 이 문제는 서로 독립적인 두 사건(남학생 선택, 여학생 선택)이 동시에 일어나므로 곱의 법칙을 적용한다.\n\n**[풀이]**\n\n**1단계: 문제 상황 파악**\n- 남학생 5명 중에서 2명을 선택\n- 여학생 4명 중에서 2명을 선택\n- 이 두 사건은 독립적으로 일어남\n\n**2단계: 남학생 2명 선택하는 경우의 수**\n\n$$\\binom{5}{2} = \\frac{5!}{2!(5-2)!} = \\frac{5!}{2! \\cdot 3!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**3단계: 여학생 2명 선택하는 경우의 수**\n\n$$\\binom{4}{2} = \\frac{4!}{2!(4-2)!} = \\frac{4!}{2! \\cdot 2!} = \\frac{4 \\times 3}{2 \\times 1} = 6$$\n\n**4단계: 곱의 법칙 적용**\n\n남학생 2명을 선택하는 각각의 경우에 대해 여학생 2명을 선택할 수 있으므로:\n\n$$\\text{전체 경우의 수} = \\binom{5}{2} \\times \\binom{4}{2} = 10 \\times 6 = 60$$\n\n**[정답 확인]**\n남학생 선택 경우의 수 10가지와 여학생 선택 경우의 수 6가지를 곱하면 60이므로 정답은 ④번이다.\n\n**[오답 분석]**\n- ① 30: 계산 실수로 $10 \\times 3$ 또는 $5 \\times 6$으로 잘못 계산한 경우\n- ② 40: 여학생 조합을 잘못 계산하거나 부분적으로만 계산한 경우\n- ③ 50: 남학생이나 여학생 조합을 잘못 계산한 경우\n- ⑤ 70: 곱의 법칙을 잘못 적용하거나 추가 계산을 한 경우\n\n**[핵심 포인트]**\n서로 다른 두 그룹에서 각각 선택하는 문제는 각 그룹별 조합을 구한 후 곱의 법칙으로 곱한다. 조합 공식에서 순서를 고려하지 않는다는 점이 중요하다.",
