    "answer": 3,
    "explanation": "**[핵심 개념]**\n삼각형을 만들기 위한 필수 조건은 서로 다른 세 점이 한 직선 위에 있지 않아야 한다는 것이다. 이 문제에서는 \"어느 세 점도 한 직선 위에 있지 않다\"는 조건이 주어졌으므로, 10개의 점 중 임의로 3개를 선택하면 항상 삼각형을 이룹니다. 따라서 조합을 이용하여 계산한다.\n\n**[풀이]**\n\n**1단계: 주어진 조건 분석**\n- 평면 위에 10개의 점이 있음\n- 어느 세 점도 한 직선 위에 있지 않음 (일직선 위의 세 점이 없음)\n- 이 조건이 있으므로 어떤 3개의 점을 선택해도 항상 삼각형을 이룸\n\n**2단계: 삼각형 개수 계산**\n\n10개의 점 중에서 순서를 고려하지 않고 3개를 선택하는 경우의 수를 구한다.\n\n$$C(10, 3) = \\frac{10!}{3!(10-3)!} = \\frac{10!}{3! \\cdot 7!}$$\n\n**3단계: 계산 수행**\n\n$$C(10, 3) = \\frac{10 \\times 9 \\times 8}{3 \\times 2 \\times 1}$$\n\n$$= \\frac{720}{6} = 120$$\n\n**4단계: 결과 해석**\n\n조건 \"어느 세 점도 한 직선 위에 있지 않다\"는 것은 선택한 어떤 3개의 점도 일직선 위에 있지 않다는 의미이므로, 계산된 모든 조합이 삼각형을 이룹니다.\n\n**[정답 확인]**\n일직선상 세 점이 없다는 조건이 있으므로, 10개 점 중 3개를 선택하는 모든 경우가 삼각형을 이루며, $C(10,3) = 120$이다.\n\n**[오답 분석]**\n- **① 45**: $C(10, 2) = 45$로, 점 2개를 선택하는 경우의 수 (선분의 개수)\n- **② 60**: 계산 실수로 인한 오답, 특별한 의미 없음\n- **③ 90**: $C(10, 2) + C(10, 3)$의 일부를 계산한 경우\n- **⑤ 150**: $C(10, 3) + C(10, 2) = 120 + 45 = 165$에 가까운 값으로, 계산 오류\n\n**[핵심 포인트]**\n\"어느 세 점도 한 직선 위에 있지 않다\"는 조건은 삼각형을 만들지 못하는 경우를 배제해주는 역할을 한다. 따라서 단순히 $C(10, 3)$을 계산하면 되며, 조건이 없었다면 일직선상 점들을 제외해야 한다.",
