    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n구별되지 않는 그룹으로 나누는 경우의 수는 단순히 조합을 곱한 후 그룹의 개수만큼의 중복을 제거해야 한다.\n\n- 구별되는 경우: 순열 사용\n- 구별되지 않는 경우: 중복된 분할을 제거하기 위해 같은 크기 그룹의 개수로 나눔\n- 같은 크기의 그룹 $k$개는 $k!$로 나누어야 함\n\n**[풀이]**\n\n**1단계: 순서를 고려하여 나누기**\n\n9명을 첫 번째 조(3명), 두 번째 조(3명), 세 번째 조(3명)로 순서 있게 나누는 경우:\n\n$$C(9,3) \\times C(6,3) \\times C(3,3) = \\frac{9!}{3!6!} \\times \\frac{6!}{3!3!} \\times \\frac{3!}{3!0!}$$\n\n$$= \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} \\times \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} \\times 1$$\n\n$$= 84 \\times 20 \\times 1 = 1680$$\n\n**2단계: 같은 크기 그룹의 중복 제거**\n\n세 조가 구별되지 않으므로(즉, 단순히 세 개의 그룹일 뿐 첫 번째, 두 번째, 세 번째 등의 구분이 없음), 3개 그룹의 순서는 상관없다.\n\n같은 크기 그룹 3개의 중복을 제거하기 위해 $3!$으로 나눔:\n\n$$\\frac{1680}{3!} = \\frac{1680}{6} = 280$$\n\n**[정답 확인]**\n\n9명을 구별되지 않는 3명씩 3개 그룹으로 나누는 경우의 수는 1680을 $3! = 6$으로 나눈 280이 정답이다.\n\n**[오답 분석]**\n\n- **② 560**: $\\frac{1680}{3} = 560$으로, 중복 제거를 완전히 하지 않은 경우\n- **③ 840**: $\\frac{1680}{2} = 840$으로, 중복 제거를 부분적으로만 한 경우\n- **④ 1120**: $\\frac{1680 \\times 2}{3} = 1120$으로, 계산 오류\n- **⑤ 1680**: 그룹을 구별하는 경우의 수로, 중복 제거를 전혀 하지 않은 경우\n\n**[핵심 포인트]**\n\n구별되지 않는 동일 크기 그룹으로 나누는 문제는 반드시 마지막에 **같은 크기 그룹 개수의 팩토리얼로 나누어** 중복을 제거해야 한다. 이것이 순서가 있는 조합과의 차이이다.",
