    "type": "조합",
    "problem": "12명의 선수를 4명, 4명, 4명의 3팀으로 나눈 후, 각 팀에 A, B, C 코트를 배정하는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 34650,
    "explanation": "**[핵심 개념]**\n\n이 문제는 두 가지 과정으로 나뉩니다.\n1. **집합의 분할(partition)**: 구별되는 12명을 구별되지 않는 같은 크기의 3개 그룹으로 나누기\n2. **순열**: 나누어진 3개 팀을 구별되는 A, B, C 코트에 배정하기\n\n집합의 분할에서 같은 크기의 같은 종류 그룹 $k$개로 나눌 때는 중복을 제거하기 위해 $k!$로 나누어야 한다.\n\n**[풀이]**\n\n**Step 1: 12명을 4명씩 3개 그룹으로 나누기**\n\n12명을 순서를 고려하여 4명, 4명, 4명으로 나누는 경우의 수는:\n$$\\binom{12}{4} \\times \\binom{8}{4} \\times \\binom{4}{4} = \\frac{12!}{4! \\times 4! \\times 4!}$$\n\n:\n$$\\binom{12}{4} = \\frac{12 \\times 11 \\times 10 \\times 9}{4 \\times 3 \\times 2 \\times 1} = \\frac{11880}{24} = 495$$\n\n$$\\binom{8}{4} = \\frac{8 \\times 7 \\times 6 \\times 5}{4 \\times 3 \\times 2 \\times 1} = \\frac{1680}{24} = 70$$\n\n$$\\binom{4}{4} = 1$$\n\n따라서: $495 \\times 70 \\times 1 = 34650$\n\n**Step 2: 3개 팀이 구별되지 않는 상태이므로 중복 제거**\n\n3개의 같은 크기 그룹은 순서가 없으므로 $3!$로 나누어야 한다:\n$$\\frac{34650}{3!} = \\frac{34650}{6} = 5775$$\n\n**Step 3: 3개의 팀을 A, B, C 코트에 배정**\n\n3개의 팀을 3개의 구별되는 코트에 배정하는 경우의 수는 $3!$이다:\n$$3! = 6$$\n\n**Step 4: 전체 경우의 수**\n\n$$5775 \\times 6 = 34650$$\n\n**[정답 확인]**\n\n12명을 구별되지 않는 4명씩 3개 팀으로 나눈 후, 이를 구별되는 3개 코트에 배정하는 모든 경우를 계산하면 정확히 34650이 된다.\n\n**[오답 분석]**\n\n- **중복 제거를 안 한 경우**: $495 \\times 70 = 34650$을 구한 후 $3!$로 나누지 않고 바로 코트 배정을 하면 $34650 \\times 6 = 207900$이 되어 오답\n- **코트 배정을 빼먹은 경우**: $5775$만 답하는 경우 (분할만 계산하고 배정 과정 누락)\n- **$3!$를 두 번 곱한 경우**: $\\frac{34650}{6} \\times 6 \\times 6$ 등의 실수\n\n**[핵심 포인트]**\n\n- **구별되지 않는 그룹 분할**: 같은 크기의 같은 종류 그룹 $k$개로 나눌 때는 반드시 $k!$로 나누어 중복을 제거\n- **분할 후 배정**: 분할과 배정은 별개의 과정이며, 분할에서 제거한 중복을 배정에서 다시 고려해야 함",
