    "problem": "집합 $X = \\{1, 2, 3\\}$에서 집합 $Y = \\{1, 2, 3, 4\\}$로의 함수의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 64,
    "explanation": "**[핵심 개념]**\n\n함수의 정의: 집합 $X$에서 집합 $Y$로의 함수 $f: X \\to Y$는 $X$의 각 원소에 $Y$의 원소를 정확히 하나씩 대응시키는 규칙이다.\n\n함수의 개수: 정의역의 각 원소마다 치역에서 대응될 값을 독립적으로 선택할 수 있으므로, $|X| = m$, $|Y| = n$일 때 함수의 개수는 $n^m$개이다.\n\n**[풀이]**\n\n집합 $X = \\{1, 2, 3\\}$에서 집합 $Y = \\{1, 2, 3, 4\\}$로의 함수의 개수를 구한다.\n\n정의역의 원소 개수: $|X| = 3$\n치역의 원소 개수: $|Y| = 4$\n\n함수를 정의하기 위해서는:\n- $1 \\in X$의 상(image)을 정해야 한다: $Y$의 4개 원소 중 1개 선택 → 4가지\n- $2 \\in X$의 상을 정해야 한다: $Y$의 4개 원소 중 1개 선택 → 4가지 \n- $3 \\in X$의 상을 정해야 한다: $Y$의 4개 원소 중 1개 선택 → 4가지\n\n각 원소의 대응은 독립적이므로, 곱의 법칙에 의해:\n\n$$\\text{함수의 개수} = 4 \\times 4 \\times 4 = 4^3 = 64$$\n\n일반적으로: $f: X \\to Y$ (단, $|X| = m$, $|Y| = n$)의 함수 개수는 $n^m$\n\n**[정답 확인]**\n\n정의역의 3개 원소 각각이 치역의 4개 원소 중 하나를 독립적으로 선택하므로 $4^3 = 64$가 정답이다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으나, 흔한 오답은:\n- $3^4 = 81$: 정의역과 치역을 역순으로 계산한 경우\n- $4 + 3 = 7$ 또는 $4 \\times 3 = 12$: 덧셈이나 기본 곱셈으로 잘못 계산한 경우\n- $P(4,3) = 24$: 함수가 아닌 일대일 대응(전단사)의 개수로 착각한 경우\n\n**[핵심 포인트]**\n\n함수 $f: X \\to Y$의 개수는 \"정의역의 각 원소가 치역에서 선택할 수 있는 경우의 수의 곱\"이므로 $|Y|^{|X|}$이다. 정의역의 크기를 지수로, 치역의 크기를 밑으로 계산하세요.",
