    "answer": 3,
    "explanation": "**[핵심 개념]**\n곱의 법칙(multiplicative principle)은 독립적인 사건들이 동시에 일어날 때 사용되는 경우의 수 계산법이다. 사건 A가 $m$가지, 사건 B가 $n$가지로 일어날 수 있을 때, 두 사건이 동시에 일어나는 경우의 수는 $m \\times n$가지이다. 이를 3개 이상의 사건으로 확장하면 $m \\times n \\times p \\times \\cdots$가 된다.\n\n**[풀이]**\n서로 다른 3개의 주사위를 동시에 던지는 상황을 분석한다.\n\n**1단계: 첫 번째 주사위의 경우의 수**\n첫 번째 주사위가 나타낼 수 있는 눈의 수는 1, 2, 3, 4, 5, 6이므로 $6$가지이다.\n\n**2단계: 두 번째 주사위의 경우의 수**\n두 번째 주사위도 독립적으로 던지므로, 역시 1부터 6까지 나올 수 있어 $6$가지이다.\n\n**3단계: 세 번째 주사위의 경우의 수**\n세 번째 주사위도 마찬가지로 $6$가지이다.\n\n**4단계: 곱의 법칙 적용**\n세 주사위가 나타내는 눈의 수는 서로 독립적인 사건이므로, 전체 경우의 수는 다음과 같이 계산된다.\n\n$$\\text{전체 경우의 수} = 6 \\times 6 \\times 6 = 6^3 = 216$$\n\n**[정답 확인]**\n서로 다른 3개의 주사위를 동시에 던질 때, 각 주사위는 6가지 결과를 독립적으로 나타내므로 곱의 법칙에 의해 $6^3 = 216$가지이다.\n\n**[오답 분석]**\n- ① 18: $3 \\times 6 = 18$으로, 주사위 3개 중 1개만 고려한 것\n- ② 36: $6 \\times 6 = 36$으로, 주사위 2개만 던진 경우\n- ③ 108: $6 \\times 6 \\times 3 = 108$으로, 세 번째 주사위의 경우의 수를 잘못 계산한 것\n- ⑤ 720: $6! = 720$으로, 순열 개념을 잘못 적용한 것\n\n**[핵심 포인트]**\n- 독립적인 사건이 동시에 일어날 때는 **곱의 법칙**을 적용한다.\n- \"동시에 던진다\"는 것은 각 주사위의 결과가 서로 영향을 주지 않으므로, 각각의 경우의 수를 모두 곱해야 한다.",
