    "answer": 1,
    "explanation": "**[핵심 개념]**\n이 문제는 중복조합 문제이다. 같은 종류의 물건 n개를 k명에게 나누어 주되, 받지 못하는 사람이 있을 수 있을 때의 경우의 수는 중복조합 $H(k, n) = C(n+k-1, k-1)$로 구한다. 이는 \"중복을 허용하는 조합\"으로, 음이 아닌 정수해의 개수를 구하는 문제와 동일한다.\n\n**[풀이]**\n\n같은 사탕 8개를 3명의 학생에게 나누어 주는 경우의 수를 구하는 문제이다.\n\n학생 A, B, C가 받는 사탕의 개수를 각각 $x, y, z$라 하면:\n$$x + y + z = 8, \\quad x \\geq 0, y \\geq 0, z \\geq 0$$\n\n이 방정식의 음이 아닌 정수해의 개수를 구하면 된다.\n\n중복조합 공식을 적용하면:\n$$H(3, 8) = C(8+3-1, 3-1) = C(10, 2)$$\n\n계산하면:\n$$C(10, 2) = \\frac{10!}{2! \\cdot 8!} = \\frac{10 \\times 9}{2 \\times 1} = \\frac{90}{2} = 45$$\n\n**[정답 확인]**\n같은 물건 8개를 서로 다른 3명에게 나누어 주는 중복조합은 $C(10, 2) = 45$로, 정답은 ②번이다.\n\n**[오답 분석]**\n- ① 36: $C(9, 2) = 36$으로, $n+k-1$을 잘못 계산하여 9를 사용한 경우\n- ③ 55: $C(11, 2) = 55$로, 분자와 분모를 혼동하거나 조합 공식을 잘못 적용한 경우\n- ④ 66: 조합 계산 과정에서 실수한 경우\n- ⑤ 78: 순열로 잘못 계산하거나 다른 공식을 적용한 경우\n\n**[핵심 포인트]**\n\"같은 종류의 n개를 k명에게 나누어 주는 경우의 수\" = $C(n+k-1, k-1)$ 공식을 정확히 기억하고, 이는 $x_1 + x_2 + \\cdots + x_k = n$의 음이 아닌 정수해의 개수와 동일하다는 점이다.",
