    "answer": 1,
    "explanation": "**[핵심 개념]**\n중복조합(음이 아닌 정수해)과 양의 정수해의 관계를 이용하는 문제이다.\n- 음이 아닌 정수해: $x_1 + x_2 + \\cdots + x_n = r$을 만족하는 해의 개수는 $\\binom{n+r-1}{n-1}$\n- 양의 정수해: 변수 치환을 통해 음이 아닌 정수해 문제로 변환\n\n**[풀이]**\n\n**단계 1: 문제 상황 분석**\n\n$x + y + z = 7$을 만족하는 양의 정수 $x, y, z$를 구해야 한다.\n양의 정수는 1 이상의 정수이므로, $x \\geq 1, y \\geq 1, z \\geq 1$이라는 조건이 있다.\n\n**단계 2: 변수 치환**\n\n양의 정수 조건을 음이 아닌 정수 조건으로 바꾸기 위해 다음과 같이 치환한다.\n\n$$x = x' + 1, \\quad y = y' + 1, \\quad z = z' + 1$$\n\n여기서 $x', y', z' \\geq 0$ (음이 아닌 정수)\n\n**단계 3: 새로운 방정식으로 변환**\n\n$(x' + 1) + (y' + 1) + (z' + 1) = 7$\n\n$$x' + y' + z' + 3 = 7$$\n\n$$x' + y' + z' = 4$$\n\n**단계 4: 중복조합 공식 적용**\n\n음이 아닌 정수 $x', y', z'$에 대해 $x' + y' + z' = 4$의 해의 개수는:\n\n$$\\binom{3+4-1}{3-1} = \\binom{6}{2} = \\frac{6 \\times 5}{2 \\times 1} = 15$$\n\n**[정답 확인]**\n변수 치환으로 양의 정수 조건을 음이 아닌 정수 조건으로 변환한 후 중복조합 공식을 적용하면 15가 나온다.\n\n**[오답 분석]**\n- ① 10: 중복조합 계산 실수 ($\\binom{5}{2}$ 계산)\n- ③ 20: 변수 치환 없이 직접 계산하려다 실수\n- ④ 21: $x' + y' + z' = 5$로 잘못 계산 ($\\binom{7}{2} = 21$)\n- ⑤ 28: 음이 아닌 정수 조건으로 시작한 경우 ($x + y + z = 7$를 음이 아닌 정수로 풀면 $\\binom{9}{2} = 36$이 되므로, 다른 계산 오류)\n\n**[핵심 포인트]**\n양의 정수 조건($x \\geq 1$)은 각 변수에서 1을 빼는 치환을 통해 음이 아닌 정수($x' \\geq 0$) 문제로 변환한다. 이를 통해 중복조합 공식을 바로 적용할 수 있다.",
