    "choices": null,
    "answer": 14,
    "explanation": "**[핵심 개념]**\n조건부 정수해의 개수를 구하는 문제이다. 변수 치환을 통해 조건을 단순화한 후, 중복조합을 이용하여 경우의 수를 계산한다.\n\n**[풀이]**\n\n**Step 1: 변수 조건 정리**\n- $1 \\leq x \\leq 4$\n- $y \\geq 2$\n- $z \\geq 3$\n- $x + y + z = 10$\n\n**Step 2: 변수 치환으로 조건을 음이 아닌 정수로 변환**\n\n$x' = x - 1$로 놓으면: $0 \\leq x' \\leq 3$ (∵ $1 \\leq x \\leq 4$)\n\n$y' = y - 2$로 놓으면: $y' \\geq 0$ (∵ $y \\geq 2$)\n\n$z' = z - 3$으로 놓으면: $z' \\geq 0$ (∵ $z \\geq 3$)\n\n**Step 3: 변환된 방정식 도출**\n\n원래 방정식에 대입:\n$$x + y + z = 10$$\n$$(x' + 1) + (y' + 2) + (z' + 3) = 10$$\n$$x' + y' + z' + 6 = 10$$\n$$x' + y' + z' = 4$$\n\n이제 구하는 조건은: $0 \\leq x' \\leq 3$, $y' \\geq 0$, $z' \\geq 0$, $x' + y' + z' = 4$\n\n**Step 4: 경우를 나누어 계산**\n\n$x'$의 값에 따라 경우를 분류한다.\n\n**경우 1: $x' = 0$일 때**\n$$y' + z' = 4, \\quad y' \\geq 0, z' \\geq 0$$\n음이 아닌 정수해의 개수: $\\binom{4+1}{1} = 5$개\n(순서쌍: $(0,4), (1,3), (2,2), (3,1), (4,0)$)\n\n**경우 2: $x' = 1$일 때**\n$$y' + z' = 3, \\quad y' \\geq 0, z' \\geq 0$$\n음이 아닌 정수해의 개수: $\\binom{3+1}{1} = 4$개\n\n**경우 3: $x' = 2$일 때**\n$$y' + z' = 2, \\quad y' \\geq 0, z' \\geq 0$$\n음이 아닌 정수해의 개수: $\\binom{2+1}{1} = 3$개\n\n**경우 4: $x' = 3$일 때**\n$$y' + z' = 1, \\quad y' \\geq 0, z' \\geq 0$$\n음이 아닌 정수해의 개수: $\\binom{1+1}{1} = 2$개\n\n**Step 5: 전체 경우의 수**\n$$5 + 4 + 3 + 2 = 14$$\n\n**[정답 확인]**\n변수 치환으로 조건을 단순화한 후, 각 경우에 대해 중복조합을 적용하여 모두 합하면 14개이다.\n\n**[오답 분석]**\n객관식이 아닌 단답형 문제이다.\n\n**[핵심 포인트]**\n1. 조건이 있는 정수해 문제는 **변수 치환으로 음이 아닌 정수 조건으로 변환**하는 것이 핵심이다.\n2. 범위가 제한된 변수($0 \\leq x' \\leq 3$)는 **각 값에 대해 경우를 나누어 계산**해야 한다.",
