    "explanation": "**[핵심 개념]**\n\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 주어진 식에서 상수항은 $x$의 지수가 0이 되는 항을 찾는 것이다.\n\n**[풀이]**\n\n$(x + \\frac{1}{x})^6$을 이항정리로 전개하면:\n\n$$\\left(x + \\frac{1}{x}\\right)^6 = \\sum_{r=0}^{6} \\binom{6}{r} x^{6-r} \\left(\\frac{1}{x}\\right)^r$$\n\n일반항을 정리하면:\n\n$$\\binom{6}{r} x^{6-r} \\cdot x^{-r} = \\binom{6}{r} x^{6-r-r} = \\binom{6}{r} x^{6-2r}$$\n\n상수항이 되려면 $x$의 지수가 0이어야 하므로:\n\n$$6 - 2r = 0$$\n$$2r = 6$$\n$$r = 3$$\n\n따라서 상수항은 $r=3$일 때의 항이다:\n\n$$\\binom{6}{3} = \\frac{6!}{3! \\cdot 3!} = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = \\frac{120}{6} = 20$$\n\n**[정답 확인]**\n\n$r=3$일 때 $x^{6-2(3)} = x^0 = 1$이므로 상수항이 맞으며, 그 계수는 $\\binom{6}{3} = 20$이다.\n\n**[오답 분석]**\n\n선택지가 없으므로 일반적인 오류를 언급하면:\n- 지수 계산 실수: $6-r-r$을 $6-r$로 잘못 계산\n- 조합 계산 오류: $\\binom{6}{3}$을 잘못 계산하여 15나 다른 값을 얻음\n- $r=2$를 사용: $x^{6-2(2)} = x^2$ (상수항 아님)\n\n**[핵심 포인트]**\n\n일반항에서 $x$의 지수를 $0$으로 만드는 $r$ 값을 찾고, 해당하는 이항계수를 계산하는 것이 핵심이다. 특히 $\\left(\\frac{1}{x}\\right)^r = x^{-r}$임을 정확히 인식해야 한다.",
