    "answer": 2,
    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 특정 항의 계수를 구하는 문제이다.\n이항정리: $(a+b)^n = \\sum_{r=0}^{n} \\binom{n}{r} a^{n-r} b^r$\n일반항: $(2x-1)^4$에서 $r$번째 항은 $\\binom{4}{r}(2x)^{4-r}(-1)^r$\n\n**[풀이]**\n\n이항정리를 이용하여 $(2x-1)^4$를 전개한다.\n\n$$(2x-1)^4 = \\sum_{r=0}^{4} \\binom{4}{r}(2x)^{4-r}(-1)^r$$\n\n일반항은:\n$$\\binom{4}{r}(2x)^{4-r}(-1)^r = \\binom{4}{r} \\cdot 2^{4-r} \\cdot x^{4-r} \\cdot (-1)^r$$\n\n$x^2$의 계수를 구하려면 $4-r = 2$이어야 하므로 $r=2$\n\n$r=2$일 때의 항:\n$$\\binom{4}{2}(2x)^{4-2}(-1)^2 = \\binom{4}{2} \\cdot 2^2 \\cdot x^2 \\cdot 1$$\n\n각 값을 계산하면:\n- $\\binom{4}{2} = \\frac{4!}{2! \\cdot 2!} = \\frac{4 \\times 3}{2 \\times 1} = 6$\n- $2^2 = 4$\n- $(-1)^2 = 1$\n\n따라서 $x^2$의 계수는:\n$$6 \\times 4 \\times 1 = 24$$\n\n**[정답 확인]**\n이항정리에서 $r=2$일 때 $\\binom{4}{2} \\cdot 2^2 \\cdot (-1)^2 = 6 \\times 4 \\times 1 = 24$이므로 정답은 ③이다.\n\n**[오답 분석]**\n- ① 8: $\\binom{4}{2} \\times 2 = 6 \\times 2 = 12$로 잘못 계산\n- ② 16: $2^4 = 16$으로 이항계수를 빠뜨린 경우\n- ④ 32: $\\binom{4}{2} \\times 2^3 = 6 \\times 8 = 48$으로 잘못 계산하거나, $2^5 = 32$로 계산 오류\n- ⑤ 48: $\\binom{4}{1} \\times 2^3 \\times (-1) = 4 \\times 8 = 32$로 $r$값을 잘못 선택하거나 계산 오류\n\n**[핵심 포인트]**\n이항정리에서 특정 차수의 항을 찾을 때, $x$의 지수가 원하는 값이 되도록 하는 $r$값을 정확히 구해야 한다. 이 문제에서는 $4-r=2$에서 $r=2$를 찾고, 계수 $\\binom{4}{r}$와 밑 $2^{4-r}$를 모두 곱해야 한다.",
