    "answer": 3,
    "explanation": "**[핵심 개념]**\n이항정리를 이용한 전개식에서 특정 항의 계수를 구하는 문제이다.\n\n이항정리: $(a+b)^n = \\sum_{k=0}^{n} \\binom{n}{k} a^{n-k} b^k$\n\n주어진 식을 전개할 때 각 항의 지수를 정확히 계산하여 $x^3$이 되는 경우를 찾아야 한다.\n\n**[풀이]**\n\n$\\left(x^2 + \\frac{1}{x}\\right)^6$을 이항정리로 전개하면:\n\n$$\\left(x^2 + \\frac{1}{x}\\right)^6 = \\sum_{k=0}^{6} \\binom{6}{k} (x^2)^{6-k} \\left(\\frac{1}{x}\\right)^k$$\n\n각 항을 정리하면:\n\n$$= \\sum_{k=0}^{6} \\binom{6}{k} x^{2(6-k)} \\cdot x^{-k}$$\n\n$$= \\sum_{k=0}^{6} \\binom{6}{k} x^{12-2k-k}$$\n\n$$= \\sum_{k=0}^{6} \\binom{6}{k} x^{12-3k}$$\n\n**$x^3$의 계수를 구하기:**\n\n$x^3$항이 나오려면:\n$$12 - 3k = 3$$\n\n$$3k = 9$$\n\n$$k = 3$$\n\n따라서 $x^3$의 계수는:\n\n$$\\binom{6}{3} = \\frac{6!}{3! \\cdot 3!} = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = \\frac{120}{6} = 20$$\n\n**[정답 확인]**\n$k=3$일 때 지수가 $12-3(3)=3$이 되므로 $x^3$항이고, 이항계수 $\\binom{6}{3}=20$이 계수이다.\n\n**[오답 분석]**\n- ① 6: $\\binom{6}{1}$의 값으로, $k=1$일 때의 계수 (지수는 9)\n- ② 10: $\\binom{6}{2}$의 값으로, $k=2$일 때의 계수 (지수는 6)\n- ③ 15: $\\binom{6}{4}$의 값으로, $k=4$일 때의 계수 (지수는 0)\n- ⑤ 30: 계산 실수로 $\\binom{6}{3} \\times 1.5$ 정도로 잘못 계산한 경우\n\n**[핵심 포인트]**\n이항정리 전개에서 특정 차수의 계수를 구할 때는 **지수 조건식을 먼저 세우고 $k$값을 결정**한 후, 해당하는 이항계수를 계산해야 한다. 지수 계산 실수가 가장 흔한 오류이다.",
