    "_type": "binomial",
    "type": "이항정리",
    "problem": "$(1+x)^{10}$의 전개식에서 $x^4$의 계수와 $x^5$의 계수의 비를 가장 간단한 정수비 $a:b$로 나타낼 때, $a + b$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 11,
    "explanation": "**[핵심 개념]**\n이항정리(Binomial Theorem)에 따르면 $(1+x)^n$의 전개식에서 $x^k$의 계수는 $\\binom{n}{k}$이다. 즉, $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$이며, 이를 이용하여 특정 항의 계수를 구한다. 또한 두 수의 비를 가장 간단한 정수비로 나타내려면 최대공약수로 나누어 기약분수 형태로 만들어야 한다.\n\n**[풀이]**\n\n**1단계: $x^4$의 계수 구하기**\n\n$(1+x)^{10}$의 전개식에서 $x^4$의 계수는 이항계수 $\\binom{10}{4}$이다.\n\n$$\\binom{10}{4} = \\frac{10!}{4! \\cdot 6!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = \\frac{5040}{24} = 210$$\n\n**2단계: $x^5$의 계수 구하기**\n\n$(1+x)^{10}$의 전개식에서 $x^5$의 계수는 이항계수 $\\binom{10}{5}$이다.\n\n$$\\binom{10}{5} = \\frac{10!}{5! \\cdot 5!} = \\frac{10 \\times 9 \\times 8 \\times 7 \\times 6}{5 \\times 4 \\times 3 \\times 2 \\times 1} = \\frac{30240}{120} = 252$$\n\n**3단계: 계수의 비 구하기**\n\n$$\\binom{10}{4} : \\binom{10}{5} = 210 : 252$$\n\n**4단계: 최대공약수로 약분하기**\n\n$210 = 2 \\times 3 \\times 5 \\times 7$\n$252 = 2^2 \\times 3^2 \\times 7$\n\n$\\gcd(210, 252) = 2 \\times 3 \\times 7 = 42$\n\n$$210 : 252 = \\frac{210}{42} : \\frac{252}{42} = 5 : 6$$\n\n따라서 가장 간단한 정수비는 $a : b = 5 : 6$이다.\n\n**5단계: 답 구하기**\n\n$$a + b = 5 + 6 = 11$$\n\n**[정답 확인]**\n이항계수를 올바르게 계산하여 비를 구한 후 최대공약수 42로 약분하면 $5:6$을 얻고, $5+6=11$이 정답이다.\n\n**[오답 분석]**\n- 약분하지 않고 $210 + 252 = 462$를 답으로 하는 경우: 계수의 합을 구하는 것이 아니라 비의 합을 구해야 한다.\n- 비율을 역으로 계산하여 $6 : 5$로 구한 후 $11$을 얻는 경우: 순서는 달라지지만 합은 같으므로 우연히 맞을 수 있다.\n- 최대공약수를 잘못 구한 경우: 약분이 불완전하여 다른 값을 얻게 된다.\n\n**[핵심 포인트]**\n$(1+x)^n$에서 $x^k$의 계수는 $\\binom{n}{k}$이며, 비를 가장 간단한 형태로 만들기 위해서는 반드시 최대공약수로 약분하는 과정이 필수이다.",
