    "_type": "binomial",
    "type": "이항정리",
    "problem": "$(1 + x + x^2)^8$의 전개식에서 $x^4$의 계수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 266,
    "explanation": "**[핵심 개념]**\n\n$(1 + x + x^2)^8$을 전개할 때 $x^4$의 계수를 구하려면 다항정리를 활용해야 한다. 일반항은 다음과 같이 나타낼 수 있다:\n\n$$(1 + x + x^2)^8 = \\sum_{i+j+k=8} \\binom{8}{i,j,k} \\cdot 1^i \\cdot x^j \\cdot (x^2)^k$$\n\n여기서 $i, j, k \\geq 0$이고, 지수가 $j + 2k = 4$를 만족할 때만 $x^4$ 항이 된다.\n\n**[풀이]**\n\n$(1 + x + x^2)^8$에서 $x^4$ 항이 나오려면:\n- $i + j + k = 8$ (전개에서 8개를 선택)\n- $j + 2k = 4$ (지수 조건)\n\n$j + 2k = 4$에서 가능한 $(j, k)$의 경우:\n\n**경우 1: $k = 0, j = 4$**\n$$i = 8 - j - k = 8 - 4 - 0 = 4$$\n계수: $\\binom{8}{4,4,0} = \\frac{8!}{4! \\cdot 4! \\cdot 0!} = \\frac{8!}{4! \\cdot 4!} = \\binom{8}{4} = 70$\n\n**경우 2: $k = 1, j = 2$**\n$$i = 8 - j - k = 8 - 2 - 1 = 5$$\n계수: $\\binom{8}{5,2,1} = \\frac{8!}{5! \\cdot 2! \\cdot 1!} = \\frac{8 \\times 7 \\times 6}{2 \\times 1} = 168$\n\n**경우 3: $k = 2, j = 0$**\n$$i = 8 - j - k = 8 - 0 - 2 = 6$$\n계수: $\\binom{8}{6,0,2} = \\frac{8!}{6! \\cdot 0! \\cdot 2!} = \\frac{8 \\times 7}{2} = 28$\n\n따라서 $x^4$의 계수는:\n$$70 + 168 + 28 = 266$$\n\n**[정답 확인]**\n\n세 가지 경우 모두에서 $i + j + k = 8$과 $j + 2k = 4$를 동시에 만족하며, 각 경우의 다항계수를 정확히 계산하여 합하면 266이 된다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오답은:\n- 경우를 빠뜨린 경우 (예: 경우 2나 경우 3만 계산)\n- 다항계수 계산 실수 (조합 계산 오류)\n- $j + 2k = 4$ 조건을 놓치고 전체 전개식에서 $x^4$ 항만 찾는 경우\n\n**[핵심 포인트]**\n\n$(a + b + c)^n$ 형태의 전개에서는 **지수 조건을 만족하는 모든 경우를 찾아 각 경우의 다항계수를 구한 후 합산**해야 한다. 이 문제에서 $j + 2k = 4$를 만족하는 세 가지 경우를 모두 고려하는 것이 핵심이다.",
