    "explanation": "**[핵심 개념]**\n확률의 정의: 어떤 사건이 일어날 확률은 $\\frac{\\text{사건이 일어나는 경우의 수}}{\\text{전체 경우의 수}}$이다.\n\n주사위를 던질 때 나올 수 있는 모든 결과는 1, 2, 3, 4, 5, 6으로 총 6가지이다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 파악**\n주사위를 한 번 던질 때 나올 수 있는 모든 눈: {1, 2, 3, 4, 5, 6}\n따라서 전체 경우의 수 = 6\n\n**2단계: 사건 조건 분석**\n\"3 이상의 눈이 나올 경우\"를 찾아봅시다.\n- 3 이상: 3, 4, 5, 6\n- 조건을 만족하는 경우의 수 = 4\n\n**3단계: 확률 계산**\n$$P(\\text{3 이상}) = \\frac{\\text{3 이상인 경우의 수}}{\\text{전체 경우의 수}} = \\frac{4}{6} = \\frac{2}{3}$$\n\n**[정답 확인]**\n3 이상인 눈은 4개(3, 4, 5, 6)이고 전체 6가지 중이므로, 확률은 $\\frac{4}{6} = \\frac{2}{3}$이다.\n\n**[오답 분석]**\n\n① $\\frac{1}{6}$: 특정 숫자 하나가 나올 확률 (예: 3이 정확히 나올 확률)\n\n② $\\frac{1}{3}$: $\\frac{2}{6}$로, 2가지 경우만 센 것 (예: 홀수 중 일부)\n\n③ $\\frac{1}{2}$: $\\frac{3}{6}$으로, 3가지 경우만 센 것 (예: 1, 2, 3)\n\n⑤ $\\frac{5}{6}$: 5가지 경우의 확률로, \"3 초과\"와 혼동한 경우\n\n**[핵심 포인트]**\n- \"3 이상\" = 3을 포함하여 3, 4, 5, 6 (4가지)\n- \"3 초과\"와 혼동하지 않기 (초과는 4, 5, 6만 해당)",
