    "answer": 4,
    "explanation": "**[핵심 개념]**\n여사건의 확률을 이용하는 방법이다. \"적어도 1번 앞면이 나올 확률\"은 전체에서 \"한 번도 앞면이 나오지 않을 확률\"을 빼는 것이 더 간단한다. 동전 1개를 던질 때 앞면이 나올 확률은 $\\frac{1}{2}$, 뒷면이 나올 확률도 $\\frac{1}{2}$이다.\n\n**[풀이]**\n\n**방법 1: 여사건을 이용한 풀이**\n\n\"적어도 1번 앞면이 나올 확률\" = 1 - \"3번 모두 뒷면이 나올 확률\"\n\n동전을 3번 던질 때, 매번 독립적으로 일어나므로:\n\n$$P(\\text{3번 모두 뒷면}) = \\frac{1}{2} \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{8}$$\n\n따라서:\n$$P(\\text{적어도 1번 앞면}) = 1 - \\frac{1}{8} = \\frac{7}{8}$$\n\n**방법 2: 직접 계산 (검증)**\n\n\"적어도 1번 앞면\" = \"정확히 1번 앞면\" + \"정확히 2번 앞면\" + \"정확히 3번 앞면\"\n\n- 정확히 1번 앞면: $\\binom{3}{1} \\times \\left(\\frac{1}{2}\\right)^1 \\times \\left(\\frac{1}{2}\\right)^2 = 3 \\times \\frac{1}{8} = \\frac{3}{8}$\n\n- 정확히 2번 앞면: $\\binom{3}{2} \\times \\left(\\frac{1}{2}\\right)^2 \\times \\left(\\frac{1}{2}\\right)^1 = 3 \\times \\frac{1}{8} = \\frac{3}{8}$\n\n- 정확히 3번 앞면: $\\binom{3}{3} \\times \\left(\\frac{1}{2}\\right)^3 = 1 \\times \\frac{1}{8} = \\frac{1}{8}$\n\n합계: $\\frac{3}{8} + \\frac{3}{8} + \\frac{1}{8} = \\frac{7}{8}$\n\n**[정답 확인]**\n여사건을 이용하여 $1 - \\frac{1}{8} = \\frac{7}{8}$이 구해지므로 정답은 ⑤번이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{8}$: 3번 모두 뒷면이 나올 확률 (구하는 값의 여사건)\n- ② $\\frac{3}{8}$: 정확히 1번만 앞면이 나올 확률 (불완전함)\n- ③ $\\frac{1}{2}$: 특별한 의미 없음 (단순 오류)\n- ④ $\\frac{5}{8}$: 계산 실수로 얻어질 수 있는 값\n\n**[핵심 포인트]**\n\"적어도\"라는 표현이 나오면 여사건을 먼저 생각하세요. $P(\\text{적어도 1번}) = 1 - P(\\text{0번})$이 가장 효율적이다.",
