    "explanation": "**[핵심 개념]**\n- **여사건의 확률**: 어떤 사건이 일어날 확률을 직접 구하기 어려울 때, 그 여사건(일어나지 않을 확률)을 이용하면 편리한다.\n- 공식: $P(A) = 1 - P(A^c)$ (여기서 $A^c$는 A의 여사건)\n- **독립시행의 확률**: 각 시행이 독립적일 때, 여러 번 시행한 결과의 확률은 각 확률의 곱으로 계산한다.\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- 한 발을 맞힐 확률: $P(\\text{맞음}) = \\frac{4}{5}$\n- 한 발을 맞추지 못할 확률: $P(\\text{빗남}) = 1 - \\frac{4}{5} = \\frac{1}{5}$\n- 총 3발을 쏨\n\n**Step 2: 구하는 확률 정의**\n\"적어도 1발 이상 맞힐 확률\" = \"1발 이상 3발 이하가 맞을 확률\"\n\n**Step 3: 여사건을 이용한 풀이**\n적어도 1발 이상 맞힐 확률은 3발 모두 빗나갈 확률의 여사건이다.\n\n$$P(\\text{적어도 1발 이상 맞음}) = 1 - P(\\text{3발 모두 빗남})$$\n\n**Step 4: 3발 모두 빗나갈 확률 계산**\n각 발이 독립적이므로:\n\n$$P(\\text{3발 모두 빗남}) = \\left(\\frac{1}{5}\\right)^3 = \\frac{1}{125}$$\n\n**Step 5: 최종 확률 계산**\n\n$$P(\\text{적어도 1발 이상 맞음}) = 1 - \\frac{1}{125} = \\frac{125-1}{125} = \\frac{124}{125}$$\n\n**Step 6: 기약분수 확인 및 분모 구하기**\n$\\frac{124}{125}$에서 $\\gcd(124, 125) = 1$이므로 이미 기약분수이다.\n\n따라서 기약분수의 분모는 **125**\n\n**[정답 확인]**\n여사건을 이용하여 \"3발 모두 빗나갈 확률\"을 구하고 이를 1에서 뺀 결과 $\\frac{124}{125}$를 얻었고, 분모는 125이다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 없음\n\n**[핵심 포인트]**\n- **여사건 활용**: \"적어도 1발 이상\"처럼 경우의 수가 많을 때는 여사건(\"모두 안 됨\")으로 푸는 것이 훨씬 효율적이다.\n- 독립시행에서 각 시행의 확률을 곱할 때, 역수의 거듭제곱도 같은 방식으로 계산된다: $\\left(\\frac{1}{5}\\right)^3 = \\frac{1^3}{5^3} = \\frac{1}{125}$",
    "difficulty": "lv3",
