    "problem": "두 사건 A, B에 대하여 $P(A) = \\frac{1}{2}$, $P(A \\cap B) = \\frac{1}{5}$일 때, $P(B|A)$의 값은?",
    "answerType": "choice",
    "choices": [
      "① $\\frac{1}{5}$",
      "② $\\frac{3}{10}$",
      "③ $\\frac{2}{5}$",
      "④ $\\frac{1}{2}$",
      "⑤ $\\frac{3}{5}$"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n조건부 확률은 특정 사건이 일어났다는 조건 하에서 다른 사건이 일어날 확률이다. 사건 A가 일어났을 때 사건 B가 일어날 조건부 확률 $P(B|A)$는 다음 공식으로 구한다:\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n이 공식은 A가 이미 발생했으므로, A의 범위 내에서 A와 B가 동시에 일어나는 경우의 비율을 구하는 것이다.\n\n**[풀이]**\n주어진 정보를 정리하면:\n- $P(A) = \\frac{1}{2}$\n- $P(A \\cap B) = \\frac{1}{5}$\n- 구하는 값: $P(B|A)$\n\n조건부 확률 공식에 주어진 값들을 대입한다:\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{\\frac{1}{5}}{\\frac{1}{2}}$$\n\n분수의 나눗셈을 계산한다:\n\n$$P(B|A) = \\frac{1}{5} \\times \\frac{2}{1} = \\frac{2}{5}$$\n\n**[정답 확인]**\n$P(B|A) = \\frac{2}{5}$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{5}$: $P(A \\cap B)$의 값을 그대로 선택한 오류\n- ② $\\frac{3}{10}$: 계산 과정에서 실수한 경우 (예: $\\frac{1}{5} + \\frac{1}{10}$ 등)\n- ④ $\\frac{1}{2}$: $P(A)$의 값을 선택한 오류\n- ⑤ $\\frac{3}{5}$: 분자와 분모를 잘못 계산한 경우\n\n**[핵심 포인트]**\n조건부 확률 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$를 공식에 대입하면 되는 기본 문제이다. \"A가 주어졌을 때\"는 항상 분모에 $P(A)$를 사용한다는 점을 기억하세요.",
