    "type": "조건부 확률",
    "problem": "두 사건 A, B에 대하여 $P(A) = \\frac{2}{5}$, $P(B|A) = \\frac{1}{3}$, $P(B|A^c) = \\frac{2}{3}$일 때, $P(B)$의 값을 구하시오. (기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 8,
    "explanation": "**[핵심 개념]**\n\n조건부 확률과 전확률 공식(Law of Total Probability)을 이용한 문제이다.\n\n- 조건부 확률: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$\n- 전확률 공식: $P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$\n\n사건 $A$의 발생 여부에 따라 전체 확률을 분할하여 계산한다.\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n\n- $P(A) = \\frac{2}{5}$\n- $P(B|A) = \\frac{1}{3}$\n- $P(B|A^c) = \\frac{2}{3}$\n\n**Step 2: $P(A^c)$ 계산**\n\n$$P(A^c) = 1 - P(A) = 1 - \\frac{2}{5} = \\frac{3}{5}$$\n\n**Step 3: 전확률 공식 적용**\n\n전확률 공식에 의해:\n\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n**Step 4: 값 대입**\n\n$$P(B) = \\frac{1}{3} \\cdot \\frac{2}{5} + \\frac{2}{3} \\cdot \\frac{3}{5}$$\n\n$$P(B) = \\frac{2}{15} + \\frac{6}{15}$$\n\n$$P(B) = \\frac{8}{15}$$\n\n**Step 5: 기약분수 확인 및 분자 확인**\n\n$\\gcd(8, 15) = 1$이므로 $\\frac{8}{15}$는 기약분수이다.\n\n따라서 분자는 **8**이다.\n\n**[정답 확인]**\n\n전확률 공식을 정확하게 적용하여 $P(B) = \\frac{8}{15}$를 얻었고, 기약분수 형태의 분자인 8이 정답이다.\n\n**[오답 분석]**\n\n- **3**: $P(A^c)$의 분자를 답으로 선택한 경우\n- **5**: $P(A)$의 분모를 답으로 선택한 경우\n- **15**: 기약분수가 아닌 분모를 잘못 답으로 선택한 경우\n\n**[핵심 포인트]**\n\n전체 표본공간을 상호배타적인 두 사건 $A$, $A^c$로 분할할 때, 어떤 사건 $B$의 확률은 $P(B) = P(B|A)P(A) + P(B|A^c)P(A^c)$로 구한다. 조건부 확률이 주어질 때는 항상 전확률 공식의 적용을 먼저 고려하세요.",
