    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "어느 공장에서 A 기계는 전체 제품의 60%, B 기계는 40%를 생산한다. A 기계의 불량률은 3%, B 기계의 불량률은 5%이다. 임의로 선택한 제품이 불량품일 때, 그것이 A 기계에서 생산되었을 확률을 구하시오. (기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률과 전확률 공식(베이즈 정리)을 이용하는 문제이다.\n- **전확률 공식**: $P(B) = P(B|A)P(A) + P(B|A^c)P(A^c)$\n- **베이즈 정리**: $P(A|B) = \\frac{P(B|A)P(A)}{P(B)}$\n\n여기서 \"불량품이 주어졌을 때, A 기계에서 생산되었을 확률\"을 구하는 것이므로 베이즈 정리를 사용한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $P(A) = 0.6$ (A 기계 생산 비율)\n- $P(B) = 0.4$ (B 기계 생산 비율)\n- $P(\\text{불량}|A) = 0.03$ (A 기계 불량률)\n- $P(\\text{불량}|B) = 0.05$ (B 기계 불량률)\n\n**2단계: 전체 불량품의 확률 계산**\n전확률 공식을 사용하여 임의로 선택한 제품이 불량품일 확률을 구한다.\n\n$$P(\\text{불량}) = P(\\text{불량}|A) \\cdot P(A) + P(\\text{불량}|B) \\cdot P(B)$$\n\n$$= 0.03 \\times 0.6 + 0.05 \\times 0.4$$\n\n$$= 0.018 + 0.020 = 0.038$$\n\n**3단계: 베이즈 정리 적용**\n불량품이 A 기계에서 생산되었을 조건부 확률:\n\n$$P(A|\\text{불량}) = \\frac{P(\\text{불량}|A) \\cdot P(A)}{P(\\text{불량})}$$\n\n$$= \\frac{0.03 \\times 0.6}{0.038} = \\frac{0.018}{0.038}$$\n\n**4단계: 분수로 정리**\n$$\\frac{0.018}{0.038} = \\frac{18}{38} = \\frac{9}{19}$$\n\n기약분수로 나타내면 $\\frac{9}{19}$이므로, 분자는 **9**이다.\n\n**[정답 확인]**\n불량품 중에서 A 기계에서 나온 제품의 비율은 $\\frac{9}{19}$이고, 이를 기약분수로 표현했을 때 분자가 9이므로 정답은 9이다.\n\n**[오답 분석]**\n- **11**: A 기계의 생산 비율 60%를 잘못 선택한 경우\n- **19**: 기약분수의 분모를 선택한 경우\n- **3**: A 기계의 불량률 3%를 그대로 선택한 경우\n- **18**: 분자를 약분하지 않고 선택한 경우\n\n**[핵심 포인트]**\n사후확률(불량품이 주어졌을 때 A 기계 확률)을 구할 때는 단순히 주어진 확률을 이용하면 안 되고, **베이즈 정리**를 사용하여 전체 불량품 중에서의 비율을 계산해야 한다. 분모는 각 기계에서 나올 수 있는 모든 불량품의 확률의 합이다.",
