    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "두 사건 A, B에 대하여 $P(A) = \\frac{1}{3}$, $P(B) = \\frac{1}{2}$, $P(A|B) = \\frac{1}{4}$일 때, $P(A \\cup B)$의 값은?",
    "answerType": "choice",
    "choices": [
      "① $\\frac{5}{12}$",
      "② $\\frac{1}{2}$",
      "③ $\\frac{7}{12}$",
      "④ $\\frac{2}{3}$",
      "⑤ $\\frac{17}{24}$"
    ],
    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n조건부 확률과 합집합의 확률을 다루는 문제이다.\n\n- **조건부 확률**: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n- **합집합의 확률**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n이 두 공식을 연결하여 문제를 풀어야 한다.\n\n**[풀이]**\n\n**1단계: 조건부 확률 공식을 이용하여 $P(A \\cap B)$ 구하기**\n\n조건부 확률의 정의에서:\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)}$$\n\n주어진 값을 대입하면:\n$$\\frac{1}{4} = \\frac{P(A \\cap B)}{\\frac{1}{2}}$$\n\n양변에 $\\frac{1}{2}$를 곱하면:\n$$P(A \\cap B) = \\frac{1}{4} \\times \\frac{1}{2} = \\frac{1}{8}$$\n\n**2단계: 합집합의 확률 공식을 이용하여 $P(A \\cup B)$ 구하기**\n\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n구한 값들을 대입:\n$$P(A \\cup B) = \\frac{1}{3} + \\frac{1}{2} - \\frac{1}{8}$$\n\n**3단계: 분수 계산**\n\n공통분모 24로 통분:\n$$P(A \\cup B) = \\frac{8}{24} + \\frac{12}{24} - \\frac{3}{24} = \\frac{8 + 12 - 3}{24} = \\frac{17}{24}$$\n\n**[정답 확인]**\n\n조건부 확률로부터 교집합 확률을 올바르게 구하고, 합집합 공식을 정확하게 적용하면 $\\frac{17}{24}$를 얻는다.\n\n**[오답 분석]**\n\n- **① $\\frac{5}{12}$**: $P(A \\cap B)$를 계산하지 않고 $P(A) + P(B)$를 잘못 계산한 경우\n- **② $\\frac{1}{2}$**: $P(B)$의 값으로, 중간 계산 실수로 이를 선택한 경우\n- **③ $\\frac{7}{12}$**: $P(A \\cap B) = \\frac{1}{6}$으로 잘못 계산한 경우 ($P(A|B) \\times P(B)$ 계산 실수)\n- **④ $\\frac{2}{3}$**: $P(A \\cap B)$를 빼지 않고 $P(A) + P(B)$만 계산한 경우\n\n**[핵심 포인트]**\n\n조건부 확률 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$를 정확히 변형하여 $P(A \\cap B)$를 먼저 구한 후, 합집합 공식에 대입하는 두 단계 풀이가 핵심이다. 분수 계산 시 공통분모를 찾아 정확하게 계산해야 한다.",
