    "type": "조건부 확률",
    "problem": "세 상자 A, B, C가 있다. A에는 흰 공 3개, 검은 공 2개, B에는 흰 공 1개, 검은 공 4개, C에는 흰 공 4개, 검은 공 1개가 들어 있다. 주사위를 던져 1, 2가 나오면 A에서, 3, 4가 나오면 B에서, 5, 6이 나오면 C에서 공 1개를 꺼낸다. 꺼낸 공이 흰 공일 때, 그것이 B 상자에서 나왔을 확률을 구하시오. (기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 1,
    "explanation": "**[핵심 개념]**\n조건부 확률 공식: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$\n\n이 문제는 \"흰 공이 나왔을 때, 그것이 B에서 나왔을 확률\"을 구하는 조건부 확률 문제이다. 베이즈 정리를 사용하여 다음과 같이 접근한다:\n\n$$P(\\text{B에서 나옴}|\\text{흰 공}) = \\frac{P(\\text{흰 공}|\\text{B에서 나옴}) \\times P(\\text{B에서 나옴})}{P(\\text{흰 공})}$$\n\n**[풀이]**\n\n**1단계: 각 상자에서 나올 확률과 각 상자에서 흰 공이 나올 확률**\n\n주사위를 던질 때:\n- A에서 나올 확률: $P(A) = \\frac{2}{6} = \\frac{1}{3}$\n- B에서 나올 확률: $P(B) = \\frac{2}{6} = \\frac{1}{3}$\n- C에서 나올 확률: $P(C) = \\frac{2}{6} = \\frac{1}{3}$\n\n각 상자에서 흰 공이 나올 확률:\n- A에서 흰 공: $P(\\text{흰}|A) = \\frac{3}{5}$ (흰 공 3개, 검은 공 2개)\n- B에서 흰 공: $P(\\text{흰}|B) = \\frac{1}{5}$ (흰 공 1개, 검은 공 4개)\n- C에서 흰 공: $P(\\text{흰}|C) = \\frac{4}{5}$ (흰 공 4개, 검은 공 1개)\n\n**2단계: 흰 공이 나올 전체 확률 계산**\n\n전확률 공식을 사용하면:\n\n$$P(\\text{흰 공}) = P(\\text{흰}|A) \\times P(A) + P(\\text{흰}|B) \\times P(B) + P(\\text{흰}|C) \\times P(C)$$\n\n$$= \\frac{3}{5} \\times \\frac{1}{3} + \\frac{1}{5} \\times \\frac{1}{3} + \\frac{4}{5} \\times \\frac{1}{3}$$\n\n$$= \\frac{1}{3}\\left(\\frac{3}{5} + \\frac{1}{5} + \\frac{4}{5}\\right) = \\frac{1}{3} \\times \\frac{8}{5} = \\frac{8}{15}$$\n\n**3단계: B에서 흰 공이 나올 확률**\n\n$$P(\\text{흰 공} \\cap B) = P(\\text{흰}|B) \\times P(B) = \\frac{1}{5} \\times \\frac{1}{3} = \\frac{1}{15}$$\n\n**4단계: 조건부 확률 계산**\n\n$$P(B|\\text{흰 공}) = \\frac{P(\\text{흰 공} \\cap B)}{P(\\text{흰 공})} = \\frac{\\frac{1}{15}}{\\frac{8}{15}} = \\frac{1}{15} \\times \\frac{15}{8} = \\frac{1}{8}$$\n\n따라서 기약분수로 $\\frac{1}{8}$이고, 분자는 **1**이다.\n\n**[정답 확인]**\nB에서 나온 흰 공의 확률은 $\\frac{1}{15}$이고, 전체 흰 공의 확률은 $\\frac{8}{15}$이므로, 조건부 확률은 $\\frac{1}{8}$이 되어 정답이 1이다.\n\n**[오답 분석]**\n객관식이 없으므로 생략한다. 만약 다른 답을 선택했다면, 전체 흰 공의 확률 계산 부분이나 조건부 확률 공식의 적용에서 실수했을 가능성이 높다.\n\n**[핵심 포인트]**\n- 조건부 확률은 항상 \"전체 확률\"로 나누기: 흰 공이 나왔다는 조건 하에서 B의 확률이므로, 분모는 모든 경로를 통해 흰 공이 나올 확률\n- 베이즈 정리: 역으로 원인의 확률을 구할 때 전확률 공식이 필수",
    "difficulty": "lv4",
