    "problem": "양성 판정의 민감도가 99%, 특이도가 95%인 검사가 있다. 전체 인구의 0.1%가 해당 질병에 걸려 있을 때, 양성 판정을 받은 사람이 실제로 질병에 걸렸을 확률을 구하시오. (소수 셋째 자리에서 반올림하여 소수 둘째 자리까지 구한 후, 100을 곱하여 정수로 답하시오.)",
