    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이 문제는 조건부 확률과 베이즈 정리를 활용하는 의료 통계 문제이다.\n\n- **민감도(sensitivity)**: 질병이 있는 사람이 양성으로 판정될 확률 = $P(+|질병)$\n- **특이도(specificity)**: 질병이 없는 사람이 음성으로 판정될 확률 = $P(-|건강)$\n- **구하는 것**: 양성 판정을 받은 사람이 실제로 질병을 가질 확률 = $P(질병|+)$ (양성 예측도)\n\n**베이즈 정리**: $P(질병|+) = \\frac{P(+|질병) \\times P(질병)}{P(+)}$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 민감도: $P(+|질병) = 0.99$\n- 특이도: $P(-|건강) = 0.95$ → $P(+|건강) = 1 - 0.95 = 0.05$\n- 질병 유병률: $P(질병) = 0.001$ → $P(건강) = 0.999$\n\n**2단계: 전체 양성 판정의 확률 $P(+)$ 구하기**\n\n전확률 공식을 사용한다:\n\n$$P(+) = P(+|질병) \\times P(질병) + P(+|건강) \\times P(건강)$$\n\n$$P(+) = 0.99 \\times 0.001 + 0.05 \\times 0.999$$\n\n$$P(+) = 0.00099 + 0.04995 = 0.05094$$\n\n**3단계: 베이즈 정리 적용**\n\n$$P(질병|+) = \\frac{P(+|질병) \\times P(질병)}{P(+)}$$\n\n$$P(질병|+) = \\frac{0.99 \\times 0.001}{0.05094}$$\n\n$$P(질병|+) = \\frac{0.00099}{0.05094} = 0.019434...$$\n\n**4단계: 소수점 처리 및 최종 계산**\n\n소수 셋째 자리에서 반올림하면:\n$$0.019434... \\approx 0.019 \\approx 0.02$$\n\n100을 곱하면:\n$$0.02 \\times 100 = 2$$\n\n**[정답 확인]**\n\n베이즈 정리를 정확히 적용하여 양성 판정 시 실제 질병 확률을 구하면 약 1.94%로, 반올림하면 2%이므로 정답은 **2**이다.\n\n**[오답 분석]**\n\n객관식이 없으므로 생략하지만, 흔한 실수는:\n- 민감도 99%를 그대로 답으로 착각 (→ 99)\n- 특이도 95%를 사용 (→ 95)\n- 전체 양성 확률을 계산하지 않고 민감도만 사용 (→ 99)\n\n**[핵심 포인트]**\n\n**희귀질병에서는 민감도가 높아도 양성 예측도(실제 질병 확률)는 매우 낮다.** 이유는 거짓 양성(건강한데 양성)이 진정한 양성(질병이면서 양성)보다 훨씬 많기 때문이다. 베이즈 정리는 \"사전 확률(유병률)이 낮을수록 양성 판정의 신뢰도가 떨어진다\"는 의학적 직관을 수식으로 보여준다.",
    "difficulty": "lv4",
