    "answer": 3,
    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 성질:\n- 기댓값(평균): $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n이항분포는 n번의 독립적인 베르누이 시행에서 성공 확률이 p일 때의 분포로, 분산 공식은 성공 확률과 실패 확률의 곱에 시행 횟수를 곱한 형태이다.\n\n**[풀이]**\n주어진 조건을 정리하면:\n- $X \\sim B(100, \\frac{1}{5})$\n- $n = 100$, $p = \\frac{1}{5}$\n\n이항분포의 분산 공식을 적용한다:\n$$V(X) = np(1-p)$$\n\n$1-p$를 계산하면:\n$$1-p = 1 - \\frac{1}{5} = \\frac{4}{5}$$\n\n분산값을 구한다:\n$$V(X) = 100 \\times \\frac{1}{5} \\times \\frac{4}{5}$$\n\n$$V(X) = 100 \\times \\frac{4}{25}$$\n\n$$V(X) = \\frac{400}{25} = 16$$\n\n**[정답 확인]**\n$V(X) = 16$이므로 정답은 ④번이다.\n\n**[오답 분석]**\n- ① 4: $np = 100 \\times \\frac{1}{5} = 20$과 혼동했을 가능성\n- ② 8: $np$의 절반인 값으로, 분산 공식을 잘못 적용한 경우\n- ③ 12: 계산 과정에서 실수한 경우\n- ⑤ 20: $np$ 값 그 자체로, 기댓값과 분산을 혼동한 경우\n\n**[핵심 포인트]**\n이항분포의 분산 공식 $V(X) = np(1-p)$를 정확히 기억하고, 특히 분산은 기댓값과 다르다는 점을 유의해야 한다. $(1-p)$ 항을 빠뜨리지 않는 것이 중요하다.",
