    "problem": "확률변수 $X$가 이항분포 $B(n, p)$를 따르고 $E(X) = 6$, $V(X) = 2$일 때, $n$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n확률변수 $X$가 이항분포 $B(n, p)$를 따를 때, 기댓값과 분산의 공식은 - 기댓값: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n이 두 공식을 이용하면 모수 $n$과 $p$를 구한다.\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- $E(X) = 6$\n- $V(X) = 2$\n\n**Step 2: 기댓값과 분산의 관계식 세우기**\n\n이항분포의 기댓값 공식에서:\n$$E(X) = np = 6 \\cdots (1)$$\n\n이항분포의 분산 공식에서:\n$$V(X) = np(1-p) = 2 \\cdots (2)$$\n\n**Step 3: $p$ 구하기**\n\n식 (2)를 식 (1)로 나누면:\n$$\\frac{np(1-p)}{np} = \\frac{2}{6}$$\n\n$$1-p = \\frac{1}{3}$$\n\n$$p = \\frac{2}{3}$$\n\n**Step 4: $n$ 구하기**\n\n식 (1)에 $p = \\frac{2}{3}$를 대입:\n$$n \\cdot \\frac{2}{3} = 6$$\n\n$$n = 6 \\times \\frac{3}{2} = 9$$\n\n**Step 5: 검산**\n\n$n = 9$, $p = \\frac{2}{3}$일 때:\n- $E(X) = 9 \\times \\frac{2}{3} = 6$ ✓\n- $V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = 9 \\times \\frac{2}{9} = 2$ ✓\n\n**[정답 확인]**\n$n = 9$일 때 기댓값과 분산의 조건을 모두 만족하므로 정답이다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오류를 제시한다.\n- $n = 6$: $p$를 구하지 않고 기댓값만 사용한 경우\n- $n = 18$: 분산 공식을 잘못 이해하거나 계산 실수한 경우\n- $n = 3$: $p$와 $n$을 혼동한 경우\n\n**[핵심 포인트]**\n이항분포에서 $E(X) = np$, $V(X) = np(1-p)$를 이용하면, 두 식의 비를 통해 $p$를 먼저 구한 후 $n$을 구하는 것이 효율적이다.",
