    "problem": "확률변수 $X$가 정규분포 $N(50, 5^2)$을 따를 때, $P(X \\geq 55)$를 표준정규분포표를 이용하여 구한 값은? (단, $P(0 \\leq Z \\leq 1) = 0.3413$)",
