    "answer": 2,
    "explanation": "**[핵심 개념]**\n정규분포 문제를 풀기 위해서는 **표준화(정규화)** 과정이 필수이다. 일반 정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수 $X$를 표준정규분포 $N(0, 1)$을 따르는 확률변수 $Z$로 변환하는 공식은 :\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n이를 통해 주어진 표준정규분포표를 이용하여 확률을 구한다.\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- $X \\sim N(50, 5^2)$ (평균 $\\mu = 50$, 표준편차 $\\sigma = 5$)\n- 구하는 값: $P(X \\geq 55)$\n- 주어진 표준정규분포 정보: $P(0 \\leq Z \\leq 1) = 0.3413$\n\n**Step 2: 표준화 수행**\n$X = 55$일 때 표준정규분포로 변환한다:\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{55 - 50}{5} = \\frac{5}{5} = 1$$\n\n따라서:\n$$P(X \\geq 55) = P(Z \\geq 1)$$\n\n**Step 3: 표준정규분포의 대칭성 이용**\n표준정규분포는 $Z = 0$을 중심으로 대칭이다. 전체 확률이 1이므로:\n- $P(Z \\leq 0) = 0.5$ (왼쪽 절반)\n- $P(Z \\geq 0) = 0.5$ (오른쪽 절반)\n\n**Step 4: 구하는 확률 계산**\n$P(0 \\leq Z \\leq 1) = 0.3413$이 주어졌으므로:\n$$P(Z \\geq 1) = P(Z \\geq 0) - P(0 \\leq Z \\leq 1)$$\n$$P(Z \\geq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**[정답 확인]**\n$P(X \\geq 55) = P(Z \\geq 1) = 0.1587$이므로 정답은 **③번**이다.\n\n**[오답 분석]**\n- ① 0.0228: $0.5 - 0.3413 = 0.1587$을 계산하지 않음, 또는 잘못된 계산\n- ② 0.0668: $P(0 \\leq Z \\leq 1)$을 반으로 나눈 값 ($0.3413 \\div 2$) - 부분확률을 전체로 착각\n- ④ 0.2514: $0.3413 - 0.0899$ 등 불필요한 계산으로 얻은 값\n- ⑤ 0.3413: 주어진 $P(0 \\leq Z \\leq 1)$ 값을 그대로 선택한 오류\n\n**[핵심 포인트]**\n1. **표준화 공식**: $Z = \\frac{X - \\mu}{\\sigma}$를 정확히 적용하고, 표준편차 값을 확인하세요.\n2. **표준정규분포의 성질**: $P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$ (단, $a > 0$)를 활용하여 한 번에 답을 구한다.",
