    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n정규분포는 평균을 중심으로 대칭인 분포이다. 따라서 두 점이 평균으로부터 같은 거리에 있으면, 그 두 점을 기준으로 한 누적확률이 대칭 관계를 가진다. 즉, $P(X \\leq a) = P(X \\geq b)$라는 조건은 $a$와 $b$가 평균 $m$을 중심으로 대칭이라는 의미이다.\n\n**[풀이]**\n\n주어진 조건: $P(X \\leq 14) = P(X \\geq 26)$\n\n정규분포의 대칭성을 이용한다.\n\n$P(X \\leq 14) = P(X \\geq 26)$이 성립한다는 것은 14와 26이 평균 $m$을 중심으로 대칭이라는 뜻이다.\n\n정규분포에서 대칭성을 식으로 나타내면:\n- 점 $a$를 기준으로 한 누적확률 $P(X \\leq a)$\n- 점 $b$를 기준으로 한 누적확률의 여사건 $P(X \\geq b)$\n\n이 둘이 같으려면:\n$$P(X \\leq 14) = P(X \\geq 26)$$\n\n정규분포의 대칭성에 의해:\n$$P(X \\leq 14) = P(X \\geq 26) \\Rightarrow 14 \\text{와 } 26 \\text{은 평균 } m \\text{에 대해 대칭}$$\n\n따라서 평균 $m$은 14와 26의 중점이다:\n\n$$m = \\frac{14 + 26}{2} = \\frac{40}{2} = 20$$\n\n**[정답 확인]**\n\n$m = 20$일 때, 14는 평균으로부터 6만큼 왼쪽에, 26은 평균으로부터 6만큼 오른쪽에 위치하므로 대칭이고, $P(X \\leq 14) = P(X \\geq 26)$이 성립한다.\n\n**[오답 분석]**\n\n- ① 16: $m=16$이면 평균으로부터 14는 2만큼, 26은 10만큼 떨어져 있어 대칭이 아닙니다.\n- ② 18: $m=18$이면 평균으로부터 14는 4만큼, 26은 8만큼 떨어져 있어 대칭이 아닙니다.\n- ④ 22: $m=22$이면 평균으로부터 14는 8만큼, 26은 4만큼 떨어져 있어 대칭이 아닙니다.\n- ⑤ 24: $m=24$이면 평균으로부터 14는 10만큼, 26은 2만큼 떨어져 있어 대칭이 아닙니다.\n\n**[핵심 포인트]**\n\n정규분포에서 $P(X \\leq a) = P(X \\geq b)$라는 조건이 주어지면, $a$와 $b$가 평균을 중심으로 대칭이므로 $m = \\frac{a+b}{2}$로 즉시 구한다.",
