    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하기 위해 표준화(정규화)를 사용한다. 확률변수 $X$가 $N(\\mu, \\sigma^2)$을 따를 때, $Z = \\frac{X-\\mu}{\\sigma}$로 변환하면 $Z$는 표준정규분포 $N(0,1)$을 따릅니다. 표준정규분포는 평균을 중심으로 대칭이라는 성질을 이용한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(70, 10^2)$ 이므로 $\\mu = 70$, $\\sigma = 10$\n- 구하는 확률: $P(50 \\leq X \\leq 80)$\n\n**2단계: 표준화 변환**\n\n$X$를 표준정규분포로 변환한다:\n$$Z = \\frac{X - 70}{10}$$\n\n$X = 50$일 때: $Z = \\frac{50-70}{10} = \\frac{-20}{10} = -2$\n\n$X = 80$일 때: $Z = \\frac{80-70}{10} = \\frac{10}{10} = 1$\n\n따라서:\n$$P(50 \\leq X \\leq 80) = P(-2 \\leq Z \\leq 1)$$\n\n**3단계: 표준정규분포의 대칭성 이용**\n\n표준정규분포는 $Z=0$을 중심으로 대칭이므로:\n$$P(-2 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 2) = 0.4772$$\n\n**4단계: 구간 분리**\n\n$$P(-2 \\leq Z \\leq 1) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1)$$\n\n$$= 0.4772 + 0.3413 = 0.8185$$\n\n**[정답 확인]**\n\n$P(50 \\leq X \\leq 80) = 0.8185$이므로 정답은 **③번**이다.\n\n**[오답 분석]**\n\n- ① 0.6826: $P(-1 \\leq Z \\leq 1) = 2 \\times 0.3413$으로 계산한 경우\n- ② 0.7745: $P(-2 \\leq Z \\leq 1)$을 잘못 계산한 경우\n- ④ 0.8664: $P(-1.5 \\leq Z \\leq 1.5)$ 정도에 해당하는 값\n- ⑤ 0.9544: $P(-2 \\leq Z \\leq 2) = 2 \\times 0.4772$으로 계산한 경우\n\n**[핵심 포인트]**\n\n1. 정규분포 문제는 반드시 **표준화($Z = \\frac{X-\\mu}{\\sigma}$)** 를 통해 표준정규분포로 변환해야 한다.\n2. 표준정규분포의 **대칭성**을 이용하여 $P(-a \\leq Z \\leq 0) = P(0 \\leq Z \\leq a)$임을 활용한다.",
