    "problem": "어느 고등학교 학생들의 수학 성적은 평균 60점, 표준편차 15점인 정규분포를 따른다. 전체 학생이 500명일 때, 75점 이상인 학생 수를 구하시오. (소수점 이하 버림) (단, $P(0 \\leq Z \\leq 1) = 0.3413$)",
    "answerType": "short",
    "choices": null,
    "answer": 79,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 확률변수를 표준정규분포로 변환하기 위해 표준화(Z-score) 공식을 사용한다. 표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$ (여기서 $\\mu$는 평균, $\\sigma$는 표준편차)\n\n표준정규분포의 대칭성을 이용하면:\n- $P(Z \\geq 0) = 0.5$\n- $P(Z < 0) = 0.5$\n- $P(a \\leq Z \\leq b) = P(0 \\leq Z \\leq b) - P(0 \\leq Z \\leq a)$ (단, $0 \\leq a < b$)\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 평균: $\\mu = 60$점\n- 표준편차: $\\sigma = 15$점\n- 전체 학생 수: $N = 500$명\n- 구하는 값: 75점 이상인 학생 수\n- 주어진 확률: $P(0 \\leq Z \\leq 1) = 0.3413$\n\n**2단계: 75점을 표준화**\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{75 - 60}{15} = \\frac{15}{15} = 1$$\n\n따라서 75점 이상은 표준정규분포에서 $Z \\geq 1$인 경우이다.\n\n**3단계: $P(Z \\geq 1)$ 구하기**\n\n표준정규분포의 대칭성을 이용하면:\n$$P(Z \\geq 1) = P(Z > 0) - P(0 \\leq Z \\leq 1)$$\n\n$$P(Z \\geq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**4단계: 75점 이상인 학생 수 계산**\n$$\\text{학생 수} = 500 \\times 0.1587 = 79.35$$\n\n소수점 이하를 버리면:\n$$\\text{답} = 79\\text{명}$$\n\n**[정답 확인]**\n표준화를 통해 구한 $Z = 1$일 때의 확률 $P(Z \\geq 1) = 0.1587$을 전체 학생 수 500명에 곱하면 79.35명이 되고, 소수점 이하를 버리면 79명이다.\n\n**[오답 분석]**\n- **80명**: 79.35를 반올림한 경우. 문제에서 명시적으로 '버림'을 요구했으므로 틀림\n- **78명**: 계산 과정에서 확률값을 잘못 적용한 경우\n- **158명**: $P(Z \\leq 1) = 0.8413$을 전체 학생에 곱한 경우 (75점 **이하**를 구한 오류)\n\n**[핵심 포인트]**\n1. 정규분포 문제는 반드시 표준화 $Z = \\frac{X-\\mu}{\\sigma}$를 첫 단계로 진행\n2. 표준정규분포는 $Z=0$을 중심으로 대칭이므로 $P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$ 공식을 활용",
