    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 확률변수 $X$에 대하여 $P(m - 2\\sigma \\leq X \\leq m + \\sigma)$의 값을 구하시오. (소수점 넷째 자리에서 반올림하여 소수점 셋째 자리까지 구한 후 1000을 곱하여 정수로 답하시오.) (단, $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$)",
    "answerType": "short",
    "choices": null,
    "answer": 819,
    "explanation": "**[핵심 개념]**\n\n정규분포 $N(m, \\sigma^2)$을 따르는 확률변수 $X$를 표준정규분포로 변환하기 위해 표준화를 사용한다. $Z = \\frac{X-m}{\\sigma}$로 놓으면 $Z$는 표준정규분포 $N(0,1)$을 따릅니다. 표준정규분포는 평균을 중심으로 대칭이므로 $P(Z \\leq 0) = P(Z \\geq 0) = 0.5$이다.\n\n**[풀이]**\n\n**Step 1: 주어진 확률을 표준화**\n\n$P(m - 2\\sigma \\leq X \\leq m + \\sigma)$를 구하기 위해 표준화한다.\n\n$$Z = \\frac{X-m}{\\sigma}$$\n\n- $X = m - 2\\sigma$일 때: $Z = \\frac{(m-2\\sigma)-m}{\\sigma} = -2$\n- $X = m + \\sigma$일 때: $Z = \\frac{(m+\\sigma)-m}{\\sigma} = 1$\n\n따라서:\n$$P(m - 2\\sigma \\leq X \\leq m + \\sigma) = P(-2 \\leq Z \\leq 1)$$\n\n**Step 2: 표준정규분포의 대칭성을 이용하여 분해**\n\n$$P(-2 \\leq Z \\leq 1) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1)$$\n\n표준정규분포는 $Z=0$을 중심으로 대칭이므로:\n$$P(-2 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 2)$$\n\n**Step 3: 주어진 값을 대입**\n\n$$P(-2 \\leq Z \\leq 1) = P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 1)$$\n$$= 0.4772 + 0.3413$$\n$$= 0.8185$$\n\n**Step 4: 최종 답 계산**\n\n소수점 넷째 자리에서 반올림하여 소수점 셋째 자리까지:\n$$0.8185 \\rightarrow 0.819$$ (넷째 자리 5이므로 올림)\n\n따라서:\n$$0.819 \\times 1000 = 819$$\n\n**[정답 확인]**\n\n$P(-2 \\leq Z \\leq 1) = P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 1) = 0.4772 + 0.3413 = 0.8185$를 반올림하여 1000을 곱한 결과가 819이다.\n\n**[오답 분석]**\n\n- **818**: 반올림을 0.8184로 잘못 계산하거나 절단한 경우\n- **820**: 0.8195로 계산하여 올림을 과다하게 한 경우\n- **817**: 계산 과정에서 0.4772 값을 잘못 사용한 경우\n\n**[핵심 포인트]**\n\n1. **표준화**: $X \\to Z = \\frac{X-m}{\\sigma}$로 변환하여 표준정규분포로 만들기\n2. **대칭성**: $P(-a \\leq Z \\leq 0) = P(0 \\leq Z \\leq a)$를 이용하여 음수 구간을 양수 구간으로 변환하기",
