    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n표본평균의 분포는 모집단이 정규분포를 따를 때, 표본평균 $\\bar{X}$도 정규분포를 따릅니다.\n- 모집단: $N(\\mu, \\sigma^2)$\n- 표본평균의 분포: $N\\left(\\mu, \\frac{\\sigma^2}{n}\\right)$\n\n표본평균을 표준화하면 표준정규분포 $N(0,1)$을 따르므로, 주어진 확률값을 이용하여 구간확률을 계산할 수 있다.\n\n**[풀이]**\n\n**1단계: 표본평균의 분포 구하기**\n\n모집단이 $N(60, 10^2)$을 따르고, 표본크기 $n=25$이므로:\n\n$$\\bar{X} \\sim N\\left(60, \\frac{10^2}{25}\\right) = N(60, 4)$$\n\n따라서 표본평균의 평균은 60, 표본평균의 표준편차는 $\\sqrt{4} = 2$이다.\n\n**2단계: 표준화하기**\n\n$\\bar{X}$를 표준화하면:\n\n$$Z = \\frac{\\bar{X} - 60}{2}$$\n\n구하는 확률 $P(\\bar{X} \\geq 64)$를 표준화하면:\n\n$$P(\\bar{X} \\geq 64) = P\\left(\\frac{\\bar{X} - 60}{2} \\geq \\frac{64-60}{2}\\right) = P(Z \\geq 2)$$\n\n**3단계: 표준정규분포표 이용하기**\n\n표준정규분포는 0을 중심으로 대칭이므로:\n\n$$P(Z \\geq 2) = P(Z \\leq -2) = 0.5 - P(-2 \\leq Z \\leq 0)$$\n\n$P(0 \\leq Z \\leq 2) = 0.4772$이 주어졌으므로, 대칭성에 의해:\n\n$$P(-2 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 2) = 0.4772$$\n\n따라서:\n\n$$P(Z \\geq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**[정답 확인]**\n\n표본평균의 표준화 후 표준정규분포표를 정확히 적용하면, $P(\\bar{X} \\geq 64) = 0.0228$이므로 ①번이 정답이다.\n\n**[오답 분석]**\n\n- ② 0.0456: $2 \\times 0.0228$로, 양쪽 꼬리 확률을 구한 경우 (한쪽만 구해야 함)\n- ③ 0.1587: $P(Z \\geq 1)$의 값으로, 표준화 과정에서 실수한 경우\n- ④ 0.3413: $P(0 \\leq Z \\leq 1)$의 값으로, $Z$값 계산 실수\n- ⑤ 0.4772: 주어진 확률값 자체로, 대칭성을 이용한 여사건 계산을 하지 않은 경우\n\n**[핵심 포인트]**\n\n1. 표본평균의 표준편차는 $\\frac{\\sigma}{\\sqrt{n}}$임을 반드시 기억\n2. 표준정규분포의 대칭성을 이용하여 $P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$로 계산",
