    "problem": "확률변수 $X$가 정규분포 $N(100, 15^2)$을 따를 때, $P(70 \\leq X \\leq 130) - P(85 \\leq X \\leq 115)$의 값을 구하시오. (소수 넷째 자리까지 구한 후, 10000을 곱하여 정수로 답하시오.) (단, $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$)",
