    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수는 표준화를 통해 표준정규분포로 변환할 수 있다. 표준화 공식은 $Z = \\frac{X - \\mu}{\\sigma}$이며, 표준정규분포의 대칭성을 이용하여 확률을 계산한다. 표준정규분포는 평균 0을 중심으로 대칭이므로 $P(-a \\leq Z \\leq a) = 2P(0 \\leq Z \\leq a)$이다.\n\n**[풀이]**\n\n주어진 조건: $X \\sim N(100, 15^2)$, 즉 $\\mu = 100$, $\\sigma = 15$\n\n**Step 1: $P(70 \\leq X \\leq 130)$ 계산**\n\n표준화:\n- $X = 70$일 때: $Z = \\frac{70-100}{15} = \\frac{-30}{15} = -2$\n- $X = 130$일 때: $Z = \\frac{130-100}{15} = \\frac{30}{15} = 2$\n\n따라서 $P(70 \\leq X \\leq 130) = P(-2 \\leq Z \\leq 2)$\n\n표준정규분포의 대칭성을 이용하면:\n$$P(-2 \\leq Z \\leq 2) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n$$= P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$$\n\n**Step 2: $P(85 \\leq X \\leq 115)$ 계산**\n\n표준화:\n- $X = 85$일 때: $Z = \\frac{85-100}{15} = \\frac{-15}{15} = -1$\n- $X = 115$일 때: $Z = \\frac{115-100}{15} = \\frac{15}{15} = 1$\n\n따라서 $P(85 \\leq X \\leq 115) = P(-1 \\leq Z \\leq 1)$\n\n표준정규분포의 대칭성을 이용하면:\n$$P(-1 \\leq Z \\leq 1) = P(-1 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1)$$\n$$= P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 1) = 2 \\times 0.3413 = 0.6826$$\n\n**Step 3: 두 확률의 차 계산**\n\n$$P(70 \\leq X \\leq 130) - P(85 \\leq X \\leq 115) = 0.9544 - 0.6826 = 0.2718$$\n\n**Step 4: 최종 답 계산**\n\n소수 넷째 자리까지 구한 후 10000을 곱하면:\n$$0.2718 \\times 10000 = 2718$$\n\n**[정답 확인]**\n\n표준화를 올바르게 수행하고, 표준정규분포의 대칭성을 이용하여 두 확률을 정확히 계산한 후 그 차를 구했으므로 정답이다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당사항 없음. 다만 계산 오류로 인한 오답이 발생할 수 있는 지점:\n- 표준화 계산 실수 (분자나 분모 계산 오류)\n- $2 \\times 0.4772 = 0.9544$ 또는 $2 \\times 0.3413 = 0.6826$ 계산 오류\n- 빼기 연산 오류: $0.9544 - 0.6826 = 0.2718$ 계산 실수\n- 10000을 곱하기 전에 반올림하는 오류\n\n**[핵심 포인트]**\n\n1. 정규분포 문제에서는 반드시 표준화($Z = \\frac{X-\\mu}{\\sigma}$)를 통해 표준정규분포로 변환해야 한다.\n2. 표준정규분포는 0을 중심으로 대칭이므로 $P(-a \\leq Z \\leq a) = 2P(0 \\leq Z \\leq a)$ 공식을 활용하여 계산을 단순화할 수 있다.",
