    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수의 일차결합은 다시 정규분포를 따른다. $X \\sim N(\\mu_1, \\sigma_1^2)$, $Y \\sim N(\\mu_2, \\sigma_2^2)$이고 $X$, $Y$가 독립일 때, $W = aX + bY$는 $N(a\\mu_1 + b\\mu_2, a^2\\sigma_1^2 + b^2\\sigma_2^2)$를 따른다. 이를 표준정규분포로 변환하여 주어진 표준정규분포표를 이용해 확률을 구한다.\n\n**[풀이]**\n\n**1단계: $W = X - Y$의 분포 구하기**\n\n$X \\sim N(10, 3^2)$, $Y \\sim N(5, 4^2)$이고 $X$, $Y$가 독립이므로:\n\n$$E(W) = E(X - Y) = E(X) - E(Y) = 10 - 5 = 5$$\n\n$$\\text{Var}(W) = \\text{Var}(X - Y) = \\text{Var}(X) + \\text{Var}(Y) = 3^2 + 4^2 = 9 + 16 = 25$$\n\n따라서 $W \\sim N(5, 25)$, 즉 $W \\sim N(5, 5^2)$\n\n**2단계: 표준화하기**\n\n표준정규분포로 변환하면:\n\n$$Z = \\frac{W - 5}{5}$$\n\n구하는 확률은:\n\n$$P(W \\geq 10) = P\\left(\\frac{W-5}{5} \\geq \\frac{10-5}{5}\\right) = P(Z \\geq 1)$$\n\n**3단계: 표준정규분포표 이용**\n\n표준정규분포는 $Z = 0$을 중심으로 대칭이므로:\n\n$$P(Z \\geq 0) = 0.5$$\n\n$$P(0 \\leq Z \\leq 1) = 0.3413$$ (주어진 조건)\n\n따라서:\n\n$$P(Z \\geq 1) = P(Z \\geq 0) - P(0 \\leq Z \\leq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**[정답 확인]**\n\n$W$의 표준편차는 5이고, $P(W \\geq 10) = P(Z \\geq 1) = 0.1587$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n\n- ① 0.0228: $P(Z \\geq 2)$의 값으로, 분산을 잘못 계산했을 때 나오는 답\n- ③ 0.3413: 주어진 조건값 자체로, 표준화 후 계산을 하지 않은 경우\n- ④ 0.5: $P(W \\geq 5)$의 값으로, 기댓값 이상의 확률을 구한 경우\n- ⑤ 0.8413: $P(Z \\leq 1) = 0.5 + 0.3413$로, $P(Z \\geq 1)$과 반대의 누적확률을 구한 경우\n\n**[핵심 포인트]**\n\n독립인 정규분포 확률변수의 차($X - Y$)의 분산은 **각 분산을 더한다**: $\\text{Var}(X-Y) = \\text{Var}(X) + \\text{Var}(Y)$. 표준화 후 주어진 표의 대칭성을 이용하여 $P(Z \\geq 1) = 0.5 - P(0 \\leq Z \\leq 1)$로 계산한다.",
