    "answer": 1,
    "explanation": "**[핵심 개념]**\n모집단에서 표본을 추출할 때, 표본평균의 분포는 중심극한정리를 따릅니다. 모집단이 정규분포를 따를 때, 표본평균 $\\bar{X}$도 정규분포를 따르며, 표본평균의 표준편차(표준오차)는 다음 공식으로 구한다:\n\n$$\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}$$\n\n여기서 $\\sigma$는 모표준편차, $n$은 표본의 크기이다.\n\n**[풀이]**\n주어진 조건을 정리하면:\n- 모표준편차: $\\sigma = 6$\n- 표본의 크기: $n = 36$\n- 구하는 값: 표본평균 $\\bar{X}$의 표준편차\n\n표본평균의 표준편차 공식에 주어진 값들을 대입한다:\n\n$$\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}} = \\frac{6}{\\sqrt{36}} = \\frac{6}{6} = 1$$\n\n따라서 표본평균의 표준편차는 $1$이다.\n\n**[정답 확인]**\n공식 $\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}$에 $\\sigma = 6$, $n = 36$을 대입하면 $\\frac{6}{6} = 1$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{2}$: $\\frac{6}{12}$로 계산한 경우 (분모를 잘못 계산)\n- ③ $\\frac{3}{2}$: $\\frac{6}{4}$로 계산한 경우 (분모를 $\\sqrt{36} = 6$이 아닌 다른 값으로 계산)\n- ④ $2$: $\\frac{6}{3}$으로 계산한 경우 ($\\sqrt{n}$을 $\\sqrt{36/4}$로 잘못 이해)\n- ⑤ $3$: $\\frac{\\sigma}{2}$로 계산한 경우 (표본크기를 고려하지 않음)\n\n**[핵심 포인트]**\n표본평균의 표준편차는 모표준편차를 표본크기의 제곱근으로 나눈 값이다. 표본의 크기가 커질수록 표본평균의 표준편차는 작아진다는 의미이다. 공식 $\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}}$을 반드시 암기하세요.",
