    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n정규모집단에서 표본평균의 분포는 다음과 같은 성질을 따릅니다.\n- 모집단이 $N(m, \\sigma^2)$를 따를 때, 표본평균 $\\bar{X}$의 분포는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n- 즉, 표본평균의 평균은 모평균과 같고, 표본평균의 분산은 모분산을 표본크기로 나눈 값이다.\n- 표본평균의 표준편차(표준오차)는 $\\frac{\\sigma}{\\sqrt{n}}$이다.\n\n**[풀이]**\n\n주어진 정보:\n- 모표준편차: $\\sigma = 8$\n- 표본크기: $n = 64$\n- 표본평균의 분포: $\\bar{X} \\sim N(m, a^2)$\n\n표본평균의 분포에서 분산을 구하면:\n\n$$\\text{Var}(\\bar{X}) = \\frac{\\sigma^2}{n} = \\frac{8^2}{64} = \\frac{64}{64} = 1$$\n\n따라서 표본평균의 표준편차는:\n\n$$a = \\sqrt{\\text{Var}(\\bar{X})} = \\sqrt{1} = 1$$\n\n즉, $\\bar{X} \\sim N(m, 1^2)$이므로 $a = 1$이다.\n\n**[정답 확인]**\n\n표본평균의 표준편차(표준오차) 공식 $\\frac{\\sigma}{\\sqrt{n}} = \\frac{8}{\\sqrt{64}} = \\frac{8}{8} = 1$을 적용하면 $a=1$이 맞다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{2}$: 표준편차를 구할 때 $\\sqrt{1} = 1$을 $\\frac{1}{2}$로 잘못 계산한 경우\n- ③ $2$: 표본크기를 $n=64$가 아닌 $n=16$으로 잘못 읽은 경우 ($\\frac{8}{\\sqrt{16}}=2$)\n- ④ $4$: 표본크기를 $n=4$로 잘못 읽은 경우 ($\\frac{8}{\\sqrt{4}}=4$)\n- ⑤ $8$: 모표준편차를 그대로 답으로 쓴 경우 (표본평균의 표준편차를 구하지 않음)\n\n**[핵심 포인트]**\n\n표본평균의 표준편차는 모표준편차를 $\\sqrt{n}$으로 나눈 값이다. 공식 $a = \\frac{\\sigma}{\\sqrt{n}}$을 정확히 적용하는 것이 중요하다.",
