    "problem": "정규분포 $N(m, 4^2)$을 따르는 모집단에서 크기 64인 표본을 임의추출하여 구한 표본평균이 25일 때, 모평균 $m$에 대한 신뢰도 95%의 신뢰구간은? (단, $P(|Z| \\leq 1.96) = 0.95$)",
