    "answer": 0,
    "explanation": "**[핵심 개념]**\n모평균에 대한 신뢰구간은 표본평균을 중심으로 오차한계만큼 위아래로 설정한다. \n- 모집단이 정규분포 $N(m, \\sigma^2)$를 따를 때, 표본평균 $\\bar{X}$의 분포는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n- 신뢰도 $95\\%$에서 신뢰구간: $\\bar{X} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 4^2)$ → 모표준편차 $\\sigma = 4$\n- 표본크기: $n = 64$\n- 표본평균: $\\bar{X} = 25$\n- 신뢰도: $95\\%$ → $P(|Z| \\leq 1.96) = 0.95$에서 $z_{\\alpha/2} = 1.96$\n\n**2단계: 표본평균의 표준편차 계산**\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{4}{\\sqrt{64}} = \\frac{4}{8} = 0.5$$\n\n**3단계: 오차한계 계산**\n$$E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\times 0.5 = 0.98$$\n\n**4단계: 신뢰구간 계산**\n$$\\bar{X} - E \\leq m \\leq \\bar{X} + E$$\n$$25 - 0.98 \\leq m \\leq 25 + 0.98$$\n$$24.02 \\leq m \\leq 25.98$$\n\n**[정답 확인]**\n계산된 신뢰구간 $24.02 \\leq m \\leq 25.98$이 선택지 ①과 정확히 일치한다.\n\n**[오답 분석]**\n- ② $24.51 \\leq m \\leq 25.49$: 오차한계를 0.49로 계산 (잘못된 값)\n- ③ $23.04 \\leq m \\leq 26.96$: $z_{\\alpha/2} = 1.96$을 $\\frac{\\sigma}{\\sqrt{n}}$에 곱하지 않고 $\\sigma$ 전체에 곱함\n- ④ $24.00 \\leq m \\leq 26.00$: 오차한계를 1.0으로 계산 (근사값, 1.96 × 0.5 = 0.98을 1로 잘못 반올림)\n- ⑤ $23.50 \\leq m \\leq 26.50$: 오차한계를 1.5로 계산 (잘못된 값)\n\n**[핵심 포인트]**\n표본평균의 표준오차는 $\\frac{\\sigma}{\\sqrt{n}}$이며, 신뢰구간의 오차한계는 **$z_{\\alpha/2}$에 표준오차를 곱한 값**이다. 표준편차 $\\sigma$를 직접 사용하지 않도록 주의하세요.",
