    "answer": 2,
    "explanation": "**[핵심 개념]**\n정규모집단에서 모표준편차 $\\sigma$를 알고 있을 때, 표본평균의 신뢰구간은 다음과 같이 구성된다.\n- 표본평균을 $\\bar{x}$, 표본크기를 $n$이라 할 때\n- 신뢰도 95%의 신뢰구간: $\\bar{x} \\pm 1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$\n- 이때 $1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$을 오차한계(margin of error)라 한다.\n\n**[풀이]**\n\n**Step 1: 신뢰구간 정보 정리**\n- 신뢰구간: $[18.04, 21.96]$\n- 표본크기: $n = 100$\n- 신뢰도: 95% (임계값 $z_{\\alpha/2} = 1.96$)\n\n**Step 2: 표본평균 구하기**\n신뢰구간의 중심은 표본평균이다.\n$$\\bar{x} = \\frac{18.04 + 21.96}{2} = \\frac{40}{2} = 20$$\n\n**Step 3: 오차한계 구하기**\n신뢰구간의 좌측 끝은 $\\bar{x} - 1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$이므로:\n$$18.04 = 20 - 1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$$\n\n또는 우측 끝은 $\\bar{x} + 1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$이므로:\n$$21.96 = 20 + 1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$$\n\n**Step 4: 오차한계로부터 $\\sigma$ 구하기**\n우측 끝 식을 이용하면:\n$$1.96 \\times \\frac{\\sigma}{\\sqrt{n}} = 21.96 - 20 = 1.96$$\n\n$$1.96 \\times \\frac{\\sigma}{\\sqrt{100}} = 1.96$$\n\n$$\\frac{\\sigma}{10} = 1$$\n\n$$\\sigma = 10$$\n\n**[정답 확인]**\n$\\sigma = 10$을 대입하면 신뢰구간이 $20 \\pm 1.96 \\times \\frac{10}{10} = 20 \\pm 1.96 = [18.04, 21.96]$으로 정확히 일치한다.\n\n**[오답 분석]**\n- ① $\\sigma = 5$: 신뢰구간이 $[19.02, 20.98]$이 되어 너무 좁음\n- ② $\\sigma = 8$: 신뢰구간이 $[18.432, 21.568]$이 되어 맞지 않음\n- ④ $\\sigma = 12$: 신뢰구간이 $[17.648, 22.352]$이 되어 너무 넓음\n- ⑤ $\\sigma = 15$: 신뢰구간이 $[17.06, 22.94]$이 되어 너무 넓음\n\n**[핵심 포인트]**\n신뢰구간의 폭(우측 끝 - 좌측 끝) = $2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{n}}$이므로, 폭이 $21.96 - 18.04 = 3.92$임을 직접 이용하면 더 빠르게 풀 수 있다: $3.92 = 2 \\times 1.96 \\times \\frac{\\sigma}{10}$에서 $\\sigma = 10$.",
