    "explanation": "**[핵심 개념]**\n정규분포를 따르는 모집단에서 모표준편차 $\\sigma$를 알고 있을 때, 표본평균을 이용한 모평균의 신뢰구간은 $$\\bar{X} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n여기서 신뢰구간의 **길이** = $2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 이다.\n\n신뢰도 95%일 때 $P(|Z| \\leq 1.96) = 0.95$이므로 $z_{\\alpha/2} = 1.96$이다.\n\n**[풀이]**\n\n**1단계: 신뢰구간의 길이 공식 설정**\n\n신뢰구간의 길이를 $L$이라 하면:\n$$L = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 1.96 \\times \\frac{10}{\\sqrt{n}}$$\n\n**2단계: 주어진 조건 적용**\n\n신뢰구간의 길이가 4 이하여야 하므로:\n$$2 \\times 1.96 \\times \\frac{10}{\\sqrt{n}} \\leq 4$$\n\n**3단계: 부등식 정리**\n\n$$\\frac{2 \\times 1.96 \\times 10}{\\sqrt{n}} \\leq 4$$\n\n$$\\frac{39.2}{\\sqrt{n}} \\leq 4$$\n\n$$39.2 \\leq 4\\sqrt{n}$$\n\n$$\\sqrt{n} \\geq \\frac{39.2}{4} = 9.8$$\n\n**4단계: $n$의 범위 구하기**\n\n$$n \\geq (9.8)^2 = 96.04$$\n\n$n$은 자연수이므로 $n \\geq 97$\n\n따라서 표본의 크기 $n$의 최솟값은 **97**이다.\n\n**[정답 확인]**\n\n$n = 97$일 때 신뢰구간의 길이는 $2 \\times 1.96 \\times \\frac{10}{\\sqrt{97}} \\approx 3.98 < 4$ ✓\n$n = 96$일 때 신뢰구간의 길이는 $2 \\times 1.96 \\times \\frac{10}{\\sqrt{96}} \\approx 4.00 > 4$ (조건 불만족)\n\n**[오답 분석]**\n\n- **96**: 계산 과정에서 $(9.8)^2 = 96$으로 잘못 계산하거나, 부등호 방향을 착각하면 나오는 답이다. 실제로 $n=96$은 조건을 만족하지 않는다.\n\n- **98, 100** 등: 계산 실수나 올림을 과하게 하는 경우 나올 수 있으나, **최솟값**을 구하는 문제이므로 부적절한다.\n\n**[핵심 포인트]**\n\n1. 신뢰구간의 길이 = $2 \\times z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$ 공식을 정확히 적용하세요.\n2. 길이 조건($\\leq 4$)에서 부등호를 풀어 $\\sqrt{n} \\geq 9.8$을 얻으면 $n \\geq 96.04$이고, **최솟값은 97**이다.",
