    "type": "통계적 추정",
    "problem": "모표준편차가 $12$인 정규모집단에서 크기 $n = 144$인 표본을 추출하여 표본평균 $\\bar{x} = 80$을 얻었다. 모평균 $m$에 대한 신뢰도 99%의 신뢰구간의 길이를 구하시오. (소수 둘째 자리까지 구한 후 100을 곱하여 정수로 답하시오.) (단, $P(|Z| \\leq 2.58) = 0.99$)",
    "answerType": "short",
    "choices": null,
    "answer": 516,
    "explanation": "**[핵심 개념]**\n\n정규모집단에서 모표준편차를 알 때, 모평균에 대한 신뢰구간은 표준정규분포를 이용한다.\n\n신뢰도 $1-\\alpha$에서 모평균 $m$의 신뢰구간은:\n$$\\bar{x} - z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{x} + z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n신뢰구간의 길이는 양쪽 끝점 사이의 거리이므로:\n$$\\text{신뢰구간의 길이} = 2 \\cdot z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- 모표준편차: $\\sigma = 12$\n- 표본크기: $n = 144$\n- 표본평균: $\\bar{x} = 80$\n- 신뢰도: $99\\%$ → $P(|Z| \\leq 2.58) = 0.99$\n- 따라서 $z_{\\alpha/2} = 2.58$\n\n**Step 2: 표준오차 계산**\n\n표준오차는 $\\frac{\\sigma}{\\sqrt{n}}$이므로:\n\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{12}{\\sqrt{144}} = \\frac{12}{12} = 1$$\n\n**Step 3: 오차한계 계산**\n\n오차한계(margin of error)는:\n$$E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2.58 \\times 1 = 2.58$$\n\n**Step 4: 신뢰구간의 길이 계산**\n\n신뢰구간의 길이는:\n$$\\text{길이} = 2 \\times E = 2 \\times 2.58 = 5.16$$\n\n**Step 5: 최종 답 계산**\n\n문제에서 \"소수 둘째 자리까지 구한 후 100을 곱하여 정수로 답하시오\"라고 했으므로:\n\n$$5.16 \\times 100 = 516$$\n\n**[정답 확인]**\n\n신뢰도 99%에서 신뢰구간의 길이는 $2 \\times 2.58 \\times 1 = 5.16$이고, 이를 100배하면 **516**이다.\n\n**[오답 분석]**\n\n- **258**: 오차한계 $E = 2.58$을 100배한 경우 (신뢰구간 길이가 아님)\n- **1032**: 신뢰구간 길이 $5.16$을 200배한 경우 (문제 지시사항 오류)\n- **2.58**: 오차한계를 그대로 답한 경우 (100배를 하지 않음)\n\n**[핵심 포인트]**\n\n1. **신뢰구간의 길이는 $2 \\times z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$** (양쪽 끝점까지의 거리)\n\n2. **표본크기가 충분할 때 ($n=144$) 표준오차를 정확히 계산하는 것이 중요** - 이 문제에서는 $\\sqrt{144} = 12$로 깔끔하게 계산됨",
