    "problem": "모표준편차가 $\\sigma$인 정규모집단에서 크기 $n$인 표본을 추출하여 신뢰도 95%로 모평균을 추정한다. 표본의 크기를 4배로 늘리면, 신뢰구간의 길이는 원래의 몇 배가 되는가?",
