    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n정규모집단에서 모평균을 추정할 때 신뢰구간은 다음과 같이 구성된다.\n\n신뢰도 95%일 때 신뢰구간: $\\bar{x} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n여기서 $z_{\\alpha/2}$는 신뢰도에 따라 결정되는 상수(95%일 때 약 1.96)이고, **신뢰구간의 길이** = $2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 이다.\n\n**[풀이]**\n\n**1단계: 원래 신뢰구간의 길이 계산**\n\n표본 크기가 $n$일 때:\n$$L_1 = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**2단계: 표본 크기를 4배로 늘린 후 신뢰구간의 길이 계산**\n\n표본 크기가 $4n$일 때:\n$$L_2 = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{4n}}$$\n\n**3단계: 신뢰구간의 길이 변화 계산**\n\n$$L_2 = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{4n}} = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{2\\sqrt{n}}$$\n\n$$L_2 = \\frac{1}{2} \\times 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} = \\frac{1}{2} L_1$$\n\n따라서 신뢰구간의 길이는 원래의 $\\frac{1}{2}$배가 된다.\n\n**[정답 확인]**\n\n신뢰구간의 길이는 $\\frac{\\sigma}{\\sqrt{n}}$에 비례하므로, 표본 크기가 4배 증가하면 분모가 2배 증가하여 신뢰구간의 길이는 $\\frac{1}{2}$배가 된다.\n\n**[오답 분석]**\n\n- **① $\\frac{1}{4}$배**: 표본 크기를 4배로 늘렸을 때 신뢰구간도 4배 줄어든다고 착각한 오류\n- **③ 1배 (변하지 않음)**: 신뢰도는 변하지 않았지만, 표본 크기 변화는 신뢰구간의 길이에 영향을 준다\n- **④ 2배, ⑤ 4배**: 표본 크기 증가의 방향을 반대로 생각한 오류 (신뢰구간이 커지는 경우는 표본 크기가 감소할 때)\n\n**[핵심 포인트]**\n\n신뢰구간의 길이는 $\\sqrt{n}$에 반비례한다. 즉, 표본 크기를 $k^2$배로 늘리면 신뢰구간의 길이는 $\\frac{1}{k}$배가 된다.",
