    "_type": "killer",
    "type": "복합 킬러",
    "problem": "1부터 6까지의 자연수가 하나씩 적힌 6장의 카드에서 3장을 동시에 뽑아 세 수의 합이 짝수인 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[핵심 개념]**\n세 수의 합이 짝수가 되려면 다음 두 경우 중 하나여야 한다.\n- 세 수가 모두 짝수 (짝수 + 짝수 + 짝수 = 짝수)\n- 짝수 1개, 홀수 2개 (짝수 + 홀수 + 홀수 = 짝수)\n\n주어진 카드: 1, 2, 3, 4, 5, 6\n- 홀수: 1, 3, 5 (3개)\n- 짝수: 2, 4, 6 (3개)\n\n**[풀이]**\n\n**경우 1: 짝수 3개를 모두 선택하는 경우**\n\n짝수 카드 3개(2, 4, 6)에서 3개를 모두 뽑는 경우:\n$$\\binom{3}{3} = 1$$\n\n(2, 4, 6)의 합 = 12 (짝수) ✓\n\n**경우 2: 짝수 1개, 홀수 2개를 선택하는 경우**\n\n짝수 3개 중에서 1개를 선택: $\\binom{3}{1} = 3$\n\n홀수 3개 중에서 2개를 선택: $\\binom{3}{2} = 3$\n\n이 경우의 수:\n$$\\binom{3}{1} \\times \\binom{3}{2} = 3 \\times 3 = 9$$\n\n구체적인 예:\n- 짝수 2 선택: (2, 1, 3), (2, 1, 5), (2, 3, 5) → 3가지\n- 짝수 4 선택: (4, 1, 3), (4, 1, 5), (4, 3, 5) → 3가지\n- 짝수 6 선택: (6, 1, 3), (6, 1, 5), (6, 3, 5) → 3가지\n\n**전체 경우의 수**\n$$1 + 9 = 10$$\n\n**[정답 확인]**\n세 수의 합이 짝수인 경우는 (짝수 3개 모두) 또는 (짝수 1개 + 홀수 2개)이므로, $1 + 9 = 10$가지이다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오류 가능성:\n- 홀수 3개만 세는 경우: $\\binom{3}{3} = 1$ → 틀림 (홀수는 합이 홀수)\n- 전체 경우의 수만 구하는 경우: $\\binom{6}{3} = 20$ → 틀림 (조건을 무시함)\n- 경우 2에서 곱셈을 잘못하는 경우: $3 + 3 = 6$ → 틀림 (조합은 곱하기)\n\n**[핵심 포인트]**\n1. 합의 홀짝성 판정: 짝수와 홀수의 개수로 판정 (홀수가 짝수 개면 합은 짝수)\n2. 조합 문제에서 여러 경우를 나눌 때는 경우의 수를 모두 더함 (덧셈 원리)",
