    "explanation": "**[핵심 개념]**\n조합을 이용한 확률 계산 문제이다. 전체 경우의 수에서 구하려는 사건의 경우의 수를 구한 후, 확률 = (사건의 경우의 수)/(전체 경우의 수) 공식을 적용한다. \"적어도\"라는 표현은 여사건을 이용하는 것이 효율적일 수 있다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n\n흰 공 5개, 검은 공 3개(총 8개)에서 3개를 동시에 꺼내는 경우의 수:\n$$\\binom{8}{3} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$$\n\n**Step 2: \"흰 공이 적어도 2개\" 경우의 수 계산**\n\n\"적어도 2개\"는 \"정확히 2개\" 또는 \"정확히 3개\"를 의미한다.\n\n**경우 1) 흰 공 정확히 2개, 검은 공 1개:**\n$$\\binom{5}{2} \\times \\binom{3}{1} = 10 \\times 3 = 30$$\n\n**경우 2) 흰 공 정확히 3개, 검은 공 0개:**\n$$\\binom{5}{3} \\times \\binom{3}{0} = 10 \\times 1 = 10$$\n\n**Step 3: 유리한 경우의 수 합계**\n\n$$30 + 10 = 40$$\n\n**Step 4: 확률 계산**\n\n$$P(\\text{흰 공 적어도 2개}) = \\frac{40}{56} = \\frac{5}{7}$$\n\n**[정답 확인]**\n흰 공이 적어도 2개 포함될 경우의 수는 40가지이고, 전체 경우의 수는 56가지이므로 확률은 $\\frac{40}{56} = \\frac{5}{7}$이다.\n\n**[오답 분석]**\n- ① $\\frac{13}{28}$: 흰 공이 정확히 2개인 경우만 계산($\\frac{30}{56} = \\frac{15}{28}$)했을 때의 오답\n- ② $\\frac{15}{28}$: 흰 공이 정확히 2개인 경우만 계산한 경우\n- ④ $\\frac{23}{28}$: 흰 공이 1개 이상인 경우로 잘못 계산한 경우\n- ⑤ $\\frac{25}{28}$: 계산 실수로 인한 오답\n\n**[핵심 포인트]**\n1. \"적어도 2개\" = \"2개 또는 3개\"이므로 두 경우를 모두 더해야 한다.\n2. 조합 계산 시 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$을 정확히 적용하고, 최종 답을 기약분수로 나타내야 한다.",
