    "type": "복합 킬러",
    "problem": "확률변수 $X$가 이항분포 $B(n, p)$를 따르고 $E(X) = 6$, $V(X) = 2$일 때, $n + p$의 값을 구하시오. (답을 3배 하여 정수로 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 29,
    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 기댓값과 분산은 - 기댓값: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n이 두 식을 이용하여 $n$과 $p$를 구한다.\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- $E(X) = 6$\n- $V(X) = 2$\n\n**1단계: 기댓값 식 세우기**\n$$E(X) = np = 6 \\cdots (1)$$\n\n**2단계: 분산 식 세우기**\n$$V(X) = np(1-p) = 2 \\cdots (2)$$\n\n**3단계: $p$ 구하기**\n식 (2)를 식 (1)로 나누면:\n$$\\frac{np(1-p)}{np} = \\frac{2}{6}$$\n\n$$1-p = \\frac{1}{3}$$\n\n$$p = \\frac{2}{3}$$\n\n**4단계: $n$ 구하기**\n식 (1)에 $p = \\frac{2}{3}$를 대입:\n$$n \\cdot \\frac{2}{3} = 6$$\n\n$$n = 9$$\n\n**5단계: $n + p$ 계산**\n$$n + p = 9 + \\frac{2}{3} = \\frac{27 + 2}{3} = \\frac{29}{3}$$\n\n**6단계: 최종 답 계산**\n문제에서 \"$n + p$의 값을 3배 하여 정수로 답하시오\"라고 했으므로:\n$$3(n + p) = 3 \\times \\frac{29}{3} = 29$$\n\n**[정답 확인]**\n$n = 9, p = \\frac{2}{3}$일 때, $E(X) = 9 \\times \\frac{2}{3} = 6$ ✓, $V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = 2$ ✓ 이므로 모든 조건을 만족한다.\n\n**[오답 분석]**\n객관식 선지가 제시되지 않아 일반적인 실수를 언급하면:\n- $p = \\frac{1}{3}$로 계산한 경우: $n+p = 9 + \\frac{1}{3} = \\frac{28}{3}$이므로 3배하면 28\n- $n$과 $p$를 구하지 않고 단순히 $E(X) + V(X) = 8$을 3배한 경우: 24\n- 분산 공식을 $V(X) = np$로 잘못 사용한 경우: 다른 오답 도출\n\n**[핵심 포인트]**\n이항분포에서 기댓값과 분산의 관계식 $V(X) = np(1-p) = E(X)(1-p)$를 이용하면 두 미지수 $n, p$를 동시에 구한다. 분산을 기댓값으로 나누어 $p$를 먼저 구하는 것이 효율적이다.",
