    "_type": "killer",
    "type": "복합 킬러",
    "problem": "주사위 2개를 동시에 던져 나온 두 눈의 수를 각각 $a$, $b$라 할 때, $a + b \\leq 5$일 확률과 $ab$가 짝수일 확률의 합을 구하시오. (기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 37,
    "explanation": "**[핵심 개념]**\n확률의 덧셈법칙과 여집합을 이용한 확률 계산이 필요하다. 두 사건 $A$, $B$에 대해 $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$이고, 여집합의 확률은 $P(A^c) = 1 - P(A)$이다. 주사위 2개를 동시에 던질 때 전체 경우의 수는 $6 \\times 6 = 36$이다.\n\n**[풀이]**\n\n**1단계: $a + b \\leq 5$일 확률 구하기**\n\n$a + b \\leq 5$를 만족하는 경우를 나열한다.\n- $a + b = 2$: $(1,1)$ → 1가지\n- $a + b = 3$: $(1,2), (2,1)$ → 2가지\n- $a + b = 4$: $(1,3), (2,2), (3,1)$ → 3가지\n- $a + b = 5$: $(1,4), (2,3), (3,2), (4,1)$ → 4가지\n\n따라서 $a + b \\leq 5$인 경우의 수는 $1 + 2 + 3 + 4 = 10$가지\n\n$$P(a + b \\leq 5) = \\frac{10}{36} = \\frac{5}{18}$$\n\n**2단계: $ab$가 짝수일 확률 구하기**\n\n$ab$가 짝수인 경우는 $a$ 또는 $b$ 중 적어도 하나가 짝수인 경우이다.\n\n여집합을 이용하면, $ab$가 홀수인 경우는 $a$와 $b$가 모두 홀수인 경우이다.\n\n홀수: $1, 3, 5$ (각 3개)\n- $a$가 홀수이고 $b$가 홀수: $3 \\times 3 = 9$가지\n\n따라서 $ab$가 홀수인 경우의 수는 9가지\n\n$$P(ab \\text{가 홀수}) = \\frac{9}{36} = \\frac{1}{4}$$\n\n$$P(ab \\text{가 짝수}) = 1 - \\frac{1}{4} = \\frac{3}{4}$$\n\n**3단계: 두 확률의 합 구하기**\n\n$$P(a + b \\leq 5) + P(ab \\text{가 짝수}) = \\frac{5}{18} + \\frac{3}{4}$$\n\n분모를 통일한다. $\\text{lcm}(18, 4) = 36$\n\n$$\\frac{5}{18} + \\frac{3}{4} = \\frac{10}{36} + \\frac{27}{36} = \\frac{37}{36}$$\n\n기약분수이므로 분자는 **37**이다.\n\n**[정답 확인]**\n$\\frac{37}{36}$은 기약분수이고, 분자는 37이다. 두 확률의 합이 1을 초과하는 것은 두 사건이 독립적이지 않기 때문에 자연스럽다.\n\n**[오답 분석]**\n- 만약 $ab$가 짝수일 확률을 직접 계산했다면 계산 오류 가능\n- 확률의 합을 구할 때 통분하지 않으면 오답 발생\n- $a + b \\leq 5$인 경우를 세는 과정에서 빠뜨린 경우가 있으면 오답\n\n**[핵심 포인트]**\n1. 여집합을 이용한 확률 계산($ab$가 짝수 = 여집합의 홀수)이 효율적이다.\n2. 두 확률을 더할 때는 반드시 통분하여 정확한 답을 구해야 한다.",
