    "type": "복합 킬러",
    "problem": "정규분포 $N(50, 10^2)$을 따르는 모집단에서 크기 25인 표본을 추출하여 표본평균 $\\bar{x}$를 구했다. 모평균 $m$에 대한 95% 신뢰구간에 $m = 47$이 포함되려면 $\\bar{x}$의 범위를 구하시오. 이때 $\\bar{x}$가 취할 수 있는 구간의 길이를 구하시오. (소수 둘째 자리까지 구한 후, 100을 곱하여 정수로 답하시오.) (단, $P(|Z| \\leq 1.96) = 0.95$)",
    "answerType": "short",
    "choices": null,
    "answer": 784,
    "explanation": "**[핵심 개념]**\n표본평균의 신뢰구간 문제이다. 모집단이 정규분포 $N(\\mu, \\sigma^2)$를 따를 때, 표본평균 $\\bar{x}$는 $N(\\mu, \\frac{\\sigma^2}{n})$를 따릅니다. 신뢰도 95%인 신뢰구간은 $\\bar{x} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 형태이며, 주어진 조건에서 역으로 $\\bar{x}$의 범위를 구하는 것이 핵심이다.\n\n**[풀이]**\n\n**1단계: 표본평균의 표본분포 구하기**\n\n모집단: $N(50, 10^2)$, 표본크기: $n=25$\n\n표본평균 $\\bar{x}$는 다음을 따릅니다:\n$$\\bar{x} \\sim N\\left(50, \\frac{10^2}{25}\\right) = N(50, 4)$$\n\n따라서 표본평균의 표준편차: $\\sigma_{\\bar{x}} = \\frac{10}{\\sqrt{25}} = \\frac{10}{5} = 2$\n\n**2단계: 신뢰구간 공식 설정**\n\n모평균 $m$에 대한 95% 신뢰구간은:\n$$\\bar{x} - 1.96 \\cdot \\sigma_{\\bar{x}} \\leq m \\leq \\bar{x} + 1.96 \\cdot \\sigma_{\\bar{x}}$$\n\n$$\\bar{x} - 1.96 \\times 2 \\leq m \\leq \\bar{x} + 1.96 \\times 2$$\n\n$$\\bar{x} - 3.92 \\leq m \\leq \\bar{x} + 3.92$$\n\n**3단계: $m=47$이 신뢰구간에 포함되는 조건**\n\n$m = 47$이 위 신뢰구간에 포함되려면:\n$$\\bar{x} - 3.92 \\leq 47 \\leq \\bar{x} + 3.92$$\n\n좌측 부등식에서: $\\bar{x} - 3.92 \\leq 47$ → $\\bar{x} \\leq 50.92$\n\n우측 부등식에서: $47 \\leq \\bar{x} + 3.92$ → $43.08 \\leq \\bar{x}$\n\n따라서: $43.08 \\leq \\bar{x} \\leq 50.92$\n\n**4단계: 구간의 길이 계산**\n\n$$\\text{구간의 길이} = 50.92 - 43.08 = 7.84$$\n\n**5단계: 최종 답 계산**\n\n문제에서 요구한 대로 100을 곱하면:\n$$7.84 \\times 100 = 784$$\n\n**[정답 확인]**\n$\\bar{x}$의 95% 신뢰구간이 정확히 $m=47$을 포함하는 범위는 $43.08 \\leq \\bar{x} \\leq 50.92$이며, 이 구간의 길이는 7.84이고 100을 곱하면 784이다.\n\n**[오답 분석]**\n- **792**: 구간의 길이를 계산할 때 $1.96 \\times 2 \\times 2 = 7.84$에서 실수로 다른 계수를 사용한 경우\n- **800**: 반올림 오류로 7.84를 8으로 처리한 경우\n- **760**: 계산 과정에서 표준편차를 잘못 적용한 경우\n\n**[핵심 포인트]**\n신뢰구간 문제에서 \"신뢰구간에 특정 값이 포함된다\"는 것은 그 값이 부등식을 만족한다는 의미이다. 역으로 주어진 모평균 값으로부터 표본평균의 범위를 구할 때는 부등식의 방향을 정확히 유지해야 한다.",
