    "problem": "A, B 두 사람이 각각 주사위를 한 번씩 던진다. A가 나온 눈의 수만큼 점수를 얻고, B도 나온 눈의 수만큼 점수를 얻는다. A의 점수가 B의 점수보다 높을 확률을 구하시오. (기약분수의 분모를 답하시오.)",
