    "choices": null,
    "answer": 12,
    "explanation": "**[핵심 개념]**\n\n두 개의 독립적인 사건에서 특정 조건을 만족하는 경우의 수를 구하는 문제이다. 전체 경우의 수는 $6 \\times 6 = 36$이고, A의 점수가 B의 점수보다 높은 경우를 모두 세어야 한다. 확률은 (유리한 경우의 수)/(전체 경우의 수)로 구한다.\n\n**[풀이]**\n\nA가 던진 주사위의 눈을 $a$, B가 던진 주사위의 눈을 $b$라고 한다. ($a, b \\in \\{1,2,3,4,5,6\\}$)\n\n우리가 구하는 것은 $P(a > b)$이다.\n\n각 경우를 $a$의 값에 따라 정리하면:\n\n- $a = 1$일 때: $b < 1$인 경우는 없음 → 0가지\n- $a = 2$일 때: $b \\in \\{1\\}$ → 1가지\n- $a = 3$일 때: $b \\in \\{1, 2\\}$ → 2가지\n- $a = 4$일 때: $b \\in \\{1, 2, 3\\}$ → 3가지\n- $a = 5$일 때: $b \\in \\{1, 2, 3, 4\\}$ → 4가지\n- $a = 6$일 때: $b \\in \\{1, 2, 3, 4, 5\\}$ → 5가지\n\nA가 B보다 높은 경우의 수는:\n$$0 + 1 + 2 + 3 + 4 + 5 = 15$$\n\n따라서 구하는 확률은:\n$$P(a > b) = \\frac{15}{36} = \\frac{5}{12}$$\n\n기약분수로 나타낼 때 분모는 **12**이다.\n\n**[정답 확인]**\n\n$\\gcd(5, 12) = 1$이므로 $\\frac{5}{12}$는 기약분수이며, 분모는 12이다.\n\n**[오답 분석]**\n\n객관식이 아닌 단답형이므로 해당사항 없다.\n\n**[핵심 포인트]**\n\n두 사람의 주사위 결과가 같을 수도 있으므로, A > B인 경우만 세면 된다. 대칭성을 이용하면 P(a > b) = P(b > a)이고, P(a > b) + P(a = b) + P(b > a) = 1이라는 검증도 가능한다.",
    "difficulty": "lv4",
