    "problem": "서로 다른 7개의 색연필 중 3개를 선택하여 일렬로 나열하는 경우의 수를 구하시오.",
    "answerType": "choice",
    "choices": [
      "① 35",
      "② 120",
      "③ 210",
      "④ 240",
      "⑤ 5040"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 순열(Permutation) 문제이다. 순열은 서로 다른 n개의 대상 중에서 r개를 선택하여 순서를 고려하여 나열하는 경우의 수를 구하는 것이다. 순열의 공식은 $P(n,r) = \\frac{n!}{(n-r)!} = n \\times (n-1) \\times (n-2) \\times \\cdots \\times (n-r+1)$ 이다.\n\n**[풀이]**\n이 문제는 7개의 서로 다른 색연필 중에서 3개를 선택하여 일렬로 나열하는 것이므로, 순서가 중요하다.\n\n**단계 1: 상황 파악**\n- 전체 색연필의 개수: $n = 7$\n- 선택하여 나열할 색연필의 개수: $r = 3$\n- 구하는 것: 순열 $P(7, 3)$\n\n**단계 2: 순열 공식 적용**\n$$P(7, 3) = \\frac{7!}{(7-3)!} = \\frac{7!}{4!}$$\n\n**단계 3: 계산**\n$$P(7, 3) = 7 \\times 6 \\times 5 = 210$$\n\n이는 다음과 같이 이해할 수 있다:\n- 첫 번째 자리에 올 색연필: 7개 중 선택 → 7가지\n- 두 번째 자리에 올 색연필: 남은 6개 중 선택 → 6가지\n- 세 번째 자리에 올 색연필: 남은 5개 중 선택 → 5가지\n\n따라서 $7 \\times 6 \\times 5 = 210$\n\n**[정답 확인]**\n순열 $P(7,3) = 7 \\times 6 \\times 5 = 210$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n- ① 35: $C(7,3) = \\frac{7!}{3!4!} = 35$ (조합으로 계산한 경우 - 순서를 무시한 실수)\n- ② 120: $P(10,3) = 10 \\times 6 \\times 2$나 다른 잘못된 계산 결과\n- ④ 240: $7 \\times 6 \\times 5 + 30$ 등 계산 오류\n- ⑤ 5040: $7! = 5040$ (7개 모두를 나열하는 경우 - 3개만 선택한다는 조건을 무시한 실수)\n\n**[핵심 포인트]**\n- **순열 vs 조합**: \"나열한다\", \"배열한다\", \"순서를 고려한다\" → 순열 | \"선택한다\" 만 해서는 순서가 없으면 → 조합\n- **순열 계산**: $P(n,r) = n \\times (n-1) \\times (n-2) \\times \\cdots$ (r개 곱하기)",
    "difficulty": "lv1",
    "_qid": "R-0081",
    "_reviewed": true,
    "_source": "original"
