    "answer": 72,
    "explanation": "**[핵심 개념]**\n순열(Permutation)은 서로 다른 n개의 원소 중에서 r개를 순서를 고려하여 선택하는 경우의 수이다. 순열의 기호는 $_nP_r$이며, 공식은 $$_nP_r = \\frac{n!}{(n-r)!} = n \\times (n-1) \\times (n-2) \\times \\cdots \\times (n-r+1)$$\n\n이는 첫 번째 자리에 n개, 두 번째 자리에 (n-1)개, ..., r번째 자리에 (n-r+1)개를 배치하는 것과 같다.\n\n**[풀이]**\n$_9P_2$는 9개의 서로 다른 원소 중에서 2개를 순서를 고려하여 선택하는 경우의 수이다.\n\n공식을 이용하면:\n$$_9P_2 = \\frac{9!}{(9-2)!} = \\frac{9!}{7!}$$\n\n분자와 분모를 정리하면:\n$$_9P_2 = \\frac{9 \\times 8 \\times 7!}{7!} = 9 \\times 8 = 72$$\n\n또는 직관적으로:\n- 첫 번째 자리: 9개 중 선택 → 9가지\n- 두 번째 자리: 남은 8개 중 선택 → 8가지\n- 총 경우의 수: $9 \\times 8 = 72$\n\n**[정답 확인]**\n공식과 계산 모두 $9 \\times 8 = 72$를 만족하므로 정답이다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오답 사례:\n- $9 + 8 = 17$: 순열이 아닌 덧셈으로 잘못 계산\n- $\\frac{9!}{2!} = 181,440$: 조합($C$)과 순열($P$)을 혼동\n- $9 \\times 2 = 18$: 순열의 의미를 잘못 이해\n\n**[핵심 포인트]**\n$_nP_r = n \\times (n-1) \\times (n-2) \\times \\cdots \\times (n-r+1)$로 계산할 때, r개를 연속으로 곱하면 된다. $_9P_2$는 9에서 시작하여 2개를 곱하므로 $9 \\times 8$이다.",
