    "answer": 3,
    "explanation": "**[핵심 개념]**\n이 문제는 순열(Permutation) 문제이다. 10명의 선수 중에서 1등(금메달), 2등(은메달), 3등(동메달)을 정하는 것으로, 순서가 중요하다. 즉, A가 1등이고 B가 2등인 경우와 B가 1등이고 A가 2등인 경우는 다릅니다.\n\n순열의 공식: $P(n, r) = \\frac{n!}{(n-r)!}$ 는 n개 중에서 r개를 뽑아 순서대로 배열하는 경우의 수이다.\n\n**[풀이]**\n\n**1단계: 금메달 결정**\n10명의 선수 중 누가 1등(금메달)을 할지 정한다.\n경우의 수: $10$가지\n\n**2단계: 은메달 결정**\n금메달을 받은 1명을 제외한 9명 중에서 2등(은메달)을 정한다.\n경우의 수: $9$가지\n\n**3단계: 동메달 결정**\n금메달과 은메달을 받은 2명을 제외한 8명 중에서 3등(동메달)을 정한다.\n경우의 수: $8$가지\n\n**4단계: 곱의 법칙 적용**\n각 단계가 독립적으로 일어나므로 곱의 법칙을 적용한다.\n\n$$\\text{경우의 수} = 10 \\times 9 \\times 8 = 720$$\n\n또는 순열 공식으로:\n$$P(10, 3) = \\frac{10!}{(10-3)!} = \\frac{10!}{7!} = 10 \\times 9 \\times 8 = 720$$\n\n**[정답 확인]**\n10명 중 3명을 순서를 정하여 선택하는 순열이므로 $P(10,3) = 720$이 정답이다.\n\n**[오답 분석]**\n\n① **120**: $\\frac{10!}{3! \\times 7!} = C(10,3) = 120$ - 조합 공식을 잘못 적용한 경우이다. 순서를 고려하지 않았다.\n\n② **360**: $10 \\times 9 \\times 4 = 360$ - 세 번째 단계를 잘못 계산한 경우이다.\n\n③ **504**: 어떤 계산 실수로 얻어진 수치로 보이며, 올바른 곱셈이 아닙니다.\n\n⑤ **1000**: $10 \\times 10 \\times 10 = 1000$ - 중복을 허용한 경우이다. 같은 선수가 여러 메달을 받을 수 없으므로 틀렸다.\n\n**[핵심 포인트]**\n- **순서가 중요한가?** → Yes → 순열 사용 ($P(n,r)$)\n- 메달의 등급이 다르므로 선수를 뽑는 순서가 중요하며, 이는 전형적인 순열 문제이다. $P(10, 3) = 10 \\times 9 \\times 8 = 720$",
