    "explanation": "**[핵심 개념]**\n이 문제는 **순열(Permutation)** 개념을 적용하는 문제이다. \n- 순열: $n$개 중에서 $r$개를 순서를 고려하여 선택하는 경우의 수\n- 순열 공식: $P(n, r) = \\frac{n!}{(n-r)!}$\n- 문자열은 **순서가 중요**한다. 예를 들어 \"AB\"와 \"BA\"는 다른 문자열이다.\n\n**[풀이]**\n\n**Step 1: 문제 상황 분석**\n- 전체 알파벳: A, B, C, D (4개)\n- 선택할 개수: 서로 다른 2개\n- 만들 것: 문자열 (순서 고려)\n\n**Step 2: 첫 번째 자리와 두 번째 자리 채우기**\n- 첫 번째 자리: 4개 알파벳 중 1개 선택 → **4가지**\n- 두 번째 자리: 남은 3개 알파벳 중 1개 선택 → **3가지**\n (첫 번째 자리에서 이미 1개를 사용했으므로)\n\n**Step 3: 곱의 법칙 적용**\n$$\\text{문자열의 개수} = 4 \\times 3 = 12$$\n\n**Step 4: 순열 공식으로도 확인**\n$$P(4, 2) = \\frac{4!}{(4-2)!} = \\frac{4!}{2!} = \\frac{24}{2} = 12$$\n\n**Step 5: 구체적인 예시로 검증**\n- A로 시작: AB, AC, AD (3개)\n- B로 시작: BA, BC, BD (3개)\n- C로 시작: CA, CB, CD (3개)\n- D로 시작: DA, DB, DC (3개)\n- 합계: $3 + 3 + 3 + 3 = 12$개 ✓\n\n**[정답 확인]**\n4개 중 서로 다른 2개를 순서를 고려하여 선택하는 순열이므로 $4 \\times 3 = 12$이다.\n\n**[오답 분석]**\n- ① 6: $\\binom{4}{2} = 6$ (조합으로 계산한 경우 - 순서를 무시함)\n- ② 8: 특별한 근거 없는 오답\n- ④ 16: $4^2 = 16$ (중복을 허용한 경우 - 문제에서 \"서로 다른\"이라는 조건 무시)\n- ⑤ 24: $4! = 24$ (4개를 모두 사용하는 경우 - 2개만 선택한다는 조건 무시)\n\n**[핵심 포인트]**\n**문자열은 순서가 중요하므로 조합이 아닌 순열을 사용**해야 한다. \"서로 다른 2개\"는 중복을 허용하지 않는다는 의미이므로 각 자리마다 선택할 수 있는 개수가 줄어듭니다.",
