    "answer": 2,
    "explanation": "**[핵심 개념]**\n순열(Permutation)은 서로 다른 n개의 원소 중에서 r개를 뽑아 일렬로 배열하는 경우의 수이다. 이 문제에서 회장과 부회장은 서로 다른 직책이므로 순서가 중요하다. 순열의 공식은 $P(n,r) = \\frac{n!}{(n-r)!}$ 또는 $P(n,r) = n \\times (n-1) \\times (n-2) \\times \\cdots \\times (n-r+1)$ 이다.\n\n**[풀이]**\n8명의 학생 중에서 회장 1명, 부회luke 1명을 뽑는 문제를 단계별로 해결한다.\n\n**1단계: 회장 선출**\n8명의 학생 중에서 회장을 선출하는 경우의 수: $8$가지\n\n**2단계: 부회장 선출**\n회장이 정해진 후, 남은 7명 중에서 부회장을 선출하는 경우의 수: $7$가지\n\n**3단계: 곱의 법칙 적용**\n전체 경우의 수는 두 사건이 동시에 일어나므로:\n$$P(8,2) = 8 \\times 7 = 56$$\n\n또는 순열 공식을 사용하면:\n$$P(8,2) = \\frac{8!}{(8-2)!} = \\frac{8!}{6!} = \\frac{8 \\times 7 \\times 6!}{6!} = 8 \\times 7 = 56$$\n\n**[정답 확인]**\n회장과 부회장은 서로 다른 직책이므로 순서가 구별되며, 8 × 7 = 56이 정답이다.\n\n**[오답 분석]**\n- ① 28: $\\frac{8 \\times 7}{2} = 28$으로, 조합으로 잘못 계산한 경우이다. 순서를 고려하지 않았다.\n- ② 40: 계산 실수 또는 8 + 7 × 4 = 40 같은 잘못된 공식을 적용한 경우이다.\n- ④ 64: $8^2 = 64$로, 복원추출(같은 학생을 두 번 뽑을 수 있다고 착각)한 경우이다.\n- ⑤ 72: 8 × 9 = 72로 계산한 것으로, 남은 학생 수를 잘못 계산한 경우이다.\n\n**[핵심 포인트]**\n- 직책이 다르면 순서가 중요하므로 **순열**을 사용한다.\n- 첫 번째 선출 후 남은 인원이 하나 줄어드는 점을 반드시 고려해야 한다.",
