    "explanation": "**[핵심 개념]**\n이 문제는 순열(Permutation) 개념을 다룹니다. 서로 다른 n개의 물건을 n명의 사람에게 하나씩 나누어주는 경우의 수는 n의 계승(factorial)으로 계산된다. 이를 $n!$ 으로 표기하며, $n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 2 \\times 1$ 이다.\n\n**[풀이]**\n4명의 친구를 A, B, C, D라 하고, 선물을 ①, ②, ③, ④라고 한다.\n\n$\\text{첫 번째 친구(A)에게 줄 선물 선택: } 4\\text{가지}$\n\n$\\text{두 번째 친구(B)에게 줄 선물 선택: } 3\\text{가지}$ (A에게 준 선물 제외)\n\n$\\text{세 번째 친구(C)에게 줄 선물 선택: } 2\\text{가지}$ (A, B에게 준 선물 제외)\n\n$\\text{네 번째 친구(D)에게 줄 선물 선택: } 1\\text{가지}$ (남은 선물 1개)\n\n곱의 법칙에 의해:\n$$4! = 4 \\times 3 \\times 2 \\times 1 = 24$$\n\n따라서 경우의 수는 **24가지**이다.\n\n**[정답 확인]**\n4개의 서로 다른 물건을 4명에게 하나씩 나누어주는 것은 4개 원소의 순열이므로 $4! = 24$가 정답이다.\n\n**[오답 분석]**\n- ① 12: $4! ÷ 2 = 12$로, 중복을 고려한 잘못된 계산\n- ② 16: $4^2 = 16$으로, 거듭제곱을 잘못 적용한 경우\n- ④ 32: $2^5 = 32$로, 순열 개념 없이 임의로 계산\n- ⑤ 64: $4^3 = 64$로, 거듭제곱을 잘못 적용한 경우\n\n**[핵심 포인트]**\n\"서로 다른 n개를 n명에게 하나씩 나누어주기\" = n! 순열이다. 각 단계마다 선택지가 1씩 줄어드는 구조를 명확히 파악하면 된다.",
