    "explanation": "**[핵심 개념]**\n조건이 있는 순열 문제에서는 조건을 만족하는 대상을 하나의 단위로 묶어서 생각하는 \"묶음 전략\"을 사용한다. 이를 통해 복잡한 조건을 단순화할 수 있다.\n\n**[풀이]**\n\n**Step 1: 부모 2명을 하나의 단위로 묶기**\n\n부모 2명이 반드시 이웃해야 한다는 조건이 있으므로, 부모 2명을 하나의 블록으로 생각한다.\n\n- 부모 블록 1개 + 자녀 3명 = 총 4개의 단위\n\n**Step 2: 4개 단위를 일렬로 배열하기**\n\n4개의 단위를 일렬로 서는 경우의 수는:\n$$4! = 24$$\n\n**Step 3: 부모 블록 내에서 부모 2명의 순서**\n\n부모 블록 내에서 부모 2명이 배열되는 경우의 수는:\n$$2! = 2$$\n\n(부모 A-부모 B 순서 또는 부모 B-부모 A 순서)\n\n**Step 4: 전체 경우의 수 계산**\n\n곱의 법칙에 의해 전체 경우의 수는:\n$$24 \\times 2 = 48$$\n\n**[정답 확인]**\n부모 2명을 하나의 블록으로 묶어 4개 단위의 배열($4!=24$)과 블록 내 부모의 순서($2!=2$)를 곱하면 $24 \\times 2 = 48$이 되어 정답이다.\n\n**[오답 분석]**\n- ① 12: $4! \\div 2$를 계산한 오류로, 부모의 순서를 고려하지 않음\n- ② 24: 부모 2명을 묶은 후 4개 단위의 배열만 구한 것으로, 부모 내 순서($2!$)를 곱하지 않음\n- ③ 36: 계산 과정의 오류\n- ⑤ 60: $5! \\div 2$ 등의 잘못된 계산\n\n**[핵심 포인트]**\n조건부 순열에서는 조건을 만족하는 대상을 하나의 묶음으로 취급한 후, 묶음 내에서의 내부 배열도 함께 곱해주어야 한다: $(\\text{묶음 배열}) \\times (\\text{내부 배열}) = 4! \\times 2! = 48$",
