    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 조건이 있는 순열 문제이다. 특정한 조건(A가 맨 앞 또는 맨 뒤)을 만족하는 경우의 수를 구할 때는 경우를 나누어 계산한다.\n- 경우의 수 덧셈 법칙: 겹치지 않는 두 사건이 있을 때, 전체 경우의 수 = (사건 1의 경우의 수) + (사건 2의 경우의 수)\n- n명을 일렬로 세우는 경우의 수 = $n!$\n\n**[풀이]**\n\n**1단계: 전체 상황 파악**\n- 총 6명의 학생 중 학생 A는 반드시 맨 앞 또는 맨 뒤에 서야 함\n- 나머지 5명은 자유롭게 배치\n\n**2단계: 경우를 나누기**\n학생 A의 위치에 따라 두 가지 경우로 나눔\n\n**경우 1: A가 맨 앞에 서는 경우**\n- A의 위치: 고정 (맨 앞)\n- 나머지 5명의 학생: 2번째부터 6번째 위치에 배치\n- 경우의 수: $5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$\n\n**경우 2: A가 맨 뒤에 서는 경우**\n- A의 위치: 고정 (맨 뒤)\n- 나머지 5명의 학생: 1번째부터 5번째 위치에 배치\n- 경우의 수: $5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$\n\n**3단계: 전체 경우의 수 계산**\n두 경우는 겹치지 않으므로 덧셈 법칙 적용:\n$$\\text{전체 경우의 수} = 120 + 120 = 240$$\n\n**[정답 확인]**\n학생 A가 맨 앞에 서는 경우 120가지와 맨 뒤에 서는 경우 120가지를 더하면 240가지이므로 정답은 ③번이다.\n\n**[오답 분석]**\n- ① 48: $5! \\div 5 = 24$를 실수로 계산한 경우\n- ② 120: 한 가지 경우(A가 맨 앞 또는 맨 뒤 중 하나)만 계산한 경우\n- ④ 360: $6! \\div 2 = 360$으로 잘못된 공식을 적용한 경우\n- ⑤ 480: $5! \\times 2 \\times 2 = 240$을 실수로 계산한 경우\n\n**[핵심 포인트]**\n\"또는\"이라는 조건이 있을 때는 경우를 나누어 각각 계산 후 더해야 한다. 조건이 있는 위치는 고정시키고, 나머지 원소들의 배열만 계산하는 것이 핵심이다.",
