    "explanation": "**[핵심 개념]**\n세 자리 자연수는 백의 자리가 0이 아니어야 한다. 따라서 이 문제는 \"0을 제외한 숫자로 백의 자리를 정하고, 나머지 자리를 채우는\" 경우의 수 문제이다. 중복이 없으므로 각 자리에서 선택할 수 있는 숫자의 개수가 감소한다.\n\n**[풀이]**\n\n세 자리 수 $\\overline{ABC}$를 만드는데, $A \\neq 0$ (백의 자리)이고, $A, B, C$는 모두 다른 숫자여야 한다.\n\n**1단계: 백의 자리(A) 결정**\n- 0, 1, 2, 3, 4 중에서 0을 제외해야 하므로\n- 백의 자리에 올 수 있는 숫자: 1, 2, 3, 4\n- 경우의 수: $4$가지\n\n**2단계: 십의 자리(B) 결정**\n- 백의 자리에서 1개 숫자를 사용했으므로 남은 숫자는 4개\n- 이 4개 숫자(0 포함) 모두 십의 자리에 올 수 있음\n- 경우의 수: $4$가지\n\n**3단계: 일의 자리(C) 결정**\n- 백의 자리, 십의 자리에서 각각 1개씩 사용했으므로 남은 숫자는 3개\n- 이 3개 숫자 중 하나를 선택\n- 경우의 수: $3$가지\n\n**4단계: 전체 경우의 수**\n$$4 \\times 4 \\times 3 = 48$$\n\n**[정답 확인]**\n백의 자리는 0이 아닌 4개 중 선택(4가지), 십의 자리는 남은 4개 중 선택(4가지), 일의 자리는 남은 3개 중 선택(3가지)이므로 $4 \\times 4 \\times 3 = 48$이다.\n\n**[오답 분석]**\n- 60: $5 \\times 4 \\times 3 = 60$ (0을 백의 자리에 놓는 경우를 포함한 오류)\n- 40: 십의 자리 계산 실수로 $4 \\times 3 \\times 3 = 36$ 또는 $5 \\times 4 \\times 2$ 등으로 계산한 오류\n- 36: $4 \\times 3 \\times 3$ (십의 자리를 3가지로 잘못 계산)\n\n**[핵심 포인트]**\n세 자리 자연수는 **백의 자리가 0이 아니어야 한다**는 조건이 핵심이다. 백의 자리부터 먼저 정하고(0 제외), 이후 남은 숫자들로 십의 자리와 일의 자리를 채워나가는 순서가 중요하다.",
