    "explanation": "**[핵심 개념]**\n순열 문제에서 조건이 있을 때는 조건을 먼저 만족시키고, 나머지 자리를 배열하는 방식을 사용한다. 일렬 배열에서 \"양 끝\"이라는 조건이 있으면, 양 끝 자리를 먼저 정하고 중간 자리를 배열하는 단계별 접근이 효과적이다.\n\n**[풀이]**\n\n**1단계: 양 끝에 남학생을 배치**\n- 양 끝 두 자리에 들어올 남학생 3명 중 2명을 선택하여 배치\n- 왼쪽 끝: 3가지 선택지\n- 오른쪽 끝: 2가지 선택지 (남은 남학생 중)\n- 양 끝 배치 경우의 수: $3 \\times 2 = 6$가지\n\n**2단계: 나머지 자리에 남은 학생 배치**\n- 양 끝에 남학생 2명이 배치된 후, 중간 4자리가 남음\n- 남은 학생: 남학생 1명, 여학생 3명 (총 4명)\n- 이 4명을 중간 4자리에 배열하는 경우의 수: $4!$\n- $4! = 4 \\times 3 \\times 2 \\times 1 = 24$가지\n\n**3단계: 곱의 법칙 적용**\n$$\\text{전체 경우의 수} = 6 \\times 24 = 144$$\n\n**[정답 확인]**\n양 끝에 남학생을 고정(6가지)하고, 중간 4명을 자유롭게 배열(24가지)하면 $6 \\times 24 = 144$이므로 ③번이 정답이다.\n\n**[오답 분석]**\n- ① 72: $3 \\times 2 \\times 12 = 72$ (중간 4명을 4!이 아닌 3!으로 계산한 오류)\n- ② 108: $3 \\times 3 \\times 12 = 108$ (양 끝 배치를 $3 \\times 3$으로 중복 계산)\n- ④ 216: $6 \\times 36 = 216$ (중간을 $P(4,4)$ 대신 다른 값으로 계산한 오류)\n- ⑤ 288: $6 \\times 48 = 288$ (계산 실수로 4!을 잘못 구한 경우)\n\n**[핵심 포인트]**\n조건이 있는 배열은 **조건을 만족하는 부분을 먼저 배치**하고, **나머지 요소를 남은 자리에 자유롭게 배열**하는 단계별 접근이 기본이다. 곱의 법칙으로 각 단계를 곱하면 된다.",
