    "answer": 3,
    "explanation": "**[핵심 개념]**\n여사건을 이용한 경우의 수 계산 방법이다. 구하고자 하는 \"A와 B가 이웃하지 않는 경우\"는 \"전체 경우에서 A와 B가 이웃하는 경우를 빼는\" 방식으로 구한다. 이는 직접 세기보다 계산이 훨씬 간단한다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 구하기**\n\n5명이 일렬로 서는 모든 경우의 수는:\n$$5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$$\n\n**2단계: A와 B가 이웃하는 경우의 수 구하기**\n\nA와 B를 하나의 단위로 생각한다. 이를 \"AB 묶음\"이라 하면:\n- AB 묶음, C, D, E 총 4개의 객체를 배열: $4! = 24$\n- AB 묶음 내에서 A와 B의 순서: $2! = 2$\n- 따라서 A와 B가 이웃하는 경우: $4! \\times 2! = 24 \\times 2 = 48$\n\n**3단계: 여사건을 이용하여 답 구하기**\n\nA와 B가 이웃하지 않는 경우의 수는:\n$$120 - 48 = 72$$\n\n**[정답 확인]**\n전체 120가지 중에서 A와 B가 이웃하는 48가지를 제외하면 72가지가 되어 정답이다.\n\n**[오답 분석]**\n- ① 36: $72 \\div 2$의 값으로, 계산 오류 (AB를 한 번만 계산한 경우)\n- ② 48: A와 B가 이웃하는 경우의 수를 잘못 선택한 경우\n- ③ 60: $120 - 60$으로 계산하여 잘못 계산한 경우\n- ⑤ 84: $120 - 36$으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n제약 조건이 있는 순열 문제는 **여사건(전체 - 제약을 위반하는 경우)을 이용**하면 효율적이다. 특히 \"이웃하지 않는\" 문제에서는 \"이웃하는 경우\"를 먼저 계산하는 것이 핵심이다.",
