    "problem": "영어 소문자 a, b, c, d, e에서 서로 다른 3개를 선택해 만든 문자열 중, a로 시작하는 것의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 12,
    "explanation": "**[핵심 개념]**\n\n이 문제는 순열(Permutation) 문제이다. 서로 다른 n개에서 r개를 선택하여 순서를 고려하여 나열하는 경우의 수는 $P(n,r) = \\frac{n!}{(n-r)!}$로 계산된다. 또한 조건이 있을 때는 조건을 먼저 고정하고, 나머지 경우의 수를 계산한다.\n\n**[풀이]**\n\n**1단계: 문제 상황 파악**\n- 전체 문자: a, b, c, d, e (5개)\n- 선택할 개수: 3개 (서로 다른 문자)\n- 조건: a로 시작해야 함\n- 순서를 고려한 문자열을 만들어야 함\n\n**2단계: 조건 고정**\n\na로 시작한다는 것은 첫 번째 자리에 a가 고정되었다는 의미이다.\n$$\\text{[a][\\_][\\_]}$$\n\n**3단계: 남은 자리 채우기**\n\n- 첫 번째 자리: a (고정)\n- 두 번째 자리: 남은 문자 중 선택\n- 세 번째 자리: 남은 문자 중 선택\n\na를 제외한 남은 문자는 b, c, d, e (4개)이다.\n\n이 4개 중에서 서로 다른 2개를 순서를 고려하여 선택해야 한다.\n\n**4단계: 경우의 수 계산**\n\n$$P(4, 2) = \\frac{4!}{(4-2)!} = \\frac{4!}{2!} = \\frac{4 \\times 3 \\times 2!}{2!} = 4 \\times 3 = 12$$\n\n또는 단계적으로:\n- 두 번째 자리에 올 수 있는 문자: 4개 (b, c, d, e 중 하나)\n- 세 번째 자리에 올 수 있는 문자: 3개 (두 번째에서 선택한 것 제외한 3개)\n\n따라서 $4 \\times 3 = 12$\n\n**[정답 확인]**\n\na로 시작하는 3개 문자 문자열은 (a, 나머지 4개 중 2개를 순서대로 선택)이므로 $P(4,2) = 12$이다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으나, 흔한 오답은:\n- **10개**: $C(4,2) \\times 2! = 6 \\times 2$로 중복 계산한 경우\n- **20개**: 전체 5개에서 3개를 선택하는 $P(5,3) = 60$을 계산 후 잘못 축약한 경우\n- **5개**: a 다음 1개만 선택하는 것으로 잘못 이해한 경우\n\n**[핵심 포인트]**\n\n1. **조건이 있을 때는 조건을 먼저 고정**: a로 시작한다는 것을 먼저 처리하여 문제를 단순화\n2. **순서 있는 선택은 순열**: 문자열은 순서가 중요하므로 조합이 아닌 순열($P$)을 사용",
