    "_type": "permutation",
    "type": "순열",
    "problem": "서로 다른 4개의 편지를 서로 다른 4개의 우체통에 넣되, 특정 편지 X는 특정 우체통 P에 넣지 않는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 18,
    "explanation": "**[핵심 개념]**\n이 문제는 제약 조건이 있는 순열 문제이다. 전체 경우에서 조건을 위반하는 경우를 빼는 \"여사건\"을 이용하는 방법과, 직접 경우를 나누어 세는 방법을 사용할 수 있다.\n\n**[풀이]**\n\n**방법 1: 여사건을 이용한 풀이**\n\n전체 경우의 수에서 \"편지 X가 우체통 P에 들어가는 경우\"를 빼면 된다.\n\n- 전체 경우: 4개의 편지를 4개의 우체통에 넣는 경우 = $4! = 24$\n\n- 제약 조건 위반: 편지 X가 반드시 우체통 P에 들어가는 경우\n - 편지 X를 우체통 P에 고정\n - 나머지 3개의 편지를 나머지 3개의 우체통에 배치 = $3! = 6$\n\n따라서 구하는 경우의 수:\n$$24 - 6 = 18$$\n\n**방법 2: 직접 세기**\n\n편지 X가 들어갈 수 있는 우체통은 P를 제외한 3개이다.\n\n- 편지 X를 넣을 우체통 선택: 3가지\n\n- 각 경우에 대해 나머지 3개의 편지를 나머지 3개의 우체통에 배치: $3! = 6$가지\n\n따라서:\n$$3 \\times 6 = 18$$\n\n**[정답 확인]**\n전체 24가지에서 X가 P에 들어가는 6가지를 제외하면 18이 되므로 정답이다.\n\n**[오답 분석]**\n- **24**: 제약 조건을 무시하고 전체 경우의 수만 계산한 경우\n- **6**: 편지 X가 P에 반드시 들어가는 경우만 센 경우 (여사건만 계산)\n- **12**: 계산 실수로 $3 \\times 4 = 12$로 계산한 경우\n\n**[핵심 포인트]**\n제약 조건이 있는 순열은 **전체 - (조건 위반)**으로 계산하는 것이 가장 빠르고 실수가 적다. 편지 X의 선택지를 먼저 정하고(3가지), 나머지를 배치($3! = 6$)하는 직접 계산도 효과적이다.",
