    "answer": 1,
    "explanation": "**[핵심 개념]**\n여학생끼리 이웃하지 않는다는 조건은 여학생들 사이에 남학생이 반드시 배치되어야 함을 의미한다. 이런 문제는 제약 조건이 있는 대상을 먼저 배치하고, 나머지를 그 사이사이에 삽입하는 방법을 사용한다. 일반적으로 (1) 제약이 없는 대상을 먼저 배열 (2) 그 사이의 빈 자리에 제약이 있는 대상을 배치하는 전략이다.\n\n**[풀이]**\n\n**1단계: 남학생 4명을 일렬로 배치**\n제약 조건이 없는 남학생 4명을 먼저 일렬로 배열한다.\n$$4! = 24 \\text{가지}$$\n\n**2단계: 여학생이 들어갈 수 있는 위치 파악**\n남학생 4명이 배열되면 여학생이 들어갈 수 있는 위치는:\n$$\\_ \\text{남} \\_ \\text{남} \\_ \\text{남} \\_ \\text{남} \\_$$\n\n남학생 사이 및 양쪽 끝에 총 **5개의 빈 자리**가 생깁니다.\n\n**3단계: 여학생 3명을 5개 자리 중 선택**\n여학생끼리 이웃하지 않으려면, 5개의 빈 자리 중 서로 다른 3개의 자리를 선택해야 한다.\n5개 자리 중 3개를 선택하는 경우의 수:\n$$\\binom{5}{3} = 10 \\text{가지}$$\n\n**4단계: 선택한 자리에 여학생 3명 배치**\n선택된 3개의 자리에 여학생 3명을 배열한다.\n$$3! = 6 \\text{가지}$$\n\n**5단계: 전체 경우의 수 계산**\n곱의 법칙에 의해:\n$$4! \\times \\binom{5}{3} \\times 3! = 24 \\times 10 \\times 6 = 1440$$\n\n**[정답 확인]**\n남학생을 먼저 배치(24가지) → 생기는 5개 자리 중 3개 선택(10가지) → 여학생 배치(6가지)를 곱하면 정확히 1440이 된다.\n\n**[오답 분석]**\n- ① 720: $4! \\times 5 \\times 3! = 720$ (조합을 고려하지 않음, 단순히 5개 자리 중 하나만 선택)\n- ③ 2160: $4! \\times \\binom{5}{3} \\times 3! \\times 1.5$ (계산 오류)\n- ④ 2880: $7! / 2 = 2880$ (제약 조건을 제대로 반영하지 않은 단순 계산)\n- ⑤ 4320: $7! = 5040$의 일부 또는 중복 계산 (제약 조건 무시)\n\n**[핵심 포인트]**\n**\"제약이 있는 문제는 제약이 없는 것을 먼저 배치하고, 그 사이에 제약 있는 것을 삽입하라\"** — 이 전략으로 복잡한 조건을 단순하게 처리할 수 있다. 여학생 3명이 들어갈 5개 자리 중 3개를 선택하는 것이 핵심이다.",
