    "answer": 156,
    "explanation": "**[핵심 개념]**\n네 자리 짝수는 일의 자리가 0, 2, 4 중 하나여야 한다. 따라서 일의 자리 수에 따라 경우를 나누어 계산하는 것이 효율적이다. 또한 천의 자리는 0이 올 수 없다는 제약이 있으므로 이를 고려해야 한다.\n\n**[풀이]**\n\n네 자리 수를 $\\overline{abcd}$로 나타낼 때, 다음 조건을 만족해야 한다:\n- $a \\neq 0$ (천의 자리)\n- $d \\in \\{0, 2, 4\\}$ (일의 자리는 짝수)\n- 0, 1, 2, 3, 4, 5를 중복 없이 사용\n\n일의 자리 수에 따라 경우를 나눕니다.\n\n**경우 1: $d = 0$일 때**\n\n일의 자리가 0으로 정해졌으므로, 천의 자리에 올 수 있는 수는 1, 2, 3, 4, 5 중 하나이다 (5개 선택지).\n\n천의 자리가 정해지면, 백의 자리와 십의 자리에는 남은 4개 숫자 중 2개를 순서를 고려하여 배열한다.\n\n$$5 \\times P(4, 2) = 5 \\times 4 \\times 3 = 60$$\n\n**경우 2: $d = 2$일 때**\n\n일의 자리가 2로 정해졌으므로, 천의 자리에 올 수 있는 수는 1, 3, 4, 5 중 하나이다 (0은 불가, 2는 이미 사용).\n\n- 천의 자리 선택: 4가지\n- 천의 자리가 정해진 후, 남은 4개 숫자(0 포함) 중에서 백의 자리와 십의 자리에 2개를 순서를 고려하여 배열:\n\n$$4 \\times P(4, 2) = 4 \\times 4 \\times 3 = 48$$\n\n**경우 3: $d = 4$일 때**\n\n일의 자리가 4로 정해졌으므로, 천의 자리에 올 수 있는 수는 1, 2, 3, 5 중 하나이다 (0은 불가, 4는 이미 사용).\n\n- 천의 자리 선택: 4가지\n- 천의 자리가 정해진 후, 남은 4개 숫자(0 포함) 중에서 백의 자리와 십의 자리에 2개를 순서를 고려하여 배열:\n\n$$4 \\times P(4, 2) = 4 \\times 4 \\times 3 = 48$$\n\n**전체 경우의 수**\n\n$$60 + 48 + 48 = 156$$\n\n**[정답 확인]**\n일의 자리 수에 따라 경우를 나누고 각 경우에서 천의 자리 제약(0 불가)을 정확히 적용하면 156개가 나온다.\n\n**[오답 분석]**\n- 천의 자리에 0이 올 수 있다고 잘못 계산하면 더 큰 수가 나온다.\n- 경우 2, 3에서 천의 자리 선택지를 5개로 잘못 계산하면 $(5+5+5) \\times 4 \\times 3 = 180$ 등의 오답이 나온다.\n- 일의 자리별로 경우를 나누지 않고 계산하면 복잡한 중복 제거 문제가 발생한다.\n\n**[핵심 포인트]**\n1. 네 자리 짝수 문제에서는 **일의 자리부터 결정**하고, 천의 자리 제약을 동시에 고려한다.\n2. 일의 자리가 0인 경우와 0이 아닌 경우는 **천의 자리 선택지의 개수가 달라지므로** 반드시 분리하여 계산해야 한다.",
