    "answer": 3,
    "explanation": "**[핵심 개념]**\n조건이 있는 순열 문제이다. 특정 순서 관계가 주어진 경우, 전체 순열에서 그 순서 관계를 만족하는 비율을 이용한다.\n\n- 서로 다른 n개 원소 중 특정 k개의 상대적 순서가 정해진 경우의 수: $\\frac{n!}{k!}$\n- 이는 n개를 배열하는 모든 경우 중에서, k개의 상대적 순서가 일정한 비율($\\frac{1}{k!}$)로 나타나기 때문이다.\n\n**[풀이]**\n\n**Step 1: 전체 상황 파악**\n- 6명이 일렬로 서는데, A, B, C 사이에만 순서 제약이 있다.\n- 조건: A는 B보다 왼쪽, B는 C보다 왼쪽 (즉, A < B < C의 순서)\n\n**Step 2: 전체 순열에서의 비율 계산**\n6명을 일렬로 세우는 전체 경우의 수: $6! = 720$\n\nA, B, C 세 명의 상대적 위치만 고려하면, 이들을 배치하는 방법은:\n- ABC 순서, ACB 순서, BAC 순서, BCA 순서, CAB 순서, CBA 순서 (총 $3! = 6$가지)\n\n이 중에서 A < B < C를 만족하는 경우는 **1가지**만 가능한다.\n\n**Step 3: 조건을 만족하는 경우의 수**\n대칭성에 의해, 6명 중 A, B, C의 상대적 순서가 결정되면, 나머지 3명(다른 사람들)은 자유롭게 배치된다.\n\n따라서 구하는 경우의 수:\n$$\\frac{6!}{3!} = \\frac{720}{6} = 120$$\n\n**Step 4: 검증**\n다른 방법으로 검증:\n- 6명 중 3명을 뽑아 A, B, C로 지정하는 경우: $\\binom{6}{3} = 20$\n- 이들을 A < B < C 순서로 배치하는 경우: 1가지 (고정)\n- 나머지 3명을 배치하는 경우: $3! = 6$\n- 총합: $20 \\times 1 \\times 6 = 120$ ✓\n\n**[정답 확인]**\n조건을 만족하는 경우의 수는 $\\frac{6!}{3!} = 120$이며, 이는 A, B, C 세 명의 상대적 순서가 정해졌을 때 전체 순열을 그 순서의 개수로 나눈 값이다.\n\n**[오답 분석]**\n- ① 60: $\\frac{6!}{12}$ - 분모를 잘못 계산한 경우\n- ② 80: 특정 위치 조건을 잘못 해석한 경우\n- ③ 100: 순열과 조합을 혼동하여 계산한 경우\n- ⑤ 180: $\\frac{6!}{4} = 180$ - 3!이 아닌 다른 값으로 나눈 경우\n\n**[핵심 포인트]**\n서로 다른 n개 원소 중 k개의 상대적 순서가 정해진 경우의 수는 $\\frac{n!}{k!}$이다. 이 문제에서는 A, B, C 3명의 순서가 고정되므로 $\\frac{6!}{3!} = 120$이 답이다.",
