    "answer": 1,
    "explanation": "**[핵심 개념]**\n원형 배열에서 조건이 있을 때의 경우의 수를 구하는 문제이다.\n- 원형 배열: 회전을 같은 것으로 보므로 $(n-1)!$\n- 조건부 배열: 특정 조건(부부가 이웃)을 만족하는 경우의 수\n- 블록 단위 배열: 조건을 만족하는 단위를 하나의 블록으로 취급\n\n**[풀이]**\n\n**1단계: 부부 4쌍을 하나의 단위로 블록화**\n\n모든 부부가 이웃하여 앉아야 하므로, 각 부부를 하나의 블록으로 생각한다.\n- 블록의 개수: 4개\n- 각 블록 내에서 남녀의 순서: 2가지\n\n**2단계: 4개 블록의 원형 배열**\n\n4개의 블록을 원형 탁자에 배열하는 경우의 수:\n$$n = 4 \\text{일 때, 원형 배열} = (4-1)! = 3! = 6$$\n\n**3단계: 각 블록 내에서 부부의 배열**\n\n각 블록(부부)마다 남편과 아내의 순서를 정할 수 있다.\n- 블록 1: 2가지\n- 블록 2: 2가지\n- 블록 3: 2가지\n- 블록 4: 2가지\n- 총: $2^4 = 16$가지\n\n**4단계: 전체 경우의 수 계산**\n\n$$\\text{전체 경우의 수} = 3! \\times 2^4 = 6 \\times 16 = 96$$\n\n**[정답 확인]**\n원형 배열의 기본 공식 $(n-1)!$에 각 블록 내 순서 $2^4$를 곱하면 $6 \\times 16 = 96$이 되어 정답이다.\n\n**[오답 분석]**\n- ① 48: $3! \\times 2^3$으로 한 블록의 순서만 누락한 경우\n- ③ 192: $4! \\times 2^3$으로 원형 배열을 고려하지 않고 직선 배열 공식을 잘못 적용한 경우\n- ④ 384: $4! \\times 2^4$로 원형 배열을 완전히 무시하고 직선 배열로 계산한 경우\n- ⑤ 768: $4! \\times 2^5$로 불필요한 추가 곱셈을 한 경우\n\n**[핵심 포인트]**\n조건부 원형 배열 문제에서는 **(블록 단위 원형 배열) × (각 블록 내 배열)** 형태로 계산하며, 원형이므로 회전 대칭을 반드시 제거해야 한다.",
