    "answer": 0,
    "explanation": "**[핵심 개념]**\n원형 탁자 배치 문제에서는 회전을 같은 것으로 간주한다. 따라서 $n$명을 원형으로 배치하는 경우의 수는 $(n-1)!$이다. 이 문제에서는 조건부 배치를 다루므로, 조건을 만족하는 경우를 체계적으로 분류해야 한다.\n\n**[풀이]**\n\n**Step 1: A와 B를 하나의 단위로 묶기**\n\nA와 B가 이웃해야 하므로, A와 B를 한 묶음으로 생각한다.\n- 묶음 내에서 A, B의 배치: $2!$ 가지\n- (AB), C, D, E 4개 단위를 원형 배치: $(4-1)! = 3! = 6$ 가지\n- A, B 이웃 조건만으로: $2 \\times 6 = 12$ 가지\n\n**Step 2: C와 D가 이웃하는 경우 제외하기**\n\nA와 B를 이웃하게 배치했을 때, C와 D도 이웃하는 경우를 구해서 빼야 한다.\n\nA, B를 한 묶음 (AB), C, D를 한 묶음 (CD), E로 생각하면:\n- (AB) 내 배치: $2!$ 가지\n- (CD) 내 배치: $2!$ 가지\n- (AB), (CD), E 3개 단위를 원형 배치: $(3-1)! = 2! = 2$ 가지\n- A, B 이웃이고 C, D도 이웃하는 경우: $2 \\times 2 \\times 2 = 8$ 가지\n\n**Step 3: 최종 계산**\n\n$$\\text{구하는 경우의 수} = 12 - 8 = 4$$\n\n**[정답 확인]**\nA, B는 반드시 이웃하고, C, D는 반드시 이웃하지 않아야 한다는 두 조건을 모두 만족하는 배치는 4가지이다.\n\n**[오답 분석]**\n- ② 6: A, B 이웃 조건만 고려하거나 계산 실수\n- ③ 8: C, D가 이웃하는 경우의 수를 구함 (빼야 할 부분을 답으로 선택)\n- ④ 12: A, B 이웃 조건만 적용하고 C, D 조건을 무시함\n- ⑤ 16: 원형 배치의 회전 대칭을 고려하지 않음\n\n**[핵심 포인트]**\n1. 원형 배치에서는 회전을 같은 것으로 보므로 $(n-1)!$을 사용한다.\n2. '이웃하고' & '이웃하지 않는' 조건은 전체에서 여집합을 이용하여 계산한다: (이웃함) - (둘 다 이웃함)",
