    "problem": "1, 2, 3, 4, 5, 6을 일렬로 나열할 때, 1이 2보다 왼쪽에, 2가 3보다 왼쪽에, 그리고 4가 5보다 왼쪽에 있는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 60,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 순열 문제이다. 전체 순열에서 특정 원소들 간의 상대적 순서가 고정될 때, 경우의 수를 구하는 문제이다. \n\n핵심 원리: $n$개 원소를 배열할 때, 특정 $k$개 원소의 상대적 순서가 정해지면, 그 경우의 수는 전체 배열 중에서 $\\frac{1}{k!}$만큼만 해당된다. 이는 $k$개 원소가 특정 순서로 나타날 확률이 $\\frac{1}{k!}$이기 때문이다.\n\n**[풀이]**\n\n**1단계: 전체 구조 파악**\n- 1, 2, 3, 4, 5, 6을 배열하되\n- 조건 1: 1 < 2 < 3 (상대적 위치)\n- 조건 2: 4 < 5 (상대적 위치)\n\n**2단계: 조건 1 적용 (1, 2, 3의 순서)**\n\n전체 배열 6!에서 1, 2, 3이 임의로 배치될 때, \n- 1, 2, 3의 상대적 순서는 3! = 6가지가 모두 동일한 확률\n\n따라서 \"1이 2보다 왼쪽, 2가 3보다 왼쪽\"인 경우는:\n$$\\frac{6!}{3!} = \\frac{720}{6} = 120$$\n\n**3단계: 조건 2 추가 적용 (4, 5의 순서)**\n\n위의 120가지 배열 각각에서 4와 5의 위치는 독립적이다.\n- 1, 2, 3이 정해진 상태에서 4, 5가 배치될 때\n- 4와 5의 상대적 순서는 2! = 2가지가 동일한 확률\n\n따라서 \"4가 5보다 왼쪽\"인 경우는:\n$$\\frac{120}{2} = 60$$\n\n**다른 풀이 방법: 조합론적 접근**\n\n6개 위치 중 1, 2, 3이 들어갈 3개 위치를 선택: $\\binom{6}{3}$\n- 이 3개 위치에는 자동으로 1, 2, 3이 오름차순으로 배치\n\n남은 3개 위치 중 4, 5가 들어갈 2개 위치를 선택: $\\binom{3}{2}$\n- 이 2개 위치에는 자동으로 4, 5가 오름차순으로 배치\n\n남은 1개 위치에 6이 배치\n\n$$\\binom{6}{3} \\times \\binom{3}{2} = 20 \\times 3 = 60$$\n\n**[정답 확인]**\n조합론적 방법과 확률적 방법 모두 60을 도출하므로, 답은 **60**이 맞다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으므로 일반적인 오류를 설명한다:\n- **720**: 조건을 무시하고 6! 전체를 계산한 경우\n- **180**: 조건 1만 적용하고 조건 2를 빠뜨린 경우\n- **120**: 조건 1만 적용한 경우 (조건 2를 반영하지 않음)\n\n**[핵심 포인트]**\n✓ **다중 조건의 독립성**: 1,2,3의 순서와 4,5의 순서는 독립적이므로 각각 조건을 순차적으로 적용할 수 있다.\n\n✓ **조합 선택법이 가장 직관적**: $\\binom{n}{k}$로 위치를 선택하면 자동으로 그 위치에 오름차순 배치되므로 조건이 자동 만족된다.",
