    "explanation": "**[핵심 개념]**\n조건부 경우의 수 문제로, \"특정 2명이 같은 방에 배정된다\"는 조건을 만족하는 경우를 구한다. 이는 전체 경우에서 특정 조건을 만족하는 부분만을 선택하는 문제이다. 조합 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$을 사용하여 각 경우를 계산한다.\n\n**[풀이]**\n\nP와 Q가 같은 방에 배정되는 경우를 두 가지로 나누어 계산한다.\n\n**경우 1: P, Q가 모두 A방에 배정되는 경우**\n\n- A방에는 이미 P, Q가 배정되었으므로, 남은 6명(P, Q 제외) 중에서 $3 - 2 = 1$명을 선택하여 A방에 배정한다.\n- 경우의 수: $\\binom{6}{1} = 6$\n\n**경우 2: P, Q가 모두 B방에 배정되는 경우**\n\n- B방에는 이미 P, Q가 배정되었으므로, 남은 6명(P, Q 제외) 중에서 $5 - 2 = 3$명을 선택하여 B방에 배정한다.\n- 경우의 수: $\\binom{6}{3} = \\frac{6!}{3! \\cdot 3!} = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = 20$\n\n**전체 경우의 수**\n\n$$\\text{경우 1} + \\text{경우 2} = 6 + 20 = 26$$\n\n**[정답 확인]**\nP, Q를 하나의 단위로 생각하고, 각 경우에서 남은 인원을 적절히 배분하는 조합을 계산한 결과가 26이므로 정답이다.\n\n**[오답 분석]**\n\n- ① 16: 경우 2에서 $\\binom{6}{2}$를 계산한 경우 ($6 + 10 = 16$)로, B방에 필요한 인원 수를 잘못 파악한 오답이다.\n- ② 21: 경우 1만 계산하거나 부분적인 계산으로 도출된 오답이다.\n- ④ 36: 두 경우를 곱하거나 ($6 \\times 6 = 36$) 다른 계산 실수로 인한 오답이다.\n- ⑤ 42: $\\binom{6}{1} + \\binom{6}{4} = 6 + 15 = 21$ 등 잘못된 조합 계산으로 인한 오답이다.\n\n**[핵심 포인트]**\n조건부 경우의 수는 조건을 만족하는 각 경우를 **명확히 분류**하고, 각 경우에서 **남은 인원이 각 방에 배정되는 조건**을 정확히 파악하는 것이 중요하다. P, Q를 선택 후 남은 6명을 배분하는 방식으로 접근하면 실수를 줄일 수 있다.",
