    "explanation": "**[핵심 개념]**\n\n순열(Permutation)은 주어진 원소들 중에서 일부를 선택하여 순서를 정하는 경우의 수이다.\n$_nP_r$은 $n$개의 원소 중에서 $r$개를 순서를 고려하여 선택하는 경우의 수이며, 공식은 $$_nP_r = \\frac{n!}{(n-r)!} = n(n-1)(n-2)\\cdots(n-r+1)$$\n\n특히 $_nP_2 = n(n-1)$이다.\n\n**[풀이]**\n\n주어진 조건: $_nP_2 = 6$\n\n순열의 공식을 적용하면:\n$$_nP_2 = n(n-1) = 6$$\n\n이를 전개하면:\n$$n^2 - n = 6$$\n\n$$n^2 - n - 6 = 0$$\n\n이차방정식을 인수분해하면:\n$$(n-3)(n+2) = 0$$\n\n따라서:\n$$n = 3 \\text{ 또는 } n = -2$$\n\n문제의 조건에서 $n$은 자연수이고 $n \\geq 2$이므로, $n = -2$는 버려진다.\n\n$$\\therefore n = 3$$\n\n**[정답 확인]**\n\n$n = 3$을 검증하면: $_3P_2 = 3 \\times 2 = 6$ ✓\n\n**[오답 분석]**\n\n- ② $n=4$: $_4P_2 = 4 \\times 3 = 12 \\neq 6$\n- ③ $n=5$: $_5P_2 = 5 \\times 4 = 20 \\neq 6$\n- ④ $n=6$: $_6P_2 = 6 \\times 5 = 30 \\neq 6$\n- ⑤ $n=7$: $_7P_2 = 7 \\times 6 = 42 \\neq 6$\n\n$n$이 커질수록 $_nP_2$의 값도 증가하므로 위의 선택지들은 모두 6보다 큽니다.\n\n**[핵심 포인트]**\n\n$_nP_2 = n(n-1)$이라는 간단한 형태를 빠르게 인식하고, 이를 이차방정식으로 변환하여 풀면 된다. 항상 조건($n$은 자연수, $n \\geq 2$)을 확인하여 불필요한 해를 제거하는 것이 중요하다.",
