    "explanation": "**[핵심 개념]**\n이 문제는 조건부 순열 문제이다. 6개의 원소 중 짝수(2, 4, 6)의 상대적 위치는 고정되어야 하고, 홀수(1, 3, 5)는 자유롭게 배치되는 상황이다. 이는 조합론의 \"제약 조건이 있는 순열\"을 다루는 문제로, 먼저 제약이 있는 원소들의 배치를 고정한 후 나머지 원소들을 삽입하는 방법을 사용한다.\n\n**[풀이]**\n\n**Step 1: 짝수와 홀수 분류**\n- 짝수: 2, 4, 6 (3개)\n- 홀수: 1, 3, 5 (3개)\n\n**Step 2: 짝수의 배치 고정**\n짝수끼리는 크기 순서대로(2 < 4 < 6) 나열되어야 한다. \n\n6개의 위치 중에서 짝수 3개가 들어갈 위치를 선택하면, 그 위치에는 자동으로 2, 4, 6이 순서대로 배치된다.\n\n따라서 짝수 3개의 배치 방법은 정확히 1가지이다.\n\n**Step 3: 짝수가 배치된 후 홀수 삽입**\n6개 위치 중 3개를 짝수가 차지하면, 나머지 3개 위치에 홀수 3개를 배치해야 한다.\n\n예를 들어, 짝수의 위치가 정해지면:\n- (2, _, 4, _, 6, _) 형태로 3개의 빈 자리가 생김\n\n**Step 4: 홀수 배치 계산**\n남은 3개 위치에 홀수 1, 3, 5를 배치하는 경우의 수는:\n$$3! = 6$$\n\n**Step 5: 다른 방식으로의 접근 (검증)**\n일렬로 6개를 배치하되, 짝수 3개의 상대 위치만 고정된 경우:\n\n$$\\binom{6}{3} \\times 3! = 20 \\times 6 = 120$$\n\n여기서 $\\binom{6}{3}$는 6개 위치 중 짝수 3개가 들어갈 위치를 선택하는 경우의 수이고, $3!$은 홀수 3개를 배치하는 경우의 수이다.\n\n**[정답 확인]**\n짝수의 상대적 순서는 고정(1가지)되고, 6개 위치 중 짝수 위치 선택 $\\binom{6}{3}=20$가지와 홀수 배치 $3!=6$가지를 곱하면 $20 \\times 6 = 120$이다.\n\n**[오답 분석]**\n- **720**: $6!$을 계산한 경우 - 짝수들이 임의로 배치되는 모든 경우를 센 오류\n- **360**: $\\frac{6!}{2}$ 등으로 계산한 경우 - 제약 조건을 불완전하게 반영\n- **60**: $\\binom{6}{3} \\times 3!/2$ 등 잘못된 공식 적용\n\n**[핵심 포인트]**\n조건부 순열에서는 **제약이 있는 원소들의 배치를 먼저 고정한 후**, 나머지 원소들을 자유롭게 배치하는 방법을 사용한다. 이 경우 $\\binom{6}{3} \\times 3!$ 구조로 해결된다.",
