    "explanation": "**[핵심 개념]**\n이 문제는 구별되는 객체를 구별되지 않는 그룹으로 나누고, 그 그룹들을 구별되는 상자(교실)에 배정하는 문제이다.\n- 조합론에서 집합의 분할(partition)과 배정(assignment)을 함께 다루는 문제\n- 순서가 있는 분할(ordered partition): 같은 크기의 조가 없으므로 각 조가 구별됨\n- 최종 배정: 만들어진 조를 A, B, C 교실에 배정\n\n**[풀이]**\n\n**1단계: 6명을 (3명, 2명, 1명)의 세 조로 나누기**\n\n6명 중 3명을 선택: $\\binom{6}{3}$\n남은 3명 중 2명을 선택: $\\binom{3}{2}$\n남은 1명은 자동으로 한 조: $\\binom{1}{1}$\n\n$$\\binom{6}{3} \\times \\binom{3}{2} \\times \\binom{1}{1} = 20 \\times 3 \\times 1 = 60$$\n\n**2단계: 조와 교실의 대응 확인**\n\n문제에서 \"3명의 조를 A 교실에, 2명의 조를 B 교실에, 1명의 조를 C 교실에 배정\"한다고 명시되어 있다. (또는 문맥상 조의 크기가 이미 정해져 있음)\n\n따라서 조를 나누는 방법의 수가 곧 배정의 경우의 수이다.\n\n$$\\text{전체 경우의 수} = 60$$\n\n**[정답 확인]**\n6명을 크기가 다른 (3, 2, 1)의 조로 나누고 순서가 정해진 교실에 배정하는 경우는 $\\binom{6}{3} \\times \\binom{3}{2} \\times \\binom{1}{1} = 60$가지이다.\n\n**[오답 분석]**\n- ① 30: $60 \\div 2$로 계산한 경우 (중복을 잘못 제거)\n- ③ 90: $60 \\times 1.5$로 계산한 경우 (근거 없음)\n- ④ 120: $60 \\times 2$로 계산한 경우 (조를 교실에 배정하는 순열 $3!$을 잘못 곱함)\n- ⑤ 180: $60 \\times 3$으로 계산한 경우 (추가 배정을 오류로 적용)\n\n**[핵심 포인트]**\n구별되는 크기의 조(3명, 2명, 1명)는 이미 다르므로, 조를 나누는 방법이 곧 결과이다. 같은 크기의 조가 있을 때만 중복 제거 $(n_1! \\times n_2! \\times \\cdots)$가 필요하다.",
