    "answer": 6,
    "explanation": "**[핵심 개념]**\n- 중복순열: 같은 원소가 있을 때 순열의 개수는 $\\frac{n!}{n_1! \\times n_2! \\times \\cdots}$ 형태로 계산\n- 조건부 경우의 수: 특정 조건(여기서는 30000 이상)을 만족하는 경우를 먼저 분류한 후 계산\n- 만의 자리 수가 3 이상이면 30000 이상의 수가 됨\n\n**[풀이]**\n\n30000 이상이 되려면 만의 자리 숫자가 3 이상이어야 한다.\n\n주어진 숫자: 1, 1, 2, 2, 3\n\n만의 자리에 올 수 있는 숫자는 3뿐이다. (1, 2는 30000 미만)\n\n**Step 1: 만의 자리에 3을 고정**\n\n만의 자리에 3을 배치하면, 나머지 네 자리에 배치할 숫자는:\n$$1, 1, 2, 2$$\n\n**Step 2: 나머지 네 자리 배열의 개수 계산**\n\n네 개의 숫자 1, 1, 2, 2를 네 자리에 배열하는 경우의 수는:\n\n$$\\frac{4!}{2! \\times 2!} = \\frac{24}{2 \\times 2} = \\frac{24}{4} = 6$$\n\n이는 다음과 같이 이해할 수 있다:\n- 4개를 모두 다르다고 가정하면 $4! = 24$가지\n- 같은 1이 2개 있으므로 $2!$로 나눔\n- 같은 2가 2개 있으므로 $2!$로 나눔\n\n**Step 3: 구체적인 예시**\n\n실제로 나열하면:\n- 1, 1, 2, 2\n- 1, 2, 1, 2\n- 1, 2, 2, 1\n- 2, 1, 1, 2\n- 2, 1, 2, 1\n- 2, 2, 1, 1\n\n정확히 6가지이다.\n\n따라서 30000 이상인 다섯 자리 수의 개수는 **6개**이다.\n\n**[정답 확인]**\n만의 자리에 3을 고정했을 때, 남은 1, 1, 2, 2를 배열하는 중복순열 $\\frac{4!}{2! \\times 2!} = 6$이 답이다.\n\n**[오답 분석]**\n객관식이 없으므로 생략.\n\n**[핵심 포인트]**\n1. 조건을 만족하려면 만의 자리 숫자를 먼저 결정해야 함 (3만 가능)\n2. 중복된 원소가 있을 때는 중복순열 공식 $\\frac{n!}{n_1! \\times n_2!}$를 사용",
