    "explanation": "**[핵심 개념]**\n조건부 경우의 수 문제로, 두 가지 제약 조건을 동시에 만족하는 경우를 구해야 한다.\n- A가 왼쪽에서 3번째 이내: 1, 2, 3번째 위치 중 하나\n- B가 오른쪽에서 3번째 이내: 5, 6, 7번째 위치 중 하나 (전체 7명 기준)\n- 포함-배제 원리를 사용하여 중복을 제거한다.\n\n**[풀이]**\n\n**Step 1: 조건을 위치로 변환**\n- A의 가능한 위치: 1, 2, 3번째 (왼쪽에서 3번째 이내)\n- B의 가능한 위치: 5, 6, 7번째 (오른쪽에서 3번째 이내, 즉 전체 7명 중 뒤에서 3번째까지)\n\n**Step 2: A와 B의 위치가 겹치는지 확인**\nA의 위치(1, 2, 3)와 B의 위치(5, 6, 7)는 겹치지 않으므로, 두 조건은 독립적이다.\n\n**Step 3: 경우의 수 계산**\n\n$A$가 들어갈 위치를 선택: 3가지\n$B$가 들어갈 위치를 선택: 3가지\n선택된 위치에 $A, B$를 배치: $1 \\times 1 = 1$가지\n\n남은 5명의 학생을 남은 5개 위치에 배열: $5!$ 가지\n\n**Step 4: 전체 경우의 수**\n\n$$\\text{경우의 수} = 3 \\times 3 \\times 5! = 9 \\times 120 = 1080$$\n\n**[정답 확인]**\nA와 B의 허용 위치 범위가 서로 겹치지 않아 독립적으로 선택할 수 있으며, 나머지 5명을 $5! = 120$가지로 배열하므로 $3 \\times 3 \\times 120 = 1080$이 정답이다.\n\n**[오답 분석]**\n- **② 1200**: $5 \\times 4 \\times 5! = 2400$의 절반. A 또는 B의 가능 위치를 4가지로 잘못 계산\n- **③ 1320**: $3 \\times 4 \\times 5! + 120$으로 계산. B의 위치를 4가지로 오계산하거나 추가 항을 더함\n- **④ 1440**: $4 \\times 3 \\times 5! = 1440$. A의 가능 위치를 4가지로 잘못 포함\n- **⑤ 1560**: $13 \\times 5! = 1560$. 두 조건을 합으로 잘못 계산하여 $3 + 3 + 7 = 13$으로 처리\n\n**[핵심 포인트]**\n- **왼쪽에서 3번째 이내** = 1, 2, 3번째 (3가지)\n- **오른쪽에서 3번째 이내** = 뒤에서 3번째까지 = 5, 6, 7번째 (3가지)\n- 두 범위가 겹치지 않을 때는 각 조건을 독립적으로 계산하고 나머지를 배열한다.",
