    "problem": "자연수 1, 2, 3, 4, 5, 6, 7 중 서로 다른 4개를 택하여 만든 네 자리 수 중, 각 자릿수가 왼쪽에서 오른쪽으로 갈수록 증가하거나 감소하는 수의 개수를 구하시오.",
    "answerType": "short",
