    "answer": 70,
    "explanation": "**[핵심 개념]**\n네 자리 수의 각 자릿수가 \"왼쪽에서 오른쪽으로 증가하거나 감소\"한다는 것은 다음을 의미한다:\n- **증가 수열**: $a_1 < a_2 < a_3 < a_4$ (예: 1357)\n- **감소 수열**: $a_1 > a_2 > a_3 > a_4$ (예: 7531)\n\n1부터 7까지의 서로 다른 4개 숫자를 선택하는 경우, 일단 4개를 선택하면 이를 배열하는 방법은 **증가 수열 1가지, 감소 수열 1가지** 뿐이다.\n\n**[풀이]**\n\n**Step 1: 증가하는 수열의 개수**\n\n1부터 7까지 중 서로 다른 4개를 선택한다. 4개를 선택하면, 이들을 작은 순서대로 배열하면 자동으로 증가 수열이 된다.\n\n선택하는 경우의 수:\n$$\\binom{7}{4} = \\frac{7!}{4! \\cdot 3!} = \\frac{7 \\times 6 \\times 5}{3 \\times 2 \\times 1} = 35$$\n\n예시: {1, 3, 5, 7}을 선택하면 → 1357만 가능\n\n**Step 2: 감소하는 수열의 개수**\n\n1부터 7까지 중 서로 다른 4개를 선택한다. 4개를 선택하면, 이들을 큰 순서대로 배열하면 자동으로 감소 수열이 된다.\n\n선택하는 경우의 수:\n$$\\binom{7}{4} = 35$$\n\n예시: {1, 3, 5, 7}을 선택하면 → 7531만 가능\n\n**Step 3: 중복 확인**\n\n증가하는 수열과 감소하는 수열이 같을 수 있는가?\n\n네 자리 수가 $a_1 < a_2 < a_3 < a_4$이면서 동시에 $a_1 > a_2 > a_3 > a_4$일 수 없다.\n(모순이므로 중복은 없다)\n\n**Step 4: 전체 개수**\n\n$$\\text{총 개수} = 35 + 35 = 70$$\n\n**[정답 확인]**\n1부터 7까지 중 4개를 선택하는 모든 경우($\\binom{7}{4} = 35$)에 대해, 선택된 4개 숫자는 증가 수열 또는 감소 수열 중 정확히 하나의 형태로만 배열되므로, 총 $35 + 35 = 70$이다.\n\n**[오답 분석]**\n선택지가 없으므로 생략한다.\n\n**[핵심 포인트]**\n- **조합의 본질**: 서로 다른 4개를 선택하면, 증가/감소 배열은 자동 결정됨\n- **중복 제거**: 같은 4개 숫자 집합은 증가 또는 감소 중 하나로만 계산되어 중복이 없음",
