    "explanation": "**[핵심 개념]**\n조합(Combination)은 n개의 서로 다른 원소 중에서 순서를 고려하지 않고 r개를 선택하는 경우의 수이다. 조합의 공식은 :\n\n$$\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$$\n\n여기서 $n!$은 n의 팩토리얼로, $n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 2 \\times 1$을 의미한다.\n\n**[풀이]**\n$\\binom{8}{3}$을 구하기 위해 조합 공식에 $n=8$, $r=3$을 대입한다.\n\n$$\\binom{8}{3} = \\frac{8!}{3!(8-3)!} = \\frac{8!}{3! \\times 5!}$$\n\n분자와 분모를 전개하면:\n\n$$\\binom{8}{3} = \\frac{8 \\times 7 \\times 6 \\times 5!}{3! \\times 5!}$$\n\n$5!$은 분자와 분모에서 약분된다:\n\n$$\\binom{8}{3} = \\frac{8 \\times 7 \\times 6}{3!} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1}$$\n\n분자를 계산하면:\n$$8 \\times 7 \\times 6 = 336$$\n\n분모를 계산하면:\n$$3 \\times 2 \\times 1 = 6$$\n\n따라서:\n$$\\binom{8}{3} = \\frac{336}{6} = 56$$\n\n**[정답 확인]**\n$\\frac{336}{6} = 56$이므로 정답은 56이다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으므로 일반적인 오류를 안내한다:\n- **40**: $\\frac{8 \\times 7 \\times 5}{6}$ 등으로 잘못 계산한 경우\n- **28**: $\\binom{8}{3}$을 $\\binom{8}{2} = 28$과 혼동한 경우\n- **336**: 분모인 $3!$을 나누지 않은 경우\n\n**[핵심 포인트]**\n조합을 계산할 때는 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$에서 분자의 팩토리얼과 분모의 $(n-r)!$이 약분되므로, $\\binom{n}{r} = \\frac{n \\times (n-1) \\times \\cdots \\times (n-r+1)}{r!}$ 형태로 계산하면 더 효율적이다.",
