    "explanation": "**[핵심 개념]**\n이 문제는 조합(Combination) 문제이다. 10명 중에서 4명을 뽑을 때 순서가 중요하지 않으므로 조합을 사용해야 한다. 조합의 공식은 $C(n,r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이며, 이는 n개 중에서 순서를 고려하지 않고 r개를 선택하는 경우의 수이다.\n\n**[풀이]**\n10명 중에서 대표 4명을 뽑는 경우의 수는 조합 $C(10,4)$를 이용한다.\n\n$$C(10,4) = \\frac{10!}{4!(10-4)!} = \\frac{10!}{4! \\cdot 6!}$$\n\n분자와 분모를 정리하면:\n\n$$C(10,4) = \\frac{10 \\times 9 \\times 8 \\times 7 \\times 6!}{4! \\times 6!}$$\n\n$6!$은 약분되므로:\n\n$$C(10,4) = \\frac{10 \\times 9 \\times 8 \\times 7}{4!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1}$$\n\n분자를 계산하면:\n$$10 \\times 9 \\times 8 \\times 7 = 5040$$\n\n분모를 계산하면:\n$$4! = 24$$\n\n따라서:\n$$C(10,4) = \\frac{5040}{24} = 210$$\n\n**[정답 확인]**\n10명 중 4명을 순서 없이 선택하는 조합 공식을 정확히 적용하면 $\\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = 210$이 된다.\n\n**[오답 분석]**\n- ① 120: $5! = 120$으로, 5명을 배열하는 순열과 혼동한 경우\n- ② 150: 계산 실수로 약분을 잘못 처리한 경우\n- ③ 180: 분자나 분모 계산 중 오류가 있는 경우\n- ⑤ 5040: 분자인 $10 \\times 9 \\times 8 \\times 7$만 계산하고 분모 $4!$로 나누지 않은 경우 (순열 $P(10,4)$를 구한 것)\n\n**[핵심 포인트]**\n\"대표를 뽑는다\" = 순서가 없다 = 조합을 사용한다. 순열과 조합을 구분하는 것이 가장 중요하며, 계산 시 약분을 통해 간단히 정리하는 습관이 필요하다.",
