    "explanation": "**[핵심 개념]**\n조합(Combination)은 순서를 고려하지 않고 n개의 서로 다른 것 중에서 r개를 선택하는 경우의 수이다. 조합의 공식은 :\n\n$$C(n, r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$$\n\n이 문제는 9개의 서로 다른 과일 중에서 2개를 선택하는데, 선택된 과일의 순서는 중요하지 않으므로 조합 문제이다.\n\n**[풀이]**\n주어진 조건을 정리하면:\n- 전체 과일의 개수: $n = 9$\n- 선택할 과일의 개수: $r = 2$\n\n조합 공식을 적용한다:\n\n$$C(9, 2) = \\frac{9!}{2!(9-2)!} = \\frac{9!}{2! \\cdot 7!}$$\n\n분자와 분모를 정리하면:\n\n$$C(9, 2) = \\frac{9 \\times 8 \\times 7!}{2 \\times 1 \\times 7!} = \\frac{9 \\times 8}{2 \\times 1}$$\n\n계산한다:\n\n$$C(9, 2) = \\frac{72}{2} = 36$$\n\n**[정답 확인]**\n9개의 과일 중 2개를 순서 없이 선택하는 조합 $C(9,2) = \\frac{9 \\times 8}{2} = 36$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n- ① 18: $\\frac{9 \\times 8}{4}$로 계산한 경우 (분모를 잘못 계산)\n- ② 27: $9 \\times 3$으로 임의로 계산한 경우 (조합 공식을 적용하지 않음)\n- ④ 45: $\\frac{9 \\times 10}{2}$로 계산한 경우 (n값을 잘못 사용)\n- ⑤ 72: $9 \\times 8$로 계산한 경우 (순열 $P(9,2)$를 계산하거나 분모를 빠뜨린 경우)\n\n**[핵심 포인트]**\n조합은 순서를 고려하지 않으므로 반드시 분모에 $r!$를 나누어야 한다. 순열과 조합을 혼동하지 않도록 주의하세요. 간단한 2개 선택 문제에서는 $C(n,2) = \\frac{n(n-1)}{2}$ 공식을 빠르게 활용할 수 있다.",
