    "problem": "직선 위에 있지 않은 6개의 점으로 만들 수 있는 삼각형의 개수를 구하시오. (단, 어떤 세 점도 일직선 위에 있지 않습니다.)",
    "answerType": "short",
    "choices": null,
    "answer": 20,
    "explanation": "**[핵심 개념]**\n\n삼각형을 만들기 위한 조건은 서로 다른 3개의 점이 필요하며, 이 3개의 점이 일직선 위에 있지 않아야 한다. 이 문제에서는 \"어떤 세 점도 일직선 위에 있지 않다\"는 조건이 주어졌으므로, 6개의 점 중에서 임의로 선택한 3개의 점은 항상 삼각형을 이룹니다. 따라서 조합(combination)을 이용하여 6개의 점 중 3개를 선택하는 경우의 수를 구하면 된다.\n\n**[풀이]**\n\n직선 위에 있지 않은 6개의 점이 있고, 어떤 세 점도 일직선 위에 있지 않다는 것은 다음을 의미한다:\n- 6개의 점 중 임의로 3개를 선택하면 항상 삼각형을 만들 수 있다\n\n따라서 구하는 삼각형의 개수는 6개의 점 중에서 순서를 고려하지 않고 3개를 선택하는 조합의 개수와 같다.\n\n$$\\binom{6}{3} = \\frac{6!}{3!(6-3)!} = \\frac{6!}{3! \\cdot 3!}$$\n\n계산 과정:\n$$\\binom{6}{3} = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = \\frac{120}{6} = 20$$\n\n따라서 만들 수 있는 삼각형의 개수는 **20개**이다.\n\n**[정답 확인]**\n\n6개의 점 중 일직선 위의 점이 없고 어떤 세 점도 일직선 위에 있지 않으므로, 모든 3점 조합이 삼각형을 이루며, $\\binom{6}{3} = 20$이 정답이다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 흔한 오류는:\n- **순열을 사용한 경우**: $P(6,3) = 120$ - 삼각형은 점의 순서가 중요하지 않으므로 조합을 사용해야 함\n- **6개 중 2개를 선택한 경우**: $\\binom{6}{2} = 15$ - 삼각형은 3개의 점이 필요\n- **전체 경우에서 일부를 뺀 경우**: 이미 일직선 위의 점이 없다는 조건이 주어졌으므로 추가 계산 불필요\n\n**[핵심 포인트]**\n\n삼각형을 만들기 위해서는 **서로 다른 3개의 점이 일직선 위에 있지 않아야** 한다. 문제에서 이 조건이 보장되면 단순히 $\\binom{n}{3}$을 계산하면 된다.",
