    "answer": 1,
    "explanation": "**[핵심 개념]**\n조합(combination)은 $n$개의 원소 중에서 순서를 고려하지 않고 $r$개를 선택하는 경우의 수이다. 조합의 계산 공식은 :\n\n$$\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$$\n\n또한 파스칼의 삼각형 성질 중 $\\binom{n}{r} + \\binom{n}{r+1} = \\binom{n+1}{r+1}$이 성립한다.\n\n**[풀이]**\n\n방법 1: 직접 계산\n\n$\\binom{7}{3}$을 계산한다:\n$$\\binom{7}{3} = \\frac{7!}{3!(7-3)!} = \\frac{7!}{3! \\cdot 4!} = \\frac{7 \\times 6 \\times 5}{3 \\times 2 \\times 1} = \\frac{210}{6} = 35$$\n\n$\\binom{7}{4}$를 계산한다:\n$$\\binom{7}{4} = \\frac{7!}{4!(7-4)!} = \\frac{7!}{4! \\cdot 3!} = \\frac{7 \\times 6 \\times 5}{3 \\times 2 \\times 1} = \\frac{210}{6} = 35$$\n\n따라서:\n$$\\binom{7}{3} + \\binom{7}{4} = 35 + 35 = 70$$\n\n방법 2: 파스칼의 성질 이용\n\n조합의 성질 $\\binom{n}{r} + \\binom{n}{r+1} = \\binom{n+1}{r+1}$을 적용하면:\n$$\\binom{7}{3} + \\binom{7}{4} = \\binom{8}{4}$$\n\n$\\binom{8}{4}$를 계산한다:\n$$\\binom{8}{4} = \\frac{8!}{4! \\cdot 4!} = \\frac{8 \\times 7 \\times 6 \\times 5}{4 \\times 3 \\times 2 \\times 1} = \\frac{1680}{24} = 70$$\n\n**[정답 확인]**\n두 방법 모두 70이라는 동일한 답을 얻으므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ① 56: $\\binom{8}{3}$의 값이며, 계산 실수로 조합값을 잘못 구한 경우\n- ③ 84: $\\binom{7}{3} \\times 2 + 14$ 같은 계산 오류\n- ④ 105: $\\binom{7}{3} + \\binom{7}{4} + \\binom{7}{5}$처럼 세 항을 더한 경우\n- ⑤ 126: $\\binom{9}{2}$의 값이며, 조합 공식을 잘못 적용한 경우\n\n**[핵심 포인트]**\n조합 문제에서는 $\\binom{n}{r} = \\binom{n}{n-r}$의 대칭성과 $\\binom{n}{r} + \\binom{n}{r+1} = \\binom{n+1}{r+1}$의 파스칼 성질을 활용하면 계산을 간단히 할 수 있다.",
