    "explanation": "**[핵심 개념]**\n조합(Combination)은 순서를 고려하지 않고 n개 중에서 r개를 선택하는 경우의 수이다. 조합의 공식은 $C(n,r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$ 이다. 이 문제에서는 12명 중 11명을 선택하므로 순서가 없는 조합 문제이다.\n\n**[풀이]**\n12명 중 11명을 선발하는 경우의 수를 구해야 한다.\n\n$$C(12, 11) = \\binom{12}{11} = \\frac{12!}{11!(12-11)!}$$\n\n분모를 정리하면:\n$$= \\frac{12!}{11! \\times 1!}$$\n\n분자와 분모를 전개하면:\n$$= \\frac{12 \\times 11!}{11! \\times 1}$$\n\n$11!$을 약분하면:\n$$= \\frac{12}{1} = 12$$\n\n**다른 방법으로 생각하기:**\n12명 중 11명을 선발한다는 것은 12명 중 1명을 제외한다는 의미이다. 제외할 선수를 선택하는 경우의 수는 12명 중 1명을 고르는 것이므로:\n$$C(12, 1) = 12$$\n\n**[정답 확인]**\n12명 중 11명을 선발하는 경우의 수는 제외할 1명을 선택하는 것과 같으므로 12가지이다.\n\n**[오답 분석]**\n- ① 11: 선발 인원 수를 답으로 잘못 선택한 경우\n- ③ 22: $12 \\times 2$로 계산하는 실수. 조합 공식을 잘못 적용한 경우\n- ④ 66: $\\binom{12}{2} = \\frac{12 \\times 11}{2} = 66$으로, 2명을 선택하는 경우와 혼동한 경우\n- ⑤ 132: $12 \\times 11 = 132$로, 순열로 잘못 계산한 경우\n\n**[핵심 포인트]**\n$C(n, r) = C(n, n-r)$ 성질을 기억하세요. 12명 중 11명을 선택하는 것은 12명 중 1명을 제외하는 것과 같으므로, 복잡한 계산 대신 $C(12, 1) = 12$로 간단히 구한다.",
