    "explanation": "**[핵심 개념]**\n두 점을 지나는 직선은 유일하게 결정된다. 따라서 서로 다른 n개의 점에서 만들 수 있는 직선의 개수는 이 n개의 점 중 2개를 선택하는 조합의 수와 같다. 즉, $\\binom{n}{2} = \\frac{n(n-1)}{2}$ 이다.\n\n단, 조건으로 \"어떤 세 점도 일직선 위에 있지 않다\"는 것은 선택한 2개의 점이 항상 서로 다른 직선을 결정한다는 의미이다.\n\n**[풀이]**\n\n**1단계: 조합 공식 적용**\n\n5개의 서로 다른 점 중에서 2개를 선택하는 경우의 수를 구한다.\n\n$$\\binom{5}{2} = \\frac{5!}{2!(5-2)!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**2단계: 조건 검토**\n\n문제에서 \"어떤 세 점도 일직선 위에 있지 않다\"는 조건이 주어졌다. 이는 다음을 의미한다:\n- 5개의 점 중 임의의 2개를 선택할 때마다 항상 서로 다른 직선을 만든다\n- 3개 이상의 점이 한 직선 위에 있지 않으므로, 중복되는 직선이 없다\n\n**3단계: 최대값 결정**\n\n따라서 5개의 점으로 만들 수 있는 직선의 최대 개수는:\n\n$$\\text{직선의 개수} = \\binom{5}{2} = 10$$\n\n**[정답 확인]**\n\n조건에서 세 점 이상이 일직선 위에 있지 않으므로, 5개 점 중 2개씩 선택한 모든 조합이 서로 다른 직선을 만들어 정확히 10개이다.\n\n**[오답 분석]**\n\n선택지가 없어 직접 오답 분석은 불가하지만, 흔한 오류는:\n- **9개**: 중복을 잘못 계산한 경우\n- **15개**: 순서쌍 $P(5,2) = 20$에서 잘못 계산한 경우\n- **20개**: $5 \\times 4 = 20$으로 조합이 아닌 순열을 계산한 경우\n\n**[핵심 포인트]**\n\n- 직선의 개수 = $\\binom{n}{2} = \\frac{n(n-1)}{2}$ 공식을 반드시 기억할 것\n- \"세 점이 일직선 위에 있지 않다\"는 조건은 모든 직선이 서로 다름을 보장하므로, 중복을 제거할 필요가 없다는 의미이다.",
