    "_type": "combination",
    "type": "조합",
    "problem": "동아리 부원 15명 중 활동비를 낼 3명을 뽑는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 455,
    "explanation": "**[핵심 개념]**\n이 문제는 조합 문제이다. 15명 중에서 3명을 선택하는데, 선택되는 순서가 중요하지 않으므로 조합을 사용한다.\n조합의 공식은 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$ 이다.\n여기서 $n=15$ (전체 부원), $r=3$ (선택할 인원)이다.\n\n**[풀이]**\n\n15명 중 3명을 선택하는 경우의 수는:\n\n$$\\binom{15}{3} = \\frac{15!}{3!(15-3)!} = \\frac{15!}{3! \\times 12!}$$\n\n분자와 분모를 정리하면:\n\n$$\\binom{15}{3} = \\frac{15 \\times 14 \\times 13 \\times 12!}{3! \\times 12!} = \\frac{15 \\times 14 \\times 13}{3!}$$\n\n분모를 계산하면:\n\n$$3! = 3 \\times 2 \\times 1 = 6$$\n\n분자를 계산하면:\n\n$$15 \\times 14 \\times 13 = 210 \\times 13 = 2730$$\n\n따라서:\n\n$$\\binom{15}{3} = \\frac{2730}{6} = 455$$\n\n**[정답 확인]**\n$\\frac{2730}{6} = 455$이므로 정답은 455이다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으므로, 흔한 오류를 소개한다:\n- **순열 공식을 사용한 경우**: $P(15,3) = 15 \\times 14 \\times 13 = 2730$ → 순서를 고려해야 할 때만 사용\n- **잘못된 계산**: 분자나 분모 계산 실수로 다른 값 도출\n\n**[핵심 포인트]**\n- 조합은 **순서가 없는** 선택이므로 $\\binom{n}{r}$ 공식을 사용한다.\n- \"~명을 뽑는다\" = 조합, \"~명을 배열한다\" = 순열로 구분하세요.",
