    "answer": 2,
    "explanation": "**[핵심 개념]**\n조합(Combination)은 n개의 원소 중에서 순서를 고려하지 않고 r개를 선택하는 경우의 수이다. 공식은 $C(n,r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이다.\n\n\"특정 원소가 반드시 포함되는 경우\"는 그 원소를 미리 선택하고, 나머지 원소들 중에서 필요한 개수를 선택하는 조합 문제이다.\n\n**[풀이]**\n\n**1단계: 문제 상황 정리**\n- 전체 학생: 8명\n- 반장 후보를 뽑는 인원: 3명\n- 조건: 학생 A는 반드시 포함되어야 함\n\n**2단계: 조건 적용**\n학생 A가 반드시 포함되므로, A는 이미 선택된 것으로 간주한다.\n- A를 제외한 나머지 학생: $8 - 1 = 7$명\n- 추가로 뽑아야 할 후보: $3 - 1 = 2$명\n\n**3단계: 조합 계산**\n7명의 학생 중에서 2명을 선택하는 경우의 수:\n\n$$C(7,2) = \\binom{7}{2} = \\frac{7!}{2!(7-2)!} = \\frac{7 \\times 6}{2 \\times 1} = \\frac{42}{2} = 21$$\n\n**4단계: 결론**\n따라서 학생 A가 반드시 포함되는 경우의 수는 **21**이다.\n\n**[정답 확인]**\nA를 포함하여 3명을 선택하는 것 = A를 먼저 고정하고, 나머지 7명 중 2명을 선택하는 것 = $C(7,2) = 21$\n\n**[오답 분석]**\n- ① 7: $C(7,1)$의 값으로, 2명이 아닌 1명만 선택한 경우\n- ② 14: 계산 실수 또는 $C(7,2) \\times \\frac{2}{3}$을 잘못 계산한 경우\n- ④ 28: $C(8,3) \\times \\frac{3}{8}$을 잘못 계산했거나, 다른 공식을 혼용한 경우\n- ⑤ 35: $C(7,3)$의 값으로, 전체 7명 중 3명을 선택하는 경우(A의 조건을 무시한 경우)\n\n**[핵심 포인트]**\n**\"특정 원소가 반드시 포함\"된다는 조건은 그 원소를 미리 선택하고 시작하는 것과 같다.** 따라서 (전체 n명 중 r명 선택) 문제를 (n-1명 중 r-1명 선택) 문제로 축소하여 풀면 된다.",
