    "answer": 2,
    "explanation": "**[핵심 개념]**\n조합 문제에서 \"동시에 포함되지 않는다\"는 조건은 여사건을 이용하여 풀 수 있다. 전체에서 조건을 위반하는 경우를 빼는 방법을 사용한다.\n- 조합의 정의: $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$\n- 여사건 활용: (구하는 경우의 수) = (전체) - (P와 Q가 동시에 포함되는 경우)\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n10명 중 5명을 뽑는 모든 경우의 수를 구한다.\n$$\\binom{10}{5} = \\frac{10!}{5! \\cdot 5!} = \\frac{10 \\times 9 \\times 8 \\times 7 \\times 6}{5 \\times 4 \\times 3 \\times 2 \\times 1} = 252$$\n\n**2단계: P와 Q가 동시에 포함되는 경우의 수**\nP와 Q가 반드시 포함되는 경우, 이미 2명이 선택되었으므로 나머지 8명 중에서 3명을 추가로 선택한다.\n$$\\binom{8}{3} = \\frac{8!}{3! \\cdot 5!} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$$\n\n**3단계: 여사건을 이용한 계산**\nP와 Q가 동시에 포함되지 않는 경우의 수는:\n$$\\binom{10}{5} - \\binom{8}{3} = 252 - 56 = 196$$\n\n**[정답 확인]**\n전체 경우의 수에서 조건을 위반하는 경우(P, Q 동시 포함)를 제거하면 196이 되어 정답이다.\n\n**[오답 분석]**\n- ① 126: $\\binom{10}{5}$를 잘못 계산한 경우\n- ② 168: $\\binom{10}{5} - \\binom{8}{3}$를 계산 오류로 잘못 구한 경우\n- ④ 210: 전체 경우의 수만 구한 후 다른 방식으로 계산하려다 실패한 경우\n- ⑤ 252: 전체 경우의 수만 구하고 조건을 적용하지 않은 경우\n\n**[핵심 포인트]**\n\"동시에 포함되지 않는다\" = \"동시에 포함되는 경우를 제외\"이므로 여사건 활용이 핵심이다. 조건이 있는 조합 문제는 (전체) - (조건 위반)으로 접근하는 것이 가장 효율적이다.",
