    "explanation": "**[핵심 개념]**\n\n다각형에서 대각선의 개수를 구하는 문제이다. \n- **대각선**: 다각형의 두 꼭짓점을 이은 선분 중에서 변(edge)이 아닌 것\n- n각형에서 두 꼭짓점을 선택하는 경우의 수: $\\binom{n}{2} = \\frac{n(n-1)}{2}$\n- 대각선의 개수 = (모든 선분의 개수) - (변의 개수)\n\n**[풀이]**\n\n**1단계: 정육각형의 꼭짓점에서 선택할 수 있는 모든 선분의 개수**\n\n정육각형은 6개의 꼭짓점을 가지므로, 이 중 2개를 선택하는 경우의 수는:\n$$\\binom{6}{2} = \\frac{6 \\times 5}{2} = 15$$\n\n**2단계: 정육각형의 변의 개수**\n\n정육각형은 6개의 변을 가진다.\n\n**3단계: 대각선의 개수 계산**\n\n대각선은 두 꼭짓점을 이은 선분 중에서 변이 아닌 것이므로:\n$$\\text{대각선의 개수} = 15 - 6 = 9$$\n\n**[정답 확인]**\n\n정육각형에서 6개 꼭짓점 중 2개를 선택하는 모든 경우(15개)에서 변(6개)을 제외하면 9개의 대각선이 만들어진다.\n\n**[오답 분석]**\n\n- **① 6**: 정육각형의 변의 개수와 혼동한 오답\n- **② 8**: 계산 실수로 변의 개수를 잘못 제외한 경우\n- **④ 12**: 전체 선분에서 일부만 뺀 경우의 오답\n- **⑤ 15**: 변을 전혀 제외하지 않고 모든 선분의 개수를 답으로 한 오답\n\n**[핵심 포인트]**\n\n**대각선의 개수 = $\\binom{n}{2} - n = \\frac{n(n-1)}{2} - n = \\frac{n(n-3)}{2}$**\n\n정육각형의 경우: $\\frac{6(6-3)}{2} = \\frac{6 \\times 3}{2} = 9$",
