    "problem": "방정식 $x + y + z = 10$을 만족시키는 음이 아닌 정수해 $(x, y, z)$의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 66,
    "explanation": "**[핵심 개념]**\n음이 아닌 정수해의 개수를 구하는 문제는 조합론의 \"중복조합\" 또는 \"stars and bars\" 방법을 사용한다.\n\n$x + y + z = n$을 만족하는 음이 아닌 정수해의 개수는 $\\binom{n+k-1}{k-1}$이다.\n여기서 $n$은 합의 값, $k$는 변수의 개수이다.\n\n이는 $n$개의 동일한 공을 $k$개의 서로 다른 상자에 넣는 경우의 수와 같다.\n\n**[풀이]**\n\n주어진 방정식: $x + y + z = 10$ (단, $x, y, z \\geq 0$인 정수)\n\n**Step 1: 공식 적용**\n- 합의 값: $n = 10$\n- 변수의 개수: $k = 3$\n\n**Step 2: 중복조합 공식 적용**\n음이 아닌 정수해의 개수는 다음 공식으로 구한다:\n\n$$\\binom{n+k-1}{k-1} = \\binom{10+3-1}{3-1} = \\binom{12}{2}$$\n\n**Step 3: 조합값 계산**\n$$\\binom{12}{2} = \\frac{12!}{2! \\times 10!} = \\frac{12 \\times 11}{2 \\times 1} = \\frac{132}{2} = 66$$\n\n**[정답 확인]**\n중복조합 공식 $\\binom{n+k-1}{k-1} = \\binom{12}{2} = 66$을 정확히 적용하여 구한 답이다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 없음\n\n**[핵심 포인트]**\n- $x + y + z = n$의 음이 아닌 정수해 개수 = $\\binom{n+k-1}{k-1}$ (중복조합)\n- 이 문제에서는 $\\binom{12}{2} = 66$을 기억: 3개 변수, 합이 10일 때의 표준 공식",
