    "answer": 2,
    "explanation": "**[핵심 개념]**\n조합(Combination)은 n개 중에서 r개를 순서 관계없이 선택하는 경우의 수이다. 공식은 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이다. 이 문제에서는 \"제외\"라는 조건이 있으므로, 전체에서 제외할 사람들을 빼고 나머지에서 선택해야 한다.\n\n**[풀이]**\n\n**Step 1: 상황 파악**\n- 전체 인원: 11명\n- 제외할 사람: A, B, C 3명\n- 뽑을 위원: 4명\n\n**Step 2: 실제 선택 가능한 인원 계산**\nA, B, C를 모두 제외하므로, 선택 대상이 되는 사람의 수는:\n$$11 - 3 = 8\\text{명}$$\n\n**Step 3: 조합 계산**\n8명 중에서 4명을 선택하는 경우의 수:\n$$\\binom{8}{4} = \\frac{8!}{4!(8-4)!} = \\frac{8!}{4! \\cdot 4!}$$\n\n**Step 4: 단계별 계산**\n$$\\binom{8}{4} = \\frac{8 \\times 7 \\times 6 \\times 5}{4 \\times 3 \\times 2 \\times 1}$$\n\n분자: $8 \\times 7 \\times 6 \\times 5 = 1680$\n\n분모: $4 \\times 3 \\times 2 \\times 1 = 24$\n\n$$\\binom{8}{4} = \\frac{1680}{24} = 70$$\n\n**[정답 확인]**\n11명에서 특정 3명을 제외하면 8명이 남고, 이 8명 중 4명을 선택하는 $\\binom{8}{4} = 70$이 정답이다.\n\n**[오답 분석]**\n- **① 35**: $\\binom{7}{3} = 35$로, 4명이 아닌 3명을 선택한 경우\n- **② 56**: $\\binom{8}{3} = 56$으로, 4명이 아닌 3명을 선택한 경우\n- **④ 84**: $\\binom{9}{4} = 126$에서 잘못 계산하거나, 제외 인원을 2명으로 잘못 파악한 경우\n- **⑤ 120**: $\\binom{10}{4} = 210$에서 계산 실수하거나, 제외 대상을 잘못 이해한 경우\n\n**[핵심 포인트]**\n\"제외\"라는 조건은 **전체 인원에서 먼저 제외 대상을 빼고 시작**해야 함을 의미한다. 조건 해석 → 실제 선택 대상 결정 → 조합 계산의 순서를 명확히 하는 것이 중요하다.",
