    "problem": "12명 중 5명을 선발하되 A를 포함하고 B를 제외하는 경우의 수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 210,
    "explanation": "**[핵심 개념]**\n\n조합(Combination) 문제이다. 조건부 선택 문제에서는 반드시 포함되어야 할 대상과 반드시 제외되어야 할 대상을 먼저 처리한 후, 남은 대상 중에서 필요한 인원을 선택한다. 조합의 공식은 $C(n,r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$ 이다.\n\n**[풀이]**\n\n**Step 1: 조건 정리**\n- 전체 인원: 12명\n- 선발 인원: 5명\n- A는 반드시 포함\n- B는 반드시 제외\n\n**Step 2: A를 반드시 포함하고 B를 반드시 제외**\n\nA는 반드시 선발되므로, A를 먼저 선택한 것으로 간주한다.\nB는 제외하므로, 선택 대상에서 제거한다.\n\n따라서:\n- 남은 인원: 12명 - (A 1명) - (B 1명) = 10명\n- 남은 선발 인원: 5명 - (A 1명) = 4명\n\n**Step 3: 10명 중 4명 선택**\n\n이제 남은 10명 중에서 4명을 추가로 선택하면 된다.\n\n$$C(10, 4) = \\frac{10!}{4! \\times 6!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1}$$\n\n**Step 4: 계산**\n\n$$C(10, 4) = \\frac{10 \\times 9 \\times 8 \\times 7}{24} = \\frac{5040}{24} = 210$$\n\n**[정답 확인]**\n\nA를 포함하고 B를 제외한 후 남은 10명 중에서 4명을 선택하는 경우의 수는 $C(10,4) = 210$이므로 정답이다.\n\n**[오답 분석]**\n\n선택지가 주어지지 않았으므로 흔한 오류를 설명한다:\n- 흔한 오류 1) $C(12, 5) = 792$를 선택: 조건을 무시하고 단순히 12명 중 5명을 선택한 경우\n- 흔한 오류 2) $C(11, 5) = 462$를 선택: B만 제외하고 A의 반드시 포함 조건을 무시한 경우\n- 흔한 오류 3) $C(10, 5) = 252$를 선택: A와 B를 제외하고 10명 중 5명을 선택한 경우\n\n**[핵심 포인트]**\n\n조건부 선택 문제에서는 **반드시 포함할 대상을 먼저 선택한 후, 나머지 조건을 적용**하는 것이 핵심이다. 이 문제에서는 A를 미리 선택하고(5명 중 1명), 남은 10명 중에서 4명을 선택하는 방식으로 접근한다.",
