    "explanation": "**[핵심 개념]**\n조합 문제에서 \"적어도\"라는 표현이 나올 때는 여집합을 이용하는 것이 효율적이다. \n- 전체에서 조건을 만족하지 않는 경우를 빼는 방법\n- 조합 공식: $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 구하기**\n\n남학생 6명, 여학생 5명(총 11명) 중에서 5명을 선택하는 전체 경우의 수:\n$$\\binom{11}{5} = \\frac{11!}{5! \\cdot 6!} = \\frac{11 \\times 10 \\times 9 \\times 8 \\times 7}{5 \\times 4 \\times 3 \\times 2 \\times 1} = \\frac{55440}{120} = 462$$\n\n**Step 2: 여집합 이용 - 조건을 만족하지 않는 경우**\n\n\"남학생이 적어도 2명\"의 여집합은 \"남학생이 0명 또는 1명\"이다.\n\n**경우 1) 남학생 0명(여학생 5명):**\n$$\\binom{6}{0} \\times \\binom{5}{5} = 1 \\times 1 = 1$$\n\n**경우 2) 남학생 1명(여학생 4명):**\n$$\\binom{6}{1} \\times \\binom{5}{4} = 6 \\times 5 = 30$$\n\n조건을 만족하지 않는 경우의 수: $1 + 30 = 31$\n\n**Step 3: 최종 답 계산**\n\n남학생이 적어도 2명 포함되는 경우의 수:\n$$462 - 31 = 431$$\n\n**[정답 확인]**\n전체 462가지에서 남학생이 0명 또는 1명인 31가지를 제외하면 431가지이다.\n\n**[오답 분석]**\n- ① 401: 계산 실수로 전체에서 61을 뺀 경우\n- ② 411: 조건을 만족하지 않는 경우를 잘못 계산한 경우\n- ③ 421: 여학생 5명을 선택하는 경우(1가지)만 빼고 남학생 1명인 경우를 놓친 오류\n- ⑤ 441: 조건을 만족하지 않는 경우를 과소 계산한 경우\n\n**[핵심 포인트]**\n\"적어도\"가 포함된 조합 문제는 **여집합(전체 - 반대 경우)**을 이용하면 계산이 훨씬 간단한다. 이 경우 남학생 0명 또는 1명인 경우만 제외하면 되어 계산 과정이 단순화된다.",
