    "explanation": "**[핵심 개념]**\n원 위의 n개 점 중에서 k개의 점을 선택하는 조합을 이용한다. 원 위의 점들은 모두 같은 원 위에 있으므로 선택한 점들이 항상 같은 평면상에 있으며, 3개 이상의 점을 선택하면 항상 다각형을 만들 수 있다. 따라서 단순히 조합의 수를 계산하면 된다.\n\n조합 공식: $\\binom{n}{k} = \\frac{n!}{k!(n-k)!}$\n\n**[풀이]**\n\n**1단계: 삼각형의 개수 구하기**\n\n원 위의 10개 점 중에서 3개의 점을 선택하는 경우의 수이다. 원 위의 서로 다른 3개 점은 항상 하나의 삼각형을 결정한다.\n\n$$\\text{삼각형의 개수} = \\binom{10}{3} = \\frac{10!}{3! \\times 7!} = \\frac{10 \\times 9 \\times 8}{3 \\times 2 \\times 1} = \\frac{720}{6} = 120$$\n\n**2단계: 사각형의 개수 구하기**\n\n원 위의 10개 점 중에서 4개의 점을 선택하는 경우의 수이다. 원 위의 서로 다른 4개 점은 항상 하나의 사각형을 결정한다.\n\n$$\\text{사각형의 개수} = \\binom{10}{4} = \\frac{10!}{4! \\times 6!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = \\frac{5040}{24} = 210$$\n\n**3단계: 합 계산하기**\n\n$$\\text{삼각형과 사각형의 합} = 120 + 210 = 330$$\n\n**[정답 확인]**\n원 위의 점들로 만든 도형은 선택된 점의 개수만으로 결정되므로, 조합을 이용하여 계산한 120 + 210 = 330이 정답이다.\n\n**[오답 분석]**\n- ① 210: 사각형의 개수만 계산한 경우\n- ② 280: 계산 실수 (예: 조합 계산 오류)\n- ④ 420: 삼각형과 사각형을 중복으로 계산하거나 다른 다각형까지 포함한 경우\n- ⑤ 630: 원 위의 점들을 구별하지 않고 과도하게 계산한 경우\n\n**[핵심 포인트]**\n원 위의 n개 점 중 k개를 선택하면 항상 하나의 k각형이 만들어진다. 따라서 단순히 조합의 수 $\\binom{n}{k}$를 계산하면 되며, 원의 기하학적 성질은 고려할 필요가 없다.",
