    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n이 문제는 중복조합(또는 조합론의 중복조합 공식)을 이용하는 문제이다. $n$개의 동일한 물건을 $r$개의 서로 다른 상자에 넣는 경우의 수는 $\\binom{n+r-1}{r-1}$이다. \n\n양의 정수 조건이 중요하다. $x, y, z \\geq 1$이므로, 이를 음이 아닌 정수로 변환하는 치환이 필요하다.\n\n**[풀이]**\n\n$x + y + z = 8$을 만족시키는 양의 정수해를 구해야 한다.\n\n$x, y, z$는 모두 1 이상이어야 하므로, 다음과 같이 치환한다:\n- $x' = x - 1$, $y' = y - 1$, $z' = z - 1$\n- 이때 $x', y', z' \\geq 0$ (음이 아닌 정수)\n\n원래 식에 대입하면:\n$$(x' + 1) + (y' + 1) + (z' + 1) = 8$$\n\n$$x' + y' + z' + 3 = 8$$\n\n$$x' + y' + z' = 5$$\n\n이제 $x' + y' + z' = 5$를 만족시키는 음이 아닌 정수해의 개수를 구하면 된다.\n\n중복조합 공식을 적용하면, $n = 5$개의 동일한 물건을 $r = 3$개의 서로 다른 상자에 넣는 경우의 수는:\n\n$$\\binom{n + r - 1}{r - 1} = \\binom{5 + 3 - 1}{3 - 1} = \\binom{7}{2}$$\n\n$$\\binom{7}{2} = \\frac{7 \\times 6}{2 \\times 1} = \\frac{42}{2} = 21$$\n\n**[정답 확인]**\n\n양의 정수 조건을 음이 아닌 정수 조건으로 올바르게 변환한 후, 중복조합 공식 $\\binom{n+r-1}{r-1}$을 적용하여 21을 얻는다.\n\n**[오답 분석]**\n\n- ① 15: $\\binom{6}{2} = 15$로, 변환 과정에서 식을 잘못 세운 경우 (예: $x' + y' + z' = 4$로 계산)\n- ③ 28: $\\binom{8}{2} = 28$로, 양의 정수 조건을 음이 아닌 정수 조건으로 제대로 변환하지 않은 경우\n- ④ 36: $\\binom{9}{2} = 36$로, 중복조합 공식의 계수를 잘못 적용한 경우\n- ⑤ 45: $\\binom{10}{2} = 45$로, 더 큰 값으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n양의 정수 조건($x, y, z \\geq 1$)을 음이 아닌 정수 조건($x', y', z' \\geq 0$)으로 치환하는 것이 핵심이다. 이후 중복조합 공식 $\\binom{n+r-1}{r-1}$을 정확하게 적용하면 된다.",
