    "explanation": "**[핵심 개념]**\n격자에서 직사각형을 만들기 위해서는 가로줄 2개와 세로줄 2개를 선택해야 한다. 직사각형의 개수는 가로줄 중 2개를 선택하는 경우의 수와 세로줄 중 2개를 선택하는 경우의 수의 곱으로 구한다. 이는 조합 공식 $\\binom{n}{2} = \\frac{n(n-1)}{2}$를 사용한다.\n\n**[풀이]**\n\n**1단계: 문제 상황 파악**\n- 가로줄 5개, 세로줄 4개로 이루어진 격자\n- 직사각형을 만들기 위해 필요한 조건: 평행한 가로줄 2개와 평행한 세로줄 2개\n\n**2단계: 가로줄에서 2개 선택**\n5개의 가로줄 중에서 2개를 선택하는 경우의 수:\n$$\\binom{5}{2} = \\frac{5 \\times 4}{2 \\times 1} = \\frac{20}{2} = 10$$\n\n**3단계: 세로줄에서 2개 선택**\n4개의 세로줄 중에서 2개를 선택하는 경우의 수:\n$$\\binom{4}{2} = \\frac{4 \\times 3}{2 \\times 1} = \\frac{12}{2} = 6$$\n\n**4단계: 전체 직사각형의 개수**\n가로줄 2개의 선택과 세로줄 2개의 선택은 독립적이므로, 곱의 법칙을 적용한다:\n$$\\text{직사각형의 개수} = \\binom{5}{2} \\times \\binom{4}{2} = 10 \\times 6 = 60$$\n\n**[정답 확인]**\n가로줄 2개와 세로줄 2개가 만나는 교점들이 직사각형의 네 꼭짓점을 결정하므로, $10 \\times 6 = 60$이 정답이다.\n\n**[오답 분석]**\n- ① 30: $\\binom{5}{2} \\times 2 = 20$이나 $\\binom{4}{2} \\times 5 = 30$으로 계산한 오류\n- ② 40: 계산 실수로 $10 \\times 4 = 40$으로 계산한 오류\n- ③ 50: 대략적으로 추정한 오답\n- ⑤ 80: $\\binom{5}{2} + \\binom{4}{2}$를 곱하지 않고 다른 식으로 계산한 오류\n\n**[핵심 포인트]**\n격자에서 직사각형의 개수는 **\"가로줄 중 2개를 선택하는 경우의 수 × 세로줄 중 2개를 선택하는 경우의 수\"**로 구한다. 직사각형은 2개의 평행한 직선 쌍으로 유일하게 결정된다.",
