    "problem": "8개의 서로 다른 구슬을 3개, 3개, 2개의 세 묶음으로 나누는 경우의 수를 구하시오. (묶음에 이름이 없습니다.)",
    "answerType": "short",
    "choices": null,
    "answer": 280,
    "explanation": "**[핵심 개념]**\n서로 다른 원소를 크기가 정해진 묶음으로 나누는 문제이다. 묶음에 이름이 없으므로 순서를 고려하지 않아야 한다. 같은 크기의 묶음이 있을 때는 중복을 제거해야 한다.\n\n기본 공식: $\\frac{n!}{n_1! \\cdot n_2! \\cdot \\cdots \\cdot n_k!} \\times \\frac{1}{같은\\ 크기\\ 묶음의\\ 개수!}$\n\n**[풀이]**\n\n**Step 1: 구별되는 묶음으로 나누는 경우의 수**\n\n8개의 서로 다른 구슬을 (3, 3, 2) 크기로 구별되는 세 묶음으로 나누는 경우의 수는:\n$$\\binom{8}{3} \\times \\binom{5}{3} \\times \\binom{2}{2} = \\frac{8!}{3! \\cdot 3! \\cdot 2!}$$\n\n계산하면:\n$$\\binom{8}{3} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$$\n\n$$\\binom{5}{3} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n$$\\binom{2}{2} = 1$$\n\n따라서: $56 \\times 10 \\times 1 = 560$\n\n**Step 2: 같은 크기의 묶음으로 인한 중복 제거**\n\n묶음에 이름이 없으므로, 3개짜리 묶음 두 개는 구별되지 않는다.\n\n예를 들어 {A, B, C}와 {D, E, F}로 나누는 것과 {D, E, F}와 {A, B, C}로 나누는 것은 같은 경우이다.\n\n같은 크기(3개)인 묶음이 2개이므로, $2!$으로 나누어야 한다:\n\n$$\\frac{560}{2!} = \\frac{560}{2} = 280$$\n\n**[정답 확인]**\n구별되는 분할로 560가지를 구한 후, 크기가 같은 3개짜리 묶음 2개의 순서 $2! = 2$로 나누어 중복을 제거하면 280이 된다.\n\n**[오답 분석]**\n- **560**: 묶음의 순서를 고려한 경우(묶음에 이름이 있다고 잘못 생각)\n- **280**: 정답\n- **140**: $\\frac{560}{4}$로 잘못 나눈 경우\n- **336**: $\\frac{8!}{3! \\cdot 3! \\cdot 2!}$를 직접 계산하지 못한 경우\n\n**[핵심 포인트]**\n**\"묶음에 이름이 없다\" = 같은 크기의 묶음은 구별되지 않는다** 따라서 같은 크기인 묶음의 개수만큼 팩토리얼로 나누어 중복을 제거하는 것이 핵심이다.",
