    "problem": "평면 위에 10개의 점이 있고, 이 중 4개의 점이 한 직선 위에 있습니다. 나머지 점들 사이에서는 어떤 세 점도 일직선 위에 있지 않을 때, 이 10개의 점으로 만들 수 있는 삼각형의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 116,
    "explanation": "**[핵심 개념]**\n삼각형을 만들기 위한 조건은 일직선 위에 있지 않은 서로 다른 3개의 점이 필요하다. 조합을 이용하여 전체 경우에서 일직선 위의 3개 점으로 이루어진 경우를 제외하는 여사건을 활용한다.\n\n**[풀이]**\n\n**Step 1: 전체 10개 점 중 3개를 선택하는 경우**\n\n10개의 점 중에서 순서를 고려하지 않고 3개를 선택하는 경우의 수:\n$$\\binom{10}{3} = \\frac{10 \\times 9 \\times 8}{3 \\times 2 \\times 1} = 120$$\n\n**Step 2: 삼각형을 만들지 못하는 경우 제외**\n\n삼각형을 만들지 못하는 경우는 선택한 3개의 점이 모두 일직선 위에 있을 때이다.\n\n문제의 조건:\n- 한 직선 위에 있는 점: 4개\n- 나머지 6개의 점들: 어떤 세 점도 일직선 위에 있지 않음\n\n따라서 일직선 위의 3개 점을 선택하는 경우는 **한 직선 위의 4개 점에서만** 발생한다.\n\n**Step 3: 한 직선 위의 4개 점 중 3개를 선택하는 경우**\n\n$$\\binom{4}{3} = \\frac{4 \\times 3 \\times 2}{3 \\times 2 \\times 1} = 4$$\n\n**Step 4: 삼각형의 개수**\n\n삼각형을 만들 수 있는 경우의 수:\n$$\\binom{10}{3} - \\binom{4}{3} = 120 - 4 = 116$$\n\n**[정답 확인]**\n10개 점 중 3개를 선택하는 모든 경우(120)에서 한 직선 위의 4개 점 중 3개를 선택하는 경우(4)를 빼면 정확히 116이 된다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으므로, 다음과 같은 오류를 조심해야 한다:\n- **120**: 일직선 위의 점들을 고려하지 않고 단순히 $\\binom{10}{3}$만 계산한 경우\n- **115**: 계산 실수로 $\\binom{4}{3} = 5$로 잘못 계산한 경우\n- **124**: 여사건을 잘못 이해하여 더한 경우\n\n**[핵심 포인트]**\n- 삼각형의 조건: \"일직선 위에 있지 않은 3개의 점\" → 여사건(일직선 위의 3점)을 제외\n- 한 직선 위의 4개 점에서만 일직선 위의 3점 조합이 발생하므로, $\\binom{4}{3} = 4$만 제외하면 된다.",
