    "explanation": "**[핵심 개념]**\n\n이 문제는 순열과 조합의 차이를 묻는 문제이다.\n\n- **순열 $P(n,r)$**: 서로 다른 n개에서 r개를 선택하여 순서를 고려하여 배열하는 경우의 수\n - 공식: $P(n,r) = \\frac{n!}{(n-r)!}$\n\n- **조합 $C(n,r)$**: 서로 다른 n개에서 r개를 선택하는 경우의 수 (순서 무관)\n - 공식: $C(n,r) = \\frac{n!}{r!(n-r)!}$\n\n- 직책이 있으면 순열, 직책 구분이 없으면 조합을 사용한다.\n\n**[풀이]**\n\n**1단계: 임원 4명을 뽑는 경우의 수 (순열)**\n\n회장, 부회장, 총무, 서기는 모두 다른 직책이므로 순서가 중요하다.\n\n$$P(12,4) = 12 \\times 11 \\times 10 \\times 9$$\n\n계산 과정:\n- 회장: 12명 중 선택\n- 부회장: 남은 11명 중 선택\n- 총무: 남은 10명 중 선택\n- 서기: 남은 9명 중 선택\n\n$$P(12,4) = 12 \\times 11 \\times 10 \\times 9 = 11,880$$\n\n**2단계: 대표 4명을 뽑는 경우의 수 (조합)**\n\n직책 구분이 없으므로 순서를 고려하지 않는다.\n\n$$C(12,4) = \\frac{12!}{4!(12-4)!} = \\frac{12!}{4! \\times 8!}$$\n\n$$C(12,4) = \\frac{12 \\times 11 \\times 10 \\times 9}{4 \\times 3 \\times 2 \\times 1}$$\n\n$$C(12,4) = \\frac{11,880}{24} = 495$$\n\n**3단계: 차이 계산**\n\n$$P(12,4) - C(12,4) = 11,880 - 495 = 11,385$$\n\n**[정답 확인]**\n\n임원(순열)과 대표(조합)의 차이는 $11,880 - 495 = 11,385$이므로 정답은 **②번**이다.\n\n**[오답 분석]**\n\n- ① 10890: $P(12,4) \\div 1.09$ 정도로 잘못 계산했을 경우\n- ③ 11880: $P(12,4)$만 구하고 차이를 계산하지 않은 경우\n- ④ 12375: 계산 실수로 중간값을 더하거나 다른 조합을 사용한 경우\n- ⑤ 12870: $P(12,4) + C(12,4)$를 계산한 경우 (차이가 아닌 합을 구함)\n\n**[핵심 포인트]**\n\n1. **직책이 있으면 순열**, **직책이 없으면 조합**을 구분하여 사용하세요.\n2. 순열은 조합의 24배($4!$배)이므로, 임원 선발이 대표 선발보다 훨씬 많은 경우의 수를 가진다.",
