    "problem": "좌표 평면에서 원점 $(0,0)$에서 점 $(5,4)$까지 최단 거리로 이동하되, 점 $(2,2)$를 반드시 지나는 경로의 수를 구하시오. (오른쪽 또는 위쪽으로만 이동)",
