    "explanation": "**[핵심 개념]**\n\n격자 경로 문제에서 원점 $(0,0)$에서 점 $(a,b)$까지 오른쪽(R) 또는 위쪽(U)으로만 이동할 때, 최단 경로의 수는 $\\binom{a+b}{a}$이다. 특정 점을 반드시 지나는 경로의 수는 (출발점→경유점의 경로 수) × (경유점→도착점의 경로 수)로 계산한다.\n\n**[풀이]**\n\n**1단계: 문제 상황 분석**\n\n- 출발점: $(0,0)$\n- 도착점: $(5,4)$\n- 반드시 지나야 할 점: $(2,2)$\n- 이동 방향: 오른쪽(R) 또는 위쪽(U)만 가능\n\n최단 거리로 이동하므로, $(0,0) \\to (2,2) \\to (5,4)$ 순서로 이동해야 한다.\n\n**2단계: $(0,0)$에서 $(2,2)$까지의 경로 수 계산**\n\n$(0,0)$에서 $(2,2)$로 가려면:\n- 오른쪽으로 2칸\n- 위쪽으로 2칸\n- 총 4번의 이동 중 오른쪽 2번을 선택하는 경우의 수\n\n$$\\binom{2+2}{2} = \\binom{4}{2} = \\frac{4!}{2!2!} = \\frac{4 \\times 3}{2 \\times 1} = 6$$\n\n**3단계: $(2,2)$에서 $(5,4)$까지의 경로 수 계산**\n\n$(2,2)$에서 $(5,4)$로 가려면:\n- 오른쪽으로 $5-2=3$칸\n- 위쪽으로 $4-2=2$칸\n- 총 5번의 이동 중 오른쪽 3번을 선택하는 경우의 수\n\n$$\\binom{3+2}{3} = \\binom{5}{3} = \\frac{5!}{3!2!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**4단계: 전체 경로 수 계산**\n\n곱의 법칙을 이용하여:\n\n$$\\text{(전체 경로 수)} = 6 \\times 10 = 60$$\n\n**[정답 확인]**\n\n$(0,0) \\to (2,2) \\to (5,4)$의 경로는 반드시 $(2,2)$를 지나며, 각 구간에서 최단 경로만 이동하므로 계산이 정확한다.\n\n**[오답 분석]**\n\n- ① 30: $6 \\times 5 = 30$으로, $(2,2)$에서 $(5,4)$까지의 경로를 잘못 계산한 경우\n- ② 40: 계산 실수로 인한 값\n- ④ 80: $8 \\times 10 = 80$으로, $(0,0)$에서 $(2,2)$까지의 경로를 $\\binom{4}{1}=4$로 잘못 계산한 후 $(5,4)$ 전체 경로 $\\binom{9}{5}=126$을 잘못 적용한 경우\n- ⑤ 90: $(0,0)$에서 $(5,4)$ 전체 경로 $\\binom{9}{5}=126$을 잘못 계산하거나 다른 방식으로 접근한 경우\n\n**[핵심 포인트]**\n\n조건부 경로 문제는 반드시 지나야 할 점을 기준으로 **구간을 나누어 각각 계산한 후 곱하는 것**이 핵심이다. 조합 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$을 정확히 계산하는 것이 중요하다.",
