    "answer": 10,
    "explanation": "**[핵심 개념]**\n조합의 정의와 대칭성을 이용하는 문제이다.\n\n조합 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$의 중요한 성질 중 하나는 **대칭성**이다:\n$$\\binom{n}{r} = \\binom{n}{n-r}$$\n\n이는 $n$개 중에서 $r$개를 선택하는 것과 $n$개 중에서 $n-r$개를 선택하는 것(= $r$개를 제외하는 것)이 같기 때문이다.\n\n**[풀이]**\n\n주어진 조건: $\\binom{n}{4} = \\binom{n}{6}$\n\n조합의 대칭성에 의해 $\\binom{n}{r} = \\binom{n}{n-r}$이므로, \n$$\\binom{n}{4} = \\binom{n}{6}$$\n이 성립하려면 다음 두 가지 경우 중 하나여야 한다:\n\n**경우 1:** $4 = 6$ (이는 불가능)\n\n**경우 2:** $4 = n - 6$ (대칭성 이용)\n\n경우 2에서:\n$$4 = n - 6$$\n$$n = 10$$\n\n**검증:**\n- $n = 10$일 때, $\\binom{10}{4} = \\binom{10}{10-4} = \\binom{10}{6}$ ✓\n\n직접 계산으로도 확인:\n$$\\binom{10}{4} = \\frac{10!}{4! \\cdot 6!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = \\frac{5040}{24} = 210$$\n\n$$\\binom{10}{6} = \\frac{10!}{6! \\cdot 4!} = 210$$\n\n따라서 $n = 10$\n\n**[정답 확인]**\n$n = 10$일 때 조합의 대칭성에 의해 $\\binom{10}{4} = \\binom{10}{6} = 210$이 성립한다.\n\n**[오답 분석]**\n- $n = 4$: $\\binom{4}{6}$은 정의되지 않음 (조합에서 $r > n$이면 불가능)\n- $n = 6$: $\\binom{6}{4} = 15$, $\\binom{6}{6} = 1$ (같지 않음)\n- $n = 12$: $\\binom{12}{4} = 495$, $\\binom{12}{6} = 924$ (같지 않음)\n\n**[핵심 포인트]**\n1. **조합의 대칭성**: $\\binom{n}{r} = \\binom{n}{n-r}$ → 두 조합이 같으려면 지수가 대칭 관계에 있어야 함\n2. $\\binom{n}{4} = \\binom{n}{6}$에서 $4 + 6 = 10 = n$이 되어야 한다는 것을 빠르게 인식하는 것이 중요",
