    "explanation": "**[핵심 개념]**\n이 문제는 조합 문제로, 전체 경우에서 조건을 만족하는 경우를 구하는 방식을 사용한다.\n- 10명을 구별되는 두 조(A조, B조)로 5명씩 나누는 경우의 수: $\\binom{10}{5}$\n- 특정 조건(P, Q가 같은 조)을 만족하는 경우를 직접 계산하는 방법을 적용한다.\n\n**[풀이]**\n\n**방법: P, Q의 위치에 따라 경우를 나누기**\n\nP와 Q가 같은 조에 속하는 경우는 다음 두 가지이다.\n\n**경우 1) P, Q 모두 A조에 속하는 경우**\n- P, Q는 이미 A조에 배치됨\n- 남은 인원: 8명 (P, Q 제외)\n- A조에 3명 더 필요, B조에 5명 필요\n- 남은 8명 중 A조에 들어올 3명을 선택: $\\binom{8}{3}$\n- 경우의 수: $\\binom{8}{3} = \\frac{8!}{3!5!} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = 56$\n\n**경우 2) P, Q 모두 B조에 속하는 경우**\n- P, Q는 이미 B조에 배치됨\n- 남은 인원: 8명 (P, Q 제외)\n- A조에 5명 필요, B조에 3명 더 필요\n- 남은 8명 중 A조에 들어올 5명을 선택: $\\binom{8}{5}$\n- 경우의 수: $\\binom{8}{5} = \\binom{8}{3} = 56$\n\n**전체 경우의 수**\n$$56 + 56 = 112$$\n\n**[정답 확인]**\nP, Q가 같은 조에 속하려면 (1) 둘 다 A조 또는 (2) 둘 다 B조에 있어야 하며, 각각 56가지씩 존재하므로 총 112가지이다.\n\n**[오답 분석]**\n- ① 92: 한 경우만 계산하거나 조합값을 잘못 계산한 경우\n- ② 102: $\\binom{8}{3} = 56$을 정확히 계산하지 못하고 근사값을 사용한 경우\n- ④ 122: 계산 과정에서 덧셈 실수를 한 경우\n- ⑤ 132: 조건을 잘못 이해하거나 전체 경우의 수를 잘못 계산한 경우\n\n**[핵심 포인트]**\n조건을 만족하는 경우를 계산할 때 **대상이 속할 수 있는 각각의 경우(A조 또는 B조)를 나누어 계산**하고, 서로 배타적이므로 합의 법칙을 적용한다. 특히 P, Q를 먼저 배치한 후 남은 인원을 배분하는 사고방식이 중요하다.",
