    "type": "조합",
    "problem": "좌표 평면에서 원점 $(0,0)$에서 점 $(4,3)$까지 최단 거리로 이동하되, 점 $(1,1)$과 $(2,2)$를 모두 지나지 않는 경로의 수를 구하시오. (오른쪽 또는 위쪽으로만 이동)",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n격자 경로 문제에서 최단 경로의 수는 조합으로 구한다. 원점에서 $(m,n)$까지 오른쪽으로 $m$번, 위쪽으로 $n$번 이동해야 하므로 총 경로의 수는 $\\binom{m+n}{m}$이다. 특정 점을 지나지 않는 경로의 수는 **포함-배제 원리**를 사용한다.\n\n**[풀이]**\n\n**1단계: 전체 경로의 수**\n\n원점 $(0,0)$에서 $(4,3)$까지 최단 경로는 오른쪽 4번, 위쪽 3번 이동이다.\n전체 경로의 수: $\\binom{7}{4} = \\binom{7}{3} = 35$\n\n**2단계: 점 $(1,1)$을 지나는 경로의 수**\n\n- $(0,0) \\to (1,1)$: $\\binom{2}{1} = 2$\n- $(1,1) \\to (4,3)$: 오른쪽 3번, 위쪽 2번 이동하므로 $\\binom{5}{3} = 10$\n- $(1,1)$을 지나는 경로: $2 \\times 10 = 20$\n\n**3단계: 점 $(2,2)$를 지나는 경로의 수**\n\n- $(0,0) \\to (2,2)$: $\\binom{4}{2} = 6$\n- $(2,2) \\to (4,3)$: 오른쪽 2번, 위쪽 1번 이동하므로 $\\binom{3}{2} = 3$\n- $(2,2)$를 지나는 경로: $6 \\times 3 = 18$\n\n**4단계: 점 $(1,1)$과 $(2,2)$를 모두 지나는 경로의 수**\n\n$(1,1)$과 $(2,2)$는 모두 지날 수 있으므로, $(1,1) \\to (2,2) \\to (4,3)$ 순서로 지나야 한다.\n\n- $(0,0) \\to (1,1)$: $2$\n- $(1,1) \\to (2,2)$: 오른쪽 1번, 위쪽 1번이므로 $\\binom{2}{1} = 2$\n- $(2,2) \\to (4,3)$: $3$\n- 둘 다 지나는 경로: $2 \\times 2 \\times 3 = 12$\n\n**5단계: 포함-배제 원리 적용**\n\n$(1,1)$ 또는 $(2,2)$를 지나는 경로의 수:\n$$|A \\cup B| = |A| + |B| - |A \\cap B| = 20 + 18 - 12 = 26$$\n\n**6단계: 최종 답**\n\n$(1,1)$과 $(2,2)$를 모두 지나지 않는 경로의 수:\n$$35 - 26 = 9$$\n\n**[정답 확인]**\n\n포함-배제 원리를 통해 제외할 경로를 정확히 계산했으므로, 전체 35개에서 26개를 빼면 두 점을 모두 지나지 않는 9개의 경로가 남다.\n\n**[오답 분석]**\n\n- **20 (오답)**: $(1,1)$만 지나지 않는 경우로, $(2,2)$를 지나는 경우를 고려하지 않음\n- **17 (오답)**: $(2,2)$만 지나지 않는 경우 ($35 - 18 = 17$)로, $(1,1)$을 지나는 경우를 고려하지 않음\n- **26 (오답)**: 반대로 계산하여 지나는 경로의 수를 구한 경우\n\n**[핵심 포인트]**\n\n1. 격자 경로 문제는 조합과 포함-배제 원리의 조합이다.\n2. 여러 점을 지나지 않는 경로는 (전체) - (어느 점이라도 지나는 경로)로 계산한다.",
