    "answer": 2,
    "explanation": "**[핵심 개념]**\n집합에서 4개 원소를 선택하는 조합 문제에서 \"최댓값과 최솟값의 차이가 7 이상\"이라는 조건을 해석해야 한다.\n- 4개 원소의 부분집합에서 최솟값을 $a$, 최댓값을 $b$라 하면, $b - a \\geq 7$\n- 전체 조합에서 조건을 만족하지 않는 경우를 빼는 여사건을 이용하거나, 직접 세는 방법을 사용할 수 있다.\n\n**[풀이]**\n\n4개 원소를 선택할 때, 최솟값을 $m$, 최댓값을 $M$이라 하면:\n- 조건: $M - m \\geq 7$\n\n**Step 1: 전체 경우의 수**\n$$\\binom{10}{4} = 210$$\n\n**Step 2: 여사건 이용 ($M - m \\leq 6$인 경우를 제외)**\n\n$M - m \\leq 6$이 되려면, 최솟값과 최댓값의 차가 6 이하여야 한다.\n\n최솟값이 $m$이고 최댓값이 $M$일 때 ($M - m \\leq 6$):\n- 4개 원소는 $m$과 $M$을 반드시 포함하고, 나머지 2개는 $(m, M)$ 사이에서 선택\n\n최솟값이 $m$, 최댓값이 $M$인 경우의 수를 세면:\n- $m$부터 $M$ 사이의 원소 개수가 $M - m + 1$개\n- 이 중 양끝($m, M$)을 제외한 $M - m - 1$개 중에서 2개를 선택: $\\binom{M-m-1}{2}$\n\n**Step 3: $M - m \\leq 6$인 모든 경우**\n\n각 $(m, M)$ 쌍에 대해 $d = M - m$이라 하면 ($1 \\leq d \\leq 6$):\n\n$$\\sum_{d=1}^{6} (11-d) \\cdot \\binom{d-1}{2}$$\n\n- $d=1$: $(11-1) \\cdot \\binom{0}{2} = 10 \\cdot 0 = 0$\n- $d=2$: $(11-2) \\cdot \\binom{1}{2} = 9 \\cdot 0 = 0$\n- $d=3$: $(11-3) \\cdot \\binom{2}{2} = 8 \\cdot 1 = 8$\n- $d=4$: $(11-4) \\cdot \\binom{3}{2} = 7 \\cdot 3 = 21$\n- $d=5$: $(11-5) \\cdot \\binom{4}{2} = 6 \\cdot 6 = 36$\n- $d=6$: $(11-6) \\cdot \\binom{5}{2} = 5 \\cdot 10 = 50$\n\n합계: $0 + 0 + 8 + 21 + 36 + 50 = 95$\n\n**Step 4: 조건을 만족하는 경우**\n$$210 - 95 = 115$$\n\n**[정답 확인]**\n전체 조합 210개에서 최댓값과 최솟값의 차가 6 이하인 95개를 제외하면 115개가 남으므로 정답이다.\n\n**[오답 분석]**\n- ① 95: $M - m \\leq 6$인 경우만 센 것 (여사건 값)\n- ② 105: 계산 실수로 $d=6$인 경우를 과소 계산\n- ④ 125: 여사건 계산 시 $d=5$나 $d=6$ 항을 빠뜨린 경우\n- ⑤ 135: 전체에서 너무 적게 뺀 경우\n\n**[핵심 포인트]**\n- 직접 세는 것보다 **여사건을 이용한 계산이 효율적**이다.\n- 최솟값이 $m$, 최댓값이 $M$일 때, 나머지 2개를 선택하는 경우의 수는 $\\binom{M-m-1}{2}$이다.",
