    "answer": 1,
    "explanation": "**[핵심 개념]**\n이 문제는 **중복조합** 문제이다. 3가지 종류의 음료 중에서 중복을 허락하여 5잔을 선택하는 것이므로, 같은 음료를 여러 번 선택할 수 있다. 중복조합의 공식은 $n$가지 종류에서 중복을 허락하여 $r$개를 선택하는 경우의 수는 $H(n,r) = C(n+r-1, r)$이다.\n\n**[풀이]**\n\n**단계 1: 주어진 정보 정리**\n- 음료의 종류: 3가지 ($n=3$)\n- 선택할 잔의 수: 5잔 ($r=5$)\n- 중복 선택 허락\n\n**단계 2: 중복조합 공식 적용**\n$$H(3,5) = C(3+5-1, 5) = C(7, 5)$$\n\n**단계 3: 조합 계산**\n$$C(7,5) = C(7,2) = \\frac{7!}{2! \\times 5!} = \\frac{7 \\times 6}{2 \\times 1} = \\frac{42}{2} = 21$$\n\n($C(7,5) = C(7,2)$인 이유는 조합의 성질 $C(n,r) = C(n, n-r)$을 사용했다)\n\n**[정답 확인]**\n중복조합 공식을 올바르게 적용하면 $C(7,5) = 21$이므로 정답은 **②번**이다.\n\n**[오답 분석]**\n\n**① 15**: $C(6,4)$ 또는 잘못된 계산으로 나올 수 있는 값이다. 공식을 잘못 적용한 경우이다.\n\n**③ 35**: $C(7,3)$의 값으로, $C(7,5)$ 대신 다른 조합값을 계산한 실수이다.\n\n**④ 56**: $C(8,3)$ 또는 공식에서 $n$과 $r$을 잘못 대입한 경우이다.\n\n**⑤ 243**: $3^5$을 계산한 값으로, 순서를 고려한 **중복순열**로 잘못 풀었을 때 나온다. 이 문제는 순서가 없는 조합이다.\n\n**[핵심 포인트]**\n- **중복조합 vs 중복순열**: \"선택한다\" = 조합 / \"배열한다\" = 순열\n- **중복조합 공식**: $H(n,r) = C(n+r-1, r)$을 정확히 기억하기. 특히 $n+r-1$이 분자의 큰 수가 됨을 주의!",
