    "explanation": "**[핵심 개념]**\n네 자리 양의 정수는 천의 자리 숫자가 0이 아니어야 한다. 따라서 천의 자리와 나머지 자리의 경우의 수를 따로 계산해야 한다. 이는 '곱의 법칙'을 이용하여 경우의 수를 구하는 문제이다.\n\n**[풀이]**\n네 자리 양의 정수를 $\\overline{abcd}$라고 한다. (단, $a$는 천의 자리)\n\n**1단계: 천의 자리 결정**\n- 0, 1, 2의 세 숫자 중에서 천의 자리 $a$는 0이 될 수 없다.\n- (왜냐하면 네 자리 수가 되려면 천의 자리가 0이 아니어야 하기 때문)\n- 따라서 $a \\in \\{1, 2\\}$\n- 천의 자리의 경우의 수: **2가지**\n\n**2단계: 백의 자리 결정**\n- 백의 자리 $b$는 0, 1, 2 중 아무거나 선택 가능한다.\n- 백의 자리의 경우의 수: **3가지**\n\n**3단계: 십의 자리 결정**\n- 십의 자리 $c$는 0, 1, 2 중 아무거나 선택 가능한다.\n- 십의 자리의 경우의 수: **3가지**\n\n**4단계: 일의 자리 결정**\n- 일의 자리 $d$는 0, 1, 2 중 아무거나 선택 가능한다.\n- 일의 자리의 경우의 수: **3가지**\n\n**5단계: 곱의 법칙 적용**\n각 자리의 선택이 독립적이므로, 전체 경우의 수는:\n$$2 \\times 3 \\times 3 \\times 3 = 2 \\times 3^3 = 2 \\times 27 = 54$$\n\n**[정답 확인]**\n천의 자리는 1 또는 2만 가능(2가지), 나머지 세 자리는 각각 0, 1, 2 모두 가능(각 3가지)하므로, $2 \\times 3^3 = 54$가 정답이다.\n\n**[오답 분석]**\n- **81** (=$3^4$): 천의 자리에 0을 포함시킨 경우로, 이는 네 자리 수가 아닙니다.\n- **162** (=$2 \\times 3^4$): 나머지 자리를 4개로 잘못 계산한 경우이다.\n- **48** (=$2 \\times 3 \\times 2 \\times 2$): 백의 자리 이하에서 0을 제외시킨 잘못된 계산이다.\n\n**[핵심 포인트]**\n1. **'양의 정수'이므로 천의 자리는 0이 될 수 없다**는 조건이 핵심이다.\n2. 천의 자리와 나머지 자리의 제약이 다르므로 **각 자리를 구분하여 계산**해야 한다.",
