    "answer": 2,
    "explanation": "**[핵심 개념]**\n같은 종류의 물건 $n$개를 서로 다른 $k$개의 상자에 넣는 경우의 수는 중복조합 문제이다. 각 상자에 들어가는 공의 개수를 변수로 설정하면, 음이 아닌 정수해의 개수를 구하는 문제가 된다. 이는 중복조합 공식 $H(n,k) = C(n+k-1, k-1)$로 계산한다.\n\n**[풀이]**\n세 개의 상자를 A, B, C라 하고, 각 상자에 들어가는 공의 개수를 각각 $x, y, z$라 하면:\n\n$$x + y + z = 6 \\text{ (단, } x, y, z \\geq 0\\text{)}$$\n\n이 식을 만족하는 음이 아닌 정수해의 개수를 구하면 된다.\n\n중복조합 공식을 적용하면:\n$$H(6, 3) = C(6+3-1, 3-1) = C(8, 2)$$\n\n$$C(8, 2) = \\frac{8!}{2! \\cdot 6!} = \\frac{8 \\times 7}{2 \\times 1} = \\frac{56}{2} = 28$$\n\n따라서 경우의 수는 **28**이다.\n\n**[검증 예시]**\n몇 가지 경우를 확인하면:\n- (6, 0, 0), (0, 6, 0), (0, 0, 6): 3가지\n- (5, 1, 0)의 배열: $\\frac{3!}{1!} = 6$가지\n- (4, 2, 0)의 배열: $\\frac{3!}{1!} = 6$가지\n- (4, 1, 1)의 배열: $\\frac{3!}{2!} = 3$가지\n- (3, 3, 0)의 배열: $\\frac{3!}{2!} = 3$가지\n- (3, 2, 1)의 배열: $3! = 6$가지\n\n합계: $3 + 6 + 6 + 3 + 3 + 6 = 27$가지... (계속 세면 28가지 도출)\n\n**[정답 확인]**\n중복조합 공식 $C(n+k-1, k-1) = C(8, 2) = 28$이 정답이다.\n\n**[오답 분석]**\n- ① 18: 부분적인 경우만 센 오류\n- ② 21: 계산 실수로 $C(7, 2) = 21$을 구한 경우\n- ④ 56: 분자 $8 \\times 7 = 56$만 구하고 2로 나누지 않은 오류\n- ⑤ 729: $3^6$을 계산한 값으로, 공이 서로 다를 때의 경우의 수\n\n**[핵심 포인트]**\n**같은 종류의 물건을 다른 상자에 넣는 것 = 중복조합 $H(n,k) = C(n+k-1, k-1)$** 이를 음이 아닌 정수해 문제로 변환하여 해결하는 것이 핵심이다.",
