    "type": "중복순열·중복조합",
    "problem": "주사위를 3번 던질 때, 나올 수 있는 모든 눈의 순서쌍 $(a, b, c)$의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 216,
    "explanation": "**[핵심 개념]**\n\n곱의 법칙(Multiplication Principle): 독립적인 여러 사건이 순차적으로 일어날 때, 전체 경우의 수는 각 사건의 경우의 수를 곱한 값이다. 주사위는 1부터 6까지의 눈이 나올 수 있으며, 각 던지기는 독립적이다.\n\n**[풀이]**\n\n주사위를 3번 던질 때 나오는 결과를 순서쌍 $(a, b, c)$로 나타냅니다.\n\n**1단계: 첫 번째 던지기**\n- 첫 번째 주사위 $a$의 경우의 수: $6$가지 (1, 2, 3, 4, 5, 6 중 하나)\n\n**2단계: 두 번째 던지기**\n- 두 번째 주사위 $b$의 경우의 수: $6$가지\n- $a$의 결과와 무관하게 독립적으로 $6$가지 모두 가능\n\n**3단계: 세 번째 던지기**\n- 세 번째 주사위 $c$의 경우의 수: $6$가지\n- $a$, $b$의 결과와 무관하게 독립적으로 $6$가지 모두 가능\n\n**4단계: 곱의 법칙 적용**\n\n전체 경우의 수는:\n$$6 \\times 6 \\times 6 = 6^3 = 216$$\n\n**[정답 확인]**\n\n주사위 3번 던지기에서 각 던지기마다 6가지 경우가 독립적으로 발생하므로, 곱의 법칙에 의해 $6^3 = 216$이 정답이다.\n\n**[오답 분석]**\n\n선택지가 없으므로 일반적인 오류를 언급한다.\n- **18**: $6 + 6 + 6$으로 잘못 계산 (덧셈의 법칙을 잘못 적용)\n- **36**: $6 \\times 6$으로 계산하여 두 번째 던지기만 고려 (3번이 아닌 2번만 계산)\n- **20**: 조합으로 계산하려는 오류 (순서쌍이므로 순열 개념 사용)\n\n**[핵심 포인트]**\n\n- **곱의 법칙**: 순차적이고 독립적인 사건은 경우의 수를 **곱함**\n- **순서쌍의 중요성**: 같은 눈이 나와도 다른 순서면 다른 경우이므로, $(1,2,3)$과 $(2,1,3)$은 서로 다른 순서쌍이다.",
