    "answer": 2,
    "explanation": "**[핵심 개념]**\n조합(Combination)은 $n$개의 서로 다른 원소 중에서 순서를 고려하지 않고 $r$개를 선택하는 경우의 수이다. 조합의 공식은 $$_nC_r = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$$\n\n여기서 $n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 2 \\times 1$이다.\n\n**[풀이]**\n$_5H_2$는 5개의 서로 다른 원소 중에서 2개를 선택하는 조합이다.\n\n조합 공식을 적용하면:\n$$_5C_2 = \\frac{5!}{2!(5-2)!} = \\frac{5!}{2! \\times 3!}$$\n\n각 팩토리얼을 계산한다:\n- $5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$\n- $2! = 2 \\times 1 = 2$\n- $3! = 3 \\times 2 \\times 1 = 6$\n\n따라서:\n$$_5C_2 = \\frac{120}{2 \\times 6} = \\frac{120}{12} = 10$$\n\n아니, 다시 계산한다. 더 간단한 방법을 사용하면:\n$$_5C_2 = \\frac{5 \\times 4}{2 \\times 1} = \\frac{20}{2} = 10$$\n\n잠깐, 문제에서 정답이 ③ 15라고 했으므로 $_5H_2$는 중복조합(Combination with repetition)을 의미한다.\n\n중복조합 공식:\n$$_nH_r = _{n+r-1}C_r = \\frac{(n+r-1)!}{r!(n-1)!}$$\n\n따라서:\n$$_5H_2 = _{5+2-1}C_2 = _6C_2 = \\frac{6!}{2! \\times 4!} = \\frac{6 \\times 5}{2 \\times 1} = \\frac{30}{2} = 15$$\n\n**[정답 확인]**\n중복조합 공식 $_nH_r = _{n+r-1}C_r$을 적용하여 $_5H_2 = _6C_2 = 15$로 계산된다.\n\n**[오답 분석]**\n- ① 6: $_5C_1$의 값으로, 잘못된 조합이다.\n- ② 10: 중복을 허용하지 않는 일반 조합 $_5C_2$의 값이다. $H$를 $C$로 잘못 이해한 경우이다.\n- ④ 20: $_6C_2$에서 분자만 계산한 경우(6×5=30을 2로 나누지 않음)이다.\n- ⑤ 25: $5^2$으로 잘못 계산한 경우이다.\n\n**[핵심 포인트]**\n- $_nH_r$(중복조합)은 같은 것을 여러 번 선택할 수 있으며, 공식은 $_nH_r = _{n+r-1}C_r$이다.\n- 문제에서 $H$ 기호를 사용하면 반드시 중복조합임을 인식하는 것이 중요하다.",
