    "problem": "방정식 $x + y + z = 7$의 음이 아닌 정수해의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 36,
    "explanation": "**[핵심 개념]**\n\n음이 아닌 정수해의 개수를 구하는 문제는 **중복조합(중복을 허용하는 조합)** 문제이다.\n\n$x + y + z = 7$을 만족하는 음이 아닌 정수 $x, y, z$의 개수는 7개의 동일한 공을 3개의 서로 다른 상자에 넣는 경우의 수와 같다.\n\n일반적으로 $x_1 + x_2 + \\cdots + x_n = r$의 음이 아닌 정수해의 개수는 **중복조합 공식**으로 구한다:\n$$\\mathrm{H}(n, r) = \\mathrm{C}(n+r-1, r) = \\binom{n+r-1}{r}$$\n\n**[풀이]**\n\n주어진 방정식: $x + y + z = 7$ (단, $x, y, z \\geq 0$이고 정수)\n\n여기서:\n- 변수의 개수: $n = 3$ (즉, $x, y, z$ 세 개)\n- 합: $r = 7$\n\n중복조합 공식을 적용하면:\n$$\\mathrm{H}(3, 7) = \\binom{3+7-1}{7} = \\binom{9}{7}$$\n\n조합을 계산한다:\n$$\\binom{9}{7} = \\binom{9}{9-7} = \\binom{9}{2}$$\n\n(대칭성을 이용하여 계산을 간단히 함)\n\n$$\\binom{9}{2} = \\frac{9 \\times 8}{2 \\times 1} = \\frac{72}{2} = 36$$\n\n**[정답 확인]**\n\n중복조합 공식 $\\binom{n+r-1}{r} = \\binom{3+7-1}{7} = \\binom{9}{7} = 36$으로 정확하게 계산되었다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나 흔한 오답은:\n- $\\binom{7}{3} = 35$: 공식을 잘못 적용한 경우\n- $\\binom{8}{3} = 56$: $n+r$을 잘못 사용한 경우\n- $7 \\times 6 / 2 = 21$: 순열이나 단순 조합으로 계산한 경우\n\n**[핵심 포인트]**\n\n$x_1 + x_2 + \\cdots + x_n = r$의 음이 아닌 정수해 개수는 **$\\binom{n+r-1}{r}$** 공식을 반드시 암기하세요. 이는 $n$개의 변수와 합 $r$이 주어질 때 직접 적용할 수 있다.",
