    "explanation": "**[핵심 개념]**\n\n중복조합 문제로, 양의 정수 조건과 음이 아닌 정수 조건의 차이를 이해하는 것이 중요하다.\n\n$x + y + z = n$을 만족하는 음이 아닌 정수해의 개수는 $\\binom{n+k-1}{k-1}$이고, 양의 정수해의 개수는 변수 치환을 통해 구한다.\n\n**[풀이]**\n\n$x, y, z$가 모두 양의 정수이므로 $x \\geq 1, y \\geq 1, z \\geq 1$이다.\n\n변수를 치환하여 문제를 단순화한다.\n\n$x' = x - 1, y' = y - 1, z' = z - 1$로 놓으면, $x', y', z' \\geq 0$인 음이 아닌 정수이다.\n\n원래 식 $x + y + z = 5$에 대입하면:\n\n$$(x' + 1) + (y' + 1) + (z' + 1) = 5$$\n\n$$x' + y' + z' + 3 = 5$$\n\n$$x' + y' + z' = 2$$\n\n이제 $x' + y' + z' = 2$를 만족하는 음이 아닌 정수해의 개수를 구한다.\n\n중복조합 공식을 적용하면:\n\n$$\\binom{2 + 3 - 1}{3 - 1} = \\binom{4}{2} = \\frac{4 \\times 3}{2 \\times 1} = 6$$\n\n**[정답 확인]**\n\n양의 정수 조건을 음이 아닌 정수 조건으로 변환한 후 중복조합 공식을 올바르게 적용하면 6개이다.\n\n**[오답 분석]**\n\n- ① 3: 변수가 3개라고 착각하여 선택한 경우\n- ③ 10: $\\binom{5+3-1}{3-1} = \\binom{7}{2} = 21$의 일부를 계산하는 실수\n- ④ 15: 음이 아닌 정수해의 공식을 잘못 적용한 경우\n- ⑤ 21: 양의 정수 조건 없이 음이 아닌 정수해의 개수 $\\binom{5+2}{2}$를 구한 경우\n\n**[핵심 포인트]**\n\n양의 정수해 문제는 반드시 **$x' = x-1, y' = y-1, z' = z-1$ 치환**으로 음이 아닌 정수 문제로 변환하고, 우변도 함께 조정해야 한다. 이 한 단계의 차이가 정답과 오답을 가르는 핵심이다.",
