    "_type": "repeated",
    "type": "중복순열·중복조합",
    "problem": "방정식 $a + b + c = 8$을 만족하는 양의 정수 해의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 21,
    "explanation": "**[핵심 개념]**\n\n양의 정수해의 개수를 구하는 문제는 **중복조합(또는 조합론의 stars and bars 방법)**을 사용한다.\n\n일반적으로 $x_1 + x_2 + \\cdots + x_n = k$를 만족하는 양의 정수해의 개수는 $\\binom{k-1}{n-1}$이다.\n\n- 양의 정수: 1 이상의 정수 (0 제외)\n- 음이 아닌 정수: 0 이상의 정수\n\n**[풀이]**\n\n**Step 1: 문제 상황 파악**\n\n$a + b + c = 8$을 만족하는 양의 정수해를 구해야 한다.\n- $a, b, c \\geq 1$ (양의 정수)\n\n**Step 2: 변수 치환**\n\n양의 정수 조건을 음이 아닌 정수 조건으로 변환하기 위해 다음과 같이 치환한다.\n\n$a' = a - 1, \\quad b' = b - 1, \\quad c' = c - 1$\n\n그러면 $a', b', c' \\geq 0$ (음이 아닌 정수)\n\n**Step 3: 새로운 방정식 세우기**\n\n원래 식에 대입하면:\n$$(a' + 1) + (b' + 1) + (c' + 1) = 8$$\n$$a' + b' + c' + 3 = 8$$\n$$a' + b' + c' = 5$$\n\n**Step 4: 음이 아닌 정수해의 개수 계산**\n\n$a' + b' + c' = 5$를 만족하는 음이 아닌 정수해의 개수는 중복조합 공식을 적용한다:\n\n$$\\binom{5 + 3 - 1}{3 - 1} = \\binom{7}{2} = \\frac{7 \\times 6}{2 \\times 1} = 21$$\n\n**[정답 확인]**\n\n변수 치환을 통해 양의 정수 조건을 음이 아닌 정수 조건으로 변환한 후 중복조합 공식 $\\binom{n+r-1}{r-1}$을 올바르게 적용하면 21이 된다.\n\n**[오답 분석]**\n\n- **28**: $\\binom{8}{2} = 28$로, 음이 아닌 정수해 개수를 구한 경우 (변수 치환을 하지 않음)\n- **56**: $\\binom{8}{3} = 56$으로, 다른 공식을 잘못 적용한 경우\n- **35**: $\\binom{7}{3} = 35$로, 공식의 분자와 분모를 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n1. **양의 정수 조건에서는 반드시 변수 치환** ($x_i' = x_i - 1$)을 하여 음이 아닌 정수 문제로 변환해야 한다.\n\n2. **중복조합 공식**: $x_1 + x_2 + \\cdots + x_n = k$ (음이 아닌 정수)의 해의 개수는 $\\binom{k+n-1}{n-1}$이다.",
