    "type": "중복순열·중복조합",
    "problem": "방정식 $x + y + z = 10$을 만족하는 음이 아닌 정수 해 중에서 $x \\leq 3$인 해의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 38,
    "explanation": "**[핵심 개념]**\n음이 아닌 정수 해의 개수를 구하는 문제는 중복조합을 이용한다. 방정식 $x_1 + x_2 + \\cdots + x_n = k$ (단, $x_i \\geq 0$)의 음이 아닌 정수 해의 개수는 $\\binom{n+k-1}{k}$ 또는 $\\binom{n+k-1}{n-1}$이다. 추가 조건이 있을 때는 조건을 만족하는 경우만 따로 계산하거나, 변수 치환을 통해 문제를 단순화한다.\n\n**[풀이]**\n\n주어진 조건: $x + y + z = 10$ (단, $x, y, z \\geq 0$이고 $x \\leq 3$)\n\n$x$의 범위에 따라 경우를 나누어 계산한다.\n\n**경우 1: $x = 0$일 때**\n$y + z = 10$을 만족하는 음이 아닌 정수 해의 개수\n\n$y \\geq 0, z \\geq 0$이므로, 중복조합으로:\n$$\\binom{10+2-1}{2-1} = \\binom{11}{1} = 11$$\n\n**경우 2: $x = 1$일 때**\n$y + z = 9$를 만족하는 음이 아닌 정수 해의 개수\n\n$$\\binom{9+2-1}{2-1} = \\binom{10}{1} = 10$$\n\n**경우 3: $x = 2$일 때**\n$y + z = 8$을 만족하는 음이 아닌 정수 해의 개수\n\n$$\\binom{8+2-1}{2-1} = \\binom{9}{1} = 9$$\n\n**경우 4: $x = 3$일 때**\n$y + z = 7$을 만족하는 음이 아닌 정수 해의 개수\n\n$$\\binom{7+2-1}{2-1} = \\binom{8}{1} = 8$$\n\n**전체 해의 개수**\n$$11 + 10 + 9 + 8 = 38$$\n\n**[정답 확인]**\n$x$의 각 값($0, 1, 2, 3$)에 대해 $y+z$의 해의 개수가 각각 11, 10, 9, 8개이므로, 합계는 38개가 맞다.\n\n**[오답 분석]**\n선택지가 없어 오답 분석은 생략하지만, 다음과 같은 실수를 주의해야 한다:\n- $x \\leq 3$을 $x < 3$으로 잘못 이해하여 경우 4를 빠뜨리는 경우 → 30이 나옴\n- 조건 없이 전체 해를 구하는 경우 $\\binom{12}{2} = 66$\n\n**[핵심 포인트]**\n음이 아닌 정수 해의 개수는 $n$개의 변수와 합 $k$에 대해 중복조합 $\\binom{n+k-1}{n-1}$로 계산하며, 추가 조건이 있을 때는 조건의 범위별로 나누어 각각 계산한 후 합산하는 것이 효과적이다.",
