    "explanation": "**[핵심 개념]**\n같은 종류의 물건을 여러 명에게 나누어 주는 문제는 중복조합으로 해결한다. 조건이 있을 때는 변수를 치환하여 조건을 제거한 후 기본 중복조합 공식 $H(n,r) = C(n+r-1, r)$을 적용한다.\n\n**[풀이]**\n\n**1단계: 조건 분석**\n- 사탕 10개를 3명의 학생(A, B, C)에게 나누어 줌\n- 각 학생이 적어도 2개씩 받아야 함\n\n**2단계: 변수 치환으로 조건 제거**\n\n각 학생이 받는 사탕의 개수를 $x_1, x_2, x_3$라 하면:\n$$x_1 + x_2 + x_3 = 10, \\quad x_i \\geq 2 \\text{ (모든 } i\\text{)}$$\n\n각 학생에게 먼저 2개씩 나누어 주고, 나머지를 분배하는 방식으로 생각한다.\n\n$y_i = x_i - 2$로 치환하면:\n- $y_1 + y_2 + y_3 = 10 - 6 = 4$\n- $y_i \\geq 0$ (모든 $i$)\n\n**3단계: 중복조합 공식 적용**\n\n음이 아닌 정수해의 개수는:\n$$H(3, 4) = C(3+4-1, 4) = C(6, 4)$$\n\n**4단계: 조합 계산**\n\n$$C(6, 4) = C(6, 2) = \\frac{6 \\times 5}{2 \\times 1} = 15$$\n\n**[정답 확인]**\n변수 치환으로 조건을 제거하여 중복조합 공식을 적용한 결과 15가 나오므로 정답이다.\n\n**[오답 분석]**\n- 조건을 무시하고 $H(3,10) = C(12,10) = 66$으로 계산한 경우\n- 조건을 잘못 이해하여 정확한 개수(정확히 2개)로 해석한 경우\n- 계산 실수로 $C(6,4)$를 잘못 계산한 경우\n\n**[핵심 포인트]**\n조건이 있는 중복조합 문제에서는 **변수 치환**을 통해 조건을 제거한 후 표준 중복조합 공식을 적용하는 것이 핵심이다. 각 학생이 최소한 받아야 하는 양을 먼저 할당한 후 나머지를 자유롭게 분배하는 발상의 전환이 중요하다.",
