    "type": "중복순열·중복조합",
    "problem": "방정식 $x + y + z = 10$을 만족하는 음이 아닌 정수 해 중에서 $x \\leq 5,\\, y \\leq 5,\\, z \\leq 5$인 해의 개수는?",
    "answerType": "choice",
