    "answer": 0,
    "explanation": "**[핵심 개념]**\n이 문제는 중복조합(조합론) 문제이다. 음이 아닌 정수 $a, b, c, d$에 대하여 $a + b + c + d = n$을 만족하는 해의 개수는 중복조합 공식으로 구한다.\n\n$n$개의 같은 공을 $k$개의 서로 다른 상자에 넣는 경우의 수는 $\\binom{n+k-1}{k-1}$이다.\n\n**[풀이]**\n$a + b + c + d = n$을 만족하는 음이 아닌 정수해의 개수를 구하는 문제이다.\n\n**Step 1: 중복조합 공식 적용**\n\n4개의 변수($a, b, c, d$)가 있고, 합이 $n$인 음이 아닌 정수해의 개수는:\n$$\\binom{n+4-1}{4-1} = \\binom{n+3}{3}$$\n\n**Step 2: 주어진 조건 적용**\n\n이 값이 120이므로:\n$$\\binom{n+3}{3} = 120$$\n\n**Step 3: 조합값 계산**\n\n$$\\binom{n+3}{3} = \\frac{(n+3)(n+2)(n+1)}{3 \\times 2 \\times 1} = \\frac{(n+3)(n+2)(n+1)}{6} = 120$$\n\n따라서:\n$$(n+3)(n+2)(n+1) = 720$$\n\n**Step 4: 방정식 풀이**\n\n$n = 7$을 대입하면:\n$$(7+3)(7+2)(7+1) = 10 \\times 9 \\times 8 = 720$$ ✓\n\n따라서 $n = 7$이다.\n\n**[정답 확인]**\n$n=7$일 때 $\\binom{10}{3} = \\frac{10 \\times 9 \\times 8}{6} = \\frac{720}{6} = 120$으로 정확히 일치한다.\n\n**[오답 분석]**\n- ② $n=8$: $\\binom{11}{3} = \\frac{11 \\times 10 \\times 9}{6} = 165$ (❌)\n- ③ $n=9$: $\\binom{12}{3} = \\frac{12 \\times 11 \\times 10}{6} = 220$ (❌)\n- ④ $n=10$: $\\binom{13}{3} = \\frac{13 \\times 12 \\times 11}{6} = 286$ (❌)\n- ⑤ $n=11$: $\\binom{14}{3} = \\frac{14 \\times 13 \\times 12}{6} = 364$ (❌)\n\n**[핵심 포인트]**\n음이 아닌 정수해의 개수 문제는 **중복조합 공식** $\\binom{n+k-1}{k-1}$을 반드시 기억해야 한다. 여기서 $n$은 합, $k$는 변수의 개수이다.",
