    "problem": "$x + y + z = 15$를 만족하는 음이 아닌 정수 해 중에서 $x, y, z$가 모두 짝수인 해의 개수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 0,
    "explanation": "**[핵심 개념]**\n음이 아닌 정수해의 개수를 구하는 문제에서는 변수 치환을 통해 중복조합 공식을 적용한다. 또한 주어진 조건(짝수 조건)을 만족하는지 논리적으로 검토하는 것이 중요하다.\n\n중복조합 공식: $x_1 + x_2 + \\cdots + x_n = k$의 음이 아닌 정수해의 개수는 $\\binom{k+n-1}{n-1}$\n\n**[풀이]**\n\n**1단계: 짝수 조건 분석**\n\n$x, y, z$가 모두 짝수이므로 다음과 같이 놓을 수 있다.\n$$x = 2a, \\quad y = 2b, \\quad z = 2c$$\n여기서 $a, b, c$는 음이 아닌 정수이다.\n\n**2단계: 주어진 식에 대입**\n\n원래 식 $x + y + z = 15$에 대입하면:\n$$2a + 2b + 2c = 15$$\n$$2(a + b + c) = 15$$\n\n**3단계: 모순 확인**\n\n좌변 $2(a + b + c)$는 **짝수**이다.\n\n우변은 $15$이고, $15$는 **홀수**이다.\n\n따라서:\n$$\\text{짝수} = \\text{홀수}$$\n\n이는 모순이다.\n\n**4단계: 결론**\n\n$x + y + z = 15$를 만족하면서 $x, y, z$가 모두 짝수인 음이 아닌 정수해는 **존재하지 않는다**.\n\n따라서 해의 개수는 **0개**이다.\n\n**[정답 확인]**\n세 짝수의 합은 항상 짝수이지만, 주어진 합 15는 홀수이므로 조건을 만족하는 해가 존재할 수 없다.\n\n**[오답 분석]**\n- 학생들이 흔히 하는 실수: 변수 치환 후 중복조합만 계산하고, 그 과정에서 나타나는 모순을 간과하는 경우\n- 예를 들어 $a + b + c = 7.5$로 잘못 계산하고 정수해를 구하려는 착오\n\n**[핵심 포인트]**\n- **패리티(parity) 검토**: 홀짝성을 먼저 확인하면 불가능한 경우를 빠르게 파악할 수 있다.\n- 짝수 개의 짝수를 더하면 항상 짝수이고, 홀수 개의 홀수를 더하면 항상 홀수이다.",
