    "answer": 2,
    "explanation": "**[핵심 개념]**\n다항식을 전개할 때 서로 다른 항의 개수를 구하는 문제이다. $(x_1 + x_2 + x_3)^4$를 전개하면 $x_1^{a}x_2^{b}x_3^{c}$ 형태의 항들이 나오는데, 여기서 $a + b + c = 4$ (단, $a, b, c \\geq 0$인 음이 아닌 정수)를 만족하는 서로 다른 $(a, b, c)$ 조합의 개수를 구해야 한다. 이는 중복조합 문제이다.\n\n**[풀이]**\n\n$(x_1 + x_2 + x_3)^4$를 전개할 때 나타나는 항은 다항정리에 의해 다음과 같은 형태이다:\n\n$$x_1^{a}x_2^{b}x_3^{c} \\text{ (단, } a + b + c = 4, \\, a, b, c \\geq 0\\text{)}$$\n\n서로 다른 항의 개수는 조건을 만족하는 음이 아닌 정수해 $(a, b, c)$의 개수와 같다.\n\n이것은 **중복조합** 문제로, $n$개의 서로 다른 것 중에서 중복을 허용하여 $r$개를 뽑는 경우의 수는:\n\n$$H(n, r) = C(n+r-1, r) = \\binom{n+r-1}{r}$$\n\n우리의 경우 $n = 3$ (변수가 3개), $r = 4$ (지수의 합이 4)이므로:\n\n$$H(3, 4) = \\binom{3+4-1}{4} = \\binom{6}{4}$$\n\n$$= \\binom{6}{4} = \\frac{6!}{4! \\cdot 2!} = \\frac{6 \\times 5}{2 \\times 1} = 15$$\n\n**검증 (직접 나열):**\n- $a=4$: $(4,0,0)$ → 1개\n- $a=3$: $(3,1,0), (3,0,1)$ → 2개\n- $a=2$: $(2,2,0), (2,1,1), (2,0,2)$ → 3개\n- $a=1$: $(1,3,0), (1,2,1), (1,1,2), (1,0,3)$ → 4개\n- $a=0$: $(0,4,0), (0,3,1), (0,2,2), (0,1,3), (0,0,4)$ → 5개\n\n합계: $1 + 2 + 3 + 4 + 5 = 15$개\n\n**[정답 확인]**\n$a + b + c = 4$를 만족하는 음이 아닌 정수해의 개수는 중복조합 $\\binom{6}{4} = 15$이므로 정답은 ③이다.\n\n**[오답 분석]**\n- ① 10: $\\binom{5}{3}$으로 잘못 계산한 경우\n- ② 12: 계산 실수로 중복조합을 잘못 적용한 경우\n- ④ 20: $\\binom{6}{2}$로 잘못 계산한 경우\n- ⑤ 81: $3^4$로 계산하여 전개 후 동류항을 합치지 않은 경우\n\n**[핵심 포인트]**\n다항식 $(x_1 + x_2 + \\cdots + x_n)^r$의 서로 다른 항의 개수 = 중복조합 $H(n, r) = \\binom{n+r-1}{r}$. 지수의 합이 정해진 단항식의 개수를 구할 때는 **중복조합**을 사용한다.",
