    "problem": "$(1 + x)^5$를 전개할 때, $x^3$의 계수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[핵심 개념]**\n이항정리(Binomial Theorem)를 이용하여 $(1+x)^n$을 전개할 때 특정 항의 계수를 구하는 문제이다.\n\n이항정리: $(a+b)^n = \\sum_{k=0}^{n} \\binom{n}{k} a^{n-k} b^k$\n\n$(1+x)^n$의 경우, $x^r$항의 계수는 $\\binom{n}{r}$이다.\n\n**[풀이]**\n\n$(1+x)^5$를 이항정리로 전개하면:\n\n$$(1+x)^5 = \\sum_{k=0}^{5} \\binom{5}{k} \\cdot 1^{5-k} \\cdot x^k = \\sum_{k=0}^{5} \\binom{5}{k} x^k$$\n\n각 항은 :\n- $k=0$: $\\binom{5}{0}x^0 = 1$\n- $k=1$: $\\binom{5}{1}x^1 = 5x$\n- $k=2$: $\\binom{5}{2}x^2 = 10x^2$\n- $k=3$: $\\binom{5}{3}x^3 = ?x^3$ ← 구하려는 항\n- $k=4$: $\\binom{5}{4}x^4 = 5x^4$\n- $k=5$: $\\binom{5}{5}x^5 = x^5$\n\n$x^3$의 계수는 $\\binom{5}{3}$이다.\n\n$$\\binom{5}{3} = \\frac{5!}{3!(5-3)!} = \\frac{5!}{3! \\cdot 2!} = \\frac{5 \\times 4 \\times 3!}{3! \\times 2 \\times 1} = \\frac{5 \\times 4}{2 \\times 1} = \\frac{20}{2} = 10$$\n\n**[정답 확인]**\n$x^3$항의 계수를 구하는 조합 $\\binom{5}{3}$을 계산하면 10이 되어 정답과 일치한다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오답들:\n- **5**: $\\binom{5}{1}$을 구한 경우\n- **15**: 계산 실수로 $\\frac{5 \\times 4 \\times 3}{2}$를 계산한 경우\n- **20**: 분자 $5 \\times 4$만 구한 경우\n\n**[핵심 포인트]**\n$(1+x)^n$에서 $x^r$의 계수는 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이다. 이항정리를 사용하면 전개 없이 특정 항의 계수를 빠르게 구한다.",
