    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항정리(Binomial Theorem)를 이용하여 $(a+b)^n$을 전개할 때, 특정 항의 계수를 구하는 문제이다.\n\n$(a+b)^n$의 전개식에서 $a^{n-r}b^r$의 계수는 이항계수 $\\binom{n}{r}$이다.\n\n일반항: $(a+b)^n = \\sum_{r=0}^{n} \\binom{n}{r}a^{n-r}b^r$\n\n**[풀이]**\n\n$(a+b)^6$을 이항정리로 전개하면:\n\n$$\\sum_{r=0}^{6} \\binom{6}{r}a^{6-r}b^r$$\n\n$a^4b^2$항을 찾기 위해 지수를 비교한다.\n- $a$의 지수: $6-r = 4$ → $r = 2$\n- $b$의 지수: $r = 2$ ✓\n\n따라서 $a^4b^2$의 계수는 $r=2$일 때의 이항계수 $\\binom{6}{2}$이다.\n\n$$\\binom{6}{2} = \\frac{6!}{2!(6-2)!} = \\frac{6!}{2! \\cdot 4!}$$\n\n$$= \\frac{6 \\times 5 \\times 4!}{2 \\times 1 \\times 4!} = \\frac{6 \\times 5}{2} = \\frac{30}{2} = 15$$\n\n**[정답 확인]**\n\n$(a+b)^6$의 전개식에서 $a^4b^2$항의 계수는 이항계수 $\\binom{6}{2} = 15$이므로 정답은 **③**이다.\n\n**[오답 분석]**\n\n- ① 6: $\\binom{6}{1}$의 값, $r=1$일 때의 계수\n- ② 10: $\\binom{5}{2}$의 값, 잘못된 계산\n- ④ 20: $\\binom{6}{2} \\times 2$ 등 계산 오류\n- ⑤ 30: 분자 $6 \\times 5$만 계산하고 분모를 나누지 않은 실수\n\n**[핵심 포인트]**\n\n$(a+b)^n$에서 $a^{n-r}b^r$의 계수는 **$\\binom{n}{r}$**이다. 지수의 합이 $n$이 되는 $r$값을 찾아 이항계수를 계산하면 된다.",
