    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. \n$(1-x)^4$를 전개할 때는 $a=1$, $b=-x$, $n=4$로 놓고, 원하는 항의 계수를 구한다.\n\n**[풀이]**\n$(1-x)^4$의 전개식에서 일반항은 $$\\binom{4}{r}(1)^{4-r}(-x)^r = \\binom{4}{r}(-1)^r x^r$$\n\n$x^3$의 계수를 구하려면 $r=3$을 대입한다.\n\n$$\\binom{4}{3}(-1)^3 x^3 = \\binom{4}{3} \\times (-1) \\times x^3$$\n\n이항계수 $\\binom{4}{3}$을 계산하면:\n\n$$\\binom{4}{3} = \\frac{4!}{3!(4-3)!} = \\frac{4!}{3! \\cdot 1!} = \\frac{4 \\times 3!}{3! \\times 1} = 4$$\n\n따라서 $x^3$의 계수는:\n\n$$4 \\times (-1) = -4$$\n\n**[정답 확인]**\n$(1-x)^4$를 전개하면 $(1-x)^4 = 1 - 4x + 6x^2 - 4x^3 + x^4$이므로 $x^3$의 계수는 $-4$이다.\n\n**[오답 분석]**\n- ② -1: 이항계수를 구하지 않고 $(-1)^3$만 계산한 경우\n- ③ 1: 부호를 무시하고 절댓값만 구한 경우\n- ④ 4: 이항계수 $\\binom{4}{3}=4$만 구하고 음수 부호를 빠뜨린 경우\n- ⑤ 6: $\\binom{4}{2}$를 잘못 구한 경우\n\n**[핵심 포인트]**\n이항정리에서 $(a+b)^n$의 일반항 $\\binom{n}{r}a^{n-r}b^r$에서 $b$가 음수일 때는 $(-1)^r$의 부호를 반드시 포함해야 한다.",
