    "explanation": "**[핵심 개념]**\n이항정리(Binomial Theorem)는 $(a+b)^n$을 전개할 때 일반항을 이용하여 특정 항의 계수를 구하는 방법이다.\n\n$(a+b)^n = \\sum_{k=0}^{n} \\binom{n}{k} a^{n-k} b^k$\n\n여기서 $\\binom{n}{k} = \\frac{n!}{k!(n-k)!}$는 이항계수이다.\n\n**[풀이]**\n\n$(x+1)^8$의 전개식에서 일반항은 $$T_{k+1} = \\binom{8}{k} x^{8-k} \\cdot 1^k = \\binom{8}{k} x^{8-k}$$\n\n$x^5$항을 찾기 위해 $8-k=5$가 되는 $k$값을 구한다.\n\n$$8-k=5 \\Rightarrow k=3$$\n\n따라서 $x^5$의 계수는 $k=3$일 때의 이항계수이다.\n\n$$\\binom{8}{3} = \\frac{8!}{3!(8-3)!} = \\frac{8!}{3! \\cdot 5!}$$\n\n$$= \\frac{8 \\times 7 \\times 6 \\times 5!}{3! \\times 5!} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1}$$\n\n$$= \\frac{8 \\times 7 \\times 6}{6} = 8 \\times 7 = 56$$\n\n**[정답 확인]**\n$(x+1)^8$을 전개할 때 $x^5$항은 $\\binom{8}{3}x^5$이므로 계수는 56이다.\n\n**[오답 분석]**\n객관식 선지가 주어지지 않았으나, 일반적인 오답은:\n- $\\binom{8}{5}=56$으로 계산하는 경우: 공식은 같지만 순서만 다르므로 결과는 같음 (대칭성)\n- $\\binom{8}{2}=28$: $k$값을 잘못 설정\n- $\\binom{8}{4}=70$: $8-k$를 계산할 때 실수\n\n**[핵심 포인트]**\n이항정리에서 $x^m$항을 찾을 때는 지수가 정확히 $m$이 되는 $k$값을 먼저 찾은 후, 해당하는 이항계수를 계산하면 된다. $\\binom{n}{k}=\\binom{n}{n-k}$의 대칭성도 활용할 수 있다.",
