    "answer": 1,
    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$의 전개식에서 특정 항의 계수를 구하는 문제이다.\n\n이항정리: $(a+b)^n = \\sum_{r=0}^{n} \\binom{n}{r}a^{n-r}b^r$\n\n$(a-b)^n$의 경우 $b$ 대신 $-b$를 대입하면 되므로, 일반항은 $\\binom{n}{r}a^{n-r}(-b)^r = \\binom{n}{r}(-1)^r a^{n-r}b^r$이다.\n\n**[풀이]**\n\n$(a-b)^5$의 전개식에서 일반항은:\n$$\\binom{5}{r}a^{5-r}(-b)^r = \\binom{5}{r}(-1)^r a^{5-r}b^r$$\n\n$a^2b^3$항을 얻기 위해서는 $a$의 지수가 2, $b$의 지수가 3이어야 한다.\n\n일반항에서 $5-r=2$이고 $r=3$이어야 하므로:\n- $5-r=2$ → $r=3$ ✓\n\n따라서 $a^2b^3$의 계수는:\n$$\\binom{5}{3}(-1)^3 = \\binom{5}{3} \\times (-1)$$\n\n$\\binom{5}{3}$을 계산하면:\n$$\\binom{5}{3} = \\frac{5!}{3! \\times 2!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n따라서 $a^2b^3$의 계수는:\n$$10 \\times (-1) = -10$$\n\n**[정답 확인]**\n이항정리를 올바르게 적용하여 $r=3$일 때의 계수를 구하면 $10 \\times (-1) = -10$이므로 ②번이 정답이다.\n\n**[오답 분석]**\n- ① -20: $\\binom{5}{3}$을 2배로 잘못 계산한 경우\n- ③ 5: $\\binom{5}{3} = 10$을 반으로 나누고 음수 부호를 빠뜨린 경우\n- ④ 10: $(-1)^3 = -1$을 곱하지 않아 음수 부호를 빠뜨린 경우\n- ⑤ 20: $\\binom{5}{3}$을 2배로 계산하고 음수 부호를 빠뜨린 경우\n\n**[핵심 포인트]**\n$(a-b)^n$에서는 반드시 $(-1)^r$을 곱해야 하며, 특정 항의 지수 조건을 정확히 파악하여 $r$값을 결정하는 것이 중요하다.",
