    "problem": "$(2x + 3)^5$의 전개식에서 $x^3$의 계수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 720,
    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 특정 항의 계수를 구하기 위해서는 원하는 차수를 만드는 $r$ 값을 찾고, 그에 해당하는 이항계수와 계수들을 곱해야 한다.\n\n**[풀이]**\n$(2x+3)^5$의 전개식에서 이항정리를 적용하면:\n\n$$(2x+3)^5 = \\sum_{r=0}^{5} \\binom{5}{r}(2x)^{5-r}(3)^r$$\n\n일반항은:\n$$\\binom{5}{r}(2x)^{5-r} \\cdot 3^r = \\binom{5}{r} \\cdot 2^{5-r} \\cdot x^{5-r} \\cdot 3^r$$\n\n$x^3$의 계수를 구하려면 $x$의 지수가 3이어야 하므로:\n$$5-r = 3$$\n$$r = 2$$\n\n따라서 $x^3$ 항은 $r=2$일 때이고, 그 계수는:\n\n$$\\binom{5}{2} \\cdot 2^{5-2} \\cdot 3^2$$\n\n각 부분을 계산하면:\n- $\\binom{5}{2} = \\frac{5!}{2!3!} = \\frac{5 \\times 4}{2 \\times 1} = 10$\n- $2^{5-2} = 2^3 = 8$\n- $3^2 = 9$\n\n따라서 $x^3$의 계수는:\n$$10 \\times 8 \\times 9 = 80 \\times 9 = 720$$\n\n**[정답 확인]**\n이항정리의 일반항 공식을 올바르게 적용하여 $r=2$일 때의 계수를 구한 결과가 720이므로 정답이다.\n\n**[오답 분석]**\n- 240: 이항계수를 잘못 계산했거나($\\binom{5}{2}=5$로 잘못 계산), $2^3$을 빼먹은 경우\n- 360: $2^3 \\times 3^2$만 계산하고 이항계수를 빼먹은 경우\n- 540: 이항계수나 지수 계산 과정에서 오류가 발생한 경우\n\n**[핵심 포인트]**\n$(ax+b)^n$ 형태의 전개식에서 특정 차수의 계수를 구할 때는 **세 가지 요소(이항계수, 밑의 계수의 거듭제곱, 상수항의 거듭제곱)를 모두 곱해야** 한다는 것을 기억하세요.",
