    "problem": "$(x + \\frac{1}{x})^6$의 전개식에서 상수항을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 20,
    "explanation": "**[핵심 개념]**\n이항정리를 이용한 전개식에서 특정 항을 찾는 문제이다. 이항정리에 의해 $(a+b)^n$을 전개하면 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 상수항은 문자가 포함되지 않은 항이므로, 지수의 합이 0이 되는 경우를 찾아야 한다.\n\n**[풀이]**\n\n이항정리를 적용하여 $(x + \\frac{1}{x})^6$을 전개한다.\n\n일반항은 :\n$$T_{r+1} = \\binom{6}{r}x^{6-r}\\left(\\frac{1}{x}\\right)^r = \\binom{6}{r}x^{6-r} \\cdot x^{-r} = \\binom{6}{r}x^{6-r-r} = \\binom{6}{r}x^{6-2r}$$\n\n상수항이 되려면 $x$의 지수가 0이어야 하므로:\n$$6-2r = 0$$\n$$2r = 6$$\n$$r = 3$$\n\n따라서 상수항은 $r=3$일 때의 항이다.\n\n$$T_{3+1} = T_4 = \\binom{6}{3}x^0 = \\binom{6}{3}$$\n\n이항계수를 계산한다:\n$$\\binom{6}{3} = \\frac{6!}{3!3!} = \\frac{6 \\times 5 \\times 4}{3 \\times 2 \\times 1} = \\frac{120}{6} = 20$$\n\n**[정답 확인]**\n$r=3$일 때 $x$의 지수가 정확히 0이 되므로 상수항이며, 그 계수는 $\\binom{6}{3} = 20$이다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 상수항을 구할 때 흔한 오류는:\n- 일반항에서 $x$의 지수를 잘못 계산하는 경우\n- 지수를 0이 되게 하는 $r$ 값을 찾지 못하는 경우\n- 이항계수 $\\binom{6}{3}$을 잘못 계산하는 경우 (예: 15, 18 등)\n\n**[핵심 포인트]**\n$(x + \\frac{1}{x})^n$ 형태의 전개식에서 상수항은 $x^{n-r} \\cdot x^{-r} = x^{n-2r}$의 지수가 0일 때이므로 $r = \\frac{n}{2}$이다. 이 문제에서는 $r=3$이고 상수항의 값은 $\\binom{6}{3}$이다.",
