    "problem": "$_8C_0 - _8C_1 + _8C_2 - _8C_3 + \\cdots + _8C_8$의 값은?",
    "answerType": "choice",
    "choices": [
      "① $-1$",
      "② $0$",
      "③ $1$",
      "④ $128$",
      "⑤ $256$"
    ],
    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n이항정리(Binomial Theorem)를 이용한 이항계수의 합 문제이다.\n\n이항정리: $(x+y)^n = \\sum_{k=0}^{n} _nC_k x^{n-k}y^k$\n\n$x=1, y=1$을 대입하면: $(1+1)^n = \\sum_{k=0}^{n} _nC_k = 2^n$\n\n$x=1, y=-1$을 대입하면: $(1-1)^n = \\sum_{k=0}^{n} _nC_k (-1)^k$\n\n**[풀이]**\n\n주어진 식을 정리하면:\n$$_8C_0 - _8C_1 + _8C_2 - _8C_3 + \\cdots + _8C_8 = \\sum_{k=0}^{8} _8C_k (-1)^k$$\n\n이항정리에서 $x=1, y=-1$을 대입한다:\n\n$$(1-1)^8 = \\sum_{k=0}^{8} _8C_k \\cdot 1^{8-k} \\cdot (-1)^k$$\n\n$$0^8 = \\sum_{k=0}^{8} _8C_k (-1)^k$$\n\n$$0 = _8C_0 - _8C_1 + _8C_2 - _8C_3 + \\cdots + _8C_8$$\n\n**[정답 확인]**\n\n$(1-1)^8 = 0^8 = 0$이므로, 주어진 교대합은 0이 된다.\n\n**[오답 분석]**\n\n- ① $-1$: $(1-1)^n$이 $-1$이 되려면 홀수 제곱이어야 하는데, 8은 짝수이다.\n- ③ $1$: $(1-1)^8 \\neq 1$이다. 이는 $(1+1)^8 = 256$과 혼동한 경우이다.\n- ④ $128$: $2^7 = 128$로, $n=7$일 때의 값이다.\n- ⑤ $256$: $2^8 = 256$으로, 부호가 모두 양수인 $\\sum_{k=0}^{8} _8C_k$의 값이다.\n\n**[핵심 포인트]**\n\n교대합 $\\sum_{k=0}^{n} _nC_k (-1)^k$는 $(1-1)^n = 0^n$이므로, $n$이 양수일 때 항상 **0**이다. 이항정리에서 $y=-1$을 대입하는 것이 교대합을 구하는 핵심 기법이다.",
