    "answer": 240,
    "explanation": "**[핵심 개념]**\n이항정리(Binomial Theorem)를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 :\n$$\\binom{n}{r}a^{n-r}b^r$$\n여기서 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$는 이항계수이다. 특정 항의 계수를 구하려면 주어진 지수 조건을 만족하는 $r$ 값을 찾아야 한다.\n\n**[풀이]**\n$(1+2x)^6$을 이항정리로 전개하면, 일반항은:\n$$\\binom{6}{r}(1)^{6-r}(2x)^r = \\binom{6}{r}(2x)^r = \\binom{6}{r}2^r x^r$$\n\n$x^4$의 계수를 구하려면 $r=4$일 때의 항을 찾으면 된다.\n\n$r=4$일 때:\n$$\\binom{6}{4}2^4 x^4$$\n\n각 부분을 계산한다:\n\n**이항계수 계산:**\n$$\\binom{6}{4} = \\frac{6!}{4!(6-4)!} = \\frac{6!}{4! \\cdot 2!} = \\frac{6 \\times 5}{2 \\times 1} = \\frac{30}{2} = 15$$\n\n**$2^4$ 계산:**\n$$2^4 = 16$$\n\n**$x^4$의 계수:**\n$$15 \\times 16 = 240$$\n\n**[정답 확인]**\n$(1+2x)^6$에서 $x^4$의 계수는 $\\binom{6}{4} \\times 2^4 = 15 \\times 16 = 240$이므로 정답이다.\n\n**[오답 분석]**\n- **160**: $\\binom{6}{4} \\times 2^3 = 15 \\times 8$을 계산한 오류 (지수를 3으로 착각)\n- **96**: $\\binom{6}{3} \\times 2^4 = 20 \\times 8$을 계산한 오류 (r값을 3으로 착각하거나 계산 실수)\n- **60**: $\\binom{6}{4} \\times 2^2 = 15 \\times 4$을 계산한 오류 ($(2x)^r$에서 지수를 잘못 처리)\n\n**[핵심 포인트]**\n이항정리에서 $(a+b)^n$을 전개할 때, 특정 항의 계수는 $\\binom{n}{r} \\times a^{n-r} \\times b^r$에서 원하는 문자의 지수를 만족하는 $r$을 찾은 후 계산하면 된다. 여기서는 $(2x)^r$의 지수 $r=4$가 $x^4$를 만드는 것을 정확히 파악하는 것이 중요하다.",
