    "explanation": "**[핵심 개념]**\n이항정리(Binomial Theorem)를 이용하여 $(1+x)^n$을 전개할 때, $x^r$의 계수를 구하는 문제이다.\n\n이항정리: $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$\n\n여기서 $x^k$의 계수는 이항계수 $\\binom{n}{k} = \\frac{n!}{k!(n-k)!}$ 이다.\n\n**[풀이]**\n\n**Step 1: $x^4$의 계수 $a$ 구하기**\n\n$(1+x)^{10}$을 이항정리로 전개하면:\n$$\\binom{10}{0} + \\binom{10}{1}x + \\binom{10}{2}x^2 + \\cdots + \\binom{10}{10}x^{10}$$\n\n$x^4$의 계수는:\n$$a = \\binom{10}{4} = \\frac{10!}{4! \\cdot 6!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1}$$\n\n$$= \\frac{10 \\times 9 \\times 8 \\times 7}{24} = \\frac{5040}{24} = 210$$\n\n**Step 2: $x^6$의 계수 $b$ 구하기**\n\n$x^6$의 계수는:\n$$b = \\binom{10}{6} = \\frac{10!}{6! \\cdot 4!}$$\n\n이항계수의 대칭성 $\\binom{n}{k} = \\binom{n}{n-k}$를 이용하면:\n$$\\binom{10}{6} = \\binom{10}{4} = 210$$\n\n**Step 3: $a + b$ 계산**\n\n$$a + b = 210 + 210 = 420$$\n\n**[정답 확인]**\n이항계수의 대칭성에 의해 $\\binom{10}{4} = \\binom{10}{6} = 210$이므로, $a + b = 420$이 정답이다.\n\n**[오답 분석]**\n- ① 210: $a$만 구한 값\n- ② 330: 계산 오류 (예: $\\binom{10}{3} + \\binom{10}{4}$ 등)\n- ④ 462: $\\binom{11}{5}$ 등 다른 이항계수\n- ⑤ 504: 계산 오류로 인한 결과\n\n**[핵심 포인트]**\n1. 이항정리에서 $(1+x)^n$의 $x^k$ 계수는 $\\binom{n}{k}$이다.\n2. 이항계수의 대칭성 $\\binom{n}{k} = \\binom{n}{n-k}$를 활용하면 계산을 단순화할 수 있다.",
