    "problem": "$(x + \\frac{2}{x})^8$의 전개식에서 $x^2$의 계수를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 448,
    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 주어진 식을 전개한 후 특정 차수의 항을 찾기 위해 지수 조건을 세워 계수를 구한다.\n\n**[풀이]**\n\n$(x + \\frac{2}{x})^8$을 이항정리로 전개하면:\n\n$$\\left(x + \\frac{2}{x}\\right)^8 = \\sum_{r=0}^{8} \\binom{8}{r} x^{8-r} \\left(\\frac{2}{x}\\right)^r$$\n\n일반항을 정리하면:\n\n$$\\binom{8}{r} x^{8-r} \\cdot \\frac{2^r}{x^r} = \\binom{8}{r} \\cdot 2^r \\cdot x^{8-r-r} = \\binom{8}{r} \\cdot 2^r \\cdot x^{8-2r}$$\n\n$x^2$항을 구하기 위해 지수가 2가 되는 조건:\n\n$$8-2r = 2$$\n$$2r = 6$$\n$$r = 3$$\n\n$r=3$일 때 계수는:\n\n$$\\binom{8}{3} \\cdot 2^3 = \\frac{8!}{3!5!} \\cdot 8$$\n\n$$= \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} \\times 8$$\n\n$$= \\frac{336}{6} \\times 8$$\n\n$$= 56 \\times 8$$\n\n$$= 448$$\n\n**[정답 확인]**\n$r=3$을 대입하여 지수를 확인하면 $x^{8-6}=x^2$이 되고, 계수 $\\binom{8}{3} \\cdot 2^3 = 56 \\times 8 = 448$로 정답과 일치한다.\n\n**[오답 분석]**\n- 지수 계산 오류: $8-2r$을 잘못 계산하면 다른 $r$값을 얻음\n- 계수 계산 오류: $\\binom{8}{3}=56$을 잘못 구하거나 $2^3=8$을 빠뜨리면 오답 도출\n\n**[핵심 포인트]**\n일반항에서 $x$의 지수를 정확히 $8-2r$로 정리한 후, 원하는 차수가 되는 $r$값을 찾는 것이 핵심이다. 이항계수와 밑의 거듭제곱을 모두 곱해야 최종 계수를 얻는다.",
