    "problem": "$(1+x)^{12}$의 전개식에서 계수가 최대인 항의 $x$의 차수는?",
    "answerType": "choice",
    "choices": [
      "① 4",
      "② 5",
      "③ 6",
      "④ 7",
      "⑤ 8"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항정리에 의해 $(1+x)^{12}$의 전개식은 $\\sum_{r=0}^{12} \\binom{12}{r}x^r$ 이고, 각 항의 계수는 이항계수 $\\binom{12}{r}$이다. 이항계수의 최댓값을 찾기 위해 인접한 항들의 계수 비율을 비교한다. $\\binom{n}{r}$에서 $n$이 짝수일 때, 계수는 $r = \\frac{n}{2}$에서 최대이다.\n\n**[풀이]**\n\n$(1+x)^{12}$의 전개식에서 $x^r$ 항의 계수는 $\\binom{12}{r}$이다.\n\n이항계수의 최댓값을 찾기 위해 인접한 두 항의 비율을 살펴봅시다.\n\n$$\\frac{\\binom{12}{r+1}}{\\binom{12}{r}} = \\frac{\\frac{12!}{(r+1)!(11-r)!}}{\\frac{12!}{r!(12-r)!}} = \\frac{12-r}{r+1}$$\n\n계수가 계속 증가하려면 이 비율이 1보다 커야 한다:\n\n$$\\frac{12-r}{r+1} > 1$$\n\n$$12-r > r+1$$\n\n$$11 > 2r$$\n\n$$r < 5.5$$\n\n따라서 $r \\leq 5$일 때 계수가 증가하고, $r \\geq 6$일 때 계수가 감소한다.\n\n$r = 5$와 $r = 6$에서의 계수를 비교하면:\n- $\\binom{12}{5} = \\frac{12!}{5! \\cdot 7!} = \\frac{12 \\times 11 \\times 10 \\times 9 \\times 8}{5 \\times 4 \\times 3 \\times 2 \\times 1} = 792$\n- $\\binom{12}{6} = \\frac{12!}{6! \\cdot 6!} = 924$\n\n$\\binom{12}{6} > \\binom{12}{5}$이므로, 계수의 최댓값은 $r = 6$에서 달성된다.\n\n또는 $n=12$(짝수)이므로 $r = \\frac{12}{2} = 6$에서 최대이다.\n\n**[정답 확인]**\n\n$(1+x)^{12}$에서 $n=12$는 짝수이므로, 이항계수는 $r = \\frac{12}{2} = 6$에서 최대값 $\\binom{12}{6} = 924$를 가진다.\n\n**[오답 분석]**\n\n- **①, ②번**: $r = 4, 5$일 때의 계수는 최댓값보다 작다. ($\\binom{12}{4} = 495$, $\\binom{12}{5} = 792$)\n- **④, ⑤번**: $r = 7, 8$일 때의 계수는 감소한다. ($\\binom{12}{7} = 792$, $\\binom{12}{8} = 495$) 이들은 대칭성에 의해 $r=5, 4$와 같지만, 최댓값이 아닙니다.\n\n**[핵심 포인트]**\n\n$(1+x)^n$의 전개식에서 $n$이 짝수일 때, 계수의 최댓값은 $r = \\frac{n}{2}$인 항에서 나타난다. 인접 계수의 비율 $\\frac{\\binom{n}{r+1}}{\\binom{n}{r}} = \\frac{n-r}{r+1}$를 이용하면 최대값의 위치를 쉽게 찾을 수 있다.",
