    "problem": "$(1+x)^{10}$의 전개식에서 $_{10}C_0 + _{10}C_2 + _{10}C_4 + \\cdots + _{10}C_{10}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 512,
    "explanation": "**[핵심 개념]**\n이항정리에 의해 $(1+x)^n = \\sum_{k=0}^{n} _nC_k x^k$로 전개된다. 이 식에 특정 $x$ 값을 대입하면 이항계수들의 합을 구한다. 특히 $x=1$과 $x=-1$을 이용하면 짝수 항의 계수만 또는 홀수 항의 계수만 더할 수 있다.\n\n**[풀이]**\n\n$(1+x)^{10}$을 이항정리로 전개하면:\n$$\\displaystyle (1+x)^{10} = _10C_0 + _10C_1x + _10C_2x^2 + _10C_3x^3 + \\cdots + _10C_{10}x^{10}$$\n\n**Step 1:** $x=1$을 대입\n$$(1+1)^{10} = _10C_0 + _10C_1 + _10C_2 + _10C_3 + \\cdots + _10C_{10}$$\n$$2^{10} = \\sum_{k=0}^{10} _10C_k = 1024 \\quad \\cdots (1)$$\n\n**Step 2:** $x=-1$을 대입\n$$(1-1)^{10} = _10C_0 - _10C_1 + _10C_2 - _10C_3 + \\cdots + _10C_{10}$$\n$$0 = _10C_0 - _10C_1 + _10C_2 - _10C_3 + \\cdots + _10C_{10} \\quad \\cdots (2)$$\n\n(우변은 짝수 항은 양수, 홀수 항은 음수이므로)\n\n**Step 3:** (1)과 (2)를 더하기\n\n$$(1) + (2): 1024 + 0 = 2(_10C_0 + _10C_2 + _10C_4 + \\cdots + _10C_{10})$$\n\n$$1024 = 2(_10C_0 + _10C_2 + _10C_4 + \\cdots + _10C_{10})$$\n\n$$_10C_0 + _10C_2 + _10C_4 + \\cdots + _10C_{10} = \\frac{1024}{2} = 512$$\n\n**[정답 확인]**\n$x=1$과 $x=-1$을 대입한 두 식을 더하면 짝수 인덱스 항만 2배 남고 홀수 인덱스 항은 소거되어, 짝수 인덱스 이항계수의 합을 구한다.\n\n**[오답 분석]**\n- **256**: $2^8$을 얻는 실수로, 지수를 잘못 이용한 경우\n- **1024**: $2^{10}$ 전체 합을 구한 경우로, 짝수 항만 골라야 한다는 조건을 놓친 경우\n- **600**: 계산 과정에서 나눗셈을 제대로 하지 않은 경우\n\n**[핵심 포인트]**\n이항정리에서 $x=1$과 $x=-1$을 번갈아 대입하면 짝수 항의 합과 홀수 항의 합을 각각 구한다. 이는 이항계수의 합 문제에서 매우 유용한 기법이다.",
