    "explanation": "**[핵심 개념]**\n어떤 수를 특정 수로 나눈 나머지를 구할 때는 modular arithmetic(합동식)을 이용한다. 특히 $a^n \\pmod{m}$을 구할 때는 지수를 단계적으로 줄여가며 계산하는 방법이 효율적이다. $11^5 \\pmod{100}$을 구하기 위해 $11$의 거듭제곱을 순차적으로 계산하여 $100$으로 나눈 나머지를 추적한다.\n\n**[풀이]**\n$11^5$을 $100$으로 나눈 나머지를 구하기 위해 단계적으로 계산한다.\n\n먼저 $11$의 낮은 차수 거듭제곱부터 구한다.\n\n$11^1 = 11$\n\n$11^2 = 121 \\equiv 21 \\pmod{100}$\n($121 = 100 \\times 1 + 21$)\n\n$11^3 = 11^2 \\times 11 \\equiv 21 \\times 11 \\pmod{100}$\n$21 \\times 11 = 231 \\equiv 31 \\pmod{100}$\n($231 = 100 \\times 2 + 31$)\n\n$11^4 = 11^3 \\times 11 \\equiv 31 \\times 11 \\pmod{100}$\n$31 \\times 11 = 341 \\equiv 41 \\pmod{100}$\n($341 = 100 \\times 3 + 41$)\n\n$11^5 = 11^4 \\times 11 \\equiv 41 \\times 11 \\pmod{100}$\n$41 \\times 11 = 451 \\equiv 51 \\pmod{100}$\n($451 = 100 \\times 4 + 51$)\n\n따라서 $11^5 \\equiv 51 \\pmod{100}$\n\n**[정답 확인]**\n$11^5 = 161051 = 100 \\times 1610 + 51$이므로 $11^5$을 $100$으로 나눈 나머지는 정확히 $51$이다.\n\n**[오답 분석]**\n선택지가 없으나, 흔한 오답은:\n- $41$: $11^4 \\pmod{100}$의 값을 실수로 선택한 경우\n- $31$: $11^3 \\pmod{100}$의 값을 실수로 선택한 경우\n- $21$: $11^2 \\pmod{100}$의 값을 실수로 선택한 경우\n\n**[핵심 포인트]**\n큰 거듭제곱의 나머지를 구할 때는 한 단계씩 계산하면서 매번 나머지를 구해 수를 작게 유지하는 것이 중요하다. $11^n \\pmod{100}$은 일의 자리가 패턴을 보이므로($1, 1, 1, 1, ...$) 십의 자리의 변화를 추적하면 더 쉽게 규칙을 찾을 수 있다.",
