    "answer": 2,
    "explanation": "**[핵심 개념]**\n이항정리에 의해 $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$로 전개된다.\n- $x$의 계수: $\\binom{n}{1} = n$\n- $x^2$의 계수: $\\binom{n}{2} = \\frac{n(n-1)}{2}$\n\n주어진 조건을 식으로 세워 $n$을 구하는 문제이다.\n\n**[풀이]**\n\n**1단계: 각 항의 계수 구하기**\n\n$(1+x)^n$을 이항정리로 전개하면:\n$$x \\text{의 계수} = \\binom{n}{1} = n$$\n\n$$x^2 \\text{의 계수} = \\binom{n}{2} = \\frac{n(n-1)}{2}$$\n\n**2단계: 주어진 조건을 식으로 표현**\n\n문제에서 \"$x^2$의 계수가 $x$의 계수의 4배\"라고 했으므로:\n$$\\frac{n(n-1)}{2} = 4n$$\n\n**3단계: 방정식 풀기**\n\n양변에 2를 곱하면:\n$$n(n-1) = 8n$$\n\n$n$은 자연수이므로 $n \\neq 0$, 양변을 $n$으로 나누면:\n$$n-1 = 8$$\n\n$$n = 9$$\n\n**4단계: 검증**\n\n$n=9$일 때:\n- $x$의 계수: $9$\n- $x^2$의 계수: $\\frac{9 \\times 8}{2} = 36$\n- $36 = 4 \\times 9$ ✓\n\n**[정답 확인]**\n$n=9$일 때 $x^2$의 계수 36이 $x$의 계수 9의 정확히 4배이므로 조건을 만족한다.\n\n**[오답 분석]**\n- ① $n=7$: $x^2$의 계수 = $21$, $x$의 계수 = $7$ → $21 \\neq 4 \\times 7 = 28$ ✗\n- ② $n=8$: $x^2$의 계수 = $28$, $x$의 계수 = $8$ → $28 \\neq 4 \\times 8 = 32$ ✗\n- ④ $n=10$: $x^2$의 계수 = $45$, $x$의 계수 = $10$ → $45 \\neq 4 \\times 10 = 40$ ✗\n- ⑤ $n=11$: $x^2$의 계수 = $55$, $x$의 계수 = $11$ → $55 \\neq 4 \\times 11 = 44$ ✗\n\n**[핵심 포인트]**\n이항정리에서 $x^k$의 계수는 $\\binom{n}{k}$이며, 주어진 조건을 등식으로 세운 후 정리하면 $n-1=8$이라는 간단한 일차방정식이 된다. 계산 실수에 주의해야 한다.",
