    "problem": "$(x - \\frac{1}{x})^9$의 전개식에서 $x^3$의 계수는?",
    "answerType": "choice",
    "choices": [
      "① $-84$",
      "② $-36$",
      "③ $36$",
      "④ $84$",
      "⑤ $126$"
    ],
    "answer": 0,
    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. \n$(x - \\frac{1}{x})^9$를 전개하면 여러 항이 나오는데, 이 중에서 $x^3$항만 찾아야 한다.\n일반항에서 $x$의 지수를 구하는 식: $(n-r) + r' = $ 원하는 지수 형태로 계산한다.\n\n**[풀이]**\n\n이항정리를 적용하면:\n$$(x - \\frac{1}{x})^9 = \\sum_{r=0}^{9} \\binom{9}{r}x^{9-r}\\left(-\\frac{1}{x}\\right)^r$$\n\n일반항을 정리하면:\n$$\\binom{9}{r}x^{9-r} \\cdot (-1)^r \\cdot x^{-r} = \\binom{9}{r}(-1)^r x^{9-r-r} = \\binom{9}{r}(-1)^r x^{9-2r}$$\n\n$x^3$항을 찾기 위해 지수가 3이 되어야 하므로:\n$$9 - 2r = 3$$\n$$2r = 6$$\n$$r = 3$$\n\n$r=3$일 때 계수는:\n$$\\binom{9}{3}(-1)^3 = \\frac{9!}{3!6!} \\times (-1)$$\n\n$$= \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} \\times (-1)$$\n\n$$= \\frac{504}{6} \\times (-1)$$\n\n$$= 84 \\times (-1)$$\n\n$$= -84$$\n\n**[정답 확인]**\n$r=3$을 대입하면 $x^{9-6}=x^3$이 되고, 계수 $\\binom{9}{3}(-1)^3 = 84 \\times (-1) = -84$이므로 ①번이 정답이다.\n\n**[오답 분석]**\n- ② $-36$: $\\binom{9}{3} = 84$인데 절반으로 잘못 계산한 경우\n- ③ $36$: 음수 부호를 놓친 경우\n- ④ $84$: $(-1)^3$의 음수를 빠뜨린 경우\n- ⑤ $126$: $\\binom{9}{2}=36$ 등 다른 이항계수와 혼동한 경우\n\n**[핵심 포인트]**\n1. 이항전개에서 $x$의 지수는 $(n-r)+(-r) = n-2r$ 형태로 계산된다는 것을 정확히 파악하기\n2. $(-\\frac{1}{x})^r = (-1)^r x^{-r}$에서 $(-1)^r$의 부호를 꼭 포함시켜야 함",
