    "problem": "$(1 + x)^{20}$의 전개식에서 $_{20}C_r$이 최대가 되는 $r$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[핵심 개념]**\n이항계수 $_nC_r$의 최댓값은 $n$이 짝수일 때 $r = \\frac{n}{2}$에서 달성된다. 이는 $_nC_r$이 $r$이 증가할수록 처음에는 증가하다가 중간값에서 최대가 된 후 감소하는 대칭성 때문이다. 일반적으로 $_nC_r$과 $_{nC_{r+1}}$의 대소를 비교하기 위해 비율 $\\frac{_{nC_{r+1}}}{_nC_r}$을 이용한다.\n\n**[풀이]**\n$(1+x)^{20}$의 전개식에서 일반항의 계수는 $_20C_r$이다. $_20C_r$이 최대가 되는 $r$을 찾기 위해 이항계수의 성질을 이용한다.\n\n이항계수의 비를 구하면:\n$$\\frac{_{20}C_{r+1}}{_{20}C_r} = \\frac{\\frac{20!}{(r+1)!(20-r-1)!}}{\\frac{20!}{r!(20-r)!}} = \\frac{20-r}{r+1}$$\n\n$_{20}C_r$이 증가하려면 $\\frac{_{20}C_{r+1}}{_{20}C_r} > 1$이어야 하므로:\n$$\\frac{20-r}{r+1} > 1$$\n$$20-r > r+1$$\n$$20 > 2r+1$$\n$$r < 9.5$$\n\n따라서 $r \\leq 9$일 때 $_20C_r$은 증가하고, $r \\geq 10$일 때 $_20C_r$은 감소한다.\n\n이는 다음을 의미한다:\n- $_20C_0 < _{20}C_1 < \\cdots < _{20}C_9 < _{20}C_{10}$\n- $_20C_{10} > _{20}C_{11} > \\cdots > _{20}C_{20}$\n\n따라서 $_20C_r$이 최대가 되는 점은 $r = 10$이다.\n\n이를 다른 방법으로도 확인된다. $n$이 짝수일 때, $_nC_r$은 $r = \\frac{n}{2}$에서 최대이므로, $n=20$일 때 $r = \\frac{20}{2} = 10$에서 최대이다.\n\n**[정답 확인]**\n$_{20}C_{10}$은 $_20C_9$와 $_{20}C_{11}$보다 모두 크므로, 20이 짝수이고 중간값인 10에서 최댓값을 갖다.\n\n**[오답 분석]**\n선택지가 없으나, 흔한 오답은:\n- $r = 9$ 또는 $r = 11$: 최대값 근처이지만 정확한 최댓값이 아님\n- $r = 20$: 최솟값에 해당 ($_20C_{20} = 1$)\n- $r = 5$: $_nC_r$의 성질을 반영하지 못함\n\n**[핵심 포인트]**\n1. $_nC_r$은 $r = \\frac{n}{2}$ (n이 짝수)에서 최대이다.\n2. 이항계수 비율의 크기 $\\frac{_{nC_{r+1}}}{_nC_r}$과 1을 비교하여 증감을 판단하는 방법이 매우 유용한다.",
