    "_type": "binomial",
    "type": "이항정리",
    "problem": "$\\sum_{k=0}^{10} k \\cdot _{10}C_k$의 값은?",
    "answerType": "choice",
    "choices": [
      "① $2560$",
      "② $5120$",
      "③ $10240$",
      "④ $15360$",
      "⑤ $20480$"
    ],
    "answer": 1,
    "explanation": "**[핵심 개념]**\n이 문제는 이항계수(binomial coefficient)와 그 성질을 이용하는 문제이다. 핵심은 $k \\cdot \\binom{n}{k}$를 다루는 방법이다.\n\n**이항정리:** $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$\n\n**중요 성질:** $k \\cdot \\binom{n}{k} = n \\cdot \\binom{n-1}{k-1}$\n이는 $k \\cdot \\frac{n!}{k!(n-k)!} = n \\cdot \\frac{(n-1)!}{(k-1)!(n-k)!}$에서 유도된다.\n\n**[풀이]**\n\n**1단계: 합 변형하기**\n$$\\sum_{k=0}^{10} k \\cdot \\binom{10}{k}$$\n\n$k=0$일 때 항은 0이므로:\n$$\\sum_{k=0}^{10} k \\cdot \\binom{10}{k} = \\sum_{k=1}^{10} k \\cdot \\binom{10}{k}$$\n\n**2단계: 성질 적용**\n$k \\cdot \\binom{10}{k} = 10 \\cdot \\binom{9}{k-1}$을 이용한다.\n\n$$\\sum_{k=1}^{10} k \\cdot \\binom{10}{k} = \\sum_{k=1}^{10} 10 \\cdot \\binom{9}{k-1} = 10 \\sum_{k=1}^{10} \\binom{9}{k-1}$$\n\n**3단계: 치환**\n$j = k-1$로 놓으면, $k=1$일 때 $j=0$, $k=10$일 때 $j=9$:\n\n$$10 \\sum_{j=0}^{9} \\binom{9}{j}$$\n\n**4단계: 이항정리 적용**\n이항정리에서 $x=1$을 대입하면:\n$$(1+1)^9 = \\sum_{j=0}^{9} \\binom{9}{j} = 2^9$$\n\n**5단계: 최종 계산**\n$$\\sum_{k=0}^{10} k \\cdot \\binom{10}{k} = 10 \\cdot 2^9 = 10 \\cdot 512 = 5120$$\n\n**[정답 확인]**\n$k \\cdot \\binom{10}{k} = 10 \\cdot \\binom{9}{k-1}$ 성질을 이용하여 모든 $k$에 대한 합을 $10 \\cdot 2^9 = 5120$으로 계산했으므로 ②번이 정답이다.\n\n**[오답 분석]**\n- ① $2560$: $10 \\cdot 2^8$을 계산한 경우 (지수를 잘못 처리)\n- ③ $10240$: $20 \\cdot 2^9$를 계산한 경우 (계수를 잘못 적용)\n- ④ $15360$: 다른 공식을 잘못 적용한 경우\n- ⑤ $20480$: $10 \\cdot 2^{10}$을 계산한 경우 (합 범위를 잘못 이해)\n\n**[핵심 포인트]**\n1. $k \\cdot \\binom{n}{k} = n \\cdot \\binom{n-1}{k-1}$은 조합 문제에서 매우 유용한 성질이다.\n2. 이항정리 $(1+1)^n = 2^n$을 이용하여 모든 이항계수의 합을 구한다.",
