    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항정리: $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$\n\n이 공식에서 $x$에 특정 값을 대입하면 이항계수들의 합을 구한다. 특히 $x=1$을 대입하면 $2^n$, $x=2$를 대입하면 $3^n$ 등을 얻을 수 있다.\n\n**[풀이]**\n\n주어진 식을 정리하면:\n$$_nC_0 + 2 \\cdot _nC_1 + 2^2 \\cdot _nC_2 + \\cdots + 2^n \\cdot _nC_n = 729$$\n\n이를 시그마 기호로 나타내면:\n$$\\sum_{k=0}^{n} 2^k \\cdot _nC_k = 729$$\n\n이항정리 $(1+x)^n = \\sum_{k=0}^{n} _nC_k \\cdot x^k$에서 $x=2$를 대입하면:\n$$(1+2)^n = \\sum_{k=0}^{n} _nC_k \\cdot 2^k$$\n\n따라서:\n$$3^n = 729$$\n\n$729$를 $3$의 거듭제곱으로 나타내면:\n$$729 = 3^6$$\n\n따라서:\n$$3^n = 3^6$$\n\n$$n = 6$$\n\n**[정답 확인]**\n\n$n=6$일 때, $3^6 = 729$이므로 주어진 조건을 만족한다.\n\n**[오답 분석]**\n\n- ① $n=4$: $3^4 = 81 \\neq 729$\n- ② $n=5$: $3^5 = 243 \\neq 729$\n- ④ $n=7$: $3^7 = 2187 \\neq 729$\n- ⑤ $n=8$: $3^8 = 6561 \\neq 729$\n\n**[핵심 포인트]**\n\n이항정리에 $x=2$를 대입하면 계수 앞에 $2^k$가 곱해진 형태의 합을 $(1+2)^n = 3^n$으로 간단히 구한다. 이항계수의 합 문제는 적절한 값을 대입하여 간단히 풀이하는 것이 핵심이다.",
