    "problem": "$\\sum_{k=0}^{10} k^2 \\cdot _{10}C_k$의 값은?",
    "answerType": "choice",
    "choices": [
      "① $15360$",
      "② $25600$",
      "③ $28160$",
      "④ $30720$",
      "⑤ $51200$"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항계수와 관련된 합을 구하는 문제이다. 핵심은 다음 항등식들이다:\n\n1) 이항정리: $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$\n\n2) 양변을 $x$로 미분하면: $n(1+x)^{n-1} = \\sum_{k=0}^{n} k\\binom{n}{k}x^{k-1}$\n\n3) 양변에 $x$를 곱하면: $nx(1+x)^{n-1} = \\sum_{k=0}^{n} k\\binom{n}{k}x^k$\n\n4) 다시 $x$로 미분하면: $k^2$을 포함한 항을 얻을 수 있다.\n\n**[풀이]**\n\n$\\sum_{k=0}^{10} k^2 \\cdot \\binom{10}{k}$를 구하기 위해 미분을 이용한다.\n\n$(1+x)^{10} = \\sum_{k=0}^{10} \\binom{10}{k}x^k$\n\n양변을 $x$로 미분하면:\n$$10(1+x)^9 = \\sum_{k=0}^{10} k\\binom{10}{k}x^{k-1}$$\n\n양변에 $x$를 곱하면:\n$$10x(1+x)^9 = \\sum_{k=0}^{10} k\\binom{10}{k}x^k$$\n\n다시 $x$로 미분하면:\n$$10(1+x)^9 + 10x \\cdot 9(1+x)^8 = \\sum_{k=0}^{10} k^2\\binom{10}{k}x^{k-1}$$\n\n$$10(1+x)^9 + 90x(1+x)^8 = \\sum_{k=0}^{10} k^2\\binom{10}{k}x^{k-1}$$\n\n양변에 $x$를 곱하면:\n$$10x(1+x)^9 + 90x^2(1+x)^8 = \\sum_{k=0}^{10} k^2\\binom{10}{k}x^k$$\n\n$x=1$을 대입하면:\n$$\\sum_{k=0}^{10} k^2\\binom{10}{k} = 10 \\cdot 1 \\cdot 2^9 + 90 \\cdot 1 \\cdot 2^8$$\n\n$$= 10 \\cdot 512 + 90 \\cdot 256$$\n\n$$= 5120 + 23040$$\n\n$$= 28160$$\n\n**[정답 확인]**\n\n$x=1$을 미분 결과에 대입하여 계산하면 $10 \\cdot 2^9 + 90 \\cdot 2^8 = 28160$이므로 ③번이 정답이다.\n\n**[오답 분석]**\n\n- ① $15360$: $10 \\cdot 2^9 = 5120$만 계산한 경우\n- ② $25600$: 계산 실수로 $2^8$의 계수를 잘못 적용한 경우\n- ④ $30720$: $90 \\cdot 2^8$을 잘못 계산한 경우\n- ⑤ $51200$: 두 항을 더한 후 추가로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n이항계수를 포함한 합에서 $k$ 또는 $k^2$이 나타나면 **미분을 이용**하고, 마지막에 **$x=1$을 대입**하여 값을 구한다. 특히 $\\sum k^2\\binom{n}{k} = n(n+1)2^{n-2}$임을 기억하면 검증할 수 있다.",
