    "answer": 1,
    "explanation": "**[핵심 개념]**\n확률의 정의: 어떤 사건이 일어날 확률은 (원하는 경우의 수)/(전체 경우의 수)로 구한다. 트럼프 카드는 총 52장이며, 4가지 무늬(♠ 스페이드, ♥ 하트, ♦ 다이아몬드, ♣ 클럽) 각각 13장씩 구성되어 있다.\n\n**[풀이]**\n**Step 1: 전체 경우의 수 파악**\n52장의 트럼프 카드 중 1장을 뽑으므로, 전체 경우의 수는 52이다.\n\n**Step 2: 원하는 경우의 수 파악**\n하트 카드는 4가지 무늬 중 하나이므로, 52장 중 $\\frac{52}{4} = 13$장이 하트이다.\n따라서 하트가 나오는 경우의 수는 13이다.\n\n**Step 3: 확률 계산**\n하트가 나올 확률은:\n$$P(\\text{하트}) = \\frac{\\text{하트 카드의 개수}}{\\text{전체 카드의 개수}} = \\frac{13}{52} = \\frac{1}{4}$$\n\n**[정답 확인]**\n트럼프 카드 52장은 4가지 무늬가 균등하게 분포하므로, 특정 무늬가 나올 확률은 $\\frac{1}{4}$이다.\n\n**[오답 분석]**\n- **① 1/13**: 52장 중 특정 카드 1장이 나올 확률로, 무늬 전체가 아닌 특정 카드 한 장의 확률이다.\n- **③ 1/2**: 비논리적인 선택으로, 근거 있는 확률 계산과 무관한다.\n- **④ 3/4**: 하트가 나올 확률의 여사건(하트가 아닐 확률)에 해당하므로 틀렸다.\n- **⑤ 4/13**: 계산 과정에서 분자와 분모를 잘못 대입한 오류이다.\n\n**[핵심 포인트]**\n트럼프 카드는 4가지 무늬가 각각 13장씩 균등하게 구성되므로, 특정 무늬가 나올 확률은 항상 $\\frac{1}{4}$이다. 이는 고전 확률의 가장 기본적인 문제 유형이다.",
