    "explanation": "**[핵심 개념]**\n합사건의 확률을 구하는 문제이다. \"또는\"으로 표현된 사건들의 합사건 확률은 포함-배제 원리를 사용한다.\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n또는 여사건을 이용하여 $P(A \\cup B) = 1 - P(\\overline{A \\cup B})$로도 구한다.\n\n**[풀이]**\n\n**방법 1: 포함-배제 원리 이용**\n\n주사위의 눈: {1, 2, 3, 4, 5, 6}\n\n사건 A: 짝수가 나오는 경우\n- $A = \\{2, 4, 6\\}$\n- $P(A) = \\frac{3}{6} = \\frac{1}{2}$\n\n사건 B: 5 이상의 눈이 나오는 경우\n- $B = \\{5, 6\\}$\n- $P(B) = \\frac{2}{6} = \\frac{1}{3}$\n\n사건 $A \\cap B$: 짝수이면서 5 이상인 경우\n- $A \\cap B = \\{6\\}$\n- $P(A \\cap B) = \\frac{1}{6}$\n\n따라서:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B) = \\frac{1}{2} + \\frac{1}{3} - \\frac{1}{6}$$\n\n$$= \\frac{3}{6} + \\frac{2}{6} - \\frac{1}{6} = \\frac{4}{6} = \\frac{2}{3}$$\n\n**방법 2: 여사건 이용**\n\n짝수 또는 5 이상의 눈이 나올 확률의 여사건은 \"홀수이면서 5 미만\"이다.\n- 여사건: $\\{1, 3\\}$\n- $P(\\text{여사건}) = \\frac{2}{6} = \\frac{1}{3}$\n\n따라서:\n$$P(A \\cup B) = 1 - \\frac{1}{3} = \\frac{2}{3}$$\n\n**[정답 확인]**\n짝수 또는 5 이상의 눈: {2, 4, 5, 6}으로 총 4가지이므로 $\\frac{4}{6} = \\frac{2}{3}$이 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{3}$: 5 이상의 확률만 구한 경우\n- ② $\\frac{1}{2}$: 짝수의 확률만 구한 경우\n- ④ $\\frac{5}{6}$: 포함-배제 원리에서 $P(A \\cap B)$를 더한 경우\n- ⑤ $1$: 모든 확률의 합으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\"또는\"의 합사건 확률에서는 반드시 **교집합을 중복으로 뺄셈**해야 한다. 여사건을 이용하면 교집합을 고려할 필요 없이 더 간단하게 풀 수 있다.",
    "difficulty": "lv1",
