    "explanation": "**[핵심 개념]**\n확률의 정의: 어떤 사건이 일어날 확률은 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$로 계산된다.\n\n주사위를 한 번 던질 때, 나올 수 있는 모든 경우는 {1, 2, 3, 4, 5, 6}으로 총 6가지이다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 파악**\n주사위를 한 번 던질 때 나올 수 있는 결과: 1, 2, 3, 4, 5, 6\n$$\\text{전체 경우의 수} = 6$$\n\n**2단계: 호의 눈이 나오는 경우의 수 파악**\n주사위에서 홀수인 눈: 1, 3, 5\n$$\\text{홀수가 나오는 경우의 수} = 3$$\n\n**3단계: 확률 계산**\n$$P(\\text{홀수}) = \\frac{\\text{홀수가 나오는 경우의 수}}{\\text{전체 경우의 수}} = \\frac{3}{6} = \\frac{1}{2}$$\n\n**[정답 확인]**\n주사위 6개의 눈 중 홀수는 1, 3, 5로 정확히 절반인 3개이므로, 홀수가 나올 확률은 $\\frac{1}{2}$이다.\n\n**[오답 분석]**\n- **① $\\frac{1}{6}$**: 주사위에서 특정한 한 개의 눈(예: 1)이 나올 확률이므로 틀림\n- **② $\\frac{1}{3}$**: 홀수 3개를 6개로 나누지 못하고 잘못 계산한 경우\n- **④ $\\frac{2}{3}$**: 짝수가 나올 경우(2, 4, 6)의 확률과 혼동한 경우 (오답)\n- **⑤ $\\frac{5}{6}$**: 1이 아닌 다른 수가 나올 확률로, 문제와 무관함\n\n**[핵심 포인트]**\n- 주사위의 홀수: 1, 3, 5 → 총 3개\n- 주사위 확률 문제는 전체 경우의 수 6을 항상 분모에 놓고, 조건을 만족하는 경우의 수를 분자에 놓으면 된다.",
