    "problem": "1부터 10까지 자연수가 적힌 카드 10장에서 1장을 뽑을 때, 소수가 적힌 카드를 뽑을 확률을 구하시오. (답을 기약분수로 나타낼 때, 분자와 분모의 합을 구하시오.)",
