    "answer": 7,
    "explanation": "**[핵심 개념]**\n확률의 정의: 어떤 사건이 일어날 확률 = (사건이 일어나는 경우의 수)/(전체 경우의 수)\n\n1부터 10까지의 자연수 중 소수를 정확히 파악하는 것이 중요하다.\n- 소수: 1보다 큰 자연수 중 1과 자기 자신만을 약수로 가지는 수\n- 1은 소수가 아닙니다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수**\n10장의 카드 중 1장을 뽑으므로 전체 경우의 수 = 10\n\n**Step 2: 1부터 10까지의 소수 찾기**\n각 수를 확인하면:\n- 1: 소수 아님\n- 2: 소수 ✓\n- 3: 소수 ✓\n- 4: 소수 아님 (4 = 2 × 2)\n- 5: 소수 ✓\n- 6: 소수 아님 (6 = 2 × 3)\n- 7: 소수 ✓\n- 8: 소수 아님 (8 = 2 × 4)\n- 9: 소수 아님 (9 = 3 × 3)\n- 10: 소수 아님 (10 = 2 × 5)\n\n소수: 2, 3, 5, 7 → **4개**\n\n**Step 3: 확률 계산**\n소수가 적힌 카드를 뽑을 확률 = $\\frac{4}{10}$\n\n**Step 4: 기약분수로 변환**\n$\\frac{4}{10} = \\frac{2}{5}$ (최대공약수 2로 나눔)\n\n**Step 5: 분자와 분모의 합**\n분자 = 2, 분모 = 5\n분자와 분모의 합 = $2 + 5 = 7$\n\n**[정답 확인]**\n1부터 10까지의 소수 4개(2, 3, 5, 7)를 정확히 파악하고, 확률을 기약분수 $\\frac{2}{5}$로 나타낸 후 분자와 분모를 더하면 7이 된다.\n\n**[오답 분석]**\n- 1을 소수로 착각하여 5개로 세는 경우: $\\frac{5}{10} = \\frac{1}{2}$ → 분자와 분모의 합 = 3\n- 기약분수로 약분하지 않고 $\\frac{4}{10}$ 그대로 계산하는 경우: 4 + 10 = 14\n- 4도 소수로 착각하는 경우 등의 계산 오류\n\n**[핵심 포인트]**\n1. **1은 소수가 아니다**는 정의를 반드시 기억할 것\n2. 확률을 구한 후 **기약분수로 변환**하는 추가 단계를 놓치지 말 것",
