    "explanation": "**[핵심 개념]**\n확률의 기본 정의: 어떤 사건이 일어날 확률은 (그 사건이 일어나는 경우의 수)/(전체 경우의 수)이다.\n기약분수: 분자와 분모의 최대공약수가 1인 분수로, 더 이상 약분할 수 없는 형태이다.\n\n**[풀이]**\n\n**Step 1: 전체 공의 개수 파악**\n- 빨간 공: 3개\n- 파란 공: 2개\n- 전체 공의 개수: $3 + 2 = 5$개\n\n**Step 2: 빨간 공이 나올 확률 계산**\n$$P(\\text{빨간 공}) = \\frac{\\text{빨간 공의 개수}}{\\text{전체 공의 개수}} = \\frac{3}{5}$$\n\n**Step 3: 기약분수 확인**\n$\\frac{3}{5}$에서 분자 3과 분모 5의 최대공약수는 1이므로, 이미 기약분수이다.\n$$\\frac{p}{q} = \\frac{3}{5}$$\n\n따라서 $p = 3$, $q = 5$\n\n**Step 4: $p + q$ 계산**\n$$p + q = 3 + 5 = 8$$\n\n**[정답 확인]**\n전체 5개의 공 중에서 빨간 공 3개를 뽑을 확률은 $\\frac{3}{5}$이고, 이를 기약분수로 나타내면 $p=3, q=5$이므로 $p+q=8$이 맞다.\n\n**[오답 분석]**\n객관식 문제가 아니므로 해당 없음\n\n**[핵심 포인트]**\n1. 확률 = (구하는 경우의 수)/(전체 경우의 수) 공식을 정확히 적용하기\n2. 구한 확률이 기약분수임을 확인하고, 분자와 분모를 정확히 파악하여 더하기",
