    "_type": "prob_basic",
    "type": "확률의 덧셈·곱셈",
    "problem": "동전 한 개를 3번 던질 때, 앞면이 정확히 1번 나올 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 11,
    "explanation": "**[핵심 개념]**\n이항확률(Binomial Probability)을 이용한 문제이다. 동전을 던질 때 앞면이 나올 확률은 $\\frac{1}{2}$이고, $n$번 시행 중 정확히 $k$번 성공할 확률은 다음 공식으로 구한다:\n$$P(X=k) = \\binom{n}{k}p^k(1-p)^{n-k}$$\n여기서 $\\binom{n}{k}$는 조합, $p$는 성공확률이다.\n\n**[풀이]**\n\n**Step 1: 문제 상황 정리**\n- 동전을 3번 던짐 ($n=3$)\n- 앞면이 정확히 1번 나올 확률을 구함 ($k=1$)\n- 동전의 앞면이 나올 확률 ($p=\\frac{1}{2}$), 뒷면이 나올 확률 ($1-p=\\frac{1}{2}$)\n\n**Step 2: 이항확률 공식 적용**\n$$P(X=1) = \\binom{3}{1}\\left(\\frac{1}{2}\\right)^1\\left(\\frac{1}{2}\\right)^{3-1}$$\n\n**Step 3: 각 항 계산**\n- 조합: $\\binom{3}{1} = \\frac{3!}{1!(3-1)!} = \\frac{3!}{1! \\cdot 2!} = 3$\n- 확률: $\\left(\\frac{1}{2}\\right)^1 \\cdot \\left(\\frac{1}{2}\\right)^2 = \\frac{1}{2} \\cdot \\frac{1}{4} = \\frac{1}{8}$\n\n**Step 4: 최종 확률 계산**\n$$P(X=1) = 3 \\times \\frac{1}{8} = \\frac{3}{8}$$\n\n**Step 5: 기약분수 확인 및 답 계산**\n$\\frac{3}{8}$에서 $\\gcd(3,8)=1$이므로 이미 기약분수이다.\n따라서 $p=3$, $q=8$\n\n$$p+q = 3+8 = 11$$\n\n**[정답 확인]**\n동전 3번 시행에서 앞면이 정확히 1번 나오는 경우는 (앞뒷뒷), (뒷앞뒷), (뒷뒷앞) 3가지이고, 각각의 확률은 $\\frac{1}{8}$이므로 총 확률은 $3 \\times \\frac{1}{8} = \\frac{3}{8}$이다.\n\n**[오답 분석]**\n선택지가 제시되지 않았으나, 흔한 오류는:\n- $\\binom{3}{1}$을 계산하지 않고 $\\frac{1}{8}$만 답하는 경우: $1+8=9$ (오답)\n- 앞면이 나올 확률만 곱하는 경우: $\\frac{1}{2}$, $p+q=3$ (오답)\n- 조합을 잘못 계산하는 경우 (오답)\n\n**[핵심 포인트]**\n동전을 여러 번 던질 때 특정 횟수만큼 성공할 확률은 **조합**을 반드시 포함해야 하며, 기약분수로 나타낸 후 분자와 분모를 더하는 것을 잊지 말아야 한다.",
