    "explanation": "**[핵심 개념]**\n확률의 기본 정의: 어떤 사건이 일어날 확률은 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$\n\n주사위를 한 번 던질 때 나올 수 있는 모든 경우는 1, 2, 3, 4, 5, 6의 6가지이다.\n\n\"또는\"이라는 표현은 합집합을 의미하므로, 조건을 만족하는 모든 경우를 찾아야 한다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 파악**\n주사위의 눈: {1, 2, 3, 4, 5, 6} → 전체 경우의 수 = 6\n\n**2단계: 조건을 만족하는 경우 찾기**\n구하는 사건: \"2 이하 또는 5 이상\"\n\n- 2 이하: 1, 2 (2가지)\n- 5 이상: 5, 6 (2가지)\n\n합집합이므로 겹치는 부분이 없다.\n\n따라서 조건을 만족하는 경우: {1, 2, 5, 6} → 4가지\n\n**3단계: 확률 계산**\n\n$$P = \\frac{\\text{조건을 만족하는 경우의 수}}{\\text{전체 경우의 수}} = \\frac{4}{6} = \\frac{2}{3}$$\n\n**[정답 확인]**\n주사위 6가지 중 4가지(1, 2, 5, 6)가 조건을 만족하므로 확률은 $\\frac{4}{6} = \\frac{2}{3}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{3}$: 조건을 만족하는 경우가 2가지라고 잘못 센 경우 (5 이상을 5만 센 경우)\n- ② $\\frac{1}{2}$: 3가지 경우만 센 경우 (한 조건만 일부만 고려한 경우)\n- ④ $\\frac{5}{6}$: 5가지를 센 경우 (3을 포함시킨 오류)\n- ⑤ $1$: 모든 경우가 조건을 만족한다고 본 경우 (3, 4가 조건을 만족하지 않음을 간과)\n\n**[핵심 포인트]**\n\"또는\"은 합집합이므로 모든 조건을 만족하는 경우를 합쳐야 한다. 이 문제에서는 2 이하인 경우 2가지, 5 이상인 경우 2가지로 총 4가지이다.",
