    "explanation": "**[핵심 개념]**\n확률의 정의: 어떤 사건이 일어날 확률 = (사건에 해당하는 경우의 수) / (전체 경우의 수)\n\n주사위를 한 번 던질 때 나올 수 있는 모든 경우는 1, 2, 3, 4, 5, 6으로 총 6가지이다.\n\n\"4 이하의 눈이 나오지 않는다\"는 것은 5 이상의 눈이 나온다는 의미이다.\n\n**[풀이]**\n**1단계: 전체 경우의 수 파악**\n주사위를 한 번 던질 때 가능한 모든 경우: 1, 2, 3, 4, 5, 6\n- 전체 경우의 수 = 6\n\n**2단계: 사건 해석**\n\"4 이하의 눈이 나오지 않을 확률\" = \"4보다 큰 눈이 나올 확률\"\n- 4 이하: 1, 2, 3, 4\n- 4 이하가 아닌 경우: 5, 6\n\n**3단계: 해당 경우의 수**\n4보다 큰 눈이 나오는 경우: 5, 6\n- 해당 경우의 수 = 2\n\n**4단계: 확률 계산**\n$$P(\\text{4 이하의 눈이 나오지 않음}) = \\frac{2}{6} = \\frac{1}{3}$$\n\n**[정답 확인]**\n주사위 6개 면 중에서 5와 6만 조건을 만족하므로 $\\frac{2}{6} = \\frac{1}{3}$이 정답이다.\n\n**[오답 분석]**\n- **①** $\\frac{1}{6}$: 한 가지 경우만 카운트한 경우 (5 또는 6 중 하나만 선택)\n- **③** $\\frac{1}{2}$: 계산 실수로 $\\frac{3}{6}$으로 계산한 경우\n- **④** $\\frac{2}{3}$: 4 이하인 경우를 구한 후 여사건을 잘못 계산 ($\\frac{4}{6}$의 여사건이 아님)\n- **⑤** $\\frac{5}{6}$: 분자 분모를 뒤집은 경우\n\n**[핵심 포인트]**\n\"~이 아닐 확률\" 문제에서는 조건을 정확히 해석해야 한다. \"4 이하가 아니다\" = \"4보다 크다\" = \"5 이상\"이라는 점을 정확히 파악하는 것이 중요하다.",
