    "answer": 1,
    "explanation": "**[핵심 개념]**\n확률의 기본 정의는 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$이다.\n주사위 두 개를 동시에 던질 때 전체 경우의 수는 $6 \\times 6 = 36$가지이고, 각 경우가 일어날 확률은 모두 같다(동등확률).\n\n**[풀이]**\n**Step 1: 전체 경우의 수 구하기**\n- 첫 번째 주사위: 6가지 (1, 2, 3, 4, 5, 6)\n- 두 번째 주사위: 6가지 (1, 2, 3, 4, 5, 6)\n- 전체 경우의 수 = $6 \\times 6 = 36$가지\n\n**Step 2: 두 눈의 합이 4가 되는 경우의 수 구하기**\n\n두 주사위를 $(a, b)$로 나타낼 때, $a + b = 4$를 만족하는 경우를 찾는다.\n- $(1, 3)$: $1 + 3 = 4$ ✓\n- $(2, 2)$: $2 + 2 = 4$ ✓\n- $(3, 1)$: $3 + 1 = 4$ ✓\n\n따라서 두 눈의 합이 4가 되는 경우는 **3가지**이다.\n\n**Step 3: 확률 계산**\n$$P(\\text{합이 4}) = \\frac{3}{36} = \\frac{1}{12}$$\n\n**[정답 확인]**\n두 눈의 합이 4가 되는 경우는 (1,3), (2,2), (3,1)의 3가지이고, 전체 36가지 중에서 이 경우가 차지하는 비율은 $\\frac{3}{36} = \\frac{1}{12}$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{18}$: $\\frac{2}{36}$에 해당하며, 유리한 경우를 2가지로 잘못 센 경우\n- ③ $\\frac{1}{9}$: $\\frac{4}{36}$에 해당하며, 유리한 경우를 4가지로 잘못 센 경우\n- ④ $\\frac{1}{6}$: $\\frac{6}{36}$에 해당하며, 주사위 하나를 던질 때의 확률과 혼동한 경우\n- ⑤ $\\frac{5}{36}$: 특정 계산 실수로 인한 오답\n\n**[핵심 포인트]**\n주사위 두 개를 던질 때는 반드시 **전체 경우의 수 36**을 기억하고, 구하는 사건에 해당하는 경우를 **빠짐없이 모두** 찾아야 한다. 합이 4인 경우 $(1,3)$, $(2,2)$, $(3,1)$의 3가지를 정확히 세는 것이 중요하다.",
