    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n두 사건의 합의 확률은 다음과 같이 구한다.\n\n- **일반적인 경우**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n- **배반 사건인 경우**: 두 사건이 동시에 일어날 수 없으므로 $P(A \\cap B) = 0$\n \n따라서 배반 사건 $A$, $B$에 대해: $P(A \\cup B) = P(A) + P(B)$\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- 사건 $A$와 $B$는 서로 배반 (동시에 일어날 수 없음)\n- $P(A) = 0.3$\n- $P(B) = 0.5$\n\n두 사건이 배반이므로 $P(A \\cap B) = 0$이다.\n\n합의 확률 공식에 주어진 값들을 대입하면:\n\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n$$P(A \\cup B) = 0.3 + 0.5 - 0 = 0.8$$\n\n**[정답 확인]**\n\n배반 사건의 합의 확률은 단순히 각 확률의 합이므로 $0.3 + 0.5 = 0.8$이 정답이다.\n\n**[오답 분석]**\n\n- ① 0.15: $0.3 \\times 0.5$로 두 확률을 곱한 오류 (독립 사건의 교집합 확률로 잘못 계산)\n- ② 0.5: $P(B)$의 값만 선택한 오류\n- ③ 0.65: 배반이 아닌 일반적인 경우로 계산 시 $0.3 + 0.5 - 0.15 = 0.65$가 되는데, 이는 문제 조건을 무시한 오류\n- ⑤ 1: 전체 확률과 혼동한 오류\n\n**[핵심 포인트]**\n\n배반 사건일 때는 교집합이 공집합이므로 $P(A \\cap B) = 0$이며, 합의 확률은 각 확률을 단순히 더하기만 하면 된다. \"배반\"이라는 조건이 주어지면 $P(A \\cap B) = 0$을 즉시 인지하는 것이 중요하다.",
