    "problem": "주사위 두 개를 동시에 던질 때, 적어도 하나가 6인 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 47,
    "explanation": "**[핵심 개념]**\n확률 문제에서 \"적어도 하나\"라는 표현이 나올 때는 여사건을 이용하는 것이 효율적이다. 여사건의 확률은 $P(A^c) = 1 - P(A)$로 계산한다. 또한 기약분수는 분자와 분모의 최대공약수가 1인 분수이다.\n\n**[풀이]**\n\n**1단계: 표본공간의 크기 결정**\n주사위 두 개를 동시에 던지는 경우의 수는 $6 \\times 6 = 36$가지이다.\n\n**2단계: 여사건 설정**\n\"적어도 하나가 6\"의 여사건은 \"둘 다 6이 아님\"이다.\n\n**3단계: 여사건의 확률 계산**\n둘 다 6이 아닌 경우:\n- 첫 번째 주사위: 1, 2, 3, 4, 5 중 하나 (5가지)\n- 두 번째 주사위: 1, 2, 3, 4, 5 중 하나 (5가지)\n- 경우의 수: $5 \\times 5 = 25$가지\n\n$$P(\\text{둘 다 6이 아님}) = \\frac{25}{36}$$\n\n**4단계: 구하는 확률 계산**\n$$P(\\text{적어도 하나가 6}) = 1 - P(\\text{둘 다 6이 아님}) = 1 - \\frac{25}{36} = \\frac{36-25}{36} = \\frac{11}{36}$$\n\n**5단계: 기약분수 확인**\n$\\gcd(11, 36) = 1$이므로 $\\frac{11}{36}$은 기약분수이다.\n- $p = 11$\n- $q = 36$\n\n**6단계: 답 계산**\n$$p + q = 11 + 36 = 47$$\n\n**[정답 확인]**\n기약분수 $\\frac{11}{36}$에서 $p=11$, $q=36$이므로 $p+q=47$이 맞다.\n\n**[오답 분석]**\n- 직접 세기로 실수: \"적어도 하나가 6\"인 경우를 직접 세면 (1,6), (2,6), ..., (6,6), (6,1), (6,2), ..., (6,5)로 11가지이므로, 실수로 중복 계산하면 틀릴 수 있다.\n- 기약분수 체크 미실시: $\\frac{11}{36}$을 기약분수가 아닌 다른 형태로 잘못 표현하면 답이 달라진다.\n\n**[핵심 포인트]**\n\"적어도 하나\"는 여사건이 간단하므로 **여사건을 이용**하면 효율적이고, 최종 답은 반드시 **기약분수임을 확인**해야 한다.",
