    "explanation": "**[핵심 개념]**\n비복원 추출에서 확률을 구할 때는 각 경우의 확률을 구한 후 더한다. 두 사건이 동시에 일어나는 경우의 확률은 곱의 법칙을 적용하고, 서로 배타적인 여러 경우의 합은 덧셈 법칙을 적용한다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 구하기**\n\n주머니에 총 공의 개수: $4 + 3 + 2 = 9$개\n\n비복원으로 2개를 뽑을 때 전체 경우의 수:\n$$P(전체) = \\frac{9}{1} \\times \\frac{8}{1} = 9 \\times 8 = 72$$\n\n또는 조합으로: $\\binom{9}{2} = \\frac{9 \\times 8}{2} = 36$ (순서 고려 시 $36 \\times 2 = 72$)\n\n**Step 2: 2개가 같은 색인 경우의 수**\n\n**(1) 빨간 공 2개를 뽑는 경우:**\n$$P(빨강) = \\frac{4}{9} \\times \\frac{3}{8} = \\frac{12}{72}$$\n\n**(2) 파란 공 2개를 뽑는 경우:**\n$$P(파랑) = \\frac{3}{9} \\times \\frac{2}{8} = \\frac{6}{72}$$\n\n**(3) 노란 공 2개를 뽑는 경우:**\n$$P(노랑) = \\frac{2}{9} \\times \\frac{1}{8} = \\frac{2}{72}$$\n\n**Step 3: 같은 색일 확률 계산**\n\n세 경우는 상호 배타적이므로 덧셈 법칙을 적용:\n\n$$P(같은 색) = P(빨강) + P(파랑) + P(노랑)$$\n\n$$= \\frac{12}{72} + \\frac{6}{72} + \\frac{2}{72} = \\frac{20}{72}$$\n\n**Step 4: 기약분수로 정리**\n\n$$\\frac{20}{72} = \\frac{5}{18}$$\n\n**[정답 확인]**\n빨간 공, 파란 공, 노란 공 각각에서 같은 색 2개를 뽑을 확률을 모두 더하면 $\\frac{5}{18}$이 되므로 정답이다.\n\n**[오답 분석]**\n- **② $\\frac{2}{9} = \\frac{4}{18}$**: 파란 공과 노란 공의 확률만 더한 경우\n- **③ $\\frac{1}{3} = \\frac{6}{18}$**: 계산 실수로 분자를 잘못 더한 경우\n- **④ $\\frac{11}{36}$**: 조합으로 계산했을 때 분모를 36으로 하면서 분자를 잘못 구한 경우\n- **⑤ $\\frac{7}{18}$**: 확률을 더할 때 계산 실수를 한 경우\n\n**[핵심 포인트]**\n비복원 추출에서 첫 번째 뽑을 때와 두 번째 뽑을 때의 확률이 달라진다. 같은 색 공을 뽑는 모든 경우(빨강, 파랑, 노랑)를 각각 구하고 더해야 한다.",
