    "answer": 0,
    "explanation": "**[핵심 개념]**\n비복원 추출에서의 확률은 조합을 이용하여 계산한다. 특정 조건을 만족하는 경우의 수를 전체 경우의 수로 나누면 된다.\n\n$$P(사건) = \\frac{조건을\\ 만족하는\\ 경우의\\ 수}{전체\\ 경우의\\ 수}$$\n\n조합 공식: $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n총 9개의 공(흰 공 5개 + 검은 공 4개)에서 3개를 선택하는 경우의 수:\n\n$$\\binom{9}{3} = \\frac{9!}{3!6!} = \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} = \\frac{504}{6} = 84$$\n\n**Step 2: 조건을 만족하는 경우의 수**\n흰 공 2개, 검은 공 1개를 선택하는 경우의 수:\n- 흰 공 5개에서 2개 선택: $\\binom{5}{2}$\n- 검은 공 4개에서 1개 선택: $\\binom{4}{1}$\n\n$$\\binom{5}{2} = \\frac{5!}{2!3!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n$$\\binom{4}{1} = 4$$\n\n따라서 조건을 만족하는 경우의 수:\n$$\\binom{5}{2} \\times \\binom{4}{1} = 10 \\times 4 = 40$$\n\n**Step 3: 확률 계산**\n$$P(\\text{흰 공 2개, 검은 공 1개}) = \\frac{40}{84} = \\frac{10}{21}$$\n\n**[정답 확인]**\n전체 84가지 중 조건을 만족하는 40가지를 기약분수로 나타내면 $\\frac{10}{21}$이므로 정답이다.\n\n**[오답 분석]**\n- ②번 $\\frac{5}{14}$: $\\frac{10}{21}$을 잘못 약분한 경우\n- ③번 $\\frac{3}{7}$: $\\frac{10}{21}$을 계산 실수로 약분한 경우\n- ④번 $\\frac{20}{63}$: 조합 계산 실수 또는 분모를 잘못 계산한 경우\n- ⑤번 $\\frac{4}{9}$: 복원추출로 잘못 계산하거나 조합을 무시하고 계산한 경우\n\n**[핵심 포인트]**\n비복원 추출에서의 확률은 **조합의 곱셈**을 이용한다. (흰 공 선택 경우의 수) × (검은 공 선택 경우의 수) / (전체 선택 경우의 수)로 계산하면 된다.",
