    "problem": "두 사건 $A$, $B$가 독립이고 $P(A^c) = \\frac{2}{3}$, $P(A \\cup B) = \\frac{5}{6}$일 때, $P(B)$의 값은?",
    "answerType": "choice",
    "choices": [
      "① 5/12",
      "② 1/2",
      "③ 3/4",
      "④ 13/20",
      "⑤ 11/12"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n1. **사건의 독립성**: 두 사건 $A$, $B$가 독립이면 $P(A \\cap B) = P(A) \\cdot P(B)$\n2. **합집합의 확률**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n3. **여사건의 확률**: $P(A^c) = 1 - P(A)$\n\n**[풀이]**\n\n**Step 1: $P(A)$ 구하기**\n\n$P(A^c) = \\frac{2}{3}$이므로\n$$P(A) = 1 - P(A^c) = 1 - \\frac{2}{3} = \\frac{1}{3}$$\n\n**Step 2: 독립성을 이용하여 조건식 세우기**\n\n$A$와 $B$가 독립이므로\n$$P(A \\cap B) = P(A) \\cdot P(B) = \\frac{1}{3} \\cdot P(B)$$\n\n**Step 3: 합집합 공식에 대입**\n\n$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$에서\n$$\\frac{5}{6} = \\frac{1}{3} + P(B) - \\frac{1}{3} \\cdot P(B)$$\n\n**Step 4: $P(B)$에 대해 정리**\n\n$$\\frac{5}{6} = \\frac{1}{3} + P(B) - \\frac{1}{3}P(B)$$\n\n$$\\frac{5}{6} = \\frac{1}{3} + P(B)\\left(1 - \\frac{1}{3}\\right)$$\n\n$$\\frac{5}{6} = \\frac{1}{3} + \\frac{2}{3}P(B)$$\n\n$$\\frac{5}{6} - \\frac{1}{3} = \\frac{2}{3}P(B)$$\n\n$$\\frac{5}{6} - \\frac{2}{6} = \\frac{2}{3}P(B)$$\n\n$$\\frac{3}{6} = \\frac{2}{3}P(B)$$\n\n$$\\frac{1}{2} = \\frac{2}{3}P(B)$$\n\n$$P(B) = \\frac{1}{2} \\cdot \\frac{3}{2} = \\frac{3}{4}$$\n\n**[정답 확인]**\n\n$P(B) = \\frac{3}{4}$일 때, $P(A \\cup B) = \\frac{1}{3} + \\frac{3}{4} - \\frac{1}{3} \\cdot \\frac{3}{4} = \\frac{4+9}{12} - \\frac{1}{4} = \\frac{13}{12} - \\frac{3}{12} = \\frac{10}{12} = \\frac{5}{6}$ ✓\n\n**[오답 분석]**\n\n- ① $\\frac{5}{12}$: 독립 조건을 반영하지 않고 단순 계산한 경우\n- ② $\\frac{1}{2}$: Step 4에서 $\\frac{1}{2} = \\frac{2}{3}P(B)$를 $P(B)$로 착각한 경우\n- ④ $\\frac{13}{20}$: 분모를 잘못 계산한 경우\n- ⑤ $\\frac{11}{12}$: 합집합 공식에서 교집합을 더하는 오류를 범한 경우\n\n**[핵심 포인트]**\n\n- **독립 사건**에서는 반드시 $P(A \\cap B) = P(A) \\cdot P(B)$ 관계식을 세워야 한다.\n- 합집합 확률 공식에 독립성 조건을 반영하여 한 개의 미지수 방정식으로 만드는 것이 핵심이다.",
