    "problem": "A 주머니에 빨간 공 2개, 흰 공 3개가 있고, B 주머니에 빨간 공 4개, 흰 공 1개가 있다. 동전을 던져 앞면이면 A에서, 뒷면이면 B에서 공 1개를 꺼낼 때, 빨간 공이 나올 확률을 $\\frac{p}{q}$라 하자. $p \\times q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 15,
    "explanation": "**[핵심 개념]**\n이 문제는 전확률 공식(Law of Total Probability)을 이용하는 문제이다. 전체 사건을 여러 개의 배반 사건으로 나누고, 각 경우의 확률을 구한 후 더하는 방법이다. 공식은 :\n$$P(사건) = P(사건|조건1) \\times P(조건1) + P(사건|조건2) \\times P(조건2)$$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- A 주머니: 빨간 공 2개, 흰 공 3개 (총 5개)\n- B 주머니: 빨간 공 4개, 흰 공 1개 (총 5개)\n- 동전: 앞면(확률 $\\frac{1}{2}$) → A에서 공 꺼냄, 뒷면(확률 $\\frac{1}{2}$) → B에서 공 꺼냄\n\n**2단계: 각 주머니에서 빨간 공이 나올 확률**\n- A에서 빨간 공이 나올 확률: $P(\\text{빨강}|A) = \\frac{2}{5}$\n- B에서 빨간 공이 나올 확률: $P(\\text{빨강}|B) = \\frac{4}{5}$\n\n**3단계: 전확률 공식 적용**\n빨간 공이 나올 확률은 다음과 같이 계산된다:\n\n$$P(\\text{빨강}) = P(\\text{빨강}|A) \\times P(A) + P(\\text{빨강}|B) \\times P(B)$$\n\n$$P(\\text{빨강}) = \\frac{2}{5} \\times \\frac{1}{2} + \\frac{4}{5} \\times \\frac{1}{2}$$\n\n**4단계: 계산**\n$$P(\\text{빨강}) = \\frac{2}{10} + \\frac{4}{10} = \\frac{6}{10} = \\frac{3}{5}$$\n\n**5단계: 기약분수 확인 및 답 구하기**\n$\\frac{3}{5}$는 이미 기약분수이다. (분자 3과 분모 5는 서로소)\n\n따라서 $p = 3$, $q = 5$\n\n$$p \\times q = 3 \\times 5 = 15$$\n\n**[정답 확인]**\n전확률 공식을 올바르게 적용하여 $\\frac{3}{5}$를 구했고, 이는 기약분수이므로 $p=3, q=5$에서 $p \\times q = 15$가 정답이다.\n\n**[오답 분석]**\n객관식 문제가 아니므로 해당 사항 없음. 만약 다른 답이 나왔다면:\n- $p \\times q = 10$: 약분하지 않은 $\\frac{6}{10}$을 사용한 경우\n- $p \\times q = 8$: 계산 실수로 확률을 잘못 더한 경우\n\n**[핵심 포인트]**\n1. **전확률 공식**: 조건부 확률의 합으로 전체 확률을 구할 때, 각 경우의 확률과 그 경우가 일어날 확률을 곱한 후 더한다.\n2. **기약분수 확인**: 최종 답이 기약분수인지 반드시 확인하고, 기약분수가 될 때까지 약분한다.",
