    "explanation": "**[핵심 개념]**\n확률의 정의는 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$이다. 이 문제에서는 조합을 이용하여 경우의 수를 구한다. 조합 공식은 $C(n,r) = \\frac{n!}{r!(n-r)!}$이다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수**\n\n10명의 학생 중에서 4명의 대표를 뽑는 경우의 수:\n$$C(10,4) = \\frac{10!}{4! \\cdot 6!} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = \\frac{5040}{24} = 210$$\n\n**Step 2: 사건이 일어나는 경우의 수**\n\n특정 2명이 모두 대표에 포함되는 경우를 계산한다.\n- 특정 2명은 반드시 포함되므로, 이들은 이미 선택됨\n- 나머지 8명 중에서 추가로 2명을 더 선택해야 함\n\n따라서 경우의 수는:\n$$C(8,2) = \\frac{8!}{2! \\cdot 6!} = \\frac{8 \\times 7}{2 \\times 1} = \\frac{56}{2} = 28$$\n\n**Step 3: 확률 계산**\n\n특정 2명이 모두 대표에 포함될 확률:\n$$P = \\frac{C(8,2)}{C(10,4)} = \\frac{28}{210}$$\n\n**Step 4: 기약분수로 정리**\n\n분자와 분모의 최대공약수를 구한다.\n$$28 = 2^2 \\times 7$$\n$$210 = 2 \\times 3 \\times 5 \\times 7$$\n$$\\gcd(28, 210) = 2 \\times 7 = 14$$\n\n따라서:\n$$\\frac{28}{210} = \\frac{28 \\div 14}{210 \\div 14} = \\frac{2}{15}$$\n\n**Step 5: 답 구하기**\n\n기약분수 $\\frac{p}{q} = \\frac{2}{15}$이므로:\n- $p = 2$\n- $q = 15$\n- $p + q = 2 + 15 = 17$\n\n**[정답 확인]**\n$\\frac{2}{15}$는 2와 15가 서로소이므로 기약분수이며, $2 + 15 = 17$이 정답이다.\n\n**[오답 분석]**\n- 전체 경우의 수를 잘못 계산한 경우: $C(10,4) = 210$을 다르게 계산하면 오류 발생\n- 사건의 경우의 수를 잘못 계산한 경우: 특정 2명이 반드시 포함된다는 조건을 간과하고 $C(10,2)$를 계산하면 오류\n- 약분을 완료하지 않은 경우: $\\frac{28}{210}$을 기약분수로 변환하지 않으면 $28 + 210 = 238$이 되어 오류\n\n**[핵심 포인트]**\n조건이 있는 확률 문제에서는 조건을 만족하는 경우를 먼저 명확히 파악해야 한다. 특정 2명이 반드시 포함되므로, 나머지 인원만 선택하는 방식으로 접근하는 것이 효율적이다. 항상 최종 확률을 기약분수로 정리하는 것을 잊지 말아야 한다.",
