    "_type": "prob_basic",
    "type": "확률의 덧셈·곱셈",
    "problem": "1부터 9까지의 자연수가 하나씩 적힌 9장의 카드에서 비복원으로 3장을 뽑을 때, 뽑은 세 수의 합이 짝수일 확률은?",
    "answerType": "choice",
    "choices": [
      "① 11/21",
      "② 13/21",
      "③ 2/3",
      "④ 5/7",
      "⑤ 17/21"
    ],
    "answer": 0,
    "explanation": "**[핵심 개념]**\n세 수의 합이 짝수가 되려면 다음 두 가지 경우 중 하나여야 한다:\n- (짝수) + (짝수) + (짝수) = 짝수\n- (홀수) + (홀수) + (짝수) = 짝수\n\n1부터 9까지의 자연수 중 홀수는 1, 3, 5, 7, 9 (5개), 짝수는 2, 4, 6, 8 (4개)이다.\n\n비복원 추출에서 전체 경우의 수는 $\\binom{9}{3}$이고, 유리한 경우의 수를 구한 후 확률을 계산한다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n9장의 카드 중 3장을 뽑는 경우의 수:\n$$\\binom{9}{3} = \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} = 84$$\n\n**Step 2: 세 수의 합이 짝수인 경우**\n\n**(1) 짝수 3개를 뽑는 경우:**\n- 짝수 4개(2, 4, 6, 8) 중 3개를 선택\n$$\\binom{4}{3} = 4$$\n\n**(2) 홀수 2개, 짝수 1개를 뽑는 경우:**\n- 홀수 5개(1, 3, 5, 7, 9) 중 2개 선택: $\\binom{5}{2}$\n- 짝수 4개(2, 4, 6, 8) 중 1개 선택: $\\binom{4}{1}$\n$$\\binom{5}{2} \\times \\binom{4}{1} = 10 \\times 4 = 40$$\n\n**Step 3: 유리한 경우의 수**\n$$4 + 40 = 44$$\n\n**Step 4: 확률 계산**\n$$P(\\text{세 수의 합이 짝수}) = \\frac{44}{84} = \\frac{11}{21}$$\n\n분자와 분모를 4로 나누면 $\\frac{44}{84} = \\frac{11}{21}$\n\n**[정답 확인]**\n짝수 3개의 경우 4가지, 홀수 2개와 짝수 1개의 경우 40가지로 총 44가지이고, $\\frac{44}{84} = \\frac{11}{21}$이므로 정답은 ①번이다.\n\n**[오답 분석]**\n- ② 13/21: 홀수 3개를 뽑는 경우($\\binom{5}{3} = 10$)를 잘못 포함하여 $\\frac{54}{84}$로 계산한 경우\n- ③ 2/3 = 14/21: 계산 과정에서 경우의 수를 잘못 센 경우\n- ④ 5/7 = 15/21: 전체 경우의 수나 유리한 경우의 수를 잘못 계산한 경우\n- ⑤ 17/21: 추가 오류로 인해 과다 계산한 경우\n\n**[핵심 포인트]**\n합이 짝수 ⟺ (짝수+짝수+짝수) 또는 (홀수+홀수+짝수). 홀수 3개를 뽑는 경우는 합이 홀수이므로 제외해야 한다.",
