    "_type": "prob_basic",
    "type": "확률의 덧셈·곱셈",
    "problem": "A, B, C 세 사람이 각각 독립적으로 과녁을 한 번씩 쏜다. A가 맞힐 확률은 $\\frac{1}{2}$, B가 맞힐 확률은 $\\frac{1}{3}$, C가 맞힐 확률은 $\\frac{1}{4}$일 때, 적어도 한 명이 맞힐 확률은?",
    "answerType": "choice",
    "choices": [
      "① 1/2",
      "② 7/12",
      "③ 2/3",
      "④ 3/4",
      "⑤ 11/12"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n\"적어도 한 명이 맞힐 확률\"은 여사건을 이용하면 쉽게 구한다. \n- 여사건의 확률: $P(A^c) = 1 - P(A)$\n- 독립사건의 곱: 여러 사건이 독립적으로 일어날 때, 모두 일어날 확률은 각 확률의 곱\n- \"적어도 하나\" = 1 - \"모두 실패\"\n\n**[풀이]**\n\n**Step 1: 각자 맞힐 확률과 맞추지 못할 확률 정리**\n\n주어진 조건:\n- A가 맞힐 확률: $P(A) = \\frac{1}{2}$ → A가 맞추지 못할 확률: $P(A^c) = 1 - \\frac{1}{2} = \\frac{1}{2}$\n- B가 맞힐 확률: $P(B) = \\frac{1}{3}$ → B가 맞추지 못할 확률: $P(B^c) = 1 - \\frac{1}{3} = \\frac{2}{3}$\n- C가 맞힐 확률: $P(C) = \\frac{1}{4}$ → C가 맞추지 못할 확률: $P(C^c) = 1 - \\frac{1}{4} = \\frac{3}{4}$\n\n**Step 2: 세 명 모두 맞추지 못할 확률 계산**\n\n세 사람이 독립적으로 행동하므로, 모두 맞추지 못할 확률은:\n\n$$P(\\text{모두 실패}) = P(A^c) \\times P(B^c) \\times P(C^c) = \\frac{1}{2} \\times \\frac{2}{3} \\times \\frac{3}{4}$$\n\n$$= \\frac{1 \\times 2 \\times 3}{2 \\times 3 \\times 4} = \\frac{6}{24} = \\frac{1}{4}$$\n\n**Step 3: 적어도 한 명이 맞힐 확률 계산 (여사건 이용)**\n\n$$P(\\text{적어도 한 명 맞춤}) = 1 - P(\\text{모두 실패})$$\n\n$$= 1 - \\frac{1}{4} = \\frac{3}{4}$$\n\n**[정답 확인]**\n세 명 모두 맞추지 못할 확률이 $\\frac{1}{4}$이므로, 적어도 한 명이 맞힐 확률은 $1 - \\frac{1}{4} = \\frac{3}{4}$이다.\n\n**[오답 분석]**\n\n① $\\frac{1}{2}$: A만 맞힐 확률로 계산한 오류\n② $\\frac{7}{12}$: 계산 과정에서 실수하거나 불완전한 경우의 수를 더한 경우\n③ $\\frac{2}{3}$: $1 - \\frac{1}{3}$으로 B의 여사건만 이용한 오류\n⑤ $\\frac{11}{12}$: 분모와 분자를 잘못 계산하거나 확률을 더한 오류\n\n**[핵심 포인트]**\n- **\"적어도\"라는 표현이 나오면 여사건을 먼저 생각하세요.** 직접 계산보다 여사건이 훨씬 간단한다.\n- 독립사건에서는 확률을 **곱한다**. (더하지 않음)",
