    "_type": "prob_basic",
    "type": "확률의 덧셈·곱셈",
    "problem": "주사위 2개를 동시에 던지는 시행을 2번 반복할 때, 두 눈의 합이 7인 경우가 적어도 1번 나올 확률은?",
    "answerType": "choice",
    "choices": [
      "① 1/6",
      "② 5/18",
      "③ 11/36",
      "④ 1/3",
      "⑤ 91/216"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n여사건을 이용한 확률 계산이 핵심이다. \"적어도 1번 나올 확률\" = 1 - \"한 번도 나오지 않을 확률\"\n\n주사위 2개를 던질 때 두 눈의 합이 7인 경우: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) → 6가지\n- 두 눈의 합이 7일 확률: $P(합=7) = \\frac{6}{36} = \\frac{1}{6}$\n- 두 눈의 합이 7이 아닐 확률: $P(합≠7) = 1 - \\frac{1}{6} = \\frac{5}{6}$\n\n**[풀이]**\n\n**Step 1: 한 번의 시행에서 두 눈의 합이 7일 확률 구하기**\n\n주사위 2개를 동시에 던지는 경우의 수: $6 \\times 6 = 36$가지\n\n두 눈의 합이 7인 경우:\n- (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) → 6가지\n\n따라서 $P(\\text{합=7}) = \\frac{6}{36} = \\frac{1}{6}$\n\n**Step 2: 한 번의 시행에서 두 눈의 합이 7이 아닐 확률**\n\n$P(\\text{합}≠7) = 1 - \\frac{1}{6} = \\frac{5}{6}$\n\n**Step 3: 2번 반복했을 때 적어도 1번 나올 확률**\n\n여사건을 이용하면:\n$$P(\\text{적어도 1번}) = 1 - P(\\text{한 번도 나오지 않음})$$\n\n2번 모두 7이 나오지 않을 확률:\n$$P(\\text{한 번도 나오지 않음}) = \\frac{5}{6} \\times \\frac{5}{6} = \\frac{25}{36}$$\n\n따라서 적어도 1번 나올 확률:\n$$P(\\text{적어도 1번}) = 1 - \\frac{25}{36} = \\frac{36-25}{36} = \\frac{11}{36}$$\n\n**[정답 확인]**\n\n여사건을 이용하여 계산한 결과 $\\frac{11}{36}$이 정답이며, 이는 선택지 ③과 일치한다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{6}$: 한 번의 시행에서 합이 7일 확률을 그대로 선택한 오류\n- ② $\\frac{5}{18}$: 계산 과정에서 분모를 잘못 설정한 오류\n- ④ $\\frac{1}{3}$: $\\frac{12}{36}$로 여사건 계산을 잘못한 오류\n- ⑤ $\\frac{91}{216}$: 주사위를 3번 던지는 경우로 잘못 계산한 오류\n\n**[핵심 포인트]**\n\n\"적어도\"라는 표현이 나올 때는 **여사건을 이용하는 것이 가장 효율적**이다. 직접 계산하면 여러 경우의 수를 더해야 하지만, 여사건을 이용하면 한 번에 계산할 수 있다.",
