    "answer": 2,
    "explanation": "**[핵심 개념]**\n조건부 확률의 정의: 사건 $A$가 일어났을 때 사건 $B$가 일어날 조건부 확률은 $$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n이 문제에서는 \"짝수가 나왔다\"는 조건 하에서 \"4 이상이 나올 확률\"을 구하는 것이므로, 조건부 확률을 적용해야 한다.\n\n**[풀이]**\n\n**1단계: 전체 표본공간 파악**\n주사위를 한 번 던질 때 가능한 결과: $\\{1, 2, 3, 4, 5, 6\\}$\n\n**2단계: 조건 사건 $A$ (짝수)와 구하는 사건 $B$ (4 이상) 정의**\n- 사건 $A$: 짝수의 눈이 나옴 → $\\{2, 4, 6\\}$\n- 사건 $B$: 4 이상의 눈이 나옴 → $\\{4, 5, 6\\}$\n\n**3단계: 두 조건을 모두 만족하는 경우 찾기**\n- $A \\cap B$ (짝수이면서 동시에 4 이상): $\\{4, 6\\}$\n\n**4단계: 각 확률 계산**\n- $P(A) = \\frac{3}{6} = \\frac{1}{2}$ (짝수가 나올 확률)\n- $P(A \\cap B) = \\frac{2}{6} = \\frac{1}{3}$ (짝수이면서 4 이상일 확률)\n\n**5단계: 조건부 확률 계산**\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{\\frac{1}{3}}{\\frac{1}{2}} = \\frac{1}{3} \\times \\frac{2}{1} = \\frac{2}{3}$$\n\n**[정답 확인]**\n짝수라는 조건 하에서 $\\{2, 4, 6\\}$ 중에서 4 이상인 경우는 $\\{4, 6\\}$이므로, $\\frac{2}{3}$이 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{6}$: 전체 표본공간에서 6이 나올 확률로 계산한 오류\n- ② $\\frac{1}{3}$: $P(A \\cap B)$의 값을 직접 선택한 오류 (조건부 확률 공식 미적용)\n- ④ $\\frac{1}{2}$: 사건 $A$의 확률과 혼동한 오류\n- ⑤ $\\frac{5}{6}$: 여사건을 잘못 계산한 오류\n\n**[핵심 포인트]**\n조건부 확률은 **조건이 되는 사건만을 새로운 표본공간으로 축소**한 후 계산해야 한다. \"짝수\"라는 조건 하에서는 $\\{2, 4, 6\\}$만 가능하므로, 이 중에서 4 이상인 비율을 구하면 된다.",
