    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률 문제이다. 조건부 확률은 특정 사건이 이미 일어났을 때, 다른 사건이 일어날 확률을 구하는 것이다.\n\n조건부 확률 공식: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n여기서 $P(A|B)$는 사건 B가 일어났을 때 사건 A가 일어날 확률이다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 전체 카드: 52장\n- 빨간 카드: 하트 13장 + 다이아 13장 = 26장\n- 주어진 조건: 뽑은 카드가 빨간 카드임\n\n**2단계: 구하려는 확률 정의**\n- 사건 A: 뽑은 카드가 하트\n- 사건 B: 뽑은 카드가 빨간 카드 (하트 또는 다이아)\n- 구하는 것: $P(A|B)$ = 빨간 카드라는 조건 하에서 하트일 확률\n\n**3단계: 조건부 확률 계산**\n\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)}$$\n\n- $P(A \\cap B)$ = 카드가 하트이면서 빨간 카드일 확률 = $\\frac{13}{52}$ (하트는 모두 빨간 카드)\n- $P(B)$ = 카드가 빨간 카드일 확률 = $\\frac{26}{52}$\n\n따라서:\n$$P(A|B) = \\frac{\\frac{13}{52}}{\\frac{26}{52}} = \\frac{13}{52} \\times \\frac{52}{26} = \\frac{13}{26} = \\frac{1}{2}$$\n\n**4단계: 직관적 이해**\n빨간 카드 26장 중에서 하트는 13장이다.\n따라서 빨간 카드라는 조건 하에서 하트일 확률은 $\\frac{13}{26} = \\frac{1}{2}$\n\n**[정답 확인]**\n빨간 카드 26장(하트 13장 + 다이아 13장) 중에서 하트 13장이 차지하는 비중이 정확히 절반이므로, 확률은 $\\frac{1}{2}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{4}$: 전체 52장 중 하트 13장의 확률로, 조건을 무시한 오류\n- ② $\\frac{1}{3}$: 특별한 근거 없는 임의의 선택\n- ④ $\\frac{2}{3}$: 역으로 계산한 오류\n- ⑤ $\\frac{13}{26}$: 정답과 같은 값이지만 기약분수가 아님 (③이 정답)\n\n**[핵심 포인트]**\n조건부 확률에서는 '조건이 주어졌을 때' 표본공간이 축소된다는 점이 중요하다. 빨간 카드라는 조건이 주어지면 표본공간은 전체 52장에서 빨간 카드 26장으로 축소되고, 이 중에서 하트의 비중을 구하면 된다.",
