    "explanation": "**[핵심 개념]**\n\n조건부 확률은 특정 사건이 일어났다는 조건 하에서 다른 사건이 일어날 확률이다. 조건부 확률의 정의는 $$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n여기서 $P(A) \\neq 0$이어야 하며, $P(B|A)$는 \"사건 A가 일어났을 때 사건 B가 일어날 확률\"을 의미한다.\n\n**[풀이]**\n\n주어진 정보를 정리하면:\n- $P(A) = \\frac{1}{2}$\n- $P(A \\cap B) = \\frac{1}{6}$\n- 구하려는 값: $P(B|A)$\n\n조건부 확률의 정의식에 주어진 값들을 직접 대입한다.\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n$$P(B|A) = \\frac{\\frac{1}{6}}{\\frac{1}{2}}$$\n\n분수를 나누는 계산을 수행한다.\n\n$$P(B|A) = \\frac{1}{6} \\times \\frac{2}{1}$$\n\n$$P(B|A) = \\frac{2}{6} = \\frac{1}{3}$$\n\n따라서 $P(B|A) = \\frac{1}{3}$이다.\n\n**[정답 확인]**\n\n조건부 확률 공식에 주어진 두 확률값을 대입하면 $\\frac{1}{6} \\div \\frac{1}{2} = \\frac{1}{3}$이 되므로 정답은 ③번이다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{6}$: $P(A \\cap B)$ 값과 혼동하여 선택한 경우\n- ② $\\frac{1}{4}$: 계산 실수로 $\\frac{1}{6} \\times \\frac{1}{2}$를 계산한 경우\n- ④ $\\frac{1}{2}$: $P(A)$ 값과 혼동하여 선택한 경우\n- ⑤ $\\frac{2}{3}$: 역순으로 $\\frac{P(A)}{P(A \\cap B)}$를 계산한 경우\n\n**[핵심 포인트]**\n\n조건부 확률 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$에서 분자는 교집합의 확률, 분모는 조건이 되는 사건의 확률이다. 이 공식을 정확히 이해하고 주어진 값을 올바르게 대입하는 것이 중요하다.",
