    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이 문제는 **조건부 확률**을 묻는 문제이다. \"3 이상의 눈이 나왔다고 한다\"는 것이 주어진 조건이므로, 이 조건 하에서 그 눈이 홀수일 확률을 구해야 한다.\n\n조건부 확률의 공식: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n여기서 A = \"홀수\", B = \"3 이상의 눈\"\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 확인**\n주사위의 눈: {1, 2, 3, 4, 5, 6}\n\n**2단계: 주어진 조건 \"3 이상의 눈\"에 해당하는 경우**\n3 이상의 눈: {3, 4, 5, 6} → 4가지\n\n따라서 $P(B) = \\frac{4}{6}$\n\n**3단계: \"3 이상의 눈\" AND \"홀수\"에 해당하는 경우**\n3 이상이면서 동시에 홀수인 눈: {3, 5} → 2가지\n\n따라서 $P(A \\cap B) = \\frac{2}{6}$\n\n**4단계: 조건부 확률 계산**\n\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{\\frac{2}{6}}{\\frac{4}{6}} = \\frac{2}{6} \\times \\frac{6}{4} = \\frac{2}{4} = \\frac{1}{2}$$\n\n**[정답 확인]**\n\n3 이상이라는 조건에서 가능한 4가지 경우(3, 4, 5, 6) 중 홀수는 2가지(3, 5)이므로, 구하는 확률은 $\\frac{2}{4} = \\frac{1}{2}$이다.\n\n**[오답 분석]**\n\n- **① 1/4**: 조건 없이 \"홀수이고 3 이상\"의 확률을 전체 6가지로 나눈 경우 ($\\frac{2}{6}$)의 오류\n- **② 1/3**: 잘못된 계산으로 다른 경우를 센 오류\n- **④ 2/3**: 3 이상인 짝수(4, 6)의 개수를 기준으로 잘못 계산한 오류\n- **⑤ 3/4**: 전체 6가지 중 홀수(1, 3, 5)를 센 후 잘못 계산한 오류\n\n**[핵심 포인트]**\n\n**조건부 확률은 주어진 조건을 \"새로운 표본공간\"으로 설정하는 것이 핵심**이다. \"3 이상\"이 조건이므로 {3, 4, 5, 6}만 고려하고, 이 중에서 홀수의 개수를 구하면 된다.",
