    "explanation": "**[핵심 개념]**\n조건부 확률 문제이다. \"1개를 꺼냈더니 불량품이었다\"는 것은 이미 일어난 사건(조건)이므로, 이를 바탕으로 남은 제품의 구성을 다시 파악해야 한다. 조건부 확률은 표본공간이 축소된다는 점이 핵심이다.\n\n**[풀이]**\n\n**Step 1: 초기 상태 파악**\n- 불량품: 2개\n- 정상품: 8개\n- 총 제품: 10개\n\n**Step 2: 첫 번째 시행 후 상태 파악**\n\"1개를 꺼냈더니 불량품이었다\"는 조건이 주어졌다.\n- 꺼낸 제품: 불량품 1개\n- 남은 불량품: $2 - 1 = 1$개\n- 남은 정상품: $8$개 (변함없음)\n- 남은 총 제품: $9$개\n\n**Step 3: 조건부 확률 계산**\n남은 9개의 제품 중에서 1개를 꺼낼 때, 그것이 불량품일 확률은:\n\n$$P(\\text{두 번째가 불량품} \\mid \\text{첫 번째가 불량품}) = \\frac{\\text{남은 불량품 개수}}{\\text{남은 총 제품 개수}} = \\frac{1}{9}$$\n\n**[정답 확인]**\n첫 번째에서 불량품이 제거되었으므로 남은 불량품은 1개, 총 9개 중에서 불량품을 뽑을 확률은 $\\frac{1}{9}$이다.\n\n**[오답 분석]**\n- **①번 1/10**: 초기 상태에서 불량품을 뽑을 확률이다. 첫 번째 시행의 결과를 반영하지 않은 오답\n- **③번 2/9**: 첫 번째 후에도 불량품이 2개 남아있다고 착각한 경우\n- **④번 1/5**: 특별한 논리적 근거 없는 임의의 선택\n- **⑤번 2/10**: ①번과 같이 초기 확률이며, 기약분수로 표현하지 않은 형태\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 주어진 조건(이미 일어난 사건)을 먼저 처리하여 표본공간을 축소해야 한다. \"1개를 꺼냈더니 불량품\"이라는 조건이 남은 제품의 구성을 변경하는 것을 정확히 파악하는 것이 핵심이다.",
