    "explanation": "**[핵심 개념]**\n\n조건부 확률의 정의와 교집합 확률의 관계를 이용하는 문제이다.\n\n- **조건부 확률의 정의**: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$ (단, $P(A) > 0$)\n- : $P(A \\cap B) = P(B|A) \\times P(A)$\n- 기약분수: 분자와 분모의 최대공약수가 1인 분수\n\n**[풀이]**\n\n**1단계: 주어진 조건 정리**\n\n- $P(A) = \\frac{2}{5}$\n- $P(B|A) = \\frac{3}{4}$\n- 구하는 것: $P(A \\cap B)$\n\n**2단계: 조건부 확률 공식 적용**\n\n조건부 확률의 정의에 의해:\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n양변에 $P(A)$를 곱하면:\n$$P(A \\cap B) = P(B|A) \\times P(A)$$\n\n**3단계: 값 대입하여 계산**\n\n$$P(A \\cap B) = \\frac{3}{4} \\times \\frac{2}{5}$$\n\n$$P(A \\cap B) = \\frac{3 \\times 2}{4 \\times 5} = \\frac{6}{20}$$\n\n**4단계: 기약분수로 나타내기**\n\n$\\gcd(6, 20) = 2$이므로:\n$$P(A \\cap B) = \\frac{6}{20} = \\frac{3}{10}$$\n\n따라서 $p = 3$, $q = 10$\n\n**5단계: 최종 답 계산**\n\n$$p + q = 3 + 10 = 13$$\n\n**[정답 확인]**\n\n조건부 확률의 정의를 올바르게 적용하여 $P(A \\cap B) = \\frac{3}{10}$을 얻었고, 이를 기약분수로 나타내 $p + q = 13$을 구했다.\n\n**[오답 분석]**\n\n- **$\\frac{6}{20}$으로 답하는 경우(11)**: 기약분수로 약분하지 않은 오류\n- **$P(B|A)$만 답하는 경우(7)**: 조건부 확률과 교집합 확률을 혼동\n- **$P(A) + P(B|A) = \\frac{2}{5} + \\frac{3}{4} = \\frac{23}{20}$으로 계산(23)**: 덧셈을 잘못 적용한 오류\n- **$\\frac{5}{13}$으로 계산하는 경우(18)**: 역순으로 계산한 오류\n\n**[핵심 포인트]**\n\n- **조건부 확률 공식**: $P(A \\cap B) = P(B|A) \\times P(A)$ 를 정확히 적용\n- **기약분수 확인**: 최종 답은 항상 기약분수 형태로 제시해야 함",
