    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "동전을 두 번 던졌을 때, 적어도 한 번은 앞면이 나왔다. 두 번 모두 앞면일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률을 다루고 있다. \"적어도 한 번은 앞면이 나왔다\"는 조건이 주어졌을 때, \"두 번 모두 앞면일 확률\"을 구하는 것이므로 조건부 확률 공식을 사용해야 한다.\n\n조건부 확률의 정의: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n여기서 사건 A: 두 번 모두 앞면, 사건 B: 적어도 한 번은 앞면\n\n**[풀이]**\n\n**1단계: 표본공간 설정**\n동전을 두 번 던질 때의 모든 경우의 수\n$$\\{(앞,앞), (앞,뒷), (뒷,앞), (뒷,뒷)\\}$$\n각 경우의 확률은 모두 $\\frac{1}{4}$이다.\n\n**2단계: 사건 B (적어도 한 번은 앞면) 정의**\n$$B = \\{(앞,앞), (앞,뒷), (뒷,앞)\\}$$\n$$P(B) = \\frac{3}{4}$$\n\n**3단계: 사건 A∩B (두 번 모두 앞면이면서 적어도 한 번은 앞면) 정의**\n두 번 모두 앞면이면 당연히 적어도 한 번은 앞면이므로:\n$$A \\cap B = A = \\{(앞,앞)\\}$$\n$$P(A \\cap B) = \\frac{1}{4}$$\n\n**4단계: 조건부 확률 계산**\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{\\frac{1}{4}}{\\frac{3}{4}} = \\frac{1}{3}$$\n\n**5단계: 기약분수 확인 및 답 계산**\n$\\frac{p}{q} = \\frac{1}{3}$에서 $\\gcd(1,3) = 1$이므로 기약분수이다.\n\n따라서 $p = 1$, $q = 3$\n\n$$p + q = 1 + 3 = 4$$\n\n**[정답 확인]**\n조건부 확률의 정의를 올바르게 적용하여 전체 3가지 경우 중 두 번 모두 앞면인 경우가 1가지이므로 $\\frac{1}{3}$이 맞다.\n\n**[오답 분석]**\n- $\\frac{1}{2}$를 선택한 경우: 조건을 무시하고 단순히 한 번 던졌을 때 앞면일 확률로 계산한 오류\n- $\\frac{1}{4}$를 선택한 경우: 조건부 확률을 적용하지 않고 기본 확률만 계산한 오류\n- $\\frac{3}{4}$를 선택한 경우: 분자와 분모를 바꾼 오류\n\n**[핵심 포인트]**\n조건이 주어진 확률 문제는 항상 조건부 확률을 사용해야 한다. \"~했을 때\" 또는 \"~라고 했을 때\"라는 표현이 있으면 조건부 확률 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$를 적용하세요.",
