    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "주머니에 1, 2, 3, 4, 5가 적힌 공이 하나씩 들어 있다. 1개를 꺼냈더니 홀수였다. 이 공에 적힌 수가 3 이상일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, $\\frac{p}{q}$는 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 5,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률 문제이다. \"1개를 꺼냈더니 홀수였다\"는 조건이 주어진 상황에서, 그 공에 적힌 수가 3 이상일 확률을 구해야 한다.\n\n조건부 확률의 정의: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n여기서 사건 $B$는 \"홀수가 나옴\", 사건 $A$는 \"3 이상의 수가 나옴\"이다.\n\n**[풀이]**\n\n**1단계: 표본공간 파악**\n주머니에 들어있는 공: 1, 2, 3, 4, 5 (총 5개)\n\n**2단계: 조건 \"홀수\"에 해당하는 경우 찾기**\n홀수는: 1, 3, 5 (총 3개)\n\n**3단계: 홀수이면서 3 이상인 경우 찾기**\n홀수이면서 3 이상인 수: 3, 5 (총 2개)\n\n**4단계: 조건부 확률 계산**\n홀수가 나왔다는 조건 하에서 그 수가 3 이상일 확률은:\n\n$$P(\\text{3 이상} \\mid \\text{홀수}) = \\frac{\\text{홀수이면서 3 이상인 경우의 수}}{\\text{홀수인 경우의 수}} = \\frac{2}{3}$$\n\n**5단계: 기약분수 확인 및 답 구하기**\n$\\frac{2}{3}$은 이미 기약분수이다. (분자 2와 분모 3의 최대공약수는 1)\n\n따라서 $p = 2, q = 3$\n\n$$p + q = 2 + 3 = 5$$\n\n**[정답 확인]**\n조건부 확률에서 표본공간을 \"홀수인 경우\"로 제한하고, 그 중에서 3 이상인 경우의 비율을 구하면 $\\frac{2}{3}$이 되어 $p + q = 5$가 맞다.\n\n**[오답 분석]**\n- 만약 조건을 무시하고 전체 5개 중에서 3 이상인 경우를 구하면 $\\frac{3}{5}$가 되어 $p+q=8$이 되는 오류가 발생한다.\n- 만약 조건을 잘못 이해하여 \"홀수이거나 3 이상\"인 경우를 구하면 1, 2, 3, 4, 5 중 1, 3, 4, 5가 해당하여 잘못된 답이 된다.\n\n**[핵심 포인트]**\n조건부 확률은 주어진 조건에 맞는 경우로만 표본공간을 재정의하고, 그 안에서의 확률을 구하는 것이다. \"홀수가 나왔다\"는 조건으로 표본공간을 {1, 3, 5}로 제한해야 한다.",
    "difficulty": "lv1",
