    "problem": "어느 학교 학생의 60%가 안경을 쓰고, 안경을 쓴 학생의 30%가 콘택트렌즈도 사용한다. 임의로 한 학생을 뽑았을 때, 안경과 콘택트렌즈를 모두 사용할 확률은?",
