    "answer": 0,
    "explanation": "**[핵심 개념]**\n조건부 확률의 곱셈 공식을 이용하는 문제이다. 사건 A가 일어났을 때 사건 B가 일어날 조건부 확률을 $P(B|A)$라 하면, 두 사건이 모두 일어날 확률은 $P(A \\cap B) = P(A) \\times P(B|A)$이다.\n\n**[풀이]**\n사건을 정의한다.\n- A: 학생이 안경을 쓰는 사건\n- B: 학생이 콘택트렌즈를 사용하는 사건\n\n주어진 정보를 정리하면:\n- $P(A) = 0.6 = \\frac{60}{100} = \\frac{3}{5}$ (안경을 쓴 학생의 비율)\n- $P(B|A) = 0.3 = \\frac{30}{100} = \\frac{3}{10}$ (안경을 쓴 학생 중에서 콘택트렌즈도 사용할 확률)\n\n우리가 구해야 하는 것은 안경과 콘택트렌즈를 **모두** 사용할 확률, 즉 $P(A \\cap B)$이다.\n\n곱셈 공식을 적용하면:\n$$P(A \\cap B) = P(A) \\times P(B|A)$$\n\n$$P(A \\cap B) = \\frac{3}{5} \\times \\frac{3}{10}$$\n\n$$P(A \\cap B) = \\frac{9}{50}$$\n\n**[정답 확인]**\n조건부 확률 곱셈 공식에 따라 $\\frac{3}{5} \\times \\frac{3}{10} = \\frac{9}{50}$으로 정답 ①이 맞다.\n\n**[오답 분석]**\n- ② $\\frac{3}{10}$: 조건부 확률 $P(B|A)$의 값만 선택한 오류\n- ③ $\\frac{1}{5}$: 계산 과정에서 실수한 경우\n- ④ $\\frac{18}{100} = \\frac{9}{50}$: 수치적으로는 맞지만 기약분수로 표현하지 않은 형태 (선택지에 $\\frac{9}{50}$이 있으므로 오답)\n- ⑤ $\\frac{2}{5}$: 확률들을 더한 오류\n\n**[핵심 포인트]**\n\"~의 ~%\"라는 표현이 나오면 조건부 확률이다. 조건이 되는 사건이 먼저 일어났다고 가정하고, 곱셈 공식 $P(A \\cap B) = P(A) \\times P(B|A)$를 적용하세요.",
