    "explanation": "**[핵심 개념]**\n조건부 확률은 특정 조건이 주어졌을 때 사건이 일어날 확률이다. 조건부 확률의 공식은 $P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{n(A \\cap B)}{n(B)}$ 이다. 이 문제에서는 \"두 눈의 합이 8 이상\"이 조건이고, \"두 눈이 모두 짝수\"가 구하려는 사건이다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수는 36가지이다.**\n주사위 두 개를 던지므로 $6 \\times 6 = 36$\n\n**Step 2: 조건 B - 두 눈의 합이 8 이상인 경우를 찾는다.**\n합이 8, 9, 10, 11, 12인 경우들을 나열한다:\n- 합 = 8: (2,6), (3,5), (4,4), (5,3), (6,2) → 5가지\n- 합 = 9: (3,6), (4,5), (5,4), (6,3) → 4가지\n- 합 = 10: (4,6), (5,5), (6,4) → 3가지\n- 합 = 11: (5,6), (6,5) → 2가지\n- 합 = 12: (6,6) → 1가지\n\n$n(B) = 5 + 4 + 3 + 2 + 1 = 15$\n\n**Step 3: 조건 A ∩ B - 두 눈의 합이 8 이상이면서 모두 짝수인 경우를 찾는다.**\n위의 경우 중에서 두 눈이 모두 짝수인 것만 선택한다:\n- 합 = 8: (2,6), (4,4), (6,2) → 3가지\n- 합 = 9: 모두 홀수와 짝수의 조합 → 0가지\n- 합 = 10: (4,6), (6,4) → 2가지\n- 합 = 11: 모두 홀수와 짝수의 조합 → 0가지\n- 합 = 12: (6,6) → 1가지\n\n$n(A \\cap B) = 3 + 2 + 1 = 6$\n\n**Step 4: 조건부 확률을 계산한다.**\n$$P(\\text{모두 짝수} | \\text{합} \\geq 8) = \\frac{n(A \\cap B)}{n(B)} = \\frac{6}{15} = \\frac{2}{5}$$\n\n**[정답 확인]**\n조건부 확률 공식을 올바르게 적용하여 유리한 경우 6가지를 전체 조건 만족 경우 15가지로 나누면 $\\frac{2}{5}$를 얻는다.\n\n**[오답 분석]**\n- ① $\\frac{1}{5}$: 3/15로 계산한 경우 (합이 8인 경우만 센 경우)\n- ② $\\frac{4}{15}$: 조건부 확률을 약분하지 않은 경우\n- ③ $\\frac{1}{3}$: 5/15로 계산한 경우 (분자를 잘못 센 경우)\n- ⑤ $\\frac{7}{15}$: 분자를 잘못 계산한 경우\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 먼저 **조건을 만족하는 전체 경우**를 찾고, 그 중에서 **추가로 원하는 사건을 만족하는 경우**를 찾아야 한다. 조건을 만족하는 경우로 나누는 것을 잊지 않아야 한다.",
