    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n조건부 확률은 특정 사건이 일어났을 때 다른 사건이 일어날 확률을 의미한다.\n\n조건부 확률의 정의: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$ (단, $P(A) > 0$)\n\n여사건의 합 공식: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n**[풀이]**\n\n**1단계: $P(A \\cap B)$ 구하기**\n\n여사건의 합 공식을 이용한다.\n\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n주어진 값을 대입하면:\n\n$$0.7 = 0.5 + 0.4 - P(A \\cap B)$$\n\n$$0.7 = 0.9 - P(A \\cap B)$$\n\n$$P(A \\cap B) = 0.9 - 0.7 = 0.2$$\n\n**2단계: 조건부 확률 $P(B|A)$ 계산하기**\n\n조건부 확률의 정의를 사용한다.\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)} = \\frac{0.2}{0.5} = 0.4$$\n\n**[정답 확인]**\n\n$P(A \\cap B) = 0.2$를 구한 후 조건부 확률 공식에 적용하면 $P(B|A) = \\frac{0.2}{0.5} = 0.4$이므로 정답은 ③이다.\n\n**[오답 분석]**\n\n- ① 0.2: $P(A \\cap B)$의 값과 혼동한 오답. 조건부 확률은 교집합 확률을 조건이 되는 사건의 확률로 나누어야 한다.\n\n- ② 0.3: 계산 과정에서 분자 또는 분모를 잘못 적용한 오답.\n\n- ④ 0.5: $P(A)$의 값과 혼동한 오답.\n\n- ⑤ 0.6: 조건부 확률 공식을 잘못 적용한 오답.\n\n**[핵심 포인트]**\n\n조건부 확률 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$를 계산할 때, 먼저 여사건의 합 공식으로 교집합 확률을 구한 후 조건이 되는 사건 $A$의 확률로 나누는 것이 핵심이다.",
