    "answer": 1,
    "explanation": "**[핵심 개념]**\n조건부 확률과 전체 확률의 법칙(Law of Total Probability)을 이용하는 문제이다.\n\n전체 확률의 법칙: 표본공간이 $A$와 $A^c$로 분할될 때,\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n조건부 확률의 정의: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $P(A) = \\frac{2}{3}$\n- $P(B|A) = \\frac{1}{4}$\n- $P(B|A^c) = \\frac{1}{2}$\n- 구하는 것: $P(B)$\n\n**2단계: $P(A^c)$ 구하기**\n$$P(A^c) = 1 - P(A) = 1 - \\frac{2}{3} = \\frac{1}{3}$$\n\n**3단계: 전체 확률의 법칙 적용**\n사건 $B$는 $A$에서 일어나거나 $A^c$에서 일어나므로:\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n**4단계: 값 대입**\n$$P(B) = \\frac{1}{4} \\times \\frac{2}{3} + \\frac{1}{2} \\times \\frac{1}{3}$$\n\n**5단계: 계산**\n$$P(B) = \\frac{2}{12} + \\frac{1}{6}$$\n\n$\\frac{1}{6} = \\frac{2}{12}$이므로:\n$$P(B) = \\frac{2}{12} + \\frac{2}{12} = \\frac{4}{12} = \\frac{1}{3}$$\n\n**[정답 확인]**\n전체 확률의 법칙을 올바르게 적용하여 $P(B) = \\frac{1}{3}$을 얻었으므로 정답은 **②번**이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{4}$: $P(B|A)$의 값만 선택한 오류\n- ③ $\\frac{5}{12}$: 계산 실수 (예: $\\frac{1}{4} \\times \\frac{2}{3} + \\frac{1}{2} \\times \\frac{2}{3}$로 잘못 계산)\n- ④ $\\frac{1}{2}$: $P(B|A^c)$의 값만 선택한 오류\n- ⑤ $\\frac{7}{12}$: 분모나 분자 계산 오류\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 항상 **전체 확률의 법칙**을 떠올려야 한다. 사건 $A$와 $A^c$는 표본공간을 완전히 분할하므로, $P(B) = P(B \\cap A) + P(B \\cap A^c)$로 계산할 수 있다.",
