    "answer": 3,
    "explanation": "**[핵심 개념]**\n조건부 확률의 정의를 이용하여 문제를 풀어야 한다.\n- 조건부 확률: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$\n- 이 공식을 변형하면 $P(A \\cap B) = P(A) \\times P(B|A)$로 표현할 수 있다.\n\n**[풀이]**\n\n주어진 정보를 정리하면:\n- $P(A \\cap B) = \\frac{1}{5}$\n- $P(B|A) = \\frac{2}{5}$\n- 구하는 것: $P(A) = \\frac{p}{q}$ (기약분수)에서 $p+q$의 값\n\n조건부 확률의 정의에서:\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n주어진 값들을 대입하면:\n$$\\frac{2}{5} = \\frac{\\frac{1}{5}}{P(A)}$$\n\n양변에 $P(A)$를 곱하면:\n$$\\frac{2}{5} \\times P(A) = \\frac{1}{5}$$\n\n양변에 $\\frac{5}{2}$를 곱하면:\n$$P(A) = \\frac{1}{5} \\times \\frac{5}{2} = \\frac{1}{2}$$\n\n따라서 $P(A) = \\frac{1}{2}$이므로, $p = 1$, $q = 2$이다.\n\n$$p + q = 1 + 2 = 3$$\n\n**[정답 확인]**\n$P(A) = \\frac{1}{2}$를 원래 조건에 대입하면 $P(B|A) = \\frac{1/5}{1/2} = \\frac{2}{5}$ ✓\n\n**[오답 분석]**\n이 문제는 객관식이 아닌 단답형 문제이므로, 계산 과정에서 흔한 실수는:\n- 조건부 확률 공식을 역으로 적용하는 경우: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$와 혼동\n- 분수를 약분하지 않아 기약분수 조건을 만족하지 못하는 경우\n\n**[핵심 포인트]**\n조건부 확률 공식 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$에서 구하는 확률이 분모에 있을 때는 이 식을 $P(A) = \\frac{P(A \\cap B)}{P(B|A)}$ 형태로 변형하여 활용하세요.",
