    "explanation": "**[핵심 개념]**\n\n조건부 확률과 합집합의 확률을 구하는 문제이다.\n\n- **조건부 확률**: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n- **합집합의 확률**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n이 두 공식을 이용하여 $P(A \\cap B)$를 먼저 구한 후, $P(A \\cup B)$를 계산한다.\n\n**[풀이]**\n\n**1단계: 조건부 확률 공식으로 $P(A \\cap B)$ 구하기**\n\n주어진 조건부 확률 공식:\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)}$$\n\n양변에 $P(B)$를 곱하면:\n$$P(A \\cap B) = P(A|B) \\times P(B)$$\n\n주어진 값들을 대입:\n$$P(A \\cap B) = 0.8 \\times 0.5 = 0.4$$\n\n**2단계: 합집합의 확률 공식으로 $P(A \\cup B)$ 구하기**\n\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n주어진 값들을 대입:\n$$P(A \\cup B) = 0.6 + 0.5 - 0.4 = 0.7$$\n\n**3단계: 10을 곱하기**\n\n$$P(A \\cup B) \\times 10 = 0.7 \\times 10 = 7$$\n\n**[정답 확인]**\n\n조건부 확률에서 $P(A \\cap B) = 0.4$를 구하고, 합집합 공식에 대입하여 $P(A \\cup B) = 0.7$을 얻었으므로, 10을 곱하면 7이다.\n\n**[오답 분석]**\n\n객관식이 아니므로 해당 없다.\n\n**[핵심 포인트]**\n\n- 조건부 확률 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$에서 교집합 확률 $P(A \\cap B)$를 구하는 것이 첫 번째 핵심이다.\n- 합집합 확률을 구할 때 $P(A \\cap B)$를 **반드시 빼야** 하는 것을 잊지 않아야 한다 (중복 제거).",
