    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "공장 A에서 60%, 공장 B에서 40%의 제품을 생산한다. A의 불량률은 3%, B의 불량률은 5%이다. 임의로 한 제품을 뽑았더니 불량이었을 때, 이 제품이 A에서 생산되었을 확률은?",
    "answerType": "choice",
