    "answer": 1,
    "explanation": "**[핵심 개념]**\n이 문제는 **베이즈 정리(조건부 확률)**를 이용한 문제이다.\n\n베이즈 정리: 사건 B가 일어났을 때 사건 A가 일어날 조건부 확률은\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{P(B|A) \\cdot P(A)}{P(B)}$$\n\n여기서 $P(B)$는 전체 확률의 법칙으로 구한다:\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $P(\\text{A 생산}) = 0.6$, $P(\\text{B 생산}) = 0.4$\n- $P(\\text{불량}|\\text{A}) = 0.03$, $P(\\text{불량}|\\text{B}) = 0.05$\n- 구하는 것: $P(\\text{A}|\\text{불량})$\n\n**2단계: 전체 불량 확률 구하기 (전체 확률의 법칙)**\n\n$$P(\\text{불량}) = P(\\text{불량}|\\text{A}) \\cdot P(\\text{A}) + P(\\text{불량}|\\text{B}) \\cdot P(\\text{B})$$\n\n$$= 0.03 \\times 0.6 + 0.05 \\times 0.4$$\n\n$$= 0.018 + 0.020 = 0.038$$\n\n**3단계: A에서 생산되면서 불량일 확률**\n\n$$P(\\text{A} \\cap \\text{불량}) = P(\\text{불량}|\\text{A}) \\cdot P(\\text{A})$$\n\n$$= 0.03 \\times 0.6 = 0.018$$\n\n**4단계: 베이즈 정리 적용**\n\n$$P(\\text{A}|\\text{불량}) = \\frac{P(\\text{A} \\cap \\text{불량})}{P(\\text{불량})}$$\n\n$$= \\frac{0.018}{0.038} = \\frac{18}{38} = \\frac{9}{19}$$\n\n**[정답 확인]**\n불량품이 나왔을 때, 그것이 A에서 생산되었을 확률은 $\\frac{9}{19}$이다. ✓\n\n**[오답 분석]**\n\n① $\\frac{7}{19}$: B에서 생산되었을 조건부 확률 $P(\\text{B}|\\text{불량}) = \\frac{0.020}{0.038} = \\frac{10}{19}$와 혼동\n\n③ $\\frac{10}{19}$: B에서 생산되었을 확률의 계산값 (정답과 역순)\n\n④ $\\frac{3}{7}$: 단순히 A의 불량률 3%와 다른 값을 잘못 결합한 경우\n\n⑤ $\\frac{12}{19}$: 계산 실수로 인한 오답\n\n**[핵심 포인트]**\n**\"불량이 나왔을 때 A인 확률\"은 조건부 확률 문제이므로, 베이즈 정리를 사용하여 (A이면서 불량)의 확률을 (전체 불량)의 확률로 나누어야 한다.** 단순 확률과 조건부 확률을 구분하는 것이 핵심이다.",
