    "choices": null,
    "answer": 11,
    "explanation": "**[핵심 개념]**\n조건부 확률의 정의: 사건 B가 일어났을 때 사건 A가 일어날 확률은 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$이다. \n이 문제에서는 \"$a + b \\ge 10$이 되었을 때\" 라는 조건이 주어졌으므로, 조건부 확률을 구해야 한다.\n\n**[풀이]**\n\n**1단계: 표본공간과 조건 정리**\n주사위를 두 번 던지므로 전체 경우의 수는 $6 \\times 6 = 36$가지이다.\n- 사건 B: $a + b \\ge 10$\n- 사건 A: $a \\ge 5$\n- 구하는 것: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n**2단계: $a + b \\ge 10$을 만족하는 경우 찾기**\n\n$a + b \\ge 10$인 경우를 체계적으로 나열한다.\n- $a + b = 10$: (4,6), (5,5), (6,4) → 3가지\n- $a + b = 11$: (5,6), (6,5) → 2가지\n- $a + b = 12$: (6,6) → 1가지\n\n따라서 $a + b \\ge 10$인 경우는 총 **6가지**이다.\n\n$P(B) = \\frac{6}{36} = \\frac{1}{6}$\n\n**3단계: $a + b \\ge 10$이면서 $a \\ge 5$인 경우 찾기**\n\n위의 6가지 경우 중 $a \\ge 5$를 만족하는 것:\n- $a + b = 10$: (5,5), (6,4) → 2가지\n- $a + b = 11$: (5,6), (6,5) → 2가지\n- $a + b = 12$: (6,6) → 1가지\n\n따라서 $a + b \\ge 10$이면서 $a \\ge 5$인 경우는 총 **5가지**이다.\n\n$P(A \\cap B) = \\frac{5}{36}$\n\n**4단계: 조건부 확률 계산**\n\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{\\frac{5}{36}}{\\frac{6}{36}} = \\frac{5}{36} \\times \\frac{36}{6} = \\frac{5}{6}$$\n\n**5단계: 기약분수 확인 및 답 구하기**\n\n$\\frac{5}{6}$은 $\\gcd(5, 6) = 1$이므로 기약분수이다.\n\n따라서 $p = 5$, $q = 6$\n\n$$p + q = 5 + 6 = 11$$\n\n**[정답 확인]**\n조건부 확률 $P(A|B) = \\frac{5}{6}$에서 분자 5와 분모 6이 서로소이므로 기약분수이고, $p + q = 11$이 정답이다.\n\n**[오답 분석]**\n- 전체 36가지 중에서 직접 계산하는 실수: $\\frac{5}{36}$으로 계산하면 안 된다.\n- $a + b \\ge 10$인 경우를 빠뜨리는 경우: 모든 경우(4,6), (5,5), (6,4), (5,6), (6,5), (6,6)를 빠짐없이 세어야 한다.\n- 조건부 확률을 무시하고 일반 확률로 계산: 반드시 조건 \"$a + b \\ge 10$\"이 주어졌을 때의 확률임을 기억해야 한다.\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 \"~일 때\"라는 조건이 주어지면, 전체 경우의 수를 그 조건을 만족하는 경우로 제한하고 계산해야 한다. 직접 세기를 통해 신뢰도 높은 답을 얻을 수 있다.",
