    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "3개의 동전을 동시에 던진다. 앞면이 적어도 2개 나왔다는 조건 하에서, 3개 모두 앞면일 확률은?",
    "answerType": "choice",
    "choices": [
      "① 1/8",
      "② 1/4",
      "③ 1/3",
      "④ 3/8",
      "⑤ 1/2"
    ],
    "answer": 1,
    "explanation": "**[핵심 개념]**\n조건부 확률은 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$로 정의된다. 이는 사건 B가 일어났다는 조건 하에서 사건 A가 일어날 확률을 구하는 공식이다. 이 문제에서는 '앞면이 적어도 2개 나왔다'는 조건이 주어졌으므로, 이를 표본공간으로 축소하여 계산해야 한다.\n\n**[풀이]**\n\n**Step 1: 전체 표본공간과 각 경우의 확률**\n\n3개의 동전을 던질 때 가능한 모든 경우는 $2^3 = 8$가지이며, 각각의 확률은 $\\frac{1}{8}$이다.\n\n표기: H(앞면), T(뒷면)\n\n**Step 2: \"앞면이 적어도 2개\" 사건 찾기**\n\n앞면이 적어도 2개인 경우:\n- 앞면이 정확히 2개: HHT, HTH, THH (3가지)\n- 앞면이 3개: HHH (1가지)\n\n따라서 조건 사건 B = {HHT, HTH, THH, HHH}이고,\n$$P(B) = \\frac{4}{8} = \\frac{1}{2}$$\n\n**Step 3: \"3개 모두 앞면\"이면서 \"앞면이 적어도 2개\" 사건**\n\nA = {HHH}이고, $A \\cap B$ = {HHH}이다.\n\n$$P(A \\cap B) = \\frac{1}{8}$$\n\n**Step 4: 조건부 확률 계산**\n\n$$P(A|B) = \\frac{P(A \\cap B)}{P(B)} = \\frac{\\frac{1}{8}}{\\frac{1}{2}} = \\frac{1}{8} \\times \\frac{2}{1} = \\frac{1}{4}$$\n\n**[정답 확인]**\n조건이 주어졌으므로 표본공간이 4가지로 축소되고, 이 중 HHH는 1가지이므로 $\\frac{1}{4}$가 정답이다.\n\n**[오답 분석]**\n- ① 1/8: 조건부 확률을 고려하지 않고 단순히 HHH의 확률로만 계산한 오류\n- ③ 1/3: 분자를 정확히 계산했으나 분모를 잘못 계산한 오류\n- ④ 3/8: P(B)를 $\\frac{1}{2}$로 올바르게 구했으나 계산 실수\n- ⑤ 1/2: 조건부 확률 개념을 완전히 무시한 오류\n\n**[핵심 포인트]**\n조건부 확률은 조건이 주어졌을 때 표본공간을 축소하는 것이 핵심이다. 분자는 두 조건을 모두 만족하는 경우의 수, 분모는 조건이 되는 사건의 확률로 설정해야 한다.",
