    "explanation": "**[핵심 개념]**\n조건부 확률의 정의: 사건 A가 일어났을 때 사건 B가 일어날 확률은 $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$이다.\n이 문제에서는 \"합이 짝수\"라는 조건 하에서 \"차가 2\"일 확률을 구하므로, 먼저 합이 짝수인 모든 경우를 찾고, 그 중에서 차가 2인 경우를 찾아야 한다.\n\n**[풀이]**\n\n**Step 1: 합이 짝수인 경우 찾기**\n\n두 수의 합이 짝수가 되려면:\n- (짝수) + (짝수) = 짝수, 또는\n- (홀수) + (홀수) = 짝수\n\n1부터 6까지 중:\n- 짝수: 2, 4, 6 (3개)\n- 홀수: 1, 3, 5 (3개)\n\n**짝수끼리의 조합:**\n$(2,4), (2,6), (4,6)$ → 3가지\n\n**홀수끼리의 조합:**\n$(1,3), (1,5), (3,5)$ → 3가지\n\n합이 짝수인 경우의 총 개수: $3 + 3 = 6$가지\n\n**Step 2: 합이 짝수이면서 차가 2인 경우 찾기**\n\n합이 짝수인 6가지 경우에서 두 수의 차가 2인 경우를 확인:\n\n- $(2,4)$: 차 = $|4-2| = 2$ ✓\n- $(2,6)$: 차 = $|6-2| = 4$ ✗\n- $(4,6)$: 차 = $|6-4| = 2$ ✓\n- $(1,3)$: 차 = $|3-1| = 2$ ✓\n- $(1,5)$: 차 = $|5-1| = 4$ ✗\n- $(3,5)$: 차 = $|5-3| = 2$ ✓\n\n차가 2인 경우: $(2,4), (4,6), (1,3), (3,5)$ → 4가지\n\n**Step 3: 조건부 확률 계산**\n\n$$P(\\text{차가 2} \\mid \\text{합이 짝수}) = \\frac{\\text{합이 짝수이고 차가 2인 경우}}{\\text{합이 짝수인 경우}} = \\frac{4}{6} = \\frac{2}{3}$$\n\n**[정답 확인]**\n합이 짝수인 6가지 경우 중에서 차가 2인 경우가 4가지이므로, 구하는 조건부 확률은 $\\frac{4}{6} = \\frac{2}{3}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{3}$: 조건을 무시하고 전체 경우에서 계산한 오류 (전체 15가지 중 5가지)\n- ② $\\frac{2}{5}$: 계산 과정에서 경우의 수를 잘못 센 경우\n- ④ $\\frac{4}{5}$: 분모와 분자를 잘못 이해한 오류\n- ⑤ $\\frac{7}{15}$: 조건부 확률의 개념 없이 단순히 계산한 오류\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 주어진 조건(여기서는 \"합이 짝수\")에 해당하는 표본공간을 먼저 구성한 후, 그 안에서 구하는 사건의 확률을 계산해야 한다. 전체 경우의 수가 아닌 조건을 만족하는 경우만 분모로 사용하는 것이 핵심이다.",
