    "problem": "상자 A에 흰 공 2개, 검은 공 1개, 상자 B에 흰 공 1개, 검은 공 2개가 있다. 주사위를 던져 3 이하면 A에서, 4 이상이면 B에서 공 1개를 꺼낸다. 꺼낸 공이 흰 공이었을 때, 상자 A에서 꺼냈을 확률은?",
    "answerType": "choice",
