    "answer": 3,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률을 묻는 문제이다. 특정 사건이 일어났을 때 다른 사건이 일어날 확률을 구하는 것으로, 베이즈 정리를 사용한다.\n\n조건부 확률: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n여기서 구하는 것은 \"흰 공이 나왔을 때 상자 A에서 나왔을 확률\"이므로:\n$$P(A에서 꺼냄|흰공) = \\frac{P(A에서 꺼냄 \\cap 흰공)}{P(흰공)}$$\n\n**[풀이]**\n\n**1단계: 각 상자에서 공을 꺼낼 확률**\n- 주사위 결과가 3 이하(1,2,3): 확률 = $\\frac{3}{6} = \\frac{1}{2}$ → 상자 A에서 꺼냄\n- 주사위 결과가 4 이상(4,5,6): 확률 = $\\frac{3}{6} = \\frac{1}{2}$ → 상자 B에서 꺼냄\n\n**2단계: 각 상자에서 흰 공을 꺼낼 조건부 확률**\n- 상자 A: 흰 공 2개, 검은 공 1개 → $P(흰공|A) = \\frac{2}{3}$\n- 상자 B: 흰 공 1개, 검은 공 2개 → $P(흰공|B) = \\frac{1}{3}$\n\n**3단계: 전체 확률의 법칙을 이용하여 흰 공이 나올 확률 계산**\n$$P(흰공) = P(A에서) \\times P(흰공|A) + P(B에서) \\times P(흰공|B)$$\n$$P(흰공) = \\frac{1}{2} \\times \\frac{2}{3} + \\frac{1}{2} \\times \\frac{1}{3}$$\n$$= \\frac{2}{6} + \\frac{1}{6} = \\frac{3}{6} = \\frac{1}{2}$$\n\n**4단계: A에서 꺼내면서 흰 공일 확률**\n$$P(A에서 \\cap 흰공) = P(A에서) \\times P(흰공|A) = \\frac{1}{2} \\times \\frac{2}{3} = \\frac{2}{6} = \\frac{1}{3}$$\n\n**5단계: 베이즈 정리 적용**\n$$P(A에서|흰공) = \\frac{P(A에서 \\cap 흰공)}{P(흰공)} = \\frac{\\frac{1}{3}}{\\frac{1}{2}} = \\frac{1}{3} \\times \\frac{2}{1} = \\frac{2}{3}$$\n\n**[정답 확인]**\n흰 공이 나왔을 때, 그것이 상자 A에서 나왔을 확률은 $\\frac{2}{3}$이므로 정답은 **④번**이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{3}$: $P(A에서 \\cap 흰공)$을 구한 값으로, 조건부 확률을 구하지 않은 실수\n- ② $\\frac{2}{5}$: 계산 과정에서 확률을 잘못 계산한 경우\n- ③ $\\frac{1}{2}$: 전체 확률 $P(흰공)$과 혼동한 경우\n- ⑤ $\\frac{4}{5}$: 역으로 계산하거나 다른 조건부 확률과 혼동한 경우\n\n**[핵심 포인트]**\n조건부 확률에서는 \"~일 때\"라는 조건이 주어진 사건을 분모에 놓고, 그 조건과 구하는 사건이 동시에 일어날 확률을 분자에 놓아야 한다. 전체 확률의 법칙으로 분모를 구하는 것이 이 유형의 핵심이다.",
