    "type": "조건부 확률",
    "problem": "주머니에 빨간 공 3개, 파란 공 2개가 있다. 비복원으로 2개를 꺼냈을 때 모두 빨간색이었다. 남은 3개에서 1개를 더 꺼낼 때 빨간 공일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률과 비복원 추출을 다루는 문제이다. 핵심은 \"비복원으로 2개를 꺼냈을 때 모두 빨간색이었다\"는 조건이 이미 주어진 상황에서, 남은 공들 중에서 빨간 공을 뽑을 확률을 구하는 것이다. 처음 상황에서 조건부 확률로 계산하는 방식도 있지만, 더 간단하게는 \"이미 빨간 공 2개가 제거되었다\"는 사실을 직접 활용할 수 있다.\n\n**[풀이]**\n\n**상황 정리:**\n- 초기: 빨간 공 3개, 파란 공 2개 (총 5개)\n- 사건: 비복원으로 2개를 꺼냈을 때 모두 빨간색\n- 구하는 것: 남은 3개에서 1개를 뽑을 때 빨간 공일 확률\n\n**Step 1: 주어진 조건 해석**\n\n문제에서 \"비복원으로 2개를 꺼냈을 때 모두 빨간색이었다\"는 것은 이미 일어난 사실이다. 따라서 우리는 이 조건 하에서 남은 공의 구성을 파악해야 한다.\n\n**Step 2: 남은 공의 구성 결정**\n\n빨간 공 2개가 제거되었으므로:\n- 남은 빨간 공: $3 - 2 = 1$개\n- 남은 파란 공: $2 - 0 = 2$개 (파란 공은 꺼내진 적 없음)\n- 남은 공의 총 개수: $1 + 2 = 3$개\n\n**Step 3: 확률 계산**\n\n남은 3개의 공 중에서 1개를 꺼낼 때, 그것이 빨간 공일 확률은:\n\n$$P(\\text{빨간 공}) = \\frac{\\text{남은 빨간 공의 개수}}{\\text{남은 공의 총 개수}} = \\frac{1}{3}$$\n\n**Step 4: 기약분수 확인 및 답 구하기**\n\n$\\frac{1}{3}$은 이미 기약분수이다.\n- $p = 1$\n- $q = 3$\n\n따라서:\n$$p + q = 1 + 3 = 4$$\n\n**[정답 확인]**\n조건부 확률을 엄밀히 계산해도 같은 결과를 얻는다. 이미 빨간 공 2개가 제거된 상태에서 남은 공은 빨간 공 1개, 파란 공 2개이므로 빨간 공을 뽑을 확률은 $\\frac{1}{3}$이고, $p+q=4$이다.\n\n**[오답 분석]**\n이 문제는 객관식이 아닌 단답형이므로 오답 선지 분석은 해당사항이 없다. 다만 흔한 실수를 언급하면:\n- 초기 상태에서의 확률을 구한 후 답하는 경우: 초기에 빨간 공을 뽑을 확률은 $\\frac{3}{5}$이지만, 문제는 조건이 주어진 후의 확률을 묻고 있다.\n- 조건부 확률 공식을 복잡하게 적용했을 때 계산 실수: 조건이 이미 충족된 상황이므로 단순히 남은 공의 구성만 파악하면 된다.\n\n**[핵심 포인트]**\n\"비복원으로 2개를 꺼냈을 때 모두 빨간색이었다\"는 이미 일어난 사건이다. 따라서 이 조건 하에서 남은 공의 구성(빨간 공 1개, 파란 공 2개)을 파악하고, 이 중에서 빨간 공을 뽑을 확률인 $\\frac{1}{3}$을 직접 구하면 된다.",
