    "explanation": "**[핵심 개념]**\n\n이 문제는 **베이즈 정리(Bayes' Theorem)**를 이용한 조건부 확률 문제이다.\n\n전체 사건이 여러 원인으로 나뉘어 있을 때, 결과가 주어졌을 때 특정 원인일 확률을 구하는 경우에 사용한다.\n\n$$P(C|불량) = \\frac{P(불량|C) \\times P(C)}{P(불량)}$$\n\n전확률의 법칙(Law of Total Probability)으로 분모를 구한다:\n$$P(불량) = P(불량|A) \\times P(A) + P(불량|B) \\times P(B) + P(불량|C) \\times P(C)$$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 기계 A: 생산량 50%, 불량률 2%\n- 기계 B: 생산량 30%, 불량률 3%\n- 기계 C: 생산량 20%, 불량률 5%\n\n**2단계: 전체 불량률 계산 (전확률의 법칙)**\n\n$$P(불량) = P(불량|A) \\times P(A) + P(불량|B) \\times P(B) + P(불량|C) \\times P(C)$$\n\n$$P(불량) = 0.02 \\times 0.5 + 0.03 \\times 0.3 + 0.05 \\times 0.2$$\n\n$$= 0.01 + 0.009 + 0.01 = 0.029$$\n\n분수로 표현하면:\n$$P(불량) = \\frac{1}{50} + \\frac{9}{1000} + \\frac{1}{100} = \\frac{20}{1000} + \\frac{9}{1000} + \\frac{10}{1000} = \\frac{39}{1000}$$\n\n**3단계: 베이즈 정리 적용**\n\n불량품이 C에서 생산되었을 확률:\n\n$$P(C|불량) = \\frac{P(불량|C) \\times P(C)}{P(불량)}$$\n\n$$= \\frac{0.05 \\times 0.2}{0.029} = \\frac{0.01}{0.029}$$\n\n분수로 계산하면:\n$$= \\frac{\\frac{1}{100}}{\\frac{39}{1000}} = \\frac{1}{100} \\times \\frac{1000}{39} = \\frac{1000}{3900} = \\frac{10}{39}$$\n\n**4단계: 기약분수 확인 및 답 계산**\n\n$\\frac{10}{39}$에서 $\\gcd(10, 39) = 1$ 이므로 이미 기약분수이다.\n\n따라서 $p = 10$, $q = 39$\n\n$$p \\times q = 10 \\times 39 = 390$$\n\n**아, 계산 재검토:**\n\n$$P(불량|C) \\times P(C) = 0.05 \\times 0.2 = 0.01 = \\frac{1}{100}$$\n\n$$P(불량) = 0.029 = \\frac{29}{1000}$$\n\n$$P(C|불량) = \\frac{\\frac{1}{100}}{\\frac{29}{1000}} = \\frac{1}{100} \\times \\frac{1000}{29} = \\frac{10}{29}$$\n\n$\\gcd(10, 29) = 1$ 이므로 기약분수\n\n따라서 $p = 10$, $q = 29$\n\n$$p \\times q = 10 \\times 29 = 290$$\n\n**[정답 확인]**\n\n베이즈 정리를 올바르게 적용하여 불량품이 C에서 생산되었을 확률을 $\\frac{10}{29}$로 구했고, $10 \\times 29 = 290$이 정답이다.\n\n**[오답 분석]**\n\n- 전확률의 법칙을 사용하지 않고 단순히 $\\frac{P(C) \\times P(불량|C)}{P(불량|C)}$로 계산하면 오류\n- 불량률만 고려하여 $\\frac{5}{2+3+5} = \\frac{5}{10}$으로 계산하면 오류 (생산량 비율 미반영)\n- 계산 과정에서 소수점 반올림 오류 발생 시 다른 값 도출\n\n**[핵심 포인트]**\n\n**조건부 확률 문제에서는 반드시 전확률의 법칙으로 분모를 구해야 한다.** 베이즈 정리는 $\\frac{\\text{원인의 확률} \\times \\text{조건부 확률}}{\\text{전체 확률}}$ 형태임을 명시하세요.",
