    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "항아리에 빨간 공 $r$개, 흰 공 $w$개가 들어 있다 (총 $r+w$개). 비복원으로 2개를 꺼낼 때, 첫 번째가 빨간 공이고 두 번째가 흰 공일 확률과 첫 번째가 흰 공이고 두 번째가 빨간 공일 확률이 같음을 이용하여 다음을 구하시오: $r=4$, $w=6$일 때, 두 번째로 꺼낸 공이 빨간색일 확률을 $\\frac{p}{q}$라 하자. $p+q$의 값을 구하시오. (단, 기약분수)",
    "answerType": "short",
    "choices": null,
    "answer": 7,
    "explanation": "**[핵심 개념]**\n\n비복원 추출에서 사건의 확률은 조건부 확률의 곱으로 표현된다. \n- 첫 번째 빨강, 두 번째 흰색: $P(R_1 \\cap W_2) = \\frac{r}{r+w} \\times \\frac{w}{r+w-1}$\n- 첫 번째 흰색, 두 번째 빨강: $P(W_1 \\cap R_2) = \\frac{w}{r+w} \\times \\frac{r}{r+w-1}$\n\n두 확률이 같다는 조건은 문제의 일관성을 확인하는 성질이며, 두 번째 공이 빨간색일 확률은 **전체 확률의 법칙**으로 구한다.\n\n**[풀이]**\n\n**1단계: 두 확률이 같다는 조건 확인**\n\n$$P(R_1 \\cap W_2) = P(W_1 \\cap R_2)$$\n\n$$\\frac{r}{r+w} \\times \\frac{w}{r+w-1} = \\frac{w}{r+w} \\times \\frac{r}{r+w-1}$$\n\n양변을 정리하면:\n$$\\frac{rw}{(r+w)(r+w-1)} = \\frac{rw}{(r+w)(r+w-1)}$$\n\n이는 항상 참이므로, 주어진 조건은 $r$과 $w$의 값과 무관하게 성립한다.\n\n**2단계: $r=4$, $w=6$일 때 두 번째 공이 빨간색일 확률 계산**\n\n두 번째 공이 빨간색일 확률은 첫 번째 공의 색깔에 따라 경우를 나누어 계산한다.\n\n$$P(R_2) = P(R_1) \\times P(R_2|R_1) + P(W_1) \\times P(R_2|W_1)$$\n\n각 항을 계산하면:\n- $P(R_1) = \\frac{4}{10}$, $P(R_2|R_1) = \\frac{3}{9}$\n- $P(W_1) = \\frac{6}{10}$, $P(R_2|W_1) = \\frac{4}{9}$\n\n따라서:\n$$P(R_2) = \\frac{4}{10} \\times \\frac{3}{9} + \\frac{6}{10} \\times \\frac{4}{9}$$\n\n$$= \\frac{12}{90} + \\frac{24}{90} = \\frac{36}{90}$$\n\n**3단계: 기약분수로 정리**\n\n$$\\frac{36}{90} = \\frac{2}{5}$$\n\n$\\gcd(36, 90) = 18$이므로, $\\frac{36}{90} = \\frac{2}{5}$\n\n따라서 $p = 2$, $q = 5$\n\n**4단계: 답 계산**\n\n$$p + q = 2 + 5 = 7$$\n\n**[정답 확인]**\n\n두 번째 공이 빨간색일 확률은 전체 확률의 법칙으로 구한 $\\frac{2}{5}$이고, 기약분수 조건에서 $p+q=7$이다.\n\n**[핵심 포인트]**\n\n1. 비복원 추출에서 특정 위치의 색깔 확률은 **전체 확률의 법칙**으로 구하며, 이는 처음 색깔과 무관하게 각 색깔의 초기 비율과 같다.\n2. 직관적으로 $P(R_2) = \\frac{r}{r+w} = \\frac{4}{10} = \\frac{2}{5}$로도 빠르게 구한다.",
