    "problem": "확률변수 $X$의 확률분포표가 다음과 같을 때, $E(X)$의 값은?\n\n| $X$ | 1 | 2 | 3 |\n|---|---|---|---|\n| $P(X=x)$ | $\\frac{1}{6}$ | $\\frac{1}{2}$ | $\\frac{1}{3}$ |",
