    "answer": 2,
    "explanation": "**[핵심 개념]**\n확률변수 $X$의 기댓값(평균)은 각 확률변수의 값에 그 확률을 곱한 후 모두 더하는 방식으로 구한다.\n\n기댓값의 정의: $E(X) = \\sum_{i} x_i \\cdot P(X=x_i)$\n\n먼저 주어진 확률의 합이 1인지 확인하는 것이 중요하다.\n\n**[풀이]**\n\n**1단계: 확률의 합 확인**\n\n$$P(X=1) + P(X=2) + P(X=3) = \\frac{1}{6} + \\frac{1}{2} + \\frac{1}{3}$$\n\n통분하면 (분모: 6)\n$$= \\frac{1}{6} + \\frac{3}{6} + \\frac{2}{6} = \\frac{6}{6} = 1 \\checkmark$$\n\n확률의 합이 1이므로 유효한 확률분포이다.\n\n**2단계: 기댓값 계산**\n\n기댓값의 정의에 따라:\n\n$$E(X) = 1 \\cdot P(X=1) + 2 \\cdot P(X=2) + 3 \\cdot P(X=3)$$\n\n$$= 1 \\cdot \\frac{1}{6} + 2 \\cdot \\frac{1}{2} + 3 \\cdot \\frac{1}{3}$$\n\n$$= \\frac{1}{6} + 1 + 1$$\n\n$$= \\frac{1}{6} + 2$$\n\n$$= \\frac{1}{6} + \\frac{12}{6}$$\n\n$$= \\frac{13}{6}$$\n\n**[정답 확인]**\n$E(X) = \\frac{13}{6}$이므로 정답은 **③번**이다.\n\n**[오답 분석]**\n- ① $1$: 첫 번째 값만 계산한 경우\n- ② $\\frac{11}{6}$: 계산 실수로 $3 \\cdot \\frac{1}{3} = 1$을 빼먹거나 확률을 잘못 곱한 경우\n- ④ $\\frac{7}{3}$: $\\frac{14}{6}$으로 계산하는 실수 (분자를 1 초과로 계산)\n- ⑤ $\\frac{5}{2}$: $\\frac{15}{6}$으로 계산하는 실수 (확률값을 더 크게 적용)\n\n**[핵심 포인트]**\n1. 기댓값은 $E(X) = \\sum x_i \\cdot P(X=x_i)$로 각 값과 확률의 곱을 모두 더한 것이다.\n2. 계산 전에 항상 확률의 합이 1인지 확인하여 유효한 분포인지 검증하세요.",
