    "problem": "확률변수 $X$의 확률분포표가 다음과 같을 때, 상수 $a$의 값은?\n\n| $X$ | 0 | 1 | 2 | 3 |\n|---|---|---|---|---|\n| $P(X=x)$ | $\\frac{1}{4}$ | $a$ | $\\frac{1}{4}$ | $\\frac{1}{8}$ |",
