    "explanation": "**[핵심 개념]**\n기댓값(평균)의 정의는 확률변수가 가질 수 있는 각 값에 그 확률을 곱한 후 모두 더한 값이다.\n- 이산확률변수 $X$의 기댓값: $E(X) = \\sum x_i \\cdot P(X = x_i)$\n- 모든 확률의 합은 1이며, 같은 확률을 가지는 경우 각 확률은 $\\frac{1}{n}$이다.\n\n**[풀이]**\n\n$X$가 $1, 2, 3, 4$의 값을 같은 확률로 가지므로, 각 값이 나올 확률은:\n$$P(X=1) = P(X=2) = P(X=3) = P(X=4) = \\frac{1}{4}$$\n\n기댓값 $E(X)$는 각 값과 확률의 곱을 모두 더한 것이다:\n\n$$E(X) = 1 \\cdot P(X=1) + 2 \\cdot P(X=2) + 3 \\cdot P(X=3) + 4 \\cdot P(X=4)$$\n\n$$E(X) = 1 \\cdot \\frac{1}{4} + 2 \\cdot \\frac{1}{4} + 3 \\cdot \\frac{1}{4} + 4 \\cdot \\frac{1}{4}$$\n\n$$E(X) = \\frac{1}{4}(1 + 2 + 3 + 4)$$\n\n$$E(X) = \\frac{1}{4} \\cdot 10 = \\frac{10}{4} = \\frac{5}{2}$$\n\n**[정답 확인]**\n기댓값은 모든 값의 합을 확률로 가중평균한 것으로, $1, 2, 3, 4$의 평균은 $\\frac{1+2+3+4}{4} = \\frac{5}{2}$이다.\n\n**[오답 분석]**\n- ① 2: 최솟값과 혼동한 경우\n- ③ 3: 중앙값(중위수)과 혼동한 경우\n- ④ 4: 최댓값과 혼동한 경우\n- ⑤ 7/2: 계산 과정에서 합을 잘못 구한 경우 (예: $1+2+3+4=11$로 계산)\n\n**[핵심 포인트]**\n- 같은 확률을 가지는 이산확률변수의 기댓값은 모든 값의 산술평균과 같다.\n- $E(X) = \\frac{\\text{모든 값의 합}}{\\text{값의 개수}}$",
