    "explanation": "**[핵심 개념]**\n확률변수 $X$의 누적분포함수(누적확률)는 $P(X \\leq a) = P(X=x_1) + P(X=x_2) + \\cdots + P(X=x_n)$ (단, $x_i \\leq a$)로 정의된다. 즉, $X$가 $a$ 이하인 모든 경우의 확률을 더하면 된다. 또한 모든 확률의 합은 1이므로 $\\sum P(X=x) = 1$이다.\n\n**[풀이]**\n$P(X \\leq 2)$는 확률변수 $X$가 2 이하인 모든 경우의 확률을 의미한다.\n\n$P(X \\leq 2)$에 포함되는 경우는 $X=1$ 또는 $X=2$이다.\n\n따라서:\n$$P(X \\leq 2) = P(X=1) + P(X=2)$$\n\n주어진 확률분포표에서:\n- $P(X=1) = 0.1$\n- $P(X=2) = 0.3$\n\n이를 대입하면:\n$$P(X \\leq 2) = 0.1 + 0.3 = 0.4$$\n\n**[정답 확인]**\n$X$가 1 또는 2의 값을 가질 확률의 합이 0.4이므로 정답은 ③번이다.\n\n**[오답 분석]**\n- ① 0.1: $P(X=1)$만 계산한 경우\n- ② 0.3: $P(X=2)$만 계산한 경우\n- ④ 0.5: $P(X \\leq 2) + P(X=3)$을 계산한 경우 (0.4 + 0.4 ≠ 0.5이므로 명백한 오류)\n- ⑤ 0.6: $P(X=2) + P(X=3)$을 계산한 경우 (0.3 + 0.4 = 0.7이므로 틀림)\n\n**[핵심 포인트]**\n- $P(X \\leq a)$는 \"$X$가 $a$ **이하**\"를 의미하므로 $X=a$인 경우를 반드시 포함해야 한다.\n- 누적확률은 조건을 만족하는 모든 개별 확률을 더하면 되며, 범위를 정확히 파악하는 것이 중요하다.",
