    "explanation": "**[핵심 개념]**\n\n확률변수의 기댓값(평균)은 각 값에 그 확률을 곱한 후 모두 더한 값이다. 기댓값의 선형성에 의해 $E(aX) = aE(X)$ (단, $a$는 상수)가 성립한다. 따라서 $E(2X) = 2E(X)$로 계산할 수 있다.\n\n**[풀이]**\n\n**1단계: $E(X)$ 계산**\n\n기댓값의 정의에 따라:\n$$E(X) = \\sum x \\cdot P(X=x)$$\n\n$$E(X) = 1 \\cdot \\frac{1}{3} + 2 \\cdot \\frac{1}{3} + 3 \\cdot \\frac{1}{3}$$\n\n$$E(X) = \\frac{1}{3} + \\frac{2}{3} + \\frac{3}{3}$$\n\n$$E(X) = \\frac{1+2+3}{3} = \\frac{6}{3} = 2$$\n\n**2단계: $E(2X)$ 계산**\n\n기댓값의 선형성을 이용하면:\n$$E(2X) = 2E(X) = 2 \\times 2 = 4$$\n\n**[정답 확인]**\n\n$E(X) = 2$이고, 기댓값의 선형성에 의해 $E(2X) = 2 \\times 2 = 4$이므로 정답은 ③이다.\n\n**[오답 분석]**\n\n- ① 2: $E(X)$의 값을 그대로 제시한 경우로, 2를 곱하지 않았다.\n- ② 3: 확률변수들의 단순 평균을 계산한 경우로, 기댓값과 혼동했다.\n- ④ 5: 계산 오류로 $E(X) = 2.5$라고 잘못 구한 후 2를 곱한 경우이다.\n- ⑤ 6: $1 + 2 + 3 = 6$을 직접 선택한 경우로, 확률을 고려하지 않았다.\n\n**[핵심 포인트]**\n\n기댓값의 선형성 $E(aX) = aE(X)$를 활용하면 $E(2X) = 2E(X)$로 간단히 계산할 수 있다. 기댓값 계산 시 각 값에 확률을 반드시 곱하는 것이 중요하다.",
