    "answer": 31,
    "explanation": "**[핵심 개념]**\n\n확률변수 $X$의 기댓값(평균) $E(X)$는 각 확률변수의 값에 그 확률을 곱한 후 모두 더한 값이다.\n\n$$E(X) = \\sum_{i} x_i \\cdot P(X=x_i)$$\n\n이는 확률분포의 무게중심을 나타내며, 확률의 합이 1인 확률분포에서만 정의된다.\n\n**[풀이]**\n\n**Step 1: 확률의 합 확인**\n\n먼저 주어진 확률분포가 올바른지 확인한다.\n\n$$P(X=0) + P(X=1) + P(X=2) + P(X=3) + P(X=4) = \\frac{1}{10} + \\frac{2}{10} + \\frac{3}{10} + \\frac{3}{10} + \\frac{1}{10} = \\frac{10}{10} = 1 \\checkmark$$\n\n**Step 2: 기댓값 계산**\n\n기댓값의 정의에 따라:\n\n$$E(X) = 0 \\cdot P(X=0) + 1 \\cdot P(X=1) + 2 \\cdot P(X=2) + 3 \\cdot P(X=3) + 4 \\cdot P(X=4)$$\n\n각 항을 계산하면:\n\n$$E(X) = 0 \\cdot \\frac{1}{10} + 1 \\cdot \\frac{2}{10} + 2 \\cdot \\frac{3}{10} + 3 \\cdot \\frac{3}{10} + 4 \\cdot \\frac{1}{10}$$\n\n$$= 0 + \\frac{2}{10} + \\frac{6}{10} + \\frac{9}{10} + \\frac{4}{10}$$\n\n$$= \\frac{2 + 6 + 9 + 4}{10} = \\frac{21}{10}$$\n\n**Step 3: 기약분수 확인 및 답 구하기**\n\n$\\gcd(21, 10) = 1$이므로 $\\frac{21}{10}$은 이미 기약분수이다.\n\n따라서 $p = 21$, $q = 10$이고:\n\n$$p + q = 21 + 10 = 31$$\n\n**[정답 확인]**\n\n기댓값 $E(X) = \\frac{21}{10}$에서 분자와 분모가 서로소이므로 기약분수이며, $p+q = 21+10 = 31$이다.\n\n**[오답 분석]**\n\n- $p+q = 25$ (오류): 계산 실수로 분자를 16으로 구한 경우\n- $p+q = 29$ (오류): $E(X) = \\frac{19}{10}$으로 구한 경우 (계산 오류)\n- $p+q = 30$ (오류): $\\frac{20}{10}$으로 기약분수가 아닌 형태를 사용한 경우\n\n**[핵심 포인트]**\n\n1. 기댓값은 $E(X) = \\sum x_i P(X=x_i)$로 계산하며, 각 값에 그 확률의 가중치를 곱하는 가중평균이다.\n2. 최종 답은 반드시 **기약분수**로 나타내야 하며, 분자와 분모의 최대공약수가 1인지 확인해야 한다.",
