    "explanation": "**[핵심 개념]**\n\n확률분포표에서 모든 확률의 합은 1이어야 한다는 성질과 기댓값의 정의를 이용하는 문제이다.\n\n- **확률의 성질**: $\\sum P(X=x) = 1$\n- **기댓값의 정의**: $E(X) = \\sum x \\cdot P(X=x)$\n- **기약분수**: 분자와 분모의 최대공약수가 1인 분수\n\n**[풀이]**\n\n**1단계: 확률 $a$ 구하기**\n\n확률분포표의 모든 확률의 합은 1이어야 하므로:\n\n$$P(X=-1) + P(X=0) + P(X=1) + P(X=2) = 1$$\n\n$$\\frac{1}{4} + a + \\frac{1}{4} + \\frac{1}{8} = 1$$\n\n$$a + \\frac{2}{8} + \\frac{2}{8} + \\frac{1}{8} = 1$$\n\n$$a + \\frac{5}{8} = 1$$\n\n$$a = \\frac{3}{8}$$\n\n**2단계: 기댓값 $E(X)$ 계산하기**\n\n기댓값의 정의에 따라:\n\n$$E(X) = (-1) \\cdot \\frac{1}{4} + 0 \\cdot \\frac{3}{8} + 1 \\cdot \\frac{1}{4} + 2 \\cdot \\frac{1}{8}$$\n\n$$= -\\frac{1}{4} + 0 + \\frac{1}{4} + \\frac{2}{8}$$\n\n$$= \\frac{2}{8}$$\n\n$$= \\frac{1}{4}$$\n\n**3단계: 기약분수로 표현하고 $p+q$ 구하기**\n\n$E(X) = \\frac{1}{4}$는 이미 기약분수이다.\n\n따라서 $p = 1$, $q = 4$\n\n$$p + q = 1 + 4 = 5$$\n\n**[정답 확인]**\n\n$a = \\frac{3}{8}$일 때 확률의 합이 1이 되고, 이를 이용해 계산한 기댓값 $\\frac{1}{4}$에서 $p+q = 5$가 나온다.\n\n**[오답 분석]**\n\n- $a$값을 구하지 않고 진행한 경우: 기댓값을 올바르게 계산할 수 없음\n- 기댓값 계산 시 $0 \\cdot \\frac{3}{8} = 0$을 누락한 경우: 계산 오류 발생\n- $\\frac{2}{8}$을 기약분수로 정리하지 않은 경우: $p+q = 2+8 = 10$ 등의 오답 도출\n\n**[핵심 포인트]**\n\n1. 확률분포표 문제는 항상 먼저 **확률의 합이 1**이라는 조건으로 미지의 확률을 구하기\n2. 기댓값 계산할 때 각 값에 대응하는 확률을 정확히 곱한 후, 최종 결과를 기약분수로 나타내기",
