    "explanation": "**[핵심 개념]**\n확률변수 $X$의 기댓값(평균)은 $E(X) = \\sum x_i \\cdot P(X=x_i)$로 정의된다. 기댓값의 선형성에 의해 $E(aX+b) = aE(X) + b$가 성립한다. 이를 이용하면 복잡한 확률변수의 기댓값을 간단히 구한다.\n\n**[풀이]**\n\n**Step 1: 확률의 합 확인**\n먼저 주어진 확률이 유효한지 확인한다.\n$$P(X=1) + P(X=2) + P(X=3) = \\frac{1}{2} + \\frac{1}{3} + \\frac{1}{6} = \\frac{3}{6} + \\frac{2}{6} + \\frac{1}{6} = 1 \\,\\checkmark$$\n\n**Step 2: $E(X)$ 계산**\n$$E(X) = 1 \\cdot P(X=1) + 2 \\cdot P(X=2) + 3 \\cdot P(X=3)$$\n$$E(X) = 1 \\cdot \\frac{1}{2} + 2 \\cdot \\frac{1}{3} + 3 \\cdot \\frac{1}{6}$$\n$$E(X) = \\frac{1}{2} + \\frac{2}{3} + \\frac{1}{2}$$\n$$E(X) = \\frac{3}{6} + \\frac{4}{6} + \\frac{3}{6} = \\frac{10}{6} = \\frac{5}{3}$$\n\n**Step 3: $E(3X+1)$ 계산 (기댓값의 선형성 이용)**\n기댓값의 선형성 성질에 의해:\n$$E(3X+1) = 3E(X) + 1$$\n$$E(3X+1) = 3 \\cdot \\frac{5}{3} + 1$$\n$$E(3X+1) = 5 + 1 = 6$$\n\n**[정답 확인]**\n기댓값의 선형성을 올바르게 적용하여 $E(X) = \\frac{5}{3}$을 구한 후, $E(3X+1) = 3 \\times \\frac{5}{3} + 1 = 6$을 얻었다.\n\n**[오답 분석]**\n- $E(3X+1) = 3E(X) + E(1)$로 잘못 계산하는 경우는 없다 ($E(1)=1$이므로 같은 결과).\n- $E(X)$를 $\\frac{1+2+3}{3} = 2$로 잘못 계산하면 $3 \\times 2 + 1 = 7$이 나온다 (확률을 무시한 오류).\n- 계산 과정에서 분수 덧셈을 실수하면 다른 값이 나올 수 있다.\n\n**[핵심 포인트]**\n1. 기댓값의 선형성: $E(aX+b) = aE(X) + b$를 항상 활용하면 계산이 간단해진다.\n2. 확률변수의 기댓값을 구할 때는 각 값에 해당 확률을 곱한 후 합산하는 정의를 정확히 적용해야 한다.",
