    "explanation": "**[핵심 개념]**\n확률변수 $X$의 분산 $V(X)$를 구하는 공식은 두 가지 방법이 있다.\n\n**방법 1:** $V(X) = E(X^2) - [E(X)]^2$\n\n**방법 2:** $V(X) = \\sum [x_i - E(X)]^2 \\cdot P(X=x_i)$\n\n분산은 확률변수가 기댓값으로부터 얼마나 흩어져 있는지를 나타내는 지표이다.\n\n**[풀이]**\n\n**Step 1: 기댓값 $E(X)$ 계산**\n\n$$E(X) = 1 \\cdot \\frac{1}{4} + 2 \\cdot \\frac{1}{2} + 3 \\cdot \\frac{1}{4}$$\n\n$$= \\frac{1}{4} + \\frac{2}{2} + \\frac{3}{4} = \\frac{1}{4} + \\frac{4}{4} + \\frac{3}{4} = \\frac{8}{4} = 2$$\n\n**Step 2: $E(X^2)$ 계산**\n\n$$E(X^2) = 1^2 \\cdot \\frac{1}{4} + 2^2 \\cdot \\frac{1}{2} + 3^2 \\cdot \\frac{1}{4}$$\n\n$$= 1 \\cdot \\frac{1}{4} + 4 \\cdot \\frac{1}{2} + 9 \\cdot \\frac{1}{4}$$\n\n$$= \\frac{1}{4} + \\frac{4}{2} + \\frac{9}{4} = \\frac{1}{4} + \\frac{8}{4} + \\frac{9}{4} = \\frac{18}{4} = \\frac{9}{2}$$\n\n**Step 3: 분산 $V(X)$ 계산**\n\n$$V(X) = E(X^2) - [E(X)]^2 = \\frac{9}{2} - 2^2$$\n\n$$= \\frac{9}{2} - 4 = \\frac{9}{2} - \\frac{8}{2} = \\frac{1}{2}$$\n\n**[정답 확인]**\n$V(X) = \\frac{1}{2}$이므로 정답은 **②번**이다.\n\n**[오답 분석]**\n\n- **①번 ($\\frac{1}{4}$):** $E(X) = 2$에서 $E(X^2)$를 구할 때 계산 실수로 $E(X^2) = \\frac{17}{4}$로 잘못 계산한 경우\n- **③번 ($\\frac{3}{4}$):** $V(X) = E(X) - [E(X)]^2 = 2 - 4 = -2$처럼 잘못된 공식을 사용한 경우\n- **④번 (1):** $E(X^2) = 5$로 계산 실수한 경우\n- **⑤번 ($\\frac{5}{4}$):** $E(X^2) = \\frac{13}{2}$로 잘못 계산하고 $V(X) = \\frac{13}{2} - 4 = \\frac{5}{2}$로 실수한 경우\n\n**[핵심 포인트]**\n분산을 구할 때는 $V(X) = E(X^2) - [E(X)]^2$ 공식을 정확히 적용해야 하며, $E(X^2)$는 $(E(X))^2$과 다르다는 점을 명확히 구분해야 한다. 특히 $[E(X)]^2$는 먼저 기댓값을 구한 후 제곱해야 한다.",
