    "explanation": "**[핵심 개념]**\n\n확률변수의 기댓값과 분산의 성질을 이용하는 문제이다. 일차함수로 변환된 확률변수의 기댓값과 분산은 다음 공식을 따릅니다.\n\n- **기댓값의 선형성**: $E(aX + b) = aE(X) + b$\n- **분산의 성질**: $V(aX + b) = a^2V(X)$ (상수 $b$는 분산에 영향을 주지 않음)\n\n**[풀이]**\n\n**1단계: $E(2X + 5)$ 구하기**\n\n기댓값의 선형성 공식을 적용한다.\n\n$$E(2X + 5) = 2E(X) + 5$$\n\n주어진 조건 $E(X) = 3$을 대입하면:\n\n$$E(2X + 5) = 2 \\times 3 + 5 = 6 + 5 = 11$$\n\n**2단계: $V(2X + 5)$ 구하기**\n\n분산의 성질 공식을 적용한다. 일차함수에서 기울기의 제곱에 원래 분산을 곱한다.\n\n$$V(2X + 5) = 2^2 \\times V(X)$$\n\n주어진 조건 $V(X) = 4$를 대입하면:\n\n$$V(2X + 5) = 4 \\times 4 = 16$$\n\n(상수항 5는 분산에 영향을 주지 않는다)\n\n**[정답 확인]**\n\n$E(2X + 5) = 11$, $V(2X + 5) = 16$이므로 정답은 **①번**이다.\n\n**[오답 분석]**\n\n- **②번 (11, 8)**: $V(2X + 5) = 2 \\times V(X) = 2 \\times 4 = 8$로 잘못 계산. 분산은 계수의 **제곱**을 곱해야 한다.\n- **③번 (11, 4)**: 분산에 변환을 적용하지 않고 원래 값 4를 그대로 사용한 오류이다.\n- **④번 (6, 16)**: $E(2X + 5) = 2 \\times 3 = 6$으로 상수항 5를 더하지 않은 오류이다.\n- **⑤번 (6, 8)**: 기댓값과 분산 모두를 잘못 계산한 경우이다.\n\n**[핵심 포인트]**\n\n- 기댓값은 **일차식 전체**에 대해 선형성이 성립한다 ($E(aX+b) = aE(X) + b$에서 상수항도 더함).\n- 분산은 **상수항에 무관**하며, 계수의 **제곱**을 곱한다 ($V(aX+b) = a^2V(X)$).",
