    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n1. **분산의 정의**: $V(X) = E(X^2) - [E(X)]^2$\n2. **분산의 성질**: \n - $V(aX + b) = a^2 \\cdot V(X)$ (단, $a, b$는 상수)\n - 상수 $b$는 분산에 영향을 주지 않음\n - 계수 $a$는 제곱되어 분산에 곱해짐\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $E(X) = 5$\n- $E(X^2) = 29$\n\n**2단계: $V(X)$ 계산**\n\n분산의 정의를 이용하여:\n\n$$V(X) = E(X^2) - [E(X)]^2 = 29 - 5^2 = 29 - 25 = 4$$\n\n**3단계: $V(3X - 2)$ 계산**\n\n분산의 성질을 이용한다. $Y = 3X - 2$일 때:\n\n$$V(3X - 2) = V(3X) + V(-2)$$\n\n상수는 분산에 영향을 주지 않으므로 $V(-2) = 0$\n\n따라서:\n$$V(3X - 2) = 3^2 \\cdot V(X) = 9 \\cdot 4 = 36$$\n\n**[정답 확인]**\n\n$V(3X - 2) = 9 \\times V(X) = 9 \\times 4 = 36$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n\n- **① 4**: $V(X)$의 값만 구한 경우 (변환 미적용)\n- **② 12**: $3 \\times V(X) = 12$로 계산한 경우 (계수를 제곱하지 않음)\n- **④ 27**: $3^3 \\times V(X)$로 잘못 계산한 경우\n- **⑤ 34**: $V(X) + E(X^2)$ 등으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n분산의 선형변환에서 **계수는 반드시 제곱**되어야 하며, **상수항은 분산 값에 영향을 주지 않는다**는 점을 기억해야 한다. 즉, $V(aX + b) = a^2V(X)$이다.",
