    "type": "이산확률분포",
    "problem": "확률변수 $X$에 대해 $E(X) = 2$, $V(X) = 3$일 때, $E\\left((X-1)^2\\right)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n확률변수의 분산과 기댓값 사이의 관계식을 이용하는 문제이다.\n\n- 분산의 정의: $V(X) = E(X^2) - \\{E(X)\\}^2$\n- 기댓값의 성질: $E((X-a)^2) = E(X^2 - 2aX + a^2) = E(X^2) - 2aE(X) + a^2$\n- 이 두 식을 결합하면 $E((X-a)^2)$을 구한다.\n\n**[풀이]**\n\n**Step 1: $E(X^2)$ 구하기**\n\n분산 공식을 이용한다:\n$$V(X) = E(X^2) - \\{E(X)\\}^2$$\n\n주어진 값을 대입하면:\n$$3 = E(X^2) - 2^2$$\n$$3 = E(X^2) - 4$$\n$$E(X^2) = 7$$\n\n**Step 2: $E((X-1)^2)$ 계산하기**\n\n$(X-1)^2$을 전개한다:\n$$(X-1)^2 = X^2 - 2X + 1$$\n\n기댓값의 선형성을 이용하면:\n$$E((X-1)^2) = E(X^2 - 2X + 1)$$\n$$= E(X^2) - 2E(X) + 1$$\n\n**Step 3: 값 대입하기**\n\nStep 1에서 구한 $E(X^2) = 7$과 주어진 $E(X) = 2$를 대입:\n$$E((X-1)^2) = 7 - 2(2) + 1$$\n$$= 7 - 4 + 1$$\n$$= 4$$\n\n**[정답 확인]**\n\n$E((X-1)^2) = E(X^2) - 2E(X) + 1 = 7 - 4 + 1 = 4$이므로, 정답은 **4**이다.\n\n**[오답 분석]**\n\n객관식 선지가 제시되지 않았으나, 자주 발생하는 오류:\n- **6**: $V(X) + E(X)$를 계산한 경우 ($3 + 2 = 5$, 아님)\n- **3**: $V(X)$만 답으로 한 경우\n- **5**: $E(X^2) - E(X) = 7 - 2$를 계산한 경우\n\n**[핵심 포인트]**\n\n1. **$E((X-a)^2) = V(X) + (E(X) - a)^2$** 로도 표현 가능한다. 이 문제의 경우 $E((X-1)^2) = 3 + (2-1)^2 = 3 + 1 = 4$\n\n2. 분산 공식 $V(X) = E(X^2) - \\{E(X)\\}^2$를 항상 먼저 이용하여 $E(X^2)$을 구하는 것이 핵심이다.",
