    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n, p)$는 동일한 확률 $p$를 가진 베르누이 시행을 $n$번 반복할 때 성공 횟수의 분포이다. 이항분포를 따르는 확률변수 $X$의 기댓값(평균)은 다음 공식으로 구한다:\n\n$$E(X) = np$$\n\n이 공식은 이항분포의 가장 기본적이고 중요한 성질이다.\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- 확률변수 $X$는 이항분포 $B(10, 0.3)$을 따름\n- 따라서 $n = 10$, $p = 0.3$\n\n이항분포의 기댓값 공식을 적용하면:\n\n$$E(X) = np = 10 \\times 0.3 = 3$$\n\n따라서 $E(X) = 3$이다.\n\n**[정답 확인]**\n\n이항분포 $B(n, p)$의 기댓값은 $E(X) = np$이므로, $E(X) = 10 \\times 0.3 = 3$이 정답이다.\n\n**[오답 분석]**\n\n- ① $1$: $np = 10 \\times 0.1$로 잘못 계산한 경우\n- ② $2$: 계산 실수로 $10 \\times 0.2 = 2$로 계산한 경우\n- ④ $4$: 확률을 잘못 읽어 $10 \\times 0.4 = 4$로 계산한 경우\n- ⑤ $7$: $n$값을 $10$이 아닌 다른 값으로 잘못 이해한 경우\n\n**[핵심 포인트]**\n\n이항분포 $B(n, p)$를 따르는 확률변수의 기댓값은 항상 $E(X) = np$이다. 이는 시행 횟수와 성공 확률의 곱이므로, 문제에서 $n$과 $p$ 값을 정확히 파악하고 공식을 바로 적용하면 된다.",
