    "answer": 2,
    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 분산(variance)은 다음 공식으로 구한다:\n$$V(X) = np(1-p)$$\n\n이는 이항분포의 기본 성질로, 평균 $E(X) = np$와 함께 가장 중요한 공식이다.\n\n**[풀이]**\n주어진 조건을 정리하면:\n- 확률변수 $X$는 이항분포 $B(20, \\frac{1}{4})$를 따름\n- 따라서 $n = 20$, $p = \\frac{1}{4}$\n\n분산 공식에 대입한다:\n$$V(X) = np(1-p)$$\n\n$$V(X) = 20 \\times \\frac{1}{4} \\times \\left(1 - \\frac{1}{4}\\right)$$\n\n$$V(X) = 20 \\times \\frac{1}{4} \\times \\frac{3}{4}$$\n\n$$V(X) = \\frac{20 \\times 3}{16}$$\n\n$$V(X) = \\frac{60}{16} = \\frac{15}{4}$$\n\n**[정답 확인]**\n이항분포의 분산 공식 $V(X) = np(1-p)$를 올바르게 적용하여 $\\frac{15}{4}$를 얻었으므로 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{5}{4}$: $20 \\times \\frac{1}{4} = 5$로 평균만 구한 경우\n- ② $\\frac{5}{2}$: $(1-p)$를 $\\frac{1}{2}$로 잘못 계산하거나 계산 실수\n- ④ $5$: 평균 $E(X) = np = 20 \\times \\frac{1}{4} = 5$와 혼동\n- ⑤ $\\frac{15}{2}$: 분모의 16을 8로 잘못 계산한 경우\n\n**[핵심 포인트]**\n이항분포 $B(n, p)$의 분산은 반드시 $V(X) = np(1-p)$이며, 평균 $np$와 혼동하지 않아야 한다. 특히 $(1-p)$ 항을 빼먹지 않는 것이 중요하다.",
