    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 성질:\n- 기댓값: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n분산 공식을 이용하여 모수 $n$을 구하는 문제이다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim B(n, \\frac{1}{3})$\n- $V(X) = 4$\n- $p = \\frac{1}{3}$이므로 $1-p = \\frac{2}{3}$\n\n**2단계: 분산 공식 적용**\n\n이항분포의 분산 공식을 적용하면:\n$$V(X) = np(1-p)$$\n\n주어진 값들을 대입한다:\n$$4 = n \\cdot \\frac{1}{3} \\cdot \\frac{2}{3}$$\n\n**3단계: $n$ 구하기**\n\n$$4 = n \\cdot \\frac{2}{9}$$\n\n양변에 $\\frac{9}{2}$를 곱한다:\n$$n = 4 \\times \\frac{9}{2} = \\frac{36}{2} = 18$$\n\n**4단계: 검증**\n\n$n = 18$일 때:\n$$V(X) = 18 \\times \\frac{1}{3} \\times \\frac{2}{3} = 18 \\times \\frac{2}{9} = \\frac{36}{9} = 4$$ ✓\n\n**[정답 확인]**\n$V(X) = np(1-p) = 18 \\times \\frac{1}{3} \\times \\frac{2}{3} = 4$이므로 $n=18$이 정답이다.\n\n**[오답 분석]**\n- ① $n=12$: $V(X) = 12 \\times \\frac{2}{9} = \\frac{24}{9} = \\frac{8}{3} \\neq 4$ (과소)\n- ② $n=15$: $V(X) = 15 \\times \\frac{2}{9} = \\frac{30}{9} = \\frac{10}{3} \\neq 4$ (과소)\n- ④ $n=24$: $V(X) = 24 \\times \\frac{2}{9} = \\frac{48}{9} = \\frac{16}{3} \\neq 4$ (과다)\n- ⑤ $n=36$: $V(X) = 36 \\times \\frac{2}{9} = 8 \\neq 4$ (과다)\n\n**[핵심 포인트]**\n이항분포 $B(n, p)$의 분산은 $V(X) = np(1-p)$이고, 이 공식을 이용하여 역으로 모수 $n$을 구한다. 계산 시 $1-p$의 값을 정확히 구하는 것이 중요하다.",
