    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n, p)$를 따르는 확률변수 $X$에 대해 $X=k$일 확률은 다음 공식으로 구한다:\n\n$$P(X = k) = \\binom{n}{k}p^k(1-p)^{n-k}$$\n\n여기서 $\\binom{n}{k} = \\frac{n!}{k!(n-k)!}$는 이항계수이다.\n\n**[풀이]**\n\n주어진 조건: $X \\sim B(6, \\frac{1}{2})$, 구하는 값: $P(X=2)$\n\n이항분포 공식에 $n=6$, $k=2$, $p=\\frac{1}{2}$를 대입한다:\n\n$$P(X = 2) = \\binom{6}{2}\\left(\\frac{1}{2}\\right)^2\\left(1-\\frac{1}{2}\\right)^{6-2}$$\n\n이항계수를 계산하면:\n\n$$\\binom{6}{2} = \\frac{6!}{2!4!} = \\frac{6 \\times 5}{2 \\times 1} = 15$$\n\n각 항을 계산한다:\n\n$$\\left(\\frac{1}{2}\\right)^2 = \\frac{1}{4}$$\n\n$$\\left(\\frac{1}{2}\\right)^{4} = \\frac{1}{16}$$\n\n따라서:\n\n$$P(X = 2) = 15 \\times \\frac{1}{4} \\times \\frac{1}{16} = 15 \\times \\frac{1}{64} = \\frac{15}{64}$$\n\n**[정답 확인]**\n\n이항분포 공식을 올바르게 적용하여 이항계수 15와 확률 $(\\frac{1}{2})^6 = \\frac{1}{64}$를 곱하면 $\\frac{15}{64}$이 된다.\n\n**[오답 분석]**\n\n- ① $\\frac{3}{32}$ : $\\frac{15}{64}$를 잘못 약분하거나 계산 오류\n- ③ $\\frac{5}{16}$ : $\\frac{20}{64}$로, 이항계수를 잘못 계산한 경우\n- ④ $\\frac{1}{4}$ : 이항계수를 무시하고 $(\\frac{1}{2})^2 \\times (\\frac{1}{2})^4$만 계산\n- ⑤ $\\frac{3}{8}$ : $\\frac{24}{64}$로, 공식 적용 과정에서의 산술 오류\n\n**[핵심 포인트]**\n\n이항분포에서 확률을 구할 때는 **이항계수 $\\binom{n}{k}$를 반드시 포함**해야 한다. $p=q=\\frac{1}{2}$인 경우, 대칭성이 있으므로 $P(X=k) = P(X=n-k)$임을 기억하면 검증에 유용한다.",
