    "answer": 1,
    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$를 따르는 확률변수 $X$에 대해:\n- 평균: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n- $E(X^2) = V(X) + [E(X)]^2$ (분산의 정의를 이용한 공식)\n\n이 공식은 $V(X) = E(X^2) - [E(X)]^2$에서 유도된다.\n\n**[풀이]**\n\n주어진 조건: $X \\sim B(8, \\frac{1}{4})$\n\n**1단계: 평균 계산**\n$$E(X) = np = 8 \\times \\frac{1}{4} = 2$$\n\n**2단계: 분산 계산**\n$$V(X) = np(1-p) = 8 \\times \\frac{1}{4} \\times \\frac{3}{4} = 8 \\times \\frac{3}{16} = \\frac{24}{16} = \\frac{3}{2}$$\n\n**3단계: $E(X^2)$ 계산**\n분산과 기댓값의 관계식을 이용하면:\n$$V(X) = E(X^2) - [E(X)]^2$$\n\n따라서:\n$$E(X^2) = V(X) + [E(X)]^2$$\n$$E(X^2) = \\frac{3}{2} + 2^2 = \\frac{3}{2} + 4$$\n$$E(X^2) = \\frac{3}{2} + \\frac{8}{2} = \\frac{11}{2}$$\n\n**[정답 확인]**\n$E(X^2) = V(X) + [E(X)]^2 = \\frac{3}{2} + 4 = \\frac{11}{2}$이므로 정답은 **②번**이다.\n\n**[오답 분석]**\n- **①번 $\\frac{5}{2}$**: $E(X) + V(X) = 2 + \\frac{1}{2}$처럼 잘못 계산한 경우\n- **③번 $\\frac{17}{4}$**: $[E(X)]^2 = 4$를 $\\frac{17}{4}$로 잘못 계산하거나, $\\frac{3}{2} + \\frac{11}{4}$ 같은 오류\n- **④번 $\\frac{21}{4}$**: $V(X)$를 잘못 계산하여 $(np(1-p))$의 값을 크게 잡은 경우\n- **⑤번 $\\frac{11}{4}$**: $E(X^2) = \\frac{11}{2}$를 2로 나누는 실수\n\n**[핵심 포인트]**\n$E(X^2)$을 구할 때는 직접 정의로 계산하지 말고, $E(X^2) = V(X) + [E(X)]^2$ 공식을 사용하면 효율적이다. 이항분포의 평균과 분산을 정확히 계산하는 것이 관건이다.",
