    "answer": 9,
    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 기댓값과 분산 공식:\n- 기댓값: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n이 두 공식을 이용하여 모수 $n$과 $p$를 구하는 문제이다.\n\n**[풀이]**\n\n주어진 조건:\n- $X \\sim B(n, p)$\n- $E(X) = 6$\n- $V(X) = 2$\n\n**Step 1:** 기댓값 공식 적용\n$$E(X) = np = 6 \\cdots (1)$$\n\n**Step 2:** 분산 공식 적용\n$$V(X) = np(1-p) = 2 \\cdots (2)$$\n\n**Step 3:** 식 (2)를 전개\n$$np(1-p) = 2$$\n$$np - np^2 = 2$$\n\n**Step 4:** 식 (1)을 이용하여 $np = 6$ 대입\n$$6 - 6p = 2$$\n$$6p = 4$$\n$$p = \\frac{2}{3}$$\n\n**Step 5:** $p$ 값을 식 (1)에 대입하여 $n$ 구하기\n$$n \\cdot \\frac{2}{3} = 6$$\n$$n = 6 \\times \\frac{3}{2} = 9$$\n\n**[정답 확인]**\n\n$n = 9, p = \\frac{2}{3}$일 때, $E(X) = 9 \\times \\frac{2}{3} = 6$ ✓, $V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = 2$ ✓\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으므로 일반적인 오류 분석:\n- $n = 6$: $E(X) = 6$이지만 $V(X) = 6p(1-p) \\leq 1.5 < 2$ (불가능)\n- $n = 12$: $E(X) = 12p = 6$에서 $p = \\frac{1}{2}$, 하지만 $V(X) = 12 \\times \\frac{1}{2} \\times \\frac{1}{2} = 3 \\neq 2$ (불일치)\n- $n = 18$: $E(X) = 18p = 6$에서 $p = \\frac{1}{3}$, 하지만 $V(X) = 18 \\times \\frac{1}{3} \\times \\frac{2}{3} = 4 \\neq 2$ (불일치)\n\n**[핵심 포인트]**\n\n이항분포의 기댓값과 분산 관계식 $\\frac{V(X)}{E(X)} = 1-p$를 이용하면 $p = 1 - \\frac{V(X)}{E(X)} = 1 - \\frac{2}{6} = \\frac{2}{3}$로 더 빠르게 풀 수 있다.",
