    "answer": 33,
    "explanation": "**[핵심 개념]**\n동전을 던지는 시행은 이항분포를 따릅니다. $X \\sim B(n, p)$일 때:\n- $E(X) = np$\n- $V(X) = np(1-p)$\n- $E(X^2) = V(X) + [E(X)]^2$\n\n이항분포의 분산 공식을 이용하여 $E(X^2)$를 구한다.\n\n**[풀이]**\n\n**1단계: 확률변수 X의 분포 파악**\n\n동전을 12번 던져서 앞면이 나오는 횟수 $X$는 이항분포 $B(12, \\frac{1}{2})$를 따릅니다.\n- $n = 12$\n- $p = \\frac{1}{2}$\n\n**2단계: E(X) 계산**\n\n$$E(X) = np = 12 \\times \\frac{1}{2} = 6$$\n\n**3단계: V(X) 계산**\n\n$$V(X) = np(1-p) = 12 \\times \\frac{1}{2} \\times \\frac{1}{2} = 12 \\times \\frac{1}{4} = 3$$\n\n**4단계: E(X²) 계산**\n\n분산과 기댓값의 관계식을 이용한다:\n$$V(X) = E(X^2) - [E(X)]^2$$\n\n따라서:\n$$E(X^2) = V(X) + [E(X)]^2 = 3 + 6^2 = 3 + 36 = 39$$\n\n**5단계: E(X²) - E(X) 계산**\n\n$$E(X^2) - E(X) = 39 - 6 = 33$$\n\n**[정답 확인]**\n이항분포에서 $E(X^2) = np(1-p) + (np)^2 = 3 + 36 = 39$이고, $E(X) = 6$이므로 $E(X^2) - E(X) = 33$이 맞다.\n\n**[오답 분석]**\n- **39**: $E(X^2)$ 값만 구하고 $E(X)$를 빼지 않은 경우\n- **6**: $E(X)$ 값만 구한 경우\n- **30**: $V(X) + [E(X)]^2 - E(X) = 3 + 36 - 6 = 33$을 계산 실수한 경우\n\n**[핵심 포인트]**\n$E(X^2) = V(X) + [E(X)]^2$ 공식을 기억하고, 마지막에 $E(X)$를 빼는 것을 잊지 않아야 한다. 이항분포에서 분산은 $np(1-p)$임을 확실히 알고 있어야 한다.",
