    "problem": "확률변수 $X$가 이항분포 $B(100, 0.4)$를 따를 때, $\\sigma(2X - 10)$의 값을 구하시오. (답이 $a\\sqrt{b}$ 형태일 때, $a+b$의 값을 구하시오. 단, $b$는 제곱인수를 갖지 않는 자연수)",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[핵심 개념]**\n\n이항분포의 표준편차와 일차함수로 변환된 확률변수의 표준편차를 구하는 문제이다.\n\n1) 이항분포 $B(n, p)$의 표준편차: $\\sigma(X) = \\sqrt{np(1-p)}$\n2) 확률변수의 일차변환: $Y = aX + b$일 때, $\\sigma(Y) = |a| \\cdot \\sigma(X)$\n (상수항 $b$는 표준편차에 영향을 주지 않고, 계수 $a$는 절댓값으로 곱해진다)\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n\n$X \\sim B(100, 0.4)$이므로\n- $n = 100$\n- $p = 0.4$\n\n**2단계: $X$의 표준편차 구하기**\n\n$$\\sigma(X) = \\sqrt{np(1-p)} = \\sqrt{100 \\times 0.4 \\times 0.6}$$\n\n$$= \\sqrt{100 \\times 0.24} = \\sqrt{24}$$\n\n$$= \\sqrt{4 \\times 6} = 2\\sqrt{6}$$\n\n**3단계: $\\sigma(2X - 10)$ 구하기**\n\n일차변환의 성질을 이용하면:\n$$\\sigma(2X - 10) = |2| \\cdot \\sigma(X) = 2 \\cdot \\sigma(X)$$\n\n$$= 2 \\times 2\\sqrt{6} = 4\\sqrt{6}$$\n\n**4단계: $a + b$ 구하기**\n\n$\\sigma(2X - 10) = 4\\sqrt{6}$이므로\n- $a = 4$\n- $b = 6$ (6은 완전제곱수를 인수로 갖지 않음)\n\n따라서 $a + b = 4 + 6 = 10$\n\n**[정답 확인]**\n\n이항분포 $B(100, 0.4)$의 표준편차 $2\\sqrt{6}$에 일차변환 계수 2를 곱하면 $4\\sqrt{6}$이 되므로, $a+b = 10$이 정답이다.\n\n**[오답 분석]**\n\n객관식 선지가 없으므로 생략한다.\n\n**[핵심 포인트]**\n\n1) 이항분포의 표준편차: $\\sigma(X) = \\sqrt{np(1-p)}$ 공식 암기\n2) 확률변수의 일차변환에서는 계수만 표준편차에 곱해지고, 상수항(평행이동)은 표준편차에 영향을 주지 않는다: $\\sigma(aX+b) = |a|\\sigma(X)$",
