    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n, p)$를 따르는 확률변수의 분산은 $V(X) = np(1-p)$이다. 또한 독립인 두 확률변수 $X$, $Y$에 대해 $V(X+Y) = V(X) + V(Y)$가 성립한다. 이는 독립성으로 인해 공분산이 0이 되기 때문이다.\n\n**[풀이]**\n\n**Step 1: $X$의 분산 구하기**\n\n$X \\sim B(10, \\frac{1}{3})$이므로\n$$V(X) = np(1-p) = 10 \\cdot \\frac{1}{3} \\cdot \\left(1-\\frac{1}{3}\\right) = 10 \\cdot \\frac{1}{3} \\cdot \\frac{2}{3} = \\frac{20}{9}$$\n\n**Step 2: $Y$의 분산 구하기**\n\n$Y \\sim B(20, \\frac{1}{3})$이므로\n$$V(Y) = np(1-p) = 20 \\cdot \\frac{1}{3} \\cdot \\left(1-\\frac{1}{3}\\right) = 20 \\cdot \\frac{1}{3} \\cdot \\frac{2}{3} = \\frac{40}{9}$$\n\n**Step 3: $V(X+Y)$ 구하기**\n\n$X$와 $Y$가 서로 독립이므로\n$$V(X+Y) = V(X) + V(Y) = \\frac{20}{9} + \\frac{40}{9} = \\frac{60}{9} = \\frac{20}{3}$$\n\n**[정답 확인]**\n\n$V(X+Y) = \\frac{20}{3}$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n\n- ① $\\frac{40}{9}$: $V(Y)$의 값으로 $V(X)$를 빠뜨린 경우\n- ③ $\\frac{50}{9}$: 계산 실수로 $V(X) + V(Y)$를 잘못 더한 경우\n- ④ $\\frac{70}{9}$: $V(X) + V(Y)$의 분자를 70으로 잘못 계산한 경우\n- ⑤ $\\frac{80}{9}$: $V(X) + V(Y) = \\frac{20}{9} + \\frac{40}{9}$를 $\\frac{80}{9}$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n1. 이항분포 $B(n, p)$의 분산은 항상 $np(1-p)$이다.\n2. **독립인 확률변수들의 합의 분산은 분산들의 합**이라는 점을 반드시 기억하세요. ($V(X+Y) = V(X) + V(Y)$ when $X \\perp Y$)",
