    "answer": 2,
    "explanation": "**[핵심 개념]**\n확률변수의 함수에 대한 기댓값은 다음과 같이 구한다:\n$$E(g(X)) = \\sum g(x) \\cdot P(X=x)$$\n\n이는 $E(X)$를 구하는 것과 달리, 먼저 확률변수를 함수로 변환한 후 각 값에 확률을 곱하여 모두 더하는 방식이다. 주의할 점은 $E(g(X)) \\neq g(E(X))$ 라는 것이다.\n\n**[풀이]**\n\n주어진 확률분포에서 $X$가 취할 수 있는 값은 0, 1, 2, 3이고, 각각의 확률은 모두 $\\frac{1}{4}$이다.\n\n$E\\left(\\frac{1}{X+1}\\right)$을 구하기 위해 $g(X) = \\frac{1}{X+1}$이라 하면:\n\n$$E\\left(\\frac{1}{X+1}\\right) = \\sum_{x=0}^{3} \\frac{1}{x+1} \\cdot P(X=x)$$\n\n각 경우를 계산하면:\n\n- $X=0$일 때: $\\frac{1}{0+1} \\cdot \\frac{1}{4} = \\frac{1}{1} \\cdot \\frac{1}{4} = \\frac{1}{4}$\n\n- $X=1$일 때: $\\frac{1}{1+1} \\cdot \\frac{1}{4} = \\frac{1}{2} \\cdot \\frac{1}{4} = \\frac{1}{8}$\n\n- $X=2$일 때: $\\frac{1}{2+1} \\cdot \\frac{1}{4} = \\frac{1}{3} \\cdot \\frac{1}{4} = \\frac{1}{12}$\n\n- $X=3$일 때: $\\frac{1}{3+1} \\cdot \\frac{1}{4} = \\frac{1}{4} \\cdot \\frac{1}{4} = \\frac{1}{16}$\n\n따라서:\n$$E\\left(\\frac{1}{X+1}\\right) = \\frac{1}{4} + \\frac{1}{8} + \\frac{1}{12} + \\frac{1}{16}$$\n\n분모 48로 통분하면:\n$$= \\frac{12}{48} + \\frac{6}{48} + \\frac{4}{48} + \\frac{3}{48} = \\frac{12+6+4+3}{48} = \\frac{25}{48}$$\n\n**[정답 확인]**\n분자 25와 분모 48의 합이 정확하며, 48은 4, 8, 12, 16의 최소공배수이므로 통분이 올바르다.\n\n**[오답 분석]**\n- ① $\\frac{1}{4}$: $X=0$일 때의 항만 계산한 경우\n- ② $\\frac{12}{25}$: 분자와 분모를 바꾼 오류\n- ④ $\\frac{7}{12}$: 통분 과정에서 계산 오류\n- ⑤ $\\frac{3}{4}$: $E\\left(\\frac{1}{X+1}\\right)$을 $\\frac{1}{E(X)+1}$로 잘못 계산한 경우 ($E(X)=1.5$이므로 $\\frac{1}{2.5}=\\frac{2}{5}$도 아님)\n\n**[핵심 포인트]**\n- 확률변수의 함수에 대한 기댓값은 반드시 각 함수값에 확률을 곱한 후 합산해야 한다.\n- 통분할 때는 모든 분모의 최소공배수를 정확히 찾아 실수를 방지하자.",
