    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이 문제를 풀기 위해 다음 개념들이 필요하다.\n\n1. **이항분포의 기댓값과 분산**: $X \\sim B(n, p)$일 때, $E(X) = np$, $Var(X) = np(1-p)$\n\n2. **분산의 정의**: $Var(X) = E(X^2) - [E(X)]^2$, 따라서 $E(X^2) = Var(X) + [E(X)]^2$\n\n3. **독립확률변수의 성질**: $X$와 $Y$가 독립이면 $E(XY) = E(X)E(Y)$\n\n4. **전개공식**: $E((X-Y)^2) = E(X^2) - 2E(XY) + E(Y^2)$\n\n**[풀이]**\n\n**Step 1: 각 확률변수의 기댓값과 분산 구하기**\n\n$X \\sim B(5, \\frac{1}{2})$이므로:\n- $E(X) = 5 \\times \\frac{1}{2} = \\frac{5}{2}$\n- $Var(X) = 5 \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{5}{4}$\n\n$Y \\sim B(3, \\frac{1}{2})$이므로:\n- $E(Y) = 3 \\times \\frac{1}{2} = \\frac{3}{2}$\n- $Var(Y) = 3 \\times \\frac{1}{2} \\times \\frac{1}{2} = \\frac{3}{4}$\n\n**Step 2: $E(X^2)$와 $E(Y^2)$ 구하기**\n\n$E(X^2) = Var(X) + [E(X)]^2 = \\frac{5}{4} + \\left(\\frac{5}{2}\\right)^2 = \\frac{5}{4} + \\frac{25}{4} = \\frac{30}{4}$\n\n$E(Y^2) = Var(Y) + [E(Y)]^2 = \\frac{3}{4} + \\left(\\frac{3}{2}\\right)^2 = \\frac{3}{4} + \\frac{9}{4} = \\frac{12}{4} = 3$\n\n**Step 3: $E(XY)$ 구하기**\n\n$X$와 $Y$가 독립이므로:\n$$E(XY) = E(X) \\times E(Y) = \\frac{5}{2} \\times \\frac{3}{2} = \\frac{15}{4}$$\n\n**Step 4: $E((X-Y)^2)$ 계산**\n\n$(X-Y)^2$을 전개하면:\n$$E((X-Y)^2) = E(X^2 - 2XY + Y^2) = E(X^2) - 2E(XY) + E(Y^2)$$\n\n$$= \\frac{30}{4} - 2 \\times \\frac{15}{4} + 3$$\n\n$$= \\frac{30}{4} - \\frac{30}{4} + 3 = 3$$\n\n**[정답 확인]**\n\n$E((X-Y)^2) = E(X^2) - 2E(XY) + E(Y^2) = \\frac{30}{4} - \\frac{30}{4} + 3 = 3$이므로 정답은 ③이다.\n\n**[오답 분석]**\n\n- **① 1**: $E(X)$과 $E(Y)$의 차이인 $|E(X) - E(Y)| = 1$을 구한 후 제곱하지 않아 실수한 경우\n- **② 2**: 분산만을 더한 경우 $Var(X) + Var(Y) = \\frac{5}{4} + \\frac{3}{4} = 2$로 잘못 계산한 경우\n- **④ 4**: 계산 과정에서 $E(XY)$ 항을 빼먹거나 부호 오류가 있는 경우\n- **⑤ 5**: 원래 $E(X^2) + E(Y^2)$만 계산한 경우\n\n**[핵심 포인트]**\n\n1. $E((X-Y)^2) = E(X^2) - 2E(XY) + E(Y^2)$로 전개한 후, 독립성을 이용하여 $E(XY) = E(X)E(Y)$로 계산하는 것이 핵심이다.\n\n2. 이항분포에서 $E(X^2)$를 구할 때는 반드시 분산 공식 $E(X^2) = Var(X) + [E(X)]^2$을 사용해야 한다.",
