    "answer": 3,
    "explanation": "**[핵심 개념]**\n확률변수가 가질 수 있는 모든 경우의 확률의 합은 1이어야 한다는 확률의 기본 성질과 기댓값의 정의를 이용하는 문제이다.\n\n- 확률의 합: $\\sum P(X=k) = 1$\n- 기댓값: $E(X) = \\sum k \\cdot P(X=k)$\n\n**[풀이]**\n\n**Step 1: 상수 c 구하기**\n\n확률의 합이 1이어야 하므로:\n$$P(X=1) + P(X=2) + P(X=3) + P(X=4) = 1$$\n\n$$c \\cdot 1^2 + c \\cdot 2^2 + c \\cdot 3^2 + c \\cdot 4^2 = 1$$\n\n$$c(1 + 4 + 9 + 16) = 1$$\n\n$$c \\cdot 30 = 1$$\n\n$$c = \\frac{1}{30}$$\n\n**Step 2: 각 확률값 계산**\n\n- $P(X=1) = \\frac{1}{30} \\cdot 1 = \\frac{1}{30}$\n- $P(X=2) = \\frac{1}{30} \\cdot 4 = \\frac{4}{30}$\n- $P(X=3) = \\frac{1}{30} \\cdot 9 = \\frac{9}{30}$\n- $P(X=4) = \\frac{1}{30} \\cdot 16 = \\frac{16}{30}$\n\n**Step 3: 기댓값 계산**\n\n$$E(X) = 1 \\cdot \\frac{1}{30} + 2 \\cdot \\frac{4}{30} + 3 \\cdot \\frac{9}{30} + 4 \\cdot \\frac{16}{30}$$\n\n$$= \\frac{1 + 8 + 27 + 64}{30}$$\n\n$$= \\frac{100}{30} = \\frac{10}{3}$$\n\n**[정답 확인]**\n\n$c = \\frac{1}{30}$을 이용하여 확률의 합이 1임을 확인하고, $E(X) = \\frac{1 \\cdot 1^2 + 2 \\cdot 2^2 + 3 \\cdot 3^2 + 4 \\cdot 4^2}{30} = \\frac{100}{30} = \\frac{10}{3}$이므로 정답은 ④번이다.\n\n**[오답 분석]**\n\n- **① 2**: 가중평균을 단순하게 계산한 경우\n- **② 3**: $(1+2+3+4)/4 = 2.5$를 반올림한 경우\n- **③ 5/2**: 확률 가중치를 제대로 고려하지 않은 경우\n- **⑤ 100/30**: 약분 전 형태로 표기한 것인데, 선지는 기약분수 형태로 제시되어야 하므로 정답은 ④\n\n**[핵심 포인트]**\n\n1. **확률의 합 = 1 조건을 먼저 이용하여 상수 c를 구하는 것이 필수**이다.\n2. 기댓값은 각 값에 대응하는 확률을 가중치로 하여 계산하므로, $E(X) = \\sum k \\cdot P(X=k)$ 공식을 정확히 적용해야 한다.",
