    "problem": "확률변수 $X$가 이항분포 $B(n, p)$를 따르고 $E(X) = 8$, $E(X^2) = 68$일 때, $n$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 16,
    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$를 따르는 확률변수 $X$에 대해:\n- 평균: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n- $E(X^2) = V(X) + [E(X)]^2$ (분산의 정의를 이용한 공식)\n\n이 세 가지 관계식을 통해 $n$과 $p$를 구한다.\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- $E(X) = 8$\n- $E(X^2) = 68$\n\n**Step 2: 분산 구하기**\n분산의 정의에 의해:\n$$V(X) = E(X^2) - [E(X)]^2 = 68 - 8^2 = 68 - 64 = 4$$\n\n**Step 3: 이항분포의 성질 이용**\n이항분포 $B(n, p)$에서:\n- $E(X) = np = 8$ ... (1)\n- $V(X) = np(1-p) = 4$ ... (2)\n\n**Step 4: $p$ 구하기**\n식 (1)을 식 (2)에 대입:\n$$np(1-p) = 4$$\n$$E(X) \\cdot (1-p) = 4$$\n$$8(1-p) = 4$$\n$$1-p = \\frac{1}{2}$$\n$$p = \\frac{1}{2}$$\n\n**Step 5: $n$ 구하기**\n식 (1)에 $p = \\frac{1}{2}$를 대입:\n$$n \\cdot \\frac{1}{2} = 8$$\n$$n = 16$$\n\n**[정답 확인]**\n$n=16, p=\\frac{1}{2}$일 때, $E(X) = 16 \\times \\frac{1}{2} = 8$ ✓, $V(X) = 16 \\times \\frac{1}{2} \\times \\frac{1}{2} = 4$ ✓, $E(X^2) = 4 + 64 = 68$ ✓\n\n**[오답 분석]**\n객관식 선지가 제시되지 않았으나, 흔한 오답:\n- $n = 8$: $E(X) = np$만 이용하여 $p=1$로 잘못 계산\n- $n = 32$: $V(X) = np$로 잘못 이해하여 $32 \\times p = 4$에서 계산\n- $n = 10$: $E(X^2) = np$로 잘못 해석\n\n**[핵심 포인트]**\n$E(X^2) \\neq E(X)$임을 반드시 기억하고, $E(X^2) = V(X) + [E(X)]^2$ 공식을 통해 분산을 먼저 구하는 것이 핵심이다.",
