    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 과정을 **표준화(standardization)**라고 한다. 확률변수 $X$가 평균 $\\mu$, 표준편차 $\\sigma$인 정규분포 $N(\\mu, \\sigma^2)$를 따를 때, 표준화 공식은 :\n\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n이렇게 변환된 $Z$는 표준정규분포 $N(0, 1)$을 따릅니다.\n\n**[풀이]**\n\n주어진 정보를 정리하면:\n- 확률변수 $X \\sim N(50, 4^2)$\n- 평균: $\\mu = 50$\n- 표준편차: $\\sigma = 4$\n- 표준화할 값: $X = 58$\n\n표준화 공식에 값을 대입한다:\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{58 - 50}{4} = \\frac{8}{4} = 2$$\n\n따라서 $Z = 2$이다.\n\n**[정답 확인]**\n\n$X = 58$을 표준화하면 $Z = \\frac{58-50}{4} = 2$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n\n- ① $Z = 1$: $X = 54$를 표준화했을 때의 값 ($\\frac{54-50}{4} = 1$)\n- ② $Z = 1.5$: $X = 56$을 표준화했을 때의 값 ($\\frac{56-50}{4} = 1.5$)\n- ④ $Z = 2.5$: $X = 60$을 표준화했을 때의 값 ($\\frac{60-50}{4} = 2.5$)\n- ⑤ $Z = 3$: $X = 62$를 표준화했을 때의 값 ($\\frac{62-50}{4} = 3$)\n\n**[핵심 포인트]**\n\n표준화는 $Z = \\frac{X - \\mu}{\\sigma}$로, 분자는 (주어진 값 - 평균), 분모는 표준편차이다. 특히 표준편차가 분모에 오는 것을 놓치면 안 된다.",
