    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n정규분포는 평균을 중심으로 대칭인 종 모양의 확률분포이다. 정규분포 $N(\\mu, \\sigma^2)$에서 $\\mu$는 평균, $\\sigma^2$는 분산이다. 정규분포의 가장 중요한 성질은 평균을 기준으로 좌우가 완전히 대칭이라는 것이다. 따라서 $P(X \\leq \\mu) = P(X \\geq \\mu) = 0.5$이다.\n\n**[풀이]**\n\n주어진 조건:\n- 확률변수 $X$는 정규분포 $N(70, 5^2)$을 따름\n- 평균 $\\mu = 70$\n- 표준편차 $\\sigma = 5$\n- 구하는 값: $P(X \\leq 70)$\n\n정규분포 $N(\\mu, \\sigma^2)$는 평균 $\\mu$를 중심으로 좌우 대칭이다.\n\n$P(X \\leq 70) = P(X \\leq \\mu)$\n\n정규분포의 대칭성에 의해:\n$$P(X \\leq \\mu) = 0.5$$\n\n따라서:\n$$P(X \\leq 70) = 0.5$$\n\n**[정답 확인]**\n\n정규분포는 평균을 중심으로 좌우 대칭이므로, 평균 이하의 확률은 항상 0.5이다.\n\n**[오답 분석]**\n\n- ① 0.25: $P(X \\leq 70) = 0.25$라면 분포가 평균에서 왼쪽으로 치우쳐야 하는데, 정규분포는 대칭이므로 틀림\n- ② 0.3413: 이는 $P(70 < X \\leq 75)$ (즉, $P(\\mu < X \\leq \\mu+\\sigma)$)의 확률로, 평균에서 표준편차 1개 구간의 확률임\n- ④ 0.6827: 이는 $P(65 \\leq X \\leq 75)$ (즉, $P(\\mu-\\sigma \\leq X \\leq \\mu+\\sigma)$)의 확률로, 평균 주변 표준편차 1개 범위의 확률임\n- ⑤ 0.9772: 이는 $P(X \\leq 80)$ (즉, $P(X \\leq \\mu+2\\sigma)$)의 확률로, 평균에서 표준편차 2개 위의 확률임\n\n**[핵심 포인트]**\n\n정규분포는 평균을 중심으로 대칭이므로 $P(X \\leq \\mu) = 0.5$이다. 이는 평균이 무엇이든, 표준편차가 무엇이든 항상 성립하는 기본 성질이다.",
