    "problem": "확률변수 $X$가 정규분포 $N(100, 10^2)$을 따를 때, 다음 중 $P(80 \\leq X \\leq 120)$에 해당하는 것은?\n\n[표준정규분포표]\n| $z$ | $P(0 \\leq Z \\leq z)$ |\n|---|---|\n| 1.0 | 0.3413 |\n| 2.0 | 0.4772 |\n| 3.0 | 0.4987 |",
