    "answer": 3,
    "explanation": "**[핵심 개념]**\n정규분포를 표준정규분포로 변환하는 표준화 과정이 필수이다. \n- 확률변수 $X \\sim N(\\mu, \\sigma^2)$일 때, 표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$\n- 표준정규분포 $Z \\sim N(0, 1)$의 대칭성: $P(Z \\leq 0) = 0.5$, $P(-z \\leq Z \\leq z) = 2P(0 \\leq Z \\leq z)$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(100, 10^2)$ → $\\mu = 100$, $\\sigma = 10$\n- 구하는 확률: $P(80 \\leq X \\leq 120)$\n\n**2단계: 표준화**\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{X - 100}{10}$$\n\n$X = 80$일 때: $Z_1 = \\frac{80 - 100}{10} = \\frac{-20}{10} = -2$\n\n$X = 120$일 때: $Z_2 = \\frac{120 - 100}{10} = \\frac{20}{10} = 2$\n\n따라서:\n$$P(80 \\leq X \\leq 120) = P(-2 \\leq Z \\leq 2)$$\n\n**3단계: 표준정규분포의 대칭성 이용**\n\n표준정규분포는 $Z = 0$을 중심으로 대칭이므로:\n$$P(-2 \\leq Z \\leq 2) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n\n대칭성에 의해:\n$$P(-2 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 2)$$\n\n**4단계: 표에서 값 찾기**\n\n표에서 $P(0 \\leq Z \\leq 2.0) = 0.4772$\n\n따라서:\n$$P(-2 \\leq Z \\leq 2) = 2 \\times P(0 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544 \\approx 0.9545$$\n\n**[정답 확인]**\n④ 0.9545가 정답이다. 평균으로부터 표준편차 2배 범위 내의 확률이며, 이는 정규분포의 성질과 일치한다.\n\n**[오답 분석]**\n- ① 0.3413 : $P(0 \\leq Z \\leq 1)$의 값 (표준편차 1배 범위)\n- ② 0.4772 : $P(0 \\leq Z \\leq 2)$의 값만 취함 (대칭성을 곱하지 않음)\n- ③ 0.6827 : $P(-1 \\leq Z \\leq 1) = 2 \\times 0.3413$ (표준편차 1배 범위)\n- ⑤ 0.9974 : $P(-3 \\leq Z \\leq 3) = 2 \\times 0.4987$ (표준편차 3배 범위)\n\n**[핵심 포인트]**\n- 정규분포 문제는 반드시 **표준화 $Z = \\frac{X-\\mu}{\\sigma}$** 를 먼저 수행\n- 표준정규분포의 **대칭성** 을 이용하여 양쪽 구간을 2배로 계산하는 것이 핵심",
