    "explanation": "**[핵심 개념]**\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 것을 **표준화(standardization)**라고 한다. 확률변수 $X$가 평균 $\\mu$, 표준편차 $\\sigma$인 정규분포 $N(\\mu, \\sigma^2)$을 따를 때, 표준화된 값 $Z$는 다음 공식으로 구한다:\n\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n표준화된 $Z$는 표준정규분포 $N(0, 1)$을 따르며, 이는 평균이 0, 표준편차가 1인 정규분포이다.\n\n**[풀이]**\n주어진 정보를 정리하면:\n- 확률변수 $X$는 $N(60, 3^2)$을 따름\n- 평균: $\\mu = 60$\n- 분산: $\\sigma^2 = 3^2 = 9$\n- 표준편차: $\\sigma = 3$\n- 주어진 $X$의 값: $X = 54$\n\n표준화 공식에 값을 대입한다:\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{54 - 60}{3} = \\frac{-6}{3} = -2$$\n\n따라서 표준화된 값 $Z = -2$이다.\n\n**[정답 확인]**\n$X = 54$는 평균 60보다 3의 표준편차 2배만큼 작은 값이므로, $Z = -2$가 올바른 표준화 값이다.\n\n**[오답 분석]**\n- ① $-3$: 분자를 $60-54=6$으로 잘못 계산하거나 다른 오류가 있을 때 발생\n- ③ $-1$: 표준편차를 6으로 잘못 인식하거나 계산 실수\n- ④ $1$: 부호를 반대로 계산한 경우\n- ⑤ $2$: 분자의 음수 부호를 빠뜨린 경우\n\n**[핵심 포인트]**\n표준화 공식 $Z = \\frac{X - \\mu}{\\sigma}$에서 분자는 (주어진 값 - 평균), 분모는 표준편차(분산의 제곱근)임을 정확히 구분하는 것이 중요하다. 특히 표준편차 $\\sigma$는 분산 $\\sigma^2$에 제곱근을 씌운 값이다.",
