    "explanation": "**[핵심 개념]**\n\n표준정규분포는 평균이 0, 표준편차가 1인 정규분포 $N(0, 1)$이다. 이 분포는 0을 중심으로 좌우 대칭인 종 모양의 분포이며, 전체 확률의 합은 1이다. 정규분포의 대칭성에 의해 $P(Z \\geq 0) = P(Z \\leq 0)$이며, 이 두 확률의 합은 전체 확률인 1이 된다.\n\n**[풀이]**\n\n표준정규분포 $N(0, 1)$의 특성을 이용한다.\n\n**Step 1: 정규분포의 대칭성**\n표준정규분포는 0을 중심으로 완전히 대칭인 분포이다.\n\n$$P(Z \\geq 0) + P(Z < 0) = 1$$\n\n**Step 2: 대칭성에 의한 확률 계산**\n대칭성에 의해:\n$$P(Z \\geq 0) = P(Z < 0)$$\n\n$P(Z = 0) = 0$이므로 $P(Z < 0) = P(Z \\leq 0)$이다.\n\n**Step 3: 방정식 풀이**\n$P(Z \\geq 0) = P(Z < 0)$이고, 두 확률의 합이 1이므로:\n\n$$P(Z \\geq 0) + P(Z \\geq 0) = 1$$\n\n$$2 \\cdot P(Z \\geq 0) = 1$$\n\n$$P(Z \\geq 0) = \\frac{1}{2} = 0.5$$\n\n**[정답 확인]**\n\n표준정규분포가 0을 중심으로 완전히 대칭이므로, 0 이상의 확률은 전체의 정확히 절반인 0.5이다.\n\n**[오답 분석]**\n\n- **① 0**: 0 이상의 값들은 무한히 많이 존재하므로 확률이 0이 될 수 없다.\n- **② 0.25**: 대칭성을 무시하고 임의로 선택한 값이다. \n- **④ 0.75**: 0 이상이 아닌 다른 구간(예: $-0.67 \\leq Z \\leq 0.67$ 등)의 확률과 혼동한 경우이다.\n- **⑤ 1**: $P(Z \\geq 0) = 1$이면 음수는 불가능하다는 뜻인데, 표준정규분포에서는 음수도 존재한다.\n\n**[핵심 포인트]**\n\n표준정규분포는 평균 0을 중심으로 좌우 완전히 대칭이므로 $P(Z \\geq 0) = P(Z \\leq 0) = 0.5$이다. 이는 정규분포 문제의 기본이 되는 중요한 성질이다.",
