    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 과정을 표준화(standardization)라고 한다. \n\n확률변수 $X$가 정규분포 $N(\\mu, \\sigma^2)$을 따를 때, $X$를 표준화한 값 $Z$는 다음 공식으로 구한다:\n\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n여기서 $\\mu$는 평균, $\\sigma$는 표준편차이며, 표준화된 $Z$는 표준정규분포 $N(0, 1)$을 따릅니다.\n\n**[풀이]**\n\n주어진 정보를 정리하면:\n- 확률변수 $X$는 정규분포 $N(80, 6^2)$을 따름\n- 평균: $\\mu = 80$\n- 분산: $\\sigma^2 = 6^2$이므로 표준편차: $\\sigma = 6$\n- 표준화할 값: $X = 92$\n\n표준화 공식에 주어진 값을 대입한다:\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{92 - 80}{6}$$\n\n분자를 계산하면:\n$$Z = \\frac{12}{6}$$\n\n나눗셈을 수행하면:\n$$Z = 2$$\n\n**[정답 확인]**\n\n$X = 92$는 평균 80보다 12만큼 크고, 이는 표준편차 6의 정확히 2배이므로 표준화 값은 2이다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으므로 일반적인 오류 사례를 제시한다:\n- **1**: 분모와 분자를 바꾸거나 $(92-80) = 12$를 $6$으로 나누지 않은 경우\n- **0.5**: $6$을 $12$로 나누는 역산을 한 경우\n- **12**: 표준화하지 않고 단순히 $92 - 80$만 계산한 경우\n\n**[핵심 포인트]**\n\n표준화는 $\\frac{\\text{(값 - 평균)}}{\\text{표준편차}}$ 공식을 정확히 적용하는 것이 중요하다. 표준편차 $\\sigma$는 분산의 제곱근이므로 주어진 분산 형태에서 주의깊게 확인해야 한다.",
