    "answer": 50,
    "explanation": "**[핵심 개념]**\n정규분포 $N(\\mu, \\sigma^2)$는 평균 $\\mu$를 중심으로 좌우 대칭인 분포이다. 정규분포의 대칭성에 의해, 평균으로부터 같은 거리에 있는 두 점에서의 확률은 같다. 즉, $P(X \\leq a) = P(X \\geq b)$라는 조건이 주어지면, 이는 $a$와 $b$가 평균 $\\mu$를 중심으로 대칭이라는 의미이다.\n\n**[풀이]**\n\n**Step 1: 주어진 조건 분석**\n\n$P(X \\leq 30) = P(X \\geq 70)$이 주어졌다.\n\n**Step 2: 정규분포의 대칭성 이용**\n\n정규분포는 평균 $\\mu$를 중심으로 대칭이므로, 다음이 성립한다:\n$$P(X \\leq a) = P(X \\geq b) \\Leftrightarrow a + b = 2\\mu$$\n\n이는 $a$와 $b$가 $\\mu$로부터 같은 거리에 있다는 의미이다.\n\n**Step 3: 식 적용**\n\n주어진 조건 $P(X \\leq 30) = P(X \\geq 70)$에서:\n- $a = 30$\n- $b = 70$\n\n따라서:\n$$30 + 70 = 2\\mu$$\n\n$$100 = 2\\mu$$\n\n$$\\mu = 50$$\n\n**Step 4: 검증**\n\n$\\mu = 50$일 때, 30과 70은 평균 50으로부터 각각 20만큼 떨어져 있다.\n- 30은 평균 아래로 20\n- 70은 평균 위로 20\n\n정규분포의 대칭성에 의해 $P(X \\leq 30) = P(X \\geq 70)$ ✓\n\n**[정답 확인]**\n정규분포의 대칭성에서 $P(X \\leq 30) = P(X \\geq 70)$이면 30과 70이 평균을 중심으로 대칭이므로, $\\mu = \\frac{30+70}{2} = 50$이다.\n\n**[오답 분석]**\n객관식 선택지가 없으므로 스킵한다.\n\n**[핵심 포인트]**\n- 정규분포의 핵심은 **평균을 중심으로 한 좌우 대칭성**이다.\n- $P(X \\leq a) = P(X \\geq b)$ 형태의 조건이 주어지면 **$\\mu = \\frac{a+b}{2}$**로 즉시 구한다.",
