    "explanation": "**[핵심 개념]**\n정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수 $X$를 표준정규분포로 변환하려면 표준화 공식을 사용한다.\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n표준화된 $Z$는 표준정규분포 $N(0, 1)$을 따르며, 표준정규분포표에서 $P(0 \\leq Z \\leq z)$ 값을 이용하여 확률을 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(100, 15^2)$ → $\\mu = 100$, $\\sigma = 15$\n- 구하는 값: $P(X \\geq 130)$\n\n**2단계: 표준화 공식 적용**\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{X - 100}{15}$$\n\n$X = 130$일 때:\n$$Z = \\frac{130 - 100}{15} = \\frac{30}{15} = 2$$\n\n따라서:\n$$P(X \\geq 130) = P(Z \\geq 2)$$\n\n**3단계: 표준정규분포표를 이용한 확률 계산**\n\n표준정규분포는 $z = 0$을 중심으로 대칭이므로:\n$$P(Z \\geq 0) = 0.5$$\n\n표에서 $P(0 \\leq Z \\leq 2) = 0.4772$\n\n따라서:\n$$P(Z \\geq 2) = P(Z \\geq 0) - P(0 \\leq Z \\leq 2)$$\n$$= 0.5 - 0.4772 = 0.0228$$\n\n**[정답 확인]**\n표준화를 통해 $P(X \\geq 130) = P(Z \\geq 2) = 0.5 - 0.4772 = 0.0228$이므로 정답은 **②**이다.\n\n**[오답 분석]**\n- **①번 0.0013**: $P(Z \\geq 3) = 0.5 - 0.4987 = 0.0013$로, $z=3$일 때의 확률이다.\n- **③번 0.1587**: $P(Z \\geq 1) = 0.5 - 0.3413 = 0.1587$로, $z=1$일 때의 확률이다.\n- **④번 0.3413**: 표에서 직접 찾은 $P(0 \\leq Z \\leq 1)$ 값으로, 문제와 무관한다.\n- **⑤번 0.4772**: 표에서 직접 찾은 $P(0 \\leq Z \\leq 2)$ 값으로, 우측 꼬리 확률이 아닙니다.\n\n**[핵심 포인트]**\n1. 정규분포 문제는 반드시 표준화하여 표준정규분포로 변환해야 한다.\n2. 표에 $P(0 \\leq Z \\leq z)$ 값이 주어지면, $P(Z \\geq z) = 0.5 - P(0 \\leq Z \\leq z)$로 계산한다.",
