    "explanation": "**[핵심 개념]**\n정규분포는 평균을 중심으로 대칭인 분포이다. 따라서 $P(X \\leq a) = P(X \\geq b)$이면 $a$와 $b$는 평균 $\\mu$를 중심으로 대칭이다. 또한 표준화를 통해 표준정규분포로 변환하면 $Z = \\frac{X - \\mu}{\\sigma}$이고, 표준정규분포표를 이용하여 확률을 구한다.\n\n**[풀이]**\n\n**Step 1: 첫 번째 조건에서 평균 구하기**\n\n$P(X \\leq 40) = P(X \\geq 60)$\n\n정규분포는 평균을 중심으로 대칭이므로, 이 조건은 40과 60이 평균 $\\mu$를 중심으로 대칭임을 의미한다.\n\n$$\\mu = \\frac{40 + 60}{2} = 50$$\n\n**Step 2: 두 번째 조건을 표준화하기**\n\n$P(X \\geq 55) = 0.1587$이 주어졌다.\n\n$X$를 표준화하면:\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{X - 50}{\\sigma}$$\n\n$X = 55$일 때:\n$$Z = \\frac{55 - 50}{\\sigma} = \\frac{5}{\\sigma}$$\n\n따라서:\n$$P\\left(Z \\geq \\frac{5}{\\sigma}\\right) = 0.1587$$\n\n**Step 3: 표준정규분포표를 이용하여 $Z$ 값 구하기**\n\n표준정규분포는 $Z = 0$을 중심으로 대칭이므로:\n$$P(Z \\geq z) = 0.1587 \\text{이면 } P(Z \\leq z) = 1 - 0.1587 = 0.8413$$\n\n표준정규분포표에서 $P(0 \\leq Z \\leq 1) = 0.3413$이므로:\n$$P(Z \\leq 1) = P(Z \\leq 0) + P(0 \\leq Z \\leq 1) = 0.5 + 0.3413 = 0.8413$$\n\n따라서:\n$$\\frac{5}{\\sigma} = 1$$\n\n**Step 4: $\\sigma$ 구하기**\n\n$$\\sigma = 5$$\n\n**[정답 확인]**\n$\\mu = 50$, $\\sigma = 5$일 때, $P(X \\geq 55) = P(Z \\geq 1) = 0.1587$이 정확히 만족되므로 답은 ②번이다.\n\n**[오답 분석]**\n- ① $\\sigma = 3$: $P(Z \\geq \\frac{5}{3} \\approx 1.67) \\approx 0.0475$ (너무 작음)\n- ③ $\\sigma = 7$: $P(Z \\geq \\frac{5}{7} \\approx 0.71) \\approx 0.238$ (너무 큼)\n- ④ $\\sigma = 10$: $P(Z \\geq 0.5) \\approx 0.309$ (너무 큼)\n- ⑤ $\\sigma = 15$: $P(Z \\geq \\frac{1}{3}) \\approx 0.369$ (너무 큼)\n\n**[핵심 포인트]**\n1. 정규분포의 대칭성을 이용하여 $P(X \\leq a) = P(X \\geq b)$에서 평균을 구하는 것이 첫 단계이다.\n2. 표준화 공식 $Z = \\frac{X - \\mu}{\\sigma}$를 정확히 적용하고 표준정규분포표를 올바르게 읽는 것이 중요하다.",
