    "explanation": "**[핵심 개념]**\n확률변수 $X$가 정규분포 $N(\\mu, \\sigma^2)$를 따를 때, 이를 표준정규분포로 변환하기 위해 표준화를 사용한다.\n- 표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$\n- 표준정규분포 $N(0, 1)$에서 $P(0 \\leq Z \\leq z) = P(-z \\leq Z \\leq 0)$ (대칭성)\n- $P(a \\leq Z \\leq b) = P(0 \\leq Z \\leq b) - P(0 \\leq Z \\leq a)$ (단, $0 < a < b$)\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- $X \\sim N(60, 4^2)$이므로 $\\mu = 60$, $\\sigma = 4$\n- 구하는 값: $P(52 \\leq X \\leq 68)$\n\n**Step 2: 표준화**\n$X$를 표준정규분포 $Z$로 변환한다.\n\n$X = 52$일 때: $Z = \\frac{52 - 60}{4} = \\frac{-8}{4} = -2$\n\n$X = 68$일 때: $Z = \\frac{68 - 60}{4} = \\frac{8}{4} = 2$\n\n따라서 $P(52 \\leq X \\leq 68) = P(-2 \\leq Z \\leq 2)$\n\n**Step 3: 표준정규분포표 이용**\n표준정규분포의 대칭성을 이용하면:\n\n$$P(-2 \\leq Z \\leq 2) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n\n$$= P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 2)$$\n\n$$= 2 \\times P(0 \\leq Z \\leq 2)$$\n\n$$= 2 \\times 0.4772 = 0.9544$$\n\n**[정답 확인]**\n표준화하면 $P(-2 \\leq Z \\leq 2) = 2 \\times P(0 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$이므로 정답은 ③이다.\n\n**[오답 분석]**\n- ① 0.3413: $P(0 \\leq Z \\leq 1)$의 값으로, $z=1$을 사용한 경우\n- ② 0.6827: $2 \\times 0.3413 = 0.6827$로, $P(-1 \\leq Z \\leq 1)$에 해당 (표준편차 1배 범위)\n- ④ 0.9772: $P(0 \\leq Z \\leq 2) = 0.4772$의 값 자체 또는 계산 실수\n- ⑤ 0.4772: $P(0 \\leq Z \\leq 2)$의 값으로, 2를 곱하지 않은 경우\n\n**[핵심 포인트]**\n- 정규분포 문제는 반드시 **표준화**를 먼저 수행하세요.\n- 표준정규분포의 **대칭성**을 이용하여 $P(-z \\leq Z \\leq z) = 2 \\times P(0 \\leq Z \\leq z)$임을 기억하세요.",
