    "answer": 1,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 확률변수를 표준정규분포로 변환하기 위해 표준화(standardization)를 사용한다.\n\n확률변수 $X$가 $N(\\mu, \\sigma^2)$을 따를 때, $Z = \\frac{X-\\mu}{\\sigma}$로 변환하면 $Z$는 표준정규분포 $N(0,1)$을 따릅니다.\n\n표준정규분포표는 $P(0 \\leq Z \\leq z)$의 값을 제공하므로, 이를 이용하여 구하는 확률을 계산할 수 있다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(70, 10^2)$에서 $\\mu = 70$, $\\sigma = 10$\n- 구하는 값: $P(X \\leq 50)$\n\n**2단계: 표준화**\n\n$X$를 표준정규분포 $Z$로 변환한다.\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{X - 70}{10}$$\n\n$X = 50$일 때:\n$$Z = \\frac{50 - 70}{10} = \\frac{-20}{10} = -2$$\n\n따라서:\n$$P(X \\leq 50) = P(Z \\leq -2)$$\n\n**3단계: 표준정규분포표를 이용한 계산**\n\n표준정규분포는 $z=0$을 중심으로 대칭이므로:\n$$P(Z \\leq -2) = P(Z \\geq 2)$$\n\n표에서 $P(0 \\leq Z \\leq 2) = 0.4772$이고,\n\n표준정규분포의 전체 확률은 1이며 $z=0$을 중심으로 대칭이므로:\n$$P(Z \\geq 0) = 0.5$$\n\n따라서:\n$$P(Z \\geq 2) = P(Z \\geq 0) - P(0 \\leq Z \\leq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**[정답 확인]**\n정규분포의 대칭성을 이용하여 표준화된 값 $Z=-2$에 대한 확률을 $P(Z \\geq 2)$로 변환한 후, 표에서 제공하는 $P(0 \\leq Z \\leq 2) = 0.4772$를 이용하여 $0.5 - 0.4772 = 0.0228$을 얻으므로 정답은 ②이다.\n\n**[오답 분석]**\n\n① **0.0013**: $P(Z \\leq -3)$에 해당하는 값으로, 표준화 계산을 잘못했을 때 나타나는 오답\n\n③ **0.1587**: $P(Z \\leq -1)$에 해당하는 값으로, 표준화 과정에서 $\\sigma=10$을 고려하지 않은 경우\n\n④ **0.3413**: 표에서 직접 읽은 $P(0 \\leq Z \\leq 1)$의 값으로, 표를 잘못 해석한 경우\n\n⑤ **0.4772**: 표에서 직접 읽은 $P(0 \\leq Z \\leq 2)$의 값으로, 음수 부호를 무시하고 표를 그대로 읽은 경우\n\n**[핵심 포인트]**\n- 정규분포 문제는 반드시 **표준화** $Z = \\frac{X-\\mu}{\\sigma}$를 먼저 수행해야 함\n- 표준정규분포의 **대칭성**을 이용하여 음수 확률을 양수 확률로 변환: $P(Z \\leq -a) = P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$",
