    "answer": 8185,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 과정이 핵심이다.\n\n확률변수 $X$가 $N(\\mu, \\sigma^2)$를 따를 때, 표준화 공식은 $Z = \\frac{X - \\mu}{\\sigma}$이며, 이렇게 변환된 $Z$는 표준정규분포 $N(0, 1)$을 따릅니다. 표준정규분포의 대칭성을 이용하여 구간 확률을 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n\n$X \\sim N(200, 20^2)$이므로 $\\mu = 200$, $\\sigma = 20$이다.\n\n구하려는 확률은 $P(180 \\leq X \\leq 240)$이다.\n\n**2단계: 표준화 변환**\n\n$X$를 표준정규분포 $Z$로 변환한다:\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{X - 200}{20}$$\n\n$X = 180$일 때: $Z = \\frac{180 - 200}{20} = \\frac{-20}{20} = -1$\n\n$X = 240$일 때: $Z = \\frac{240 - 200}{20} = \\frac{40}{20} = 2$\n\n**3단계: 표준정규분포 확률로 변환**\n\n$$P(180 \\leq X \\leq 240) = P(-1 \\leq Z \\leq 2)$$\n\n**4단계: 표준정규분포의 대칭성 이용**\n\n표준정규분포는 $Z = 0$을 중심으로 대칭이므로:\n\n$$P(-1 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 1) = 0.3413$$\n\n$$P(0 \\leq Z \\leq 2) = 0.4772$$\n\n**5단계: 확률 계산**\n\n$$P(-1 \\leq Z \\leq 2) = P(-1 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n\n$$= 0.3413 + 0.4772 = 0.8185$$\n\n**6단계: 최종 답 계산**\n\n문제에서 \"답에 10000을 곱하여 정수로 답하시오\"라고 했으므로:\n\n$$0.8185 \\times 10000 = 8185$$\n\n**[정답 확인]**\n\n표준화를 통해 $P(-1 \\leq Z \\leq 2)$로 변환한 후, 표준정규분포의 대칭성을 이용하여 $0.3413 + 0.4772 = 0.8185$를 얻고, 이에 10000을 곱하면 8185가 된다.\n\n**[오답 분석]**\n\n- 8372: $P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 2) = 0.3413 + 0.4959$를 계산한 오류 (표준정규분포표 값을 잘못 읽음)\n- 8159: 한쪽 방향의 확률만 계산하거나 표준화 과정에서 계산 실수\n- 7745: 합집합을 곱셈으로 계산하는 등 기본 개념 오류\n\n**[핵심 포인트]**\n\n1. **표준화는 필수**: $Z = \\frac{X - \\mu}{\\sigma}$ 공식으로 정규분포를 표준정규분포로 변환해야 표가 사용 가능한다.\n\n2. **대칭성 활용**: $P(-a \\leq Z \\leq 0) = P(0 \\leq Z \\leq a)$를 항상 기억하고, 표의 값은 0 이상 구간만 주어지므로 음수 구간의 확률을 변환해야 한다.",
