    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 표준화 공식을 사용한다.\n\n정규분포 $N(\\mu, \\sigma^2)$을 따르는 확률변수 $X$를 표준정규분포 $N(0, 1)$을 따르는 확률변수 $Z$로 변환하는 공식:\n$$Z = \\frac{X - \\mu}{\\sigma}$$\n\n표준정규분포의 대칭성을 이용하여 구간 확률을 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(50, 10^2)$ (평균 $\\mu = 50$, 표준편차 $\\sigma = 10$)\n- 구하는 값: $P(X \\geq 70)$\n- 주어진 표: $P(0 \\leq Z \\leq 2) = 0.4772$\n\n**2단계: 표준화**\n\n$X = 70$을 표준정규분포로 변환한다.\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{70 - 50}{10} = \\frac{20}{10} = 2$$\n\n따라서 구하는 확률은:\n$$P(X \\geq 70) = P(Z \\geq 2)$$\n\n**3단계: 표준정규분포의 성질 이용**\n\n표준정규분포는 $Z = 0$을 중심으로 좌우 대칭이므로:\n$$P(Z \\geq 0) = 0.5$$\n\n또한 다음이 성립한다:\n$$P(Z \\geq 2) = P(Z \\geq 0) - P(0 \\leq Z \\leq 2)$$\n\n**4단계: 확률 계산**\n\n주어진 표에서 $P(0 \\leq Z \\leq 2) = 0.4772$이므로:\n\n$$P(Z \\geq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**5단계: 백분율로 변환**\n\n$$0.0228 = 2.28\\%$$\n\n정수로 표현하면 약 **2%**\n\n**[정답 확인]**\n\n표준화를 통해 $P(X \\geq 70) = P(Z \\geq 2) = 0.0228 = 2.28\\% \\approx 2\\%$이므로 정답은 2이다.\n\n**[오답 분석]**\n\n객관식 선택지가 제시되지 않았으나, 흔한 오답은:\n- **4.56%**: $0.4772 \\times 2 = 0.9544$로 잘못 계산\n- **47.72%**: 표에서 읽은 값 $0.4772$를 그대로 백분율로 표현\n- **50%**: 표준화 과정을 건너뛰고 단순 계산\n\n**[핵심 포인트]**\n\n1. **표준화 공식**: $Z = \\frac{X - \\mu}{\\sigma}$를 정확히 적용하는 것이 핵심이다.\n2. **대칭성 활용**: $P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$로 한쪽 꼬리 확률을 구한다.",
