    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 표준화 과정이 핵심이다.\n\n확률변수 $X \\sim N(\\mu, \\sigma^2)$일 때, $Z = \\frac{X - \\mu}{\\sigma}$로 변환하면 $Z \\sim N(0, 1)$ (표준정규분포)을 따릅니다.\n\n표준정규분포의 성질:\n- $P(Z \\leq 0) = 0.5$\n- $P(0 \\leq Z \\leq a) = P(Z \\leq a) - 0.5$ (단, $a > 0$)\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(50, \\sigma^2)$ (즉, $\\mu = 50$)\n- $P(X \\leq 65) = 0.8413$\n- $P(0 \\leq Z \\leq 1) = 0.3413$\n\n**2단계: $X$를 표준정규분포 $Z$로 변환**\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{X - 50}{\\sigma}$$\n\n$X = 65$일 때:\n$$Z = \\frac{65 - 50}{\\sigma} = \\frac{15}{\\sigma}$$\n\n**3단계: 표준정규분포로 확률 표현**\n\n$$P(X \\leq 65) = P\\left(Z \\leq \\frac{15}{\\sigma}\\right) = 0.8413$$\n\n**4단계: 표준정규분포표 해석**\n\n표준정규분포의 성질에 의해:\n$$P(Z \\leq a) = 0.5 + P(0 \\leq Z \\leq a)$$ (단, $a > 0$)\n\n따라서:\n$$P\\left(Z \\leq \\frac{15}{\\sigma}\\right) = 0.5 + P\\left(0 \\leq Z \\leq \\frac{15}{\\sigma}\\right) = 0.8413$$\n\n**5단계: $P(0 \\leq Z \\leq \\frac{15}{\\sigma})$ 계산**\n\n$$P\\left(0 \\leq Z \\leq \\frac{15}{\\sigma}\\right) = 0.8413 - 0.5 = 0.3413$$\n\n**6단계: 표준정규분포표와 비교**\n\n주어진 표에서 $P(0 \\leq Z \\leq 1) = 0.3413$\n\n따라서:\n$$\\frac{15}{\\sigma} = 1$$\n\n$$\\sigma = 15$$\n\n**[정답 확인]**\n\n$\\sigma = 15$일 때, $P(X \\leq 65) = P(Z \\leq 1) = 0.5 + 0.3413 = 0.8413$ ✓\n\n**[오답 분석]**\n\n객관식 선지가 제시되지 않았으나, 흔한 오류:\n- $\\sigma = 10$: $P(Z \\leq 1.5)$를 계산하게 되어 0.8413과 맞지 않음\n- $\\sigma = 20$: $P(Z \\leq 0.75)$를 계산하게 되어 0.8413과 맞지 않음\n- $\\sigma = 5$: $P(Z \\leq 3)$을 계산하게 되어 0.8413과 맞지 않음\n\n**[핵심 포인트]**\n\n1. 정규분포 문제의 핵심은 표준화: $Z = \\frac{X - \\mu}{\\sigma}$로 변환하여 표준정규분포표를 활용하기\n2. $P(Z \\leq a) = 0.5 + P(0 \\leq Z \\leq a)$ 공식으로 주어진 확률값과 표를 연결하기",
