    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항분포의 정규근사: 이항분포 $B(n, p)$를 따르는 확률변수 $X$는 $n$이 충분히 클 때, 평균 $\\mu = np$, 분산 $\\sigma^2 = np(1-p)$인 정규분포로 근사할 수 있다.\n\n표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$로 표준정규분포로 변환하여 확률을 계산한다.\n\n표준정규분포의 대칭성: $P(Z \\leq 0) = 0.5$이고, $P(-z \\leq Z \\leq z) = 2 \\times P(0 \\leq Z \\leq z)$이다.\n\n**[풀이]**\n\n**단계 1: 이항분포의 모수 확인**\n- $n = 100$, $p = 0.5$\n- 평균: $\\mu = np = 100 \\times 0.5 = 50$\n- 분산: $\\sigma^2 = np(1-p) = 100 \\times 0.5 \\times 0.5 = 25$\n- 표준편차: $\\sigma = \\sqrt{25} = 5$\n\n**단계 2: 구간을 표준화**\n\n$40 \\leq X \\leq 60$을 $Z$로 변환한다.\n\n$$Z_1 = \\frac{40 - 50}{5} = \\frac{-10}{5} = -2$$\n\n$$Z_2 = \\frac{60 - 50}{5} = \\frac{10}{5} = 2$$\n\n따라서 구하는 확률은:\n$$P(40 \\leq X \\leq 60) = P(-2 \\leq Z \\leq 2)$$\n\n**단계 3: 표준정규분포표를 이용하여 확률 계산**\n\n표준정규분포의 대칭성을 이용하면:\n$$P(-2 \\leq Z \\leq 2) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n\n$$= P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 2)$$\n\n$$= 2 \\times P(0 \\leq Z \\leq 2)$$\n\n표에서 $P(0 \\leq Z \\leq 2) = 0.4772$이므로:\n\n$$P(-2 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$$\n\n**[정답 확인]**\n\n$P(40 \\leq X \\leq 60) = 0.9544$이므로 정답은 **③번**이다.\n\n**[오답 분석]**\n\n- ① 0.6827: $2 \\times P(0 \\leq Z \\leq 1) = 2 \\times 0.3413$로, $Z = \\pm 1$ 범위의 확률이다.\n- ② 0.8413: $0.5 + P(0 \\leq Z \\leq 2) = 0.5 + 0.4772$로, 한쪽 꼬리까지만 포함한 값이다.\n- ④ 0.9772: $0.5 + 2 \\times P(0 \\leq Z \\leq 2)$로, 계산 오류로 인한 값이다.\n- ⑤ 0.4772: 표에서 직접 읽은 값으로, $P(0 \\leq Z \\leq 2)$만 계산한 것이다.\n\n**[핵심 포인트]**\n\n1. 이항분포의 정규근사에서는 반드시 평균과 표준편차를 구한 후 표준화해야 한다.\n2. 대칭인 구간 $P(-z \\leq Z \\leq z)$은 표에서 $2 \\times P(0 \\leq Z \\leq z)$로 계산한다.",
