    "explanation": "**[핵심 개념]**\n이항분포 $B(n, p)$는 $n$이 충분히 클 때 정규분포로 근사할 수 있다. 이항분포의 평균은 $\\mu = np$, 분산은 $\\sigma^2 = np(1-p)$이며, 표준화하여 표준정규분포를 이용해 확률을 구한다. 표준화 공식은 $Z = \\frac{X - \\mu}{\\sigma}$이다.\n\n**[풀이]**\n\n**1단계: 이항분포의 평균과 표준편차 구하기**\n\n$X \\sim B(400, 0.5)$일 때:\n- 평균: $\\mu = np = 400 \\times 0.5 = 200$\n- 분산: $\\sigma^2 = np(1-p) = 400 \\times 0.5 \\times 0.5 = 100$\n- 표준편차: $\\sigma = \\sqrt{100} = 10$\n\n**2단계: 표준화하기**\n\n$P(X \\geq 220)$을 구하기 위해 220을 표준화한다:\n\n$$Z = \\frac{220 - 200}{10} = \\frac{20}{10} = 2$$\n\n따라서:\n$$P(X \\geq 220) = P(Z \\geq 2)$$\n\n**3단계: 표준정규분포표를 이용하여 확률 계산**\n\n표준정규분포의 대칭성을 이용하면:\n$$P(Z \\geq 2) = P(Z \\leq -2) = 0.5 - P(0 \\leq Z \\leq 2)$$\n\n주어진 표에서 $P(0 \\leq Z \\leq 2) = 0.4772$이므로:\n\n$$P(Z \\geq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**[정답 확인]**\n정규근사를 이용하여 표준화한 후 표준정규분포표에서 양쪽 꼬리 확률을 계산한 결과 0.0228이 정답이다.\n\n**[오답 분석]**\n- **①번 0.0013**: $P(Z \\geq 3)$의 값으로, 표준화 계산 오류로 인한 선택지\n- **③번 0.1587**: $P(Z \\geq 1)$에 해당하며, 표준편차를 잘못 계산했을 때의 결과\n- **④번 0.4772**: 표에서 직접 읽은 $P(0 \\leq Z \\leq 2)$ 값으로, $P(Z \\geq 2)$를 구하지 않은 오류\n- **⑤번 0.9772**: $P(Z \\leq 2)$의 값으로, 부등호 방향을 반대로 이해한 오류\n\n**[핵심 포인트]**\n이항분포의 정규근사에서는 표준편차를 정확히 구한 후 표준화하고, 표준정규분포표에서 양쪽 꼬리 확률($P(Z \\geq 2) = 0.5 - P(0 \\leq Z \\leq 2)$)을 구해야 한다.",
