    "explanation": "**[핵심 개념]**\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 표준화 과정이 핵심이다. \n- 정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수 $X$를 표준화하면: $Z = \\frac{X - \\mu}{\\sigma}$\n- 표준화된 $Z$는 표준정규분포 $N(0, 1)$을 따릅니다.\n- 구간 확률은 표준정규분포표를 이용하여 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 조건 정리**\n- $X \\sim N(500, 20^2)$ \n- $\\mu = 500$ (평균), $\\sigma = 20$ (표준편차)\n- 합격 조건: $460 \\leq X \\leq 540$\n\n**2단계: 표준화**\n합격 범위를 표준정규분포로 변환한다.\n\n$$P(460 \\leq X \\leq 540) = P\\left(\\frac{460-500}{20} \\leq \\frac{X-\\mu}{\\sigma} \\leq \\frac{540-500}{20}\\right)$$\n\n$$= P\\left(\\frac{-40}{20} \\leq Z \\leq \\frac{40}{20}\\right)$$\n\n$$= P(-2 \\leq Z \\leq 2)$$\n\n**3단계: 표준정규분포표 이용**\n표준정규분포는 평균 0을 중심으로 대칭이므로:\n\n$$P(-2 \\leq Z \\leq 2) = P(Z \\leq 2) - P(Z < -2)$$\n\n$$= P(Z \\leq 0) + P(0 \\leq Z \\leq 2) - P(Z < -2)$$\n\n대칭성에 의해 $P(Z < -2) = P(Z > 2) = 1 - P(Z \\leq 2)$이고,\n$P(Z \\leq 0) = 0.5$이므로:\n\n$$P(-2 \\leq Z \\leq 2) = P(0 \\leq Z \\leq 2) + P(-2 \\leq Z \\leq 0)$$\n\n$$= P(0 \\leq Z \\leq 2) + P(0 \\leq Z \\leq 2) = 2 \\times P(0 \\leq Z \\leq 2)$$\n\n$$= 2 \\times 0.4772 = 0.9544$$\n\n**4단계: 합격률 계산**\n$$\\text{합격률} = 0.9544 = 95.44\\%$$\n\n**[정답 확인]**\n표준화하여 $P(-2 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544 = 95.44\\%$가 되므로 정답은 ④이다.\n\n**[오답 분석]**\n- ① 68.27%: $P(-1 \\leq Z \\leq 1) \\approx 68.27\\%$로, 표준편차 1개 범위에 해당 (460과 540이 아님)\n- ② 90.00%: 대략 $P(-1.645 \\leq Z \\leq 1.645)$에 해당하는 확률로 부정확\n- ③ 95.00%: 반올림된 값처럼 보이지만 정확한 계산 결과가 아님\n- ⑤ 99.74%: $P(-3 \\leq Z \\leq 3) \\approx 99.74\\%$로, 표준편차 3개 범위에 해당 (범위가 너무 넓음)\n\n**[핵심 포인트]**\n정규분포 문제는 **표준화 공식** $Z = \\frac{X - \\mu}{\\sigma}$을 정확히 적용하고, 표준정규분포의 **대칭성**을 이용하여 $P(-a \\leq Z \\leq a) = 2 \\times P(0 \\leq Z \\leq a)$임을 기억해야 한다.",
