    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 표준화 과정이 핵심이다. \n- 확률변수 $X \\sim N(\\mu, \\sigma^2)$일 때, $Z = \\frac{X - \\mu}{\\sigma}$로 변환하면 $Z \\sim N(0, 1)$ (표준정규분포)\n- 표준정규분포의 대칭성: $P(Z \\leq 0) = 0.5$, $P(Z \\leq z) = 0.5 + P(0 \\leq Z \\leq z)$ (단, $z > 0$)\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n\n$X \\sim N(50, 10^2)$이므로 $\\mu = 50$, $\\sigma = 10$\n\n주어진 조건: $P(X \\leq k) = 0.9772$\n\n**2단계: 표준화**\n\n$X$를 표준정규분포 $Z$로 변환한다.\n\n$$Z = \\frac{X - 50}{10}$$\n\n따라서:\n$$P(X \\leq k) = P\\left(Z \\leq \\frac{k-50}{10}\\right) = 0.9772$$\n\n**3단계: 표준정규분포표 해석**\n\n표준정규분포의 성질에 의해:\n$$P(Z \\leq z) = 0.5 + P(0 \\leq Z \\leq z)$$ (단, $z > 0$)\n\n주어진 표에서 $P(0 \\leq Z \\leq 2) = 0.4772$이므로:\n$$P(Z \\leq 2) = 0.5 + 0.4772 = 0.9772$$\n\n**4단계: $k$ 값 구하기**\n\n위에서 $P(Z \\leq 2) = 0.9772$이고, $P\\left(Z \\leq \\frac{k-50}{10}\\right) = 0.9772$이므로:\n\n$$\\frac{k-50}{10} = 2$$\n\n$$k - 50 = 20$$\n\n$$k = 70$$\n\n**[정답 확인]**\n\n$k = 70$일 때, $P(X \\leq 70) = P(Z \\leq 2) = 0.9772$ ✓\n\n**[오답 분석]**\n\n- ① $k=60$: $\\frac{60-50}{10} = 1$이므로 $P(Z \\leq 1) = 0.5 + 0.3413 = 0.8413$ (오답)\n- ② $k=65$: $\\frac{65-50}{10} = 1.5$이므로 $P(Z \\leq 1.5) \\approx 0.9332$ (오답)\n- ④ $k=75$: $\\frac{75-50}{10} = 2.5$이므로 $P(Z \\leq 2.5) > 0.9772$ (오답)\n- ⑤ $k=80$: $\\frac{80-50}{10} = 3$이므로 $P(Z \\leq 3) \\approx 0.9987$ (오답)\n\n**[핵심 포인트]**\n\n1. 정규분포 문제는 반드시 **표준화**가 필수: $Z = \\frac{X - \\mu}{\\sigma}$\n2. 표준정규분포표에서 $P(Z \\leq z) = 0.5 + P(0 \\leq Z \\leq z)$임을 이용하여 주어진 확률값과 매칭하기",
