    "explanation": "**[핵심 개념]**\n\n이항분포를 정규분포로 근사할 때, $X \\sim B(n, p)$이면 근사적으로 $X \\sim N(\\mu, \\sigma^2)$를 따릅니다.\n- 평균: $\\mu = np$\n- 분산: $\\sigma^2 = np(1-p)$\n- 표준화: $Z = \\frac{X - \\mu}{\\sigma}$\n\n표준정규분포를 이용하여 확률을 구한다.\n\n**[풀이]**\n\n**1단계: 이항분포의 모수 계산**\n\n$X \\sim B(450, \\frac{1}{3})$이므로:\n- $n = 450$, $p = \\frac{1}{3}$\n- $\\mu = np = 450 \\times \\frac{1}{3} = 150$\n- $\\sigma^2 = np(1-p) = 450 \\times \\frac{1}{3} \\times \\frac{2}{3} = 450 \\times \\frac{2}{9} = 100$\n- $\\sigma = \\sqrt{100} = 10$\n\n**2단계: 확률 계산을 위해 표준화**\n\n$P(140 \\leq X \\leq 170)$을 구하기 위해 표준화한다.\n\n$$P(140 \\leq X \\leq 170) = P\\left(\\frac{140-150}{10} \\leq Z \\leq \\frac{170-150}{10}\\right)$$\n\n$$= P(-1 \\leq Z \\leq 2)$$\n\n**3단계: 표준정규분포표 이용**\n\n표준정규분포의 대칭성을 이용하면:\n\n$$P(-1 \\leq Z \\leq 2) = P(-1 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n\n$$= P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 2)$$\n\n주어진 표에서:\n- $P(0 \\leq Z \\leq 1) = 0.3413$\n- $P(0 \\leq Z \\leq 2) = 0.4772$\n\n따라서:\n$$P(-1 \\leq Z \\leq 2) = 0.3413 + 0.4772 = 0.8185$$\n\n**4단계: 최종 답 계산**\n\n문제에서 소수 넷째 자리까지 구한 값에 10000을 곱하라고 했으므로:\n\n$$0.8185 \\times 10000 = 8185$$\n\n**[정답 확인]**\n\n정규근사를 올바르게 적용하여 평균과 표준편차를 구하고, 표준화 후 표준정규분포표의 값을 정확히 더했으므로 답은 8185이다.\n\n**[오답 분석]**\n\n- **8100**: $P(-1 \\leq Z \\leq 2)$를 $P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 2) - 0.0072$ 등으로 잘못 계산\n- **8260**: $P(-2 \\leq Z \\leq 2)$를 계산한 경우 (경계값을 잘못 표준화)\n- **7745**: 표준편차를 잘못 계산하거나 표준화를 오류 있게 수행\n\n**[핵심 포인트]**\n\n1. 이항분포의 정규근사에서 $\\mu = np$, $\\sigma = \\sqrt{np(1-p)}$를 정확히 계산하는 것이 필수이다.\n2. 표준정규분포의 대칭성 ($P(-z \\leq Z \\leq 0) = P(0 \\leq Z \\leq z)$)을 활용하여 표를 효율적으로 읽어야 한다.",
