    "_type": "normal_dist",
    "type": "정규분포",
    "problem": "확률변수 $X$가 이항분포 $B(1200, \\frac{1}{4})$를 따를 때, 정규근사를 이용하여 $P(X \\leq 285)$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
    "answerType": "short",
    "choices": null,
    "answer": 1587,
    "explanation": "**[핵심 개념]**\n\n이항분포의 정규근사(정규분포로의 근사)를 이용하는 문제이다.\n\n이항분포 $B(n, p)$를 따르는 확률변수 $X$는 $n$이 충분히 클 때, 평균 $\\mu = np$, 분산 $\\sigma^2 = np(1-p)$인 정규분포 $N(np, np(1-p))$로 근사된다.\n\n표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$\n\n표준정규분포의 성질: $P(Z \\leq z) = 0.5 + P(0 \\leq Z \\leq z)$ (단, $z > 0$)\n\n**[풀이]**\n\n**1단계: 이항분포의 모수 확인**\n\n$X \\sim B(1200, \\frac{1}{4})$이므로\n- $n = 1200$\n- $p = \\frac{1}{4}$\n- $q = 1 - p = \\frac{3}{4}$\n\n**2단계: 평균과 표준편차 계산**\n\n$$\\mu = np = 1200 \\times \\frac{1}{4} = 300$$\n\n$$\\sigma^2 = np(1-p) = 1200 \\times \\frac{1}{4} \\times \\frac{3}{4} = 1200 \\times \\frac{3}{16} = 225$$\n\n$$\\sigma = \\sqrt{225} = 15$$\n\n**3단계: 정규근사를 이용한 표준화**\n\n$P(X \\leq 285)$를 구하기 위해 표준화한다.\n\n$$Z = \\frac{X - \\mu}{\\sigma} = \\frac{285 - 300}{15} = \\frac{-15}{15} = -1$$\n\n따라서:\n$$P(X \\leq 285) = P(Z \\leq -1)$$\n\n**4단계: 표준정규분포표를 이용한 확률 계산**\n\n표준정규분포의 대칭성에 의해:\n$$P(Z \\leq -1) = P(Z \\geq 1) = 1 - P(Z \\leq 1)$$\n\n$$P(Z \\leq 1) = 0.5 + P(0 \\leq Z \\leq 1) = 0.5 + 0.3413 = 0.8413$$\n\n따라서:\n$$P(Z \\leq -1) = 1 - 0.8413 = 0.1587$$\n\n**5단계: 최종 답 계산**\n\n문제에서 10000을 곱하여 정수로 답하라고 했으므로:\n\n$$0.1587 \\times 10000 = 1587$$\n\n**[정답 확인]**\n\n평균 300에서 표준편차 1개 아래인 285까지의 누적확률은 약 15.87%로, 이는 표준정규분포에서 $Z = -1$에 해당하는 확률과 정확히 일치한다.\n\n**[오답 분석]**\n\n- **8413**: $P(Z \\leq 1) = 0.8413$을 그대로 10000배한 경우 (부호를 반대로 처리)\n- **3413**: $P(0 \\leq Z \\leq 1) = 0.3413$만을 10000배한 경우 (0.5를 더하지 않음)\n- **6587**: $1 - 0.3413 = 0.6587$을 10000배한 경우 (표준정규분포 성질 오류)\n\n**[핵심 포인트]**\n\n1. 이항분포의 정규근사에서 평균과 표준편차를 정확히 계산하고, 표준화 공식을 올바르게 적용해야 한다.\n\n2. 표준정규분포표가 $P(0 \\leq Z \\leq a)$ 형태로 주어질 때, 음수 구간은 대칭성을 이용하여 $P(Z \\leq -a) = 1 - P(Z \\leq a)$로 변환해야 한다.",
