    "_type": "normal_dist",
    "type": "정규분포",
    "problem": "독립인 확률변수 $X \\sim N(100, 6^2)$, $Y \\sim N(80, 8^2)$에 대해, $W = X - Y$일 때 $P(W \\geq 30)$의 값은?\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$]",
    "answerType": "choice",
    "choices": [
      "① 0.0228",
      "② 0.1587",
      "③ 0.3413",
      "④ 0.5",
      "⑤ 0.8413"
    ],
    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n독립인 정규분포를 따르는 두 확률변수의 일차결합도 정규분포를 따릅니다. $X \\sim N(\\mu_1, \\sigma_1^2)$, $Y \\sim N(\\mu_2, \\sigma_2^2)$이 독립일 때, $W = X - Y$는 $N(\\mu_1 - \\mu_2, \\sigma_1^2 + \\sigma_2^2)$를 따릅니다. 이를 표준화하여 표준정규분포표를 이용해 확률을 구한다.\n\n**[풀이]**\n\n**Step 1: W의 분포 구하기**\n\n$X \\sim N(100, 6^2)$, $Y \\sim N(80, 8^2)$이고 X, Y가 독립이므로,\n\n$$W = X - Y \\sim N(E[W], Var(W))$$\n\n여기서:\n- $E[W] = E[X] - E[Y] = 100 - 80 = 20$\n- $Var(W) = Var(X) + Var(Y) = 6^2 + 8^2 = 36 + 64 = 100$\n- $\\sigma_W = \\sqrt{100} = 10$\n\n따라서 $W \\sim N(20, 10^2)$\n\n**Step 2: 표준화하기**\n\n$P(W \\geq 30)$을 구하기 위해 표준화한다.\n\n$$Z = \\frac{W - 20}{10}$$\n\n$W = 30$일 때:\n$$Z = \\frac{30 - 20}{10} = \\frac{10}{10} = 1$$\n\n**Step 3: 표준정규분포표 이용**\n\n$$P(W \\geq 30) = P(Z \\geq 1)$$\n\n표준정규분포의 대칭성을 이용하면:\n$$P(Z \\geq 1) = P(Z \\leq -1) = 0.5 - P(-1 \\leq Z \\leq 0)$$\n\n대칭성에 의해 $P(-1 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 1) = 0.3413$\n\n따라서:\n$$P(Z \\geq 1) = 0.5 - 0.3413 = 0.1587$$\n\n**[정답 확인]**\n\n$W$를 표준화하면 $Z = 1$이 되고, 표준정규분포표에서 $P(Z \\geq 1) = 0.5 - 0.3413 = 0.1587$이므로 정답은 ②이다.\n\n**[오답 분석]**\n\n① 0.0228: $P(Z \\geq 2) \\approx 0.0228$로, 표준화 값을 잘못 계산했을 때의 값\n\n③ 0.3413: 표준정규분포표에서 $P(0 \\leq Z \\leq 1)$의 값으로, $P(Z \\geq 1)$과 혼동\n\n④ 0.5: 표준정규분포의 중심값이지만, 이 문제에서는 무관\n\n⑤ 0.8413: $P(Z \\leq 1) = 0.5 + 0.3413 = 0.8413$으로, $P(W \\geq 30)$이 아닌 $P(W \\leq 30)$을 구한 경우\n\n**[핵심 포인트]**\n\n- 독립인 정규분포의 일차결합은 분산이 **더해진다** ($Var(X-Y) = Var(X) + Var(Y)$)\n- 표준화 후 표준정규분포의 **대칭성**을 이용하여 $P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$ (단, $a > 0$)",
