    "problem": "어느 시험의 점수 $X$가 정규분포 $N(60, 10^2)$을 따른다. 상위 $15.87\\%$ 이내인 학생에게 A등급을 주고, 하위 $2.28\\%$ 이하인 학생에게 F등급을 줄 때, A등급의 최저 점수와 F등급의 최고 점수의 차는?\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
