    "explanation": "**[핵심 개념]**\n\n정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수 $X$를 표준화하면 표준정규분포 $N(0,1)$을 따르는 확률변수 $Z = \\frac{X-\\mu}{\\sigma}$가 된다. 표준정규분포의 대칭성을 이용하여 $P(Z \\leq z) = 0.5 + P(0 \\leq Z \\leq z)$ (단, $z > 0$)이다.\n\n**[풀이]**\n\n**Step 1: A등급의 최저 점수 구하기**\n\n상위 15.87% 이내라는 것은 $P(X \\geq x_A) = 0.1587$을 의미한다.\n\n이를 표준화하면:\n$$P(Z \\geq z_A) = 0.1587$$\n\n표준정규분포의 대칭성에 의해:\n$$P(Z \\leq z_A) = 1 - 0.1587 = 0.8413$$\n\n따라서:\n$$P(0 \\leq Z \\leq z_A) = 0.8413 - 0.5 = 0.3413$$\n\n표준정규분포표에서 $P(0 \\leq Z \\leq 1) = 0.3413$이므로 $z_A = 1$\n\n표준화 공식을 역으로 적용하면:\n$$z_A = \\frac{x_A - 60}{10} = 1$$\n$$x_A = 60 + 10 = 70$$\n\n**Step 2: F등급의 최고 점수 구하기**\n\n하위 2.28% 이하라는 것은 $P(X \\leq x_F) = 0.0228$을 의미한다.\n\n이를 표준화하면:\n$$P(Z \\leq z_F) = 0.0228$$\n\n표준정규분포의 대칭성에 의해:\n$$P(Z \\geq -z_F) = 0.0228$$\n$$P(Z \\leq -z_F) = 1 - 0.0228 = 0.9772$$\n\n따라서:\n$$P(0 \\leq Z \\leq -z_F) = 0.9772 - 0.5 = 0.4772$$\n\n표준정규분포표에서 $P(0 \\leq Z \\leq 2) = 0.4772$이므로 $-z_F = 2$, 즉 $z_F = -2$\n\n표준화 공식을 역으로 적용하면:\n$$z_F = \\frac{x_F - 60}{10} = -2$$\n$$x_F = 60 - 20 = 40$$\n\n**Step 3: 두 점수의 차 계산**\n\n$$x_A - x_F = 70 - 40 = 30$$\n\n**[정답 확인]**\n\nA등급 최저 점수(70점)와 F등급 최고 점수(40점)의 차는 30점이므로 정답은 **③**이다.\n\n**[오답 분석]**\n\n- ① 20: F등급 최고 점수를 50점으로 잘못 계산한 경우 ($z_F = -1$로 오인)\n- ② 25: 두 점수의 차를 구하는 과정에서 계산 실수가 있는 경우\n- ④ 35: A등급 최저 점수나 F등급 최고 점수 중 하나를 잘못 구한 경우\n- ⑤ 40: A등급 최저 점수를 75점으로 계산하거나 F등급 최고 점수를 35점으로 잘못 구한 경우\n\n**[핵심 포인트]**\n\n1. 상위 15.87%는 $P(Z \\geq 1) = 0.1587$이고, 하위 2.28%는 $P(Z \\leq -2) = 0.0228$임을 표준정규분포표에서 읽어야 한다.\n2. 표준화 공식 $Z = \\frac{X - \\mu}{\\sigma}$를 양방향으로 자유롭게 사용할 수 있어야 한다.",
