    "explanation": "**[핵심 개념]**\n정규분포 $X \\sim N(\\mu, \\sigma^2)$를 표준정규분포 $Z \\sim N(0, 1)$으로 변환하는 표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$\n\n표준정규분포의 대칭성을 이용하면:\n- $P(Z \\leq -a) = P(Z \\geq a) = 0.5 - P(0 \\leq Z \\leq a)$\n- $P(Z \\leq a) = 0.5 + P(0 \\leq Z \\leq a)$ (단, $a > 0$)\n\n**[풀이]**\n\n**Step 1: 주어진 확률을 표준정규분포로 해석**\n\n$P(X \\leq 20) = 0.1587$에서, 표준정규분포 대칭성을 이용하면:\n$$0.1587 = 0.5 - 0.3413 = P(Z \\leq -1)$$\n\n따라서 $P\\left(\\frac{X-\\mu}{\\sigma} \\leq -1\\right) = P(X \\leq 20)$이므로:\n$$\\frac{20 - \\mu}{\\sigma} = -1 \\quad \\cdots (1)$$\n\n**Step 2: 두 번째 조건 해석**\n\n$P(X \\leq 40) = 0.8413$에서:\n$$0.8413 = 0.5 + 0.3413 = P(Z \\leq 1)$$\n\n따라서:\n$$\\frac{40 - \\mu}{\\sigma} = 1 \\quad \\cdots (2)$$\n\n**Step 3: 연립방정식 풀이**\n\n식 (1)에서: $20 - \\mu = -\\sigma$ → $\\mu - \\sigma = 20$ $\\cdots (1')$\n\n식 (2)에서: $40 - \\mu = \\sigma$ $\\cdots (2')$\n\n식 (1')과 (2')을 더하면:\n$$\\mu - \\sigma + 40 - \\mu = 20 + \\sigma$$\n$$40 - \\sigma = 20 + \\sigma$$\n$$20 = 2\\sigma$$\n$$\\sigma = 10$$\n\n식 (2')에 대입:\n$$40 - \\mu = 10$$\n$$\\mu = 30$$\n\n**[정답 확인]**\n$\\mu = 30, \\sigma = 10$일 때, $P(X \\leq 20) = P(Z \\leq -1) = 0.1587$과 $P(X \\leq 40) = P(Z \\leq 1) = 0.8413$이 모두 만족되므로 정답은 **③번**이다.\n\n**[오답 분석]**\n- ① $\\mu = 25, \\sigma = 5$: $P(X \\leq 20) = P(Z \\leq -1) = 0.1587$ ✓ 하지만 $P(X \\leq 40) = P(Z \\leq 3)$ (표에 없음)\n- ② $\\mu = 30, \\sigma = 5$: $P(X \\leq 20) = P(Z \\leq -2) = 0.0228$ ✗\n- ④ $\\mu = 35, \\sigma = 5$: $P(X \\leq 20) = P(Z \\leq -3)$ (표에 없음)\n- ⑤ $\\mu = 40, \\sigma = 10$: $P(X \\leq 20) = P(Z \\leq -2) = 0.0228$ ✗\n\n**[핵심 포인트]**\n1. 표준화 공식 $Z = \\frac{X-\\mu}{\\sigma}$를 이용하여 두 조건으로부터 $\\mu$와 $\\sigma$에 대한 연립방정식을 세우기\n2. 표준정규분포표에서 $P(Z \\leq a) = 0.5 \\pm P(0 \\leq Z \\leq |a|)$의 관계식을 정확히 파악하기",
