    "explanation": "**[핵심 개념]**\n정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수는 표준화를 통해 표준정규분포 $N(0,1)$로 변환할 수 있다. 확률변수 $X \\sim N(\\mu, \\sigma^2)$일 때, 표준화 공식은 $Z = \\frac{X - \\mu}{\\sigma}$이며, 표준정규분포의 대칭성을 이용하여 $P(Z \\geq z) = P(Z \\leq -z) = 0.5 - P(0 \\leq Z \\leq z)$이다.\n\n**[풀이]**\n\n**Step 1: $P(X \\geq 46)$ 계산**\n\n$X \\sim N(40, 4^2)$이므로 $\\mu = 40$, $\\sigma = 4$이다.\n\n표준화하면:\n$$Z_1 = \\frac{X - 40}{4} = \\frac{46 - 40}{4} = \\frac{6}{4} = 1.5$$\n\n따라서:\n$$P(X \\geq 46) = P(Z \\geq 1.5)$$\n\n표준정규분포의 성질에 의해:\n$$P(Z \\geq 1.5) = 0.5 - P(0 \\leq Z \\leq 1.5) = 0.5 - 0.4332 = 0.0668$$\n\n**Step 2: $P(Y \\leq 32)$ 계산**\n\n$Y \\sim N(40, 4^2)$이므로 $\\mu = 40$, $\\sigma = 4$이다.\n\n표준화하면:\n$$Z_2 = \\frac{Y - 40}{4} = \\frac{32 - 40}{4} = \\frac{-8}{4} = -2$$\n\n따라서:\n$$P(Y \\leq 32) = P(Z \\leq -2)$$\n\n표준정규분포의 대칭성에 의해:\n$$P(Z \\leq -2) = P(Z \\geq 2) = 0.5 - P(0 \\leq Z \\leq 2) = 0.5 - 0.4772 = 0.0228$$\n\n**Step 3: 두 확률의 합 계산**\n\n$X$와 $Y$가 독립이므로:\n$$P(X \\geq 46) + P(Y \\leq 32) = 0.0668 + 0.0228 = 0.0896$$\n\n**[정답 확인]**\n두 독립 사건의 확률을 각각 표준화하여 구한 후 더하면 0.0896이 되므로 ④번이 정답이다.\n\n**[오답 분석]**\n- ① 0.0210: $P(Y \\leq 32)$만 계산한 경우 (계산 오류)\n- ② 0.0456: 한 가지 확률만 계산하거나 중간 과정에서 실수한 경우\n- ③ 0.0625: $(0.25)^2$ 같은 잘못된 곱셈을 수행한 경우\n- ⑤ 0.1131: 표준정규분포표 값을 잘못 읽거나 계산 오류 발생\n\n**[핵심 포인트]**\n1. 표준화할 때 정확한 계산이 중요하다: $Z = \\frac{X - \\mu}{\\sigma}$에서 부호와 수치를 정확히 해야 한다.\n2. 표준정규분포의 대칭성: $P(Z \\leq -z) = P(Z \\geq z) = 0.5 - P(0 \\leq Z \\leq z)$를 올바르게 적용해야 한다.",
