    "answer": 11,
    "explanation": "**[핵심 개념]**\n\n표본평균의 분포는 정규분포를 따르는 모집단에서 추출한 표본의 평균도 정규분포를 따른다는 성질을 이용한다.\n\n독립인 정규분포를 따르는 확률변수들의 선형결합도 정규분포를 따르며, 다음이 성립한다:\n- 기댓값(평균)의 성질: $E(aX + bY) = aE(X) + bE(Y)$\n- 분산의 성질 (독립일 때): $Var(aX + bY) = a^2Var(X) + b^2Var(Y)$\n\n표본평균 $\\bar{X}$의 분포: $\\bar{X} \\sim N(\\mu, \\frac{\\sigma^2}{n})$\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n\n각 확률변수는 $X_i \\sim N(10, 2^2)$를 따르므로:\n- $E(X_i) = 10$\n- $Var(X_i) = 2^2 = 4$\n\n**Step 2: 표본평균의 기댓값 구하기**\n\n$$E(\\bar{X}) = E\\left(\\frac{X_1+X_2+X_3+X_4}{4}\\right)$$\n\n기댓값의 선형성을 이용하면:\n\n$$E(\\bar{X}) = \\frac{1}{4}[E(X_1)+E(X_2)+E(X_3)+E(X_4)]$$\n\n$$E(\\bar{X}) = \\frac{1}{4}(10+10+10+10) = \\frac{40}{4} = 10$$\n\n따라서 $a = 10$\n\n**Step 3: 표본평균의 분산 구하기**\n\n$$Var(\\bar{X}) = Var\\left(\\frac{X_1+X_2+X_3+X_4}{4}\\right)$$\n\n$X_1, X_2, X_3, X_4$가 독립이므로:\n\n$$Var(\\bar{X}) = \\frac{1}{16}[Var(X_1)+Var(X_2)+Var(X_3)+Var(X_4)]$$\n\n$$Var(\\bar{X}) = \\frac{1}{16}(4+4+4+4) = \\frac{16}{16} = 1$$\n\n따라서 $b = 1$\n\n**Step 4: 최종 답 계산**\n\n$$a + b = 10 + 1 = 11$$\n\n**[정답 확인]**\n\n표본평균 $\\bar{X} \\sim N(10, 1)$이므로 $a=10, b=1$이고, $a+b=11$이 정답이다.\n\n**[오답 분석]**\n\n이 문제는 단답형이므로 선택지 분석은 생략되지만, 흔한 오류는:\n- $b$를 분산이 아닌 표준편차로 착각하여 $b=1$이 아닌 $\\sqrt{1}=1$로 계산 (결과적으로 같음)\n- 분산 계산 시 분모를 $n$이 아닌 $n^2$으로 잘못 계산하여 $b=\\frac{1}{4}$로 구함 → $a+b=10.25$ (오답)\n\n**[핵심 포인트]**\n\n표본평균의 분산은 $\\frac{\\sigma^2}{n}$이며, 여기서 $n=4$일 때 분산이 $\\frac{4}{4}=1$로 줄어든다는 점을 기억할 것. 표본의 크기가 클수록 표본평균의 분산은 작아진다.",
