    "type": "정규분포",
    "problem": "확률변수 $X \\sim N(\\mu, \\sigma^2)$에 대해 $P(\\mu - 2\\sigma \\leq X \\leq \\mu + \\sigma) = a$이다. $a$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$]",
    "answerType": "short",
    "choices": null,
    "answer": 8185,
    "explanation": "**[핵심 개념]**\n\n정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수 $X$는 표준화를 통해 표준정규분포 $N(0,1)$을 따르는 확률변수 $Z = \\frac{X-\\mu}{\\sigma}$로 변환할 수 있다. 표준정규분포는 평균을 중심으로 대칭이므로 $P(0 \\leq Z \\leq z) = P(-z \\leq Z \\leq 0)$이다. 또한 $P(-z \\leq Z \\leq z) = 2P(0 \\leq Z \\leq z)$이다.\n\n**[풀이]**\n\n주어진 조건: $X \\sim N(\\mu, \\sigma^2)$이고 $P(\\mu - 2\\sigma \\leq X \\leq \\mu + \\sigma) = a$\n\n**1단계: 확률을 표준정규분포로 변환**\n\n$X$를 표준화하면 $Z = \\frac{X-\\mu}{\\sigma}$이다.\n\n- $X = \\mu - 2\\sigma$일 때: $Z = \\frac{\\mu - 2\\sigma - \\mu}{\\sigma} = -2$\n- $X = \\mu + \\sigma$일 때: $Z = \\frac{\\mu + \\sigma - \\mu}{\\sigma} = 1$\n\n따라서 $P(\\mu - 2\\sigma \\leq X \\leq \\mu + \\sigma) = P(-2 \\leq Z \\leq 1)$\n\n**2단계: 표준정규분포 적분 구간 분해**\n\n$P(-2 \\leq Z \\leq 1)$을 두 부분으로 나눕니다:\n\n$$P(-2 \\leq Z \\leq 1) = P(-2 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1)$$\n\n**3단계: 대칭성을 이용하여 계산**\n\n표준정규분포의 대칭성에 의해:\n$$P(-2 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 2)$$\n\n주어진 표에서 $P(0 \\leq Z \\leq 2) = 0.4772$, $P(0 \\leq Z \\leq 1) = 0.3413$\n\n따라서:\n$$a = P(-2 \\leq Z \\leq 1) = 0.4772 + 0.3413 = 0.8185$$\n\n**4단계: 최종 답 계산**\n\n문제에서 요구하는 답은 $a \\times 10000 = 0.8185 \\times 10000 = 8185$\n\n**[정답 확인]**\n\n표준정규분포표의 값을 정확히 적용하여 $P(-2 \\leq Z \\leq 0) = 0.4772$, $P(0 \\leq Z \\leq 1) = 0.3413$을 더한 결과 $a = 0.8185$이므로, 이에 10000을 곱한 8185가 정답이다.\n\n**[오답 분석]**\n\n- **4772**: $P(0 \\leq Z \\leq 2)$의 값만 10000을 곱한 경우\n- **3413**: $P(0 \\leq Z \\leq 1)$의 값만 10000을 곱한 경우\n- **8185 외의 다른 값**: 표준화 과정에서 실수하거나 대칭성을 적용하지 않은 경우\n\n**[핵심 포인트]**\n\n1. 정규분포 문제는 반드시 표준화($Z = \\frac{X-\\mu}{\\sigma}$)를 통해 표준정규분포로 변환해야 한다.\n2. 표준정규분포의 대칭성을 이용하여 $P(-a \\leq Z \\leq 0) = P(0 \\leq Z \\leq a)$임을 활용하면 계산이 간편한다.",
