    "problem": "확률변수 $X \\sim N(50, 10^2)$이고, $Y = 2X + 10$이다. $P(Y \\leq 130)$의 값을 소수 넷째 자리까지 구하면? (답에 10000을 곱하여 정수로 답하시오.)\n\n[표준정규분포표: $P(0 \\leq Z \\leq 1) = 0.3413$]",
    "answerType": "short",
    "choices": null,
    "answer": 8413,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 확률변수의 일차변환과 표준화를 이용하여 확률을 구하는 문제이다.\n- 정규분포 $N(\\mu, \\sigma^2)$를 따르는 $X$에 대해 $Y = aX + b$일 때, $Y \\sim N(a\\mu + b, a^2\\sigma^2)$\n- 표준정규분포로 변환: $Z = \\frac{X - \\mu}{\\sigma} \\sim N(0, 1)$\n- 표준정규분포의 대칭성: $P(Z \\leq 0) = 0.5$, $P(0 \\leq Z \\leq z) = P(-z \\leq Z \\leq 0)$\n\n**[풀이]**\n\n**1단계: Y의 평균과 분산 구하기**\n\n$X \\sim N(50, 10^2)$이므로 $E(X) = 50$, $\\text{Var}(X) = 100$\n\n$Y = 2X + 10$이므로:\n- $E(Y) = 2E(X) + 10 = 2(50) + 10 = 110$\n- $\\text{Var}(Y) = 4\\text{Var}(X) = 4(100) = 400$\n- 따라서 $Y \\sim N(110, 400)$, 즉 $Y \\sim N(110, 20^2)$\n\n**2단계: $P(Y \\leq 130)$을 구하기**\n\n$Y$를 표준화한다:\n$$Z = \\frac{Y - 110}{20}$$\n\n$P(Y \\leq 130)$을 $Z$로 변환하면:\n$$P(Y \\leq 130) = P\\left(\\frac{Y - 110}{20} \\leq \\frac{130 - 110}{20}\\right) = P(Z \\leq 1)$$\n\n**3단계: 표준정규분포표 이용**\n\n표준정규분포의 대칭성을 이용하면:\n$$P(Z \\leq 1) = P(Z \\leq 0) + P(0 \\leq Z \\leq 1) = 0.5 + 0.3413 = 0.8413$$\n\n**4단계: 최종 답 계산**\n\n소수 넷째 자리까지는 $0.8413$\n\n문제에서 답에 10000을 곱하여 정수로 답하라고 했으므로:\n$$0.8413 \\times 10000 = 8413$$\n\n**[정답 확인]**\n$Y$의 표준편차가 20이고, $P(Y \\leq 130) = P(Z \\leq 1) = 0.5 + 0.3413 = 0.8413$이므로 10000을 곱하면 8413이다.\n\n**[오답 분석]**\n- **3413**: $P(0 \\leq Z \\leq 1)$의 값만 10000을 곱한 경우 (표준정규분포 좌측 절반을 더하지 않음)\n- **5000**: $P(Z \\leq 0) = 0.5$만 10000을 곱한 경우\n- **6587**: 계산 오류 또는 $P(Z > 1)$을 구한 경우\n\n**[핵심 포인트]**\n1. 정규분포의 일차변환을 정확히 적용하여 $Y$의 평균과 표준편차를 구하는 것이 중요하다.\n2. 표준정규분포표는 $P(0 \\leq Z \\leq z)$ 형태이므로, $P(Z \\leq 1) = 0.5 + P(0 \\leq Z \\leq 1)$로 계산해야 한다.",
