    "problem": "어느 공장에서 생산되는 제품의 무게는 정규분포 $N(m, 4^2)$을 따른다고 한다. 이 공장에서 생산된 제품 중 64개를 임의추출하여 표본평균을 구했더니 $\\bar{X} = 50$이었다. 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구하면? (단, $z_{0.025} = 1.96$)",
    "answerType": "choice",
    "choices": [
      "① 49.02 ≤ m ≤ 50.98",
      "② 49.51 ≤ m ≤ 50.49",
      "③ 48.04 ≤ m ≤ 51.96",
      "④ 49.18 ≤ m ≤ 50.82",
      "⑤ 49.75 ≤ m ≤ 50.25"
    ],
    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n모평균의 신뢰구간은 표본평균을 중심으로 오차한계만큼 양쪽으로 벌린 구간이다. 모표준편차가 알려진 경우, 신뢰도 95%에서 모평균 $m$의 신뢰구간은 다음 공식으로 구한다:\n\n$$\\bar{X} - z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{X} + z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n여기서 $z_{\\alpha/2}$는 신뢰도에 해당하는 표준정규분포의 임계값이다.\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- 모집단: $N(m, 4^2)$ (모표준편차 $\\sigma = 4$)\n- 표본크기: $n = 64$\n- 표본평균: $\\bar{X} = 50$\n- 신뢰도: 95% → $z_{0.025} = 1.96$\n\n**Step 2: 표준오차 계산**\n\n표준오차는 표본평균의 표준편차이다:\n\n$$SE = \\frac{\\sigma}{\\sqrt{n}} = \\frac{4}{\\sqrt{64}} = \\frac{4}{8} = 0.5$$\n\n**Step 3: 오차한계 계산**\n\n오차한계(margin of error)는:\n\n$$E = z_{0.025} \\times SE = 1.96 \\times 0.5 = 0.98$$\n\n**Step 4: 신뢰구간 계산**\n\n$$\\bar{X} - E \\leq m \\leq \\bar{X} + E$$\n\n$$50 - 0.98 \\leq m \\leq 50 + 0.98$$\n\n$$49.02 \\leq m \\leq 50.98$$\n\n**[정답 확인]**\n\n계산한 신뢰구간 $49.02 \\leq m \\leq 50.98$이 선지 ①과 정확히 일치한다.\n\n**[오답 분석]**\n\n- **②번 (49.51 ≤ m ≤ 50.49)**: 오차한계를 0.49로 계산했을 가능성. $1.96 \\times 0.25 = 0.49$인데, 표준오차를 잘못 구한 경우이다.\n\n- **③번 (48.04 ≤ m ≤ 51.96)**: $z$값과 $\\sigma$를 곱한 후 표본크기로 나누지 않은 경우. $1.96 \\times 4 = 7.84$로 오차한계를 계산한 오류이다.\n\n- **④번 (49.18 ≤ m ≤ 50.82)**: 오차한계를 0.82로 계산한 경우. 표준오차를 0.42 정도로 잘못 구한 경우로 보이다.\n\n- **⑤번 (49.75 ≤ m ≤ 50.25)**: 오차한계를 0.25로 계산한 경우. 표본크기의 제곱근을 사용하지 않거나 다른 오류를 범한 경우이다.\n\n**[핵심 포인트]**\n\n1. 신뢰구간 = 표본평균 ± (임계값 × 표준오차)에서 **표준오차는 $\\frac{\\sigma}{\\sqrt{n}}$** 임을 정확히 적용해야 한다.\n\n2. 신뢰도 95%일 때 $z_{0.025} = 1.96$이라는 값은 자주 출제되므로 반드시 기억해야 한다.",
