    "explanation": "**[핵심 개념]**\n\n모집단이 정규분포 $N(m, \\sigma^2)$을 따를 때, 표본평균 $\\bar{X}$의 분포는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다. 신뢰도 $100(1-\\alpha)\\%$에 대한 모평균 $m$의 신뢰구간은 다음 공식으로 구한다:\n\n$$\\bar{X} - z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{X} + z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n여기서 $z_{\\alpha/2}$는 표준정규분포의 상위 $\\alpha/2$에 해당하는 값이다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 6^2)$ → 모표준편차 $\\sigma = 6$\n- 표본크기: $n = 36$\n- 표본평균: $\\bar{X} = 72$\n- 신뢰도: 99% → $1-\\alpha = 0.99$ → $\\alpha = 0.01$ → $\\alpha/2 = 0.005$\n- 주어진 값: $z_{0.005} = 2.58$\n\n**2단계: 표본평균의 표준오차 계산**\n\n$$SE = \\frac{\\sigma}{\\sqrt{n}} = \\frac{6}{\\sqrt{36}} = \\frac{6}{6} = 1$$\n\n**3단계: 오차한계 계산**\n\n$$E = z_{0.005} \\cdot SE = 2.58 \\times 1 = 2.58$$\n\n**4단계: 신뢰구간 계산**\n\n신뢰구간의 하한:\n$$\\bar{X} - E = 72 - 2.58 = 69.42$$\n\n신뢰구간의 상한:\n$$\\bar{X} + E = 72 + 2.58 = 74.58$$\n\n따라서 모평균 $m$의 신뢰도 99% 신뢰구간은:\n$$69.42 \\leq m \\leq 74.58$$\n\n**[정답 확인]**\n\n표준오차가 1로 정확히 계산되고, 오차한계 $2.58 \\times 1 = 2.58$을 표본평균 72에서 더하고 빼면 정확히 69.42 ≤ m ≤ 74.58이 나오므로 ①이 정답이다.\n\n**[오답 분석]**\n\n- **②번**: 신뢰도 95%일 때의 $z_{0.025} = 1.96$을 사용한 경우 ($72 \\pm 1.96 \\times 1 = 70.04 \\sim 73.96$)\n- **③번**: 오차한계를 과소계산한 경우 (약 $72 \\pm 0.86$)\n- **④번**: 신뢰도 95%에 해당하는 신뢰구간 ($z_{0.025} = 1.96$ 사용)\n- **⑤번**: $z$ 값을 1.36 정도로 잘못 사용한 경우\n\n**[핵심 포인트]**\n\n신뢰도 99%일 때는 **반드시 $z_{0.005} = 2.58$**을 사용해야 하며, 표본평균의 표준오차는 $\\frac{\\sigma}{\\sqrt{n}}$로 계산된다. 이 문제에서는 표준오차가 정확히 1이 되어 계산이 간단해진다.",
