    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 표본평균의 신뢰구간을 구하는 문제이다.\n\n모집단이 $N(m, \\sigma^2)$을 따를 때, 표본평균 $\\bar{X}$는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n\n모평균 $m$에 대한 신뢰도 $1-\\alpha$인 신뢰구간은:\n$$\\bar{X} - z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{X} + z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 3^2)$ (모표준편차 $\\sigma = 3$)\n- 표본크기: $n = 9$\n- 표본평균: $\\bar{X} = 20$\n- 신뢰도: 99% → $\\alpha = 0.01$ → $\\alpha/2 = 0.005$\n- $z_{0.005} = 2.58$\n\n**2단계: 표준오차(표본평균의 표준편차) 계산**\n\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{3}{\\sqrt{9}} = \\frac{3}{3} = 1$$\n\n**3단계: 오차한계 계산**\n\n$$E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2.58 \\times 1 = 2.58$$\n\n**4단계: 신뢰구간 계산**\n\n$$\\bar{X} - E \\leq m \\leq \\bar{X} + E$$\n\n$$20 - 2.58 \\leq m \\leq 20 + 2.58$$\n\n$$17.42 \\leq m \\leq 22.58$$\n\n**[정답 확인]**\n\n신뢰도 99%에서 오차한계가 2.58이므로, 신뢰구간은 $[17.42, 22.58]$이 맞다.\n\n**[오답 분석]**\n\n- **②번** ($18.14 \\leq m \\leq 21.86$): 오차한계가 약 1.86으로, $z_{0.025} = 1.96$ 근처 신뢰도 95%에 해당\n- **③번** ($19.14 \\leq m \\leq 20.86$): 오차한계가 0.86으로 지나치게 작음\n- **④번** ($17.84 \\leq m \\leq 22.16$): 오차한계가 2.16으로, 계산 오류\n- **⑤번** ($18.42 \\leq m \\leq 21.58$): 오차한계가 1.58으로, 신뢰도 95% 수준\n\n**[핵심 포인트]**\n\n신뢰도 99%일 때 $z_{0.005} = 2.58$을 사용하며, 표본표준편차는 모표준편차 $\\sigma = 3$을 사용한다. 표본크기 $n = 9$에서 표준오차는 $\\frac{\\sigma}{\\sqrt{n}} = 1$이 되어 계산이 단순화된다.",
