    "explanation": "**[핵심 개념]**\n모집단이 정규분포를 따를 때, 표본평균의 신뢰구간은 다음과 같이 구성된다.\n- 표본평균 $\\bar{X}$는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n- 신뢰도 95%인 신뢰구간: $\\bar{X} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n- 여기서 **오차한계(margin of error)** = $z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n신뢰도 95%일 때 $\\alpha = 0.05$이므로 $z_{\\alpha/2} = z_{0.025} = 1.96$이다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 12^2)$ → 표준편차 $\\sigma = 12$\n- 표본크기: $n = 144$\n- 표본평균: $\\bar{X} = 100$\n- 신뢰도: 95% → $z_{0.025} = 1.96$\n\n**2단계: 표본평균의 표준편차(표준오차) 계산**\n\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{12}{\\sqrt{144}} = \\frac{12}{12} = 1$$\n\n**3단계: 오차한계 계산**\n\n$$\\text{오차한계} = z_{0.025} \\times \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\times 1 = 1.96$$\n\n**4단계: 신뢰구간 확인 (검증)**\n\n신뢰구간 = $100 \\pm 1.96$ = $[98.04, 101.96]$\n\n이는 모평균 $m$이 95% 확률로 이 구간에 포함된다는 의미이다.\n\n**[정답 확인]**\n오차한계 = $z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\times 1 = 1.96$이므로 정답은 **③번**이다.\n\n**[오답 분석]**\n- ① 0.98: $1.96 \\div 2 = 0.98$ (오차한계를 반으로 나눔, 오류)\n- ② 1.29: 특정 근거 없이 임의의 값\n- ④ 2.58: $z_{0.005}$ 값으로 신뢰도 99%일 때의 값 (신뢰도 혼동)\n- ⑤ 3.92: $1.96 \\times 2 = 3.92$ (신뢰구간의 전체 폭을 계산, 오차한계는 한쪽)\n\n**[핵심 포인트]**\n1. **오차한계는 $z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$** 이고, 신뢰구간의 절반이다.\n2. 표본크기가 커질수록(√n이 커질수록) 오차한계는 작아지므로, $\\sqrt{144} = 12$로 계산하는 것이 중요하다.",
