    "explanation": "**[핵심 개념]**\n\n모집단이 정규분포를 따를 때, 표본평균의 신뢰구간은 다음과 같이 구성된다.\n- 표본평균 $\\bar{X}$는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n- 신뢰도 95%일 때 신뢰구간: $\\bar{X} \\pm z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n- **신뢰구간의 길이** = 상한 - 하한 = $2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 5^2)$ → 모표준편차 $\\sigma = 5$\n- 표본크기: $n = 100$\n- 표본평균: $\\bar{X} = 60$\n- 신뢰도: 95% → $z_{0.025} = 1.96$\n\n**2단계: 표본평균의 표준오차(표준편차) 계산**\n\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{5}{\\sqrt{100}} = \\frac{5}{10} = 0.5$$\n\n**3단계: 오차한계(신뢰구간 반폭) 계산**\n\n$$E = z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\times 0.5 = 0.98$$\n\n**4단계: 신뢰구간의 길이 계산**\n\n$$\\text{신뢰구간의 길이} = 2E = 2 \\times 0.98 = 1.96$$\n\n따라서 신뢰구간은 $60 \\pm 0.98$, 즉 $[59.02, 60.98]$이고, 길이는 $1.96$이다.\n\n**[정답 확인]**\n\n신뢰구간의 길이 공식 $2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 1.96 \\times 0.5 = 1.96$으로 정답 ②번이 맞다.\n\n**[오답 분석]**\n\n- ① 0.98: 오차한계(반폭)만 계산한 것. 길이는 이의 2배\n- ③ 2.58: $z_{0.005} = 2.58$과 혼동. 신뢰도 99%의 값을 사용한 것\n- ④ 3.92: $2 \\times 1.96 = 3.92$이지만, 표준오차 0.5를 곱하지 않음 (표준오차를 1로 잘못 계산)\n- ⑤ 5.16: 계산 오류로 인한 선택지\n\n**[핵심 포인트]**\n\n1. **신뢰구간의 길이 = $2 \\times z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$** (상한과 하한의 차이)\n2. 표준오차 계산에서 반드시 $\\sqrt{n}$으로 나누어야 함을 주의하세요.",
