    "explanation": "**[핵심 개념]**\n\n모평균 추정에서 오차한계(margin of error)는 신뢰도와 표본크기에 따라 결정된다. 정규분포를 따르는 모집단에서 모평균의 신뢰도 95% 신뢰구간은 $\\bar{x} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이고, 여기서 $z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이 오차한계 $E$이다.\n\n오차한계 공식: $E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n이를 표본크기 $n$에 대해 정리하면: $n = \\left(\\frac{z_{\\alpha/2} \\cdot \\sigma}{E}\\right)^2$\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- 모집단: $N(m, 6^2)$ → 모표준편차 $\\sigma = 6$\n- 신뢰도: 95% → $z_{0.025} = 1.96$\n- 오차한계: $E \\leq 1.2$\n\n오차한계 조건에서 표본크기를 구한다.\n\n$$E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq 1.2$$\n\n$$1.96 \\cdot \\frac{6}{\\sqrt{n}} \\leq 1.2$$\n\n양변에 $\\sqrt{n}$을 곱하면:\n\n$$1.96 \\times 6 \\leq 1.2\\sqrt{n}$$\n\n$$11.76 \\leq 1.2\\sqrt{n}$$\n\n$$\\sqrt{n} \\geq \\frac{11.76}{1.2}$$\n\n$$\\sqrt{n} \\geq 9.8$$\n\n양변을 제곱하면:\n\n$$n \\geq 96.04$$\n\n$n$은 자연수이므로, $n \\geq 97$\n\n따라서 최소 표본크기는 $n = 97$\n\n**[정답 확인]**\n\n$n = 97$일 때 오차한계는 $1.96 \\times \\frac{6}{\\sqrt{97}} \\approx 1.96 \\times 0.609 \\approx 1.194 < 1.2$이므로 조건을 만족하고, $n = 96$이면 오차한계가 1.2를 초과하므로 ③이 정답이다.\n\n**[오답 분석]**\n\n- ① 64: $n = 64$일 때 오차한계 = $1.96 \\times \\frac{6}{8} = 1.47 > 1.2$ (조건 불만족)\n- ② 81: $n = 81$일 때 오차한계 = $1.96 \\times \\frac{6}{9} = 1.31 > 1.2$ (조건 불만족)\n- ④ 100: $n = 97$에서 이미 조건을 만족하므로 필요 이상으로 크다 (최소값 아님)\n- ⑤ 121: ④와 마찬가지로 불필요하게 크다\n\n**[핵심 포인트]**\n\n표본크기 공식 $n = \\left(\\frac{z_{\\alpha/2} \\cdot \\sigma}{E}\\right)^2$에서 부등호 계산 후 나온 값보다 크거나 같은 최소 정수를 선택해야 한다. 계산 결과 $\\sqrt{n} \\geq 9.8$이므로 $n \\geq 97$이고, 최솟값은 97이다.",
