    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 모집단에서 크기 $n = 100$인 표본을 임의추출하여 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구했더니 $47.04 \\leq m \\leq 52.96$이었다. 이 모집단의 모표준편차 $\\sigma$의 값은? (단, $z_{0.025} = 1.96$)",
