    "answer": 2,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 모집단에서 표본평균의 신뢰구간은 다음과 같이 구성된다.\n- 표본평균 $\\bar{x}$는 $N(m, \\frac{\\sigma^2}{n})$를 따릅니다.\n- 신뢰도 95%의 신뢰구간: $\\bar{x} - z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{x} + z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n- 신뢰구간의 폭(반폭)은 $z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이다.\n\n**[풀이]**\n\n주어진 신뢰구간: $47.04 \\leq m \\leq 52.96$\n\n**Step 1: 신뢰구간의 중심(표본평균) 구하기**\n\n$$\\bar{x} = \\frac{47.04 + 52.96}{2} = \\frac{100}{2} = 50$$\n\n**Step 2: 신뢰구간의 반폭(오차한계) 구하기**\n\n$$E = \\bar{x} - 47.04 = 50 - 47.04 = 2.96$$\n\n또는 $E = 52.96 - \\bar{x} = 52.96 - 50 = 2.96$\n\n**Step 3: 오차한계 공식을 이용하여 $\\sigma$ 구하기**\n\n오차한계 공식:\n$$E = z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n주어진 값들을 대입:\n$$2.96 = 1.96 \\cdot \\frac{\\sigma}{\\sqrt{100}}$$\n\n$$2.96 = 1.96 \\cdot \\frac{\\sigma}{10}$$\n\n$$2.96 = \\frac{1.96\\sigma}{10}$$\n\n양변에 10을 곱하면:\n$$29.6 = 1.96\\sigma$$\n\n$$\\sigma = \\frac{29.6}{1.96} = \\frac{2960}{196} = 15$$\n\n**[정답 확인]**\n$\\sigma = 15$일 때, 오차한계 $E = 1.96 \\times \\frac{15}{10} = 1.96 \\times 1.5 = 2.94 \\approx 2.96$ (반올림 차이)으로 신뢰구간 $50 \\pm 2.96 = [47.04, 52.96]$이 성립한다.\n\n**[오답 분석]**\n- ① 10: $E = 1.96 \\times \\frac{10}{10} = 1.96$ → 신뢰구간 $[48.04, 51.96]$ (불일치)\n- ② 12: $E = 1.96 \\times \\frac{12}{10} = 2.352$ → 신뢰구간 $[47.648, 52.352]$ (불일치)\n- ④ 18: $E = 1.96 \\times \\frac{18}{10} = 3.528$ → 신뢰구간 $[46.472, 53.528]$ (불일치)\n- ⑤ 20: $E = 1.96 \\times \\frac{20}{10} = 3.92$ → 신뢰구간 $[46.08, 53.92]$ (불일치)\n\n**[핵심 포인트]**\n신뢰구간이 주어진 경우, 반폭(오차한계) $E = \\frac{\\text{구간의 폭}}{2}$을 구한 후, $E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 공식에 대입하여 모표준편차를 구한다. 계산 과정에서 표본크기 $n$의 제곱근을 올바르게 적용하는 것이 중요하다.",
