    "problem": "정규분포 $N(m, 8^2)$을 따르는 모집단에서 크기 $n$인 표본을 임의추출하여 모평균 $m$에 대한 신뢰도 99%의 신뢰구간의 길이가 $4$ 이하가 되도록 하려면 $n$의 최솟값은? (단, $z_{0.005} = 2.58$)",
    "answerType": "choice",
