    "problem": "정규분포 $N(m, 4^2)$을 따르는 모집단에서 크기 $n_1 = 64$인 표본과 크기 $n_2 = 256$인 표본을 각각 임의추출하여 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구한다. 두 신뢰구간의 길이의 비 $L_1 : L_2$를 구하면? (단, $z_{0.025} = 1.96$)",
