    "answer": 1,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 모집단에서 추출한 표본의 표본평균은 $N(m, \\frac{\\sigma^2}{n})$를 따릅니다. 모평균 $m$에 대한 신뢰도 95%의 신뢰구간은 $\\bar{X} \\pm z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 형태이며, 신뢰구간의 길이는 $L = 2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이다. 신뢰구간의 길이는 표본크기의 제곱근에 반비례한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 4^2)$이므로 $\\sigma = 4$\n- 표본 1: $n_1 = 64$\n- 표본 2: $n_2 = 256$\n- 신뢰도: 95% (양측), $z_{0.025} = 1.96$\n\n**2단계: 신뢰구간의 길이 공식**\n\n신뢰도 95%일 때 신뢰구간의 길이는:\n$$L = 2 \\times z_{0.025} \\times \\frac{\\sigma}{\\sqrt{n}}$$\n\n**3단계: 첫 번째 표본의 신뢰구간 길이**\n\n$$L_1 = 2 \\times 1.96 \\times \\frac{4}{\\sqrt{64}} = 2 \\times 1.96 \\times \\frac{4}{8}$$\n\n$$L_1 = 2 \\times 1.96 \\times 0.5 = 1.96$$\n\n**4단계: 두 번째 표본의 신뢰구간 길이**\n\n$$L_2 = 2 \\times 1.96 \\times \\frac{4}{\\sqrt{256}} = 2 \\times 1.96 \\times \\frac{4}{16}$$\n\n$$L_2 = 2 \\times 1.96 \\times 0.25 = 0.98$$\n\n**5단계: 길이의 비 계산**\n\n$$L_1 : L_2 = 1.96 : 0.98 = 2 : 1$$\n\n또는 일반적으로:\n$$\\frac{L_1}{L_2} = \\frac{\\frac{\\sigma}{\\sqrt{n_1}}}{\\frac{\\sigma}{\\sqrt{n_2}}} = \\sqrt{\\frac{n_2}{n_1}} = \\sqrt{\\frac{256}{64}} = \\sqrt{4} = 2$$\n\n**[정답 확인]**\n표본크기가 4배 증가하면 신뢰구간의 길이는 2배 감소하므로, $L_1 : L_2 = 2 : 1$이 정답이다.\n\n**[오답 분석]**\n- ① 1 : 2: 길이의 비를 역으로 계산한 경우\n- ③ 1 : 4: 표본크기의 비를 그대로 사용한 경우 (제곱근을 취하지 않음)\n- ④ 4 : 1: 표본크기의 비를 역으로 사용한 경우\n- ⑤ 1 : 1: 표본크기의 영향을 무시한 경우\n\n**[핵심 포인트]**\n신뢰구간의 길이는 $\\sqrt{n}$에 반비례한다. 따라서 표본크기의 비의 제곱근이 길이의 역비가 된다: $\\frac{L_1}{L_2} = \\sqrt{\\frac{n_2}{n_1}}$",
