    "explanation": "**[핵심 개념]**\n\n모평균 추정에서 신뢰도 95%로 추정할 때, 신뢰구간은 $\\bar{x} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 형태이다. 여기서 오차한계(margin of error)는 $E = z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이며, 이 값이 주어진 범위 이내가 되도록 하는 표본크기 $n$을 구하는 문제이다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 10^2)$ → 표준편차 $\\sigma = 10$\n- 신뢰도: 95% → $z_{\\alpha/2} = z_{0.025} = 1.96$\n- 오차한계 조건: $E \\leq 2$\n\n**2단계: 오차한계 공식 설정**\n\n신뢰도 95%에서 오차한계는:\n$$E = z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 1.96 \\cdot \\frac{10}{\\sqrt{n}}$$\n\n**3단계: 부등식 세우기**\n\n오차한계가 2 이하가 되려면:\n$$1.96 \\cdot \\frac{10}{\\sqrt{n}} \\leq 2$$\n\n**4단계: $n$ 구하기**\n\n양변에 $\\sqrt{n}$을 곱하고 2로 나누면:\n$$1.96 \\cdot 10 \\leq 2\\sqrt{n}$$\n\n$$19.6 \\leq 2\\sqrt{n}$$\n\n$$9.8 \\leq \\sqrt{n}$$\n\n양변을 제곱하면:\n$$96.04 \\leq n$$\n\n**5단계: 최솟값 결정**\n\n$n$은 자연수이므로, $n \\geq 96.04$를 만족하는 최소 자연수는:\n$$n = 97$$\n\n**[정답 확인]**\n\n$n=97$일 때 오차한계는 $E = 1.96 \\cdot \\frac{10}{\\sqrt{97}} \\approx 1.96 \\cdot \\frac{10}{9.849} \\approx 1.99 < 2$이므로 조건을 만족한다.\n\n**[오답 분석]**\n\n- $n=96$: $E = 1.96 \\cdot \\frac{10}{\\sqrt{96}} \\approx 2.0041 > 2$ → 조건 불만족\n- $n=98$: 조건은 만족하지만 최솟값이 아님\n- $n=100$: 과도하게 큰 표본크기\n\n**[핵심 포인트]**\n\n오차한계 부등식 $z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq E$에서 $n$에 대해 정리할 때, $n \\geq \\left(\\frac{z_{\\alpha/2} \\cdot \\sigma}{E}\\right)^2$의 형태가 되며, 이를 만족하는 **최소 자연수를 답**으로 선택해야 한다.",
