    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 표본을 추출할 때, 모평균의 신뢰구간은 다음과 같이 구성된다.\n\n- 표본평균 $\\bar{x}$는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n- 신뢰도 95%일 때 신뢰구간: $\\bar{x} \\pm z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n- 신뢰구간의 길이 = $2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n**[풀이]**\n\n**1단계: 신뢰구간의 길이 공식 설정**\n\n신뢰도 95%일 때 신뢰구간의 길이는:\n$$\\text{길이} = 2 \\times z_{0.025} \\times \\frac{\\sigma}{\\sqrt{n}}$$\n\n**2단계: 주어진 값 정리**\n- 신뢰구간의 길이 = 4.9\n- $n = 64$ → $\\sqrt{n} = 8$\n- $z_{0.025} = 1.96$\n- $\\sigma$ = 구하려는 값\n\n**3단계: 방정식 세우기**\n\n$$2 \\times 1.96 \\times \\frac{\\sigma}{8} = 4.9$$\n\n**4단계: $\\sigma$ 구하기**\n\n$$3.92 \\times \\frac{\\sigma}{8} = 4.9$$\n\n$$\\frac{\\sigma}{8} = \\frac{4.9}{3.92}$$\n\n$$\\frac{\\sigma}{8} = 1.25$$\n\n$$\\sigma = 8 \\times 1.25 = 10$$\n\n**[정답 확인]**\n\n$\\sigma = 10$일 때, 신뢰구간의 길이 = $2 \\times 1.96 \\times \\frac{10}{8} = 2 \\times 1.96 \\times 1.25 = 4.9$ ✓\n\n**[오답 분석]**\n\n문제에 선택지가 제시되지 않았으므로, 일반적인 오답 유형:\n- **8**: $\\sqrt{n} = 8$과 혼동한 경우\n- **5**: 신뢰구간 길이를 2로 나누지 않은 경우 ($\\sigma = 5$)\n- **12.25**: $z_{0.025}$와 길이를 혼동한 경우\n\n**[핵심 포인트]**\n\n- **신뢰구간의 길이는 양쪽 끝까지의 거리**이므로 계수 2가 붙다.\n- 신뢰구간 길이 = $2 \\times z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$를 정확히 기억하는 것이 필수이다.",
