    "_type": "estimation",
    "type": "통계적 추정",
    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 모집단에서 크기 $n = 49$인 표본을 임의추출하여 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구했더니 $a \\leq m \\leq b$이었다. $b - a = 5.6$일 때, $\\sigma$의 값은? (단, $z_{0.025} = 1.96$)",
