    "answer": 2,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 모집단에서 표본평균의 신뢰구간은 다음과 같이 구성된다.\n- 표본평균 $\\bar{X}$는 $N(m, \\frac{\\sigma^2}{n})$를 따릅니다.\n- 신뢰도 95%의 신뢰구간: $\\bar{X} - z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{X} + z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n- 신뢰구간의 폭(길이): $b - a = 2 \\cdot z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n**[풀이]**\n\n**1단계: 신뢰구간의 폭 공식 설정**\n\n신뢰도 95%인 신뢰구간에서:\n$$b - a = 2 \\cdot z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**2단계: 주어진 값 대입**\n\n주어진 조건:\n- $n = 49$ → $\\sqrt{n} = 7$\n- $z_{0.025} = 1.96$\n- $b - a = 5.6$\n\n따라서:\n$$5.6 = 2 \\times 1.96 \\times \\frac{\\sigma}{7}$$\n\n**3단계: $\\sigma$ 구하기**\n\n$$5.6 = 3.92 \\times \\frac{\\sigma}{7}$$\n\n양변에 7을 곱하면:\n$$5.6 \\times 7 = 3.92 \\times \\sigma$$\n\n$$39.2 = 3.92 \\times \\sigma$$\n\n$$\\sigma = \\frac{39.2}{3.92} = 10$$\n\n**[정답 확인]**\n$\\sigma = 10$일 때, 신뢰구간의 폭은 $2 \\times 1.96 \\times \\frac{10}{7} = 2 \\times 1.96 \\times \\frac{10}{7} = \\frac{39.2}{7} = 5.6$ ✓\n\n**[오답 분석]**\n- ① $\\sigma = 5$: 신뢰구간의 폭 = $2 \\times 1.96 \\times \\frac{5}{7} = 2.8$ (너무 작음)\n- ② $\\sigma = 7$: 신뢰구간의 폭 = $2 \\times 1.96 \\times \\frac{7}{7} = 3.92$ (너무 작음)\n- ④ $\\sigma = 14$: 신뢰구간의 폭 = $2 \\times 1.96 \\times \\frac{14}{7} = 7.84$ (너무 큼)\n- ⑤ $\\sigma = 20$: 신뢰구간의 폭 = $2 \\times 1.96 \\times \\frac{20}{7} = 11.2$ (너무 큼)\n\n**[핵심 포인트]**\n신뢰구간의 폭은 $2z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이며, 표준편차 $\\sigma$에 정비례한다. 신뢰도와 표본크기가 주어졌을 때 신뢰구간의 폭으로부터 역으로 $\\sigma$를 구하는 문제이다.",
