    "answer": 1,
    "explanation": "**[핵심 개념]**\n정규분포를 따르는 모집단에서 표본평균의 신뢰구간은 다음과 같이 구성된다.\n\n- 표본평균 $\\bar{X}$는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n- 신뢰도 $(1-\\alpha) \\times 100\\%$에 대한 모평균 $m$의 신뢰구간: $\\bar{X} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n- **신뢰구간의 길이** $= 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n신뢰도가 높아질수록 신뢰구간의 길이는 길어진다.\n\n**[풀이]**\n\n**Step 1: 신뢰도 95%의 신뢰구간 길이**\n\n신뢰도 95%일 때, $\\alpha = 0.05$이므로 $\\alpha/2 = 0.025$\n\n$$L_{95} = 2 \\times z_{0.025} \\times \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{100}} = 2 \\times 1.96 \\times \\frac{\\sigma}{10}$$\n\n$$L_{95} = \\frac{3.92\\sigma}{10} = 0.392\\sigma$$\n\n**Step 2: 신뢰도 99%의 신뢰구간 길이**\n\n신뢰도 99%일 때, $\\alpha = 0.01$이므로 $\\alpha/2 = 0.005$\n\n$$L_{99} = 2 \\times z_{0.005} \\times \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 2.58 \\times \\frac{\\sigma}{\\sqrt{100}} = 2 \\times 2.58 \\times \\frac{\\sigma}{10}$$\n\n$$L_{99} = \\frac{5.16\\sigma}{10} = 0.516\\sigma$$\n\n**Step 3: 길이의 비율 $k$ 계산**\n\n$$k = \\frac{L_{95}}{L_{99}} = \\frac{0.392\\sigma}{0.516\\sigma} = \\frac{0.392}{0.516}$$\n\n분자와 분모에 1000을 곱하면:\n\n$$k = \\frac{392}{516} = \\frac{2 \\times 196}{2 \\times 258} = \\frac{196}{258}$$\n\n분자와 분모를 2로 나누면:\n\n$$k = \\frac{98}{129}$$\n\n**[정답 확인]**\n\n신뢰도 95%의 신뢰구간 길이가 신뢰도 99%의 신뢰구간 길이보다 작으므로 $k < 1$이어야 하며, $\\frac{98}{129} \\approx 0.759$로 이를 만족한다.\n\n**[오답 분석]**\n\n① $\\frac{49}{129}$ - 분자를 절반으로 잘못 계산한 경우\n\n③ $\\frac{129}{98}$ - 역수를 구한 경우 (신뢰도 99%의 길이를 분자로 함)\n\n④ $\\frac{98}{258}$ - 분모를 간단히 하지 않은 경우 (기약분수가 아님)\n\n⑤ $\\frac{129}{49}$ - 계산 실수로 역수를 구하고 분자를 절반으로 한 경우\n\n**[핵심 포인트]**\n\n1. 신뢰구간의 길이는 $2z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$에 비례하므로, 길이의 비는 임계값의 비와 같다: $k = \\frac{z_{0.025}}{z_{0.005}} = \\frac{1.96}{2.58} = \\frac{98}{129}$\n\n2. 신뢰도가 높을수록 신뢰구간이 길어지므로, 95% 신뢰구간이 99% 신뢰구간보다 짧아 $k < 1$이다.",
