    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 표본의 크기가 $n$일 때, 모평균 $m$에 대한 신뢰도 $(1-\\alpha) \\times 100\\%$의 신뢰구간은 $$\\bar{x} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n신뢰구간의 길이(폭)는 양쪽 끝점까지의 거리이므로:\n$$\\text{신뢰구간의 길이} = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n신뢰도가 높을수록 $z_{\\alpha/2}$ 값이 커지고, 표본의 크기가 클수록 신뢰구간의 길이는 짧아진다.\n\n**[풀이]**\n\n**1단계: 첫 번째 표본의 신뢰구간 길이**\n\n신뢰도 95%일 때, $\\alpha = 0.05$이므로 $\\alpha/2 = 0.025$이다.\n\n따라서 신뢰구간의 길이는:\n$$L_1 = 2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n_1}} = 2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{n_1}}$$\n\n**2단계: 두 번째 표본의 신뢰구간 길이**\n\n신뢰도 99%일 때, $\\alpha = 0.01$이므로 $\\alpha/2 = 0.005$이다.\n\n따라서 신뢰구간의 길이는:\n$$L_2 = 2 \\times z_{0.005} \\cdot \\frac{\\sigma}{\\sqrt{n_2}} = 2 \\times 2.58 \\times \\frac{\\sigma}{\\sqrt{n_2}}$$\n\n**3단계: 두 신뢰구간의 길이가 같다는 조건 적용**\n\n$$L_1 = L_2$$\n\n$$2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{n_1}} = 2 \\times 2.58 \\times \\frac{\\sigma}{\\sqrt{n_2}}$$\n\n양변을 $2\\sigma$로 나누면:\n$$\\frac{1.96}{\\sqrt{n_1}} = \\frac{2.58}{\\sqrt{n_2}}$$\n\n**4단계: $\\frac{n_2}{n_1}$ 구하기**\n\n양변을 제곱하면:\n$$\\frac{(1.96)^2}{n_1} = \\frac{(2.58)^2}{n_2}$$\n\n$$\\frac{n_2}{n_1} = \\frac{(2.58)^2}{(1.96)^2} = \\frac{6.6564}{3.8416}$$\n\n나눗셈을 계산하면:\n$$\\frac{n_2}{n_1} = 1.7318...$$\n\n소수점 셋째 자리에서 반올림하면:\n$$\\frac{n_2}{n_1} = 1.73$$\n\n**[정답 확인]**\n\n신뢰도가 99%로 높아지므로 같은 길이의 신뢰구간을 만들기 위해서는 더 큰 표본이 필요하며, $n_2/n_1 = 1.73$은 이 조건을 만족한다.\n\n**[오답 분석]**\n\n- ① 1.33: $z$ 값의 비율을 잘못 계산한 경우\n- ② 1.56: 계산 과정에서 제곱을 빠뜨린 경우\n- ④ 1.96: $z_{0.025}$ 값을 그대로 선택한 경우\n- ⑤ 2.58: $z_{0.005}$ 값을 그대로 선택한 경우\n\n**[핵심 포인트]**\n\n신뢰구간의 길이는 $2z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$에 비례한다. 두 신뢰구간의 길이가 같으려면 $z_{\\alpha/2}$와 $\\sqrt{n}$의 곱이 일정해야 하므로, 더 큰 $z$ 값에는 더 작은 $\\sqrt{n}$ (즉, 작은 $n$)이 대응되어야 한다.",
