    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 모집단에서 크기 $n$인 표본을 임의추출하여 신뢰도 95%의 신뢰구간을 구한다. 현재 $n = 400$이고, 표본 크기를 증가시켜 신뢰구간의 길이를 현재의 $\\frac{1}{3}$로 줄이려면 표본 크기를 얼마로 해야 하는가? (단, $z_{0.025} = 1.96$)",
    "answerType": "choice",
