    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 표본평균의 신뢰구간은 다음과 같이 구성된다.\n\n신뢰도 95%의 신뢰구간: $\\bar{x} \\pm z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n신뢰구간의 길이(오차한계의 2배): $L = 2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n신뢰구간의 길이는 표본크기의 제곱근에 반비례한다.\n\n**[풀이]**\n\n**1단계: 현재 신뢰구간의 길이 표현**\n\n표본크기 $n_1 = 400$일 때, 신뢰구간의 길이:\n\n$$L_1 = 2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n_1}} = 2 \\times 1.96 \\cdot \\frac{\\sigma}{\\sqrt{400}} = 2 \\times 1.96 \\cdot \\frac{\\sigma}{20}$$\n\n**2단계: 새로운 신뢰구간의 길이 조건**\n\n신뢰구간의 길이를 현재의 $\\frac{1}{3}$로 줄이려면:\n\n$$L_2 = \\frac{1}{3}L_1$$\n\n새로운 표본크기를 $n_2$라 하면:\n\n$$L_2 = 2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n_2}}$$\n\n**3단계: 두 길이의 비 계산**\n\n$$\\frac{L_2}{L_1} = \\frac{2 \\times 1.96 \\cdot \\frac{\\sigma}{\\sqrt{n_2}}}{2 \\times 1.96 \\cdot \\frac{\\sigma}{\\sqrt{n_1}}} = \\frac{\\sqrt{n_1}}{\\sqrt{n_2}} = \\sqrt{\\frac{n_1}{n_2}}$$\n\n**4단계: 주어진 조건 적용**\n\n$$\\frac{L_2}{L_1} = \\frac{1}{3}$$\n\n$$\\sqrt{\\frac{n_1}{n_2}} = \\frac{1}{3}$$\n\n양변을 제곱하면:\n\n$$\\frac{n_1}{n_2} = \\frac{1}{9}$$\n\n$$n_2 = 9n_1 = 9 \\times 400 = 3600$$\n\n**[정답 확인]**\n\n표본크기를 3600으로 하면 신뢰구간의 길이가 원래의 $\\frac{1}{3}$이 되므로 정답은 ④번이다.\n\n**[오답 분석]**\n\n- ① 1200: $\\sqrt{\\frac{400}{1200}} = \\sqrt{\\frac{1}{3}} \\approx 0.577$ (약 $\\frac{1}{1.73}$배 감소, 부족)\n- ② 1600: $\\sqrt{\\frac{400}{1600}} = \\sqrt{\\frac{1}{4}} = \\frac{1}{2}$ (길이가 $\\frac{1}{2}$배, 과도하게 감소)\n- ③ 2400: $\\sqrt{\\frac{400}{2400}} = \\sqrt{\\frac{1}{6}} \\approx 0.408$ (길이가 약 $\\frac{1}{2.45}$배, 부족)\n- ⑤ 4800: $\\sqrt{\\frac{400}{4800}} = \\sqrt{\\frac{1}{12}} \\approx 0.289$ (길이가 약 $\\frac{1}{3.46}$배, 과도)\n\n**[핵심 포인트]**\n\n신뢰구간의 길이는 $\\sqrt{n}$에 반비례한다. 길이를 $\\frac{1}{k}$로 줄이려면 표본크기를 $k^2$배로 늘려야 한다.",
