    "problem": "정규분포 $N(m, 4^2)$을 따르는 모집단에서 크기 $n = 64$인 표본을 임의추출하여 표본평균 $\\bar{X}$를 구한다. 신뢰도 95%의 신뢰구간의 길이를 $L_{95}$, 신뢰도 99%의 신뢰구간의 길이를 $L_{99}$라 할 때, $L_{99} - L_{95}$의 값을 구하시오. (단, $z_{0.025} = 1.96$, $z_{0.005} = 2.58$)",
