    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n모집단이 정규분포를 따를 때, 표본평균 $\\bar{X}$의 신뢰구간은 $$\\bar{X} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n여기서 신뢰구간의 길이는 양쪽 오차한계를 더한 값이므로:\n\n$$L = 2 \\cdot z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n신뢰도가 높을수록 신뢰구간의 길이는 길어진다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 4^2)$ → $\\sigma = 4$\n- 표본크기: $n = 64$\n- $z_{0.025} = 1.96$ (신뢰도 95%)\n- $z_{0.005} = 2.58$ (신뢰도 99%)\n\n**2단계: 표본평균의 표준오차 계산**\n\n$$\\frac{\\sigma}{\\sqrt{n}} = \\frac{4}{\\sqrt{64}} = \\frac{4}{8} = 0.5$$\n\n**3단계: 신뢰도 95%의 신뢰구간 길이 계산**\n\n$$L_{95} = 2 \\cdot z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 1.96 \\times 0.5 = 1.96$$\n\n**4단계: 신뢰도 99%의 신뢰구간 길이 계산**\n\n$$L_{99} = 2 \\cdot z_{0.005} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 2.58 \\times 0.5 = 2.58$$\n\n**5단계: 두 길이의 차이 계산**\n\n$$L_{99} - L_{95} = 2.58 - 1.96 = 0.62$$\n\n**[정답 확인]**\n\n신뢰도 99%가 95%보다 높으므로 신뢰구간이 더 길어지며, 그 차이가 정확히 0.62이다.\n\n**[오답 분석]**\n\n- ① 0.31: $0.62 \\div 2$의 값으로, 신뢰구간 길이의 절반만 구한 경우\n- ③ 1.24: $0.62 \\times 2$의 값으로, 계산 실수\n- ④ 1.86: $2.58 - 0.72$ 같은 잘못된 계산\n- ⑤ 2.48: $2.58 + 1.96 - 2.06$ 같은 복잡한 오류\n\n**[핵심 포인트]**\n\n신뢰구간의 길이는 $2 \\cdot z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이며, 신뢰도가 올라가면서 임계값($z$값)이 커지므로 신뢰구간도 길어진다. 두 길이의 차이는 임계값의 차이에만 의존한다.",
