    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 모집단에서 크기 $n = 400$인 표본을 임의추출하여 모평균 $m$에 대한 신뢰도 95%의 신뢰구간을 구했더니 $a \\leq m \\leq b$이었다. $b - a = 3.92$이고, 같은 모집단에서 크기 $n' = 100$인 표본을 임의추출하여 신뢰도 99%의 신뢰구간을 구할 때, 이 신뢰구간의 길이를 구하시오. (단, $z_{0.025} = 1.96$, $z_{0.005} = 2.58$)",
