    "explanation": "**[핵심 개념]**\n\n모집단이 정규분포 $N(m, \\sigma^2)$을 따를 때, 표본평균 $\\bar{X}$의 분포는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다.\n\n모평균 $m$에 대한 신뢰도 $(1-\\alpha) \\times 100\\%$의 신뢰구간은:\n$$\\bar{X} - z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{X} + z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n신뢰구간의 길이(오차한계의 2배)는:\n$$\\text{길이} = 2z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n**[풀이]**\n\n**Step 1: 첫 번째 신뢰구간에서 $\\sigma$ 구하기**\n\n$n = 400$, 신뢰도 95%에서 $z_{0.025} = 1.96$\n\n신뢰구간의 길이:\n$$b - a = 2 \\times 1.96 \\times \\frac{\\sigma}{\\sqrt{400}} = 3.92$$\n\n$$2 \\times 1.96 \\times \\frac{\\sigma}{20} = 3.92$$\n\n$$\\frac{3.92\\sigma}{20} = 3.92$$\n\n$$\\sigma = 20$$\n\n**Step 2: 두 번째 신뢰구간의 길이 구하기**\n\n$n' = 100$, 신뢰도 99%에서 $z_{0.005} = 2.58$\n\n신뢰구간의 길이:\n$$\\text{길이} = 2 \\times 2.58 \\times \\frac{\\sigma}{\\sqrt{n'}}$$\n\n$$= 2 \\times 2.58 \\times \\frac{20}{\\sqrt{100}}$$\n\n$$= 2 \\times 2.58 \\times \\frac{20}{10}$$\n\n$$= 2 \\times 2.58 \\times 2$$\n\n$$= 10.32$$\n\n**[정답 확인]**\n\n첫 번째 조건에서 $\\sigma = 20$을 구한 후, 이를 이용하여 두 번째 신뢰구간의 길10.32가 나온다.\n\n**[오답 분석]**\n\n- ① 7.84: $n' = 100$에서 신뢰도 95%로 잘못 계산한 경우 ($2 \\times 1.96 \\times 2 = 7.84$)\n- ② 8.24: 계산 과정에서 오류 발생\n- ④ 12.90: $n' = 400$으로 착각하여 계산한 경우\n- ⑤ 15.48: $\\sigma$ 값을 잘못 구했거나 계산 실수\n\n**[핵심 포인트]**\n\n1. 신뢰구간의 길이는 신뢰도가 높을수록, 표본의 크기가 작을수록 커진다.\n2. 첫 번째 조건에서 모표준편차 $\\sigma$를 구하는 것이 핵심이며, 이를 두 번째 신뢰구간 계산에 사용한다.",
