    "problem": "어느 지역에서 특정 정책에 대한 찬성 비율을 조사하기 위해 400명을 임의추출하여 조사했더니 찬성한 사람이 240명이었다. 모비율 $p$에 대한 신뢰도 95%의 신뢰구간을 구하면? (단, $z_{0.025} = 1.96$)",
    "answerType": "choice",
