    "answer": 0,
    "explanation": "**[핵심 개념]**\n모비율 $p$에 대한 신뢰도 $95\\%$의 신뢰구간은 표본비율을 중심으로 오차한계를 더하고 빼서 구한다. \n\n신뢰구간: $\\hat{p} \\pm z_{\\alpha/2}\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$\n\n여기서:\n- $\\hat{p}$ = 표본비율\n- $n$ = 표본크기\n- $z_{\\alpha/2}$ = 신뢰도에 해당하는 표준정규분포의 값\n\n**[풀이]**\n\n**1단계: 표본비율 구하기**\n\n표본크기 $n = 400$, 찬성한 사람 = 240명\n\n$$\\hat{p} = \\frac{240}{400} = 0.6$$\n\n**2단계: 표준오차 계산**\n\n$$\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} = \\sqrt{\\frac{0.6 \\times 0.4}{400}} = \\sqrt{\\frac{0.24}{400}} = \\sqrt{0.0006}$$\n\n$$= \\sqrt{\\frac{6}{10000}} = \\frac{\\sqrt{6}}{100}$$\n\n더 간단히 계산하면:\n$$\\sqrt{\\frac{0.24}{400}} = \\frac{\\sqrt{0.24}}{20} = \\frac{0.4899}{20} \\approx 0.0245$$\n\n**3단계: 오차한계 계산**\n\n신뢰도 95%이므로 $z_{0.025} = 1.96$\n\n$$E = z_{0.025} \\times \\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} = 1.96 \\times 0.0245 = 0.048$$\n\n**4단계: 신뢰구간 구하기**\n\n$$\\hat{p} - E \\leq p \\leq \\hat{p} + E$$\n\n$$0.6 - 0.048 \\leq p \\leq 0.6 + 0.048$$\n\n$$0.552 \\leq p \\leq 0.648$$\n\n**[정답 확인]**\n계산한 신뢰구간 $0.552 \\leq p \\leq 0.648$이 선지 ①과 정확히 일치한다.\n\n**[오답 분석]**\n- ②, ③, ⑤: 오차한계 계산 오류로 인한 결과. 표준오차나 $z$값을 잘못 적용한 경우\n- ④: 오차한계가 $0.04$로 계산되어 구간이 더 좁아진 경우. $1.96 \\times 0.0245 \\neq 0.04$\n\n**[핵심 포인트]**\n- 모비율의 신뢰구간은 $\\hat{p} \\pm z_{\\alpha/2}\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$ 공식을 정확히 적용\n- 표본비율 $\\hat{p} = 0.6$, 표준오차 $\\sqrt{\\frac{0.24}{400}} = 0.0245$, 오차한계 $= 1.96 \\times 0.0245 = 0.048$",
