    "problem": "모비율 $p$를 추정하기 위해 $n$명을 조사한다. 신뢰도 95%에서 오차한계가 $0.03$ 이하가 되도록 하려면 표본의 크기 $n$은 최소 얼마이어야 하는가? (단, $z_{0.025} = 1.96$, 모비율의 사전 정보는 없다.)",
