    "explanation": "**[핵심 개념]**\n\n모비율 추정에서 표본의 크기를 결정하는 공식은 오차한계 $E = z_{\\alpha/2} \\sqrt{\\frac{p(1-p)}{n}}$\n\n이를 $n$에 대해 정리하면: $n = \\frac{z_{\\alpha/2}^2 \\cdot p(1-p)}{E^2}$\n\n신뢰도 95%일 때 $z_{0.025} = 1.96$이고, 모비율의 사전 정보가 없을 때는 $p = 0.5$를 사용한다. (이때 $p(1-p)$가 최대값 0.25가 되어 필요한 표본 크기가 최대가 된다.)\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 신뢰도: 95% → $z_{0.025} = 1.96$\n- 오차한계: $E = 0.03$ 이하\n- 모비율의 사전 정보: 없음 → $p = 0.5$ 사용\n\n**2단계: 표본 크기 공식에 대입**\n\n$$n = \\frac{z_{\\alpha/2}^2 \\cdot p(1-p)}{E^2}$$\n\n**3단계: 값 계산**\n\n$$n = \\frac{(1.96)^2 \\times 0.5 \\times 0.5}{(0.03)^2}$$\n\n$$n = \\frac{3.8416 \\times 0.25}{0.0009}$$\n\n$$n = \\frac{0.9604}{0.0009}$$\n\n$$n = 1067.111...$$\n\n**4단계: 올림하기**\n\n표본 크기는 자연수여야 하고 오차한계 조건을 만족해야 하므로, 최소값은 $n = 1068$이다.\n\n**[정답 확인]**\n\n$n = 1068$일 때 오차한계는 $E = 1.96\\sqrt{\\frac{0.25}{1068}} \\approx 0.03$이 되어 조건을 만족한다.\n\n**[오답 분석]**\n\n- **①849**: $p(1-p) = 0.25$ 대신 다른 값을 사용하거나 계산 실수\n- **③1068**: 선택지 ②와 동일한 값으로, 중복 표시된 것으로 보임\n- **④1600**: $1.96^2 \\approx 4$로 근사하고 $p = 0.5$를 사용한 경우, $\\frac{4 \\times 0.25}{0.0009} = 1111$이 아닌 다른 계산 오류\n- **⑤2401**: $n = \\frac{1.96 \\times 0.5}{0.03}$의 형태로 제곱을 빠뜨린 경우 ($49^2 = 2401$)\n\n**[핵심 포인트]**\n\n- **모비율의 사전 정보가 없을 때는 반드시 $p = 0.5$를 사용**하여 필요한 최대 표본 크기를 구한다.\n- 계산 결과가 정수가 아니면 **올림**하여 오차한계 조건을 확실히 만족하도록 한다.",
