    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 모평균의 신뢰구간은 다음과 같이 구성된다.\n\n신뢰도 $(1-\\alpha) \\times 100\\%$일 때, 표본크기가 $n$이고 표본평균이 $\\bar{x}$, 모표준편차가 $\\sigma$일 때:\n\n$$\\bar{x} - z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} \\leq m \\leq \\bar{x} + z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$$\n\n신뢰도가 높을수록 신뢰구간의 폭이 넓어진다.\n\n**[풀이]**\n\n**Step 1: 신뢰도 95% 신뢰구간 설정**\n\n신뢰도 95%이므로 $\\alpha = 0.05$, $\\alpha/2 = 0.025$\n\n$$a = \\bar{x} - z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = \\bar{x} - 1.96 \\cdot \\frac{\\sigma}{10}$$\n\n$$b = \\bar{x} + z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}} = \\bar{x} + 1.96 \\cdot \\frac{\\sigma}{10}$$\n\n**Step 2: 신뢰도 99% 신뢰구간 설정**\n\n신뢰도 99%이므로 $\\alpha = 0.01$, $\\alpha/2 = 0.005$\n\n$$c = \\bar{x} - z_{0.005} \\cdot \\frac{\\sigma}{\\sqrt{n}} = \\bar{x} - 2.58 \\cdot \\frac{\\sigma}{10}$$\n\n$$d = \\bar{x} + z_{0.005} \\cdot \\frac{\\sigma}{\\sqrt{n}} = \\bar{x} + 2.58 \\cdot \\frac{\\sigma}{10}$$\n\n**Step 3: $d - b$ 계산**\n\n$$d - b = \\left(\\bar{x} + 2.58 \\cdot \\frac{\\sigma}{10}\\right) - \\left(\\bar{x} + 1.96 \\cdot \\frac{\\sigma}{10}\\right)$$\n\n$$d - b = 2.58 \\cdot \\frac{\\sigma}{10} - 1.96 \\cdot \\frac{\\sigma}{10}$$\n\n$$d - b = (2.58 - 1.96) \\cdot \\frac{\\sigma}{10}$$\n\n$$d - b = 0.62 \\cdot \\frac{\\sigma}{10}$$\n\n**Step 4: $\\sigma$ 구하기**\n\n주어진 조건: $d - b = 0.93$\n\n$$0.62 \\cdot \\frac{\\sigma}{10} = 0.93$$\n\n$$\\frac{\\sigma}{10} = \\frac{0.93}{0.62} = 1.5$$\n\n$$\\sigma = 15$$\n\n**[정답 확인]**\n\n신뢰도 99%의 신뢰구간의 오른쪽 끝점과 신뢰도 95%의 신뢰구간의 오른쪽 끝점의 차이가 0.93이라는 조건에서, 신뢰도계수의 차이 $(2.58 - 1.96) = 0.62$를 이용하여 $\\sigma = 15$를 얻는다.\n\n**[오답 분석]**\n\n- **①번(10)**: $0.62 \\times \\frac{10}{10} = 0.62 \\neq 0.93$ (너무 작음)\n- **③번(20)**: $0.62 \\times \\frac{20}{10} = 1.24 \\neq 0.93$ (너무 큼)\n- **④번(25)**: $0.62 \\times \\frac{25}{10} = 1.55 \\neq 0.93$ (더욱 큼)\n- **⑤번(30)**: $0.62 \\times \\frac{30}{10} = 1.86 \\neq 0.93$ (매우 큼)\n\n**[핵심 포인트]**\n\n신뢰구간의 폭은 신뢰계수에 비례한다. 두 신뢰구간의 우측 끝점 차이 = (신뢰계수 차이) × (표준오차)를 이용하여 모표준편차를 구하는 것이 핵심이다.",
