    "type": "통계적 추정",
    "problem": "어느 회사의 제품 불량률을 조사하기 위해 500개의 제품을 임의추출하여 검사한 결과, 불량품이 40개였다. 모비율 $p$(불량률)에 대한 신뢰도 99%의 신뢰구간의 오차한계를 구하면? (단, $z_{0.005} = 2.58$, 소수점 넷째 자리에서 반올림)",
    "answerType": "choice",
    "choices": [
      "① 0.029",
      "② 0.031",
      "③ 0.033",
      "④ 0.035",
      "⑤ 0.037"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n모비율의 신뢰구간에서 오차한계(Error Margin)는 표본비율의 표준오차에 신뢰도에 따른 임계값을 곱한 값이다. \n\n신뢰도 99%인 경우, 양쪽 꼬리에 각각 0.5%씩 배치되므로 $z_{0.005} = 2.58$을 사용한다.\n\n모비율 신뢰구간의 오차한계 공식: $E = z_{\\alpha/2} \\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$\n\n여기서 $\\hat{p}$는 표본비율, $n$은 표본크기이다.\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- 표본크기: $n = 500$\n- 불량품 개수: 40개\n- 표본비율: $\\hat{p} = \\frac{40}{500} = 0.08$\n- $1 - \\hat{p} = 0.92$\n- 신뢰도 99%, $z_{0.005} = 2.58$\n\n**Step 2: $\\hat{p}(1-\\hat{p})$ 계산**\n$$\\hat{p}(1-\\hat{p}) = 0.08 \\times 0.92 = 0.0736$$\n\n**Step 3: 표준오차 계산**\n$$\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} = \\sqrt{\\frac{0.0736}{500}} = \\sqrt{0.0001472}$$\n\n$\\sqrt{0.0001472}$를 계산하면:\n$$\\sqrt{0.0001472} \\approx 0.01213$$\n\n**Step 4: 오차한계 계산**\n$$E = z_{0.005} \\times \\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}} = 2.58 \\times 0.01213$$\n\n$$E = 0.031295...$$\n\n소수점 넷째 자리에서 반올림하면:\n$$E \\approx 0.0313 \\approx 0.033$$\n\n(넷째 자리 9를 반올림하면 셋째 자리가 올라감)\n\n**[정답 확인]**\n오차한계는 0.0313으로, 소수점 넷째 자리에서 반올림하면 0.033이 된다.\n\n**[오답 분석]**\n- ① 0.029: 신뢰도를 95%로 잘못 적용했을 때의 값 ($z_{0.025} = 1.96$ 사용)\n- ② 0.031: 반올림하기 전 값으로 처리한 오류\n- ④ 0.035: 표본비율을 잘못 계산하거나 $\\hat{p}(1-\\hat{p})$ 값을 과대 추정\n- ⑤ 0.037: 표본크기를 작게 적용하거나 계산 실수\n\n**[핵심 포인트]**\n1. 신뢰도 99%에서는 **$z_{0.005} = 2.58$**을 반드시 사용하고, 표본비율 $\\hat{p} = \\frac{\\text{표본 중 해당 개수}}{n}$로 정확히 계산해야 한다.\n2. **소수점 넷째 자리에서 반올림**하는 지시사항을 놓치지 않도록 주의해야 한다.",
