    "problem": "정규분포 $N(m, \\sigma^2)$을 따르는 두 모집단 $A$, $B$가 있다. $A$의 모표준편차는 $\\sigma_A = 6$, $B$의 모표준편차는 $\\sigma_B = 9$이다. $A$에서 크기 $n_A$, $B$에서 크기 $n_B$인 표본을 각각 임의추출하여 신뢰도 95%의 신뢰구간을 구할 때, 두 신뢰구간의 길이가 같으려면 $\\frac{n_B}{n_A}$의 값은? (단, $z_{0.025} = 1.96$)",
    "answerType": "choice",
    "choices": [
      "① 1.50",
      "② 2.00",
      "③ 2.25",
      "④ 3.00",
      "⑤ 4.00"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 표본평균의 신뢰구간은 다음과 같이 구성된다.\n\n신뢰도 95%일 때 신뢰구간: $\\bar{x} \\pm z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n신뢰구간의 길이 = $2 \\times z_{0.025} \\cdot \\frac{\\sigma}{\\sqrt{n}}$\n\n모표준편차 $\\sigma$가 클수록, 표본크기 $n$이 작을수록 신뢰구간의 길이가 길어진다.\n\n**[풀이]**\n\n**1단계: 각 모집단의 신뢰구간 길이 공식 세우기**\n\n모집단 $A$의 신뢰구간 길이:\n$$L_A = 2 \\times z_{0.025} \\times \\frac{\\sigma_A}{\\sqrt{n_A}} = 2 \\times 1.96 \\times \\frac{6}{\\sqrt{n_A}}$$\n\n모집단 $B$의 신뢰구간 길이:\n$$L_B = 2 \\times z_{0.025} \\times \\frac{\\sigma_B}{\\sqrt{n_B}} = 2 \\times 1.96 \\times \\frac{9}{\\sqrt{n_B}}$$\n\n**2단계: 두 신뢰구간의 길이가 같다는 조건 적용**\n\n$$L_A = L_B$$\n\n$$2 \\times 1.96 \\times \\frac{6}{\\sqrt{n_A}} = 2 \\times 1.96 \\times \\frac{9}{\\sqrt{n_B}}$$\n\n**3단계: 정리하기**\n\n양변에서 $2 \\times 1.96$을 소거하면:\n\n$$\\frac{6}{\\sqrt{n_A}} = \\frac{9}{\\sqrt{n_B}}$$\n\n양변을 제곱하면:\n\n$$\\frac{36}{n_A} = \\frac{81}{n_B}$$\n\n**4단계: $\\frac{n_B}{n_A}$ 구하기**\n\n$$36 \\times n_B = 81 \\times n_A$$\n\n$$\\frac{n_B}{n_A} = \\frac{81}{36} = \\frac{9}{4} = 2.25$$\n\n**[정답 확인]**\n\n$\\frac{n_B}{n_A} = 2.25$이므로 정답은 **③번**이다. 모표준편차가 더 큰 모집단 $B$는 같은 길이의 신뢰구간을 얻기 위해 더 큰 표본을 필요로 한다.\n\n**[오답 분석]**\n\n- **①번 (1.50)**: $\\frac{n_B}{n_A} = \\frac{3}{2}$로 계산한 경우 (표준편차 비율을 잘못 적용)\n- **②번 (2.00)**: $\\frac{\\sigma_B}{\\sigma_A} = \\frac{9}{6} = 1.5$를 단순히 제곱하지 않고 다른 방식으로 계산\n- **④번 (3.00)**: 표준편차 비율 $\\frac{9}{6} = 1.5$를 2배 한 경우\n- **⑤번 (4.00)**: $\\left(\\frac{9}{6}\\right)^2 = \\frac{81}{36}$를 잘못 계산하여 정수로 근사\n\n**[핵심 포인트]**\n\n신뢰구간의 길이가 같으려면 $\\frac{\\sigma}{\\sqrt{n}}$이 같아야 하므로, 표준편차가 크면 표본크기도 **제곱 비율**로 커져야 한다: $\\frac{n_B}{n_A} = \\left(\\frac{\\sigma_B}{\\sigma_A}\\right)^2$",
