    "type": "통계적 추정",
    "problem": "어느 도시의 유권자 중 $n$명을 임의추출하여 특정 후보 지지 여부를 조사했더니 지지자가 $0.4n$명이었다. 모비율 $p$에 대한 신뢰도 95%의 신뢰구간의 오차한계가 $0.04$ 이하가 되도록 하는 $n$의 최솟값을 구하시오. (단, $z_{0.025} = 1.96$)",
    "answerType": "short",
    "choices": null,
    "answer": 577,
    "explanation": "**[핵심 개념]**\n모비율 추정에서 신뢰도 $1-\\alpha$에 대한 신뢰구간의 오차한계는 $E = z_{\\alpha/2}\\sqrt{\\frac{p(1-p)}{n}}$로 주어진다. \n- 표본비율 $\\hat{p} = \\frac{0.4n}{n} = 0.4$\n- 신뢰도 95%일 때 $z_{0.025} = 1.96$\n- 오차한계 $E \\leq 0.04$를 만족하는 최소 표본크기 $n$을 구하는 문제이다.\n\n**[풀이]**\n\n**1단계: 오차한계 공식 설정**\n$$E = z_{0.025}\\sqrt{\\frac{\\hat{p}(1-\\hat{p})}{n}}$$\n\n주어진 조건:\n- $\\hat{p} = 0.4$\n- $z_{0.025} = 1.96$\n- $E \\leq 0.04$\n\n**2단계: 부등식 세우기**\n$$1.96\\sqrt{\\frac{0.4 \\times 0.6}{n}} \\leq 0.04$$\n\n**3단계: 부등식 정리**\n$$\\sqrt{\\frac{0.4 \\times 0.6}{n}} \\leq \\frac{0.04}{1.96}$$\n\n$$\\sqrt{\\frac{0.24}{n}} \\leq \\frac{0.04}{1.96}$$\n\n양변을 제곱:\n$$\\frac{0.24}{n} \\leq \\left(\\frac{0.04}{1.96}\\right)^2$$\n\n$$\\frac{0.24}{n} \\leq \\frac{0.0016}{3.8416}$$\n\n**4단계: $n$ 계산**\n$$n \\geq \\frac{0.24 \\times 3.8416}{0.0016}$$\n\n$$n \\geq \\frac{0.921984}{0.0016}$$\n\n$$n \\geq 576.24$$\n\n**5단계: 최솟값 결정**\n$n$은 자연수이므로 $n$의 최솟값은 $577$이다.\n\n**[정답 확인]**\n$n = 577$일 때 오차한계는 $1.96\\sqrt{\\frac{0.24}{577}} \\approx 0.0399 < 0.04$이므로 조건을 만족하며, $n = 576$일 때는 오차한계가 0.04를 초과하므로 최솟값은 **577**이다.\n\n**[오답 분석]**\n- **576**: 계산 과정에서 부등호 방향을 잘못 적용하거나 올림을 하지 않은 경우\n- **570~575**: 제곱 계산 실수나 중간 과정에서의 근사 오류\n- **580 이상**: 필요 이상으로 큰 표본크기를 선택한 경우\n\n**[핵심 포인트]**\n표본크기 계산에서는 부등식을 $n$에 대해 정리한 후 **항상 올림**하여 최솟값을 구해야 한다. 특히 오차한계 조건 $E \\leq 0.04$에서 $n$의 범위는 $n \\geq 576.24$이므로, 자연수인 $n$의 최솟값은 **577**이다.",
