    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n정규분포를 따르는 모집단에서 모평균에 대한 신뢰구간은 $\\bar{x} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 형태이다. \n- 신뢰도 95%일 때: $z_{0.025} = 1.96$ (양쪽 꼬리 각 2.5%)\n- 신뢰도 99%일 때: $z_{0.005} = 2.58$ (양쪽 꼬리 각 0.5%)\n\n신뢰구간의 폭(너비)은 $2 \\times z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$이다.\n\n**[풀이]**\n\n**1단계: 신뢰구간의 폭 표현**\n\n표본평균을 $\\bar{x}$, $\\frac{\\sigma}{\\sqrt{n}} = s$라고 하면:\n\n- 신뢰도 95% 신뢰구간: $[a, b] = [\\bar{x} - 1.96s, \\bar{x} + 1.96s]$\n \n 따라서 $b - a = 2 \\times 1.96s = 3.92s$\n\n- 신뢰도 99% 신뢰구간: $[c, d] = [\\bar{x} - 2.58s, \\bar{x} + 2.58s]$\n \n 따라서 $d - c = 2 \\times 2.58s = 5.16s$\n\n**2단계: 주어진 비율식 활용**\n\n$$\\frac{b-a}{d-c} = \\frac{3.92s}{5.16s} = \\frac{3.92}{5.16} = \\frac{98}{129}$$\n\n검증: $\\frac{3.92}{5.16} = \\frac{392}{516} = \\frac{98}{129}$ ✓\n\n**3단계: $d-b$ 식 세우기**\n\n구간의 위치:\n- $b = \\bar{x} + 1.96s$\n- $d = \\bar{x} + 2.58s$\n\n따라서:\n$$d - b = (\\bar{x} + 2.58s) - (\\bar{x} + 1.96s) = (2.58 - 1.96)s = 0.62s$$\n\n**4단계: $s$ 값 구하기**\n\n주어진 조건 $d - b = 1.86$을 이용:\n\n$$0.62s = 1.86$$\n\n$$s = \\frac{1.86}{0.62} = 3$$\n\n따라서 $\\frac{\\sigma}{\\sqrt{n}} = 3$\n\n**[정답 확인]**\n\n$d - b = 0.62 \\times 3 = 1.86$ ✓이고, $\\frac{b-a}{d-c} = \\frac{3.92 \\times 3}{5.16 \\times 3} = \\frac{98}{129}$ ✓을 만족한다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 일반적인 오류:\n- **1.86만 답이라 생각**: 이는 $d-b$의 값이지 $\\frac{\\sigma}{\\sqrt{n}}$이 아닙니다.\n- **비율식을 잘못 계산**: $\\frac{1.96}{2.58}$로 계산하면 잘못된 값이 나온다.\n- **0.62를 구하지 못함**: $2.58 - 1.96$의 계산 실수로 $d-b$를 잘못 표현한다.\n\n**[핵심 포인트]**\n\n신뢰도가 다른 두 신뢰구간에서 폭의 비율은 신뢰도계수의 비율이고, 구간의 상한 차이 $d-b$는 신뢰도계수 차이에 표준오차를 곱한 값이다. 이 두 조건을 연립하면 표준오차를 정확히 구한다.",
