    "problem": "6명의 학생 중에서 3명을 선택하여 일렬로 세우는 경우의 수를 $a$, 6명 중 3명을 선택하는 조합의 수를 $b$라 하자. 이 $b$명을 한 모둠으로 만들어 각 모둠에서 대표 1명을 뽑을 때, 대표가 될 확률이 $\\frac{1}{b}$인 특정 학생이 대표로 뽑히지 않을 확률은?",
    "answerType": "choice",
