    "explanation": "**[핵심 개념]**\n확률의 정의: 구하는 경우의 수를 전체 경우의 수로 나눈 값이다.\n- 전체 경우의 수: 1, 2, 3, 4, 5에서 서로 다른 3개를 선택하여 배열하는 순열\n- 구하는 경우의 수: 일의 자리가 짝수(2 또는 4)인 경우\n\n세 자리 수가 짝수 ⟺ 일의 자리 숫자가 짝수(2 또는 4)\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 계산**\n\n1, 2, 3, 4, 5에서 서로 다른 3개를 선택하여 세 자리 수를 만드는 경우의 수:\n$$P(5,3) = 5 \\times 4 \\times 3 = 60$$\n\n**2단계: 짝수가 되는 경우의 수 계산**\n\n세 자리 수가 짝수가 되려면 일의 자리가 짝수(2 또는 4)여야 한다.\n\n**경우 1) 일의 자리가 2인 경우**\n- 일의 자리: 2 (고정)\n- 백의 자리: 남은 4개(1, 3, 4, 5) 중 1개 선택 → 4가지\n- 십의 자리: 남은 3개 중 1개 선택 → 3가지\n- 소계: $4 \\times 3 = 12$가지\n\n**경우 2) 일의 자리가 4인 경우**\n- 일의 자리: 4 (고정)\n- 백의 자리: 남은 4개(1, 2, 3, 5) 중 1개 선택 → 4가지\n- 십의 자리: 남은 3개 중 1개 선택 → 3가지\n- 소계: $4 \\times 3 = 12$가지\n\n**짝수인 경우의 수 합계:**\n$$12 + 12 = 24$$\n\n**3단계: 확률 계산**\n\n$$P(\\text{짝수}) = \\frac{24}{60} = \\frac{2}{5}$$\n\n**[정답 확인]**\n\n전체 60개의 세 자리 수 중 일의 자리가 2 또는 4(짝수)인 경우가 24개이므로, 확률은 $\\frac{24}{60} = \\frac{2}{5}$이다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{5}$: 일의 자리가 2인 경우만 계산한 오류 ($\\frac{12}{60}$을 약분 잘못함)\n- ② $\\frac{3}{10}$: 분자나 분모를 잘못 계산한 경우\n- ④ $\\frac{1}{2}$: 짝수가 2개, 홀수가 3개이므로 단순히 비율로 계산한 오류\n- ⑤ $\\frac{3}{5}$: 홀수인 경우(1, 3, 5)의 확률로 계산한 오류\n\n**[핵심 포인트]**\n\n세 자리 수가 짝수인지 판정하는 것은 **일의 자리만 확인**하면 되며, 일의 자리에 짝수가 올 확률을 구하는 문제이다. 일의 자리부터 먼저 정하는 방법으로 접근하면 계산이 간단해진다.",
