    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n1. **가위바위보의 확률**: 가위바위보에서 A가 이길 확률, 질 확률, 비길 확률은 각각 $\\frac{1}{3}$이다.\n\n2. **원형 순열**: $n$명이 원형으로 앉는 경우의 수는 한 사람을 고정하고 나머지를 배열하는 것으로 $(n-1)!$이다. 이는 회전을 같은 것으로 간주하기 때문이다.\n\n**[풀이]**\n\n**Step 1: 가위바fitzgerald보에서 A가 이길 확률 구하기**\n\n가위바위보는 3가지 경우(가위, 바위, 보)가 있고, 각각 동등한 확률을 가진다.\n- A가 보를 내고 B가 바위를 낼 확률: $\\frac{1}{3} \\times \\frac{1}{3} = \\frac{1}{9}$\n- A가 바위를 내고 B가 가위를 낼 확률: $\\frac{1}{3} \\times \\frac{1}{3} = \\frac{1}{9}$\n- A가 가위를 내고 B가 보를 낼 확률: $\\frac{1}{3} \\times \\frac{1}{3} = \\frac{1}{9}$\n\n따라서 A가 이길 확률 $p = \\frac{1}{9} + \\frac{1}{9} + \\frac{1}{9} = \\frac{3}{9} = \\frac{1}{3}$\n\n**Step 2: 5명이 원형으로 앉는 경우의 수 구하기**\n\n원형 순열에서는 회전을 같은 것으로 간주한다. \n- 일렬로 앉히는 경우: $5!$\n- 원형으로 앉히는 경우: 한 사람을 고정하고 나머지 4명을 배열\n\n따라서 $n = (5-1)! = 4! = 24$\n\n**Step 3: $n \\times p$ 계산하기**\n\n$$n \\times p = 24 \\times \\frac{1}{3} = \\frac{24}{3} = 8$$\n\n**[정답 확인]**\n\n$n = 24$, $p = \\frac{1}{3}$이므로 $n \\times p = 8$이다. 정답은 ③번이다.\n\n**[오답 분석]**\n\n- **①번 (4)**: $n \\times p = 12 \\times \\frac{1}{3}$으로 계산한 경우로, 원형 순열을 $4!$ 대신 다른 값으로 잘못 계산했을 때 나타난다.\n\n- **②번 (6)**: $n \\times p = 18 \\times \\frac{1}{3}$의 경우인데, 이는 원형 순열을 올바르게 계산하지 않은 오류이다.\n\n- **④번 (10)**: 확률 $p$를 $\\frac{1}{2}$로 잘못 이해하거나 $n = 30$으로 잘못 계산한 경우이다.\n\n- **⑤번 (12)**: $n \\times p = 36 \\times \\frac{1}{3}$으로 원형 순열을 $5! = 120$의 일부로 잘못 해석했을 경우이다.\n\n**[핵심 포인트]**\n\n1. **가위바위보의 확률**: A가 이길 확률은 정확히 $\\frac{1}{3}$이다 (3가지 이기는 방법 × $\\frac{1}{9}$ 각각).\n\n2. **원형 순열의 기본**: $n$명의 원형 순열은 $(n-1)!$이며, 이는 한 사람을 기준점으로 고정하고 나머지를 배열하기 때문이다.",
