    "problem": "주사위를 2번 던져 나온 눈의 수를 차례로 $a$, $b$라 하자. 순서쌍 $(a, b)$에서 $a + b \\leq 4$인 경우의 수를 $k$라 할 때, $\\frac{k}{36}$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 6,
    "explanation": "**[핵심 개념]**\n주사위를 2번 던질 때 나올 수 있는 모든 경우의 수는 $6 \\times 6 = 36$가지이다. 이 문제에서는 조건 $a + b \\leq 4$를 만족하는 순서쌍 $(a, b)$의 개수를 구한 후, 확률 형태로 나타내야 한다. 여기서 $a, b$는 각각 1 이상 6 이하의 자연수이다.\n\n**[풀이]**\n\n**1단계: 조건 분석**\n$a + b \\leq 4$를 만족하려면 $a + b$의 값이 2, 3, 또는 4여야 한다.\n($a \\geq 1, b \\geq 1$이므로 $a + b$의 최솟값은 2이다)\n\n**2단계: 각 경우의 수 계산**\n\n$a + b = 2$인 경우:\n$$a + b = 2 \\Rightarrow (a, b) = (1, 1)$$\n→ 1가지\n\n$a + b = 3$인 경우:\n$$a + b = 3 \\Rightarrow (a, b) = (1, 2), (2, 1)$$\n→ 2가지\n\n$a + b = 4$인 경우:\n$$a + b = 4 \\Rightarrow (a, b) = (1, 3), (2, 2), (3, 1)$$\n→ 3가지\n\n**3단계: 전체 경우의 수 구하기**\n$$k = 1 + 2 + 3 = 6$$\n\n**4단계: 확률 계산**\n$$\\frac{k}{36} = \\frac{6}{36} = \\frac{1}{6}$$\n\n따라서 답은 $\\boxed{6}$이다.\n\n**[정답 확인]**\n조건을 만족하는 순서쌍이 정확히 6가지이므로, $k = 6$이 맞고, 이를 36으로 나누면 $\\frac{1}{6}$이 되어 정답이다.\n\n**[오답 분석]**\n- 1: $a + b = 2$인 경우만 센 경우\n- 3: $a + b = 3$인 경우만 센 경우 \n- 4: $a + b = 4$인 경우만 센 경우\n- 5: 계산 실수로 한 가지를 빠뜨린 경우\n\n**[핵심 포인트]**\n조건부등식 $a + b \\leq 4$는 여러 경우로 나뉘므로, 각 등호 경우를 나누어 순서쌍을 체계적으로 나열하는 것이 중요하다. 주사위의 눈이 1부터 6까지임을 항상 기억해야 한다.",
