    "type": "복합 킬러",
    "problem": "어느 공장에서 생산되는 제품의 불량률은 $0.1$이다. 이 공장에서 생산된 제품 중 10개를 임의로 선택할 때, 불량품이 2개 이상일 확률을 $P$라 하자. $P = 1 - \\left(\\frac{9}{10}\\right)^{10} - {}_{10}C_1 \\left(\\frac{1}{10}\\right) \\left(\\frac{9}{10}\\right)^{9}$일 때, $P$의 값에 가장 가까운 것은? (단, $0.9^{10} \\approx 0.349$, $0.9^{9} \\approx 0.387$로 계산한다.)",
    "answerType": "choice",
    "choices": [
      "① 0.164",
      "② 0.194",
      "③ 0.224",
      "④ 0.264",
      "⑤ 0.314"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n이 문제는 이항분포(Binomial Distribution)를 다루는 문제이다.\n- 불량률 $p = 0.1$, 양품률 $q = 0.9$, 시행 횟수 $n = 10$\n- \"2개 이상\"의 확률은 여사건을 이용하여 $P(\\text{2개 이상}) = 1 - P(\\text{0개}) - P(\\text{1개})$로 계산한다.\n- 이항분포의 확률질량함수: $P(X=k) = {}_nC_k p^k q^{n-k}$\n\n**[풀이]**\n\n**Step 1: 상황 파악**\n- 제품 10개 중 불량품의 개수를 $X$라 하면, $X \\sim B(10, 0.1)$\n- 구하는 확률: $P(X \\geq 2) = 1 - P(X=0) - P(X=1)$\n\n**Step 2: $P(X=0)$ 계산**\n\n$$P(X=0) = {}_{10}C_0 \\left(\\frac{1}{10}\\right)^0 \\left(\\frac{9}{10}\\right)^{10} = \\left(\\frac{9}{10}\\right)^{10} = (0.9)^{10}$$\n\n주어진 조건에서: $P(X=0) = 0.349$\n\n**Step 3: $P(X=1)$ 계산**\n\n$$P(X=1) = {}_{10}C_1 \\left(\\frac{1}{10}\\right)^1 \\left(\\frac{9}{10}\\right)^9 = 10 \\times \\frac{1}{10} \\times (0.9)^9$$\n\n$$= (0.9)^9$$\n\n주어진 조건에서: $P(X=1) = 0.387$\n\n**Step 4: $P(X \\geq 2)$ 계산**\n\n$$P = 1 - P(X=0) - P(X=1)$$\n\n$$= 1 - (0.9)^{10} - {}_{10}C_1 \\left(\\frac{1}{10}\\right)\\left(\\frac{9}{10}\\right)^9$$\n\n$$= 1 - 0.349 - 0.387$$\n\n$$= 1 - 0.736 = 0.264$$\n\n**[정답 확인]**\n\n계산 결과 $P = 0.264$로 정답 ④번과 정확히 일치한다.\n\n**[오답 분석]**\n\n① 0.164: $1 - 0.349 - 0.387 = 0.264$이므로, 0.1을 뺀 잘못된 계산\n② 0.194: $0.9^{10}$을 잘못 적용하거나 중간 계산 오류\n③ 0.224: 근사값 적용 시 계산 실수\n⑤ 0.314: 여사건을 제대로 적용하지 않고 다른 확률값을 사용한 경우\n\n**[핵심 포인트]**\n\n- **여사건의 활용**: \"2개 이상\"은 여사건으로 $1 - P(0) - P(1)$로 계산하는 것이 효율적\n- **이항계수**: ${}_{10}C_1 = 10$이므로 $P(X=1) = 10 \\times 0.1 \\times (0.9)^9 = (0.9)^9$로 단순화됨",
