    "explanation": "**[핵심 개념]**\n\n확률변수 $X$가 이항분포 $B(n,p)$를 따를 때, 다음의 성질을 이용한다.\n- 기댓값: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n이 두 식을 연립하여 $n$과 $p$를 구한다.\n\n**[풀이]**\n\n**단계 1: 주어진 조건으로 연립방정식 세우기**\n\n$$E(X) = np = 6 \\cdots (1)$$\n$$V(X) = np(1-p) = 2 \\cdots (2)$$\n\n**단계 2: $p$ 구하기**\n\n식 (2)를 전개하면:\n$$np(1-p) = 2$$\n$$np - np^2 = 2$$\n\n식 (1)에서 $np = 6$을 대입:\n$$6 - 6p = 2$$\n$$6p = 4$$\n$$p = \\frac{2}{3}$$\n\n**단계 3: $n$ 구하기**\n\n식 (1)에 $p = \\frac{2}{3}$을 대입:\n$$n \\times \\frac{2}{3} = 6$$\n$$n = 9$$\n\n**단계 4: ${}_nC_2 \\times p$ 계산하기**\n\n$${}_nC_2 = {}_9C_2 = \\frac{9 \\times 8}{2 \\times 1} = 36$$\n\n$${}_nC_2 \\times p = 36 \\times \\frac{2}{3} = 24$$\n\n**[정답 확인]**\n\n$n=9, p=\\frac{2}{3}$일 때 $E(X) = 9 \\times \\frac{2}{3} = 6$, $V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = 2$로 주어진 조건을 만족하며, ${}_9C_2 \\times \\frac{2}{3} = 36 \\times \\frac{2}{3} = 24$이다.\n\n**[오답 분석]**\n\n- ① 9: $n$의 값과 혼동. ${}_nC_2$를 계산하지 않음\n- ② 12: ${}_nC_2 = 36$을 $\\frac{1}{3}$으로 곱한 경우\n- ③ 18: ${}_nC_2 = 36$을 $\\frac{1}{2}$으로 곱한 경우\n- ⑤ 27: 계산 오류로 $n \\times p = 9 \\times 3 = 27$로 착각한 경우\n\n**[핵심 포인트]**\n\n이항분포의 기댓값과 분산 공식을 정확히 기억하고, 주어진 두 조건을 연립방정식으로 풀어 $n$과 $p$를 동시에 구하는 것이 중요하다. 특히 분산 공식에서 $np(1-p)$를 올바르게 적용해야 한다.",
