    "explanation": "**[핵심 개념]**\n조건부확률은 특정 조건이 주어졌을 때의 확률을 의미한다. 조건부확률의 정의는 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$이다. 비복원추출에서는 한 번 뽑은 공을 다시 넣지 않으므로, 두 번째 뽑을 때 주머니 안의 공의 개수와 구성이 달라진다.\n\n**[풀이]**\n\n**1단계: 초기 상태 파악**\n- 흰 공: 5개, 검은 공: 3개, 총 8개\n- 비복원추출이므로 첫 번째 결과에 따라 두 번째 상황이 달라짐\n\n**2단계: $P_1$ 계산 (첫 번째가 흰 공일 때, 두 번째도 흰 공일 확률)**\n\n첫 번째에 흰 공을 뽑으면:\n- 남은 공의 상태: 흰 공 4개, 검은 공 3개, 총 7개\n\n따라서 \n$$P_1 = \\frac{4}{7}$$\n\n**3단계: $P_2$ 계산 (첫 번째가 검은 공일 때, 두 번째가 흰 공일 확률)**\n\n첫 번째에 검은 공을 뽑으면:\n- 남은 공의 상태: 흰 공 5개, 검은 공 2개, 총 7개\n\n따라서 \n$$P_2 = \\frac{5}{7}$$\n\n**4단계: $P_1 + P_2$ 계산**\n\n$$P_1 + P_2 = \\frac{4}{7} + \\frac{5}{7} = \\frac{9}{7}$$\n\n**[정답 확인]**\n첫 번째 추출 결과에 관계없이 두 번째에 남은 공은 항상 7개이고, $P_1 + P_2 = \\frac{4}{7} + \\frac{5}{7} = \\frac{9}{7}$이므로 정답은 ③이다.\n\n**[오답 분석]**\n- ① $\\frac{5}{7}$: $P_2$의 값만 선택한 경우\n- ② $\\frac{34}{49}$: 분수를 더할 때 통분을 잘못하거나 분자를 잘못 계산한 경우\n- ④ $\\frac{39}{49}$: 분모를 8×8=64로 잘못 계산하거나 다른 계산 오류\n- ⑤ $\\frac{41}{49}$: 계산 과정의 다른 실수\n\n**[핵심 포인트]**\n비복원추출에서는 각 단계마다 남은 공의 개수를 정확히 파악해야 한다. 이 문제에서는 첫 번째 결과와 관계없이 두 번째 추출 시 항상 7개의 공이 남아있다는 점이 중요하다.",
