    "problem": "확률변수 $X$가 정규분포 $N(50, 5^2)$을 따른다. $P(X \\leq a) = P(X \\geq 2a - 30)$을 만족하는 $a$의 값을 구한 후, 이항분포 $B(a, 0.5)$의 분산을 구하시오.",
    "answerType": "choice",
