    "_type": "killer",
    "type": "복합 킬러",
    "problem": "확률변수 $X$가 이항분포 $B(8, p)$를 따르고, $P(X=2) = P(X=6)$일 때, $V(X)$의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n,p)$를 따르는 확률변수 $X$에 대해:\n- 확률질량함수: $P(X=k) = \\binom{n}{k}p^k(1-p)^{n-k}$\n- 대칭성: $P(X=k) = P(X=n-k)$일 때, $p = 1-p$ (즉, $p=\\frac{1}{2}$)\n- 분산: $V(X) = np(1-p)$\n\n**[풀이]**\n\n**1단계: 조건 $P(X=2) = P(X=6)$ 해석**\n\n$X \\sim B(8,p)$이므로:\n$$P(X=2) = \\binom{8}{2}p^2(1-p)^6$$\n$$P(X=6) = \\binom{8}{6}p^6(1-p)^2$$\n\n$P(X=2) = P(X=6)$이므로:\n$$\\binom{8}{2}p^2(1-p)^6 = \\binom{8}{6}p^6(1-p)^2$$\n\n**2단계: $\\binom{8}{2} = \\binom{8}{6}$ 확인**\n\n$$\\binom{8}{2} = \\frac{8!}{2!6!} = 28, \\quad \\binom{8}{6} = \\frac{8!}{6!2!} = 28$$\n\n따라서:\n$$p^2(1-p)^6 = p^6(1-p)^2$$\n\n**3단계: $p$ 구하기**\n\n양변을 $p^2(1-p)^2$으로 나누면 ($p \\neq 0, 1$):\n$$(1-p)^4 = p^4$$\n\n양변에 4제곱근을 취하면:\n$$1-p = p \\quad \\text{또는} \\quad 1-p = -p$$\n\n두 번째 경우는 $1=0$이므로 불가능하고, 첫 번째 경우에서:\n$$1-p = p$$\n$$p = \\frac{1}{2}$$\n\n**4단계: 분산 계산**\n\n$$V(X) = np(1-p) = 8 \\times \\frac{1}{2} \\times \\frac{1}{2} = 8 \\times \\frac{1}{4} = 2$$\n\n**[정답 확인]**\n\n$p=\\frac{1}{2}$일 때 $P(X=2) = \\binom{8}{2}\\left(\\frac{1}{2}\\right)^8 = P(X=6)$이 성립하고, $V(X) = 8 \\times \\frac{1}{4} = 2$이다.\n\n**[오답 분석]**\n\n선택지가 제시되지 않았으나, 일반적인 오답:\n- **1**: $V(X) = np$만 계산한 경우\n- **4**: $V(X) = n(1-p)$만 계산한 경우\n- **8**: $V(X) = np$에서 $p=1$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n$P(X=k) = P(X=n-k)$ 조건은 이항분포의 **대칭성**을 나타내며, 이는 $p=\\frac{1}{2}$일 때만 성립한다는 것을 기억하자. 분산은 반드시 $V(X) = np(1-p)$로 계산해야 한다.",
