    "explanation": "**[핵심 개념]**\n5지선다 문제에서 찍어서 맞힐 확률은 $p = \\frac{1}{5}$이고, 4개 문제를 푸는 것은 각각 독립 시행이다. 따라서 $X$는 성공확률 $p = \\frac{1}{5}$, 시행횟수 $n = 4$인 이항분포 $B(4, \\frac{1}{5})$를 따릅니다. $E(X^2)$를 구하기 위해 분산 공식 $V(X) = E(X^2) - [E(X)]^2$를 활용한다.\n\n**[풀이]**\n\n$X \\sim B(4, \\frac{1}{5})$이므로, 이항분포의 성질에 의해:\n\n$$E(X) = np = 4 \\times \\frac{1}{5} = \\frac{4}{5}$$\n\n$$V(X) = np(1-p) = 4 \\times \\frac{1}{5} \\times \\frac{4}{5} = \\frac{16}{25}$$\n\n분산의 정의에서:\n$$V(X) = E(X^2) - [E(X)]^2$$\n\n따라서:\n$$E(X^2) = V(X) + [E(X)]^2$$\n\n$$E(X^2) = \\frac{16}{25} + \\left(\\frac{4}{5}\\right)^2$$\n\n$$E(X^2) = \\frac{16}{25} + \\frac{16}{25} = \\frac{32}{25}$$\n\n문제에서 요구하는 것은 $E(X^2)$에 25를 곱한 값이므로:\n\n$$E(X^2) \\times 25 = \\frac{32}{25} \\times 25 = 32$$\n\n**[정답 확인]**\n이항분포의 분산 공식과 $E(X^2) = V(X) + [E(X)]^2$ 관계식을 정확히 적용하여 $E(X^2) = \\frac{32}{25}$를 얻었고, 25를 곱하면 32가 된다.\n\n**[오답 분석]**\n객관식 선택지가 제시되지 않았으나, 다음과 같은 오류가 가능한다:\n- $E(X^2) = [E(X)]^2$로 잘못 계산하면 $\\frac{16}{25} \\times 25 = 16$\n- $V(X)$만 25배하면 $16$\n- $E(X) \\times 25 = 20$\n- 모두 정답 32와 다릅니다.\n\n**[핵심 포인트]**\n$E(X^2) \\neq [E(X)]^2$임을 기억하기. 항상 $E(X^2) = V(X) + [E(X)]^2$ 공식을 이용하여 $E(X^2)$을 구해야 한다.",
