    "type": "복합 킬러",
    "problem": "A, B 두 상자가 있다. A에는 1, 2, 3이 적힌 카드가, B에는 4, 5, 6이 적힌 카드가 하나씩 들어 있다. 각 상자에서 카드를 1장씩 꺼내어 두 수의 곱이 짝수일 확률을 구하시오. (답은 분모가 9인 기약분수의 분자를 답하시오.)",
    "answerType": "short",
    "choices": null,
    "answer": 7,
    "explanation": "**[핵심 개념]**\n두 수의 곱이 짝수가 되는 조건은 \"**최소한 하나 이상의 수가 짝수**\"일 때이다. 여사건을 이용하면 \"곱이 홀수일 확률\"을 구한 후 1에서 빼는 방법이 효율적이다. 곱이 홀수가 되려면 \"**두 수 모두 홀수**\"여야 한다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n- A 상자에서 1장: 3가지\n- B 상자에서 1장: 3가지\n- 전체 경우의 수: $3 \\times 3 = 9$가지\n\n**Step 2: 곱이 홀수인 경우의 수 (여사건 이용)**\n\n곱이 홀수가 되려면 두 수 모두 홀수여야 한다.\n\n- A 상자에서 홀수: 1, 3 (2개)\n- B 상자에서 홀수: 5 (1개)\n- 곱이 홀수인 경우: $2 \\times 1 = 2$가지\n\n구체적으로:\n- $(1, 5)$: $1 \\times 5 = 5$ (홀수) ✓\n- $(3, 5)$: $3 \\times 5 = 15$ (홀수) ✓\n\n**Step 3: 곱이 짝수인 경우의 수**\n\n$$\\text{곱이 짝수인 경우} = \\text{전체} - \\text{곱이 홀수인 경우}$$\n$$= 9 - 2 = 7\\text{가지}$$\n\n**Step 4: 확률 계산**\n\n$$P(\\text{곱이 짝수}) = \\frac{7}{9}$$\n\n분모가 9인 기약분수이므로, 분자는 **7**\n\n**[정답 확인]**\n곱이 짝수일 확률은 $\\frac{7}{9}$이고, 기약분수의 분자는 7이다.\n\n**[오답 분석]**\n- **2**: 곱이 홀수인 경우의 수만 센 경우\n- **4, 5, 6, 8**: 곱이 짝수인 경우를 잘못 센 경우 (예: 짝수만 센 경우)\n- **9**: 전체 경우의 수를 답한 경우\n\n**[핵심 포인트]**\n곱이 짝수일 확률은 여사건(곱이 홀수)을 이용하면 간단한다. **홀수 × 홀수 = 홀수**가 유일한 홀수 조건이므로, 이 경우만 찾으면 된다.",
