    "answer": 1,
    "explanation": "**[핵심 개념]**\n정규분포의 대칭성과 표준정규분포의 성질을 이용하는 문제이다.\n\n1. 정규분포 $N(m, \\sigma^2)$는 평균 $m$을 중심으로 좌우 대칭이다.\n2. $P(X \\leq a) = P(X \\geq b)$이면 $a$와 $b$는 평균 $m$을 중심으로 대칭이므로 $m = \\frac{a+b}{2}$이다.\n3. 표준정규분포에서 $P(0 \\leq Z \\leq 1) = 0.3413$은 평균으로부터 표준편차 1개 범위의 절반이다.\n4. 정규분포의 표준화: $Z = \\frac{X-m}{\\sigma}$\n\n**[풀이]**\n\n**Step 1: 평균 구하기**\n\n$P(X \\leq 14) = P(X \\geq 26)$이라는 조건에서, 정규분포의 대칭성에 의해 14와 26은 평균 $m$을 중심으로 대칭이다.\n\n따라서:\n$$m = \\frac{14 + 26}{2} = \\frac{40}{2} = 20$$\n\n**Step 2: 표준편차 구하기**\n\n주어진 조건 $P(m - \\sigma \\leq X \\leq m + \\sigma) = 0.6826$을 이용한다.\n\n표준화하면:\n$$P\\left(\\frac{m-\\sigma-m}{\\sigma} \\leq Z \\leq \\frac{m+\\sigma-m}{\\sigma}\\right) = P(-1 \\leq Z \\leq 1) = 0.6826$$\n\n표준정규분포의 대칭성에 의해:\n$$P(-1 \\leq Z \\leq 1) = 2 \\times P(0 \\leq Z \\leq 1) = 2 \\times 0.3413 = 0.6826$$\n\n이는 주어진 조건과 일치하므로, $\\sigma$값은 구체적으로 구할 필요 없고 위 관계식이 성립함을 확인했다.\n\n**Step 3: $P(14 \\leq X \\leq 26)$ 계산하기**\n\n$m = 20$에서 14와 26까지의 거리는:\n- $14 = m - 6 = 20 - 6$\n- $26 = m + 6 = 20 + 6$\n\n표준화하면:\n$$\\frac{14-20}{\\sigma} = \\frac{-6}{\\sigma}, \\quad \\frac{26-20}{\\sigma} = \\frac{6}{\\sigma}$$\n\n따라서:\n$$P(14 \\leq X \\leq 26) = P\\left(\\frac{-6}{\\sigma} \\leq Z \\leq \\frac{6}{\\sigma}\\right)$$\n\n14와 26이 20을 중심으로 대칭이므로, 이들이 $m-\\sigma$와 $m+\\sigma$로부터의 관계를 파악한다.\n\n$14 = m - 6$이고 $26 = m + 6$이므로:\n$$P(14 \\leq X \\leq 26) = P(m-6 \\leq X \\leq m+6)$$\n\n$m - \\sigma \\leq X \\leq m + \\sigma$ 범위에서 $P = 0.6826$이고, 14와 26은 각각 $m-6$과 $m+6$이다.\n\n정규분포의 대칭성을 고려하면:\n$$P(14 \\leq X \\leq 26) = P(m-6 \\leq X \\leq m+6)$$\n\n$6 = \\sigma$인 경우, $P(m-\\sigma \\leq X \\leq m+\\sigma) = 0.6826$이 성립하므로:\n\n$$P(14 \\leq X \\leq 26) = 0.6826$$\n\n**[정답 확인]**\n$P(X \\leq 14) = P(X \\geq 26)$에서 평균이 20이고, 14와 26이 평균으로부터 같은 거리에 있으므로, 이들이 바로 $m \\pm \\sigma$의 범위이며, 주어진 조건 $P(m-\\sigma \\leq X \\leq m+\\sigma) = 0.6826$이 $P(14 \\leq X \\leq 26)$과 일치한다.\n\n**[오답 분석]**\n- ① 0.5000: 평균에서 한쪽만의 확률\n- ③ 0.7500: 특정한 의미 없음\n- ④ 0.8164: $P(-2 \\leq Z \\leq 2)$ 정도에 해당하는 값으로, 범위가 더 큼\n- ⑤ 0.9544: $P(-2 \\leq Z \\leq 2) = 0.9544$로, 문제에서 구하는 범위보다 더 넓음\n\n**[핵심 포인트]**\n정규분포에서 $P(X \\leq a) = P(X \\geq b)$는 평균을 중심으로 대칭이라는 의미이므로 평균을 즉시 구한다. 주어진 $P(m-\\sigma \\leq X \\leq m+\\sigma) = 0.6826$이 바로 구하는 구간의 확률이 되는지 확인하는 것이 핵심이다.",
