    "answer": 3,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률을 구하는 문제이다. 전체 사건이 \"안경을 착용한 학생\"으로 제한되었을 때, 그 중에서 \"남학생일 확률\"을 구해야 한다. \n\n조건부 확률의 공식: $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$\n\n이를 적용하면: $P(\\text{남학생}|\\text{안경착용}) = \\frac{P(\\text{남학생 AND 안경착용})}{P(\\text{안경착용})}$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 남학생 비율: $60\\% = 0.6$\n- 여학생 비율: $40\\% = 0.4$\n- 남학생 중 안경 착용 비율: $40\\% = 0.4$\n- 여학생 중 안경 착용 비율: $30\\% = 0.3$\n\n**2단계: 남학생이면서 안경을 착용할 확률**\n$$P(\\text{남학생 AND 안경착용}) = 0.6 \\times 0.4 = 0.24$$\n\n**3단계: 여학생이면서 안경을 착용할 확률**\n$$P(\\text{여학생 AND 안경착용}) = 0.4 \\times 0.3 = 0.12$$\n\n**4단계: 전체 학생 중 안경을 착용할 확률**\n$$P(\\text{안경착용}) = P(\\text{남학생 AND 안경착용}) + P(\\text{여학생 AND 안경착용})$$\n$$= 0.24 + 0.12 = 0.36$$\n\n**5단계: 조건부 확률 계산**\n$$P(\\text{남학생}|\\text{안경착용}) = \\frac{P(\\text{남학생 AND 안경착용})}{P(\\text{안경착용})} = \\frac{0.24}{0.36}$$\n\n**6단계: 기약분수로 변환**\n$$\\frac{0.24}{0.36} = \\frac{24}{36} = \\frac{2}{3}$$\n\n**[정답 확인]**\n안경을 착용한 학생 중에서 남학생의 비율은 남학생 안경착용자 24명과 여학생 안경착용자 12명의 비로 $24:12 = 2:1$이므로, 확률은 $\\frac{2}{3}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{3}$: 여학생의 조건부 확률인 $\\frac{0.12}{0.36} = \\frac{1}{3}$과 혼동\n- ② $\\frac{2}{5}$: 전체 계산 과정에서 실수하여 나온 값\n- ③ $\\frac{1}{2}$: 남학생과 여학생을 단순히 반반으로 생각한 경우\n- ⑤ $\\frac{3}{4}$: 분자와 분모를 잘못 계산한 경우\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 \"전체\"를 올바르게 파악해야 한다. 이 문제에서 전체는 \"전체 학생\"이 아니라 \"안경을 착용한 학생\"이다. 따라서 안경 착용자 중 남학생의 비율을 구해야 한다.",
