    "problem": "집합 $\\{1, 2, 3, 4, 5, 6, 7\\}$에서 서로 다른 3개의 수를 선택하여 만든 집합을 $A$라 하자. $A$의 원소의 합이 12 이상이면서 $A$에 연속하는 두 자연수가 포함되지 않을 확률은?",
