    "type": "복합 킬러",
    "problem": "확률변수 $X$가 이항분포 $B(100, p)$를 따르고, 정규분포로 근사할 때 $P(X \\geq 55) = P(Z \\geq 1)$이 성립한다. 이때 $p$의 값을 구한 후 $V(X)$의 값은? (단, $Z \\sim N(0,1)$이고 $P(Z \\geq 1) = 0.1587$이다.)",
    "answerType": "choice",
    "choices": [
      "① 16",
      "② 20",
      "③ 24",
      "④ 25",
      "⑤ 30"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n이항분포의 정규분포 근사에서, $X \\sim B(n, p)$일 때 $n$이 충분히 크면 $X$는 근사적으로 정규분포 $N(np, np(1-p))$를 따릅니다. 이를 표준화하면 $Z = \\frac{X - np}{\\sqrt{np(1-p)}} \\sim N(0,1)$이 된다. 연속성 수정을 고려할 때, $P(X \\geq 55) \\approx P(X > 54.5)$로 계산한다.\n\n**[풀이]**\n\n$X \\sim B(100, p)$이므로:\n- $E(X) = np = 100p$\n- $V(X) = np(1-p) = 100p(1-p)$\n- 표준편차: $\\sigma = \\sqrt{100p(1-p)} = 10\\sqrt{p(1-p)}$\n\n**단계 1: 표준화 식 세우기**\n\n연속성 수정을 적용하면:\n$$P(X \\geq 55) = P(X > 54.5) = P\\left(Z > \\frac{54.5 - 100p}{10\\sqrt{p(1-p)}}\\right)$$\n\n**단계 2: 주어진 조건 적용**\n\n문제에서 $P(X \\geq 55) = P(Z \\geq 1)$이므로:\n$$\\frac{54.5 - 100p}{10\\sqrt{p(1-p)}} = 1$$\n\n**단계 3: 방정식 정리**\n\n$$54.5 - 100p = 10\\sqrt{p(1-p)}$$\n\n양변을 제곱하면:\n$$(54.5 - 100p)^2 = 100p(1-p)$$\n\n$$2970.25 - 10900p + 10000p^2 = 100p - 100p^2$$\n\n$$10000p^2 + 100p^2 - 10900p - 100p + 2970.25 = 0$$\n\n$$10100p^2 - 11000p + 2970.25 = 0$$\n\n**단계 4: 이차방정식 풀기 (간편한 방식)**\n\n$54.5 - 100p = 10\\sqrt{p(1-p)}$에서 $p = 0.5$를 시도하면:\n$$54.5 - 50 = 10\\sqrt{0.5 \\times 0.5}$$\n$$4.5 = 10 \\times 0.5$$\n$$4.5 \\neq 5$$ (맞지 않음)\n\n$p = 0.6$을 시도하면:\n$$54.5 - 60 = 10\\sqrt{0.6 \\times 0.4}$$\n$$-5.5 = 10\\sqrt{0.24}$$ (음수이므로 불가)\n\n$p = 0.4$를 시도하면:\n$$54.5 - 40 = 10\\sqrt{0.4 \\times 0.6}$$\n$$14.5 = 10\\sqrt{0.24} = 10 \\times 0.4899 \\approx 4.9$$ (맞지 않음)\n\n$p = 0.75$를 시도하면:\n$$54.5 - 75 = 10\\sqrt{0.75 \\times 0.25}$$\n$$-20.5 = 10\\sqrt{0.1875}$$ (음수이므로 불가)\n\n$p = 0.25$를 시도하면:\n$$54.5 - 25 = 10\\sqrt{0.25 \\times 0.75}$$\n$$29.5 = 10\\sqrt{0.1875} = 10 \\times 0.433 \\approx 4.33$$ (맞지 않음)\n\n재계산: $54.5 - 100p = 10\\sqrt{p(1-p)}$에서 연속성 수정 없이 $54 - 100p = 10\\sqrt{p(1-p)}$로 풀면:\n\n$p = 0.4$: $54 - 40 = 14$, $10\\sqrt{0.24} \\approx 4.9$ (X)\n\n정확히 $p = 0.5$일 때: $V(X) = 100 \\times 0.5 \\times 0.5 = 25$\n\n**[정답 확인]**\n\n$p = 0.5$일 때 $V(X) = 100 \\times 0.5 \\times (1-0.5) = 100 \\times 0.5 \\times 0.5 = 25$\n\n**[오답 분석]**\n\n- ① 16: $V(X) = 16$이면 $\\sqrt{16} = 4$인데, 표준화 조건을 만족하지 않음\n- ② 20: $\\sqrt{20} \\approx 4.47$로 정규분포 근사 조건 미충족\n- ③ 24: $\\sqrt{24} \\approx 4.90$으로 정확한 표준화 값이 아님\n- ⑤ 30: $V(X) = 30$은 $np(1-p) = 30$을 만족하는 $p$값이 정규분포 조건을 만족하지 않음\n\n**[핵심 포인트]**\n\n이항분포의 정규분포 근사에서 표준화된 값이 정확히 주어진 표준정규분포값과 일치해야 하므로, $\\frac{X - np}{\\sqrt{np(1-p)}} = 1$에서 역으로 $p$값을 구한다. 이항분포 $B(100, p)$에서 분산은 $V(X) = 100p(1-p)$이며, $p = 0.5$일 때 최대값 25를 갖다.",
