    "problem": "양의 정수 $n$에 대하여 $\\sum_{k=0}^{n} {}_nC_k \\cdot 3^k = 4^n$이 성립한다. $\\sum_{k=0}^{8} k \\cdot {}_8C_k \\cdot 3^k$의 값을 $4^6$으로 나눈 값을 구하시오.",
