    "type": "복합 킬러",
    "problem": "확률변수 $X$는 정규분포 $N(\\mu, \\sigma^2)$을 따른다. $n$개의 표본평균 $\\bar{X}$에 대하여 $P(\\bar{X} \\geq \\mu + 1) = P(Z \\geq 2)$이 성립하고, $\\sigma = 4$일 때, 표본의 크기 $n$의 값을 구한 후, 이 $n$명을 원형으로 배열하는 경우의 수를 $m!$로 표현하시오. ($m$의 값을 답하시오.)",
    "answerType": "choice",
    "choices": [
      "① 31",
      "② 47",
      "③ 55",
      "④ 63",
      "⑤ 79"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n1. **표본평균의 분포**: 모집단이 $N(\\mu, \\sigma^2)$을 따를 때, 표본평균 $\\bar{X}$는 $N(\\mu, \\frac{\\sigma^2}{n})$을 따릅니다.\n\n2. **표준화**: $\\bar{X}$를 표준화하면 $Z = \\frac{\\bar{X} - \\mu}{\\sigma/\\sqrt{n}} \\sim N(0,1)$\n\n3. **원형 배열**: $n$개의 서로 다른 원소를 원형으로 배열하는 경우의 수는 $(n-1)!$이다.\n\n**[풀이]**\n\n**Step 1: 표본평균의 표준화**\n\n$\\bar{X} \\sim N(\\mu, \\frac{\\sigma^2}{n})$이므로, 표준화하면:\n\n$$Z = \\frac{\\bar{X} - \\mu}{\\sigma/\\sqrt{n}}$$\n\n**Step 2: 주어진 확률 조건 적용**\n\n$$P(\\bar{X} \\geq \\mu + 1) = P(Z \\geq 2)$$\n\n좌변을 표준화하면:\n\n$$P\\left(\\frac{\\bar{X} - \\mu}{\\sigma/\\sqrt{n}} \\geq \\frac{1}{\\sigma/\\sqrt{n}}\\right) = P(Z \\geq 2)$$\n\n$$P\\left(Z \\geq \\frac{\\sqrt{n}}{\\sigma}\\right) = P(Z \\geq 2)$$\n\n**Step 3: 표준정규분포의 성질 이용**\n\n두 확률이 같으므로:\n\n$$\\frac{\\sqrt{n}}{\\sigma} = 2$$\n\n**Step 4: $n$ 구하기**\n\n$\\sigma = 4$를 대입하면:\n\n$$\\frac{\\sqrt{n}}{4} = 2$$\n\n$$\\sqrt{n} = 8$$\n\n$$n = 64$$\n\n**Step 5: 원형 배열의 경우의 수**\n\n64명을 원형으로 배열하는 경우의 수는:\n\n$$(64-1)! = 63!$$\n\n따라서 $m = 63$\n\n**[정답 확인]**\n\n표본평균의 표준화 공식을 올바르게 적용하여 $n=64$를 구하고, 원형 배열의 공식 $(n-1)!$을 적용하여 $m=63$을 얻으므로 정답은 ④이다.\n\n**[오답 분석]**\n\n- **①31**: $n = 64$에서 $64-1=63$이 아닌 다른 계산 오류\n- **②47**: 표준화 과정에서 분모/분자를 잘못 설정한 경우\n- **③55**: $n$ 값을 잘못 계산한 경우 (예: $n=56$에서 $m=55$)\n- **⑤79**: $n$을 과도하게 크게 계산하거나 $(n-1)!$이 아닌 다른 공식 적용\n\n**[핵심 포인트]**\n\n1. 표본평균의 분포에서 표준화할 때 분모는 $\\frac{\\sigma}{\\sqrt{n}}$임을 명확히 해야 한다.\n2. 원형 배열은 일렬 배열 $n!$과 다르게 회전을 같은 것으로 보아 $(n-1)!$이 됨을 기억해야 한다.",
