    "answer": 2,
    "explanation": "**[핵심 개념]**\n주사위를 여러 번 던질 때 눈의 합이 특정 값이 될 확률을 구하는 문제이다. 주사위 한 번에 나올 수 있는 눈은 1, 2, 3, 4, 5, 6이고, 각 경우의 확률은 $\\frac{1}{6}$이다. 독립사건이므로 곱의 법칙을 적용하며, 가능한 모든 경우를 세어야 한다.\n\n**[풀이]**\n\n**1단계: $S_3 = 10$인 경우의 수 찾기**\n\n주사위를 3번 던져서 눈의 합이 10이 되려면, 세 수 $(a, b, c)$를 찾아야 한다. \n여기서 $1 \\leq a, b, c \\leq 6$이고 $a + b + c = 10$이다.\n\n가능한 경우를 체계적으로 나열하면:\n\n- $a = 1$: $b + c = 9$ → $(1,3,6), (1,4,5), (1,5,4), (1,6,3)$ → 4가지\n- $a = 2$: $b + c = 8$ → $(2,2,6), (2,3,5), (2,4,4), (2,5,3), (2,6,2)$ → 5가지\n- $a = 3$: $b + c = 7$ → $(3,1,6), (3,2,5), (3,3,4), (3,4,3), (3,5,2), (3,6,1)$ → 6가지\n- $a = 4$: $b + c = 6$ → $(4,1,5), (4,2,4), (4,3,3), (4,4,2), (4,5,1)$ → 5가지\n- $a = 5$: $b + c = 5$ → $(5,1,4), (5,2,3), (5,3,2), (5,4,1)$ → 4가지\n- $a = 6$: $b + c = 4$ → $(6,1,3), (6,2,2), (6,3,1)$ → 3가지\n\n총 경우의 수: $4 + 5 + 6 + 5 + 4 + 3 = 27$가지\n\n**2단계: 확률 계산**\n\n주사위를 3번 던지는 전체 경우의 수는 $6^3 = 216$이다.\n\n따라서 $P(S_3 = 10) = \\frac{27}{216}$\n\n**3단계: 최종 답 계산**\n\n$$P(S_3 = 10) \\times 216 = \\frac{27}{216} \\times 216 = 27$$\n\n**[정답 확인]**\n$S_3 = 10$을 만족하는 순서쌍이 정확히 27개이고, 전체 경우의 수가 216이므로, 확률에 216을 곱한 값은 바로 27이다.\n\n**[오답 분석]**\n- ① 21: 경우의 수를 잘못 세었거나 특정 조건을 빼먹은 경우\n- ② 25: 일부 경우만 세었을 가능성 (예: $a=1$일 때 3가지만 센 경우)\n- ④ 30: 범위를 초과하는 경우($a=0$ 등)를 포함했을 가능성\n- ⑤ 36: 전체 경우의 수를 잘못 계산했거나 다른 확률 문제와 혼동\n\n**[핵심 포인트]**\n세 주사위 눈의 합이 특정 값이 되는 경우를 구할 때는 **체계적으로 첫 번째 주사위 값부터 고정하여 나머지 조건을 만족하는 경우를 모두 세는 것**이 중요하다. 또한 확률에 전체 경우의 수($6^3 = 216$)를 곱하면 직접 경우의 수가 되므로 계산 실수를 줄일 수 있다.",
