    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n이 문제는 초기하분포(Hypergeometric Distribution)와 기댓값 계산을 다룹니다.\n\n- **초기하분포**: 전체 $N$개 중 성공 $K$개가 있을 때, $n$개를 뽑아서 성공 개수 $X$의 분포\n- **확률질량함수**: $P(X=k) = \\frac{{}_KC_k \\cdot {}_{N-K}C_{n-k}}{{}_NC_n}$\n- **기댓값**: $E(X) = \\sum k \\cdot P(X=k)$ 또는 초기하분포의 성질 $E(X) = n \\cdot \\frac{K}{N}$\n\n**[풀이]**\n\n**Step 1: 주어진 확률질량함수 해석**\n\n$$P(X = k) = \\frac{{}_5C_k \\cdot {}_5C_{3-k}}{{{}_{10}C_3}}$$\n\n이는 다음을 의미한다:\n- 전체 10개 중 5개, 5개로 나뉨\n- 3개를 뽑되, 첫 번째 그룹에서 $k$개, 두 번째 그룹에서 $(3-k)$개를 뽑음\n- 초기하분포의 형태이다.\n\n**Step 2: 먼저 각 확률 계산**\n\n${{}_{10}C_3} = \\frac{10!}{3!7!} = \\frac{10 \\times 9 \\times 8}{6} = 120$\n\n- $P(X=0) = \\frac{{}_5C_0 \\cdot {}_5C_3}{120} = \\frac{1 \\times 10}{120} = \\frac{10}{120}$\n\n- $P(X=1) = \\frac{{}_5C_1 \\cdot {}_5C_2}{120} = \\frac{5 \\times 10}{120} = \\frac{50}{120}$\n\n- $P(X=2) = \\frac{{}_5C_2 \\cdot {}_5C_1}{120} = \\frac{10 \\times 5}{120} = \\frac{50}{120}$\n\n- $P(X=3) = \\frac{{}_5C_3 \\cdot {}_5C_0}{120} = \\frac{10 \\times 1}{120} = \\frac{10}{120}$\n\n검증: $\\frac{10+50+50+10}{120} = \\frac{120}{120} = 1$ ✓\n\n**Step 3: 기댓값 계산**\n\n$$E(X) = 0 \\times \\frac{10}{120} + 1 \\times \\frac{50}{120} + 2 \\times \\frac{50}{120} + 3 \\times \\frac{10}{120}$$\n\n$$= \\frac{0 + 50 + 100 + 30}{120} = \\frac{180}{120} = \\frac{3}{2}$$\n\n**Step 4: $8 \\times E(X)$ 계산**\n\n$$8 \\times E(X) = 8 \\times \\frac{3}{2} = \\frac{24}{2} = 12$$\n\n**[정답 확인]**\n\n초기하분포의 기댓값 공식으로 검증: $E(X) = n \\times \\frac{K}{N} = 3 \\times \\frac{5}{10} = \\frac{3}{2}$이므로, $8 \\times \\frac{3}{2} = 12$ ✓\n\n**[오답 분석]**\n\n- ① 6: $8 \\times E(X)$를 $8 \\times \\frac{1}{4}$로 잘못 계산한 경우\n- ② 8: $8 \\times E(X)$를 $8 \\times \\frac{1}{3}$로 잘못 계산한 경우\n- ③ 10: 계산 과정에서 확률 합산 실수\n- ⑤ 15: $E(X)$를 $\\frac{15}{8}$로 잘못 구한 경우\n\n**[핵심 포인트]**\n\n- **초기하분포 인식**: 조합으로 표현된 확률질량함수는 초기하분포임을 파악하는 것이 중요\n- **기댓값 공식 활용**: $E(X) = n \\times \\frac{K}{N}$으로 빠르게 계산 가능 (이 경우 $3 \\times \\frac{5}{10} = \\frac{3}{2}$)",
