    "problem": "양의 정수 $n$에 대하여 $(1+x)^n$의 전개식에서 $x^2$의 계수를 $a_n$이라 하자. $\\sum_{n=2}^{\\infty} \\frac{a_n}{2^n}$의 값을 구하시오.",
    "answerType": "short",
