    "answer": 2,
    "explanation": "**[핵심 개념]**\n- 이항정리: $(1+x)^n = \\sum_{k=0}^{n} \\binom{n}{k}x^k$\n- 이항계수에서 $x^2$의 계수는 $\\binom{n}{2}$\n- 무한급수의 합을 구하기 위해 함수의 급수 전개식을 활용\n\n**[풀이]**\n\n**Step 1: $a_n$ 구하기**\n\n$(1+x)^n$의 전개식에서 $x^2$의 계수는:\n$$a_n = \\binom{n}{2} = \\frac{n(n-1)}{2}$$\n\n단, $n \\geq 2$일 때만 $x^2$ 항이 존재한다.\n\n**Step 2: 급수 계산**\n\n$$\\sum_{n=2}^{\\infty} \\frac{a_n}{2^n} = \\sum_{n=2}^{\\infty} \\frac{1}{2^n} \\cdot \\frac{n(n-1)}{2}$$\n\n$$= \\frac{1}{2} \\sum_{n=2}^{\\infty} \\frac{n(n-1)}{2^n}$$\n\n**Step 3: 함수의 급수 전개를 이용**\n\n$f(x) = (1-x)^{-1} = \\sum_{n=0}^{\\infty} x^n$ (단, $|x| < 1$)\n\n양변을 $x$로 미분하면:\n$$f'(x) = (1-x)^{-2} = \\sum_{n=1}^{\\infty} nx^{n-1}$$\n\n다시 양변에 $x$를 곱하면:\n$$xf'(x) = x(1-x)^{-2} = \\sum_{n=1}^{\\infty} nx^n$$\n\n양변을 다시 $x$로 미분하면:\n$$\\frac{d}{dx}[x(1-x)^{-2}] = \\sum_{n=1}^{\\infty} n^2x^{n-1}$$\n\n$(1-x)^{-2} + 2x(1-x)^{-3} = \\sum_{n=1}^{\\infty} n^2x^{n-1}$\n\n양변에 $x$를 곱하면:\n$$x(1-x)^{-2} + 2x^2(1-x)^{-3} = \\sum_{n=1}^{\\infty} n^2x^n$$\n\n**Step 4: $n(n-1)$ 항 구하기**\n\n$\\sum_{n=1}^{\\infty} n(n-1)x^n = \\sum_{n=1}^{\\infty} n^2x^n - \\sum_{n=1}^{\\infty} nx^n$\n\n또는 직접: $g(x) = (1-x)^{-1}$에 대해\n$$\\sum_{n=0}^{\\infty} x^n = (1-x)^{-1}$$\n\n양변을 미분하면: $\\sum_{n=1}^{\\infty} nx^{n-1} = (1-x)^{-2}$\n\n다시 미분하면: $\\sum_{n=2}^{\\infty} n(n-1)x^{n-2} = 2(1-x)^{-3}$\n\n양변에 $x^2$를 곱하면:\n$$\\sum_{n=2}^{\\infty} n(n-1)x^n = 2x^2(1-x)^{-3}$$\n\n**Step 5: $x = \\frac{1}{2}$ 대입**\n\n$$\\sum_{n=2}^{\\infty} n(n-1)\\left(\\frac{1}{2}\\right)^n = 2 \\cdot \\frac{1}{4} \\cdot \\left(1-\\frac{1}{2}\\right)^{-3}$$\n\n$$= \\frac{1}{2} \\cdot \\left(\\frac{1}{2}\\right)^{-3} = \\frac{1}{2} \\cdot 8 = 4$$\n\n**Step 6: 최종 답**\n\n$$\\sum_{n=2}^{\\infty} \\frac{a_n}{2^n} = \\frac{1}{2} \\sum_{n=2}^{\\infty} \\frac{n(n-1)}{2^n} = \\frac{1}{2} \\cdot 4 = 2$$\n\n**[정답 확인]**\n이항계수의 성질과 함수의 미분을 이용한 급수 전개를 통해 무한급수의 합을 구한 결과가 2로 일치한다.\n\n**[오답 분석]**\n- **1**: $\\frac{1}{2}$를 곱하는 단계를 빠뜨린 경우\n- **3**: 부호 오류나 미분 과정에서의 계산 실수\n- **4**: $\\sum n(n-1)x^n$을 잘못 계산한 경우\n\n**[핵심 포인트]**\n$\\sum n(n-1)x^n = 2x^2(1-x)^{-3}$은 중요한 공식이다. 무한급수 문제에서는 기본 함수의 도함수를 이용한 급수 전개가 핵심이다.",
