    "answer": 1,
    "explanation": "**[핵심 개념]**\n같은 것이 있는 순열 문제이다. 전체 $n$개의 원소 중에서 같은 것이 각각 $n_1$개, $n_2$개, ..., $n_k$개 있을 때, 이들을 모두 일렬로 나열하는 경우의 수는 다음 공식으로 구한다:\n$$\\frac{n!}{n_1! \\cdot n_2! \\cdot ... \\cdot n_k!}$$\n\n**[풀이]**\n주어진 문자는 $x, x, y, y, z$로 총 5개이다.\n\n- 전체 문자의 개수: $n = 5$\n- 문자 $x$의 개수: 2개\n- 문자 $y$의 개수: 2개\n- 문자 $z$의 개수: 1개\n\n같은 것이 있는 순열의 공식을 적용하면:\n\n$$\\text{경우의 수} = \\frac{5!}{2! \\cdot 2! \\cdot 1!}$$\n\n각 값을 계산한다:\n- $5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$\n- $2! = 2$\n- $2! = 2$\n- $1! = 1$\n\n따라서:\n$$\\frac{5!}{2! \\cdot 2! \\cdot 1!} = \\frac{120}{2 \\times 2 \\times 1} = \\frac{120}{4} = 30$$\n\n**[정답 확인]**\n5개의 문자 중 같은 문자가 있는 경우의 수는 $\\frac{120}{4} = 30$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ①번(20): $\\frac{5!}{3! \\cdot 2!}$처럼 잘못 계산한 경우\n- ③번(40): $\\frac{5!}{3!}$처럼 한 종류의 같은 것만 고려한 경우\n- ④번(50): 분모를 과소 계산한 경우\n- ⑤번(60): 같은 문자를 구별하여 $\\frac{5!}{1!}$로 계산한 경우\n\n**[핵심 포인트]**\n같은 것이 있는 순열에서는 전체 경우의 수에서 같은 것들의 순열로 나누어야 한다. 이 문제에서는 $x$ 2개, $y$ 2개가 있으므로 각각 $2!$으로 나누는 것이 핵심이다.",
