    "explanation": "**[핵심 개념]**\n같은 것이 있는 순열은 전체 원소의 개수에서 같은 원소들의 개수를 고려하여 계산한다.\n$n$개의 원소 중 같은 것이 각각 $n_1, n_2, \\cdots, n_k$개씩 있을 때, 순열의 개수는 다음 공식으로 구한다:\n$$\\frac{n!}{n_1! \\cdot n_2! \\cdot \\cdots \\cdot n_k!}$$\n\n**[풀이]**\n주어진 다섯 개의 문자: $a, a, a, b, c$\n\n**1단계: 전체 원소의 개수 확인**\n- 전체 5개의 문자가 있다.\n\n**2단계: 같은 원소의 개수 파악**\n- 문자 $a$: 3개 (같은 것)\n- 문자 $b$: 1개\n- 문자 $c$: 1개\n\n**3단계: 같은 것이 있는 순열 공식 적용**\n$$\\frac{5!}{3! \\cdot 1! \\cdot 1!} = \\frac{5!}{3!}$$\n\n**4단계: 계산**\n$$\\frac{5!}{3!} = \\frac{5 \\times 4 \\times 3!}{3!} = 5 \\times 4 = 20$$\n\n따라서 경우의 수는 **20**이다.\n\n**[정답 확인]**\n같은 문자 $a$가 3개 있으므로, 이들을 구별하지 않는 경우의 수를 계산하면 $\\frac{5!}{3!} = 20$이 되어 정답 ②가 맞다.\n\n**[오답 분석]**\n- ① 10: $\\frac{5!}{3! \\times 2!}$로 잘못 계산한 경우 (같은 것이 2개 더 있다고 착각)\n- ③ 30: $5! \\div 4 = 30$으로 잘못 계산한 경우\n- ④ 40: $5 \\times 8$로 임의로 계산한 경우\n- ⑤ 60: $5! = 120$에서 2로 나눈 경우 (분모 계산 오류)\n\n**[핵심 포인트]**\n같은 것이 있는 순열에서는 전체 경우의 수(분자)에서 같은 것들의 개수의 팩토리얼(분모)로 나누는 것이 핵심이다. $a$가 3개이므로 반드시 $3!$로 나누어야 한다.",
