    "explanation": "**[핵심 개념]**\n중복이 있는 원소들을 일렬로 나열하는 경우의 수는 전체 경우의 수에서 중복된 원소들의 중복을 제거해야 한다. 같은 것이 있는 순열의 공식은 :\n\n$$\\frac{n!}{n_1! \\times n_2! \\times \\cdots \\times n_k!}$$\n\n여기서 $n$은 전체 원소의 개수이고, $n_1, n_2, \\ldots, n_k$는 각각 같은 원소의 개수이다.\n\n**[풀이]**\n주어진 문자는 $a, a, b, c, d$로 총 5개이다.\n\n이 중에서:\n- 문자 $a$: 2개 (같은 것)\n- 문자 $b$: 1개\n- 문자 $c$: 1개\n- 문자 $d$: 1개\n\n같은 것이 있는 순열 공식을 적용하면:\n\n$$\\text{경우의 수} = \\frac{5!}{2! \\times 1! \\times 1! \\times 1!}$$\n\n계산 과정:\n$$= \\frac{5!}{2!}$$\n\n$$= \\frac{5 \\times 4 \\times 3 \\times 2 \\times 1}{2 \\times 1}$$\n\n$$= \\frac{120}{2}$$\n\n$$= 60$$\n\n**[정답 확인]**\n5개의 문자 중 같은 문자 $a$가 2개이므로, 전체 순열 $5! = 120$을 $2! = 2$로 나누어 60을 얻는다.\n\n**[오답 분석]**\n- ① 30: $\\frac{5!}{4} = 30$으로, 분모를 잘못 계산한 경우\n- ② 40: 특정 계산 실수로 나타나는 오답\n- ③ 50: 공식을 부정확하게 적용한 경우\n- ⑤ 120: 중복을 고려하지 않고 단순히 $5!$을 계산한 경우 (같은 것이 있다는 조건을 무시)\n\n**[핵심 포인트]**\n같은 것이 있는 순열에서는 반드시 같은 원소의 개수만큼 계승으로 나누어야 한다. 이 문제에서 $a$가 2개이므로 $2!$로 나누는 것이 핵심이다.",
