    "explanation": "**[핵심 개념]**\n같은 것이 있는 순열 문제이다. 전체 $n$개의 원소 중에서 같은 것이 $n_1$개, $n_2$개, ..., $n_k$개씩 있을 때, 이들을 일렬로 나열하는 경우의 수는 다음 공식으로 구한다:\n\n$$\\frac{n!}{n_1! \\times n_2! \\times \\cdots \\times n_k!}$$\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- 나열할 숫자: $1, 1, 2, 3$ (총 4개)\n- 같은 것: 숫자 $1$이 2개\n- 서로 다른 것: 숫자 $2$가 1개, 숫자 $3$이 1개\n\n**Step 2: 같은 것이 있는 순열 공식 적용**\n\n전체 4개를 나열하는데, 같은 숫자 $1$이 2개 있으므로:\n\n$$\\text{경우의 수} = \\frac{4!}{2!}$$\n\n**Step 3: 계산**\n\n$$\\frac{4!}{2!} = \\frac{4 \\times 3 \\times 2 \\times 1}{2 \\times 1} = \\frac{24}{2} = 12$$\n\n**[정답 확인]**\n숫자 1이 2개로 같으므로, 전체 $4! = 24$에서 같은 것 2개의 중복을 제거하여 $24 \\div 2 = 12$가 정답이다.\n\n**[오답 분석]**\n\n- **①번 (6)**: $3! = 6$으로, 숫자 4개 중 3개만 순열한 경우. 전체 개수를 고려하지 않은 오류이다.\n\n- **②번 (8)**: 계산 과정에서의 산술 오류이다. 특별한 논리적 근거가 없다.\n\n- **③번 (10)**: $\\frac{5!}{2!}$ 또는 다른 잘못된 공식을 적용한 경우로 보이다.\n\n- **⑤번 (24)**: 같은 것이 있다는 조건을 무시하고 $4! = 24$로 계산한 경우. 1이 2개라는 점을 반영하지 않았다.\n\n**[핵심 포인트]**\n같은 것이 있는 순열에서는 **전체 순열의 수를 같은 것의 개수의 팩토리얼로 나눕니다.** 이 문제에서 1이 2번 나타나므로 반드시 $2!$로 나누어야 한다.",
