    "explanation": "**[핵심 개념]**\n같은 것이 있는 순열(중복순열)의 공식을 사용한다. $n$개의 원소 중에서 같은 것이 각각 $n_1$개, $n_2$개, ..., $n_k$개 있을 때, 이들을 모두 일렬로 나열하는 경우의 수는 :\n\n$$\\frac{n!}{n_1! \\times n_2! \\times \\cdots \\times n_k!}$$\n\n**[풀이]**\n\n주어진 다섯 개의 숫자: $1, 2, 2, 3, 3$\n\n먼저 각 숫자의 개수를 정리한다:\n- 숫자 1: 1개\n- 숫자 2: 2개 (같은 것)\n- 숫자 3: 2개 (같은 것)\n- 전체: 5개\n\n같은 것이 있는 순열 공식을 적용한다:\n\n$$\\text{경우의 수} = \\frac{5!}{1! \\times 2! \\times 2!}$$\n\n각 팩토리얼을 계산한다:\n- $5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$\n- $1! = 1$\n- $2! = 2 \\times 1 = 2$\n- $2! = 2 \\times 1 = 2$\n\n따라서:\n\n$$\\text{경우의 수} = \\frac{120}{1 \\times 2 \\times 2} = \\frac{120}{4} = 30$$\n\n**[정답 확인]**\n5개의 자리에 1을 배치하고(5가지), 남은 4개 자리에 2를 2개 배치하고($\\binom{4}{2} = 6$), 남은 2개 자리에 3을 배치하면($\\binom{2}{2} = 1$) $5 \\times 6 \\times 1 = 30$이 되어 답이 일치한다.\n\n**[오답 분석]**\n\n- **①번(10)**: $\\frac{5!}{2! \\times 3!}$ 으로 잘못 계산한 경우. 3이 3개라고 잘못 센 오류이다.\n\n- **②번(20)**: $\\frac{5!}{3!} = 20$으로 중복을 제대로 처리하지 않은 경우. 분모에 2!을 하나만 넣은 오류이다.\n\n- **④번(40)**: $\\frac{5!}{1! \\times 2!} = 60$에서 계산 실수하거나, 분모 계산을 잘못한 경우이다.\n\n- **⑤번(60)**: $\\frac{5!}{1! \\times 2!} = 60$으로 한 개의 2!만 나누었을 때의 값. 숫자 3이 2개임을 빠뜨린 오류이다.\n\n**[핵심 포인트]**\n같은 것이 있는 순열에서는 전체 개수의 팩토리얼을 각각 같은 원소의 개수 팩토리얼로 나누어야 한다. 문제에서 주어진 각 원소의 개수를 정확히 파악하는 것이 가장 중요하다.",
