    "answer": 0,
    "explanation": "**[핵심 개념]**\n\n원탁에 앉는 경우의 수는 회전을 같은 것으로 보므로 $(n-1)!$이다. 확률은 \"구하는 경우의 수/전체 경우의 수\"로 구하며, 여사건을 이용하면 계산이 간단할 수 있다. 이 문제에서는 \"A가 B 또는 C와 이웃할 확률\"을 구하므로, 여사건 \"A가 B와도 C와도 이웃하지 않을 확률\"을 구한 후 1에서 빼는 방법을 사용한다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n\n7명이 원탁에 앉는 경우의 수는 회전을 같은 것으로 보므로:\n$$\\text{전체} = (7-1)! = 6! = 720$$\n\n**2단계: 여사건 활용 - A가 B, C 모두와 이웃하지 않는 경우**\n\n여사건으로 접근한다: \"A가 B 또는 C와 이웃할 확률\" = $1 -$ \"A가 B와도 C와도 이웃하지 않을 확률\"\n\nA가 B, C 모두와 이웃하지 않으려면, A의 양옆 자리에 B와 C가 모두 없어야 한다.\n\n**3단계: A를 고정하고 생각**\n\n원탁이므로 A를 한 자리에 고정한다. A의 양옆 2자리가 있고, 나머지 4자리가 있다.\n\nA가 B, C 모두와 이웃하지 않으려면:\n- A의 양옆 2자리에 B, C가 오면 안 된다.\n- 즉, B와 C는 나머지 4자리 중에만 배치되어야 한다.\n\n**4단계: 경우의 수 계산**\n\nA를 고정했을 때, A가 B, C 모두와 이웃하지 않는 경우:\n- A의 양옆이 아닌 나머지 4자리에 B, C를 포함한 6명 중 B, C를 배치: $P(4,2) = 4 \\times 3 = 12$\n- 나머지 4명을 나머지 4자리에 배치: $4! = 24$\n- 경우의 수: $12 \\times 24 = 288$\n\n또는 다르게 계산:\n- A의 양옆 2자리에 올 수 있는 사람: B, C를 제외한 4명 중에서 선택\n- A의 양옆 2자리 배치: $P(4,2) = 4 \\times 3 = 12$\n- 나머지 4명을 4자리에 배치: $4! = 24$\n- 경우의 수: $12 \\times 24 = 288$\n\n**5단계: 확률 계산**\n\nA가 B, C 모두와 이웃하지 않을 확률:\n$$P(\\text{이웃하지 않음}) = \\frac{288}{720} = \\frac{2}{5}$$\n\nA가 B 또는 C와 이웃할 확률:\n$$P(\\text{B 또는 C와 이웃}) = 1 - \\frac{2}{5} = \\frac{3}{5}$$\n\n**[정답 확인]**\n\n여사건을 이용하여 계산한 결과 $\\frac{3}{5}$이므로 정답은 **①번**이다.\n\n**[오답 분석]**\n\n- **②번($\\frac{2}{3}$)**: A의 양옆을 단순히 계산하되, 전체 경우를 잘못 계산한 경우\n- **③번($\\frac{11}{15}$)**: 여사건 확률을 잘못 계산하거나, 중복을 고려하지 않은 경우\n- **④번($\\frac{3}{4}$)**: A의 양옆 2자리 중 최소 하나에 B나 C가 올 확률로 계산하되, 경우의 수를 과다 계산한 경우\n- **⑤번($\\frac{4}{5}$)**: 여사건 확률을 $\\frac{1}{5}$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n원탁 문제에서는 한 사람을 고정하고 나머지를 배치한다. 복잡한 경우는 **여사건**을 이용하면 계산이 간단해진다: \"B 또는 C와 이웃\" = $1 -$ \"B, C 모두와 이웃하지 않음\"",
