    "problem": "1부터 6까지의 자연수가 하나씩 적힌 6개의 의자가 원형으로 놓여 있다. 6명이 의자에 한 명씩 앉을 때, 이웃한 두 의자에 적힌 수의 합이 11이 되는 경우가 없도록 앉는 경우의 수를 구하시오.",
