    "explanation": "**[핵심 개념]**\n중복조합과 중복순열의 차이를 이해해야 한다. 이 문제는 \"중복을 허락하여 4개를 택해 일렬로 나열\"하므로 **중복순열** 문제이다.\n\n$n$개의 서로 다른 것 중에서 중복을 허락하여 $r$개를 택해 일렬로 나열하는 경우의 수는 $n^r$이다.\n\n**[풀이]**\n주어진 조건:\n- 선택할 수 있는 문자: $a, b, c$ (3개)\n- 나열할 개수: 4개\n- 중복 허락\n\n각 자리를 채우는 경우의 수를 단계별로 계산한다.\n\n**첫 번째 자리:** $a, b, c$ 중 하나를 선택 → 3가지\n\n**두 번째 자리:** $a, b, c$ 중 하나를 선택 → 3가지\n(중복을 허락하므로 첫 번째 자리에서 선택한 것을 다시 선택할 수 있음)\n\n**세 번째 자리:** $a, b, c$ 중 하나를 선택 → 3가지\n\n**네 번째 자리:** $a, b, c$ 중 하나를 선택 → 3가지\n\n곱의 법칙에 의해 전체 경우의 수는:\n$$3 \\times 3 \\times 3 \\times 3 = 3^4 = 81$$\n\n또는 중복순열 공식을 직접 적용하면:\n$$n^r = 3^4 = 81$$\n\n**[정답 확인]**\n$3^4 = 81$이므로 정답은 **⑤번**이다.\n\n**[오답 분석]**\n- ① 12: $3 \\times 4 = 12$로, 순열의 기본 개념을 혼동한 경우\n- ② 24: $4! = 24$로, 4개 문자를 모두 다르다고 가정하고 계산한 경우\n- ③ 36: $3^2 \\times 4 = 36$ 등 계산 실수\n- ④ 64: $4^3 = 64$로, 분자와 지수를 바뀌어 계산한 경우 ($4^3$ 대신 $3^4$를 계산해야 함)\n\n**[핵심 포인트]**\n중복순열은 각 자리에서 **독립적으로 $n$가지 선택**을 할 수 있으므로 $n^r$ 공식을 사용한다. \"중복을 허락한다\"는 조건이 있으면 항상 중복순열임을 기억하세요.",
