    "problem": "다섯 개의 자연수 $a, b, c, d, e$가 다음 조건을 만족시킬 때, 순서쌍 $(a, b, c, d, e)$의 개수를 구하시오.\n\n(가) $a+b+c+d+e=12$\n(나) $|a^2 - b^2| = 5$",
