    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n이 문제는 두 조건을 동시에 만족하는 자연수 조합을 찾는 문제이다.\n- 조건 (나)에서 $|a^2 - b^2| = |a-b||a+b| = 5$를 이용하여 $(a,b)$의 가능한 쌍을 먼저 찾는다.\n- 조건 (가)에서 남은 변수 $c, d, e$의 개수를 구한다.\n- 자연수 조건: $a, b, c, d, e \\geq 1$\n\n**[풀이]**\n\n**Step 1: 조건 (나)에서 $(a,b)$ 쌍 찾기**\n\n$|a^2 - b^2| = 5$에서 $|a-b||a+b| = 5$\n\n5는 소수이므로, 인수분해는 $5 = 1 \\times 5$만 가능한다.\n\n$a, b$가 자연수이므로 $a + b \\geq 2$이고, $a - b$의 절댓값은 음이 아닙니다.\n\n**경우 1:** $|a-b| = 1$, $a+b = 5$\n- $a - b = 1$이면: $a = 3, b = 2$\n- $a - b = -1$이면: $a = 2, b = 3$\n\n**경우 2:** $|a-b| = 5$, $a+b = 1$\n- $a + b = 1$은 자연수 조건에 모순 (최소값이 2)\n\n따라서 가능한 $(a,b)$ 쌍은: $(3, 2)$, $(2, 3)$\n\n**Step 2: 각 경우에 대해 $(c, d, e)$의 개수 구하기**\n\n**경우 A: $(a, b) = (3, 2)$**\n\n조건 (가)에서: $3 + 2 + c + d + e = 12$\n\n따라서 $c + d + e = 7$\n\n$c, d, e$는 자연수이므로, $c' = c-1, d' = d-1, e' = e-1$로 치환하면 ($c', d', e' \\geq 0$):\n\n$c' + d' + e' = 4$\n\n음이 아닌 정수해의 개수는 $\\binom{4+3-1}{3-1} = \\binom{6}{2} = 15$\n\n**경우 B: $(a, b) = (2, 3)$**\n\n조건 (가)에서: $2 + 3 + c + d + e = 12$\n\n따라서 $c + d + e = 7$\n\n마찬가지로 $c' + d' + e' = 4$의 음이 아닌 정수해 개수는 $\\binom{6}{2} = 15$\n\n**Step 3: 전체 순서쌍 개수**\n\n각 경우가 독립적이므로:\n\n$$\\text{전체 개수} = 15 + 15 = 30$$\n\n**[정답 확인]**\n\n조건 (나)로부터 $(a,b) = (3,2)$ 또는 $(2,3)$만 가능하고, 각 경우마다 $c+d+e=7$을 만족하는 자연수 조합이 15개씩 존재하므로 총 30개이다.\n\n**[오답 분석]**\n\n- ① 10: $(a,b)$ 한 가지 경우만 세거나 중복 제거를 잘못한 경우\n- ② 15: $(a,b)$ 한 가지 경우의 $(c,d,e)$ 개수만 센 경우\n- ③ 20: 계산 과정에서 음이 아닌 정수해 공식을 잘못 적용한 경우\n- ④ 25: 일부 경우를 빠뜨리거나 중복 계산한 경우\n\n**[핵심 포인트]**\n\n1. $|a^2-b^2| = |a-b||a+b|$의 인수분해를 이용하면 조건 (나)에서 $(a,b)$를 빠르게 결정할 수 있다.\n2. 자연수 조건에서 음이 아닌 정수 조합 문제로 변환하여 중복조합 공식 $\\binom{n+k-1}{k-1}$을 적용한다.",
