    "type": "조합",
    "problem": "6 이하의 자연수 $a, b, c, d$에 대하여 $a \\leq c \\leq d$이고 $b \\leq c \\leq d$를 만족시키는 순서쌍 $(a, b, c, d)$의 개수를 구하시오.",
