    "answer": 2,
    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 특정 항의 계수를 구할 때는 원하는 차수가 나오는 $r$ 값을 찾아 이항계수를 계산한다.\n\n**[풀이]**\n\n$(x+2)^7$을 이항정리로 전개하면:\n\n$$\n(x+2)^7 = \\sum_{r=0}^{7} \\binom{7}{r}x^{7-r} \\cdot 2^r\n$$\n\n$x^5$의 계수를 구하려면 $x$의 지수가 5가 되어야 한다.\n\n일반항에서 $x$의 지수: $7-r = 5$\n\n따라서 $r = 2$\n\n$r=2$일 때의 항은:\n$$\n\\binom{7}{2}x^{7-2} \\cdot 2^2 = \\binom{7}{2}x^5 \\cdot 4\n$$\n\n이항계수를 계산하면:\n$$\n\\binom{7}{2} = \\frac{7!}{2!(7-2)!} = \\frac{7 \\times 6}{2 \\times 1} = \\frac{42}{2} = 21\n$$\n\n따라서 $x^5$의 계수는:\n$$\n21 \\times 4 = 84\n$$\n\n**[정답 확인]**\n일반항에서 $r=2$를 대입하면 $\\binom{7}{2} \\cdot 2^2 = 21 \\times 4 = 84$이므로 정답이다.\n\n**[오답 분석]**\n- ① 42: $\\binom{7}{2} = 21$을 2배한 값으로, $2^2=4$를 곱하지 않은 경우\n- ② 56: $\\binom{7}{2} \\times 2 = 42$로 계산하거나 다른 $r$ 값으로 잘못 계산한 경우\n- ④ 112: $21 \\times 4 \\times 2$로 계산하여 불필요하게 2를 한 번 더 곱한 경우\n- ⑤ 168: $21 \\times 8$로 계산하여 $2^3$을 사용한 경우\n\n**[핵심 포인트]**\n$(x+a)^n$ 전개에서 $x^k$의 계수는 $n-r=k$를 만족하는 $r$에 대해 $\\binom{n}{r}a^r$이다. 이항계수 계산과 상수항의 거듭제곱을 정확히 곱하는 것이 중요하다.",
