    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 주어진 식 $(x^3+2)^5$를 전개할 때, 특정 차수의 계수를 구하려면 $x^6$을 만드는 항을 찾아야 한다.\n\n**[풀이]**\n\n$(x^3+2)^5$를 이항정리로 전개하면, 일반항은:\n\n$$\\binom{5}{r}(x^3)^{5-r}(2)^r = \\binom{5}{r} \\cdot x^{3(5-r)} \\cdot 2^r$$\n\n$x$의 지수를 정리하면:\n\n$$x^{15-3r}$$\n\n$x^6$의 계수를 구하려면 지수가 6이 되어야 하므로:\n\n$$15 - 3r = 6$$\n\n$$3r = 9$$\n\n$$r = 3$$\n\n따라서 $r=3$일 때의 항을 구하면:\n\n$$\\binom{5}{3} \\cdot x^6 \\cdot 2^3 = \\binom{5}{3} \\cdot 8 \\cdot x^6$$\n\n$\\binom{5}{3}$을 계산하면:\n\n$$\\binom{5}{3} = \\frac{5!}{3! \\cdot 2!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n따라서 $x^6$의 계수는:\n\n$$10 \\times 8 = 80$$\n\n**[정답 확인]**\n$r=3$일 때 $x^{15-9}=x^6$이 되고, 그 계수는 $\\binom{5}{3} \\times 2^3 = 10 \\times 8 = 80$이므로 정답은 ③이다.\n\n**[오답 분석]**\n- ① 40: $\\binom{5}{3} \\times 2^2 = 10 \\times 4$로 계산한 경우 (2의 지수를 잘못 적용)\n- ② 60: $\\binom{5}{2} \\times 2^3 = 10 \\times 6$이나 다른 계산 실수\n- ④ 120: $\\binom{5}{3} \\times 2^4 = 10 \\times 12$로 2의 지수를 과도하게 적용\n- ⑤ 160: $\\binom{5}{3} \\times 2^4 = 10 \\times 16$ 또는 $\\binom{5}{2} \\times 2^4$ 등의 오류\n\n**[핵심 포인트]**\n$(x^3+2)^5$에서 $x^6$ 항을 얻으려면 $(x^3)^{5-r}$의 지수 $3(5-r)=6$을 만족하는 $r$값을 찾아야 하며, 이항계수와 상수항의 거듭제곱을 정확히 계산하는 것이 중요하다.",
