    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n이항정리(Binomial Theorem)를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $$T_{r+1} = \\binom{n}{r}a^{n-r}b^r$$\n\n여기서 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$는 이항계수이고, $r$번째 항(0부터 시작)을 나타냅니다. 특정 차수의 계수를 구할 때는 원하는 차수가 되도록 하는 $r$ 값을 찾아 계산한다.\n\n**[풀이]**\n\n$(2x+1)^5$의 전개식에서 일반항은:\n\n$$T_{r+1} = \\binom{5}{r}(2x)^{5-r} \\cdot 1^r = \\binom{5}{r}2^{5-r}x^{5-r}$$\n\n$x^3$의 계수를 구하려면 $x$의 지수가 3이 되어야 하므로:\n\n$$5-r = 3$$\n$$r = 2$$\n\n따라서 $x^3$항은 $r=2$일 때 나타나므로:\n\n$$T_{2+1} = T_3 = \\binom{5}{2}2^{5-2}x^3 = \\binom{5}{2}2^3x^3$$\n\n이항계수를 계산하면:\n\n$$\\binom{5}{2} = \\frac{5!}{2!3!} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n따라서 $x^3$의 계수는:\n\n$$\\binom{5}{2} \\times 2^3 = 10 \\times 8 = 80$$\n\n**[정답 확인]**\n\n이항정리를 올바르게 적용하여 $r=2$일 때 계수를 구하면 $10 \\times 8 = 80$이 되므로 정답이다.\n\n**[오답 분석]**\n\n- **① 40**: $\\binom{5}{2} \\times 2^2 = 10 \\times 4$로 계산한 경우 (2의 지수를 잘못 구함)\n- **② 60**: $\\binom{5}{3} \\times 2^2 = 10 \\times 6$으로 계산한 경우 (r값과 2의 지수를 동시에 잘못 구함)\n- **④ 120**: $\\binom{5}{1} \\times 2^4 = 5 \\times 24$로 계산한 경우 (r값을 잘못 설정)\n- **⑤ 160**: $\\binom{5}{2} \\times 2^4 = 10 \\times 16$으로 계산한 경우 (2의 지수를 하나 더 많이 계산)\n\n**[핵심 포인트]**\n\n$(a+b)^n$에서 특정 차수의 계수를 구할 때는 ① 원하는 차수가 되도록 하는 r값을 정확히 찾고, ② 계수와 밑의 거듭제곱을 모두 곱하는 것을 잊지 말아야 한다.",
