    "explanation": "**[핵심 개념]**\n이항정리를 이용하여 $(a+b)^n$을 전개할 때, 일반항은 $\\binom{n}{r}a^{n-r}b^r$이다. 특정 차수의 항의 계수를 구할 때는 원하는 차수가 되는 $r$ 값을 찾아 그 항의 계수를 계산한다.\n\n**[풀이]**\n\n$(x^2+2)^6$을 이항정리로 전개하면, 일반항은 $$\\binom{6}{r}(x^2)^{6-r}(2)^r = \\binom{6}{r}x^{2(6-r)}2^r$$\n\n$x$의 지수를 정리하면:\n$$x^{12-2r}$$\n\n$x^4$항을 얻기 위해 지수를 같게 놓으면:\n$$12-2r = 4$$\n$$2r = 8$$\n$$r = 4$$\n\n$r=4$일 때 항의 계수는:\n$$\\binom{6}{4} \\cdot 2^4 = \\binom{6}{4} \\cdot 16$$\n\n$\\binom{6}{4}$를 계산한다:\n$$\\binom{6}{4} = \\binom{6}{2} = \\frac{6 \\times 5}{2 \\times 1} = 15$$\n\n따라서 $x^4$의 계수는:\n$$15 \\times 16 = 240$$\n\n**[정답 확인]**\n$r=4$일 때 $\\binom{6}{4} \\cdot 2^4 = 15 \\times 16 = 240$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n- ① 120: $15 \\times 8 = 120$ (지수 계산은 맞으나 $2^3$을 사용한 경우)\n- ② 160: $10 \\times 16 = 160$ (이항계수를 $\\binom{6}{3}=20$이나 다른 값으로 잘못 계산한 경우)\n- ④ 320: $20 \\times 16 = 320$ (이항계수를 $\\binom{6}{3}=20$으로 잘못 계산한 경우)\n- ⑤ 480: $15 \\times 32 = 480$ ($2^5$를 사용한 경우)\n\n**[핵심 포인트]**\n$(x^2+2)^6$에서 $x$의 지수는 $2(6-r) = 12-2r$로 계산되므로, 원하는 $x^4$를 얻기 위해 $12-2r=4$에서 $r=4$를 찾아야 한다. 이항계수와 $2^r$을 정확히 곱하는 것이 중요하다.",
