    "explanation": "**[핵심 개념]**\n이항정리를 이용한 전개식에서 특정 항의 계수를 구하는 문제이다.\n- 이항정리: $(a+b)^n = \\sum_{k=0}^{n} \\binom{n}{k}a^{n-k}b^k$\n- 특정 차수의 항을 찾기 위해 지수 조건을 세우고 만족하는 $k$ 값을 찾아야 한다.\n\n**[풀이]**\n\n$(x^2-2)^5$를 이항정리로 전개하면:\n\n$$(x^2-2)^5 = \\sum_{k=0}^{5} \\binom{5}{k}(x^2)^{5-k}(-2)^k$$\n\n일반항은:\n$$\\binom{5}{k}(x^2)^{5-k}(-2)^k = \\binom{5}{k}x^{2(5-k)}(-2)^k = \\binom{5}{k}(-2)^k \\cdot x^{10-2k}$$\n\n$x^6$항을 얻기 위한 조건:\n$$10 - 2k = 6$$\n$$2k = 4$$\n$$k = 2$$\n\n$k=2$일 때 $x^6$의 계수는:\n$$\\binom{5}{2}(-2)^2 = \\frac{5!}{2!3!} \\times 4$$\n\n$$= \\frac{5 \\times 4}{2 \\times 1} \\times 4 = 10 \\times 4 = 40$$\n\n**[정답 확인]**\n$k=2$를 대입하면 $x^{10-4}=x^6$이 되고, 계수는 $\\binom{5}{2} \\times 4 = 10 \\times 4 = 40$이다.\n\n**[오답 분석]**\n- ① -80: $(-2)^2=4$를 $-2$로 잘못 계산하거나, 계산 과정에서 부호를 잘못 처리한 경우\n- ② -40: 계수의 절댓값은 맞지만 부호를 음수로 잘못 적용한 경우\n- ④ 80: $\\binom{5}{2}=10$을 $20$으로 계산하거나 $(-2)^2$를 $8$로 잘못 계산한 경우\n- ⑤ 160: 조합과 거듭제곱을 모두 잘못 계산하여 2배의 값을 얻은 경우\n\n**[핵심 포인트]**\n1. 이항정리에서 지수 조건식 $10-2k=6$을 정확히 세우는 것이 가장 중요하다.\n2. $(-2)^2 = +4$로 양수임을 명시적으로 인식하여 부호 오류를 방지해야 한다.",
