    "answer": 2,
    "explanation": "**[핵심 개념]**\n이항정리를 이용한 전개식에서 특정 항의 계수를 구하는 문제이다.\n- 이항정리: $(a+b)^n = \\sum_{r=0}^{n} \\binom{n}{r}a^{n-r}b^r$\n- 일반항에서 원하는 차수의 항을 찾기 위해 지수를 비교하여 $r$값을 결정\n- 해당하는 $r$값에서의 이항계수와 계수들의 곱이 답\n\n**[풀이]**\n\n$\\left(2x^3+\\dfrac{1}{x^2}\\right)^4$를 전개할 때, 일반항은:\n\n$$T_{r+1} = \\binom{4}{r}(2x^3)^{4-r}\\left(\\dfrac{1}{x^2}\\right)^r$$\n\n:\n\n$$T_{r+1} = \\binom{4}{r} \\cdot 2^{4-r} \\cdot x^{3(4-r)} \\cdot x^{-2r}$$\n\n$$= \\binom{4}{r} \\cdot 2^{4-r} \\cdot x^{12-3r-2r}$$\n\n$$= \\binom{4}{r} \\cdot 2^{4-r} \\cdot x^{12-5r}$$\n\n$x^2$의 계수를 구하려면 지수가 2가 되어야 하므로:\n\n$$12 - 5r = 2$$\n\n$$5r = 10$$\n\n$$r = 2$$\n\n$r=2$일 때의 계수는:\n\n$$\\binom{4}{2} \\cdot 2^{4-2} = \\binom{4}{2} \\cdot 2^2$$\n\n$$= 6 \\cdot 4 = 24$$\n\n**[정답 확인]**\n$r=2$일 때 $x^2$항이 나타나며, 그 계수는 $6 \\times 4 = 24$이다.\n\n**[오답 분석]**\n- ① 8: $2^3 = 8$로 계산하여 이항계수를 빠뜨린 경우\n- ② 16: $2^4 = 16$으로만 계산한 경우\n- ④ 32: $\\binom{4}{2} \\cdot 2^3 = 6 \\times 8$로 잘못 계산한 경우\n- ⑤ 48: $2 \\times 24$로 중복 계산하거나 다른 항과 혼동한 경우\n\n**[핵심 포인트]**\n1. 일반항에서 $x$의 지수를 정확히 정리하여 원하는 차수가 되는 $r$값을 찾아야 한다.\n2. 최종 계수는 이항계수 $\\binom{n}{r}$과 밑의 계수 $2^{4-r}$의 곱이다.",
