    "explanation": "**[핵심 개념]**\n이항정리를 이용한 전개식에서 특정 항의 계수를 구하는 문제이다.\n\n$\\left(x^2+\\dfrac{a}{x}\\right)^5$를 전개할 때, 일반항은 다항정리에 의해:\n$$T_{r+1} = \\binom{5}{r}(x^2)^{5-r}\\left(\\dfrac{a}{x}\\right)^r = \\binom{5}{r}a^r x^{10-2r-r} = \\binom{5}{r}a^r x^{10-3r}$$\n\n여기서 $x$의 지수는 $10-3r$이다.\n\n**[풀이]**\n\n**Step 1: $\\dfrac{1}{x^2}$의 계수 구하기**\n\n$\\dfrac{1}{x^2} = x^{-2}$이므로, $10-3r = -2$를 만족하는 $r$을 찾는다.\n\n$$10-3r = -2$$\n$$3r = 12$$\n$$r = 4$$\n\n따라서 $\\dfrac{1}{x^2}$의 계수는:\n$$\\binom{5}{4}a^4 = 5a^4$$\n\n**Step 2: $x$의 계수 구하기**\n\n$x$의 지수가 1이므로, $10-3r = 1$을 만족하는 $r$을 찾는다.\n\n$$10-3r = 1$$\n$$3r = 9$$\n$$r = 3$$\n\n따라서 $x$의 계수는:\n$$\\binom{5}{3}a^3 = 10a^3$$\n\n**Step 3: 두 계수가 같다는 조건 적용**\n\n$$5a^4 = 10a^3$$\n\n$a > 0$이므로 양변을 $5a^3$으로 나누면:\n$$a = 2$$\n\n**[정답 확인]**\n$a=2$일 때, $\\dfrac{1}{x^2}$의 계수는 $5 \\times 2^4 = 5 \\times 16 = 80$이고, $x$의 계수는 $10 \\times 2^3 = 10 \\times 8 = 80$으로 같으므로 정답이다.\n\n**[오답 분석]**\n- ① $a=1$: $5(1)^4 = 5$, $10(1)^3 = 10$ → 계수가 다름\n- ③ $a=3$: $5(3)^4 = 405$, $10(3)^3 = 270$ → 계수가 다름\n- ④ $a=4$: $5(4)^4 = 1280$, $10(4)^3 = 640$ → 계수가 다름\n- ⑤ $a=5$: $5(5)^4 = 3125$, $10(5)^3 = 1250$ → 계수가 다름\n\n**[핵심 포인트]**\n- 일반항에서 $x$의 지수를 올바르게 구하는 것이 중요하다: $(x^2)^{5-r} \\cdot x^{-r} = x^{10-3r}$\n- 두 계수가 같다는 조건을 등식으로 세울 때, $a > 0$이므로 양변을 $a^3$으로 나누어 간단히 할 수 있다.",
