    "explanation": "**[핵심 개념]**\n\n조건부 확률의 정의와 확률의 덧셈 공식이 핵심이다.\n\n- **조건부 확률**: $P(A|B) = \\dfrac{P(A \\cap B)}{P(B)}$\n- **확률의 덧셈 공식**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n- **독립사건**: $P(A|B) = P(A)$이면 두 사건 A, B는 독립이다.\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n\n- $P(A|B) = P(A) = \\dfrac{1}{2}$\n- $P(A \\cap B) = \\dfrac{1}{5}$\n\n**Step 2: $P(B)$ 구하기**\n\n조건부 확률의 정의에 의해:\n$$P(A|B) = \\dfrac{P(A \\cap B)}{P(B)}$$\n\n주어진 값을 대입하면:\n$$\\dfrac{1}{2} = \\dfrac{\\dfrac{1}{5}}{P(B)}$$\n\n양변에 $P(B)$를 곱하고 정리하면:\n$$P(B) \\cdot \\dfrac{1}{2} = \\dfrac{1}{5}$$\n\n$$P(B) = \\dfrac{1}{5} \\times 2 = \\dfrac{2}{5}$$\n\n**Step 3: $P(A \\cup B)$ 구하기**\n\n확률의 덧셈 공식을 적용한다:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n$$P(A \\cup B) = \\dfrac{1}{2} + \\dfrac{2}{5} - \\dfrac{1}{5}$$\n\n$$P(A \\cup B) = \\dfrac{1}{2} + \\dfrac{1}{5}$$\n\n분모를 10으로 통일하면:\n$$P(A \\cup B) = \\dfrac{5}{10} + \\dfrac{2}{10} = \\dfrac{7}{10}$$\n\n**[정답 확인]**\n\n$P(A \\cup B) = \\dfrac{7}{10}$으로, 선택지 ②번이 정답이다.\n\n**[오답 분석]**\n\n- **① $\\dfrac{3}{5}$**: $P(A) + P(B)$의 값으로, 교집합을 빼지 않은 경우\n- **③ $\\dfrac{4}{5}$**: 계산 실수로 $P(A) + P(A \\cap B)$를 더한 경우\n- **④ $\\dfrac{9}{10}$**: $P(A) + P(B)$를 제대로 계산하되 교집합을 빼지 않은 경우\n- **⑤ $1$**: 확률의 덧셈 공식을 올바르게 적용하지 않은 경우\n\n**[핵심 포인트]**\n\n$P(A|B) = P(A)$라는 조건은 **두 사건이 독립**임을 의미하며, 조건부 확률 공식 $P(A|B) = \\dfrac{P(A \\cap B)}{P(B)}$를 이용해 $P(B)$를 먼저 구하는 것이 중요하다. 그 후 합집합의 확률은 반드시 교집합을 빼야 한다.",
