    "explanation": "**[핵심 개념]**\n\n1. **독립사건의 확률**: 두 사건 $A$, $B$가 독립이면 $P(A\\cap B) = P(A) \\cdot P(B)$\n\n2. **여사건의 확률**: $P(A^c) = 1 - P(A)$\n\n3. **전확률의 합**: $P(A) + P(A^c) = 1$\n\n**[풀이]**\n\n**1단계: $P(A)$ 구하기**\n\n주어진 조건에서 $P(A^c) = 2P(A)$이고, $P(A) + P(A^c) = 1$이므로:\n\n$$P(A) + 2P(A) = 1$$\n\n$$3P(A) = 1$$\n\n$$P(A) = \\frac{1}{3}$$\n\n따라서 $P(A^c) = 1 - \\frac{1}{3} = \\frac{2}{3}$\n\n검증: $\\frac{2}{3} = 2 \\times \\frac{1}{3}$ ✓\n\n**2단계: $P(B)$ 구하기**\n\n사건 $A$와 $B$가 독립이므로:\n\n$$P(A \\cap B) = P(A) \\cdot P(B)$$\n\n주어진 조건 $P(A\\cap B)=\\frac{1}{4}$를 대입:\n\n$$\\frac{1}{4} = \\frac{1}{3} \\cdot P(B)$$\n\n$$P(B) = \\frac{1}{4} \\times 3 = \\frac{3}{4}$$\n\n**[정답 확인]**\n\n$P(A) = \\frac{1}{3}$, $P(B) = \\frac{3}{4}$일 때, $P(A \\cap B) = \\frac{1}{3} \\times \\frac{3}{4} = \\frac{1}{4}$ ✓ (독립성 만족)\n\n**[오답 분석]**\n\n- **①번 ($\\frac{1}{4}$)**: $P(A\\cap B)$의 값과 혼동하여 선택한 경우. $P(A\\cap B) = P(A) \\cdot P(B)$이지, $P(B)$가 아님.\n\n- **②번 ($\\frac{1}{3}$)**: $P(A)$의 값과 혼동하여 선택한 경우. $P(A) = P(B)$라고 잘못 가정함.\n\n- **③번 ($\\frac{1}{2}$)**: 계산 과정에서 $P(A) = \\frac{1}{2}$로 잘못 구한 경우나, 임의로 선택한 경우.\n\n- **⑤번 ($\\frac{5}{6}$)**: 여사건 확률 $P(A^c) = \\frac{2}{3}$와 연관지어 잘못 계산한 경우.\n\n**[핵심 포인트]**\n\n1. **여사건 조건을 먼저 처리**: $P(A^c) = 2P(A)$ → $P(A) = \\frac{1}{3}$을 구하는 것이 첫 번째 단계\n\n2. **독립성의 정의**: 독립사건의 교집합 확률은 각 확률의 곱이므로, $P(A \\cap B) = P(A) \\times P(B)$를 활용하여 $P(B)$를 구함",
