    "explanation": "**[핵심 개념]**\n\n조건부 확률과 합집합의 확률 공식을 활용하는 문제이다.\n\n- 조건부 확률: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$\n- 합집합의 확률: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n- $P(A \\cup B) = 1$은 두 사건의 합집합이 전체사건임을 의미한다.\n\n**[풀이]**\n\n**1단계: 조건부 확률 공식으로 $P(A \\cap B)$ 구하기**\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n$$\\frac{1}{4} = \\frac{P(A \\cap B)}{\\frac{2}{5}}$$\n\n$$P(A \\cap B) = \\frac{1}{4} \\times \\frac{2}{5} = \\frac{2}{20} = \\frac{1}{10}$$\n\n**2단계: 합집합의 확률 공식 적용**\n\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n주어진 조건 $P(A \\cup B) = 1$을 대입하면:\n\n$$1 = \\frac{2}{5} + P(B) - \\frac{1}{10}$$\n\n**3단계: $P(B)$ 계산**\n\n$$P(B) = 1 - \\frac{2}{5} + \\frac{1}{10}$$\n\n공통분모 10으로 통일:\n\n$$P(B) = \\frac{10}{10} - \\frac{4}{10} + \\frac{1}{10} = \\frac{7}{10}$$\n\n**[정답 확인]**\n\n$P(A \\cup B) = \\frac{2}{5} + \\frac{7}{10} - \\frac{1}{10} = \\frac{4}{10} + \\frac{7}{10} - \\frac{1}{10} = \\frac{10}{10} = 1$ ✓\n\n**[오답 분석]**\n\n- **①번 1/2**: $P(B)$를 구하는 과정에서 분수 계산 실수로 선택\n- **②번 3/5**: $P(A \\cap B)$를 빠뜨리고 계산한 경우 ($1 - \\frac{2}{5} = \\frac{3}{5}$)\n- **④번 4/5**: 합집합 공식에서 교집합을 더하는 실수로 선택\n- **⑤번 9/10**: 계산 과정에서 부호 실수로 선택\n\n**[핵심 포인트]**\n\n$P(A \\cup B) = 1$이라는 조건은 합집합의 확률 공식에 직접 대입하여 미지수 $P(B)$를 구하는 핵심이다. 조건부 확률에서 교집합을 먼저 구한 후, 합집합 공식에 체계적으로 대입하는 것이 중요하다.",
