    "problem": "두 사건 $A$, $B$에 대하여 $P(A\\cup B)=1$, $P(A\\cap B)=\\dfrac{1}{4}$, $P(A|B)=P(B|A)$일 때, $P(A)$의 값을 구하시오.",
