    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n조건부 확률과 합사건의 확률 공식을 활용하는 문제이다.\n\n- 조건부 확률: $P(A|B) = \\frac{P(A\\cap B)}{P(B)}$, $P(B|A) = \\frac{P(A\\cap B)}{P(A)}$\n- 합사건의 확률: $P(A\\cup B) = P(A) + P(B) - P(A\\cap B)$\n- 조건부 확률이 같다는 조건을 식으로 표현하면 대칭 관계를 찾을 수 있다.\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- $P(A\\cup B) = 1$\n- $P(A\\cap B) = \\frac{1}{4}$\n- $P(A|B) = P(B|A)$\n\n**Step 2: 조건부 확률이 같다는 조건 활용**\n\n$$P(A|B) = P(B|A)$$\n\n$$\\frac{P(A\\cap B)}{P(B)} = \\frac{P(A\\cap B)}{P(A)}$$\n\n$P(A\\cap B) = \\frac{1}{4} \\neq 0$이므로 양변에 $P(B)$, $P(A)$를 곱하면:\n\n$$P(A) = P(B)$$\n\n**Step 3: 합사건 공식에 대입**\n\n$$P(A\\cup B) = P(A) + P(B) - P(A\\cap B)$$\n\n$P(A) = P(B)$를 대입하면:\n\n$$1 = P(A) + P(A) - \\frac{1}{4}$$\n\n$$1 = 2P(A) - \\frac{1}{4}$$\n\n$$2P(A) = 1 + \\frac{1}{4} = \\frac{5}{4}$$\n\n$$P(A) = \\frac{5}{8}$$\n\n**Step 4: 검증**\n\n- $P(A) = P(B) = \\frac{5}{8}$\n- $P(A\\cup B) = \\frac{5}{8} + \\frac{5}{8} - \\frac{1}{4} = \\frac{10}{8} - \\frac{2}{8} = \\frac{8}{8} = 1$ ✓\n- $P(A|B) = \\frac{1/4}{5/8} = \\frac{1}{4} \\times \\frac{8}{5} = \\frac{2}{5}$\n- $P(B|A) = \\frac{1/4}{5/8} = \\frac{2}{5}$ ✓\n\n**[정답 확인]**\n\n조건부 확률이 같다는 조건에서 $P(A) = P(B)$를 도출하고, 합사건의 확률이 1이라는 조건을 적용하면 $P(A) = \\frac{5}{8}$을 얻는다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{4}$: $P(A\\cap B)$의 값과 혼동한 경우\n- ② $\\frac{1}{2}$: 계산 과정에서 $2P(A) = 1$로 잘못 세운 경우 (합사건 공식에서 교집합을 빼먹음)\n- ④ $\\frac{3}{4}$: 합사건 공식을 잘못 적용한 경우\n- ⑤ $\\frac{7}{8}$: 계산 실수로 $2P(A) = \\frac{7}{4}$로 계산한 경우\n\n**[핵심 포인트]**\n\n$P(A|B) = P(B|A)$에서 교집합이 0이 아니면 **$P(A) = P(B)$**라는 중요한 대칭성을 도출할 수 있다. 이를 합사건 공식과 함께 사용하면 간단히 해결된다.",
