    "answer": 2,
    "explanation": "**[핵심 개념]**\n\n확률의 덧셈 정리와 여사건의 성질을 이용하여 문제를 풀어야 한다.\n\n- 덧셈 정리: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n- 여사건: $P(A^c) = 1 - P(A)$\n- 전체 표본공간의 분할: $B = (A \\cap B) \\cup (A^c \\cap B)$ (서로소 집합)\n\n**[풀이]**\n\n**Step 1: $A^c \\cap B$의 의미 파악**\n\n$A^c \\cap B$는 사건 $B$에 속하면서 사건 $A$에는 속하지 않는 경우이다.\n\n사건 $B$를 다음과 같이 분할할 수 있다:\n$$B = (A \\cap B) \\cup (A^c \\cap B)$$\n\n따라서:\n$$P(B) = P(A \\cap B) + P(A^c \\cap B)$$\n\n**Step 2: $P(A \\cap B)$ 구하기**\n\n주어진 조건: $P(A^c \\cap B) = \\dfrac{1}{4}$\n\n따라서:\n$$P(B) = P(A \\cap B) + \\dfrac{1}{4}$$\n$$P(A \\cap B) = P(B) - \\dfrac{1}{4} \\cdots (1)$$\n\n**Step 3: 덧셈 정리 적용**\n\n주어진 조건: $P(A \\cup B) = \\dfrac{5}{6}$\n\n덧셈 정리에 의해:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$\\dfrac{5}{6} = P(A) + P(B) - P(A \\cap B) \\cdots (2)$$\n\n식 (1)을 식 (2)에 대입:\n$$\\dfrac{5}{6} = P(A) + P(B) - \\left(P(B) - \\dfrac{1}{4}\\right)$$\n$$\\dfrac{5}{6} = P(A) + P(B) - P(B) + \\dfrac{1}{4}$$\n$$\\dfrac{5}{6} = P(A) + \\dfrac{1}{4}$$\n\n**Step 4: $P(A)$ 계산**\n\n$$P(A) = \\dfrac{5}{6} - \\dfrac{1}{4}$$\n$$P(A) = \\dfrac{10}{12} - \\dfrac{3}{12} = \\dfrac{7}{12}$$\n\n**Step 5: $P(A^c)$ 계산**\n\n$$P(A^c) = 1 - P(A) = 1 - \\dfrac{7}{12} = \\dfrac{5}{12}$$\n\n**[정답 확인]**\n\n$P(A) = \\dfrac{7}{12}$이므로 $P(A^c) = 1 - \\dfrac{7}{12} = \\dfrac{5}{12}$로, 주어진 두 조건을 모두 만족한다.\n\n**[오답 분석]**\n\n- **① 1/6**: $P(A \\cup B)$의 여값으로 혼동한 경우\n- **② 1/4**: $P(A^c \\cap B)$ 값과 혼동한 경우\n- **④ 1/2**: 계산 과정에서 분모를 잘못 통일한 경우\n- **⑤ 7/12**: $P(A)$와 $P(A^c)$를 혼동한 경우\n\n**[핵심 포인트]**\n\n표본공간의 분할($B = (A \\cap B) \\cup (A^c \\cap B)$)을 이용하여 $P(B)$를 $P(A \\cap B)$로 표현한 후, 덧셈 정리에 대입하면 $P(A)$를 직접 구한다. 특히 $A^c \\cap B$와 $A \\cap B$의 합이 $B$임을 인식하는 것이 중요하다.",
