    "explanation": "**[핵심 개념]**\n확률 문제에서 \"적어도 1개\"와 같은 조건은 여사건을 이용하면 계산이 간단해진다. 여사건의 확률은 $P(A^c) = 1 - P(A)$로 구한다. 또한 조합을 이용하여 경우의 수를 계산한다: $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n\n흰색 5개, 검은색 9개, 총 14개에서 3개를 선택하는 경우의 수:\n$$\\binom{14}{3} = \\frac{14 \\times 13 \\times 12}{3 \\times 2 \\times 1} = \\frac{2184}{6} = 364$$\n\n**Step 2: 여사건 활용**\n\n\"적어도 1개가 흰색\" = 1 - \"0개가 흰색(즉, 모두 검은색)\"\n\n따라서 검은색 3개를 모두 선택하는 경우의 수를 구한다:\n$$\\binom{9}{3} = \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} = \\frac{504}{6} = 84$$\n\n**Step 3: 확률 계산**\n\n검은색만 3개를 뽑을 확률:\n$$P(\\text{검은색 3개}) = \\frac{84}{364} = \\frac{21}{91}$$\n\n적어도 1개가 흰색일 확률:\n$$P(\\text{적어도 1개 흰색}) = 1 - \\frac{21}{91} = \\frac{91-21}{91} = \\frac{70}{91}$$\n\n**[정답 확인]**\n여사건을 이용하여 검은색만 뽑는 경우(84가지)를 전체 경우의 수(364가지)에서 빼면 $\\frac{70}{91}$이 나온다.\n\n**[오답 분석]**\n- ① $\\frac{55}{91}$: 계산 과정에서 조합값을 잘못 구한 경우\n- ② $\\frac{60}{91}$: 경우의 수 계산 실수로 인한 오답\n- ③ $\\frac{65}{91}$: 여사건 계산 중 실수한 경우\n- ⑤ $\\frac{75}{91}$: 검은색만 뽑는 경우를 잘못 계산한 경우\n\n**[핵심 포인트]**\n\"적어도 1개\"는 여사건(반대 경우)을 이용하면 계산이 간단하다. 검은색 마스크 9개 중 3개를 모두 선택하는 84가지를 구한 후, 전체에서 빼는 것이 핵심이다.",
