    "explanation": "**[핵심 개념]**\n\n1. **여사건의 확률**: $P(A^c) = 1 - P(A)$\n2. **배반사건**: 두 사건 $A$, $B$가 배반이면 $A \\cap B = \\emptyset$이므로 $P(A \\cap B) = 0$\n3. **합사건의 확률**: \n - 일반적으로: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n - 배반사건일 때: $P(A \\cup B) = P(A) + P(B)$\n\n**[풀이]**\n\n**Step 1: 주어진 조건 정리**\n- $P(A^c) = \\dfrac{5}{6}$\n- $P(A \\cup B) = \\dfrac{3}{4}$\n- $A$와 $B$는 배반사건\n\n**Step 2: $P(A)$ 구하기**\n\n여사건의 확률 공식을 이용하면:\n$$P(A) = 1 - P(A^c) = 1 - \\frac{5}{6} = \\frac{1}{6}$$\n\n**Step 3: $P(B)$ 구하기**\n\n$A$와 $B$가 배반사건이므로 $P(A \\cap B) = 0$\n\n합사건의 확률 공식에서:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n$$\\frac{3}{4} = \\frac{1}{6} + P(B) - 0$$\n\n$$P(B) = \\frac{3}{4} - \\frac{1}{6}$$\n\n분모를 12로 통일하면:\n$$P(B) = \\frac{9}{12} - \\frac{2}{12} = \\frac{7}{12}$$\n\n**Step 4: $P(B^c)$ 구하기**\n\n여사건의 확률 공식을 이용하면:\n$$P(B^c) = 1 - P(B) = 1 - \\frac{7}{12} = \\frac{5}{12}$$\n\n**[정답 확인]**\n\n$P(A) = \\frac{1}{6}$, $P(B) = \\frac{7}{12}$일 때, $P(A \\cup B) = \\frac{1}{6} + \\frac{7}{12} = \\frac{2}{12} + \\frac{7}{12} = \\frac{9}{12} = \\frac{3}{4}$ ✓ (주어진 조건과 일치)\n\n**[오답 분석]**\n\n- **① $\\dfrac{1}{12}$**: $1 - P(A) = 1 - \\dfrac{1}{6} = \\dfrac{5}{6}$로 잘못 계산한 경우\n- **② $\\dfrac{1}{6}$**: $P(A)$의 값을 $P(B^c)$로 착각한 경우\n- **④ $\\dfrac{5}{6}$**: $P(A^c)$의 값을 그대로 답으로 한 경우\n- **⑤ $\\dfrac{11}{12}$**: 계산 과정에서 분수를 잘못 더하거나 뺀 경우\n\n**[핵심 포인트]**\n\n배반사건일 때는 $P(A \\cup B) = P(A) + P(B)$로 간단해진다는 점과, 여사건의 확률 공식 $P(X^c) = 1 - P(X)$를 정확히 적용하는 것이 중요하다.",
