    "explanation": "**[핵심 개념]**\n여사건을 이용한 확률 계산: 구하려는 사건이 복잡할 때는 여사건의 확률을 구한 후 $P(A) = 1 - P(A^c)$를 이용한다. 이 문제에서 \"적어도 1개가 7 이상의 홀수\"의 여사건은 \"둘 다 7 미만이거나 짝수\"이다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n11개의 공에서 2개를 선택하는 경우의 수:\n$$\\binom{11}{2} = \\frac{11 \\times 10}{2} = 55$$\n\n**2단계: 7 이상의 홀수 파악**\n1부터 11까지의 자연수 중 7 이상의 홀수: $7, 9, 11$ (3개)\n\n**3단계: 여사건 정의**\n\"적어도 1개가 7 이상의 홀수\"의 여사건은 \"2개 모두 7 이상의 홀수가 아님\"\n= \"2개 모두가 7 미만이거나 짝수\"\n\n**4단계: 7 이상의 홀수가 아닌 수**\n- 7 미만: $1, 2, 3, 4, 5, 6$ (6개)\n- 7 이상의 짝수: $8, 10$ (2개)\n- 합계: $6 + 2 = 8$개\n\n**5단계: 여사건의 경우의 수**\n8개의 수에서 2개를 선택:\n$$\\binom{8}{2} = \\frac{8 \\times 7}{2} = 28$$\n\n**6단계: 여사건의 확률**\n$$P(A^c) = \\frac{28}{55}$$\n\n**7단계: 구하는 확률**\n$$P(A) = 1 - P(A^c) = 1 - \\frac{28}{55} = \\frac{55-28}{55} = \\frac{27}{55}$$\n\n**[정답 확인]**\n여사건을 이용하여 계산한 결과 $\\frac{27}{55}$이므로 정답은 ④번이다.\n\n**[오답 분석]**\n- ① $\\frac{17}{55}$: $55 - 38 = 17$인데, 이는 7 이상의 홀수에서만 2개를 선택하는 경우 $\\binom{3}{2}=3$과 혼동한 것으로 보임\n- ② $\\frac{19}{55}$: 계산 오류로 여사건을 잘못 계산한 경우\n- ③ $\\frac{23}{55}$: $55 - 32 = 23$으로, 여사건의 경우의 수를 잘못 센 경우\n- ⑤ $\\frac{31}{55}$: $55 - 24 = 31$로, 제외할 수를 잘못 계산한 경우\n\n**[핵심 포인트]**\n\"적어도\"가 포함된 확률 문제는 여사건을 이용하는 것이 효율적이다. 여사건을 정확히 파악하고 제외되는 원소를 정확히 세는 것이 관건이다.",
