    "explanation": "**[핵심 개념]**\n여사건을 이용한 확률 계산: 어떤 사건의 확률을 직접 구하기 어려울 때, 여사건의 확률을 구한 후 $P(A) = 1 - P(A^c)$를 이용한다. 이 문제에서는 \"곱이 5의 배수\"의 여사건인 \"곱이 5의 배수가 아닐\" 확률을 구하는 것이 훨씬 간단한다. 곱이 5의 배수가 되려면 5의 배수인 수가 최소 1개 이상 포함되어야 한다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n10개의 공 중에서 4개를 선택하는 경우의 수:\n$$\\binom{10}{4} = \\frac{10 \\times 9 \\times 8 \\times 7}{4 \\times 3 \\times 2 \\times 1} = 210$$\n\n**2단계: 1부터 10까지 수의 분류**\n- 5의 배수: 5, 10 (2개)\n- 5의 배수가 아닌 수: 1, 2, 3, 4, 6, 7, 8, 9 (8개)\n\n**3단계: 여사건 이용 - 곱이 5의 배수가 아닐 경우**\n곱이 5의 배수가 아니려면 5의 배수인 공을 하나도 꺼내지 않아야 한다.\n즉, 5의 배수가 아닌 8개 중에서만 4개를 선택:\n$$\\binom{8}{4} = \\frac{8 \\times 7 \\times 6 \\times 5}{4 \\times 3 \\times 2 \\times 1} = 70$$\n\n**4단계: 곱이 5의 배수일 확률**\n곱이 5의 배수인 경우의 수:\n$$210 - 70 = 140$$\n\n따라서 구하는 확률:\n$$P = \\frac{140}{210} = \\frac{2}{3}$$\n\n**[정답 확인]**\n여사건을 이용하여 5의 배수가 아닌 경우(8개 수만 사용)를 구하고 전체에서 빼면 $\\frac{140}{210} = \\frac{2}{3}$이 된다.\n\n**[오답 분석]**\n- **②번 $\\frac{17}{21}$**: 계산 과정에서 경우의 수를 잘못 센 경우 (분모를 210이 아닌 다른 수로 설정)\n- **③번 $\\frac{5}{7}$**: 조건을 잘못 해석하거나 경우의 수 계산 실수\n- **④번 $\\frac{11}{14}$**: 5의 배수가 아닌 경우를 잘못 계산한 경우\n- **⑤번 $\\frac{13}{15}$**: 전체 경우의 수를 잘못 구한 경우\n\n**[핵심 포인트]**\n\"~의 배수일 확률\" 문제는 **여사건**을 이용하는 것이 효율적이다. 5의 배수가 포함되려면 5 또는 10 중 하나 이상이 있어야 하므로, 반대로 이들이 모두 제외된 경우를 구하면 간단하게 풀 수 있다.",
