    "explanation": "**[핵심 개념]**\n- 전체 경우의 수: n개의 서로 다른 원소를 일렬로 나열하는 경우의 수는 $n!$\n- 조건부 확률: 특정 조건을 만족하는 경우의 수를 전체 경우의 수로 나눔\n- 여사건의 활용: 구하는 사건의 여사건을 이용하면 계산이 간단할 수 있음\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n\n6장의 카드를 일렬로 나열하는 모든 경우의 수:\n$$6! = 720$$\n\n**Step 2: 양 끝의 두 수의 합이 10 이하인 경우 찾기**\n\n양 끝에 놓인 두 수를 $(a, b)$라 하면 ($a$: 왼쪽, $b$: 오른쪽), $a + b \\leq 10$을 만족해야 함.\n\n**Step 3: 여사건 이용 - 합이 11 이상인 경우**\n\n$a + b \\geq 11$인 경우를 먼저 구하는 것이 효율적:\n- $(5, 6)$: $5 + 6 = 11$ ✓\n- $(6, 5)$: $6 + 5 = 11$ ✓\n- $(6, 6)$: 불가능 (같은 카드)\n- $(4, 6)$: $4 + 6 = 10$ ✗\n- $(6, 4)$: $6 + 4 = 10$ ✗\n\n조건 $a + b \\geq 11$을 만족하는 $(a, b)$ 순서쌍:\n$$(5, 6), (6, 5)$$\n\n**Step 4: 합이 11 이상인 경우의 수**\n\n양 끝이 $(5, 6)$으로 고정될 때, 중간 4개의 카드를 배열:\n$$4! = 24$$\n\n양 끝이 $(6, 5)$로 고정될 때, 중간 4개의 카드를 배열:\n$$4! = 24$$\n\n합이 11 이상인 전체 경우의 수:\n$$24 + 24 = 48$$\n\n**Step 5: 합이 10 이하인 경우의 수**\n\n$$720 - 48 = 672$$\n\n**Step 6: 확률 계산**\n\n$$P = \\frac{672}{720} = \\frac{672}{720} = \\frac{14}{15}$$\n\n(분자, 분모를 48로 나누면: $\\frac{672 \\div 48}{720 \\div 48} = \\frac{14}{15}$)\n\n**[정답 확인]**\n\n여사건을 이용하여 계산한 결과 $\\frac{14}{15}$이므로 정답은 **④번**이다.\n\n**[오답 분석]**\n\n- ① $\\frac{11}{15}$: 계산 실수 또는 조건을 잘못 이해한 경우\n- ② $\\frac{4}{5} = \\frac{12}{15}$: 합이 11 이상인 경우를 잘못 계산한 경우\n- ③ $\\frac{13}{15}$: 양 끝이 $(5,6)$ 또는 $(6,5)$인 경우를 한 가지만 센 경우 ($24 + 720 = 744$에서 오류)\n- ⑤ $1$: 모든 경우가 조건을 만족한다고 잘못 생각한 경우\n\n**[핵심 포인트]**\n\n1. **여사건 활용**: 조건을 만족하지 않는 경우가 적을 때, 여사건으로 계산하면 훨씬 간단한다.\n2. **양 끝 고정**: 양 끝의 숫자가 정해지면 나머지 중간 4개를 배열하는 $(n-2)!$만 계산하면 된다.",
