    "explanation": "**[핵심 개념]**\n두 수의 곱이 짝수가 되는 조건은 두 수 중 **최소한 하나 이상이 짝수**여야 한다는 것이다. \n- 짝수 × 짝수 = 짝수\n- 짝수 × 홀수 = 짝수\n- 홀수 × 홀수 = 홀수\n\n따라서 여사건을 이용하여 \"곱이 홀수인 경우\"를 구하고, 전체에서 빼는 것이 효율적이다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수**\n7장의 카드를 일렬로 나열하는 경우의 수는 $7!$가지이다.\n\n**Step 2: 홀수와 짝수 분류**\n- 홀수: 1, 3, 5, 7 (4개)\n- 짝수: 2, 4, 6 (3개)\n\n**Step 3: 곱이 홀수인 경우 (여사건)**\n두 수의 곱이 홀수가 되려면 **양 끝 모두 홀수**여야 한다.\n\n양 끝에 홀수가 올 경우의 수:\n- 왼쪽 끝에 올 홀수 선택: 4가지\n- 오른쪽 끝에 올 홀수 선택: 3가지 (왼쪽에서 선택한 것 제외)\n- 중간 5자리에 남은 5장 배열: $5!$가지\n\n따라서 양 끝의 곱이 홀수인 경우: $4 \\times 3 \\times 5! = 12 \\times 120 = 1440$가지\n\n**Step 4: 곱이 짝수인 경우**\n곱이 짝수인 경우 = 전체 - 곱이 홀수인 경우\n\n$$7! - 1440 = 5040 - 1440 = 3600\\text{가지}$$\n\n**Step 5: 확률 계산**\n$$P(\\text{곱이 짝수}) = \\frac{3600}{5040} = \\frac{3600}{5040}$$\n\n분자와 분모를 최대공약수 840으로 나누면:\n$$\\frac{3600}{5040} = \\frac{3600 \\div 840}{5040 \\div 840} = \\frac{30}{42} = \\frac{5}{7}$$\n\n**[정답 확인]**\n양 끝의 곱이 짝수일 확률은 $\\frac{5}{7}$이며, 이는 여사건 \"양 끝 모두 홀수일 확률 $\\frac{2}{7}$\"을 이용하여 $1 - \\frac{2}{7} = \\frac{5}{7}$로도 확인된다.\n\n**[오답 분석]**\n- ① $\\frac{4}{7}$: 홀수의 개수(4개)를 전체(7개)로 나눈 값으로, 계산 오류\n- ② $\\frac{11}{21}$: 분모를 잘못 설정하거나 중간 계산 실수\n- ④ $\\frac{17}{21}$: 여사건의 확률을 잘못 계산한 경우\n- ⑤ $\\frac{6}{7}$: 곱이 짝수인 경우를 과다 계산\n\n**[핵심 포인트]**\n1. **여사건 활용**: \"곱이 짝수\" = 1 - \"곱이 홀수(양 끝 모두 홀수)\"로 계산하면 훨씬 간단한다.\n2. **곱이 홀수 조건**: 두 수의 곱이 홀수 ⟺ 양쪽 모두 홀수 (이 조건을 정확히 파악하는 것이 핵심)",
