    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 성질:\n- 평균(기댓값): $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n분산의 성질:\n- $V(aX) = a^2 \\cdot V(X)$ (단, $a$는 상수)\n\n이를 이용하여 주어진 조건에서 $n$을 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n\n확률변수 $X$는 이항분포 $B\\left(n, \\frac{1}{3}\\right)$을 따르므로:\n$$V(X) = n \\cdot \\frac{1}{3} \\cdot \\left(1 - \\frac{1}{3}\\right) = n \\cdot \\frac{1}{3} \\cdot \\frac{2}{3} = \\frac{2n}{9}$$\n\n**2단계: $V(2X)$ 계산**\n\n분산의 성질에 의해:\n$$V(2X) = 2^2 \\cdot V(X) = 4 \\cdot V(X)$$\n\n$$V(2X) = 4 \\cdot \\frac{2n}{9} = \\frac{8n}{9}$$\n\n**3단계: 주어진 조건 적용**\n\n문제에서 $V(2X) = 40$이므로:\n$$\\frac{8n}{9} = 40$$\n\n**4단계: $n$ 구하기**\n\n$$8n = 360$$\n\n$$n = 45$$\n\n**[정답 확인]**\n\n$n = 45$일 때, $V(X) = \\frac{2 \\times 45}{9} = 10$이므로 $V(2X) = 4 \\times 10 = 40$ ✓\n\n**[오답 분석]**\n\n① $n = 12$: $V(2X) = \\frac{8 \\times 12}{9} = \\frac{96}{9} \\approx 10.67$ ✗\n\n② $n = 15$: $V(2X) = \\frac{8 \\times 15}{9} = \\frac{120}{9} \\approx 13.33$ ✗\n\n③ $n = 18$: $V(2X) = \\frac{8 \\times 18}{9} = 16$ ✗\n\n④ $n = 27$: $V(2X) = \\frac{8 \\times 27}{9} = 24$ ✗\n\n⑤ $n = 45$: $V(2X) = \\frac{8 \\times 45}{9} = 40$ ✓\n\n**[핵심 포인트]**\n\n- 이항분포의 분산 공식 $V(X) = np(1-p)$를 정확히 적용해야 함\n- 분산의 성질 $V(aX) = a^2V(X)$에서 계수의 제곱을 잊지 말 것",
