    "problem": "모집단이 정규분포 $N(m, 2^2)$을 따른다. 이 모집단에서 크기가 256인 표본을 임의추출하여 구한 표본평균으로 모평균 $m$에 대한 신뢰도 95%의 신뢰구간 $a \\leq m \\leq b$를 구할 때, $b-a$의 값을 구하시오. (단, $Z$가 표준정규분포를 따를 때, $P(|Z| \\leq 1.96) = 0.95$이다.)",
