    "explanation": "**[핵심 개념]**\n\n표본평균의 신뢰구간 구하는 문제이다. 모집단이 정규분포를 따를 때, 표본평균 $\\bar{X}$는 $N(m, \\frac{\\sigma^2}{n})$을 따릅니다. 신뢰도 95%의 신뢰구간은 $\\bar{X} \\pm z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$ 형태로 구성되며, 여기서 $z_{\\alpha/2} = 1.96$이다. 신뢰구간의 폭은 $b - a = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}}$이다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 모집단: $N(m, 2^2)$ → 표준편차 $\\sigma = 2$\n- 표본크기: $n = 256$\n- 신뢰도: 95% → $P(|Z| \\leq 1.96) = 0.95$\n\n**2단계: 표본평균의 표준편차 계산**\n\n표본평균 $\\bar{X}$의 표준편차는:\n$$\\sigma_{\\bar{X}} = \\frac{\\sigma}{\\sqrt{n}} = \\frac{2}{\\sqrt{256}} = \\frac{2}{16} = \\frac{1}{8} = 0.125$$\n\n**3단계: 신뢰구간의 오차한계 계산**\n\n신뢰도 95%에서 오차한계(margin of error) $E$는:\n$$E = z_{\\alpha/2} \\cdot \\sigma_{\\bar{X}} = 1.96 \\times 0.125 = 0.245$$\n\n**4단계: 신뢰구간의 폭 계산**\n\n신뢰구간 $a \\leq m \\leq b$는:\n- $a = \\bar{X} - E = \\bar{X} - 0.245$\n- $b = \\bar{X} + E = \\bar{X} + 0.245$\n\n따라서:\n$$b - a = (\\bar{X} + 0.245) - (\\bar{X} - 0.245) = 2 \\times 0.245 = 0.49$$\n\n**[정답 확인]**\n\n신뢰구간의 폭은 $b - a = 2 \\times z_{\\alpha/2} \\cdot \\frac{\\sigma}{\\sqrt{n}} = 2 \\times 1.96 \\times 0.125 = 0.49$이므로 정답은 **②번**이다.\n\n**[오답 분석]**\n\n- **①번 (0.245)**: 오차한계 $E$ 값 자체이다. 신뢰구간의 폭은 오차한계의 2배이다.\n- **③번 (0.98)**: $1.96 \\times 0.5$로, $\\sqrt{n}$ 계산을 잘못한 경우이다.\n- **④번 (1.96)**: 신뢰도 값 자체이다. 신뢰구간의 폭과 혼동했다.\n- **⑤번 (3.92)**: $1.96 \\times 2$로, $\\frac{\\sigma}{\\sqrt{n}}$을 계산하지 않고 $\\sigma$만 사용한 경우이다.\n\n**[핵심 포인트]**\n\n신뢰구간의 폭 = $2 \\times z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$임을 기억하세요. 특히 표본크기 $n$의 제곱근을 정확히 계산하고, 오차한계와 신뢰구간의 폭을 구분해야 한다.",
