    "explanation": "**[핵심 개념]**\n정규분포를 따르는 확률변수를 표준정규분포로 변환하는 표준화 과정이 핵심이다.\n- 확률변수 $X \\sim N(\\mu, \\sigma^2)$일 때, $Z = \\frac{X - \\mu}{\\sigma}$로 변환하면 $Z \\sim N(0, 1)$ (표준정규분포)\n- 표준정규분포의 대칭성을 이용하여 $P(0 \\leq Z \\leq a) = P(-a \\leq Z \\leq 0)$\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- $X \\sim N(68, 10^2)$ → $\\mu = 68$, $\\sigma = 10$\n- 구하는 값: $P(55 \\leq X \\leq 78)$\n\n**Step 2: 표준화 (표준정규분포로 변환)**\n\n$X$를 표준화하여 $Z$로 변환한다.\n\n$$Z = \\frac{X - 68}{10}$$\n\n- $X = 55$일 때: $Z_1 = \\frac{55 - 68}{10} = \\frac{-13}{10} = -1.3$\n\n- $X = 78$일 때: $Z_2 = \\frac{78 - 68}{10} = \\frac{10}{10} = 1.0$\n\n따라서:\n$$P(55 \\leq X \\leq 78) = P(-1.3 \\leq Z \\leq 1.0)$$\n\n**Step 3: 표준정규분포의 대칭성 이용**\n\n표준정규분포는 $Z = 0$을 중심으로 대칭이므로:\n\n$$P(-1.3 \\leq Z \\leq 1.0) = P(-1.3 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1.0)$$\n\n대칭성에 의해 $P(-1.3 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 1.3)$이므로:\n\n$$P(-1.3 \\leq Z \\leq 1.0) = P(0 \\leq Z \\leq 1.3) + P(0 \\leq Z \\leq 1.0)$$\n\n**Step 4: 주어진 값 대입**\n\n$$P(55 \\leq X \\leq 78) = 0.4032 + 0.3413 = 0.7445$$\n\n**[정답 확인]**\n표준화를 통해 $P(-1.3 \\leq Z \\leq 1.0)$을 구했고, 표준정규분포의 대칭성을 이용하여 주어진 두 확률값을 더하면 0.7445가 된다.\n\n**[오답 분석]**\n- ① 0.6247: $P(0 \\leq Z \\leq 1.3) - P(0 \\leq Z \\leq 1.0)$을 계산한 오류\n- ② 0.6826: 표준화 과정에서 실수하거나 $P(0 \\leq Z \\leq 1.0)$만 두 배로 계산한 경우\n- ④ 0.8064: $P(0 \\leq Z \\leq 1.3)$을 중복 계산하거나 다른 범위를 계산한 오류\n- ⑤ 0.8413: $P(0 \\leq Z \\leq 1.3) + 2 \\times P(0 \\leq Z \\leq 1.0)$처럼 잘못 계산한 경우\n\n**[핵심 포인트]**\n1. **표준화**: $Z = \\frac{X - \\mu}{\\sigma}$로 변환하는 것이 필수\n2. **대칭성 활용**: 표준정규분포는 0을 중심으로 대칭이므로 음수 구간은 대칭인 양수 구간의 확률과 같다",
