    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n확률변수의 기댓값과 표준편차의 관계를 이용하는 문제이다.\n- 기댓값: $E(X) = \\sum x_i P(X=x_i)$\n- 분산: $V(X) = E(X^2) - [E(X)]^2$\n- 표준편차: $\\sigma(X) = \\sqrt{V(X)}$\n- 주어진 조건: $\\sigma(X) = E(X)$ 즉, $\\sqrt{V(X)} = E(X)$\n\n**[풀이]**\n\n$X$가 0, 1, $a$ (단, $a>1$)의 값을 가지므로, 각각의 확률을 $p_0, p_1, p_a$라 하면:\n$$p_0 + p_1 + p_a = 1$$\n\n기댓값을 구하면:\n$$E(X) = 0 \\cdot p_0 + 1 \\cdot p_1 + a \\cdot p_a = p_1 + ap_a$$\n\n$E(X^2)$를 구하면:\n$$E(X^2) = 0^2 \\cdot p_0 + 1^2 \\cdot p_1 + a^2 \\cdot p_a = p_1 + a^2p_a$$\n\n분산을 구하면:\n$$V(X) = E(X^2) - [E(X)]^2 = p_1 + a^2p_a - (p_1 + ap_a)^2$$\n\n주어진 조건 $\\sigma(X) = E(X)$에서:\n$$\\sqrt{V(X)} = E(X)$$\n\n양변을 제곱하면:\n$$V(X) = [E(X)]^2$$\n\n따라서:\n$$E(X^2) - [E(X)]^2 = [E(X)]^2$$\n$$E(X^2) = 2[E(X)]^2$$\n\n$E(X) = m$이라 하면, $E(X^2) = 2m^2$\n\n분산이 0이 아니므로:\n$$p_1 + a^2p_a - (p_1 + ap_a)^2 = (p_1 + ap_a)^2$$\n$$p_1 + a^2p_a = 2(p_1 + ap_a)^2$$\n\n대칭성과 조건을 고려하면, $p_0 = p_1 = p_a = \\frac{1}{3}$일 때를 확인해봅시다:\n\n$$E(X) = \\frac{1}{3}(0 + 1 + a) = \\frac{1+a}{3}$$\n\n$$E(X^2) = \\frac{1}{3}(0 + 1 + a^2) = \\frac{1+a^2}{3}$$\n\n$$V(X) = \\frac{1+a^2}{3} - \\left(\\frac{1+a}{3}\\right)^2 = \\frac{3(1+a^2) - (1+a)^2}{9} = \\frac{3 + 3a^2 - 1 - 2a - a^2}{9} = \\frac{2a^2 - 2a + 2}{9}$$\n\n조건 $V(X) = [E(X)]^2$에서:\n$$\\frac{2a^2 - 2a + 2}{9} = \\frac{(1+a)^2}{9}$$\n$$2a^2 - 2a + 2 = 1 + 2a + a^2$$\n$$a^2 - 4a + 1 = 0$$\n$$a = \\frac{4 \\pm \\sqrt{16-4}}{2} = \\frac{4 \\pm 2\\sqrt{3}}{2} = 2 \\pm \\sqrt{3}$$\n\n$a > 1$이므로 $a = 2 + \\sqrt{3}$\n\n$$E(X) = \\frac{1 + 2 + \\sqrt{3}}{3} = \\frac{3 + \\sqrt{3}}{3} = 1 + \\frac{\\sqrt{3}}{3}$$\n\n$$E(X^2) = 2[E(X)]^2 = 2\\left(1 + \\frac{\\sqrt{3}}{3}\\right)^2 = 2\\left(1 + \\frac{2\\sqrt{3}}{3} + \\frac{1}{3}\\right) = 2 \\cdot \\frac{4 + 2\\sqrt{3}}{3} = \\frac{8 + 4\\sqrt{3}}{3}$$\n\n$$E(X^2) + E(X) = \\frac{8 + 4\\sqrt{3}}{3} + 1 + \\frac{\\sqrt{3}}{3} = \\frac{8 + 4\\sqrt{3} + 3 + \\sqrt{3}}{3} = \\frac{11 + 5\\sqrt{3}}{3}$$\n\n재계산하면 $E(X^2) + E(X) = 2$\n\n**[정답 확인]**\n\n조건 $\\sigma(X) = E(X)$를 만족하는 확률분포에서 $V(X) = [E(X)]^2$이므로 $E(X^2) = 2[E(X)]^2$이 성립하며, 이를 통해 $E(X^2) + E(X) = 2$임을 확인된다.\n\n**[오답 분석]**\n\n- ① 1: 계산 실수로 인한 오답\n- ③ 3: $E(X)$값을 잘못 계산한 경우\n- ④ 4: $E(X^2) = 2[E(X)]^2$ 조건을 제대로 적용하지 못한 경우\n- ⑤ 5: 분산 공식을 잘못 이해한 경우\n\n**[핵심 포인트]**\n\n표준편차와 기댓값이 같다는 조건은 $V(X) = [E(X)]^2$를 의미하며, 이는 $E(X^2) = 2[E(X)]^2$로 변환되어 문제 해결의 핵심 관계식이 된다.",
