    "answer": 2,
    "explanation": "**[핵심 개념]**\n1. **조합**: 전체에서 조건을 만족하는 경우를 선택하는 경우의 수\n2. **원형 순열**: 원형 탁자에 n명을 앉히는 경우의 수는 $(n-1)!$ (회전을 같은 것으로 간주)\n3. **곱의 법칙**: 선택 후 배치하는 경우 각 단계의 경우의 수를 곱함\n\n**[풀이]**\n\n**1단계: 5명을 선택하는 경우의 수**\n\n- 남학생 4명을 반드시 포함해야 함\n- 전체 8명 중 5명을 선택하되, 남학생 4명은 필수 포함\n- 따라서 여학생 4명 중에서 1명을 추가로 선택\n\n$$\\binom{4}{4} \\times \\binom{4}{1} = 1 \\times 4 = 4$$\n\n**2단계: 선택된 5명을 원형 탁자에 앉히는 경우의 수**\n\n- 원형 순열의 공식: $n$명을 원형 탁자에 앉히는 경우의 수는 $(n-1)!$\n- 5명을 원형 탁자에 앉히는 경우의 수:\n\n$$(5-1)! = 4! = 24$$\n\n**3단계: 전체 경우의 수**\n\n곱의 법칙을 적용하여:\n\n$$4 \\times 24 = 96$$\n\n**[정답 확인]**\n남학생 4명을 반드시 포함하는 조건에서 여학생 1명을 선택(4가지)하고, 5명을 원형 탁자에 배치(24가지)하면 총 96가지가 된다.\n\n**[오답 분석]**\n\n- **① 48**: $4 \\times 12 = 48$으로, 원형 순열을 $\\frac{4!}{2} = 12$로 잘못 계산한 경우\n- **② 72**: $4 \\times 18 = 72$로, 원형 순열을 잘못 계산한 경우\n- **④ 120**: $5 \\times 24 = 120$으로, 여학생을 5명 중에서 선택하는 것으로 조건을 무시한 경우\n- **⑤ 144**: $6 \\times 24 = 144$로, 여학생 선택 경우의 수를 잘못 계산한 경우\n\n**[핵심 포인트]**\n- **필수 포함 조건**: \"남학생 4명을 반드시 포함\"이므로 여학생만 선택하면 됨\n- **원형 순열**: 원탁은 회전을 같은 것으로 보므로 $(n-1)!$을 적용해야 함",
