    "problem": "확률변수 $X$가 0, 1, 2, 3, 4의 값을 가지고 $P(X = k) = P(X = k+2)$ ($k = 0, 1, 2$)를 만족시키며 $E(X^2) = \\dfrac{35}{6}$일 때, $P(X = 0)$의 값은?",
