    "answer": 1,
    "explanation": "**[핵심 개념]**\n확률의 성질과 기댓값 계산에 관한 문제이다.\n- 확률변수의 모든 확률의 합은 1: $\\sum P(X=k) = 1$\n- 제곱의 기댓값: $E(X^2) = \\sum k^2 \\cdot P(X=k)$\n- 주어진 조건식을 이용하여 미지수를 줄이고 연립방정식을 세우는 전략\n\n**[풀이]**\n\n**Step 1: 조건식 정리**\n주어진 조건 $P(X=k) = P(X=k+2)$ ($k=0, 1, 2$)에서:\n- $P(X=0) = P(X=2)$\n- $P(X=1) = P(X=3)$\n- $P(X=2) = P(X=4)$\n\n따라서 $P(X=0) = P(X=2) = P(X=4)$이고, $P(X=1) = P(X=3)$이다.\n\n**Step 2: 미지수 설정**\n$P(X=0) = P(X=2) = P(X=4) = a$, $P(X=1) = P(X=3) = b$로 놓겠다.\n\n**Step 3: 확률의 합 조건**\n$$P(X=0) + P(X=1) + P(X=2) + P(X=3) + P(X=4) = 1$$\n$$a + b + a + b + a = 1$$\n$$3a + 2b = 1 \\cdots (1)$$\n\n**Step 4: $E(X^2)$ 조건**\n$$E(X^2) = 0^2 \\cdot a + 1^2 \\cdot b + 2^2 \\cdot a + 3^2 \\cdot b + 4^2 \\cdot a = \\frac{35}{6}$$\n$$0 + b + 4a + 9b + 16a = \\frac{35}{6}$$\n$$20a + 10b = \\frac{35}{6} \\cdots (2)$$\n\n**Step 5: 연립방정식 풀이**\n식 (1)에서: $2b = 1 - 3a$, 즉 $b = \\frac{1-3a}{2}$\n\n이를 식 (2)에 대입:\n$$20a + 10 \\cdot \\frac{1-3a}{2} = \\frac{35}{6}$$\n$$20a + 5(1-3a) = \\frac{35}{6}$$\n$$20a + 5 - 15a = \\frac{35}{6}$$\n$$5a + 5 = \\frac{35}{6}$$\n$$5a = \\frac{35}{6} - 5 = \\frac{35-30}{6} = \\frac{5}{6}$$\n$$a = \\frac{1}{6}$$\n\n**Step 6: 검증**\n$a = \\frac{1}{6}$일 때, $b = \\frac{1-3 \\cdot \\frac{1}{6}}{2} = \\frac{1-\\frac{1}{2}}{2} = \\frac{1}{4}$\n\n확인: $3 \\cdot \\frac{1}{6} + 2 \\cdot \\frac{1}{4} = \\frac{1}{2} + \\frac{1}{2} = 1$ ✓\n\n$E(X^2) = 20 \\cdot \\frac{1}{6} + 10 \\cdot \\frac{1}{4} = \\frac{20}{6} + \\frac{10}{4} = \\frac{10}{3} + \\frac{5}{2} = \\frac{20+15}{6} = \\frac{35}{6}$ ✓\n\n**[정답 확인]**\n$P(X=0) = a = \\frac{1}{6}$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{12}$: 식 (2)에서 계산 실수로 $10a$를 빼먹은 경우\n- ③ $\\frac{1}{4}$: $P(X=1)$의 값과 혼동한 경우\n- ④ $\\frac{1}{3}$: 식 (1)에서 $3a=1$로 잘못 계산한 경우\n- ⑤ $\\frac{5}{12}$: $E(X^2) = \\frac{35}{6}$을 잘못 해석하여 계산한 경우\n\n**[핵심 포인트]**\n1. 주어진 대칭 조건을 이용하여 미지수를 최소화하는 것이 핵심\n2. 확률의 합과 기댓값 조건을 연립하여 체계적으로 풀이하기",
