    "problem": "확률변수 $X$가 정규분포 $N(9, 0.4^2)$을 따르고, 확률변수 $Y$가 정규분포 $N(20, 1^2)$을 따른다. $P(X \\leq a) = P(Y \\geq b)$일 때, $a + b$의 값은? (단, $a < 9$, $b > 20$이고 $P(X \\leq a) = P(Y \\geq b)$를 만족시키는 상수이다.)",
