    "explanation": "**[핵심 개념]**\n\n표본평균의 분포는 정규분포를 따르며, 모집단이 $N(\\mu, \\sigma^2)$을 따를 때 크기 $n$인 표본의 표본평균 $\\bar{X}$는 $N(\\mu, \\frac{\\sigma^2}{n})$을 따릅니다. 표준정규분포를 이용하여 확률을 계산하고, 표준정규분포의 대칭성 $P(Z \\geq a) + P(Z \\leq -a) = 1$을 활용한다.\n\n**[풀이]**\n\n**Step 1: 표본평균의 분포 구하기**\n\n첫 번째 표본평균 $\\bar{X}_1$:\n- 모집단: $N(m, 6^2)$, 표본크기: $n_1 = 9$\n- $\\bar{X}_1 \\sim N\\left(m, \\frac{36}{9}\\right) = N(m, 4)$\n\n두 번째 표본평균 $\\bar{X}_2$:\n- 모집단: $N(6, 2^2)$, 표본크기: $n_2 = 4$\n- $\\bar{X}_2 \\sim N\\left(6, \\frac{4}{4}\\right) = N(6, 1)$\n\n**Step 2: 표준정규분포로 변환**\n\n$\\bar{X}_1$을 표준화하면:\n$$Z_1 = \\frac{\\bar{X}_1 - m}{2} \\sim N(0, 1)$$\n\n따라서:\n$$P(\\bar{X}_1 \\geq 7) = P\\left(Z_1 \\geq \\frac{7-m}{2}\\right) = P\\left(Z \\geq \\frac{7-m}{2}\\right)$$\n\n$\\bar{X}_2$를 표준화하면:\n$$Z_2 = \\frac{\\bar{X}_2 - 6}{1} \\sim N(0, 1)$$\n\n따라서:\n$$P(\\bar{X}_2 \\leq 5) = P(Z_2 \\leq -1) = P(Z \\leq -1)$$\n\n**Step 3: 주어진 조건 적용**\n\n주어진 조건: $P(\\bar{X}_1 \\geq 7) + P(\\bar{X}_2 \\leq 5) = 1$\n\n$$P\\left(Z \\geq \\frac{7-m}{2}\\right) + P(Z \\leq -1) = 1$$\n\n표준정규분포의 성질에 의해 $P(Z \\geq a) + P(Z \\leq -a) = 1$이므로:\n\n$$\\frac{7-m}{2} = 1$$\n\n**Step 4: $m$ 구하기**\n\n$$7 - m = 2$$\n$$m = 5$$\n\n**[정답 확인]**\n\n$m=5$일 때, $P(\\bar{X}_1 \\geq 7) = P(Z \\geq 1)$이고, $P(\\bar{X}_2 \\leq 5) = P(Z \\leq -1)$이므로, 표준정규분포의 대칭성에 의해 $P(Z \\geq 1) + P(Z \\leq -1) = 1$이 성립한다.\n\n**[오답 분석]**\n\n- ① $m=3$: $\\frac{7-3}{2}=2$이므로 $P(Z \\geq 2) + P(Z \\leq -1) \\neq 1$\n- ② $m=4$: $\\frac{7-4}{2}=1.5$이므로 $P(Z \\geq 1.5) + P(Z \\leq -1) \\neq 1$\n- ④ $m=6$: $\\frac{7-6}{2}=0.5$이므로 $P(Z \\geq 0.5) + P(Z \\leq -1) \\neq 1$\n- ⑤ $m=7$: $\\frac{7-7}{2}=0$이므로 $P(Z \\geq 0) + P(Z \\leq -1) = 0.5 + 0.159... \\neq 1$\n\n**[핵심 포인트]**\n\n표본평균의 분포에서 분산은 $\\frac{\\sigma^2}{n}$이 되므로 표본크기가 커질수록 분산이 작아진다. 표준정규분포의 대칭성 $P(Z \\geq a) = P(Z \\leq -a)$를 이용하여 두 확률의 합이 1이 되는 조건을 찾는 것이 핵심이다.",
