    "problem": "정사면체의 네 면에 1, 2, 2, 3이 하나씩 적혀 있다. 이 정사면체 2개를 동시에 던져서 바닥에 닿는 면에 적힌 수의 차를 $X$라 할 때, $V(X)$의 값은?",
