    "explanation": "**[핵심 개념]**\n모집단이 정규분포를 따를 때, 표본평균의 신뢰구간을 구하는 문제이다. 표본평균 $\\bar{x}$는 평균이 $m$이고 표준편차가 $\\frac{\\sigma}{\\sqrt{n}}$인 정규분포를 따릅니다. 신뢰도 95%일 때 $P(|Z| \\leq 1.96) = 0.95$를 이용하여 오차한계 $c$를 구한다.\n\n**[풀이]**\n\n**1단계: 표본평균의 표준편차(표준오차) 구하기**\n\n표본평균 $\\bar{x}$의 표준편차는 $$\\sigma_{\\bar{x}} = \\frac{\\sigma}{\\sqrt{n}} = \\frac{2\\sqrt{2}}{\\sqrt{128}}$$\n\n분모를 정리하면:\n$$\\sqrt{128} = \\sqrt{64 \\times 2} = 8\\sqrt{2}$$\n\n따라서:\n$$\\sigma_{\\bar{x}} = \\frac{2\\sqrt{2}}{8\\sqrt{2}} = \\frac{2}{8} = \\frac{1}{4} = 0.25$$\n\n**2단계: 신뢰도 95%에서 신뢰구간 구하기**\n\n모평균 $m$에 대한 신뢰도 95%의 신뢰구간은:\n$$\\bar{x} - z_{\\alpha/2} \\cdot \\sigma_{\\bar{x}} \\leq m \\leq \\bar{x} + z_{\\alpha/2} \\cdot \\sigma_{\\bar{x}}$$\n\n주어진 조건에서 $P(|Z| \\leq 1.96) = 0.95$이므로 $z_{\\alpha/2} = 1.96$이다.\n\n**3단계: 오차한계 $c$ 계산하기**\n\n오차한계 $c$는:\n$$c = z_{\\alpha/2} \\cdot \\sigma_{\\bar{x}} = 1.96 \\times 0.25$$\n\n$$c = \\frac{196}{100} \\times \\frac{1}{4} = \\frac{196}{400} = \\frac{49}{100} = 0.49$$\n\n**[정답 확인]**\n$c = 1.96 \\times 0.25 = 0.49$이므로 정답은 **①번**이다.\n\n**[오답 분석]**\n- ② 0.56: $1.96 \\times 0.28$로 잘못 계산한 경우\n- ③ 0.64: $1.96 \\times \\frac{1}{3}$처럼 표준오차를 잘못 구한 경우\n- ④ 0.72: $1.96 \\times \\frac{\\sigma}{n}$으로 $\\sqrt{n}$을 빠뜨린 경우\n- ⑤ 0.98: $1.96 \\times 0.5$로 표준오차를 $\\frac{\\sigma}{2}$로 잘못 계산한 경우\n\n**[핵심 포인트]**\n표본평균의 신뢰구간에서 오차한계는 $c = z_{\\alpha/2} \\times \\frac{\\sigma}{\\sqrt{n}}$이다. 특히 표준편차를 $\\sqrt{n}$으로 나누는 것을 반드시 기억해야 한다.",
