    "problem": "1, 3, 5, 7, 9가 하나씩 적힌 5장의 카드에서 3장을 복원추출하여 그 수의 표본평균을 $\\bar{X}$라 하자. $V(a\\bar{X} + 6) = 24$일 때, 양수 $a$의 값은?",
