    "explanation": "**[핵심 개념]**\n확률의 기본 공식은 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$이다. \n포함-배제 원리를 사용하면 $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$이다.\n5의 배수 판정법: 일의 자리가 0 또는 5인 수이다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 계산**\n1부터 5까지의 자연수 중 서로 다른 4개를 택하여 만든 네 자리 자연수의 개수:\n$$P(5,4) = 5 \\times 4 \\times 3 \\times 2 = 120$$\n\n**2단계: 사건 정의**\n- 사건 A: 만든 수가 5의 배수\n- 사건 B: 만든 수가 3500 이상\n- 구하는 확률: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n**3단계: 사건 A (5의 배수)의 경우의 수**\n일의 자리가 5여야 한다.\n- 일의 자리: 5 (고정)\n- 천, 백, 십의 자리: {1, 2, 3, 4}에서 3개를 순서대로 배열\n$$|A| = P(4,3) = 4 \\times 3 \\times 2 = 24$$\n\n**4단계: 사건 B (3500 이상)의 경우의 수**\n천의 자리가 3, 4, 5인 경우:\n\n- 천의 자리가 3: 3500 이상이려면 백의 자리가 5 이상이어야 함\n - 백의 자리가 5: 나머지 {1,2,4}에서 2개 순배열 → $P(3,2) = 6$\n - 천의 자리가 3일 때: 6가지\n\n- 천의 자리가 4: 모두 4000 이상\n - 나머지 {1,2,3,5}에서 3개 순배열 → $P(4,3) = 24$\n\n- 천의 자리가 5: 모두 5000 이상\n - 나머지 {1,2,3,4}에서 3개 순배열 → $P(4,3) = 24$\n\n$$|B| = 6 + 24 + 24 = 54$$\n\n**5단계: 사건 $A \\cap B$ (5의 배수이면서 3500 이상)의 경우의 수**\n일의 자리가 5이고, 동시에 3500 이상:\n\n- 천의 자리가 3: 백의 자리≥5 필요하나 5는 이미 일의 자리에 고정 → 불가능 (0가지)\n- 천의 자리가 4: 일의 자리가 5, 나머지 {1,2,3}에서 2개 순배열 → $P(3,2) = 6$\n- 천의 자리가 5: 불가능 (5는 일의 자리에 고정)\n\n$$|A \\cap B| = 6$$\n\n**6단계: 포함-배제 원리 적용**\n$$|A \\cup B| = |A| + |B| - |A \\cap B| = 24 + 54 - 6 = 72$$\n\n**7단계: 확률 계산**\n$$P(A \\cup B) = \\frac{72}{120} = \\frac{3}{5}$$\n\n**[정답 확인]**\n$\\frac{72}{120} = \\frac{3}{5}$로 정답 ①과 일치한다.\n\n**[오답 분석]**\n- ② $\\frac{31}{60}$: 포함-배제 원리를 잘못 적용했거나 교집합을 잘못 계산\n- ③ $\\frac{11}{20} = \\frac{66}{120}$: 사건 B의 경우의 수를 잘못 계산\n- ④ $\\frac{7}{12} = \\frac{70}{120}$: 교집합을 0으로 잘못 계산\n- ⑤ $\\frac{2}{3} = \\frac{80}{120}$: 전체 경우의 수 또는 합집합을 잘못 계산\n\n**[핵심 포인트]**\n5의 배수(일의 자리 5) 조건과 3500 이상(천의 자리와 백의 자리 조건) 조건의 교집합을 정확히 파악하는 것이 중요하다. 특히 5가 두 조건에서 중복되는 역할을 하므로 주의 깊게 경우를 나누어야 한다.",
