    "explanation": "**[핵심 개념]**\n\n이 문제는 이항분포를 따르는 확률변수의 기댓값을 구하는 문제이다. \n\n주요 개념:\n- 동전을 $n$번 던질 때 앞면의 수 $X$는 이항분포 $B(n, p)$를 따름\n- 이항분포의 기댓값: $E(X) = np$, 분산: $V(X) = np(1-p)$\n- 확률변수의 함수에 대한 기댓값: $E(Y) = E(f(X)) = \\sum f(x) \\cdot P(X=x)$\n- 또는 $E(Y) = E(X^2) - 4E(X)$를 이용 (선형성)\n\n**[풀이]**\n\n**Step 1: $X$의 분포 파악**\n\n동전 4개를 동시에 던지므로 $X \\sim B(4, \\frac{1}{2})$\n\n따라서:\n$$E(X) = 4 \\times \\frac{1}{2} = 2$$\n$$V(X) = 4 \\times \\frac{1}{2} \\times \\frac{1}{2} = 1$$\n\n**Step 2: $E(X^2)$ 계산**\n\n분산의 정의로부터:\n$$V(X) = E(X^2) - [E(X)]^2$$\n$$1 = E(X^2) - 2^2$$\n$$E(X^2) = 5$$\n\n**Step 3: $E(Y)$ 계산**\n\n$Y = X^2 - 4X$이므로:\n$$E(Y) = E(X^2 - 4X)$$\n$$E(Y) = E(X^2) - 4E(X)$$\n$$E(Y) = 5 - 4 \\times 2$$\n$$E(Y) = 5 - 8 = -3$$\n\n**[정답 확인]**\n\n$E(Y) = E(X^2) - 4E(X) = 5 - 8 = -3$이므로 정답은 ①번이다.\n\n**[오답 분석]**\n\n- ② $E(Y) = -2$: $E(X^2) = 4$로 잘못 계산한 경우\n- ③ $E(Y) = -1$: $E(X^2) = 3$으로 잘못 계산한 경우\n- ④ $E(Y) = 0$: $Y = 0$인 경우만 고려하거나 계산 실수\n- ⑤ $E(Y) = 1$: 부호를 반대로 계산한 경우\n\n**[핵심 포인트]**\n\n1. 이항분포의 기댓값과 분산에서 $E(X^2) = V(X) + [E(X)]^2$ 관계식을 이용하면 직접 계산 없이 빠르게 구한다.\n\n2. 확률변수의 함수에 대한 기댓값은 기댓값의 선형성을 이용하여 $E(aX + b) = aE(X) + b$ 형태로 분해하는 것이 효율적이다.",
