    "explanation": "**[핵심 개념]**\n확률의 정의: 어떤 사건이 일어날 확률 = $\\frac{\\text{구하는 경우의 수}}{\\text{전체 경우의 수}}$\n\n주사위를 던질 때 나올 수 있는 결과는 1, 2, 3, 4, 5, 6으로 총 6가지이며, 각 결과가 나올 확률은 모두 같다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 파악**\n주사위를 한 번 던질 때 나올 수 있는 모든 경우: {1, 2, 3, 4, 5, 6}\n따라서 전체 경우의 수 = 6\n\n**2단계: 3의 배수인 경우의 수 찾기**\n1부터 6 사이에서 3의 배수를 찾으면:\n- 3은 3의 배수 (∵ $3 = 3 \\times 1$) ✓\n- 6은 3의 배수 (∵ $6 = 3 \\times 2$) ✓\n- 1, 2, 4, 5는 3의 배수가 아님\n\n3의 배수의 눈이 나오는 경우의 수 = 2 (3 또는 6)\n\n**3단계: 확률 계산**\n$$P(\\text{3의 배수}) = \\frac{\\text{3의 배수가 나오는 경우의 수}}{\\text{전체 경우의 수}} = \\frac{2}{6} = \\frac{1}{3}$$\n\n**[정답 확인]**\n주사위 6면 중 3의 배수는 3, 6 두 개이므로 확률은 $\\frac{2}{6} = \\frac{1}{3}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{6}$: 특정한 한 눈(예: 정확히 3만)이 나올 확률\n- ③ $\\frac{1}{2}$: 3개의 경우가 필요한데 2개만 있음\n- ④ $\\frac{2}{3}$: 분자와 분모를 반대로 계산한 경우\n- ⑤ $\\frac{5}{6}$: 3의 배수가 아닐 확률 ($1 - \\frac{1}{3} = \\frac{2}{3}$와도 맞지 않음)\n\n**[핵심 포인트]**\n1부터 n까지의 수 중에서 k의 배수의 개수는 $\\lfloor \\frac{n}{k} \\rfloor$이므로, 주사위에서 3의 배수는 $\\lfloor \\frac{6}{3} \\rfloor = 2$개이다.",
