    "explanation": "**[핵심 개념]**\n여사건을 이용한 확률 계산 방법이다. \"적어도 한 개\"라는 조건은 여사건을 이용하면 간단히 계산할 수 있다.\n- 여사건의 확률: $P(A^c) = 1 - P(A)$\n- 동전을 던질 때 앞면이 나올 확률 = $\\frac{1}{2}$, 뒷면이 나올 확률 = $\\frac{1}{2}$\n\n**[풀이]**\n\n**방법 1: 여사건을 이용한 풀이 (추천)**\n\n\"적어도 한 개가 앞면\"의 여사건은 \"두 개 모두 뒷면\"이다.\n\n두 동전을 동시에 던질 때:\n- 첫 번째 동전이 뒷면일 확률: $\\frac{1}{2}$\n- 두 번째 동전이 뒷면일 확률: $\\frac{1}{2}$\n\n두 개 모두 뒷면이 나올 확률:\n$$P(\\text{두 개 모두 뒷면}) = \\frac{1}{2} \\times \\frac{1}{2} = \\frac{1}{4}$$\n\n따라서 적어도 한 개가 앞면일 확률:\n$$P(\\text{적어도 한 개 앞면}) = 1 - \\frac{1}{4} = \\frac{3}{4}$$\n\n**방법 2: 직접 계산으로 확인**\n\n표본공간: (첫 번째, 두 번째) = {(앞,앞), (앞,뒷), (뒷,앞), (뒷,뒷)}\n- 전체 경우의 수: 4가지\n\n\"적어도 한 개가 앞면\"인 경우:\n- (앞, 앞): 두 개 모두 앞면\n- (앞, 뒷): 첫 번째만 앞면\n- (뒷, 앞): 두 번째만 앞면\n\n유리한 경우의 수: 3가지\n\n$$P(\\text{적어도 한 개 앞면}) = \\frac{3}{4}$$\n\n**[정답 확인]**\n여사건을 이용하면 \"두 개 모두 뒷면\"의 확률 $\\frac{1}{4}$를 구해서 1에서 빼면 $\\frac{3}{4}$가 되므로 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{4}$: 두 개 모두 뒷면이 나올 확률을 실수로 선택 (여사건을 구하지 않음)\n- ② $\\frac{1}{2}$: 한 개의 동전에서 앞면이 나올 확률과 혼동\n- ④ $\\frac{1}{3}$: 계산 오류로 생기는 선택지\n- ⑤ 1: 확률이 1이면 반드시 일어나야 하는데, 두 개 모두 뒷면이 나올 가능성이 있으므로 틀림\n\n**[핵심 포인트]**\n\"적어도 한 개\"라는 표현이 나오면 **여사건을 이용**하는 것이 계산을 간단히 한다. 여사건 확률 = 1 - (반대 상황의 확률)",
