    "explanation": "**[핵심 개념]**\n\n합집합의 확률을 구하는 문제이다. 두 사건 $A$, $B$에 대해 $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$이다. \n주사위는 1부터 6까지의 눈이 나오며, 각 눈이 나올 확률은 $\\frac{1}{6}$이다.\n\n**[풀이]**\n\n**1단계: 사건 A 파악하기**\n\n사건 $A$: 2 이하의 눈이 나오는 사건\n$$A = \\{1, 2\\}$$\n$$P(A) = \\frac{2}{6} = \\frac{1}{3}$$\n\n**2단계: 사건 B 파악하기**\n\n사건 $B$: 5 이상의 눈이 나오는 사건\n$$B = \\{5, 6\\}$$\n$$P(B) = \\frac{2}{6} = \\frac{1}{3}$$\n\n**3단계: 사건 $A \\cap B$ 파악하기**\n\n$A$와 $B$의 교집합을 구한다.\n$$A \\cap B = \\{1, 2\\} \\cap \\{5, 6\\} = \\emptyset$$\n\n따라서 $P(A \\cap B) = 0$ (두 사건은 배반사건이다)\n\n**4단계: $P(A \\cup B)$ 계산하기**\n\n합집합의 확률 공식을 적용한다.\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n$$P(A \\cup B) = \\frac{1}{3} + \\frac{1}{3} - 0$$\n$$P(A \\cup B) = \\frac{2}{3}$$\n\n**[정답 확인]**\n\n$P(A \\cup B) = \\frac{2}{3}$이므로 정답은 ③번이다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{3}$: 사건 $A$의 확률만 구한 경우\n- ② $\\frac{1}{2}$: 계산 실수로 잘못된 값\n- ④ $\\frac{5}{6}$: 여집합을 잘못 이해하여 구한 경우\n- ⑤ 1: 확률의 범위를 초과하는 오답\n\n**[핵심 포인트]**\n\n주사위에서 \"2 이하\"와 \"5 이상\"은 겹치지 않는 배반사건이므로 $P(A \\cap B) = 0$이다. \n따라서 $P(A \\cup B) = P(A) + P(B)$로 간단히 계산할 수 있다.",
