    "_type": "prob_basic",
    "type": "확률의 덧셈·곱셈",
    "problem": "1부터 20까지의 자연수 중에서 하나를 택할 때, 3의 배수 또는 5의 배수인 수를 택할 확률을 \\(\\dfrac{p}{20}\\)이라 하자. \\(p\\)의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n이 문제는 집합의 합집합 원소 개수를 구하는 포함-배제 원리(Inclusion-Exclusion Principle)를 이용한다.\n\n전체 사건에서 특정 조건을 만족하는 경우의 수를 구할 때:\n- $|A \\cup B| = |A| + |B| - |A \\cap B|$\n\n이를 확률로 나타내면:\n$$P(A \\text{ 또는 } B) = P(A) + P(B) - P(A \\text{ 그리고 } B)$$\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n1부터 20까지의 자연수 중에서 하나를 택하므로, 전체 경우의 수는 20이다.\n\n**2단계: 3의 배수 개수 구하기**\n1부터 20까지의 3의 배수: $3, 6, 9, 12, 15, 18$\n\n개수: $\\left\\lfloor \\frac{20}{3} \\right\\rfloor = 6$개\n\n**3단계: 5의 배수 개수 구하기**\n1부터 20까지의 5의 배수: $5, 10, 15, 20$\n\n개수: $\\left\\lfloor \\frac{20}{5} \\right\\rfloor = 4$개\n\n**4단계: 3의 배수이면서 5의 배수(즉, 15의 배수) 개수 구하기**\n1부터 20까지의 15의 배수: $15$\n\n개수: $\\left\\lfloor \\frac{20}{15} \\right\\rfloor = 1$개\n\n**5단계: 포함-배제 원리 적용**\n3의 배수 또는 5의 배수인 수의 개수:\n$$|A \\cup B| = |A| + |B| - |A \\cap B| = 6 + 4 - 1 = 9$$\n\n**6단계: 확률 계산**\n구하는 확률은:\n$$P = \\frac{9}{20}$$\n\n따라서 $p = 9$\n\n**[정답 확인]**\n포함-배제 원리를 올바르게 적용하여 3의 배수 또는 5의 배수인 경우가 정확히 9개이므로, 확률은 $\\frac{9}{20}$이고 $p = 9$이다.\n\n**[오답 분석]**\n- **$p = 10$**: 3의 배수(6개) + 5의 배수(4개) = 10개로, 중복을 빼지 않은 경우\n- **$p = 6$**: 3의 배수만 센 경우\n- **$p = 4$**: 5의 배수만 센 경우\n- **$p = 1$**: 3의 배수이면서 5의 배수인 15의 배수만 센 경우\n\n**[핵심 포인트]**\n\"A 또는 B\"인 경우의 수를 구할 때는 반드시 **포함-배제 원리**를 적용하여 중복을 제거해야 한다. 특히 두 조건을 모두 만족하는 경우(15의 배수)를 정확히 찾아서 한 번만 빼는 것이 핵심이다.",
