    "explanation": "**[핵심 개념]**\n\n두 사건이 독립이라는 것은 한 사건의 발생 여부가 다른 사건의 확률에 영향을 주지 않는다는 의미이다. 두 사건 $A$, $B$가 독립일 때, 두 사건이 동시에 일어날 확률은 다음과 같이 계산된다:\n\n$$P(A \\cap B) = P(A) \\times P(B)$$\n\n이것이 독립사건의 가장 중요한 성질이다.\n\n**[풀이]**\n\n주어진 조건을 정리하면:\n- 사건 $A$와 $B$는 서로 독립\n- $P(A) = \\dfrac{1}{3}$\n- $P(B) = \\dfrac{1}{4}$\n\n두 사건이 독립이므로, 교집합의 확률은 각 확률의 곱으로 계산된다:\n\n$$P(A \\cap B) = P(A) \\times P(B)$$\n\n$$P(A \\cap B) = \\dfrac{1}{3} \\times \\dfrac{1}{4}$$\n\n$$P(A \\cap B) = \\dfrac{1}{12}$$\n\n**[정답 확인]**\n\n독립사건의 정의에 따라 $P(A \\cap B) = P(A) \\times P(B) = \\dfrac{1}{3} \\times \\dfrac{1}{4} = \\dfrac{1}{12}$이므로 정답은 ①번이다.\n\n**[오답 분석]**\n\n- **② $\\dfrac{1}{7}$**: 두 확률을 더한 후 잘못 계산한 경우 ($\\dfrac{1}{3} + \\dfrac{1}{4} = \\dfrac{7}{12}$의 일부)\n- **③ $\\dfrac{1}{6}$**: $\\dfrac{1}{2} \\times \\dfrac{1}{3}$처럼 다른 값들을 곱한 경우\n- **④ $\\dfrac{7}{12}$**: $1 - P(A) - P(B)$를 잘못 계산하거나, $P(A) + P(B) - P(A \\cap B)$를 계산한 경우\n- **⑤ $\\dfrac{1}{2}$**: 단순한 계산 오류\n\n**[핵심 포인트]**\n\n**독립사건은 곱셈으로 계산한다**: 두 사건이 독립일 때는 반드시 $P(A \\cap B) = P(A) \\times P(B)$를 사용하며, 더하기나 다른 연산을 하면 안 된다. 이는 수능에서 자주 출제되는 기본 공식이다.",
