    "answer": 5,
    "explanation": "**[핵심 개념]**\n주사위를 여러 번 던질 때 특정 조건을 만족하는 경우의 수를 구하는 문제이다. 주사위는 1부터 6까지의 눈이 나올 수 있으며, 두 번 던질 때 각 회차는 독립적이다. 조건을 만족하는 모든 경우를 체계적으로 나열하여 세는 것이 기본 풀이 방법이다.\n\n**[풀이]**\n첫 번째 주사위 결과를 $a$, 두 번째 주사위 결과를 $b$라 하면:\n- $a + b = 8$을 만족하는 경우를 찾아야 한다.\n- $1 \\leq a \\leq 6$, $1 \\leq b \\leq 6$\n\n$a + b = 8$에서 $b = 8 - a$이므로, $b$도 1 이상 6 이하여야 한다:\n$$1 \\leq 8 - a \\leq 6$$\n$$2 \\leq a \\leq 7$$\n\n그런데 $a$는 최대 6이므로:\n$$2 \\leq a \\leq 6$$\n\n각 경우를 나열하면:\n- $a = 2$일 때: $b = 6$ → $(2, 6)$ ✓\n- $a = 3$일 때: $b = 5$ → $(3, 5)$ ✓\n- $a = 4$일 때: $b = 4$ → $(4, 4)$ ✓\n- $a = 5$일 때: $b = 3$ → $(5, 3)$ ✓\n- $a = 6$일 때: $b = 2$ → $(6, 2)$ ✓\n\n따라서 경우의 수는 **5가지**이다.\n\n**[정답 확인]**\n주사위 합이 8이 되는 순서쌍은 (2,6), (3,5), (4,4), (5,3), (6,2)로 정확히 5가지이므로 정답이다.\n\n**[오답 분석]**\n선택지가 주어지지 않았으나, 일반적인 오류는:\n- **4가지**: (2,6), (3,5), (4,4), (5,3)만 세어 (6,2)를 빠뜨린 경우\n- **6가지**: 합이 7 또는 9인 경우까지 포함한 경우\n- **3가지**: (3,5), (4,4), (5,3)만 센 경우\n\n**[핵심 포인트]**\n주사위 두 번 던지기에서 순서쌍 $(a, b)$와 $(b, a)$는 서로 다른 경우이다. 조건을 만족하는 모든 순서쌍을 빠짐없이 나열하는 것이 중요하다.",
