    "problem": "서로 독립인 두 사건 \\(A\\), \\(B\\)에 대하여 \\(P(A) = \\dfrac{2}{5}\\), \\(P(B) = \\dfrac{1}{3}\\)일 때, \\(P(A^c \\cap B^c)\\)의 값은?",
    "answerType": "choice",
