    "explanation": "**[핵심 개념]**\n확률의 기본 정의는 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$이다. 이 문제에서는 조합을 이용하여 경우의 수를 구해야 한다. 조합 공식은 $C(n,r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이며, 이는 n개 중에서 r개를 순서 상관없이 뽑는 경우의 수이다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 구하기**\n\n1부터 9까지의 카드 9장 중에서 3장을 동시에 뽑는 경우의 수는:\n$$C(9,3) = \\binom{9}{3} = \\frac{9!}{3!6!} = \\frac{9 \\times 8 \\times 7}{3 \\times 2 \\times 1} = \\frac{504}{6} = 84$$\n\n**2단계: 사건이 일어나는 경우의 수 구하기**\n\n1부터 9까지의 자연수 중 홀수는 1, 3, 5, 7, 9로 총 5개이다.\n\n뽑은 카드에 적힌 수가 모두 홀수가 되려면, 이 5장의 홀수 카드 중에서 3장을 선택해야 한다:\n$$C(5,3) = \\binom{5}{3} = \\frac{5!}{3!2!} = \\frac{5 \\times 4}{2 \\times 1} = \\frac{20}{2} = 10$$\n\n**3단계: 확률 구하기**\n\n구하는 확률은:\n$$P(\\text{모두 홀수}) = \\frac{C(5,3)}{C(9,3)} = \\frac{10}{84} = \\frac{5}{42}$$\n\n**[정답 확인]**\n분자 10과 분모 84의 최대공약수는 2이므로 $\\frac{10}{84} = \\frac{5}{42}$로 기약분수로 정리되며, 이는 선택지 ①과 일치한다.\n\n**[오답 분석]**\n- ② $\\frac{1}{6}$: $\\frac{1}{6} = \\frac{14}{84}$로 분자가 14가 되어야 하는데, 홀수만 뽑는 경우는 10가지이다.\n- ③ $\\frac{5}{21}$: $\\frac{5}{21} = \\frac{20}{84}$로 분자를 2배로 잘못 계산한 경우이다.\n- ④ $\\frac{2}{7}$: $\\frac{2}{7} = \\frac{24}{84}$로 전혀 다른 값이다.\n- ⑤ $\\frac{1}{3}$: $\\frac{1}{3} = \\frac{28}{84}$로 홀수와 짝수가 섞여 뽑히는 경우를 포함한 잘못된 계산이다.\n\n**[핵심 포인트]**\n1~9의 홀수가 정확히 5개임을 파악하는 것이 중요하다. 조합 계산에서 $C(5,3) = 10$, $C(9,3) = 84$를 정확히 구한 후 기약분수로 정리하면 $\\frac{5}{42}$를 얻는다.",
