    "answer": 2,
    "explanation": "**[핵심 개념]**\n확률의 기본 정의는 $P(A) = \\frac{\\text{사건 A가 일어나는 경우의 수}}{\\text{전체 경우의 수}}$이다. 이 문제에서는 조건부 경우의 수를 구하기 위해 먼저 전체 경우의 수와 조건을 만족하는 경우의 수를 각각 계산해야 한다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수 구하기**\n\n1부터 5까지의 카드 5장을 일렬로 나열하는 경우의 수는:\n$$5! = 5 \\times 4 \\times 3 \\times 2 \\times 1 = 120$$\n\n**2단계: 주어진 조건 분석**\n\n1부터 5까지의 자연수 중에서:\n- 홀수: 1, 3, 5 (3개)\n- 짝수: 2, 4 (2개)\n\n양 끝에 놓인 카드의 수가 모두 홀수여야 한다.\n\n**3단계: 조건을 만족하는 경우의 수 구하기**\n\n양 끝 위치를 [왼쪽 끝]_____[오른쪽 끝]으로 표현하면:\n\n- **왼쪽 끝에 올 홀수 선택**: 3개 중 1개 선택 → 3가지\n- **오른쪽 끝에 올 홀수 선택**: 남은 홀수 2개 중 1개 선택 → 2가지\n- **중간 3개 위치에 남은 카드 배열**: 남은 카드 3개를 배열 → $3! = 6$가지\n\n따라서 조건을 만족하는 경우의 수는:\n$$3 \\times 2 \\times 3! = 3 \\times 2 \\times 6 = 36$$\n\n**4단계: 확률 계산**\n\n$$P(\\text{양 끝이 모두 홀수}) = \\frac{36}{120} = \\frac{3}{10}$$\n\n**[정답 확인]**\n전체 120가지 중에서 양 끝 위치에 홀수를 배치하고 나머지를 자유롭게 배열하는 36가지이므로, 확률은 $\\frac{36}{120} = \\frac{3}{10}$이다.\n\n**[오답 분석]**\n\n- ① $\\frac{1}{10}$: 양 끝이 특정 홀수 쌍(예: 1과 3)일 확률을 구한 경우\n- ② $\\frac{3}{20}$: 계산 오류로 분자나 분모를 잘못 계산한 경우\n- ④ $\\frac{2}{5}$: 중간 3개 위치 배열을 고려하지 않은 경우 ($\\frac{6}{15}$)\n- ⑤ $\\frac{1}{2}$: 양 끝에 홀수가 올 단순 확률을 과대 추정한 경우\n\n**[핵심 포인트]**\n조건을 만족하는 경우의 수를 구할 때 **단계적으로 각 위치에 배치되는 경우를 곱셈 법칙으로 계산**하는 것이 중요하다. 양 끝 2개 위치 선택 → 중간 3개 위치 배열 순서로 진행하면 쉽게 풀 수 있다.",
