    "explanation": "**[핵심 개념]**\n\n두 수의 곱이 짝수가 되려면 **최소한 하나 이상의 수가 짝수**여야 한다. 반대로 곱이 홀수가 되려면 **두 수 모두 홀수**여야 한다. 따라서 여집합을 이용하면 계산이 간단해진다: $P(\\text{곱이 짝수}) = 1 - P(\\text{곱이 홀수})$\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n\n5장의 카드 중 2장을 동시에 뽑는 경우의 수:\n$$\\binom{5}{2} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**2단계: 곱이 홀수인 경우의 수**\n\n곱이 홀수가 되려면 **두 수 모두 홀수**여야 한다.\n\n주어진 카드: 1, 2, 3, 4, 5\n- 홀수: 1, 3, 5 (3개)\n- 짝수: 2, 4 (2개)\n\n홀수 카드 중 2장을 뽑는 경우의 수:\n$$\\binom{3}{2} = \\frac{3 \\times 2}{2 \\times 1} = 3$$\n\n(구체적으로: (1,3), (1,5), (3,5))\n\n**3단계: 곱이 짝수인 경우의 수**\n\n여집합을 이용:\n$$\\text{곱이 짝수인 경우} = 10 - 3 = 7$$\n\n**4단계: 확률 계산**\n\n$$P(\\text{곱이 짝수}) = \\frac{7}{10}$$\n\n**[정답 확인]**\n\n여집합을 활용하여 곱이 홀수인 경우(3가지)를 먼저 구하고 전체에서 빼면, 곱이 짝수인 경우는 7가지이므로 확률은 $\\frac{7}{10}$이다.\n\n**[오답 분석]**\n\n- ① $\\frac{3}{10}$: 곱이 홀수일 확률로, 문제에서 요구하는 답의 여집합이다.\n- ② $\\frac{2}{5}$ = $\\frac{4}{10}$: 짝수만 2개라는 잘못된 계산\n- ③ $\\frac{1}{2}$ = $\\frac{5}{10}$: 근거 없는 선택\n- ⑤ $\\frac{4}{5}$ = $\\frac{8}{10}$: 계산 실수로 전체 경우의 수를 잘못 적용\n\n**[핵심 포인트]**\n\n- **여집합 활용**: 곱이 짝수인 경우를 직접 세는 것보다 곱이 홀수인 경우(두 수 모두 홀수)를 먼저 구하는 것이 훨씬 효율적이다.\n- **홀짝성 판정**: 곱이 홀수 ⟺ 모든 인수가 홀수",
