    "explanation": "**[핵심 개념]**\n두 개의 공을 동시에 꺼내는 경우의 수는 조합 $\\binom{5}{2}$로 계산한다. 두 수의 차이 $X$는 큰 수에서 작은 수를 뺀 값이므로, 항상 양수이다. 확률은 구하는 경우의 수를 전체 경우의 수로 나누어 계산한다.\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 계산**\n\n5개의 공 중에서 2개를 동시에 꺼내므로:\n$$\\text{전체 경우의 수} = \\binom{5}{2} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**Step 2: 모든 경우와 $X$ 값 찾기**\n\n2개의 공을 꺼낼 때 (작은 수, 큰 수) 순서로 나열하고 $X = \\text{큰 수} - \\text{작은 수}$를 계산한다:\n\n| 경우 | (1,2) | (1,3) | (1,4) | (1,5) | (2,3) | (2,4) | (2,5) | (3,4) | (3,5) | (4,5) |\n|------|-------|-------|-------|-------|-------|-------|-------|-------|-------|-------|\n| $X$ | 1 | 2 | 3 | 4 | 1 | 2 | 3 | 1 | 2 | 1 |\n\n**Step 3: $X \\geq 3$인 경우 찾기**\n\n표에서 $X \\geq 3$인 경우는:\n- $(1,4)$: $X = 3$ ✓\n- $(1,5)$: $X = 4$ ✓\n- $(2,5)$: $X = 3$ ✓\n\n따라서 $X \\geq 3$인 경우의 수는 **3가지**\n\n**Step 4: 확률 계산**\n\n$$P(X \\geq 3) = \\frac{3}{10}$$\n\n**[정답 확인]**\n$X \\geq 3$을 만족하는 경우가 정확히 3가지이고, 전체 경우의 수가 10가지이므로 확률은 $\\frac{3}{10}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{5} = \\frac{2}{10}$: $X$의 최댓값만 고려하거나 경우의 수를 잘못 센 경우\n- ③ $\\frac{2}{5} = \\frac{4}{10}$: $X = 2$인 경우도 포함해서 센 오류\n- ④ $\\frac{1}{2} = \\frac{5}{10}$: 전체의 절반이라고 임의로 판단한 오류\n- ⑤ $\\frac{3}{5} = \\frac{6}{10}$: $X \\geq 2$인 경우를 센 오류\n\n**[핵심 포인트]**\n조합으로 전체 경우의 수를 구한 후, 조건을 만족하는 경우를 **직접 나열하여 세는 것**이 중요하다. 특히 두 수의 차를 다룰 때는 순서쌍 (작은 수, 큰 수)로 체계적으로 정리하면 실수를 줄일 수 있다.",
