    "problem": "6명의 학생을 3명, 3명의 두 조로 나누는 경우의 수를 구한 후, 이 중에서 특정 2명이 같은 조에 속할 확률을 \\(\\dfrac{a}{b}\\) (기약분수)라 하자. \\(a\\)의 값을 구하시오.",
