    "answer": 1,
    "explanation": "**[핵심 개념]**\n이 문제는 이항분포(Binomial Distribution)를 이용한 확률 계산 문제이다. 독립시행에서 성공 확률이 $p$일 때, $n$번 시행 중 정확히 $r$번 성공할 확률은 다음 공식으로 구한다:\n\n$$P(X=r) = \\binom{n}{r}p^r(1-p)^{n-r}$$\n\n여기서 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$는 조합이다.\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- 불량률(불량품일 확률): $p = \\frac{1}{10}$\n- 정상품일 확률: $1-p = 1-\\frac{1}{10} = \\frac{9}{10}$\n- 검사 제품 개수: $n=3$\n- 구하려는 사건: 불량품이 정확히 1개\n\n**Step 2: 이항분포 공식 적용**\n\n불량품이 정확히 1개일 확률은 $P(X=1)$이다.\n\n$$P(X=1) = \\binom{3}{1} \\left(\\frac{1}{10}\\right)^1 \\left(\\frac{9}{10}\\right)^{3-1}$$\n\n**Step 3: 각 항 계산**\n\n- 조합: $\\binom{3}{1} = \\frac{3!}{1! \\cdot 2!} = 3$\n\n- 불량품 1개일 확률: $\\left(\\frac{1}{10}\\right)^1 = \\frac{1}{10}$\n\n- 정상품 2개일 확률: $\\left(\\frac{9}{10}\\right)^2 = \\frac{81}{100}$\n\n**Step 4: 확률 계산**\n\n$$P(X=1) = 3 \\times \\frac{1}{10} \\times \\frac{81}{100}$$\n\n$$= 3 \\times \\frac{81}{1000}$$\n\n$$= \\frac{243}{1000}$$\n\n**[정답 확인]**\n계산 결과 $\\frac{243}{1000}$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ① $\\frac{189}{1000}$: $3 \\times \\frac{1}{10} \\times \\frac{63}{100}$처럼 $9^2$을 잘못 계산한 경우\n- ③ $\\frac{27}{100} = \\frac{270}{1000}$: 조합을 고려하지 않거나 분모를 잘못 계산한 경우\n- ④ $\\frac{81}{250} = \\frac{324}{1000}$: 조합을 빠뜨리거나 $\\left(\\frac{9}{10}\\right)^2$만 계산한 경우\n- ⑤ $\\frac{3}{10} = \\frac{300}{1000}$: 단순히 불량률과 정상률의 곱으로만 계산한 경우\n\n**[핵심 포인트]**\n1. **조합을 잊지 말기**: 3개 중 어느 1개가 불량품인지는 3가지 경우가 있으므로 $\\binom{3}{1}=3$을 반드시 곱해야 한다.\n2. **이항분포 공식 체계적으로 적용**: 성공 확률, 실패 확률, 조합을 모두 정확히 계산하는 것이 중요하다.",
