    "explanation": "**[핵심 개념]**\n\n이항분포 $B(n, p)$를 따르는 확률변수 $X$의 기댓값과 분산은 - 기댓값: $E(X) = np$\n- 분산: $V(X) = np(1-p)$\n\n이 두 식을 이용하여 $n$과 $p$를 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 조건으로 식 세우기**\n\n$E(X) = 6$이므로:\n$$np = 6 \\cdots (1)$$\n\n$V(X) = 2$이므로:\n$$np(1-p) = 2 \\cdots (2)$$\n\n**2단계: $p$ 구하기**\n\n식 (1)을 식 (2)에 대입한다:\n$$6(1-p) = 2$$\n\n$$6 - 6p = 2$$\n\n$$6p = 4$$\n\n$$p = \\frac{2}{3}$$\n\n**3단계: $n$ 구하기**\n\n식 (1)에 $p = \\frac{2}{3}$을 대입한다:\n$$n \\cdot \\frac{2}{3} = 6$$\n\n$$n = 6 \\times \\frac{3}{2} = 9$$\n\n**4단계: $n + p$ 계산하기**\n\n$$n + p = 9 + \\frac{2}{3} = \\frac{27}{3} + \\frac{2}{3} = \\frac{29}{3}$$\n\n이는 이미 기약분수이므로 $a = 29$, $b = 3$이다.\n\n**[정답 확인]**\n\n$n = 9, p = \\frac{2}{3}$일 때 $E(X) = 9 \\times \\frac{2}{3} = 6$ ✓, $V(X) = 9 \\times \\frac{2}{3} \\times \\frac{1}{3} = 2$ ✓이고, $n + p = \\frac{29}{3}$에서 $a = 29$이다.\n\n**[오답 분석]**\n\n객관식이 아닌 단답형 문제이므로 해당 없음.\n\n**[핵심 포인트]**\n\n이항분포의 기댓값과 분산 공식에서 $E(X) = np$와 $V(X) = np(1-p)$의 비를 이용하면, $\\frac{V(X)}{E(X)} = 1-p$로 빠르게 $p$를 구한다. ($\\frac{2}{6} = 1-p$ → $p = \\frac{2}{3}$)",
