    "explanation": "**[핵심 개념]**\n\n확률의 기본 공식들:\n- 조건부 확률: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$\n- 전확률 공식: $P(B) = P(A \\cap B) + P(A^c \\cap B)$\n- 여사건: $P(A) + P(A^c) = 1$\n\n사건 $B$는 $A$와 $A^c$ 두 가지 경우로 분할되므로, $B$의 확률은 $B$가 $A$와 함께 일어날 확률과 $B$가 $A^c$와 함께 일어날 확률의 합이다.\n\n**[풀이]**\n\n**Step 1: 주어진 정보 정리**\n- $P(A) = \\frac{1}{2}$\n- $P(B|A) = \\frac{2}{5}$\n- $P(A^c \\cap B) = \\frac{1}{5}$\n\n**Step 2: $P(A \\cap B)$ 구하기**\n\n조건부 확률의 정의에서:\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n따라서:\n$$P(A \\cap B) = P(B|A) \\times P(A) = \\frac{2}{5} \\times \\frac{1}{2} = \\frac{2}{10} = \\frac{1}{5}$$\n\n**Step 3: 전확률 공식을 이용하여 $P(B)$ 구하기**\n\n사건 $B$는 $(A \\cap B)$와 $(A^c \\cap B)$로 분할되므로:\n$$P(B) = P(A \\cap B) + P(A^c \\cap B)$$\n\n값을 대입하면:\n$$P(B) = \\frac{1}{5} + \\frac{1}{5} = \\frac{2}{5}$$\n\n**[정답 확인]**\n\n$P(B) = \\frac{2}{5}$이므로 정답은 **③번**이다. 조건부 확률을 이용해 $P(A \\cap B)$를 구한 후 전확률 공식으로 계산하면 정확히 주어진 값들이 일치한다.\n\n**[오답 분석]**\n\n- **①** $\\frac{1}{5}$: $P(A^c \\cap B)$값만 선택한 경우\n- **②** $\\frac{3}{10}$: 계산 과정에서 실수(예: $\\frac{1}{5} + \\frac{1}{10}$로 잘못 계산)\n- **④** $\\frac{9}{20}$: $P(A \\cap B)$를 잘못 계산하거나 더하기 과정에서 오류\n- **⑤** $\\frac{1}{2}$: $P(A)$와 혼동하거나 조건부 확률을 잘못 적용\n\n**[핵심 포인트]**\n\n1. **전확률 공식**: 전체 확률은 여사건으로 분할한 각 경우의 확률의 합이다.\n2. **조건부 확률의 활용**: $P(B|A) = \\frac{P(A \\cap B)}{P(A)}$에서 교집합 확률을 먼저 구한 후 전확률 공식을 적용하는 것이 핵심이다.",
