    "explanation": "**[핵심 개념]**\n\n1. **합사건의 확률**: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n2. **독립사건의 성질**: 두 사건 $A$, $B$가 독립일 때, $P(A \\cap B) = P(A) \\cdot P(B)$\n\n3. **문제의 조건 해석**: \n - 두 사건이 독립 → 교집합의 확률을 곱셈으로 계산\n - 합사건의 확률, 한 사건의 확률이 주어짐 → 다른 사건의 확률 구하기\n\n**[풀이]**\n\n$A$와 $B$가 서로 독립이므로, 다음이 성립한다:\n$$P(A \\cap B) = P(A) \\cdot P(B)$$\n\n합사건의 확률 공식을 적용하면:\n$$P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$$\n\n독립성을 이용하여 교집합의 확률을 대체하면:\n$$P(A \\cup B) = P(A) + P(B) - P(A) \\cdot P(B)$$\n\n주어진 값들을 대입한다:\n$$\\frac{7}{12} = \\frac{1}{3} + P(B) - \\frac{1}{3} \\cdot P(B)$$\n\n양변을 정리하면:\n$$\\frac{7}{12} = \\frac{1}{3} + P(B) \\left(1 - \\frac{1}{3}\\right)$$\n\n$$\\frac{7}{12} = \\frac{1}{3} + P(B) \\cdot \\frac{2}{3}$$\n\n양변에서 $\\frac{1}{3}$을 빼면:\n$$\\frac{7}{12} - \\frac{1}{3} = P(B) \\cdot \\frac{2}{3}$$\n\n$$\\frac{7}{12} - \\frac{4}{12} = P(B) \\cdot \\frac{2}{3}$$\n\n$$\\frac{3}{12} = P(B) \\cdot \\frac{2}{3}$$\n\n$$\\frac{1}{4} = P(B) \\cdot \\frac{2}{3}$$\n\n양변에 $\\frac{3}{2}$를 곱하면:\n$$P(B) = \\frac{1}{4} \\cdot \\frac{3}{2} = \\frac{3}{8}$$\n\n**[정답 확인]**\n\n$P(B) = \\frac{3}{8}$일 때, $P(A \\cup B) = \\frac{1}{3} + \\frac{3}{8} - \\frac{1}{3} \\cdot \\frac{3}{8} = \\frac{8}{24} + \\frac{9}{24} - \\frac{1}{8} = \\frac{17}{24} - \\frac{3}{24} = \\frac{14}{24} = \\frac{7}{12}$ ✓\n\n**[오답 분석]**\n\n- **①** $\\frac{1}{6}$: $P(A \\cup B) = \\frac{1}{3} + \\frac{1}{6} - \\frac{1}{18} = \\frac{5}{9} \\neq \\frac{7}{12}$\n\n- **②** $\\frac{1}{4}$: $P(A \\cup B) = \\frac{1}{3} + \\frac{1}{4} - \\frac{1}{12} = \\frac{1}{2} \\neq \\frac{7}{12}$\n\n- **③** $\\frac{1}{3}$: $P(A \\cup B) = \\frac{1}{3} + \\frac{1}{3} - \\frac{1}{9} = \\frac{5}{9} \\neq \\frac{7}{12}$\n\n- **⑤** $\\frac{5}{12}$: $P(A \\cup B) = \\frac{1}{3} + \\frac{5}{12} - \\frac{5}{36} = \\frac{7}{9} \\neq \\frac{7}{12}$\n\n**[핵심 포인트]**\n\n독립사건에서는 $P(A \\cap B) = P(A) \\cdot P(B)$를 이용하고, 합사건 공식에 대입하여 미지의 확률을 구한다. 독립성 조건을 올바르게 적용하는 것이 이 문제의 핵심이다.",
