    "type": "복합 킬러",
    "problem": "주머니에 1부터 8까지의 자연수가 하나씩 적힌 8개의 공이 들어 있다. 이 주머니에서 임의로 3개의 공을 동시에 꺼낼 때, 꺼낸 공에 적힌 세 수 중 가장 큰 수가 6일 확률을 \\(\\dfrac{p}{56}\\)이라 하자. \\(p\\)의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 10,
    "explanation": "**[핵심 개념]**\n조합을 이용한 확률 문제이다. 전체 경우의 수에서 특정 조건을 만족하는 경우의 수를 구하여 확률을 계산한다. \n- 전체 경우의 수: 8개 중 3개를 선택하는 경우\n- 조건: \"가장 큰 수가 6\" = \"6이 포함되고, 나머지는 1~5에서 선택\"\n\n**[풀이]**\n\n**Step 1: 전체 경우의 수 구하기**\n\n8개의 공 중에서 3개를 동시에 꺼내는 경우의 수는:\n$$\\binom{8}{3} = \\frac{8 \\times 7 \\times 6}{3 \\times 2 \\times 1} = \\frac{336}{6} = 56$$\n\n**Step 2: \"가장 큰 수가 6\"인 경우의 수 구하기**\n\n가장 큰 수가 6이 되려면:\n- 반드시 6이 포함되어야 함\n- 나머지 2개는 6보다 작은 수(1, 2, 3, 4, 5)에서 선택해야 함\n- 7이나 8은 포함되면 안 됨\n\n따라서 1부터 5까지의 수 중에서 2개를 선택하고, 반드시 6을 포함하면 된다.\n\n$$\\binom{5}{2} = \\frac{5 \\times 4}{2 \\times 1} = 10$$\n\n**Step 3: 확률 계산**\n\n구하는 확률은:\n$$P = \\frac{\\text{가장 큰 수가 6인 경우의 수}}{\\text{전체 경우의 수}} = \\frac{10}{56}$$\n\n따라서 $\\dfrac{p}{56} = \\dfrac{10}{56}$이므로 $p = 10$\n\n**[정답 확인]**\n가장 큰 수가 6이 되는 경우는 {6}과 {1~5에서 2개}를 조합하는 것이고, 이는 $\\binom{5}{2} = 10$가지이므로 확률은 $\\frac{10}{56}$이다.\n\n**[오답 분석]**\n객관식이 아니므로 생략\n\n**[핵심 포인트]**\n\"최댓값이 특정 수\"라는 조건은 \"그 수는 반드시 포함되고, 그보다 작은 수에서만 나머지를 선택\"으로 해석하면 된다. 이렇게 번역하면 조합 문제가 단순해진다.",
