    "answer": 2,
    "explanation": "**[핵심 개념]**\n이 문제는 조건부 확률을 묻는 문제이다. \"첫 번째에 꺼낸 공이 흰 공이었을 때\"라는 조건이 주어졌으므로, 이미 일어난 사건을 전제하고 그 다음 확률을 구해야 한다. 조건부 확률의 정의는 :\n\n$$P(B|A) = \\frac{P(A \\cap B)}{P(A)}$$\n\n또는 직관적으로, 조건이 주어진 상황에서의 확률은 \"새로운 전체\"를 기준으로 계산한다.\n\n**[풀이]**\n\n**1단계: 초기 상황 파악**\n- 전체 공: 흰 공 3개, 검은 공 2개 (총 5개)\n\n**2단계: 첫 번째에 흰 공을 꺼낸 후의 상황**\n첫 번째에 흰 공을 꺼냈다는 조건이 주어졌으므로, 이제 주머니에 남은 공은:\n- 흰 공: $3 - 1 = 2$개\n- 검은 공: $2$개 (변화 없음)\n- 남은 공의 총 개수: $4$개\n\n**3단계: 두 번째에 흰 공을 꺼낼 확률 계산**\n첫 번째에 흰 공을 꺼낸 조건 하에서, 두 번째에 흰 공을 꺼낼 확률은:\n\n$$P(\\text{두 번째 흰공} \\mid \\text{첫 번째 흰공}) = \\frac{\\text{남은 흰 공의 개수}}{\\text{남은 공의 총 개수}} = \\frac{2}{4} = \\frac{1}{2}$$\n\n**[정답 확인]**\n첫 번째에 흰 공을 꺼낸 후 남은 4개 공 중 흰 공이 2개이므로, 두 번째에 흰 공을 꺼낼 확률은 $\\frac{2}{4} = \\frac{1}{2}$이다. ✓\n\n**[오답 분석]**\n\n① $\\frac{1}{4}$: 초기 상태에서 두 번째 공이 흰 공일 전체 확률을 잘못 계산한 경우\n② $\\frac{3}{10}$: 조건부 상황을 무시하고 복합 확률을 계산한 경우 ($\\frac{3}{5} \\times \\frac{2}{4}$를 혼동)\n④ $\\frac{3}{5}$: 첫 번째에 흰 공을 꺼낼 확률로, 문제의 조건을 반영하지 않음\n⑤ $\\frac{2}{3}$: 남은 공의 개수를 잘못 계산한 경우\n\n**[핵심 포인트]**\n조건부 확률 문제에서는 \"주어진 조건이 이미 일어났다\"고 가정하고, 그 조건하에서 남은 상황을 새로운 표본공간으로 삼아야 한다. 복원추출이 아닌 비복원추출이므로 첫 번째 결과가 두 번째 상황을 변화시킵니다.",
