    "explanation": "**[핵심 개념]**\n순열과 확률의 결합 문제이다. 전체 경우의 수는 6장 중 3장을 순서를 고려하여 선택하는 순열 $P(6,3)$이고, 구하는 확률은 (조건을 만족하는 경우의 수)/(전체 경우의 수)이다. 세 자리 수가 500 이상이 되려면 백의 자리가 5 또는 6이어야 한다.\n\n**[풀이]**\n\n**1단계: 전체 경우의 수**\n6장 중 3장을 택하여 일렬로 나열하므로:\n$$P(6,3) = 6 \\times 5 \\times 4 = 120$$\n\n**2단계: 500 이상의 조건 분석**\n세 자리 수가 500 이상이 되려면 백의 자리(첫 번째 자리)가 5 이상이어야 한다.\n즉, 백의 자리에는 5 또는 6만 올 수 있다.\n\n**3단계: 조건을 만족하는 경우의 수**\n\n**경우 1: 백의 자리가 5인 경우**\n- 첫 번째 자리: 5 (1가지)\n- 두 번째 자리: 남은 5개 숫자 중 선택 (5가지)\n- 세 번째 자리: 남은 4개 숫자 중 선택 (4가지)\n- 소계: $1 \\times 5 \\times 4 = 20$\n\n**경우 2: 백의 자리가 6인 경우**\n- 첫 번째 자리: 6 (1가지)\n- 두 번째 자리: 남은 5개 숫자 중 선택 (5가지)\n- 세 번째 자리: 남은 4개 숫자 중 선택 (4가지)\n- 소계: $1 \\times 5 \\times 4 = 20$\n\n500 이상인 경우의 수: $20 + 20 = 40$\n\n**4단계: 확률 계산**\n$$P = \\frac{40}{120} = \\frac{1}{3}$$\n\n**[정답 확인]**\n백의 자리가 5 또는 6인 경우만 500 이상이 되며, 각각 20가지씩 총 40가지이므로 확률은 $\\frac{40}{120} = \\frac{1}{3}$이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{6}$: 백의 자리가 6만 되는 경우로 계산한 오류 ($\\frac{20}{120}=\\frac{1}{6}$)\n- ② $\\frac{1}{4}$: 계산 실수로 경우의 수를 잘못 센 경우\n- ③ $\\frac{3}{10}$: 백의 자리 범위를 잘못 설정하거나 계산 오류\n- ⑤ $\\frac{5}{12}$: 전체 경우의 수를 잘못 계산한 경우\n\n**[핵심 포인트]**\n세 자리 수가 500 이상이 되려면 백의 자리가 5 또는 6이어야 한다는 조건을 정확히 파악하는 것이 중요하다. 나머지 두 자리는 남은 숫자 중에서 자유롭게 순서를 정하면 된다.",
