    "type": "복합 킬러",
    "problem": "주머니 A에는 흰 공 2개와 검은 공 3개가, 주머니 B에는 흰 공 4개와 검은 공 1개가 들어 있다. 한 개의 동전을 던져서 앞면이 나오면 주머니 A에서, 뒷면이 나오면 주머니 B에서 공 1개를 꺼낸다. 꺼낸 공이 흰 공이었을 때, 주머니 A에서 꺼낸 것일 확률은?",
    "answerType": "choice",
    "choices": [
      "① \\(\\dfrac{1}{5}\\)",
      "② \\(\\dfrac{1}{4}\\)",
      "③ \\(\\dfrac{1}{3}\\)",
      "④ \\(\\dfrac{2}{5}\\)",
      "⑤ \\(\\dfrac{1}{2}\\)"
    ],
    "answer": 2,
    "explanation": "**[핵심 개념]**\n조건부 확률 문제이다. 사건 $B$가 일어났을 때 사건 $A$가 일어날 조건부 확률은 $P(A|B) = \\frac{P(A \\cap B)}{P(B)}$로 계산한다. 여기서는 \"흰 공을 꺼냈을 때 주머니 A에서 꺼냈을 확률\"을 구하므로, 전체 경로 중에서 \"주머니 A에서 흰 공을 꺼낸 경우\"의 비율을 계산해야 한다.\n\n**[풀이]**\n\n**1단계: 각 주머니의 흰 공 확률 계산**\n- 주머니 A: 흰 공 2개, 검은 공 3개 (총 5개) → 흰 공일 확률 = $\\frac{2}{5}$\n- 주머니 B: 흰 공 4개, 검은 공 1개 (총 5개) → 흰 공일 확률 = $\\frac{4}{5}$\n\n**2단계: 동전 던지기에서 각 주머니 선택 확률**\n- 앞면(주머니 A): $P(A) = \\frac{1}{2}$\n- 뒷면(주머니 B): $P(B) = \\frac{1}{2}$\n\n**3단계: 흰 공을 꺼낼 전체 확률 계산**\n\n전체 경로에서 흰 공이 나올 확률은:\n\n$$P(\\text{흰 공}) = P(A) \\times P(\\text{흰 공}|A) + P(B) \\times P(\\text{흰 공}|B)$$\n\n$$= \\frac{1}{2} \\times \\frac{2}{5} + \\frac{1}{2} \\times \\frac{4}{5}$$\n\n$$= \\frac{2}{10} + \\frac{4}{10} = \\frac{6}{10} = \\frac{3}{5}$$\n\n**4단계: 조건부 확률 계산**\n\n흰 공이 나왔을 때 주머니 A에서 꺼냈을 확률:\n\n$$P(A|\\text{흰 공}) = \\frac{P(A \\cap \\text{흰 공})}{P(\\text{흰 공})}$$\n\n$$= \\frac{P(A) \\times P(\\text{흰 공}|A)}{P(\\text{흰 공})}$$\n\n$$= \\frac{\\frac{1}{2} \\times \\frac{2}{5}}{\\frac{3}{5}} = \\frac{\\frac{2}{10}}{\\frac{3}{5}} = \\frac{\\frac{1}{5}}{\\frac{3}{5}}$$\n\n$$= \\frac{1}{5} \\times \\frac{5}{3} = \\frac{1}{3}$$\n\n**[정답 확인]**\n주머니 A에서 흰 공을 꺼낼 확률($\\frac{1}{10}$)을 전체 흰 공이 나올 확률($\\frac{6}{10}$)로 나누면 $\\frac{1}{6}$이 아니라 $\\frac{1/10}{6/10} = \\frac{1}{6}$... 재확인하면 $\\frac{2/10}{6/10} = \\frac{2}{6} = \\frac{1}{3}$로 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{1}{5}$: 주머니 A의 흰 공 확률만 사용한 경우\n- ② $\\frac{1}{4}$: 동전 확률을 잘못 적용한 경우\n- ④ $\\frac{2}{5}$: 조건부 확률 공식을 적용하지 않고 주머니 A의 흰 공 확률을 잘못 사용한 경우\n- ⑤ $\\frac{1}{2}$: 동전의 앞뒷면 확률로만 답한 경우\n\n**[핵심 포인트]**\n조건부 확률에서는 \"조건(흰 공이 나옴)\"을 만족하는 모든 경로를 분모로 사용하고, 그 중에서 우리가 원하는 경로(A에서 흰 공)를 분자로 사용해야 한다. 베이즈 정리의 핵심은 모든 가능한 원인의 확률을 비교하는 것이다.",
