    "type": "복합 킬러",
    "problem": "집합 \\(X = \\{1, 2, 3, 4, 5, 6\\}\\)에서 \\(X\\)로의 함수 \\(f\\) 중에서 임의로 하나를 택한다. \\(f(1) \\leq f(2) \\leq f(3)\\)이고 \\(f(1) \\times f(2) \\times f(3)\\)이 짝수일 확률을 \\(\\dfrac{q}{p}\\) (기약분수)라 하자. \\(p + q\\)의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 131,
    "explanation": "**[핵심 개념]**\n\n이 문제는 조건부 확률 개념을 활용하는 문제이다. 전체 함수의 개수에서 주어진 조건을 만족하는 함수의 개수를 구해야 한다.\n\n- 함수 $f: X \\to X$의 총 개수는 $6^6$\n- 조건: $f(1) \\leq f(2) \\leq f(3)$이고 $f(1) \\times f(2) \\times f(3)$이 짝수\n- 곱이 짝수 ⟺ 적어도 하나는 짝수\n\n**[풀이]**\n\n**1단계: 전체 상황 파악**\n\n$f: X \\to X$에서 $f(4), f(5), f(6)$은 조건이 없으므로 각각 6가지씩 선택 가능한다.\n따라서 이들에 대한 경우의 수는 $6^3$이다.\n\n전체 함수의 개수에서 $f(1), f(2), f(3)$의 역할만 분석하면 된다.\n\n**2단계: $f(1) \\leq f(2) \\leq f(3)$을 만족하는 경우의 수**\n\n$1 \\leq f(1) \\leq f(2) \\leq f(3) \\leq 6$을 만족하는 순서쌍의 개수는 중복조합이다.\n\n$$H(6,3) = \\binom{6+3-1}{3} = \\binom{8}{3} = 56$$\n\n따라서 조건 $f(1) \\leq f(2) \\leq f(3)$을 만족하는 경우: $56 \\times 6^3$\n\n**3단계: $f(1) \\times f(2) \\times f(3)$이 짝수인 경우**\n\n여사건을 이용한다: 곱이 홀수 ⟺ 세 개 모두 홀수\n\n$X$에서 홀수: $\\{1, 3, 5\\}$ (3개)\n$X$에서 짝수: $\\{2, 4, 6\\}$ (3개)\n\n$f(1) \\leq f(2) \\leq f(3)$이고 세 개 모두 홀수인 경우:\n$$H(3,3) = \\binom{3+3-1}{3} = \\binom{5}{3} = 10$$\n\n$f(1) \\leq f(2) \\leq f(3)$이고 곱이 홀수인 경우: $10 \\times 6^3$\n\n**4단계: 구하는 확률 계산**\n\n$f(1) \\leq f(2) \\leq f(3)$이고 곱이 짝수인 경우:\n$$(56 - 10) \\times 6^3 = 46 \\times 6^3$$\n\n구하는 확률:\n$$P = \\frac{46 \\times 6^3}{6^6} = \\frac{46}{6^3} = \\frac{46}{216}$$\n\n**5단계: 기약분수로 만들기**\n\n$$\\gcd(46, 216)을\\ 구한다$$\n\n$46 = 2 \\times 23$\n$216 = 2^3 \\times 3^3$\n\n$$\\gcd(46, 216) = 2$$\n\n$$\\frac{46}{216} = \\frac{23}{108}$$\n\n따라서 $q = 23, p = 108$\n\n$$p + q = 108 + 23 = 131$$\n\n**[정답 확인]**\n\n$\\frac{23}{108}$은 기약분수이고($\\gcd(23, 108) = 1$), $p + q = 131$로 정답과 일치한다.\n\n**[오답 분석]**\n\n- 여사건을 사용하지 않고 직접 계산: 경우의 수를 놓치기 쉬움\n- 중복조합 공식을 잘못 적용: $\\binom{n+r-1}{r}$ 형태를 명확히 해야 함\n- 기약분수 변환 과정에서 최대공약수를 잘못 구함\n\n**[핵심 포인트]**\n\n1. **여사건 활용**: 곱이 짝수 조건은 \"모두 홀수\"의 여사건으로 계산하면 간결\n2. **중복조합**: $f(1) \\leq f(2) \\leq f(3)$는 중복조합 $H(6,3)$로 직접 계산",
