    "type": "조건부 확률",
    "problem": "두 사건 \\(A\\), \\(B\\)에 대하여 \\(P(A) = \\dfrac{1}{2}\\), \\(P(A \\cap B) = \\dfrac{1}{6}\\)일 때, \\(P(B|A)\\)의 값은?",
