    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n이 문제는 **조건부 확률** 문제이다. 특정 사건이 일어났을 때 다른 사건이 일어날 확률을 구하는 문제로, 베이즈 정리(Bayes' theorem)를 사용한다.\n\n구하려는 확률: $P(\\text{남학생}|\\text{안경}) = \\frac{P(\\text{남학생 AND 안경})}{P(\\text{안경})}$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 남학생의 비율: $P(\\text{남}) = 0.6$\n- 여학생의 비율: $P(\\text{여}) = 0.4$\n- 남학생 중 안경 비율: $P(\\text{안경}|\\text{남}) = 0.3$\n- 여학생 중 안경 비율: $P(\\text{안경}|\\text{여}) = 0.2$\n\n**2단계: 남학생이면서 안경을 쓴 학생의 확률**\n\n$$P(\\text{남 AND 안경}) = P(\\text{남}) \\times P(\\text{안경}|\\text{남}) = 0.6 \\times 0.3 = 0.18$$\n\n**3단계: 여학생이면서 안경을 쓴 학생의 확률**\n\n$$P(\\text{여 AND 안경}) = P(\\text{여}) \\times P(\\text{안경}|\\text{여}) = 0.4 \\times 0.2 = 0.08$$\n\n**4단계: 전체 안경을 쓴 학생의 확률 (전확률 공식)**\n\n$$P(\\text{안경}) = P(\\text{남 AND 안경}) + P(\\text{여 AND 안경})$$\n$$P(\\text{안경}) = 0.18 + 0.08 = 0.26$$\n\n**5단계: 조건부 확률 계산**\n\n$$P(\\text{남}|\\text{안경}) = \\frac{P(\\text{남 AND 안경})}{P(\\text{안경})} = \\frac{0.18}{0.26} = \\frac{18}{26} = \\frac{9}{13}$$\n\n**[정답 확인]**\n\n안경을 쓴 학생 중에서 남학생의 비율은 $\\frac{9}{13}$이므로 정답은 **②번**이다.\n\n**[오답 분석]**\n\n- **① $\\frac{4}{13}$**: $\\frac{0.08}{0.26}$로 여학생일 확률을 잘못 계산한 경우\n- **③ $\\frac{3}{5}$**: $\\frac{0.18}{0.3}$로 남학생 중 안경 비율과 혼동한 경우\n- **④ $\\frac{9}{26}$**: 분모를 $P(\\text{안경})$으로 나누지 않고 단순히 $P(\\text{남 AND 안경})$만 구한 경우\n- **⑤ $\\frac{3}{4}$**: 계산 과정에서 소수점 처리를 잘못한 경우\n\n**[핵심 포인트]**\n\n**\"이미 일어난 사건(안경을 씀)을 조건으로 주어질 때는, 그 조건에 해당하는 전체 경우의 수를 분모로 사용해야 한다\"** - 조건부 확률의 핵심은 분모를 전체가 아닌 조건을 만족하는 경우로 제한하는 것이다.",
