    "problem": "두 사건 \\(A\\), \\(B\\)에 대하여 \\(P(A|B) = \\dfrac{1}{3}\\), \\(P(B|A) = \\dfrac{2}{5}\\), \\(P(A \\cup B) = \\dfrac{3}{4}\\)일 때, \\(P(A)\\)의 값은?",
