    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n조건부 확률과 합집합의 확률 공식:\n- 조건부 확률: $P(A|B) = \\dfrac{P(A \\cap B)}{P(B)}$, $P(B|A) = \\dfrac{P(A \\cap B)}{P(A)}$\n- 합집합의 확률: $P(A \\cup B) = P(A) + P(B) - P(A \\cap B)$\n\n이 세 식을 연립하여 $P(A)$를 구한다.\n\n**[풀이]**\n\n**Step 1: 조건부 확률 식을 이용하여 관계식 세우기**\n\n$P(A|B) = \\dfrac{1}{3}$에서:\n$$P(A \\cap B) = \\dfrac{1}{3} P(B) \\cdots (1)$$\n\n$P(B|A) = \\dfrac{2}{5}$에서:\n$$P(A \\cap B) = \\dfrac{2}{5} P(A) \\cdots (2)$$\n\n**Step 2: 식 (1)과 (2)를 이용하여 $P(B)$를 $P(A)$로 표현**\n\n(1)과 (2)에서:\n$$\\dfrac{1}{3} P(B) = \\dfrac{2}{5} P(A)$$\n\n$$P(B) = \\dfrac{6}{5} P(A) \\cdots (3)$$\n\n**Step 3: 합집합 공식에 대입**\n\n$P(A \\cup B) = P(A) + P(B) - P(A \\cap B) = \\dfrac{3}{4}$\n\n(2)와 (3)을 대입:\n$$P(A) + \\dfrac{6}{5} P(A) - \\dfrac{2}{5} P(A) = \\dfrac{3}{4}$$\n\n$$P(A) + \\dfrac{4}{5} P(A) = \\dfrac{3}{4}$$\n\n$$\\dfrac{9}{5} P(A) = \\dfrac{3}{4}$$\n\n$$P(A) = \\dfrac{3}{4} \\times \\dfrac{5}{9} = \\dfrac{15}{36} = \\dfrac{5}{12}$$\n\n**[정답 확인]**\n\n$P(A) = \\dfrac{5}{12}$일 때, $P(B) = \\dfrac{6}{5} \\times \\dfrac{5}{12} = \\dfrac{1}{2}$, $P(A \\cap B) = \\dfrac{2}{5} \\times \\dfrac{5}{12} = \\dfrac{1}{6}$이고,\n$P(A \\cup B) = \\dfrac{5}{12} + \\dfrac{1}{2} - \\dfrac{1}{6} = \\dfrac{5}{12} + \\dfrac{6}{12} - \\dfrac{2}{12} = \\dfrac{9}{12} = \\dfrac{3}{4}$ ✓\n\n**[오답 분석]**\n\n- ①, ②, ③, ⑤: 계산 과정에서 조건부 확률 관계식을 잘못 연립하거나, 합집합 공식에 대입할 때 실수하면 나타나는 오답이다. 특히 $P(B)$를 $P(A)$로 표현하는 단계를 생략하면 오답에 도달한다.\n\n**[핵심 포인트]**\n\n조건부 확률의 두 식으로부터 교집합 확률을 같게 놓아서 두 확률 사이의 관계식을 도출하는 것이 핵심이다. 이를 통해 미지수를 하나로 줄인 후 합집합 공식에 대입하면 효과적으로 문제를 풀 수 있다.",
