    "_type": "cond_prob",
    "type": "조건부 확률",
    "problem": "어느 공장의 생산 라인 A, B에서 전체 제품의 70%, 30%를 생산하며, 각 라인의 불량률은 2%, 5%이다. 생산된 제품 중 임의로 하나를 택했을 때 불량이었다. 이 불량품이 라인 A에서 생산되었을 확률을 \\(\\dfrac{p}{29}\\)라 하자. \\(p\\)의 값을 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 14,
    "explanation": "**[핵심 개념]**\n이 문제는 **베이즈 정리(Bayes' Theorem)**를 이용한 조건부 확률 문제이다.\n\n베이즈 정리: 사건 B가 일어났을 때 사건 A가 일어날 조건부 확률은\n$$P(A|B) = \\frac{P(B|A) \\cdot P(A)}{P(B)}$$\n\n여기서 $P(B)$는 전체 확률의 법칙으로 구한다:\n$$P(B) = P(B|A) \\cdot P(A) + P(B|A^c) \\cdot P(A^c)$$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 라인 A에서의 생산 비율: $P(A) = 0.7 = \\frac{7}{10}$\n- 라인 B에서의 생산 비율: $P(B) = 0.3 = \\frac{3}{10}$\n- 라인 A의 불량률: $P(\\text{불량}|A) = 0.02 = \\frac{2}{100} = \\frac{1}{50}$\n- 라인 B의 불량률: $P(\\text{불량}|B) = 0.05 = \\frac{5}{100} = \\frac{1}{20}$\n\n**2단계: 전체 불량품의 확률 계산**\n\n전체 확률의 법칙을 사용하면:\n$$P(\\text{불량}) = P(\\text{불량}|A) \\cdot P(A) + P(\\text{불량}|B) \\cdot P(B)$$\n\n$$P(\\text{불량}) = \\frac{1}{50} \\times \\frac{7}{10} + \\frac{1}{20} \\times \\frac{3}{10}$$\n\n$$= \\frac{7}{500} + \\frac{3}{200}$$\n\n분모를 500으로 통일하면:\n$$= \\frac{7}{500} + \\frac{7.5}{500} = \\frac{7}{500} + \\frac{15}{1000} = \\frac{7}{500} + \\frac{3}{200}$$\n\n다시 계산하면 ($\\frac{3}{200} = \\frac{7.5}{500}$이 아니라 $\\frac{3}{200} = \\frac{15}{1000} = \\frac{7.5}{500}$):\n\n$$= \\frac{7}{500} + \\frac{15}{1000}$$\n\n최소공배수 1000으로 통일:\n$$= \\frac{14}{1000} + \\frac{15}{1000} = \\frac{29}{1000}$$\n\n**3단계: 베이즈 정리 적용**\n\n불량품이 라인 A에서 생산되었을 확률:\n$$P(A|\\text{불량}) = \\frac{P(\\text{불량}|A) \\cdot P(A)}{P(\\text{불량})}$$\n\n$$= \\frac{\\frac{1}{50} \\times \\frac{7}{10}}{\\frac{29}{1000}}$$\n\n$$= \\frac{\\frac{7}{500}}{\\frac{29}{1000}}$$\n\n$$= \\frac{7}{500} \\times \\frac{1000}{29}$$\n\n$$= \\frac{7000}{500 \\times 29} = \\frac{14}{29}$$\n\n**4단계: p 값 구하기**\n\n문제에서 확률을 $\\frac{p}{29}$로 나타내므로:\n$$\\frac{p}{29} = \\frac{14}{29}$$\n\n따라서 $p = 14$\n\n**[정답 확인]**\n베이즈 정리를 올바르게 적용하여 전체 불량품 중 라인 A에서 생산된 불량품의 비율을 $\\frac{14}{29}$로 계산했으므로, $p = 14$가 정답이다.\n\n**[오답 분석]**\n객관식이 아니므로 해당 사항 없음\n\n**[핵심 포인트]**\n- **베이즈 정리**: 결과(불량)가 주어졌을 때 원인(라인 A)의 확률을 구할 때 사용\n- **전체 확률의 법칙**: 분모가 되는 $P(\\text{불량})$을 각 경로별로 계산한 후 합하는 것이 핵심",
