    "explanation": "**[핵심 개념]**\n조합(Combination)은 순서를 고려하지 않고 n개 중에서 r개를 선택하는 경우의 수이다. \n조합의 공식: $C(n,r) = \\binom{n}{r} = \\frac{n!}{r!(n-r)!}$\n\n이 문제는 남학생과 여학생을 각각 독립적으로 선택하는 상황이므로, 곱의 법칙을 적용한다.\n\n**[풀이]**\n\n**1단계: 남학생 2명을 5명 중에서 선택**\n$$C(5,2) = \\binom{5}{2} = \\frac{5!}{2!(5-2)!} = \\frac{5!}{2! \\cdot 3!} = \\frac{5 \\times 4}{2 \\times 1} = \\frac{20}{2} = 10$$\n\n**2단계: 여학생 2명을 4명 중에서 선택**\n$$C(4,2) = \\binom{4}{2} = \\frac{4!}{2!(4-2)!} = \\frac{4!}{2! \\cdot 2!} = \\frac{4 \\times 3}{2 \\times 1} = \\frac{12}{2} = 6$$\n\n**3단계: 곱의 법칙 적용**\n남학생 2명을 선택하는 경우의 수와 여학생 2명을 선택하는 경우의 수는 독립적이므로, 두 경우의 수를 곱한다.\n\n$$\\text{전체 경우의 수} = C(5,2) \\times C(4,2) = 10 \\times 6 = 60$$\n\n**[정답 확인]**\n남학생 2명(10가지) × 여학생 2명(6가지) = 60가지이므로 정답이 맞다.\n\n**[오답 분석]**\n선택지가 제공되지 않았으므로, 흔한 오류는:\n- 50: 남학생 선택을 잘못 계산한 경우\n- 30: 여학생을 3명 선택한 것으로 잘못 이해한 경우\n- 80: 순열을 사용하거나 계산 실수가 있는 경우\n\n**[핵심 포인트]**\n- **서로 다른 그룹에서 선택할 때는 각각 조합으로 계산한 후 곱하기**\n- 남학생/여학생 선택은 독립 사건이므로 곱의 법칙(×) 적용",
