    "explanation": "**[핵심 개념]**\n조합 문제에서 주어진 조건을 만족하는 경우를 체계적으로 나누어 계산해야 한다. 이 문제는 \"과일 2개 이상\"이라는 조건이 있으므로, 과일의 개수에 따라 경우를 나누어 계산한다. 조합의 기본 공식은 $\\binom{n}{r} = \\frac{n!}{r!(n-r)!}$이다.\n\n**[풀이]**\n\n총 4개를 선택하되, 과일은 최소 2개 이상이어야 한다.\n- 과일: 5개 중에서 선택\n- 과자: 4개 중에서 선택\n\n**경우 1: 과일 2개, 과자 2개 선택**\n$$\\binom{5}{2} \\times \\binom{4}{2} = \\frac{5!}{2!3!} \\times \\frac{4!}{2!2!} = 10 \\times 6 = 60$$\n\n**경우 2: 과일 3개, 과자 1개 선택**\n$$\\binom{5}{3} \\times \\binom{4}{1} = \\frac{5!}{3!2!} \\times \\frac{4!}{1!3!} = 10 \\times 4 = 40$$\n\n**경우 3: 과일 4개, 과자 0개 선택**\n$$\\binom{5}{4} \\times \\binom{4}{0} = \\frac{5!}{4!1!} \\times \\frac{4!}{0!4!} = 5 \\times 1 = 5$$\n\n**전체 경우의 수**\n$$60 + 40 + 5 = 105$$\n\n**[정답 확인]**\n과일 2개 이상이라는 조건에서 가능한 모든 경우(과일 2개, 3개, 4개)를 더하면 105가 된다.\n\n**[오답 분석]**\n선택지가 없으므로 일반적인 오류를 설명한다:\n- **과일 2개 이상 조건을 무시**: 과일 1개인 경우까지 포함하면 $\\binom{5}{1}\\times\\binom{4}{3} = 20$이 추가되어 125가 된다.\n- **과일 2개, 과자 2개 경우만 계산**: 60만 구하는 경우 불완전한다.\n- **중복 계산**: 경우를 나눌 때 중복되는 부분을 포함시키면 오답이 된다.\n\n**[핵심 포인트]**\n조건이 있는 선택 문제는 **조건을 만족하는 경우를 모두 나누어 계산**한 후 더하는 것이 중요하다. 특히 \"이상/이하\"라는 표현에서 경계값을 정확히 파악해야 한다.",
