    "problem": "확률변수 \\(X\\)의 확률분포표가 다음과 같을 때, \\(E(2X + 4)\\)의 값을 구하시오.\n\n| \\(X\\) | 1 | 2 | 3 | 4 | 합계 |\n|---|---|---|---|---|---|\n| \\(P(X=x)\\) | \\(\\dfrac{1}{4}\\) | \\(a\\) | \\(\\dfrac{1}{4}\\) | \\(\\dfrac{1}{4}\\) | 1 |",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[핵심 개념]**\n\n확률변수의 기댓값(평균)은 각 값에 확률을 곱하여 모두 더한 것이다. \n- 기댓값의 정의: $E(X) = \\sum x_i \\cdot P(X=x_i)$\n- 기댓값의 성질: $E(aX + b) = aE(X) + b$ (선형성)\n- 확률의 합: $\\sum P(X=x) = 1$\n\n**[풀이]**\n\n**1단계: 미지수 $a$ 구하기**\n\n확률분포표에서 모든 확률의 합은 1이므로:\n\n$$\\frac{1}{4} + a + \\frac{1}{4} + \\frac{1}{4} = 1$$\n\n$$\\frac{3}{4} + a = 1$$\n\n$$a = \\frac{1}{4}$$\n\n**2단계: $E(X)$ 구하기**\n\n$$E(X) = 1 \\cdot \\frac{1}{4} + 2 \\cdot \\frac{1}{4} + 3 \\cdot \\frac{1}{4} + 4 \\cdot \\frac{1}{4}$$\n\n$$E(X) = \\frac{1}{4}(1 + 2 + 3 + 4) = \\frac{1}{4} \\cdot 10 = \\frac{10}{4} = \\frac{5}{2}$$\n\n**3단계: $E(2X + 4)$ 구하기**\n\n기댓값의 선형성을 이용하면:\n\n$$E(2X + 4) = 2E(X) + 4$$\n\n$$E(2X + 4) = 2 \\cdot \\frac{5}{2} + 4 = 5 + 4 = 9$$\n\n**[정답 확인]**\n\n확률의 합 조건으로부터 $a = \\frac{1}{4}$를 구하고, 기댓값의 선형성을 이용하여 $E(2X+4) = 2E(X) + 4 = 9$를 얻었으므로 정답이다.\n\n**[오답 분석]**\n\n- **7**: $E(X) = \\frac{5}{2}$를 구한 후 선형성을 적용하지 않고 잘못 계산한 경우\n- **8**: $E(2X) = 5$만 구하고 상수항 4를 더하지 않은 경우\n- **10**: $a$의 값을 잘못 구했거나 기댓값 계산 과정에서 실수한 경우\n\n**[핵심 포인트]**\n\n1. 확률의 합 = 1 조건을 먼저 활용하여 미지수를 구하기\n2. $E(aX + b) = aE(X) + b$ 공식을 정확히 적용하기 (상수항도 빠뜨리지 않기)",
