    "problem": "확률변수 \\(X\\)가 정규분포 \\(N(50, 5^2)\\)를 따를 때, \\(P(45 \\leq X \\leq 60)\\)의 값을 표준정규분포표를 이용하여 구하시오. (단, \\(P(0 \\leq Z \\leq 1) = 0.3413\\), \\(P(0 \\leq Z \\leq 2) = 0.4772\\))",
