    "explanation": "**[핵심 개념]**\n\n정규분포 $N(\\mu, \\sigma^2)$를 따르는 확률변수 $X$를 표준정규분포로 변환하기 위해서는 **표준화(정규화)** 과정이 필요하다.\n\n표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$\n\n표준화된 $Z$는 표준정규분포 $N(0, 1)$을 따르며, 표준정규분포표를 이용하여 확률을 구한다.\n\n표준정규분포의 대칭성: $P(-a \\leq Z \\leq 0) = P(0 \\leq Z \\leq a)$\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- $X \\sim N(50, 5^2)$ (평균 $\\mu = 50$, 표준편차 $\\sigma = 5$)\n- 구하는 값: $P(45 \\leq X \\leq 60)$\n- 주어진 표: $P(0 \\leq Z \\leq 1) = 0.3413$, $P(0 \\leq Z \\leq 2) = 0.4772$\n\n**2단계: 경계값을 표준화**\n\n$X = 45$일 때:\n$$Z_1 = \\frac{45 - 50}{5} = \\frac{-5}{5} = -1$$\n\n$X = 60$일 때:\n$$Z_2 = \\frac{60 - 50}{5} = \\frac{10}{5} = 2$$\n\n**3단계: 표준화된 확률 계산**\n\n$$P(45 \\leq X \\leq 60) = P(-1 \\leq Z \\leq 2)$$\n\n표준정규분포의 대칭성을 이용하여:\n$$P(-1 \\leq Z \\leq 2) = P(-1 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 2)$$\n\n$$= P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 2)$$\n\n$$= 0.3413 + 0.4772 = 0.8185$$\n\n**[정답 확인]**\n\n표준화 후 $P(-1 \\leq Z \\leq 2)$를 표준정규분포의 대칭성을 이용하여 $P(0 \\leq Z \\leq 1) + P(0 \\leq Z \\leq 2)$로 올바르게 변환하고 주어진 표값을 더하면 정답 ③ 0.8185를 얻는다.\n\n**[오답 분석]**\n\n① **0.6826** : $P(-1 \\leq Z \\leq 1) = 2 \\times 0.3413 = 0.6826$으로, 우측 경계를 2가 아닌 1로 잘못 계산한 경우\n\n② **0.7745** : $0.3413 + 0.4332 = 0.7745$로, 계산 실수 또는 표값을 잘못 사용한 경우\n\n④ **0.8413** : $P(0 \\leq Z \\leq 2) + 0.0641$ 등으로, 절반만 계산하거나 부분적으로만 더한 경우\n\n⑤ **0.9544** : $P(-2 \\leq Z \\leq 2) = 2 \\times 0.4772 = 0.9544$로, 좌측 경계를 -1이 아닌 -2로 계산한 경우\n\n**[핵심 포인트]**\n\n1. **표준화**: $Z = \\frac{X - \\mu}{\\sigma}$로 변환하여 표준정규분포표 사용 가능\n2. **대칭성 활용**: $P(-a \\leq Z \\leq b) = P(-a \\leq Z \\leq 0) + P(0 \\leq Z \\leq b) = P(0 \\leq Z \\leq a) + P(0 \\leq Z \\leq b)$로 음수 구간도 표로 계산 가능",
