    "explanation": "**[핵심 개념]**\n\n정규분포 문제를 풀기 위해서는 표준정규분포로의 변환(표준화)이 필수이다. \n- 표준화 공식: $Z = \\frac{X - \\mu}{\\sigma}$\n- 여기서 $X$는 확률변수, $\\mu$는 평균, $\\sigma$는 표준편차\n- 정규분포는 평균을 중심으로 대칭인 성질을 이용하여 확률을 구한다.\n\n**[풀이]**\n\n**1단계: 주어진 정보 정리**\n- 평균: $\\mu = 200$g\n- 표준편차: $\\sigma = 10$g\n- 구하는 구간: $185 \\leq X \\leq 215$\n- 주어진 정보: $P(0 \\leq Z \\leq 1.5) = 0.4332$\n\n**2단계: 양 끝점을 표준화**\n\n하한선을 표준화:\n$$Z_1 = \\frac{185 - 200}{10} = \\frac{-15}{10} = -1.5$$\n\n상한선을 표준화:\n$$Z_2 = \\frac{215 - 200}{10} = \\frac{15}{10} = 1.5$$\n\n따라서 구하는 확률은 $P(-1.5 \\leq Z \\leq 1.5)$이다.\n\n**3단계: 대칭성을 이용하여 확률 계산**\n\n표준정규분포는 $Z = 0$을 중심으로 대칭이므로:\n$$P(-1.5 \\leq Z \\leq 1.5) = P(-1.5 \\leq Z \\leq 0) + P(0 \\leq Z \\leq 1.5)$$\n\n대칭성에 의해 $P(-1.5 \\leq Z \\leq 0) = P(0 \\leq Z \\leq 1.5) = 0.4332$\n\n따라서:\n$$P(-1.5 \\leq Z \\leq 1.5) = 0.4332 + 0.4332 = 0.8664$$\n\n**[정답 확인]**\n\n표준화하여 구간을 $[-1.5, 1.5]$로 변환 후, 정규분포의 대칭성을 이용해 주어진 확률값을 두 배하면 정확히 0.8664가 된다.\n\n**[오답 분석]**\n\n① 0.7745: $P(0 \\leq Z \\leq 1.2)$ 정도의 값으로, 표준화를 잘못했을 때 나오는 결과\n② 0.8185: 한쪽 구간만 계산하거나 중간 계산 오류로 인한 값\n④ 0.9332: $0.4332 \\times 2 + \\alpha$ 형태로 추가 계산을 잘못한 경우\n⑤ 0.9544: $P(0 \\leq Z \\leq 2) = 0.4772$일 때 나오는 값으로, 표준편차 범위를 잘못 인식한 경우\n\n**[핵심 포인트]**\n\n- 정규분포 문제는 반드시 표준화($Z = \\frac{X-\\mu}{\\sigma}$)를 통해 표준정규분포로 변환해야 한다.\n- 표준정규분포의 **대칭성**을 이용하면 $P(-a \\leq Z \\leq a) = 2 \\times P(0 \\leq Z \\leq a)$로 쉽게 계산할 수 있다.",
